INSERT INTO `travel_review` VALUES (14, 'TR000014', '华严寺砖塔', '朔州', '山西', '周末短途', '冬季', 9, 4, 1489.00, '否', 3, '9月去的华严寺砖塔，情侣出行。地点在朔州，打车比较省心，现场游客较多。这次玩了4天，人均花费约1489元，氛围感不错。景点印象：华严寺砖塔位于怀仁县何家堡乡悟道村西2．5公里的清凉山。山分为南北两峰，南峰海拔1467米，北峰海拔1500米。二峰之间山凹盆地上有华严寺遗址。考之残垣断壁和部分残存筒板瓦等，当系辽代始创，清代重建。寺院座北朝南，全部范围原有正殿、乐楼、东…整体感受是还可以，避开高峰更好。二刷意愿：否。', '0%', 26);
