INSERT INTO `travel_review` VALUES (38, 'TR000038', '乔家大院', '晋中', '山西', '文化打卡', '夏季', 4, 2, 382.00, '是', 5, '4月去的乔家大院，和家人出行。地点在晋中，地铁到达方便，现场游客较多。这次玩了2天，人均花费约382元，历史文化气息浓。景点印象：《乔家大院》、《大红灯笼高高挂》等多部影视作品的取景地，砖雕、彩绘、牌匾是最大看点。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '28%', 77);
