INSERT INTO `travel_review` VALUES (78, 'TR000078', '五龙潭公园', '济南', '山东', '周末短途', '冬季', 9, 1, 634.00, '否', 3, '9月去的五龙潭公园，和朋友出行。地点在济南，自驾停车需要提前规划，现场人流量适中。这次玩了1天，人均花费约634元，历史文化气息浓。景点印象：观赏五龙潭、古温泉、贤清泉，游览游览秦琼故宅等景点。 济南四大名泉之一，四月和十月这里百花齐放，景色迷人。整体感受是体验一般，避开高峰更好。二刷意愿：否。', '40%', 39);
