INSERT INTO `travel_review` VALUES (127, 'TR000127', '巴图湾电厂', '鄂尔多斯', '内蒙古', '亲子出游', '夏季', 4, 4, 1136.00, '是', 5, '4月去的巴图湾电厂，一个人出行。地点在鄂尔多斯，打车比较省心，现场高峰时段比较拥挤。这次玩了4天，人均花费约1136元，氛围感不错。景点印象：巴图湾水电站座落在无定河中上游，巴图湾村境内，是鄂尔多斯规模较大的水力发电站。总装机容量为2800kw，单机800 kw3台，400 kw1台，设计年发电量600万kwh，是一座集发电、防洪、蓄水、旅游于一体的多效益型电站，承担着乌审旗西部电网调峰任务。\n…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 76);
