INSERT INTO `travel_review` VALUES (185, 'TR000185', '雨花台', '南京', '江苏', '文化打卡', '春季', 2, 1, 732.00, '否', 4, '2月去的雨花台，一个人出行。地点在南京，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约732元，拍照很出片。景点印象：曾是十万革命烈士殉难处，在此缅怀先烈，参观雨花石博物馆。整体感受是体验挺好，推荐来看看。二刷意愿：否。', '18%', 64);
INSERT INTO `travel_review` VALUES (186, 'TR000186', '黄河旅游区', '忻州', '山西', '亲子出游', '冬季', 11, 2, 237.00, '是', 5, '11月去的黄河旅游区，和家人出行。地点在忻州，打车比较省心，现场人不算多。这次玩了2天，人均花费约237元，夜景表现很好。景点印象：忻州的黄河旅游区，包括偏关、河曲和保德三县。黄河经过内蒙托克托县的河日镇后，急转直下，进人约180公里长的\"晋陕峡谷\"之中，此段黄河，咆哮奔腾，水面时宽时窄，河谷深切，山势险要，河水湍急，气势磅礴，十分壮观。特别是在汹涌澎湃的黄河之中…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 33);
INSERT INTO `travel_review` VALUES (187, 'TR000187', '烟台山景区', '烟台', '山东', '深度游', '冬季', 10, 3, 1204.00, '是', 5, '10月去的烟台山景区，和家人出行。地点在烟台，打车比较省心，现场人流量适中。这次玩了3天，人均花费约1204元，氛围感不错。景点印象：登上烟台的标志性灯塔，漫步海边栈道，欣赏海岸风光和城市全貌。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '17%', 102);
INSERT INTO `travel_review` VALUES (188, 'TR000188', '花垣边城旅游景区', '湘西', '湖南', '文化打卡', '秋季', 6, 1, 414.00, '是', 5, '6月去的花垣边城旅游景区，和朋友出行。地点在湘西，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约414元，氛围感不错。景点印象：沈从文的小说《边城》真正所在地，石板路，吊脚楼，酋水绕镇。 比起凤凰的人满为患，真正的边城很清静。 坐一坐小说《边城》里提及的拉拉渡，摆渡于酋水两岸。整体感受是特别满意，很推荐。二刷意愿：是。', '0%', 88);
