INSERT INTO `travel_review` VALUES (195, 'TR000195', '乌苏浪子湖', '兴安盟', '内蒙古', '城市漫游', '夏季', 3, 1, 184.00, '是', 5, '3月去的乌苏浪子湖，和朋友出行。地点在兴安盟，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约184元，历史文化气息浓。景点印象：乌苏浪子湖为火山喷发的熔岩流在流动过程中堵塞哈拉哈河形成的湖泊，原名49号泡子，四面环山，水面如镜，水质肥美，盛产鲤鱼、白鱼等冷水鱼。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '9%', 86);
INSERT INTO `travel_review` VALUES (196, 'TR000196', '签王之王-马先森', '塔城', '新疆', '城市漫游', '夏季', 4, 5, 1704.00, '是', 4, '4月去的签王之王-马先森，和朋友出行。地点在塔城，地铁到达方便，现场游客较多。这次玩了5天，人均花费约1704元，氛围感不错。景点印象：整体环境还算干净整体感受是整体不错，周末来刚好。二刷意愿：是。', '0%', 73);
INSERT INTO `travel_review` VALUES (197, 'TR000197', '彩虹桥', '上饶', '江西', '深度游', '夏季', 5, 2, 559.00, '是', 5, '5月去的彩虹桥，一个人出行。地点在上饶，公交换乘方便，现场人流量适中。这次玩了2天，人均花费约559元，氛围感不错。景点印象：古徽州最古老、最长的廊桥，踩着石墩过河，在水中央看廊桥全景。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '27%', 85);
INSERT INTO `travel_review` VALUES (198, 'TR000198', '绮罗古镇', '保山', '云南', '周末短途', '冬季', 11, 4, 976.00, '否', 5, '11月去的绮罗古镇，和家人出行。地点在保山，打车比较省心，现场游客较多。这次玩了4天，人均花费约976元，历史文化气息浓。景点印象：小桥流水，古树和那些青砖绿瓦，重檐式的辉煌建筑，构成了一幅宁静和谐的画面。整体感受是特别满意，以后还会来。二刷意愿：否。', '1%', 90);
INSERT INTO `travel_review` VALUES (199, 'TR000199', '大河堡凉都花海', '六盘水', '贵州', '亲子出游', '夏季', 5, 2, 720.00, '是', 4, '5月去的大河堡凉都花海，一个人出行。地点在六盘水，地铁到达方便，现场游客较多。这次玩了2天，人均花费约720元，拍照很出片。景点印象：周边配套比较齐全整体感受是体验挺好，推荐来看看。二刷意愿：是。', '8%', 68);
INSERT INTO `travel_review` VALUES (200, 'TR000200', '扬州大运河文化旅游度假区·史可法纪念馆', '扬州', '江苏', '文化打卡', '冬季', 11, 3, 882.00, '否', 5, '11月去的扬州大运河文化旅游度假区·史可法纪念馆，一个人出行。地点在扬州，自驾停车需要提前规划，现场游客较多。这次玩了3天，人均花费约882元，拍照很出片。景点印象：在史公祠和墓冢前缅怀民族英雄，秋冬季还可分别观赏银杏、梅花。整体感受是超出预期，很推荐。二刷意愿：否。', '4%', 77);
INSERT INTO `travel_review` VALUES (201, 'TR000201', '金鳞游泳', '铜仁', '贵州', '文化打卡', '秋季', 8, 2, 541.00, '否', 5, '8月去的金鳞游泳，情侣出行。地点在铜仁，公交换乘方便，现场游客较多。这次玩了2天，人均花费约541元，夜景表现很好。景点印象：铜仁岩的上游有一石头，下临锦江河面，其形状就像条鱼一样，老百姓称之为鲤鱼嘴。每当江面微波荡漾，那块石头就象鱼在不停地游动，古人在此山石上建起一座古刹，四周栽上茂密的翠竹，称为金鳞寺。\n鲤鱼仍在锦江游泳，金鳞寺却不知毁于何年何代。据…整体感受是超出预期，以后还会来。二刷意愿：否。', '2%', 56);
INSERT INTO `travel_review` VALUES (202, 'TR000202', '太子山风景旅游区', '临夏', '甘肃', '拍照旅行', '春季', 1, 4, 1424.00, '是', 5, '1月去的太子山风景旅游区，和朋友出行。地点在临夏，公交换乘方便，现场人不算多。这次玩了4天，人均花费约1424元，拍照很出片。景点印象：太子山又称大峙山，位于和政、临夏县境内，是临夏县南部、大夏河以东高大山岭的统称。由母太子山和公太子山组成，母太子山在东，海拔4368米，公太子山在西，海拔4183米，两山之间盘坡哑口，一夫当关，万夫莫开，是临夏与夏河县的分界，是连接中原文…整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 97);
INSERT INTO `travel_review` VALUES (203, 'TR000203', '鹅尾神石园', '莆田', '福建', '拍照旅行', '冬季', 10, 4, 1196.00, '是', 5, '10月去的鹅尾神石园，和家人出行。地点在莆田，公交换乘方便，现场高峰时段比较拥挤。这次玩了4天，人均花费约1196元，历史文化气息浓。景点印象：景点本身有一定特色整体感受是特别满意，以后还会来。二刷意愿：是。', '9%', 80);
INSERT INTO `travel_review` VALUES (204, 'TR000204', '静园', '天津', '天津', '文化打卡', '冬季', 10, 3, 1106.00, '否', 5, '10月去的静园，和朋友出行。地点在天津，地铁到达方便，现场人不算多。这次玩了3天，人均花费约1106元，拍照很出片。景点印象：溥仪故居，可以了解末代皇帝的生平，欣赏优雅的西式园林。整体感受是超出预期，值得专门打卡。二刷意愿：否。', '8%', 46);
INSERT INTO `travel_review` VALUES (205, 'TR000205', '黄沙古渡原生态旅游区', '银川', '宁夏', '文化打卡', '夏季', 5, 4, 1075.00, '否', 2, '5月去的黄沙古渡原生态旅游区，一个人出行。地点在银川，地铁到达方便，现场人流量适中。这次玩了4天，人均花费约1075元，历史文化气息浓。景点印象：体验各类沙上活动，领略“大漠黄河、塞北江南”的神奇。整体感受是没达到预期，建议谨慎前往。二刷意愿：否。', '4%', 27);
INSERT INTO `travel_review` VALUES (206, 'TR000206', '干地衣比湖', '怒江', '云南', '亲子出游', '秋季', 7, 1, 831.00, '否', 5, '7月去的干地衣比湖，和家人出行。地点在怒江，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约831元，夜景表现很好。景点印象：干地衣比湖是尚未开发的明静雪山系软型浸蚀谈湖泊之一，位于福贡县城上帕镇驻地东北方，碧罗雪山山脉西侧万山丛中，距福贡县城约40公里，湖泊海拔3490米，面积52500平方米，平均水深6米。盛夏季节，游人只要一声喊叫即会招来狂风暴雨，这种高山气候…整体感受是超出预期，很推荐。二刷意愿：否。', '0%', 64);
