INSERT INTO `travel_review` VALUES (224, 'TR000224', '黄河源', '果洛', '青海', '文化打卡', '冬季', 10, 3, 918.00, '否', 5, '10月去的黄河源，和家人出行。地点在果洛，公交换乘方便，现场人流量适中。这次玩了3天，人均花费约918元，历史文化气息浓。景点印象：也许你无法想像黄河的源头竟不是洪水滚滚，而是由众多细微的清泉和有许多砂砾野草的荒滩而组成，但会让你感受袒露无疑的大自然之美。整体感受是特别满意，值得专门打卡。二刷意愿：否。', '2%', 109);
INSERT INTO `travel_review` VALUES (225, 'TR000225', '哈巴雪山', '迪庆', '云南', '文化打卡', '春季', 12, 3, 307.00, '是', 5, '12月去的哈巴雪山，情侣出行。地点在迪庆，地铁到达方便，现场人不算多。这次玩了3天，人均花费约307元，历史文化气息浓。景点印象：玉龙雪山的“兄弟”，适合攀登的入门级雪山，山顶终年冰雪覆盖，周围环绕着大片冰川。整体感受是超出预期，很推荐。二刷意愿：是。', '2%', 33);
INSERT INTO `travel_review` VALUES (226, 'TR000226', '镇海寺', '忻州', '山西', '周末短途', '秋季', 8, 3, 759.00, '否', 5, '8月去的镇海寺，一个人出行。地点在忻州，自驾停车需要提前规划，现场人流量适中。这次玩了3天，人均花费约759元，拍照很出片。景点印象：观音殿中的观音、文殊、普贤三位菩萨都是长着胡子的男身造像，非常罕见。整体感受是超出预期，值得专门打卡。二刷意愿：否。', '6%', 105);
