INSERT INTO `travel_review` VALUES (230, 'TR000230', '花垣边城旅游景区', '湘西', '湖南', '深度游', '夏季', 3, 3, 1255.00, '否', 5, '3月去的花垣边城旅游景区，和朋友出行。地点在湘西，自驾停车需要提前规划，现场游客较多。这次玩了3天，人均花费约1255元，夜景表现很好。景点印象：沈从文的小说《边城》真正所在地，石板路，吊脚楼，酋水绕镇。 比起凤凰的人满为患，真正的边城很清静。 坐一坐小说《边城》里提及的拉拉渡，摆渡于酋水两岸。整体感受是特别满意，值得专门打卡。二刷意愿：否。', '0%', 98);
