INSERT INTO `travel_review` VALUES (253, 'TR000253', '太子山风景旅游区', '临夏', '甘肃', '深度游', '夏季', 3, 1, 416.00, '否', 5, '3月去的太子山风景旅游区，和朋友出行。地点在临夏，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约416元，拍照很出片。景点印象：太子山又称大峙山，位于和政、临夏县境内，是临夏县南部、大夏河以东高大山岭的统称。由母太子山和公太子山组成，母太子山在东，海拔4368米，公太子山在西，海拔4183米，两山之间盘坡哑口，一夫当关，万夫莫开，是临夏与夏河县的分界，是连接中原文…整体感受是超出预期，值得专门打卡。二刷意愿：否。', '0%', 60);
