INSERT INTO `travel_review` VALUES (259, 'TR000259', '南村', '洛阳', '河南', '城市漫游', '春季', 12, 4, 1325.00, '否', 3, '12月去的南村，情侣出行。地点在洛阳，地铁到达方便，现场人不算多。这次玩了4天，人均花费约1325元，夜景表现很好。景点印象：南村位于河南省洛阳市涧西工业区，是典型的都市村庄。全村有农业人口2300人，村集体企业于1998年组建了南华集团公司，成为一家集冶金、铸造、耐火材料、机械加工、餐饮、娱乐、证券参股、医疗、商贸及信息产业为一体的综合型乡镇企业集团公司，总资…整体感受是中规中矩，避开高峰更好。二刷意愿：否。', '0%', 19);
INSERT INTO `travel_review` VALUES (260, 'TR000260', '苏木山森林公园', '乌兰察布', '内蒙古', '城市漫游', '冬季', 11, 7, 1584.00, '否', 5, '11月去的苏木山森林公园，情侣出行。地点在乌兰察布，打车比较省心，现场人流量适中。这次玩了7天，人均花费约1584元，拍照很出片。景点印象：苏木山旅游区，以其险峻的山势，茂密的森林，纷呈的花卉以及浓郁的民族风情吸引着越来越多的贪享自然之美的旅行者，归者无不为其绝、其美所折服。整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '6%', 30);
