INSERT INTO `travel_review` VALUES (263, 'TR000263', '自怀风景区', '泸州', '四川', '周末短途', '冬季', 11, 1, 522.00, '是', 5, '11月去的自怀风景区，和朋友出行。地点在泸州，地铁到达方便，现场人不算多。这次玩了1天，人均花费约522元，拍照很出片。景点印象：自怀风景区是世界同纬度上唯一的，保留完整的常绿阔叶林带，自怀景区在1989年被确定为省级风景名胜区。这里四季风光各异，盛夏，气温平均比山外低5森摄氏度以上，有天然大空调之说，山秀、水美、石奇、民风纯朴，是自怀风光所独有。这里的原始林，…整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 76);
INSERT INTO `travel_review` VALUES (264, 'TR000264', '加井岛', '万宁', '海南', '拍照旅行', '秋季', 8, 1, 176.00, '是', 5, '8月去的加井岛，一个人出行。地点在万宁，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约176元，历史文化气息浓。景点印象：原生态的无人小岛，沙白水清，是享受海岛时光的绝佳去处。整体感受是超出预期，很推荐。二刷意愿：是。', '36%', 65);
