INSERT INTO `travel_review` VALUES (290, 'TR000290', '汾酒工业园林', '吕梁', '山西', '拍照旅行', '冬季', 9, 3, 817.00, '否', 5, '9月去的汾酒工业园林，一个人出行。地点在吕梁，打车比较省心，现场高峰时段比较拥挤。这次玩了3天，人均花费约817元，历史文化气息浓。景点印象：山西杏花村汾酒集团是我国最大的名白酒生产基地之一，他们生产的中国驰名商品“杏花村”汾酒、竹叶青远销50多个国家和地区，年销售收入近10个亿，年出口创汇2000万美元。进入新世纪，面对WTO带来的机遇和挑战，杏花村汾酒集团公司在把握中国白酒业…整体感受是特别满意，以后还会来。二刷意愿：否。', '5%', 99);
