INSERT INTO `travel_review` VALUES (293, 'TR000293', '关东影视城', '沈阳', '辽宁', '周末短途', '秋季', 6, 2, 870.00, '否', 3, '6月去的关东影视城，一个人出行。地点在沈阳，公交换乘方便，现场游客较多。这次玩了2天，人均花费约870元，拍照很出片。景点印象：集影视拍摄、休闲娱乐和文化教育一体，再现上世纪二三十年代沈阳城独特关东风情。整体感受是中规中矩，按需选择。二刷意愿：否。', '0%', 76);
INSERT INTO `travel_review` VALUES (294, 'TR000294', '狼洞沟', '抚顺', '辽宁', '亲子出游', '夏季', 3, 5, 1482.00, '是', 5, '3月去的狼洞沟，一个人出行。地点在抚顺，自驾停车需要提前规划，现场游客较多。这次玩了5天，人均花费约1482元，拍照很出片。景点印象：景点本身有一定特色整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 117);
INSERT INTO `travel_review` VALUES (295, 'TR000295', '青云塔', '万宁', '海南', '深度游', '秋季', 8, 2, 689.00, '否', 5, '8月去的青云塔，情侣出行。地点在万宁，公交换乘方便，现场游客较多。这次玩了2天，人均花费约689元，拍照很出片。景点印象：当地亦称这\"山尾岭\"、\"万州塔\"。青云塔体为八角形，用火砖和零星石料砌成，塔高约27米，分七层七檐。顶层正中，突出一个八棱柱，柱顶托道一个球形塔刹。底层内壁为八角形，上面六层内壁均为圆形，每层从不同方向对开两个拱门，一供观赏，二供通风透…整体感受是挺惊喜，很推荐。二刷意愿：否。', '0%', 82);
