INSERT INTO `travel_review` VALUES (298, 'TR000298', '九女湖', '晋城', '山西', '周末短途', '秋季', 7, 2, 471.00, '否', 3, '7月去的九女湖，和家人出行。地点在晋城，打车比较省心，现场高峰时段比较拥挤。这次玩了2天，人均花费约471元，历史文化气息浓。景点印象：九仙女湖旅游风景区--位于山西省阳城县，是传说中仙女下凡游玩之处所，湖中矗立有九女仙台，台上建有九女仙祠，是阳城古城八景之一。曾是历代文人墨客经常观光旅游的地方。\n九女湖地处太行山和中条山交汇的沁河峡谷之中，它是阳城县继国家级自然风…整体感受是还可以，按需选择。二刷意愿：否。', '11%', 90);
