INSERT INTO `travel_review` VALUES (301, 'TR000301', '湖田古窑遗址', '景德镇', '江西', '城市漫游', '夏季', 4, 1, 297.00, '是', 5, '4月去的湖田古窑遗址，和家人出行。地点在景德镇，自驾停车需要提前规划，现场人不算多。这次玩了1天，人均花费约297元，氛围感不错。景点印象：湖田窑是我国宋、元两代各大制瓷规模最大、延续烧造时间最长、生产的瓷器最精美的古代窑场。遗址保存的遗物非常丰富，历代古窑遍地。整体感受是超出预期，很推荐。二刷意愿：是。', '10%', 96);
