INSERT INTO `travel_review` VALUES (327, 'TR000327', '圣仙洞', '娄底', '湖南', '亲子出游', '春季', 12, 5, 1470.00, '否', 4, '12月去的圣仙洞，一个人出行。地点在娄底，打车比较省心，现场人不算多。这次玩了5天，人均花费约1470元，夜景表现很好。景点印象：圣仙洞位于市郊尖子山白石岩腰。此洞穿通整个尖子山内腹，有洞口通向山顶。洞内的景观有正宫殿、观音殿、水晶殿、万家灶、千层塔、大象厅、玉兰园、瀑布岩、葫芦台、阳河口、神龟潭等大小厅堂14个，还有隐龙宫、舍身岩、南天门、北天门、银河口、地…整体感受是整体不错，推荐来看看。二刷意愿：否。', '0%', 67);
