INSERT INTO `travel_review` VALUES (339, 'TR000339', '哈拉海湿地', '齐齐哈尔', '黑龙江', '城市漫游', '秋季', 8, 5, 1880.00, '否', 5, '8月去的哈拉海湿地，和家人出行。地点在齐齐哈尔，地铁到达方便，现场游客较多。这次玩了5天，人均花费约1880元，夜景表现很好。景点印象：哈拉海湿地位于松嫩平原的西北端、大兴安岭南麓、龙江县西北部，总面积300平方公里，核心水域30平方公里，水位落差较大。该湿地芦苇丛生，鱼肥鸟众，湖泊纵横，是我国境内唯一有湖泊的原始湿地。该湿地最具价值的发现在于其世界罕见的原始性，其大…整体感受是超出预期，值得专门打卡。二刷意愿：否。', '0%', 90);
