INSERT INTO `travel_review` VALUES (387, 'TR000387', '井冈山碑林', '吉安', '江西', '拍照旅行', '冬季', 10, 5, 1185.00, '否', 3, '10月去的井冈山碑林，一个人出行。地点在吉安，地铁到达方便，现场游客较多。这次玩了5天，人均花费约1185元，拍照很出片。景点印象：井冈山碑林始建于1987年7月，自1989年清明节起对外开放。碑林由碑亭、碑廊、自然碑型等部分组成，因势而构，曲折回环，别具一番情趣。整体感受是中规中矩，避开高峰更好。二刷意愿：否。', '5%', 102);
INSERT INTO `travel_review` VALUES (388, 'TR000388', '雪峰寺', '莆田', '福建', '城市漫游', '冬季', 9, 6, 1479.00, '是', 5, '9月去的雪峰寺，情侣出行。地点在莆田，打车比较省心，现场人流量适中。这次玩了6天，人均花费约1479元，氛围感不错。景点印象：又名崇圣寺，全名雪峰崇圣禅寺,位于闽侯县西北雪峰凤凰山南麓。唐咸通十一年（870）建,现存殿宇多为光绪年间重修。寺内主要建筑是山门、法堂、大雄宝殿、斋堂。大雄宝殿内有来自缅甸的三世如来玉佛。十八罗汉姿态各异，栩栩如生。山门外有古树四株…整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 126);
