INSERT INTO `travel_review` VALUES (396, 'TR000396', '嘉陵江', '陇南', '甘肃', '亲子出游', '冬季', 9, 2, 714.00, '是', 5, '9月去的嘉陵江，一个人出行。地点在陇南，自驾停车需要提前规划，现场游客较多。这次玩了2天，人均花费约714元，氛围感不错。景点印象：“汉水南入嘉陵道而为嘉陵水”，江名由此而来，嘉陵江发源于秦岭南麓，流经陕、甘、川至重庆流入长江。沿江两岸奇峰壁立、怪石嶙峋、森林茂密、泉瀑众多、美不胜收。整体感受是特别满意，很推荐。二刷意愿：是。', '41%', 88);
