INSERT INTO `travel_review` VALUES (416, 'TR000416', '罗圈背', '鞍山', '辽宁', '亲子出游', '夏季', 5, 5, 1138.00, '是', 5, '5月去的罗圈背，一个人出行。地点在鞍山，公交换乘方便，现场人流量适中。这次玩了5天，人均花费约1138元，历史文化气息浓。景点印象：岫岩罗圈背风景区位于岫岩满族自治县洋河镇南端罗圈背岭山脚下，风景区占地面积570万平方米，水域面积370万平方米，蓄水量6000万立方米，是鞍山地区规模最大的水库。从空中俯视，水库外形恰如一个罗锅，所以得名罗圈背。水库是岫岩和东港的交界处，…整体感受是挺惊喜，以后还会来。二刷意愿：是。', '4%', 95);
