INSERT INTO `travel_review` VALUES (443, 'TR000443', '安新县', '雄安新区', '河北', '城市漫游', '春季', 12, 1, 824.00, '否', 5, '12月去的安新县，一个人出行。地点在雄安新区，地铁到达方便，现场人不算多。这次玩了1天，人均花费约824元，拍照很出片。景点印象：安新县是河北省保定市下辖县，位于河北省中部，县境东与雄县相连，北与容城毗邻，并与之一起成为雄安新区。安新县因受历史上冀中拗陷和黄河改道及太行山东麓永定河、滹沱河冲积扇的影响，形成特殊形貌。西南北有冲积洼地平原，东有华北平原最大的淡…整体感受是特别满意，值得专门打卡。二刷意愿：否。', '0%', 67);
INSERT INTO `travel_review` VALUES (444, 'TR000444', '净月潭', '长春', '吉林', '深度游', '夏季', 3, 5, 1261.00, '否', 5, '3月去的净月潭，和家人出行。地点在长春，公交换乘方便，现场游客较多。这次玩了5天，人均花费约1261元，氛围感不错。景点印象：被誉为日月潭的姐妹潭，漫步林间步道享受森林浴，呼吸纯净空气。整体感受是挺惊喜，以后还会来。二刷意愿：否。', '24%', 70);
