INSERT INTO `travel_review` VALUES (447, 'TR000447', '包头敖伦苏木', '包头', '内蒙古', '拍照旅行', '秋季', 8, 2, 471.00, '否', 5, '8月去的包头敖伦苏木，情侣出行。地点在包头，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了2天，人均花费约471元，氛围感不错。景点印象：在达茂联合旗百灵庙镇东北约30公里处，有一座元代古城遗址，当地牧民称为“敖伦苏木”。这是全国重点文物保护单位，是元代很有势力的汪古部族的王府遗址。\n在茫茫的大漠草原上，远远地就能看到古城残垣断壁的高大建筑物的废墟，周围土地曾被开发的…整体感受是特别满意，以后还会来。二刷意愿：否。', '1%', 53);
