INSERT INTO `travel_review` VALUES (462, 'TR000462', '莽措湖', '昌都', '西藏', '周末短途', '春季', 2, 1, 115.00, '否', 5, '2月去的莽措湖，一个人出行。地点在昌都，地铁到达方便，现场游客较多。这次玩了1天，人均花费约115元，拍照很出片。景点印象：莽措湖位于芒康中部莽岭乡境内，距县城 90 公里 ，国道 214 线往北 60 公里 处，海拔 4313 米 ，湖水面积 20 多平方公里。整体感受是特别满意，很推荐。二刷意愿：否。', '6%', 49);
INSERT INTO `travel_review` VALUES (463, 'TR000463', '文星楼', '荆州', '湖北', '城市漫游', '秋季', 7, 2, 962.00, '否', 5, '7月去的文星楼，和家人出行。地点在荆州，打车比较省心，现场人流量适中。这次玩了2天，人均花费约962元，拍照很出片。景点印象：位于沙市市东南之民主街东街尾，傍临荆江大堤。该楼又名奎文阁、魁星阁，为供奉“奎星”之阁故名。该楼在清康熙年间建于堤外，清代中期迁建于此，清同治三年（公元1864年）重建，1940年被日本侵略军烧坏，1941年修复。旧时文人读书旨在做官，命运似…整体感受是挺惊喜，很推荐。二刷意愿：否。', '3%', 115);
INSERT INTO `travel_review` VALUES (464, 'TR000464', '敬亭山', '宣城', '安徽', '城市漫游', '春季', 12, 3, 680.00, '是', 5, '12月去的敬亭山，情侣出行。地点在宣城，打车比较省心，现场人流量适中。这次玩了3天，人均花费约680元，夜景表现很好。景点印象：李白写下“相看两不厌，只有敬亭山”的地方。 参观地标宋代广教寺双塔，在太白独坐楼下缅怀李白。 山上有大片茶园和竹林，空气清新，登云桥俯看宣城和水阳江。整体感受是超出预期，以后还会来。二刷意愿：是。', '14%', 46);
