INSERT INTO `travel_review` VALUES (474, 'TR000474', '阳泉水帘洞瀑布', '阳泉', '山西', '亲子出游', '秋季', 7, 6, 1365.00, '是', 4, '7月去的阳泉水帘洞瀑布，情侣出行。地点在阳泉，打车比较省心，现场高峰时段比较拥挤。这次玩了6天，人均花费约1365元，氛围感不错。景点印象：位于娘子关城东门东南方向的500米处。飞瀑奔泻，悬流百尺，散缕似珠，山城沟谷中泉眼累累。当地人称为“海眼”的悬泉，是众泉眼中最大的一个。瀑布落差30余米，宽约10多米，“海眼”泉水翻滚，激起层层白色浪花，响声震耳。平地涌出的泉水，从“海…整体感受是还蛮满意，周末来刚好。二刷意愿：是。', '0%', 87);
