INSERT INTO `travel_review` VALUES (508, 'TR000508', '汉兵马俑博物馆', '徐州', '江苏', '亲子出游', '秋季', 6, 1, 343.00, '是', 4, '6月去的汉兵马俑博物馆，一个人出行。地点在徐州，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约343元，氛围感不错。景点印象：陈列的汉代兵器、生活品、兵马俑等，既是艺术品也能看到汉代“视死如生”的丧葬制度。整体感受是整体不错，可以安排半天到一天。二刷意愿：是。', '9%', 54);
