INSERT INTO `travel_review` VALUES (526, 'TR000526', '新期火山奇观观光区', '黑河', '黑龙江', '文化打卡', '春季', 1, 2, 782.00, '否', 5, '1月去的新期火山奇观观光区，一个人出行。地点在黑河，地铁到达方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约782元，历史文化气息浓。景点印象：新期火山奇观观光区，是世界地质公园的核心，景观带总面积50平方公里，地质形成年代距今280多年，属最新期喷发的火山。这里保存了世界上新期火山地质的全貌，对研究地球物理发展史具有重要意义。区域内新期火山喷发裸露熔岩台地浩瀚无垠十分壮观，…整体感受是超出预期，以后还会来。二刷意愿：否。', '0%', 65);
