INSERT INTO `travel_review` VALUES (538, 'TR000538', '上窑国家森林公园', '淮南', '安徽', '城市漫游', '冬季', 11, 1, 277.00, '否', 5, '11月去的上窑国家森林公园，情侣出行。地点在淮南，地铁到达方便，现场人不算多。这次玩了1天，人均花费约277元，拍照很出片。景点印象：安徽上窑国家森林公园位于著名煤城淮南市东北部，横卧于美丽富饶的窑河之滨。地处东径117度06’，一117度10’，北纬32 度45’， 一32度47’，公园总面积10．4平方公里。上窑森林公园是于1992年11月26日，经原林业部批准 ，在国营上窑林场的基础上建…整体感受是特别满意，很推荐。二刷意愿：否。', '0%', 62);
INSERT INTO `travel_review` VALUES (539, 'TR000539', '明永冰川', '迪庆', '云南', '拍照旅行', '冬季', 9, 1, 231.00, '否', 5, '9月去的明永冰川，情侣出行。地点在迪庆，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约231元，历史文化气息浓。景点印象：登上冰川观景台，近距离感受冰川和卡瓦格博的壮美。整体感受是挺惊喜，很推荐。二刷意愿：否。', '3%', 99);
INSERT INTO `travel_review` VALUES (540, 'TR000540', '清溪水库', '丽江', '云南', '周末短途', '冬季', 10, 3, 600.00, '是', 4, '10月去的清溪水库，和朋友出行。地点在丽江，公交换乘方便，现场人不算多。这次玩了3天，人均花费约600元，拍照很出片。景点印象：可以拍摄雪山在湖中的倒影，湖水清澈，环境清新优美。整体感受是整体不错，周末来刚好。二刷意愿：是。', '0%', 78);
