INSERT INTO `travel_review` VALUES (552, 'TR000552', '仰山书院', '抚州', '江西', '亲子出游', '春季', 2, 3, 769.00, '是', 5, '2月去的仰山书院，和朋友出行。地点在抚州，地铁到达方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约769元，历史文化气息浓。景点印象：书院位于金溪县城王家巷，始建于清代乾隆二年（1737年），该院为南宋朱熹与陆九渊曾经讲学过的崇正书院遗址。书院右侧“先儒祠”是清代生员祭祀乡贤象山先生之所，现书院建筑面积1078平方米，构架保存完整，是江西省省级保护文物、县文博所办公之处…整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 99);
