INSERT INTO `travel_review` VALUES (556, 'TR000556', '咸阳古渡', '咸阳', '陕西', '周末短途', '春季', 1, 2, 715.00, '否', 5, '1月去的咸阳古渡，和家人出行。地点在咸阳，打车比较省心，现场人流量适中。这次玩了2天，人均花费约715元，氛围感不错。景点印象：建筑于明嘉靖年间，渡口处建有一座木桥，通陇通蜀，为秦中第一渡。整体感受是特别满意，以后还会来。二刷意愿：否。', '0%', 58);
INSERT INTO `travel_review` VALUES (557, 'TR000557', '白杨沟泥火山群', '塔城', '新疆', '文化打卡', '春季', 2, 7, 1798.00, '否', 3, '2月去的白杨沟泥火山群，一个人出行。地点在塔城，地铁到达方便，现场高峰时段比较拥挤。这次玩了7天，人均花费约1798元，氛围感不错。景点印象：新疆乌苏泥火山群位于乌苏市南约40公里，距白杨沟镇约2.5公里，属天山北坡山前丘陵地带，海拔1281米，分布在长约200米，宽约100米的范围内，约有40个泥喷发口。泥火山并非真正火山，爆发原因是地下的天然气（瓦斯）向地面喷射，将地面的泥土冲出，…整体感受是中规中矩，避开高峰更好。二刷意愿：否。', '10%', 35);
INSERT INTO `travel_review` VALUES (558, 'TR000558', '白马潭天险河漂流', '安庆', '安徽', '周末短途', '秋季', 7, 2, 437.00, '否', 4, '7月去的白马潭天险河漂流，一个人出行。地点在安庆，自驾停车需要提前规划，现场人流量适中。这次玩了2天，人均花费约437元，历史文化气息浓。景点印象：皖河漂流在天柱山南麓，有一条如同绿绸翠带般的河流盘绕山谷,这就是皖河,而其上游河段的白马潭天险河是皖河漂流的黄金河段。天险河景区河段全长约七公里,沿途七处险滩,六处深潭。滩水动如脱兔、潭水静若处子,河边龟牛狮象等奇石栩栩如生。在天险河…整体感受是整体不错，推荐来看看。二刷意愿：否。', '0%', 60);
INSERT INTO `travel_review` VALUES (559, 'TR000559', '摩天岭', '威海', '山东', '文化打卡', '冬季', 9, 1, 456.00, '否', 4, '9月去的摩天岭，一个人出行。地点在威海，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约456元，夜景表现很好。景点印象：体验亚洲最长的跨海索道，凭栏观海，体验云间穿梭，俯视碧海仙境。整体感受是体验挺好，周末来刚好。二刷意愿：否。', '3%', 90);
