INSERT INTO `travel_review` VALUES (617, 'TR000617', '国家牡丹园', '洛阳', '河南', '亲子出游', '秋季', 6, 7, 1788.00, '是', 4, '6月去的国家牡丹园，和朋友出行。地点在洛阳，打车比较省心，现场人流量适中。这次玩了7天，人均花费约1788元，夜景表现很好。景点印象：每年的四月，游客可以在园中欣赏到几十万株、上千个品种的牡丹花，还能一睹“千年牡丹王”的风采。整体感受是体验挺好，可以安排半天到一天。二刷意愿：是。', '2%', 99);
INSERT INTO `travel_review` VALUES (618, 'TR000618', '崇安寺', '晋城', '山西', '文化打卡', '春季', 12, 2, 294.00, '是', 5, '12月去的崇安寺，一个人出行。地点在晋城，公交换乘方便，现场人不算多。这次玩了2天，人均花费约294元，拍照很出片。景点印象：崇安寺，古称凌烟寺，位于山西省陵川县崇文镇西北的卧龙岗上，大有居高临下，俯瞰全城的雄伟气魄，\"先有崇安，后有陵川\"的远古说法在当地流传甚广。\n崇安寺的创始年代已无从稽考，唐初原名为\"丈八佛寺\'，宋太平兴国元年？？公元976年？？敕命为崇…整体感受是超出预期，以后还会来。二刷意愿：是。', '2%', 54);
