INSERT INTO `travel_review` VALUES (645, 'TR000645', '兴国寺', '忻州', '山西', '文化打卡', '秋季', 6, 1, 466.00, '否', 5, '6月去的兴国寺，情侣出行。地点在忻州，公交换乘方便，现场游客较多。这次玩了1天，人均花费约466元，氛围感不错。景点印象：兴国寺位于忻州市忻府区城内兴寺街，因出土唐代经幢而著名。经幢的地点在天王殿后，也是在兴国寺的中轴线上，是八棱石柱形，直径90厘米，高1.8米。幢上刻着《尊胜陀罗尼经》，笔体遒劲。莲瓣上的瓣尖、飞天的翅膀、古拙的造型，都显示出唐代的艺术…整体感受是挺惊喜，很推荐。二刷意愿：否。', '0%', 60);
