INSERT INTO `travel_review` VALUES (651, 'TR000651', '吉林查干湖国家级自然保护区-观景台', '松原', '吉林', '周末短途', '夏季', 4, 2, 643.00, '是', 4, '4月去的吉林查干湖国家级自然保护区-观景台，和家人出行。地点在松原，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约643元，拍照很出片。景点印象：景点本身有一定特色整体感受是还蛮满意，推荐来看看。二刷意愿：是。', '0%', 39);
INSERT INTO `travel_review` VALUES (652, 'TR000652', '福音堂', '南充', '四川', '拍照旅行', '春季', 1, 3, 1146.00, '否', 4, '1月去的福音堂，一个人出行。地点在南充，自驾停车需要提前规划，现场人流量适中。这次玩了3天，人均花费约1146元，夜景表现很好。景点印象：位于杨天井街7号，又称圣约翰大教堂，建于光绪三十四年，已有近百年历史。它是四川最早的西洋建筑之一，也是西南现存规模最大的基督教堂，曾一度为基督教东川教区总堂，系英国传教士“剑桥七杰”之一的盖世礼筹资修建，澳大利亚工程师设计，教堂临…整体感受是体验挺好，周末来刚好。二刷意愿：否。', '1%', 58);
INSERT INTO `travel_review` VALUES (653, 'TR000653', '丙中洛风景区', '怒江', '云南', '周末短途', '夏季', 5, 7, 1561.00, '是', 5, '5月去的丙中洛风景区，和朋友出行。地点在怒江，打车比较省心，现场人不算多。这次玩了7天，人均花费约1561元，氛围感不错。景点印象：爬上贡当神山，可俯瞰整个怒江第一湾。 周末时候，当地信徒会聚集在镇上的天主教堂，集体唱圣歌，嘹亮高亢。 秋那桶的峡谷穿行，沿途风光很美。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '25%', 111);
INSERT INTO `travel_review` VALUES (654, 'TR000654', '朝阳鸟化石国家地质公园', '朝阳', '辽宁', '文化打卡', '春季', 2, 1, 691.00, '是', 5, '2月去的朝阳鸟化石国家地质公园，一个人出行。地点在朝阳，打车比较省心，现场人流量适中。这次玩了1天，人均花费约691元，夜景表现很好。景点印象：陈列着迄今世界上最早的鸟类和开花植物的化石标本。 观赏当地出土的恐龙、爬行类、昆虫类等多种化石标本。 行走在化石发掘现场，观察中生代化石的剖面。整体感受是特别满意，很推荐。二刷意愿：是。', '25%', 86);
INSERT INTO `travel_review` VALUES (655, 'TR000655', '偶园', '潍坊', '山东', '周末短途', '春季', 1, 2, 347.00, '是', 5, '1月去的偶园，一个人出行。地点在潍坊，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约347元，拍照很出片。景点印象：在青州市里民主街南首，有一处被当地人称为“冯家花园”的偶园，它原是清初大学士、太子太溥冯溥的私人花园，系清康熙初年所建，是全国幸存的为数不多的“康熙风格”的园林建筑。偶园的规模虽不大，但它结构严谨，布局得体，别有一番情趣，满园内亭…整体感受是特别满意，以后还会来。二刷意愿：是。', '9%', 112);
