INSERT INTO `travel_review` VALUES (664, 'TR000664', '磨盘山', '吉林市', '吉林', '拍照旅行', '夏季', 4, 1, 80.00, '否', 3, '4月去的磨盘山，和朋友出行。地点在吉林市，公交换乘方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约80元，历史文化气息浓。景点印象：磨盘山又叫小磨盘山，在丰满区前二道乡王相村境内。距市区15公里，总面积10平方公里。磨盘山顶峰形状如磨盘，因此而得名。该山南北走向，南北峰对峙，南侧面为长山顶，北侧为尖山顶。北侧主峰海拔783.8米。磨盘山山势陡峻。峰奇石秀，林木茂密，狼…整体感受是体验一般，按需选择。二刷意愿：否。', '0%', 46);
