INSERT INTO `travel_review` VALUES (670, 'TR000670', '朱然陈列馆', '马鞍山', '安徽', '文化打卡', '秋季', 7, 6, 1346.00, '否', 5, '7月去的朱然陈列馆，一个人出行。地点在马鞍山，公交换乘方便，现场游客较多。这次玩了6天，人均花费约1346元，历史文化气息浓。景点印象：朱然陈列馆位于安徽省马鞍山市区南部的雨山乡境内，为三国东吴大将朱然之墓。朱然墓发掘于1984年6月，出土许多珍贵文物，部分漆器填补了三国美术史的空白，也是已发掘东吴墓葬中墓主身份最高、墓葬规模最大的、时间最早的一座大墓，被列为80年代中…整体感受是超出预期，以后还会来。二刷意愿：否。', '25%', 71);
