INSERT INTO `travel_review` VALUES (705, 'TR000705', '云山屯', '安顺', '贵州', '周末短途', '秋季', 8, 4, 687.00, '否', 5, '8月去的云山屯，情侣出行。地点在安顺，打车比较省心，现场人不算多。这次玩了4天，人均花费约687元，夜景表现很好。景点印象：作为数百年前留下的历史“化石”，云山屯和它所代表的屯堡文化，已经成了黔中一道靓丽的人文景观，让人们去感受那深隧的过去。整体感受是挺惊喜，很推荐。二刷意愿：否。', '0%', 72);
INSERT INTO `travel_review` VALUES (706, 'TR000706', '孔庙', '德阳', '四川', '文化打卡', '冬季', 9, 2, 527.00, '否', 5, '9月去的孔庙，和家人出行。地点在德阳，自驾停车需要提前规划，现场人流量适中。这次玩了2天，人均花费约527元，夜景表现很好。景点印象：位于德阳市中心南街。孔庙又称文庙，是祭把孔子的庙字。孔子，名丘，字仲尼，春 秋时鲁国人，是中国最伟大的思想家、教育家、政治家、儒 家学派创治人，世界文化名人。他创立的儒家学说，在漫长的中国计建社会，奉为正统思想，长达两千多年。他彼统…整体感受是挺惊喜，很推荐。二刷意愿：否。', '1%', 105);
