INSERT INTO `travel_review` VALUES (742, 'TR000742', '水丰景区', '丹东', '辽宁', '拍照旅行', '春季', 2, 1, 714.00, '否', 3, '2月去的水丰景区，和家人出行。地点在丹东，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约714元，氛围感不错。景点印象：水丰景区素有东北地区第一大水库和辽宁淡水湖之称。远看两岸青山叠翠，古树参天，水线以下尽是刀削岩壁，沙石堆彻的天然景观。边境山水、界河文化、百年生态、传奇江坝、古老习俗、古朴民风，是水丰景区发展旅游的定位。主要景点有：水丰大坝网箱养…整体感受是还可以，避开高峰更好。二刷意愿：否。', '0%', 55);
