INSERT INTO `travel_review` VALUES (744, 'TR000744', '龙潭瀑布', '商洛', '陕西', '文化打卡', '春季', 12, 3, 882.00, '是', 3, '12月去的龙潭瀑布，和朋友出行。地点在商洛，打车比较省心，现场高峰时段比较拥挤。这次玩了3天，人均花费约882元，拍照很出片。景点印象：州东百里，龙驹寨东河，即涌峪河，两峰对峙，一水直泻为瀑布，下为龙潭，潭中有巨石连岸，危步临之，真奇观也。\n[注释]危步：小心谨慎地行走。此景在今舟凤县城东北2．5公里处。整体感受是还可以，按需选择。二刷意愿：是。', '0%', 41);
