INSERT INTO `travel_review` VALUES (746, 'TR000746', '慕士塔格冰山', '喀什', '新疆', '文化打卡', '秋季', 7, 1, 181.00, '否', 5, '7月去的慕士塔格冰山，和朋友出行。地点在喀什，公交换乘方便，现场人流量适中。这次玩了1天，人均花费约181元，拍照很出片。景点印象：慕士塔格冰山海拔7745米，位于乌恰县与塔什库尔干县交界处。塔吉克语意为“冰川之父”。\n相传，慕士塔格峰上住着一位冰山公主，她与住在对面的海拔8116米的世界第二高峰乔格里峰上的雪山王子热恋，凶恶的天王知道后很不高兴，就用神棍劈开了这两座…整体感受是特别满意，以后还会来。二刷意愿：否。', '4%', 76);
