INSERT INTO `travel_review` VALUES (751, 'TR000751', '白水洞', '邵阳', '湖南', '深度游', '春季', 1, 5, 1494.00, '否', 3, '1月去的白水洞，和家人出行。地点在邵阳，地铁到达方便，现场游客较多。这次玩了5天，人均花费约1494元，历史文化气息浓。景点印象：白水洞风景名胜区位于湘中新邵县境内，核心景区在严塘镇白水村。 早在明代， 白水洞就是湘中的旅游胜地，文人墨客纷来沓至， 多有赞咏。清人杨太灏著有《白水洞游记》、 李厚培著有《白水洞纪胜集》。白水洞风景名胜区于1999年经省人民政 府正式批…整体感受是还可以，避开高峰更好。二刷意愿：否。', '10%', 24);
