INSERT INTO `travel_review` VALUES (759, 'TR000759', '塞罕坝机械林场', '承德', '河北', '周末短途', '冬季', 9, 2, 301.00, '否', 5, '9月去的塞罕坝机械林场，和家人出行。地点在承德，打车比较省心，现场游客较多。这次玩了2天，人均花费约301元，氛围感不错。景点印象：景点本身有一定特色整体感受是挺惊喜，以后还会来。二刷意愿：否。', '0%', 100);
INSERT INTO `travel_review` VALUES (760, 'TR000760', '茂兰喀斯特森林', '黔南', '贵州', '亲子出游', '冬季', 10, 1, 724.00, '是', 4, '10月去的茂兰喀斯特森林，和朋友出行。地点在黔南，打车比较省心，现场游客较多。这次玩了1天，人均花费约724元，历史文化气息浓。景点印象：茂兰自然保护区是国家级自然保护区，也是南方喀斯特自然遗产最重要的组成部分，这里分布着喀斯特的森林、山水、溶洞和珍稀动植物，这里还生活着布依、水族、瑶族等少数民族几千名原始居民。整体感受是还蛮满意，可以安排半天到一天。二刷意愿：是。', '18%', 44);
INSERT INTO `travel_review` VALUES (761, 'TR000761', '云南禹龙', '昭通', '云南', '深度游', '秋季', 7, 3, 1281.00, '否', 5, '7月去的云南禹龙，情侣出行。地点在昭通，自驾停车需要提前规划，现场人流量适中。这次玩了3天，人均花费约1281元，氛围感不错。景点印象：周边配套比较齐全整体感受是特别满意，值得专门打卡。二刷意愿：否。', '0%', 74);
INSERT INTO `travel_review` VALUES (762, 'TR000762', '银盘山', '常德', '湖南', '深度游', '冬季', 11, 2, 1032.00, '否', 2, '11月去的银盘山，情侣出行。地点在常德，公交换乘方便，现场游客较多。这次玩了2天，人均花费约1032元，夜景表现很好。景点印象：银盘山位于五溪湖北岸，神公寨东侧，三面环水，其状如盘，故名银盘山。一侧是青松岭，东侧有哨楼，这里山水清幽，景色宜人，是旅途中游憩之所。\n登上银盘山，面对碧绿的湖水，灿烂的鲜花，奔泻的山泉武，飞动的流云，你一定会乐而忘返的。\n银盘山…整体感受是体验偏一般，可考虑其他景点。二刷意愿：否。', '0%', 46);
INSERT INTO `travel_review` VALUES (763, 'TR000763', '下草湾古人类遗址', '宿迁', '江苏', '城市漫游', '春季', 1, 3, 1071.00, '否', 3, '1月去的下草湾古人类遗址，情侣出行。地点在宿迁，打车比较省心，现场人不算多。这次玩了3天，人均花费约1071元，夜景表现很好。景点印象：位于双沟镇东南8公里处的下草湾引河东岸，是江苏省发现最早的古人类遗址。2002年，被市政府确定为市级重点文物保护单位。1954年6月，中国科学院院士、古脊椎动物和古人类研究所所长杨钟健教授在下草湾考察时，采集到一段长15.27厘米的骨化石。经研…整体感受是体验一般，别抱太高期待。二刷意愿：否。', '0%', 58);
INSERT INTO `travel_review` VALUES (764, 'TR000764', '万笏朝天', '铜仁', '贵州', '周末短途', '冬季', 11, 6, 1544.00, '否', 5, '11月去的万笏朝天，和朋友出行。地点在铜仁，打车比较省心，现场人不算多。这次玩了6天，人均花费约1544元，历史文化气息浓。景点印象：据府志载：沿锦江顺流东下，右岸有一座山，下面丰大，上面尖削，其山巅突兀地生出一石柱，高高地直插云霄，四周已没有可陪衬的东西，其形其势就像上朝用的笏一样。古时的“金茎承露”也不足以来形容它的奇特。整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '2%', 46);
