INSERT INTO `travel_review` VALUES (773, 'TR000773', '擂鼓墩古墓群', '随州', '湖北', '周末短途', '夏季', 5, 3, 1267.00, '否', 3, '5月去的擂鼓墩古墓群，和朋友出行。地点在随州，公交换乘方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约1267元，拍照很出片。景点印象：在随州市城关西北2.5公里的擂鼓墩。擂鼓墩古为随国领地，北望桐柏，南面涡山（即大洪山），东临极水，山岭绵亘，古冢森森。曾侯乙系战国早期曾国君主，其墓营建于红砂岩坡之上，凿石为穴，墓扩面积220平方米，深近20米，停分四室，均以巨木镶隔。主…整体感受是还可以，避开高峰更好。二刷意愿：否。', '0%', 14);
INSERT INTO `travel_review` VALUES (774, 'TR000774', '二佛寺', '自贡', '四川', '城市漫游', '秋季', 7, 1, 802.00, '是', 2, '7月去的二佛寺，情侣出行。地点在自贡，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约802元，氛围感不错。景点印象：荣县二佛寺沿崖林立，造像上千尊，唐宋时名“浮图崖”，亦称千佛崖。因其众多佛像装金饰彩，阳光照射，金碧辉煌，故又称“金碧崖”。\n佛像为唐代开凿的弥勒坐佛，佛高5.8米，宽2.6米。左右龛壁上，刻有28小龛120尊造佛。整体感受是略失望，可考虑其他景点。二刷意愿：是。', '0%', 42);
INSERT INTO `travel_review` VALUES (775, 'TR000775', '古开福寺', '长沙', '湖南', '城市漫游', '春季', 12, 5, 1492.00, '是', 5, '12月去的古开福寺，一个人出行。地点在长沙，公交换乘方便，现场游客较多。这次玩了5天，人均花费约1492元，拍照很出片。景点印象：数数罗汉测凶吉，在大悲殿内转观音像，祈求心想事成。整体感受是特别满意，很推荐。二刷意愿：是。', '2%', 75);
INSERT INTO `travel_review` VALUES (776, 'TR000776', '司徒小镇', '晋城', '山西', '周末短途', '夏季', 4, 5, 1125.00, '否', 5, '4月去的司徒小镇，情侣出行。地点在晋城，公交换乘方便，现场人流量适中。这次玩了5天，人均花费约1125元，拍照很出片。景点印象：漫步古色古香的小镇，欣赏震撼人心的千人打铁花表演，感受穿越千年的山西味道。整体感受是挺惊喜，很推荐。二刷意愿：否。', '2%', 99);
