INSERT INTO `travel_review` VALUES (783, 'TR000783', '清远银盏谷水帘洞', '清远', '广东', '亲子出游', '秋季', 6, 1, 200.00, '否', 5, '6月去的清远银盏谷水帘洞，一个人出行。地点在清远，公交换乘方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约200元，历史文化气息浓。景点印象：银盏谷水帘洞具有《西游记》神话故事里花果山水帘洞般的神话色彩，国内首次发现。洞内山水相连，秀峰环抱，溪水涟涟，溪谷险峻，原始森林、瀑布群尽入眼底。当您徒步穿越水帘洞时，恍入仙境，顿时心旷神怡。洞内不时溢出的神秘感让您不断感受到大自…整体感受是特别满意，以后还会来。二刷意愿：否。', '0%', 69);
