INSERT INTO `travel_review` VALUES (850, 'TR000850', '金兰山', '信阳', '河南', '周末短途', '夏季', 5, 1, 442.00, '否', 4, '5月去的金兰山，一个人出行。地点在信阳，打车比较省心，现场人不算多。这次玩了1天，人均花费约442元，夜景表现很好。景点印象：金兰山国家森林公园，地处亚热带向暧温带过渡地带，是我国华东、华中、华北三大植物区系交汇处和我国动植物南迁北移的缓冲带，森林资源丰富，树木种类繁多。有森林面积3072公顷，森林覆盖率93.1%，植物种类2000多种，其中国家重点保护植物19种。有…整体感受是体验挺好，可以安排半天到一天。二刷意愿：否。', '0%', 60);
INSERT INTO `travel_review` VALUES (851, 'TR000851', '农团生态旅游景区', '自贡', '四川', '城市漫游', '夏季', 5, 3, 812.00, '是', 5, '5月去的农团生态旅游景区，一个人出行。地点在自贡，自驾停车需要提前规划，现场人不算多。这次玩了3天，人均花费约812元，历史文化气息浓。景点印象：农团生态旅游风景区地处自贡市区西南边缘，距自贡市区18公里，交通、通讯十分便利。风景区内均属深丘地貌，一般海拔400-480米之间，属岷江流域越溪河水系溜根河的发源地。乡内属大陆季风性气候，雨量充沛，无霜期长，湿润凉爽。多年平均气温17.1摄…整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 70);
INSERT INTO `travel_review` VALUES (852, 'TR000852', '雪乡文化展览馆', '牡丹江', '黑龙江', '深度游', '春季', 2, 1, 545.00, '否', 3, '2月去的雪乡文化展览馆，和朋友出行。地点在牡丹江，公交换乘方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约545元，历史文化气息浓。景点印象：雪乡文化展览馆展厅展出的就是中国雪乡的文明史，从海东盛国、龙兴边塞、关东血泪，一直讲到百年荣辱以及现今的生活。整体感受是体验一般，别抱太高期待。二刷意愿：否。', '0%', 50);
