INSERT INTO `travel_review` VALUES (866, 'TR000866', '马邑汉墓群', '朔州', '山西', '深度游', '冬季', 9, 1, 120.00, '是', 5, '9月去的马邑汉墓群，和家人出行。地点在朔州，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约120元，夜景表现很好。景点印象：是山西省重点文物保护单位，分布于朔州市城区四周20公里的范围内，此地汉代为重要关外军事重镇，戍边将士死后大都葬于此处，形成了密集的汉代墓葬群。目前已发掘古墓2200余座，出土文物17000件，大多保存于朔州博物馆内。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 77);
INSERT INTO `travel_review` VALUES (867, 'TR000867', '临沭县人民公园', '临沂', '山东', '城市漫游', '冬季', 9, 5, 1168.00, '是', 5, '9月去的临沭县人民公园，情侣出行。地点在临沂，公交换乘方便，现场高峰时段比较拥挤。这次玩了5天，人均花费约1168元，夜景表现很好。景点印象：周边配套比较齐全整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '0%', 90);
INSERT INTO `travel_review` VALUES (868, 'TR000868', '万笏朝天', '铜仁', '贵州', '亲子出游', '春季', 12, 1, 572.00, '否', 4, '12月去的万笏朝天，一个人出行。地点在铜仁，公交换乘方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约572元，夜景表现很好。景点印象：据府志载：沿锦江顺流东下，右岸有一座山，下面丰大，上面尖削，其山巅突兀地生出一石柱，高高地直插云霄，四周已没有可陪衬的东西，其形其势就像上朝用的笏一样。古时的“金茎承露”也不足以来形容它的奇特。整体感受是整体不错，周末来刚好。二刷意愿：否。', '2%', 76);
