INSERT INTO `travel_review` VALUES (872, 'TR000872', '哀牢山', '玉溪', '云南', '城市漫游', '冬季', 11, 3, 673.00, '是', 5, '11月去的哀牢山，一个人出行。地点在玉溪，地铁到达方便，现场人流量适中。这次玩了3天，人均花费约673元，氛围感不错。景点印象：野生动物生长繁衍的重要栖息地，堪称真正的“原始森林”，层层叠叠，弯弯曲曲，别有一番景色。整体感受是超出预期，很推荐。二刷意愿：是。', '5%', 74);
INSERT INTO `travel_review` VALUES (873, 'TR000873', '李冰陵', '德阳', '四川', '文化打卡', '春季', 12, 2, 654.00, '是', 5, '12月去的李冰陵，和朋友出行。地点在德阳，打车比较省心，现场游客较多。这次玩了2天，人均花费约654元，拍照很出片。景点印象：李冰和大禹一样，是因水而生的。\n大禹治水，历史太久远了，痕迹已成自然，而李冰的都江堰，朱李火堰，却赫然于世，年年月月造福于成都平原。\n李冰陵园在什邡洛水镇章山。2200多年前，已近晚年的李冰，累死在什邡洛水的治水工地上 。有专家考证，李…整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '0%', 78);
INSERT INTO `travel_review` VALUES (874, 'TR000874', '钟灵禅寺', '齐齐哈尔', '黑龙江', '拍照旅行', '春季', 2, 4, 1157.00, '否', 5, '2月去的钟灵禅寺，和朋友出行。地点在齐齐哈尔，自驾停车需要提前规划，现场人流量适中。这次玩了4天，人均花费约1157元，拍照很出片。景点印象：钟灵禅寺始建于1911年，位于齐齐哈尔境内，克东县昌盛乡。原名钟灵观，因缺乏道教神职人员，故改名为钟灵寺，现为佛事活动场所。\n整个庙宇建在绿荫之中，内有主殿1幢，大殿2重，配阁4座，占地6,000平方米，建筑面积600平方米，均为砖木结构，墙面…整体感受是特别满意，值得专门打卡。二刷意愿：否。', '0%', 100);
INSERT INTO `travel_review` VALUES (875, 'TR000875', '泗水塔', '南阳', '河南', '亲子出游', '秋季', 7, 1, 583.00, '否', 3, '7月去的泗水塔，一个人出行。地点在南阳，地铁到达方便，现场人不算多。这次玩了1天，人均花费约583元，拍照很出片。景点印象：泗洲塔又称泗水塔，位于唐河县城东南隅菩提寺旧址内。宋绍圣二年（1095年）建，高47.33米。底层坐落在台基上，南面辟一拱形门，第二至十层每层各辟1门。下均置砖雕斗拱，转角处有风铎，檐下为平座，塔内有塔心柱，柱之周围筑盘88旋石阶踏道，第一层…整体感受是中规中矩，别抱太高期待。二刷意愿：否。', '0%', 41);
