INSERT INTO `travel_review` VALUES (896, 'TR000896', '皖中奇石馆', '巢湖', '安徽', '城市漫游', '夏季', 4, 1, 372.00, '否', 5, '4月去的皖中奇石馆，情侣出行。地点在巢湖，自驾停车需要提前规划，现场人不算多。这次玩了1天，人均花费约372元，历史文化气息浓。景点印象：该馆系中国收藏家协会会员、青年画家王衍平创建。馆内收藏了灵壁石、无为军石、淮南龟纹石、歙县矾石、巢湖散兵石、六安锰石、巢湖斧劈石、皖南砂积石、石台钟乳石、庐江矾石、莹石等中外各地名石精品1000多件、300余吨。该馆还集知识性、趣味性为…整体感受是特别满意，值得专门打卡。二刷意愿：否。', '0%', 23);
INSERT INTO `travel_review` VALUES (897, 'TR000897', '春园海', '万宁', '海南', '周末短途', '夏季', 4, 4, 1545.00, '否', 5, '4月去的春园海，和朋友出行。地点在万宁，打车比较省心，现场人流量适中。这次玩了4天，人均花费约1545元，历史文化气息浓。景点印象：在春园海四周，可谓景观密集，特产丰富，特色鲜明。春园海湾由一条海成一级阶地形成，属小海泻湖湖岸第四纪堆积物。沿岸五岭横陈，岭间形成3个新月形海湾，春园海位于中间，东有大长岭，（清《万州志》称为旧林岭，或系古代旧有春园村而命名），蜿…整体感受是超出预期，很推荐。二刷意愿：否。', '0%', 125);
