INSERT INTO `travel_review` VALUES (912, 'TR000912', '小黑江森林公园', '普洱', '云南', '拍照旅行', '秋季', 7, 5, 1329.00, '是', 5, '7月去的小黑江森林公园，和朋友出行。地点在普洱，公交换乘方便，现场人不算多。这次玩了5天，人均花费约1329元，拍照很出片。景点印象：小黑江森林公园位于普洱县与景谷县交界处，经营面积6245公顷，属思茅地区卫国林业局经营区。多年来，由于卫国林业局重视森林资源的保护，小黑江林区保持了山长青、水长流的秀美景色，吸引了越来越多的游客。为了把小黑江林区建设成为思茅地区的旅游…整体感受是特别满意，以后还会来。二刷意愿：是。', '0%', 83);
