INSERT INTO `travel_review` VALUES (914, 'TR000914', '藏传教寺院', '张掖', '甘肃', '城市漫游', '春季', 12, 4, 1175.00, '否', 5, '12月去的藏传教寺院，和朋友出行。地点在张掖，自驾停车需要提前规划，现场人不算多。这次玩了4天，人均花费约1175元，历史文化气息浓。景点印象：藏传教寺院位于肃南裕固族自治县境内，北距张掖市65公里，是集石窟艺术、祁连山风光和裕固族风情于一体的旅游区。石窟由胜果寺、普光寺、千佛洞、金塔寺、上、中、下观音洞七处组成，共有70余处窟龛，始建于北凉。马蹄寺因传说中的天马在此落有马蹄…整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '0%', 48);
