INSERT INTO `travel_review` VALUES (938, 'TR000938', '马家大院', '晋中', '山西', '深度游', '秋季', 8, 1, 484.00, '否', 5, '8月去的马家大院，情侣出行。地点在晋中，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约484元，历史文化气息浓。景点印象：马家大院位于古城窑场街的北马家巷，是“平遥四大家族”之首、清代巨商马中选的故居,是清代建筑装饰风格的典范,是极富艺术魅力的民宅建筑群,被誉为“平遥第一大院”。整体感受是超出预期，以后还会来。二刷意愿：否。', '1%', 99);
