INSERT INTO `travel_review` VALUES (967, 'TR000967', '旅顺博物馆', '大连', '辽宁', '文化打卡', '冬季', 11, 2, 1019.00, '是', 4, '11月去的旅顺博物馆，一个人出行。地点在大连，打车比较省心，现场高峰时段比较拥挤。这次玩了2天，人均花费约1019元，氛围感不错。景点印象：馆藏陈列有新疆的古代文物，千年干尸、古代朝鲜、日本、印度的艺术品等，是旅顺必游景点之一。整体感受是还蛮满意，可以安排半天到一天。二刷意愿：是。', '5%', 58);
INSERT INTO `travel_review` VALUES (968, 'TR000968', '杰桑·索南达杰纪念碑', '玉树', '青海', '文化打卡', '春季', 12, 1, 252.00, '否', 4, '12月去的杰桑·索南达杰纪念碑，和朋友出行。地点在玉树，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约252元，夜景表现很好。景点印象：杰桑·索南达杰被誉为可可西里野生动物保护第一人，在可可西里无人区与偷猎者搏斗时丧生。为了纪念他，人们在可可西里保护区昆仑山口建立了纪念碑。整体感受是体验挺好，可以安排半天到一天。二刷意愿：否。', '12%', 44);
