INSERT INTO `travel_review` VALUES (979, 'TR000979', '南水水库', '韶关', '广东', '深度游', '夏季', 4, 5, 1071.00, '是', 4, '4月去的南水水库，一个人出行。地点在韶关，打车比较省心，现场人不算多。这次玩了5天，人均花费约1071元，拍照很出片。景点印象：南水水库位于乳源县城西南16公里处，是广东省第二大人工湖，南水湖水质晶莹透碧，沿岸青山连绵，瑶寨竹木楼掩映在绿树丛中。在水库西北一个面积约一万亩的半岛上，建有中国南方第一个狩猎场。整体感受是体验挺好，可以安排半天到一天。二刷意愿：是。', '3%', 47);
