INSERT INTO `travel_review` VALUES (989, 'TR000989', '马岭河峡谷', '黔西南', '贵州', '周末短途', '夏季', 4, 4, 882.00, '是', 5, '4月去的马岭河峡谷，一个人出行。地点在黔西南，地铁到达方便，现场人流量适中。这次玩了4天，人均花费约882元，氛围感不错。景点印象：马岭河峡谷幽深壮丽，瀑布众多，被称为“地球上最美丽的伤疤”。整体感受是超出预期，以后还会来。二刷意愿：是。', '68%', 90);
INSERT INTO `travel_review` VALUES (990, 'TR000990', '凤雏庵', '咸宁', '湖北', '城市漫游', '秋季', 6, 2, 397.00, '是', 5, '6月去的凤雏庵，一个人出行。地点在咸宁，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了2天，人均花费约397元，氛围感不错。景点印象：位于南屏山东南的金鸾山上。走近金鸾山，山门横额上“赤壁古风”几个大字赫然醒目。相传三国时庞统曾隐居于此。原建筑简陋，后世屡次扩建，但又迭遭兵焚。现存殿室数间，系清道光二十六年（1846年）重建，建国后曾维修，青砖灰瓦，甚为古朴。主室有…整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 96);
