INSERT INTO `travel_review` VALUES (997, 'TR000997', '甘肃省科学技术厅白银市人民政府共建孵化器', '白银', '甘肃', '周末短途', '秋季', 7, 1, 882.00, '否', 2, '7月去的甘肃省科学技术厅白银市人民政府共建孵化器，情侣出行。地点在白银，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约882元，历史文化气息浓。景点印象：整体环境还算干净整体感受是略失望，可考虑其他景点。二刷意愿：否。', '0%', 23);
INSERT INTO `travel_review` VALUES (998, 'TR000998', '包头敖伦苏木', '包头', '内蒙古', '深度游', '春季', 1, 7, 1669.00, '否', 4, '1月去的包头敖伦苏木，和朋友出行。地点在包头，公交换乘方便，现场游客较多。这次玩了7天，人均花费约1669元，夜景表现很好。景点印象：在达茂联合旗百灵庙镇东北约30公里处，有一座元代古城遗址，当地牧民称为“敖伦苏木”。这是全国重点文物保护单位，是元代很有势力的汪古部族的王府遗址。\n在茫茫的大漠草原上，远远地就能看到古城残垣断壁的高大建筑物的废墟，周围土地曾被开发的…整体感受是体验挺好，周末来刚好。二刷意愿：否。', '1%', 99);
