INSERT INTO `travel_review` VALUES (1072, 'TR001072', '卧鹿山效圣寺', '鞍山', '辽宁', '深度游', '夏季', 4, 4, 1127.00, '是', 5, '4月去的卧鹿山效圣寺，情侣出行。地点在鞍山，打车比较省心，现场游客较多。这次玩了4天，人均花费约1127元，夜景表现很好。景点印象：效圣寺位于岫岩城南22公里杨家堡镇松树秧村卧鹿山羊角峰下，俗称“老古庙”，是省内现存唯一大型石构古代庙宇。整个石庙建筑“石庙房、石佛像、石钟楼、石围墙”，令人叹为观止。1988年12月，效圣寺被列为省级文物保护单位。 效圣寺(老古庙)相传始…整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 85);
