INSERT INTO `travel_review` VALUES (1082, 'TR001082', '迎恩宫', '济源', '河南', '亲子出游', '冬季', 9, 2, 182.00, '否', 3, '9月去的迎恩宫，一个人出行。地点在济源，公交换乘方便，现场游客较多。这次玩了2天，人均花费约182元，历史文化气息浓。景点印象：位于市城区西北29公里的三官坪村北的迎恩宫，北依黛珠峰，西临小有河。相传，唐初紫微宫道士为迎接皇帝或圣旨而建，故名。\n宫座北向阳，为三进院落，依山趁势，就岩砌台，逐级升高，错落有致。现存古建筑有山门、祖师大殿、四圣殿、吕祖殿、三官殿…整体感受是中规中矩，按需选择。二刷意愿：否。', '0%', 60);
