INSERT INTO `travel_review` VALUES (1085, 'TR001085', '太极湖村', '宣城', '安徽', '城市漫游', '春季', 12, 6, 1789.00, '是', 4, '12月去的太极湖村，和家人出行。地点在宣城，自驾停车需要提前规划，现场游客较多。这次玩了6天，人均花费约1789元，夜景表现很好。景点印象：以砖雕门楼取胜的徽派古村，精细的砖雕能叠加到九层之多。 章氏宗祠木雕精美，里面的明代蟠龙香亭上，六条蟠龙栩栩如生。 整个村庄像幅太极图，4月可赏油菜花。整体感受是整体不错，推荐来看看。二刷意愿：是。', '5%', 34);
