INSERT INTO `travel_review` VALUES (1155, 'TR001155', '古湖', '内江', '四川', '拍照旅行', '春季', 2, 3, 1027.00, '是', 5, '2月去的古湖，情侣出行。地点在内江，公交换乘方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约1027元，氛围感不错。景点印象：隆昌古湖风景区位于隆昌县西部，它是以古宇庙为主体的风景名胜区，包括湖区、圣灯山、金鹅镇三景区10余个景点，总面积61平方公里。景区有峭壁、怪石、瀑布溶洞、寺庙、牌坊等风景名胜。古湖位于隆昌县城西南2公里，在楼峰山与圣灯山之间，湖面5平方…整体感受是特别满意，以后还会来。二刷意愿：是。', '0%', 57);
