INSERT INTO `travel_review` VALUES (1213, 'TR001213', '连康山保护区', '信阳', '河南', '文化打卡', '夏季', 4, 2, 311.00, '否', 5, '4月去的连康山保护区，一个人出行。地点在信阳，地铁到达方便，现场人不算多。这次玩了2天，人均花费约311元，氛围感不错。景点印象：保护区为一南北长、东西窄的起伏连绵的低山丘陵，相对高度250―300米之间，山下部陡峭，上部平缓，一般坡度为30―40度之间。气候冬季寒冷干燥，夏季炎热多雨，年均温15.1℃，1月均温――2℃，7月均温27.6℃，极端低温―17.3℃，极端高温42.5℃.大于…整体感受是特别满意，以后还会来。二刷意愿：否。', '0%', 104);
