INSERT INTO `travel_review` VALUES (1236, 'TR001236', '乐山岩墓', '乐山', '四川', '亲子出游', '秋季', 7, 6, 1473.00, '是', 4, '7月去的乐山岩墓，情侣出行。地点在乐山，公交换乘方便，现场人不算多。这次玩了6天，人均花费约1473元，夜景表现很好。景点印象：位于乐山市郊柿子湾、麻浩、萧坝、蕴真洞、车子等地。自东汉至南北朝时期在今四川流行的一种墓葬，前人称为“蛮子洞”。四川岩墓以乐山市为最集中。岩墓依天然岩石凿成，宽敞如室，高低参错，高的难以攀登，低的埋藏地下。大的深约90余米，小的约6…整体感受是整体不错，推荐来看看。二刷意愿：是。', '0%', 70);
