INSERT INTO `travel_review` VALUES (1306, 'TR001306', '莎车王墓', '喀什', '新疆', '周末短途', '春季', 12, 2, 556.00, '否', 4, '12月去的莎车王墓，和朋友出行。地点在喀什，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约556元，氛围感不错。景点印象：陵墓占地1050平方米，虽历经数百年，其壁饰图案、建筑用料及结构布局，仍清晰如新。近年来，当地政府和群众，又专门为阿曼尼莎汗王妃另外修建了陵墓，其高大、精美，均超出了原王陵。它位于县城中汉城、回城之间，至今瞻仰者不绝于途。整体感受是整体不错，推荐来看看。二刷意愿：否。', '0%', 96);
