INSERT INTO `travel_review` VALUES (1336, 'TR001336', '念湖', '曲靖', '云南', '文化打卡', '春季', 1, 2, 582.00, '否', 5, '1月去的念湖，一个人出行。地点在曲靖，地铁到达方便，现场游客较多。这次玩了2天，人均花费约582元，夜景表现很好。景点印象：念湖是位于曲靖市会泽县大桥乡和昭通交界处的黑颈鹤自然保护区。它原本是云南高原中一个不起眼的乡镇。一个颇具时代特征的名字，叫“跃进水库”又名“念湖”[1] 。整体感受是超出预期，很推荐。二刷意愿：否。', '5%', 84);
