INSERT INTO `travel_review` VALUES (1340, 'TR001340', '湖田古窑遗址', '景德镇', '江西', '深度游', '春季', 2, 2, 487.00, '否', 5, '2月去的湖田古窑遗址，和家人出行。地点在景德镇，打车比较省心，现场游客较多。这次玩了2天，人均花费约487元，拍照很出片。景点印象：湖田窑是我国宋、元两代各大制瓷规模最大、延续烧造时间最长、生产的瓷器最精美的古代窑场。遗址保存的遗物非常丰富，历代古窑遍地。整体感受是超出预期，以后还会来。二刷意愿：否。', '10%', 84);
