INSERT INTO `travel_review` VALUES (1433, 'TR001433', '板壁岩', '神农架', '湖北', '深度游', '冬季', 11, 1, 80.00, '是', 5, '11月去的板壁岩，和家人出行。地点在神农架，公交换乘方便，现场游客较多。这次玩了1天，人均花费约80元，夜景表现很好。景点印象：原始森林中的一片石林，怪石林立，姿态各异。 神农架“野人”出没的地方，说不定可以与“野人”兄弟不期而遇。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '26%', 77);
