INSERT INTO `travel_review` VALUES (1498, 'TR001498', '雄县', '雄安新区', '河北', '深度游', '秋季', 6, 2, 433.00, '否', 5, '6月去的雄县，一个人出行。地点在雄安新区，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了2天，人均花费约433元，氛围感不错。景点印象：雄县隶属于河北省保定市，地处冀中平原，北距首都108公里，东距天津100公里，西距保定70公里，东依霸州市，南部、东南部隔大清河与任丘市、文安县相望，西南隔白洋淀与安新县相连，西部与容城县相接，西北与高碑店市毗邻，东北与固安县接壤。整体感受是超出预期，以后还会来。二刷意愿：否。', '0%', 104);
