INSERT INTO `travel_review` VALUES (1598, 'TR001598', '罗汉圣地', '鞍山', '辽宁', '城市漫游', '冬季', 11, 1, 306.00, '是', 5, '11月去的罗汉圣地，和家人出行。地点在鞍山，公交换乘方便，现场游客较多。这次玩了1天，人均花费约306元，夜景表现很好。景点印象：座落于辽宁鞍山\"二一九\"公园湖畔，东山风景区内。与著名的玉佛苑合璧为一处，构成完整的佛教文化场所，又是一处综合性旅游场所。其外部环境以古代建筑、古典园林为主体，整个布局雄伟壮观、气势恢宏，亭、台、楼、阁、殿、宇错落有致，金壁生辉。园…整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '12%', 64);
