INSERT INTO `travel_review` VALUES (1600, 'TR001600', '华八井', '东营', '山东', '文化打卡', '秋季', 6, 1, 381.00, '是', 5, '6月去的华八井，情侣出行。地点在东营，公交换乘方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约381元，拍照很出片。景点印象：华八井是在燕山以南，太行山以东 ，大别山以北，渤海湾以西40万平方公里的华北平原内进行石油资源普查的第八口探井。位于东营市东营区东营村。1961年4月16日，该井首次用9毫米油嘴求产，获日产8.1吨工业油流，成为当时东部渤海湾地区第一口见原油的…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 74);
