INSERT INTO `travel_review` VALUES (1604, 'TR001604', '陆九渊之墓', '抚州', '江西', '周末短途', '冬季', 9, 1, 287.00, '否', 5, '9月去的陆九渊之墓，一个人出行。地点在抚州，打车比较省心，现场人流量适中。这次玩了1天，人均花费约287元，氛围感不错。景点印象：座落于金溪县陆坊乡青田村东山上，1957年被列为江西省省级保护文物。陆九渊，字子静，号象山，陆坊乡青田人，是南宋时与朱熹双峰对峙的理学大师、哲学家、教育家，在历史上有深远影响。其理学又称“心学”，提出“心即理”、“宇宙便是吾心，吾心便…整体感受是挺惊喜，以后还会来。二刷意愿：否。', '0%', 58);
