INSERT INTO `travel_review` VALUES (1626, 'TR001626', '北湖公园', '昌吉', '新疆', '拍照旅行', '冬季', 10, 4, 1173.00, '是', 4, '10月去的北湖公园，和家人出行。地点在昌吉，打车比较省心，现场高峰时段比较拥挤。这次玩了4天，人均花费约1173元，夜景表现很好。景点印象：新疆石河子昌吉北湖位于石河子市北约16千米，沿204省道可到达，交通便利。地理坐标北纬44°25′-44°27′,东经85°4′-86°1′,海拔400米。 1985年，石河子人民政府在库区建立旅游区，命名为北湖公园。先后投入1000余万元，建起了长廊、亭台、水上…整体感受是整体不错，周末来刚好。二刷意愿：是。', '0%', 67);
