INSERT INTO `travel_review` VALUES (1635, 'TR001635', '陇瑞自然保护区', '崇左', '广西', '拍照旅行', '秋季', 6, 7, 1952.00, '是', 5, '6月去的陇瑞自然保护区，情侣出行。地点在崇左，地铁到达方便，现场高峰时段比较拥挤。这次玩了7天，人均花费约1952元，氛围感不错。景点印象：保护区地面峰峦星罗棋布，每平方公里有山峰多达80多座，一般的也有20多座，海拔均在400-600米。有的山峰重迭成峰 ，而且山中溶洞繁多，洞内山水厅奇观待于开发旅游。\n保护区植被，属北热带石灰岩山地常绿雨季林，植物种类繁多，计有166科673属1282…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 119);
