INSERT INTO `travel_review` VALUES (1685, 'TR001685', '中国贡嘎山海螺沟', '甘孜藏族自治州', '四川', '拍照旅行', '夏季', 3, 4, 857.00, '是', 4, '3月去的中国贡嘎山海螺沟，和朋友出行。地点在甘孜藏族自治州，打车比较省心，现场人流量适中。这次玩了4天，人均花费约857元，拍照很出片。景点印象：可近距离接触冰湖、冰洞、冰裂隙、冰阶梯等多种景观，令人称奇。整体感受是体验挺好，推荐来看看。二刷意愿：是。', '12%', 74);
INSERT INTO `travel_review` VALUES (1686, 'TR001686', '梅花山', '龙岩', '福建', '拍照旅行', '冬季', 11, 2, 638.00, '是', 5, '11月去的梅花山，情侣出行。地点在龙岩，地铁到达方便，现场人流量适中。这次玩了2天，人均花费约638元，历史文化气息浓。景点印象：龙岩梅花山自然保护区地处武夷山脉南段东南坡与戴云山之间的玳瑁山主体部分，这里山峦耸峙，绿海无边，层林叠翠，荟萃了许多珍贵的生物资源与物种，有“神奇的宝山”“动植物资源基因库”之美称。整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 51);
