INSERT INTO `travel_review` VALUES (1688, 'TR001688', '龙园', '天水', '甘肃', '城市漫游', '秋季', 8, 1, 80.00, '否', 5, '8月去的龙园，一个人出行。地点在天水，打车比较省心，现场游客较多。这次玩了1天，人均花费约80元，历史文化气息浓。景点印象：位于渭水之滨，文山之阴，坐西面东，占地一十三亩。主体成纪殿，乃歇山重檐九开间明清式建筑。长四十五米、高二十七米，进深一十三米六。整体感受是超出预期，以后还会来。二刷意愿：否。', '0%', 111);
