INSERT INTO `travel_review` VALUES (1697, 'TR001697', '紫荆山公园', '平凉', '甘肃', '文化打卡', '冬季', 11, 3, 643.00, '否', 5, '11月去的紫荆山公园，一个人出行。地点在平凉，公交换乘方便，现场人不算多。这次玩了3天，人均花费约643元，历史文化气息浓。景点印象：紫荆山，平地突兀于庄浪县城之中，因山阴遍植紫荆树而得名。历为山城形胜，1986年被县政府辟为公园。紫荆山游览区面积1.5万平方米，集自然景观与人文景观于一体，山势玲珑剔透，雄浑壮观，环境幽雅，令人陶醉。“洛河横烟”、“紫荆香霭”等景观及…整体感受是超出预期，值得专门打卡。二刷意愿：否。', '0%', 114);
