INSERT INTO `travel_review` VALUES (1699, 'TR001699', '张北坝上草原', '张家口', '河北', '深度游', '秋季', 7, 2, 451.00, '是', 5, '7月去的张北坝上草原，和朋友出行。地点在张家口，打车比较省心，现场人流量适中。这次玩了2天，人均花费约451元，氛围感不错。景点印象：蓝天、白云、草地和羊群完美结合，在草原上走走看看，拍拍照片。 白天在草原上骑马，晚上参加篝火晚会，吃着烤全羊。 参加夏季张北草原音乐节，享受摇滚音乐的魅力。整体感受是特别满意，很推荐。二刷意愿：是。', '0%', 80);
