INSERT INTO `travel_review` VALUES (1762, 'TR001762', '奥依塔克风景区', '喀什', '新疆', '城市漫游', '春季', 2, 3, 866.00, '否', 4, '2月去的奥依塔克风景区，一个人出行。地点在喀什，打车比较省心，现场人流量适中。这次玩了3天，人均花费约866元，氛围感不错。景点印象：这里高山险峻，冰峰林立，大河滔滔，古木森森，莺飞蝶舞，芳草萎萎整体感受是体验挺好，推荐来看看。二刷意愿：否。', '4%', 119);
