INSERT INTO `travel_review` VALUES (1764, 'TR001764', '木梨硔', '黄山', '安徽', '拍照旅行', '春季', 2, 1, 674.00, '否', 3, '2月去的木梨硔，情侣出行。地点在黄山，地铁到达方便，现场人不算多。这次玩了1天，人均花费约674元，拍照很出片。景点印象：黄山海拔最高的村落，极佳的拍摄点，美似天上人间。整体感受是体验一般，别抱太高期待。二刷意愿：否。', '0%', 78);
INSERT INTO `travel_review` VALUES (1765, 'TR001765', '龙潭', '达州', '四川', '亲子出游', '冬季', 9, 4, 1251.00, '否', 5, '9月去的龙潭，情侣出行。地点在达州，地铁到达方便，现场人不算多。这次玩了4天，人均花费约1251元，拍照很出片。景点印象：位于八台山东侧，从上崩口到下崩口河段长10km，上崩口的右侧支流抠壁子沟，发源于八台山的东北角，长约6km，沟谷两侧是原始森林。龙潭河景区风光秀丽幽雅，景物丰富多彩，融山景、峰景、谷景、河景、瀑景、洞景、生景以及村景于一体。\n从上崩口至下…整体感受是特别满意，很推荐。二刷意愿：否。', '0%', 112);
