INSERT INTO `travel_review` VALUES (1790, 'TR001790', '大雾岭', '茂名', '广东', '亲子出游', '秋季', 7, 1, 304.00, '否', 4, '7月去的大雾岭，和家人出行。地点在茂名，自驾停车需要提前规划，现场人流量适中。这次玩了1天，人均花费约304元，历史文化气息浓。景点印象：大雾岭旅游区地处茂名市北部，离信宜城区38公里，地跨信宜、高州两地。大雾岭由云开山脉以及数十座海拔1000米以上的山峰组成，群山连绵不绝，高耸入云，其中海拔1500以上的山峰就有29座，是集生态保护、科学研究、旅游度假、高山疗养为一体的森林公…整体感受是整体不错，可以安排半天到一天。二刷意愿：否。', '0%', 95);
