INSERT INTO `travel_review` VALUES (1800, 'TR001800', '金凤山', '雅安', '四川', '城市漫游', '夏季', 3, 5, 1000.00, '否', 5, '3月去的金凤山，一个人出行。地点在雅安，打车比较省心，现场人不算多。这次玩了5天，人均花费约1000元，拍照很出片。景点印象：金凤山公园在雅安市城区旁，以金凤寺和高颐墓阙为主要景点。金凤寺始建于唐初，重建和扩建于明清，寺庙掩映在葱葱苍翠之中，环境幽雅，占地1万平方米。天王、弥勒、大雄、观音四殿和罗汉堂建筑规模宏大，是千年古刹。整体感受是超出预期，值得专门打卡。二刷意愿：否。', '0%', 78);
