INSERT INTO `travel_review` VALUES (1806, 'TR001806', '卧鹿山效圣寺', '鞍山', '辽宁', '亲子出游', '秋季', 6, 1, 676.00, '是', 5, '6月去的卧鹿山效圣寺，一个人出行。地点在鞍山，公交换乘方便，现场游客较多。这次玩了1天，人均花费约676元，氛围感不错。景点印象：效圣寺位于岫岩城南22公里杨家堡镇松树秧村卧鹿山羊角峰下，俗称“老古庙”，是省内现存唯一大型石构古代庙宇。整个石庙建筑“石庙房、石佛像、石钟楼、石围墙”，令人叹为观止。1988年12月，效圣寺被列为省级文物保护单位。 效圣寺(老古庙)相传始…整体感受是超出预期，值得专门打卡。二刷意愿：是。', '0%', 112);
