INSERT INTO `travel_review` VALUES (1829, 'TR001829', '浆水泉', '济南', '山东', '城市漫游', '冬季', 11, 3, 894.00, '是', 5, '11月去的浆水泉，一个人出行。地点在济南，打车比较省心，现场人不算多。这次玩了3天，人均花费约894元，氛围感不错。景点印象：浆水泉公园在回龙山、老虎山脚下，因有济南七十二名泉之一的浆水泉坐落在回龙山脚下便命名为浆水泉公园。乘坐49路公共汽车到浆水泉下车，再步行300米就到达浆水泉公园。整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 83);
INSERT INTO `travel_review` VALUES (1830, 'TR001830', '鄂豫皖苏区首府烈士陵园', '信阳', '河南', '拍照旅行', '春季', 2, 5, 1754.00, '是', 5, '2月去的鄂豫皖苏区首府烈士陵园，一个人出行。地点在信阳，地铁到达方便，现场人不算多。这次玩了5天，人均花费约1754元，夜景表现很好。景点印象：鄂豫皖苏区革命烈士陵园建于1957年、占地330亩由大门、烈士浮雕墙、烈士纪念碑、烈士纪念堂、革命斗争史陈列室、吴焕先半身塑像、烈士纪念亭、烈士墓地八大部分组成。\n大门 为现代建筑，园名由原国家主席李先念亲笔题写。\n烈士浮雕墙 用花岗岩雕塑…整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 69);
