INSERT INTO `travel_review` VALUES (1862, 'TR001862', '黑水河景区', '崇左', '广西', '拍照旅行', '春季', 2, 1, 678.00, '否', 5, '2月去的黑水河景区，和家人出行。地点在崇左，公交换乘方便，现场人不算多。这次玩了1天，人均花费约678元，夜景表现很好。景点印象：两岸怪石嶙峋，河水相映成“黛”色，非常独特。整体感受是挺惊喜，以后还会来。二刷意愿：否。', '3%', 94);
