INSERT INTO `travel_review` VALUES (1864, 'TR001864', '乌鲁瓦提水利枢纽工程', '和田', '新疆', '亲子出游', '春季', 1, 4, 990.00, '是', 5, '1月去的乌鲁瓦提水利枢纽工程，和家人出行。地点在和田，打车比较省心，现场高峰时段比较拥挤。这次玩了4天，人均花费约990元，氛围感不错。景点印象：乌鲁瓦提水利枢纽工程位于昆仑山南麓的喀拉喀什河上游山口处、和田县浪如乡境内。距和田市71公里，有泊油路和砂石路可达。属于山谷拦河水库，具有灌溉、防洪、发电、养鱼、生态保护及旅游等多，\n该枢纽工程由主坝及副坝、右岸开启式岸边溢洪道、泄…整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 96);
