INSERT INTO `travel_review` VALUES (1866, 'TR001866', '东林书院', '无锡', '江苏', '亲子出游', '秋季', 6, 4, 1039.00, '是', 5, '6月去的东林书院，和朋友出行。地点在无锡，打车比较省心，现场人流量适中。这次玩了4天，人均花费约1039元，历史文化气息浓。景点印象：寻找东林党“风声雨声读书声声声入耳”的对联，感受书香气息。整体感受是挺惊喜，很推荐。二刷意愿：是。', '17%', 124);
INSERT INTO `travel_review` VALUES (1867, 'TR001867', '蝴蝶泉', '大理', '云南', '亲子出游', '冬季', 9, 1, 460.00, '否', 5, '9月去的蝴蝶泉，一个人出行。地点在大理，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约460元，历史文化气息浓。景点印象：因为老电影《五朵金花》闻名，一汪碧绿的泉水美得动人心魄。整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '12%', 86);
INSERT INTO `travel_review` VALUES (1868, 'TR001868', '西溪国家湿地公园', '杭州', '浙江', '亲子出游', '春季', 2, 5, 1693.00, '否', 4, '2月去的西溪国家湿地公园，和家人出行。地点在杭州，打车比较省心，现场人不算多。这次玩了5天，人均花费约1693元，夜景表现很好。景点印象：“杭州之肾”，坐船漫游芦苇荡、寻迹《非诚勿扰》取景处。整体感受是整体不错，可以安排半天到一天。二刷意愿：否。', '23%', 63);
INSERT INTO `travel_review` VALUES (1869, 'TR001869', '红色娘子军雕像', '琼海', '海南', '文化打卡', '春季', 2, 3, 908.00, '是', 5, '2月去的红色娘子军雕像，和家人出行。地点在琼海，公交换乘方便，现场人不算多。这次玩了3天，人均花费约908元，历史文化气息浓。景点印象：位于琼海市南门的街心公园，于1985年8月1日落成揭幕。雕像由花岗石雕刻而成，坐北向南，高3．7米，连底座总高6．8米。座基石板铺设，四周呈六角形，围以石栏杆，占地面积40平方米。雕像后面是园林花圃等。红色娘子军纪念雕像将红军女战士脚穿草鞋、…整体感受是挺惊喜，很推荐。二刷意愿：是。', '2%', 97);
