INSERT INTO `travel_review` VALUES (1875, 'TR001875', '于国故城', '焦作', '河南', '亲子出游', '冬季', 10, 3, 1045.00, '是', 5, '10月去的于国故城，和家人出行。地点在焦作，自驾停车需要提前规划，现场人流量适中。这次玩了3天，人均花费约1045元，拍照很出片。景点印象：于国故城位于沁阳县西北15公里于邰村东。于国是商代鄂侯封地。西周时期，鄂侯南迁，周武王将此地分封给其子于叔。《史记》徐广注、《水经注》、《河内县志》等均有记载。现遗址仅存北墙，东西长820米，宽17-22米，高2-7米。目前，对该遗址尚未进行…整体感受是特别满意，很推荐。二刷意愿：是。', '0%', 57);
