INSERT INTO `travel_review` VALUES (1920, 'TR001920', '夏河县', '临夏', '甘肃', '拍照旅行', '夏季', 3, 2, 907.00, '否', 3, '3月去的夏河县，和朋友出行。地点在临夏，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约907元，夜景表现很好。景点印象：夏河县地处甘肃省西南部、甘南藏族自治州西北部，总土地面积6274平方公里,海拔在2200----3600米之间。气候属寒冷湿润类型，高原大陆性气候特点比较明显。平均气温2.6℃，平均降水量516MM，平均无霜期56天，全年日照时间为2296小时。全县共辖11个乡3…整体感受是还可以，别抱太高期待。二刷意愿：否。', '61%', 75);
