INSERT INTO `travel_review` VALUES (1954, 'TR001954', '龙鹄山', '眉山', '四川', '深度游', '秋季', 8, 1, 484.00, '是', 5, '8月去的龙鹄山，和朋友出行。地点在眉山，打车比较省心，现场人不算多。这次玩了1天，人均花费约484元，氛围感不错。景点印象：龙鹄山，距丹棱县城约3公里。唐代名\"龙鹤山\"，自南宋孝宗皇帝手书\"龙鹄山\"三字赐史学家李焘后更名。龙鹄山山势奇特，恰似一个巍巍巨人，端坐于环绕的群山之中，有人说它像莲台打坐的佛祖，左手拈决，右手抚膝，神态肃穆。据当地人说，足有48座\"磕头…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 72);
