INSERT INTO `travel_review` VALUES (2023, 'TR002023', '舍利宝塔', '聊城', '山东', '拍照旅行', '冬季', 10, 1, 834.00, '否', 3, '10月去的舍利宝塔，情侣出行。地点在聊城，打车比较省心，现场人不算多。这次玩了1天，人均花费约834元，氛围感不错。景点印象：舍利宝塔建于明万历三十九年（1611年）。清乾隆五十年张度纂《临清州志》载：州人大司空柳佐起建‘舍利宝塔’，九年乃成。整体感受是中规中矩，别抱太高期待。二刷意愿：否。', '20%', 55);
