INSERT INTO `travel_review` VALUES (2027, 'TR002027', '丹阳王墓', '朔州', '山西', '深度游', '冬季', 11, 3, 952.00, '否', 4, '11月去的丹阳王墓，和朋友出行。地点在朔州，打车比较省心，现场人不算多。这次玩了3天，人均花费约952元，夜景表现很好。景点印象：丹阳王墓位于怀仁县城北4公里的大运公路边。《怀仁县志》记载墓主人是丹阳王叔孙建，但无确凿史料及出土文物为证。建造年代当是北魏无疑。\n该墓分墓道、甬道、前室、后室和东西侧室。墓室平面均呈弧边长方形，四角攒尖顶，墓室高7．2米，墓室面积…整体感受是体验挺好，周末来刚好。二刷意愿：否。', '0%', 39);
