INSERT INTO `travel_review` VALUES (2116, 'TR002116', '云海波涛', '铜仁', '贵州', '城市漫游', '秋季', 7, 1, 350.00, '是', 4, '7月去的云海波涛，和家人出行。地点在铜仁，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约350元，夜景表现很好。景点印象：从金顶远望，白云无际，浓密处如堆积的新絮,稀疏时象漂洗的轻纱，风起云涌如汹？ヅ炫鹊耐蚯悴ㄌ巍Ｊ币？时现的山峰，恰似大海中的小岛。云波扑面而来，四周白范茫一片，使人飘飘若仙，清人诗云相会处，凭空移步作神仙。整体感受是体验挺好，可以安排半天到一天。二刷意愿：是。', '2%', 99);
INSERT INTO `travel_review` VALUES (2117, 'TR002117', '福缘佛道', '濮阳', '河南', '亲子出游', '春季', 1, 3, 770.00, '否', 2, '1月去的福缘佛道，和家人出行。地点在濮阳，地铁到达方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约770元，氛围感不错。景点印象：景点本身有一定特色整体感受是体验偏一般，不建议高峰来。二刷意愿：否。', '0%', 47);
INSERT INTO `travel_review` VALUES (2118, 'TR002118', '念湖', '曲靖', '云南', '周末短途', '春季', 12, 2, 708.00, '否', 5, '12月去的念湖，情侣出行。地点在曲靖，公交换乘方便，现场人不算多。这次玩了2天，人均花费约708元，历史文化气息浓。景点印象：念湖是位于曲靖市会泽县大桥乡和昭通交界处的黑颈鹤自然保护区。它原本是云南高原中一个不起眼的乡镇。一个颇具时代特征的名字，叫“跃进水库”又名“念湖”[1] 。整体感受是超出预期，以后还会来。二刷意愿：否。', '5%', 120);
