INSERT INTO `travel_review` VALUES (2142, 'TR002142', '白水台', '迪庆', '云南', '拍照旅行', '夏季', 5, 2, 410.00, '是', 3, '5月去的白水台，情侣出行。地点在迪庆，地铁到达方便，现场人不算多。这次玩了2天，人均花费约410元，拍照很出片。景点印象：白水台是纳西东巴教的圣地，层层叠叠的白色华台，仿佛一片白色的梯田，非常壮观。整体感受是还可以，避开高峰更好。二刷意愿：是。', '4%', 67);
INSERT INTO `travel_review` VALUES (2143, 'TR002143', '沙面', '广州', '广东', '亲子出游', '秋季', 6, 4, 1242.00, '是', 5, '6月去的沙面，情侣出行。地点在广州，打车比较省心，现场人流量适中。这次玩了4天，人均花费约1242元，历史文化气息浓。景点印象：众多欧陆风情的建筑，超级适合拍照的地方，也十分适合漫步其间。整体感受是超出预期，很推荐。二刷意愿：是。', '30%', 88);
INSERT INTO `travel_review` VALUES (2144, 'TR002144', '香加', '海西', '青海', '亲子出游', '秋季', 6, 2, 338.00, '是', 5, '6月去的香加，和朋友出行。地点在海西，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了2天，人均花费约338元，夜景表现很好。景点印象：在都兰垭口西64公里的地方，有一座小镇叫香日德。从这里弯向南就可进入布尔汗布达山腹地，也是进入巴隆野生动物保护区的一条通道。香加河谷地带的南面就是布尔汗布达山脉，有常年不化的雪峰，发源于布尔汗布达山脉和果洛州的冬给措那湖的托索河流经…整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '0%', 61);
INSERT INTO `travel_review` VALUES (2145, 'TR002145', '苏铁自然保护区', '攀枝花', '四川', '深度游', '夏季', 4, 1, 435.00, '是', 5, '4月去的苏铁自然保护区，一个人出行。地点在攀枝花，公交换乘方便，现场游客较多。这次玩了1天，人均花费约435元，历史文化气息浓。景点印象：主要保护对象是攀枝花苏铁这一珍稀濒危植物及其生态环境。\n攀枝花苏铁是1971年发现的苏铁新种，1981年才正式定名，1984年被列入我国第一批珍稀濒危保护植物名录，攀枝花苏铁对于研究我国横断山脉植物区系的发生和发展，以及古生物、古生态、古气候…整体感受是超出预期，值得专门打卡。二刷意愿：是。', '3%', 53);
INSERT INTO `travel_review` VALUES (2146, 'TR002146', '甘露寺', '镇江', '江苏', '周末短途', '冬季', 10, 3, 1095.00, '是', 4, '10月去的甘露寺，和朋友出行。地点在镇江，自驾停车需要提前规划，现场游客较多。这次玩了3天，人均花费约1095元，历史文化气息浓。景点印象：在此回顾三国中“赔了夫人又折兵”的历史典故。整体感受是体验挺好，可以安排半天到一天。二刷意愿：是。', '0%', 56);
INSERT INTO `travel_review` VALUES (2147, 'TR002147', '伊犁老城喀赞其民俗旅游区', '伊犁', '新疆', '文化打卡', '春季', 12, 1, 443.00, '否', 5, '12月去的伊犁老城喀赞其民俗旅游区，和朋友出行。地点在伊犁，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约443元，氛围感不错。景点印象：喀赞其民俗旅游区是北疆唯一一个大型原生态以反映维吾尔族风情为主的人文景区。整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '0%', 90);
INSERT INTO `travel_review` VALUES (2148, 'TR002148', '舒兰森林公园', '吉林市', '吉林', '亲子出游', '冬季', 11, 2, 507.00, '否', 5, '11月去的舒兰森林公园，和朋友出行。地点在吉林市，公交换乘方便，现场人流量适中。这次玩了2天，人均花费约507元，夜景表现很好。景点印象：舒兰市森林公园旅游园区为吉林市级旅游经济开发区，建于1997年5月，总占地面积120公顷，其中绿地面积占90％以上。森林公园东靠万寿山，南接南九山，西依红石山，北与北九山相望，故称九龙宝地。据文书记载，清乾隆年间，乾隆皇帝东巡吉林时，曾到过…整体感受是挺惊喜，很推荐。二刷意愿：否。', '0%', 100);
INSERT INTO `travel_review` VALUES (2149, 'TR002149', '二龙湖古城遗址', '通化', '吉林', '拍照旅行', '夏季', 4, 2, 759.00, '是', 5, '4月去的二龙湖古城遗址，情侣出行。地点在通化，地铁到达方便，现场游客较多。这次玩了2天，人均花费约759元，氛围感不错。景点印象：二龙湖古城遗址是战国时期最北部的边城，该遗址也是吉林省目前发现的年代最早的一座古城遗址。有关专家认为，它的发现不仅把燕国的北部疆域向北推进了近一个纬度(约一百多公里)，也把中原政权对东北腹地的开发推前到公元前三世纪，对研究当时东北地…整体感受是特别满意，很推荐。二刷意愿：是。', '20%', 61);
INSERT INTO `travel_review` VALUES (2150, 'TR002150', '新田公园', '汕尾', '广东', '拍照旅行', '夏季', 5, 2, 769.00, '是', 5, '5月去的新田公园，一个人出行。地点在汕尾，自驾停车需要提前规划，现场人流量适中。这次玩了2天，人均花费约769元，夜景表现很好。景点印象：陆河新田公园位于新田圩麻公山，陆河县新田镇措资金300多万元，在丰山村兴建占地200多亩的新田文化公园，是村民休闲娱乐、开展文体活动提供好去处。目前建设好的有观光塔、文体活动广场，陆河新田文化公园落成总投资600万元。新田文化公园大门的对…整体感受是特别满意，以后还会来。二刷意愿：是。', '0%', 134);
