INSERT INTO `travel_review` VALUES (2185, 'TR002185', '庙子沟遗址', '乌兰察布', '内蒙古', '周末短途', '秋季', 7, 2, 811.00, '否', 4, '7月去的庙子沟遗址，一个人出行。地点在乌兰察布，打车比较省心，现场人不算多。这次玩了2天，人均花费约811元，历史文化气息浓。景点印象：庙子沟遗址是目前内蒙古中南部地区发掘面积最大、遗迹保存最完整、出土遗物最为丰富的遗址。它为人们了解新石器时代晚期内蒙古地区的文化提供了大量的史料基础，而且它突然消失的文明更引起了考古工作者的兴趣。整体感受是体验挺好，可以安排半天到一天。二刷意愿：否。', '0%', 85);
