INSERT INTO `travel_review` VALUES (2192, 'TR002192', '柏枧山', '宣城', '安徽', '周末短途', '春季', 2, 1, 80.00, '否', 4, '2月去的柏枧山，和家人出行。地点在宣城，自驾停车需要提前规划，现场游客较多。这次玩了1天，人均花费约80元，氛围感不错。景点印象：柏枧山乃黄山余脉，主峰海拔999米，位于宣州区境内，离市区约20公里，景区面积达80平方公里。《辞源》称其“溪谷深邃，峰岩回曲，山水秀美，甲于江南”。\n这里山水田园美不胜收。雄奇的山川、幽深的峡谷、茂密的森林、珍奇的禽兽、美丽的河流、广阔…整体感受是还蛮满意，周末来刚好。二刷意愿：否。', '0%', 36);
