INSERT INTO `travel_review` VALUES (2204, 'TR002204', '黑松林', '临沂', '山东', '拍照旅行', '冬季', 11, 5, 1427.00, '否', 5, '11月去的黑松林，一个人出行。地点在临沂，地铁到达方便，现场高峰时段比较拥挤。这次玩了5天，人均花费约1427元，夜景表现很好。景点印象：这里的黑松林群落遮天蔽日，多年落下的松针厚厚地铺在地面上，使人如同踏上松软而有弹性的地毯。走在这幽静的松林里，日间的光影分外柔和，空气也格外地清新，若有若无的清风微拂着面颊耳际，正是古人吟咏的“密树遥遮日，轻花细逐风”的境界。当你…整体感受是超出预期，以后还会来。二刷意愿：否。', '0%', 60);
