INSERT INTO `travel_review` VALUES (2240, 'TR002240', '太极山', '安阳', '河南', '城市漫游', '冬季', 10, 4, 1103.00, '否', 3, '10月去的太极山，和朋友出行。地点在安阳，公交换乘方便，现场人流量适中。这次玩了4天，人均花费约1103元，拍照很出片。景点印象：太极山是桃花谷景区的一个分景区。\"混沌初开盘古先，太极两仪四象悬。”太极冰山是传说中盘古开天的遗迹。亿万年前，在混沌的卵石中孕育成人的盘古，蹬碎了束缚自己的卵石，经过混沌初开，摧肝裂胆的毁灭与新生，开天劈地创造了日月星辰，山川河流…整体感受是中规中矩，别抱太高期待。二刷意愿：否。', '0%', 53);
INSERT INTO `travel_review` VALUES (2241, 'TR002241', '美人谷', '荆门', '湖北', '深度游', '秋季', 8, 1, 471.00, '是', 5, '8月去的美人谷，和家人出行。地点在荆门，公交换乘方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约471元，氛围感不错。景点印象：绿林美人谷由一系列的深潭、飞瀑、奇石、幽洞组成，是一个以水石景观为主的峡谷型探秘寻芳的生态休闲游览区，景貌与四川的九寨沟何其相似乃尔，被誉为“湖北新九寨”。整体感受是超出预期，值得专门打卡。二刷意愿：是。', '13%', 96);
INSERT INTO `travel_review` VALUES (2242, 'TR002242', '普者黑景区', '文山', '云南', '文化打卡', '秋季', 8, 1, 885.00, '是', 5, '8月去的普者黑景区，和家人出行。地点在文山，公交换乘方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约885元，夜景表现很好。景点印象：世间罕见、中国独一无二的喀斯特山水田园风光。整体感受是超出预期，很推荐。二刷意愿：是。', '74%', 74);
