INSERT INTO `travel_review` VALUES (2263, 'TR002263', '螺丝山青年公园', '铜陵', '安徽', '周末短途', '春季', 1, 1, 744.00, '否', 5, '1月去的螺丝山青年公园，情侣出行。地点在铜陵，打车比较省心，现场游客较多。这次玩了1天，人均花费约744元，拍照很出片。景点印象：螺丝山景区地理位置优越，旅游资源丰富，且已列入铜都森林公园规划。开发建设螺丝山景区，既能满足市民生活娱乐的要求，又能体现城市特色，同时也为创建省和国家园林城市、文明城市做出贡献。螺丝山景区开发建设也是环境保护的重要措施，可以美化铜…整体感受是特别满意，值得专门打卡。二刷意愿：否。', '0%', 50);
