INSERT INTO `travel_review` VALUES (2319, 'TR002319', '吞力黑衣壮山寨', '百色', '广西', '周末短途', '夏季', 4, 5, 1306.00, '否', 2, '4月去的吞力黑衣壮山寨，和朋友出行。地点在百色，地铁到达方便，现场人流量适中。这次玩了5天，人均花费约1306元，拍照很出片。景点印象：吞力黑衣壮山寨位于那坡县城北部山区，距县城14公里，居住着57户，370人，全屯均为黑衣壮。\n黑衣壮人心地善良、热情好客、勤劳朴实。“有客自远方来，不亦乐乎”。不管是否相识，总会热情邀请到家中做客。他们生性浪漫，生活丰富多彩，男女老少都能…整体感受是略失望，不建议高峰来。二刷意愿：否。', '4%', 67);
