INSERT INTO `travel_review` VALUES (2322, 'TR002322', '龙台观', '商洛', '陕西', '亲子出游', '夏季', 4, 1, 355.00, '否', 5, '4月去的龙台观，和朋友出行。地点在商洛，地铁到达方便，现场游客较多。这次玩了1天，人均花费约355元，氛围感不错。景点印象：龙台观位于丹凤县城东30公里处的铁峪铺镇花子沟村，观的对面有一天然溶洞名为黄龙洞。洞高数丈，洞深无底，洞内钟乳奇观，如龙腾虎跃，似玉树琼阁，造型精美。山腰一股龙泉喷泻成瀑布披岩而下，为天然浴泉，游人可沐。\n与洞相对的峻岩峰顶有龙台观…整体感受是挺惊喜，以后还会来。二刷意愿：否。', '0%', 84);
