INSERT INTO `travel_review` VALUES (2330, 'TR002330', '坝王岭长臂猿自然保护区', '昌江', '海南', '深度游', '冬季', 11, 2, 211.00, '是', 5, '11月去的坝王岭长臂猿自然保护区，一个人出行。地点在昌江，打车比较省心，现场人不算多。这次玩了2天，人均花费约211元，氛围感不错。景点印象：保护区总面积35000多亩，这里山岳连绵，群峰叠翠，林海浩渺，古木参天，自然生态系统保存完整，热带生物资源极其丰富。沿着蜿蜒曲折的林区公路进入保护区，环顾四周，除生长着众多的名贵树种外，野生动物主食的各种野果树满山皆是，有馒头果、山石…整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 64);
INSERT INTO `travel_review` VALUES (2331, 'TR002331', '东郊椰林风景区', '文昌', '海南', '深度游', '夏季', 5, 1, 623.00, '否', 5, '5月去的东郊椰林风景区，一个人出行。地点在文昌，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约623元，拍照很出片。景点印象：欣赏椰林成片的美景，品味多种椰子美食，感受椰乡魅力。整体感受是挺惊喜，以后还会来。二刷意愿：否。', '70%', 65);
INSERT INTO `travel_review` VALUES (2332, 'TR002332', '南澳岛', '汕头', '广东', '周末短途', '秋季', 6, 1, 580.00, '否', 5, '6月去的南澳岛，情侣出行。地点在汕头，公交换乘方便，现场人流量适中。这次玩了1天，人均花费约580元，拍照很出片。景点印象：南澳岛坐落在闽、粤、台三省交界海面，碧海蓝天，风景十分优美。整体感受是特别满意，很推荐。二刷意愿：否。', '13%', 67);
INSERT INTO `travel_review` VALUES (2333, 'TR002333', '达里湖', '赤峰', '内蒙古', '亲子出游', '秋季', 6, 6, 1599.00, '否', 3, '6月去的达里湖，一个人出行。地点在赤峰，打车比较省心，现场游客较多。这次玩了6天，人均花费约1599元，历史文化气息浓。景点印象：达里诺尔湖区游览观光，感受“百鸟争鸣，百禽起舞”。整体感受是中规中矩，按需选择。二刷意愿：否。', '28%', 48);
INSERT INTO `travel_review` VALUES (2334, 'TR002334', '东地大庙', '昌吉', '新疆', '城市漫游', '夏季', 4, 1, 497.00, '否', 4, '4月去的东地大庙，和家人出行。地点在昌吉，公交换乘方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约497元，夜景表现很好。景点印象：东地大庙包括乾隆大庙(关帝庙)、娘娘庙、城隍庙,位于奇台县城东约21公里的西地乡东地村。东地大庙中的关帝庙是三座庙宇群体中的主体，占地约68平方米，座北朝南，面阔三间，进深三间，顶为三架梁硬山式。娘娘庙占地125平方米，座北朝南，进深三间，…整体感受是整体不错，推荐来看看。二刷意愿：否。', '0%', 24);
INSERT INTO `travel_review` VALUES (2335, 'TR002335', '松赞林景区', '迪庆', '云南', '亲子出游', '秋季', 8, 4, 1024.00, '是', 5, '8月去的松赞林景区，情侣出行。地点在迪庆，公交换乘方便，现场游客较多。这次玩了4天，人均花费约1024元，历史文化气息浓。景点印象：云南地区的藏传佛教寺庙，素有小布达拉宫之誉。整体感受是超出预期，很推荐。二刷意愿：是。', '41%', 74);
