INSERT INTO `travel_review` VALUES (2337, 'TR002337', '雁门关', '忻州', '山西', '亲子出游', '夏季', 3, 7, 2026.00, '是', 4, '3月去的雁门关，情侣出行。地点在忻州，地铁到达方便，现场游客较多。这次玩了7天，人均花费约2026元，拍照很出片。景点印象：杨家将故事的发源地，也是历史上重要的古战场，长城上的重要关隘。 走一段这里的长城古关道，遥看关外衰草连天，是思古的好地方。整体感受是整体不错，可以安排半天到一天。二刷意愿：是。', '16%', 70);
INSERT INTO `travel_review` VALUES (2338, 'TR002338', '水丰景区', '丹东', '辽宁', '拍照旅行', '春季', 1, 4, 1310.00, '是', 5, '1月去的水丰景区，和家人出行。地点在丹东，公交换乘方便，现场高峰时段比较拥挤。这次玩了4天，人均花费约1310元，氛围感不错。景点印象：水丰景区素有东北地区第一大水库和辽宁淡水湖之称。远看两岸青山叠翠，古树参天，水线以下尽是刀削岩壁，沙石堆彻的天然景观。边境山水、界河文化、百年生态、传奇江坝、古老习俗、古朴民风，是水丰景区发展旅游的定位。主要景点有：水丰大坝网箱养…整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 68);
INSERT INTO `travel_review` VALUES (2339, 'TR002339', '碧塔海景区', '迪庆', '云南', '拍照旅行', '春季', 2, 2, 467.00, '否', 5, '2月去的碧塔海景区，和家人出行。地点在迪庆，打车比较省心，现场高峰时段比较拥挤。这次玩了2天，人均花费约467元，氛围感不错。景点印象：湖畔长满栎树，五六月满山杜鹃花开特别壮观，还可以看到“杜鹃醉鱼”的奇观。整体感受是挺惊喜，以后还会来。二刷意愿：否。', '15%', 74);
INSERT INTO `travel_review` VALUES (2340, 'TR002340', '霞山天主教堂(天主教湛江教区)', '湛江', '广东', '拍照旅行', '夏季', 4, 1, 522.00, '是', 5, '4月去的霞山天主教堂(天主教湛江教区)，和家人出行。地点在湛江，打车比较省心，现场人流量适中。这次玩了1天，人均花费约522元，夜景表现很好。景点印象：是湛江市唯一的哥特式教堂，有奇特的叉叶木，也是全国重点教堂之一。整体感受是超出预期，以后还会来。二刷意愿：是。', '2%', 74);
