INSERT INTO `travel_review` VALUES (2352, 'TR002352', '天梯山景区', '邢台', '河北', '亲子出游', '夏季', 4, 3, 803.00, '否', 5, '4月去的天梯山景区，和家人出行。地点在邢台，自驾停车需要提前规划，现场人不算多。这次玩了3天，人均花费约803元，夜景表现很好。景点印象：登山走在悬空古桥和吊桥之间，感受天梯山地貌的独特和险峻。 走进一个个形状各异的天然山洞，观看雕像、石刻等古迹。 乘船进入金水洞，观赏古洞内的钟乳石美景。整体感受是超出预期，以后还会来。二刷意愿：否。', '0%', 81);
