INSERT INTO `travel_review` VALUES (2390, 'TR002390', '崇安寺', '晋城', '山西', '文化打卡', '冬季', 10, 4, 1051.00, '否', 5, '10月去的崇安寺，情侣出行。地点在晋城，打车比较省心，现场人流量适中。这次玩了4天，人均花费约1051元，夜景表现很好。景点印象：崇安寺，古称凌烟寺，位于山西省陵川县崇文镇西北的卧龙岗上，大有居高临下，俯瞰全城的雄伟气魄，\"先有崇安，后有陵川\"的远古说法在当地流传甚广。\n崇安寺的创始年代已无从稽考，唐初原名为\"丈八佛寺\'，宋太平兴国元年？？公元976年？？敕命为崇…整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '2%', 65);
