INSERT INTO `travel_review` VALUES (2420, 'TR002420', '水心寨', '常德', '湖南', '城市漫游', '冬季', 9, 1, 80.00, '否', 5, '9月去的水心寨，情侣出行。地点在常德，地铁到达方便，现场游客较多。这次玩了1天，人均花费约80元，氛围感不错。景点印象：桃源水心寨位于桃源境内沅江与夷望溪交汇之处，四面环水，高约数百尺，壁立陡峭，上攀山岩，前后人头脚相接，须抓住铁链而上。山岩原名水心岩，因南宋洞庭湖区农民起义军首领杨幺曾在此驻军，并立坛祭苍天，后人因此改名水心寨。寨顶有小观，自古就…整体感受是超出预期，很推荐。二刷意愿：否。', '11%', 56);
