INSERT INTO `travel_review` VALUES (2429, 'TR002429', '董氏砖雕墓', '临汾', '山西', '城市漫游', '秋季', 7, 2, 494.00, '否', 5, '7月去的董氏砖雕墓，一个人出行。地点在临汾，打车比较省心，现场游客较多。这次玩了2天，人均花费约494元，氛围感不错。景点印象：在山西侯马市西北郊基建工地发现，1959年和1969年，分别迁于山西考古研究所候马工作站院内。墓主人一名董海，一名董明，先后于金明昌七年（1196年）和大安二年（1210年）埋葬。均为仿木构砖雕墓，平面皆方形。董海墓为前后两室，系我国北方地区传统…整体感受是特别满意，很推荐。二刷意愿：否。', '0%', 74);
