INSERT INTO `travel_review` VALUES (2434, 'TR002434', '扶苏墓', '榆林', '陕西', '城市漫游', '冬季', 11, 6, 1358.00, '是', 5, '11月去的扶苏墓，和朋友出行。地点在榆林，地铁到达方便，现场高峰时段比较拥挤。这次玩了6天，人均花费约1358元，夜景表现很好。景点印象：扶苏墓位于绥德县城疏属山。扶苏（？--公元前210年），秦始皇长子。贤良明达，颇得众望，始皇三士五年，秦始皇“焚书坑儒”，在咸阳坑杀儒生460多人，引起扶苏犹虑，及时进谏：“天下初定，远方黔首未集，诸生皆诵法孔子，今以重法绳之，臣恐天下不…整体感受是特别满意，以后还会来。二刷意愿：是。', '1%', 77);
