INSERT INTO `travel_review` VALUES (2474, 'TR002474', '苏轼父子墓', '平顶山', '河南', '城市漫游', '春季', 2, 2, 754.00, '否', 5, '2月去的苏轼父子墓，一个人出行。地点在平顶山，公交换乘方便，现场人不算多。这次玩了2天，人均花费约754元，夜景表现很好。景点印象：位于郏县城西27公里处的小峨嵋山东麓。背嵩阳，面汝水，山川秀丽，风景宜人。北宋大文学家苏轼、苏辙与其父苏洵衣冠葬此，至今有近900年的历史。苏坟为历代文人墨客所景仰，留有许多珍贵的诗文碑刻。\n苏洵、苏轼、苏辙，同列“唐宋八大家”，世称“…整体感受是超出预期，很推荐。二刷意愿：否。', '50%', 71);
