INSERT INTO `travel_review` VALUES (2496, 'TR002496', '石室岩', '莆田', '福建', '深度游', '冬季', 11, 4, 929.00, '否', 5, '11月去的石室岩，一个人出行。地点在莆田，自驾停车需要提前规划，现场人流量适中。这次玩了4天，人均花费约929元，拍照很出片。景点印象：莆田市区西郊山腰间有海蚀洞多处，曾出土新石器遗物，此乃上古人穴居之所，故称石室岩。唐末高僧妙应祖师曾于此建立道场，相传祖师尝驯二虎为骑，故又名伏虎岩。宋绍圣间岩上始建寺，宋哲宗赐额曰妙应寺。明成化间寺宇废圯明万历礼部尚书莆人陈经邦…整体感受是超出预期，以后还会来。二刷意愿：否。', '0%', 121);
