INSERT INTO `travel_review` VALUES (2515, 'TR002515', '梅关古道', '韶关', '广东', '亲子出游', '春季', 12, 3, 794.00, '是', 5, '12月去的梅关古道，和朋友出行。地点在韶关，地铁到达方便，现场人不算多。这次玩了3天，人均花费约794元，历史文化气息浓。景点印象：梅关古道是全国保存得较完整的古驿道，南北遍植梅树，景色蔚为壮丽雄奇。整体感受是特别满意，以后还会来。二刷意愿：是。', '1%', 93);
INSERT INTO `travel_review` VALUES (2516, 'TR002516', '张公祠', '许昌', '河南', '深度游', '冬季', 11, 1, 215.00, '是', 5, '11月去的张公祠，和家人出行。地点在许昌，打车比较省心，现场人不算多。这次玩了1天，人均花费约215元，氛围感不错。景点印象：亦称张飞庙，位于许昌东南18公里张潘乡古城西北隅。祠建于8米的高阜上，面积10000平方米。庙中奉祀张飞，还有刘备和关羽。据传此处曾是东汉许都官驿，他们兄弟三人来见献帝时曾驻此。庙内有明嘉靖七年（公元1528年）《重修汉司马张公祠》碑一通，碑…整体感受是特别满意，很推荐。二刷意愿：是。', '0%', 53);
INSERT INTO `travel_review` VALUES (2517, 'TR002517', '恩施大峡谷', '恩施', '湖北', '城市漫游', '冬季', 9, 7, 1588.00, '是', 5, '9月去的恩施大峡谷，情侣出行。地点在恩施，自驾停车需要提前规划，现场游客较多。这次玩了7天，人均花费约1588元，拍照很出片。景点印象：层层叠叠的峰丛，近乎垂直于峡谷的大断崖。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '55%', 98);
