INSERT INTO `travel_review` VALUES (2523, 'TR002523', '豆口古镇', '长治', '山西', '文化打卡', '夏季', 4, 2, 643.00, '是', 5, '4月去的豆口古镇，和家人出行。地点在长治，地铁到达方便，现场人不算多。这次玩了2天，人均花费约643元，夜景表现很好。景点印象：豆口，是一个古老而精致的村落，行政管辖录属平顺县石城镇。村子深居太行山腹地的峡谷风景带，背山面水，“横漳水而带行山，枕龙门而控凤壁”，山奇水美。\n豆口村的主要景观是规模庞大的明清民居，这些木构木建、砖墙砖地、石雕石刻的屋院落、院落…整体感受是超出预期，值得专门打卡。二刷意愿：是。', '0%', 95);
