INSERT INTO `travel_review` VALUES (2554, 'TR002554', '九龙川自然保护区', '鞍山', '辽宁', '拍照旅行', '秋季', 7, 4, 1130.00, '是', 5, '7月去的九龙川自然保护区，情侣出行。地点在鞍山，公交换乘方便，现场高峰时段比较拥挤。这次玩了4天，人均花费约1130元，氛围感不错。景点印象：九龙川自然保护区位于海城市接文镇境内，距市区50公里，总面积34平方公里，现有森林20000余亩，各类动物300余种，并覆有大量植被，自然资源风光独特，为辽宁省政府批准设立的省级自然保护区。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 77);
