INSERT INTO `travel_review` VALUES (2560, 'TR002560', '海清寺阿育王塔', '连云港', '江苏', '深度游', '夏季', 4, 1, 92.00, '是', 5, '4月去的海清寺阿育王塔，和朋友出行。地点在连云港，地铁到达方便，现场人不算多。这次玩了1天，人均花费约92元，氛围感不错。景点印象：阿育王塔高40余米，九级八面，是苏北地区现存最高和最古老的一座宝塔。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '2%', 74);
