INSERT INTO `travel_review` VALUES (2562, 'TR002562', '华南虎保护区', '抚州', '江西', '城市漫游', '春季', 1, 4, 857.00, '是', 5, '1月去的华南虎保护区，情侣出行。地点在抚州，打车比较省心，现场高峰时段比较拥挤。这次玩了4天，人均花费约857元，夜景表现很好。景点印象：宜黄县位于江西省东部，地处武夷山山脉与雩山山脉向抚河平原过渡地带。全县土地总面积19.44万公项，其中林业用地面积15.09万公项，占土地总面积的77.6％。境内有3条南北走向的山脉，东支主峰军峰山，海拔1760.9米，中支主峰鱼牙嶂，海拔1467.9米，…整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 93);
