INSERT INTO `travel_review` VALUES (2580, 'TR002580', '历山舜王庙', '菏泽', '山东', '城市漫游', '夏季', 4, 3, 654.00, '是', 5, '4月去的历山舜王庙，一个人出行。地点在菏泽，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了3天，人均花费约654元，历史文化气息浓。景点印象：历山舜王庙在鄄城县阎什镇历山庙村西，东距阎什镇2公里。\n舜，有虞氏，姓姚，名重华，字成都，虞君之后，历代传为贤明圣君，司马迁列之为五帝之一。皇甫谧云：“舜生姚墟”，据考姚墟即今山东省鄄城县麻寨乡舜城集。《史记》载：舜耕历山，历山之人…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 95);
