INSERT INTO `travel_review` VALUES (2583, 'TR002583', '雾漫小东江', '郴州', '湖南', '城市漫游', '冬季', 9, 3, 734.00, '是', 5, '9月去的雾漫小东江，一个人出行。地点在郴州，地铁到达方便，现场人不算多。这次玩了3天，人均花费约734元，氛围感不错。景点印象：小东江位于资兴市内，水面面积达160平方公里，蓄水量81亿立方米，相当于半个洞庭湖。这里长年两岸峰峦叠翠，湖面水汽蒸腾，云雾缭绕，神秘绮丽，其雾时移时凝，宛如一条被仙女挥舞着的“白练”，美丽之极，堪称中华一绝。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '42%', 80);
