INSERT INTO `travel_review` VALUES (2615, 'TR002615', '中街', '沈阳', '辽宁', '周末短途', '冬季', 11, 2, 457.00, '是', 5, '11月去的中街，和朋友出行。地点在沈阳，地铁到达方便，现场人不算多。这次玩了2天，人均花费约457元，氛围感不错。景点印象：中国第一条步行街，是沈阳历史悠久、交易繁华的商业区。整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 99);
