INSERT INTO `travel_review` VALUES (2618, 'TR002618', '松鹤西湖滑雪狩猎场', '鹤岗', '黑龙江', '周末短途', '春季', 2, 2, 700.00, '是', 5, '2月去的松鹤西湖滑雪狩猎场，情侣出行。地点在鹤岗，公交换乘方便，现场人不算多。这次玩了2天，人均花费约700元，历史文化气息浓。景点印象：该场位于西郊松鹤西湖公园的笃斯山，山上有两条长800米的雪道和一个小动物狩猎场，山下湖中有冰上旅游项目，包括：滑冰、冰滑梯、冰上保龄球、狗拉雪撬等，是冬季溜冰滑雪的乐园。整体感受是超出预期，值得专门打卡。二刷意愿：是。', '0%', 76);
INSERT INTO `travel_review` VALUES (2619, 'TR002619', '以礼河', '曲靖', '云南', '文化打卡', '秋季', 8, 3, 1255.00, '是', 4, '8月去的以礼河，情侣出行。地点在曲靖，自驾停车需要提前规划，现场人不算多。这次玩了3天，人均花费约1255元，历史文化气息浓。景点印象：以礼河全长120公里，其上建有4个梯级电站，上游建有世界第二、全国最大的土坝----毛家村水库大坝，库容5.53亿立方米，库区回水长30公里，两岸绿树成荫，奇峰罗列，青山浮水，景色绮丽，兼有漓江秀色和三峡壮丽。\n湖面可供游客乘船游览，下游的第三…整体感受是整体不错，周末来刚好。二刷意愿：是。', '0%', 97);
INSERT INTO `travel_review` VALUES (2620, 'TR002620', '金石滩度假区', '大连', '辽宁', '深度游', '冬季', 9, 1, 80.00, '否', 5, '9月去的金石滩度假区，情侣出行。地点在大连，自驾停车需要提前规划，现场人流量适中。这次玩了1天，人均花费约80元，历史文化气息浓。景点印象：坐落着发现王国主题公园、滨海地质公园、黄金海岸等著名景点。整体感受是挺惊喜，很推荐。二刷意愿：否。', '44%', 75);
