INSERT INTO `travel_review` VALUES (2624, 'TR002624', '哈巴雪山', '迪庆', '云南', '亲子出游', '夏季', 5, 1, 151.00, '是', 5, '5月去的哈巴雪山，和朋友出行。地点在迪庆，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约151元，拍照很出片。景点印象：玉龙雪山的“兄弟”，适合攀登的入门级雪山，山顶终年冰雪覆盖，周围环绕着大片冰川。整体感受是超出预期，值得专门打卡。二刷意愿：是。', '2%', 92);
