INSERT INTO `travel_review` VALUES (2631, 'TR002631', '乌兰木图山', '阜新', '辽宁', '周末短途', '秋季', 8, 2, 795.00, '否', 4, '8月去的乌兰木图山，一个人出行。地点在阜新，打车比较省心，现场人不算多。这次玩了2天，人均花费约795元，拍照很出片。景点印象：阜蒙县八家子乡境内的乌兰木图山，早年叫阿力玛图山。两个名都是蒙语的音译，前者汉译为“有红色树木之山”，后者译为“有梨之山”。梨山之名更久。\n　　这座山的主峰叫锅底山，海拔高度831.4米，是阜新市第一高峰。站在主峰上近观远眺，收入眼帘的…整体感受是整体不错，推荐来看看。二刷意愿：否。', '0%', 116);
