INSERT INTO `travel_review` VALUES (2635, 'TR002635', '韩屯渡口', '吉林市', '吉林', '文化打卡', '冬季', 9, 4, 1305.00, '是', 5, '9月去的韩屯渡口，和朋友出行。地点在吉林市，公交换乘方便，现场高峰时段比较拥挤。这次玩了4天，人均花费约1305元，拍照很出片。景点印象：韩屯渡口位于吉林市龙潭区乌拉街满族镇雾凇岛对面的渡口附近,由于该渡口对面的雾凇岛上没有住宿，所以游客多在韩屯驻扎。从韩屯渡口摆渡到对岸就可以到雾凇岛。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '5%', 75);
