INSERT INTO `travel_review` VALUES (2648, 'TR002648', '遗址', '咸宁', '湖北', '亲子出游', '春季', 2, 3, 674.00, '是', 5, '2月去的遗址，和朋友出行。地点在咸宁，地铁到达方便，现场游客较多。这次玩了3天，人均花费约674元，历史文化气息浓。景点印象：古战场赤壁，位于长江中游南岸，湖北省赤壁市境内，距武汉市164公里， 距湖南岳阳90公里，湖北省重点文物保护单位。\n赤璧位于赤璧市境。东汉建安十三年（元二○八年），曹操率二十几万大军南下，连克新野、襄阳数城，从江陵顺江东下，与逆江西上的…整体感受是特别满意，很推荐。二刷意愿：是。', '0%', 110);
