INSERT INTO `travel_review` VALUES (2671, 'TR002671', '七星岩景区', '肇庆', '广东', '文化打卡', '春季', 12, 3, 1321.00, '否', 3, '12月去的七星岩景区，和家人出行。地点在肇庆，自驾停车需要提前规划，现场人流量适中。这次玩了3天，人均花费约1321元，夜景表现很好。景点印象：七星岩景区内七座挺拔秀丽的石灰岩山峰布列如北斗七星，故名七星岩。它分南北两列，南列由东而西为阆风岩、玉屏岩、石室岩、天柱岩、仙掌岩等，唯阿坡岩独峙北部。整体感受是还可以，别抱太高期待。二刷意愿：否。', '24%', 71);
INSERT INTO `travel_review` VALUES (2672, 'TR002672', '镇北台长城景区', '榆林', '陕西', '拍照旅行', '冬季', 9, 1, 356.00, '否', 4, '9月去的镇北台长城景区，和家人出行。地点在榆林，打车比较省心，现场游客较多。这次玩了1天，人均花费约356元，夜景表现很好。景点印象：号称“长城第一台”，是长城现存的最大的烽火台。 站在高高的镇北台上，遥看塞外风光，思古之情油然而生。整体感受是整体不错，周末来刚好。二刷意愿：否。', '14%', 35);
