INSERT INTO `travel_review` VALUES (2727, 'TR002727', '高颐阙', '雅安', '四川', '城市漫游', '春季', 2, 3, 786.00, '是', 5, '2月去的高颐阙，和家人出行。地点在雅安，打车比较省心，现场高峰时段比较拥挤。这次玩了3天，人均花费约786元，拍照很出片。景点印象：东汉益州太守高颐及其弟高实的墓阙，四川保存最完整、最精美的石阙，全国重点文物保护单位。在雅安市姚桥镇汉碑村。东汉建安十四年（209年）建造。两阙相距13.6米，阙间有高君宋碑及巨型石辟邪。两阙北壁皆有阴刻隶书铭文，东阙为\"汉故益州太守武阴…整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 62);
