INSERT INTO `travel_review` VALUES (2730, 'TR002730', '城市绿谷景区', '南通', '江苏', '城市漫游', '夏季', 5, 4, 1354.00, '否', 4, '5月去的城市绿谷景区，和家人出行。地点在南通，打车比较省心，现场高峰时段比较拥挤。这次玩了4天，人均花费约1354元，夜景表现很好。景点印象：苏北最大的双式私家园林，植被丰富、水流清秀，还有一系列游乐项目。整体感受是体验挺好，可以安排半天到一天。二刷意愿：否。', '0%', 65);
INSERT INTO `travel_review` VALUES (2731, 'TR002731', '九襄镇', '雅安', '四川', '城市漫游', '冬季', 11, 6, 1724.00, '是', 5, '11月去的九襄镇，和朋友出行。地点在雅安，公交换乘方便，现场人流量适中。这次玩了6天，人均花费约1724元，夜景表现很好。景点印象：汉初为沈黎郡、牦牛县治地。清嘉庆初置汉源乡，1950年建九襄镇，1958年改公社，1992年复镇。曾为汉源县人民政府驻地，汉源县人民政府驻地由汉源场迁至富林镇。整体感受是特别满意，以后还会来。二刷意愿：是。', '2%', 47);
