INSERT INTO `travel_review` VALUES (2802, 'TR002802', '桃源山', '常德', '湖南', '城市漫游', '冬季', 9, 1, 352.00, '是', 5, '9月去的桃源山，一个人出行。地点在常德，公交换乘方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约352元，历史文化气息浓。景点印象：面积约2．5平方公里。桃源山是道教的圣地，文化的中心。从西晋到晚明，以桃源山为主的名胜古迹，代有声名。西晋末叶桃源山上始建桃源观，中唐逐渐扩大，到北宋而称极盛。这里有潇湘一阁的水府阁，江南一宫的桃川宫，华夏一院的天宁碑院……当您朝圣…整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 73);
