INSERT INTO `travel_review` VALUES (2806, 'TR002806', '苏维埃政府旧址', '陵水', '海南', '城市漫游', '冬季', 9, 1, 301.00, '否', 5, '9月去的苏维埃政府旧址，和家人出行。地点在陵水，公交换乘方便，现场人不算多。这次玩了1天，人均花费约301元，氛围感不错。景点印象：琼崖第一个红色政权陵水县苏维埃政府就在此诞生，在这里重新点燃了全岛革命斗争的火种整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '2%', 55);
INSERT INTO `travel_review` VALUES (2807, 'TR002807', '龙神沟', '陇南', '甘肃', '拍照旅行', '夏季', 3, 1, 238.00, '是', 5, '3月去的龙神沟，和朋友出行。地点在陇南，公交换乘方便，现场游客较多。这次玩了1天，人均花费约238元，夜景表现很好。景点印象：龙神沟距县城约70千米。这里的风景美在峡谷，峡谷间有一龙头巨崖，伸向龙神河，故有龙神沟之称。龙神沟夹在两峰之间，跌入谷底深涧，有蓊郁的密林笼罩其上，只听水声淙淙，不见流水滟滟，藏龙卧虎，神奇奥秘。\n漫山遍野的森林，亭亭玉立，秀美至极…整体感受是特别满意，很推荐。二刷意愿：是。', '0%', 104);
