INSERT INTO `travel_review` VALUES (2820, 'TR002820', '老秃顶自然保护区', '本溪', '辽宁', '周末短途', '冬季', 10, 2, 756.00, '否', 4, '10月去的老秃顶自然保护区，一个人出行。地点在本溪，地铁到达方便，现场游客较多。这次玩了2天，人均花费约756元，夜景表现很好。景点印象：老秃顶是“辽宁屋脊”，省级自然保护区。位于桓仁县境内，属长白山脉。主峰海拔一千三百二十五公尺，面积七万二千亩，山顶气候寒冷，草木低矮，似龙爪状，故名老秃顶，但山腰森林茂密，有原始林。林中，有柞、桦、楸、椴、松、枫、槐、曲柳等树种，…整体感受是还蛮满意，可以安排半天到一天。二刷意愿：否。', '1%', 65);
