INSERT INTO `travel_review` VALUES (2825, 'TR002825', '黄岛金沙滩', '青岛', '山东', '深度游', '夏季', 5, 2, 791.00, '是', 5, '5月去的黄岛金沙滩，和朋友出行。地点在青岛，地铁到达方便，现场人流量适中。这次玩了2天，人均花费约791元，拍照很出片。景点印象：海滩上的沙质堪称青岛最佳最细腻，并拥有广阔海岸线。整体感受是超出预期，很推荐。二刷意愿：是。', '25%', 132);
