INSERT INTO `travel_review` VALUES (2828, 'TR002828', '玄素洞景区', '咸宁', '湖北', '城市漫游', '冬季', 11, 1, 168.00, '否', 4, '11月去的玄素洞景区，一个人出行。地点在咸宁，公交换乘方便，现场游客较多。这次玩了1天，人均花费约168元，氛围感不错。景点印象：玄素洞是咸宁市首家国家AA级旅游景区。位于雪峰山下、陆水湖畔。因远古时有一玄素真人在此修炼而得名。洞长难度量。据《大清一统志》载：旧时有好事者裹粮入，信步趋出，相距百里余。该溶洞洞道幽深，千姿百态的钟乳石遍布洞中。目前已开发三千余米…整体感受是整体不错，可以安排半天到一天。二刷意愿：否。', '3%', 51);
INSERT INTO `travel_review` VALUES (2829, 'TR002829', '南禅寺', '无锡', '江苏', '亲子出游', '夏季', 3, 1, 515.00, '否', 5, '3月去的南禅寺，一个人出行。地点在无锡，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约515元，拍照很出片。景点印象：寺庙有地铁直达，祈福便利；在周边的历史街区可吃美食、看夜景。整体感受是特别满意，值得专门打卡。二刷意愿：否。', '9%', 114);
