INSERT INTO `travel_review` VALUES (2831, 'TR002831', '塔云山', '商洛', '陕西', '文化打卡', '秋季', 7, 2, 285.00, '否', 4, '7月去的塔云山，一个人出行。地点在商洛，公交换乘方便，现场游客较多。这次玩了2天，人均花费约285元，拍照很出片。景点印象：塔云山左有弛风山，其山势陡峭，古松参天。站立弛风山头可以收览塔云山全景，是游人憩息的好去处；右为东风山，其山巍娥壮观，林木幽森。整体感受是还蛮满意，可以安排半天到一天。二刷意愿：否。', '0%', 79);
