INSERT INTO `travel_review` VALUES (2849, 'TR002849', '三顾堂', '襄阳', '湖北', '周末短途', '夏季', 5, 2, 722.00, '否', 5, '5月去的三顾堂，情侣出行。地点在襄阳，打车比较省心，现场人不算多。这次玩了2天，人均花费约722元，拍照很出片。景点印象：隆中位于襄阳城西十三公里处的群山中，是一个以诸葛亮故居为主体的襄樊市近郊文物风景区，总面积十二平方公里，景区内有隆中山、乐山、大旗山、小旗山及其所属的谷地。\n主峰隆中山海拔306米，起伏盘旋，势若蟠龙；隔谷相望的大旗山，一头高昂，一…整体感受是超出预期，值得专门打卡。二刷意愿：否。', '11%', 105);
