INSERT INTO `travel_review` VALUES (2876, 'TR002876', '井冈山碑林', '吉安', '江西', '亲子出游', '夏季', 5, 1, 316.00, '是', 5, '5月去的井冈山碑林，一个人出行。地点在吉安，公交换乘方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约316元，氛围感不错。景点印象：井冈山碑林始建于1987年7月，自1989年清明节起对外开放。碑林由碑亭、碑廊、自然碑型等部分组成，因势而构，曲折回环，别具一番情趣。整体感受是特别满意，很推荐。二刷意愿：是。', '5%', 102);
