INSERT INTO `travel_review` VALUES (2946, 'TR002946', '春湾', '阳江', '广东', '城市漫游', '秋季', 6, 3, 293.00, '否', 5, '6月去的春湾，和家人出行。地点在阳江，自驾停车需要提前规划，现场游客较多。这次玩了3天，人均花费约293元，拍照很出片。景点印象：春湾景区位于春湾镇，含龙宫岩、春湾石林、通天蜡烛、慈云岩、通真岩五个景点。\n龙宫岩长1000多米，景色瑰丽，像传说中的海底龙宫。岩洞分四段。首段迎宾廊，“龙王水族”栩栩如生；二段龙王殿，惟妙惟肖；三段聚宝库，内有“镇宫宝塔”、“定海神…整体感受是超出预期，值得专门打卡。二刷意愿：否。', '1%', 67);
