INSERT INTO `travel_review` VALUES (2959, 'TR002959', '慕士塔格冰川公园', '喀什', '新疆', '文化打卡', '冬季', 10, 1, 80.00, '是', 5, '10月去的慕士塔格冰川公园，情侣出行。地点在喀什，公交换乘方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约80元，历史文化气息浓。景点印象：慕士塔格冰川公园位于塔什库尔干县、世界著名的“冰山之父”—7546米的慕士塔格峰裙带下，该公园方圆20公里，距县城72公里，距314国道12公里，平均海拔5000米，有美丽的“绿弓湖”在此停留。游客可以看到冰川的雄伟、冰蛇的秀丽、冰塔、冰洞的多姿…整体感受是特别满意，很推荐。二刷意愿：是。', '3%', 75);
