INSERT INTO `travel_review` VALUES (2998, 'TR002998', '乌尔禾风城', '克拉玛依', '新疆', '城市漫游', '秋季', 8, 2, 662.00, '否', 4, '8月去的乌尔禾风城，情侣出行。地点在克拉玛依，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约662元，拍照很出片。景点印象：位于市区东北100多公里的乌尔干地，北倚哈拉阿拉特山，方圆约30余公里，是我国罕见的风蚀地貌。亿万年前，这里是淡水湖泊，地壳的沧桑剧变使它形成了戈壁平台，年复一年的风蚀雨剥，使地面形成沟壑、纵横深浅不一的石层，并将石层雕塑成各种奇形怪…整体感受是体验挺好，推荐来看看。二刷意愿：否。', '6%', 35);
