INSERT INTO `travel_review` VALUES (3014, 'TR003014', '老龙潭', '固原', '宁夏', '拍照旅行', '秋季', 6, 2, 720.00, '否', 2, '6月去的老龙潭，和朋友出行。地点在固原，打车比较省心，现场人不算多。这次玩了2天，人均花费约720元，夜景表现很好。景点印象：整体环境还算干净整体感受是没达到预期，建议谨慎前往。二刷意愿：否。', '8%', 28);
INSERT INTO `travel_review` VALUES (3015, 'TR003015', '朱载育墓', '焦作', '河南', '文化打卡', '秋季', 6, 2, 80.00, '否', 2, '6月去的朱载育墓，和家人出行。地点在焦作，地铁到达方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约80元，拍照很出片。景点印象：朱载育墓位于沁阳县东北15公里处的山王庄乡张坡村东九峰山下。北依太行，南瞰怀川，墓周流水潺潺，环境优雅。原有明代书法家王铎书写的神道碑，抗日战争时期被日军炸毁。墓上原有高大封土堆，墓面有神道，神道两侧有石像生等，\"文化大革命\"开始后，…整体感受是略失望，可考虑其他景点。二刷意愿：否。', '0%', 35);
INSERT INTO `travel_review` VALUES (3016, 'TR003016', '天台寺(天台峰)', '池州', '安徽', '文化打卡', '冬季', 11, 3, 1114.00, '是', 5, '11月去的天台寺(天台峰)，和家人出行。地点在池州，地铁到达方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约1114元，夜景表现很好。景点印象：位于九华山顶部的寺院，相传金地藏（地藏菩萨）曾经居住在这里，可以在这里寻找金地藏的足迹。 这里是九华山观看日出和云海的好地方，还能俯瞰九华山众峰和山下的九华街。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '20%', 81);
INSERT INTO `travel_review` VALUES (3017, 'TR003017', '忆云山水温泉', '万宁', '海南', '文化打卡', '冬季', 11, 3, 796.00, '是', 4, '11月去的忆云山水温泉，和朋友出行。地点在万宁，打车比较省心，现场人不算多。这次玩了3天，人均花费约796元，拍照很出片。景点印象：南药养生温泉浴，在海南忆云山水温泉养生基地首家实施，是由北京资深老中医张教授领衔，与海南省中医院专家团队一起研发的18大功能养生温泉。整体感受是还蛮满意，推荐来看看。二刷意愿：是。', '0%', 85);
