INSERT INTO `travel_review` VALUES (3037, 'TR003037', '罗锅箐―大羊场', '怒江', '云南', '深度游', '秋季', 8, 1, 80.00, '否', 5, '8月去的罗锅箐―大羊场，和朋友出行。地点在怒江，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约80元，拍照很出片。景点印象：罗锅箐—大羊场风景区距县城56公里，位于通甸乡东北部24公里，总面积约60平方公里，该景区为普米族聚居区。\n罗锅箐—大羊场风景区由兰坪县通甸乡锣锅箐原始森林和河西乡大羊场草甸组成，其主要景点为：锣锅箐普米族村寨、吉利吉彩屏、回音壁、丹崖…整体感受是挺惊喜，很推荐。二刷意愿：否。', '0%', 79);
