INSERT INTO `travel_review` VALUES (3054, 'TR003054', '董必武旧居', '黄冈', '湖北', '城市漫游', '夏季', 4, 1, 305.00, '否', 2, '4月去的董必武旧居，和家人出行。地点在黄冈，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约305元，氛围感不错。景点印象：董必武旧居在红安县城民主街。旧居为一栋7间中式平房，坐西向东，面积120平方米。正中一间为小堂屋，上方香台依墙高置，大条桌放于中央，两张圆椅分列两旁，下方存放着董必武母亲用过的纺线车、织布机和灯架。堂屋北面的后半间房，是董必武诞生地，…整体感受是体验偏一般，可考虑其他景点。二刷意愿：否。', '0%', 42);
