INSERT INTO `travel_review` VALUES (3069, 'TR003069', '喀拉库勒湖', '克孜勒苏柯尔克孜', '新疆', '亲子出游', '夏季', 3, 4, 945.00, '是', 5, '3月去的喀拉库勒湖，情侣出行。地点在克孜勒苏柯尔克孜，打车比较省心，现场游客较多。这次玩了4天，人均花费约945元，历史文化气息浓。景点印象：高原湖泊-----喀拉库勒湖距阿图什220公里，海拔3600百米，面积为10平方公里，水深30多米，因湖水深邃幽黯，故名“喀拉库勒”（柯尔克孜语意为黑湖）。湖东面矗立着“冰山之父”慕士塔格峰，西面雄踞逶迤不绝的萨尔阔勒山脉；湖的南面是一片草原，一…整体感受是超出预期，很推荐。二刷意愿：是。', '80%', 73);
