INSERT INTO `travel_review` VALUES (3143, 'TR003143', '五彩城', '阿勒泰', '新疆', '亲子出游', '夏季', 3, 1, 433.00, '是', 5, '3月去的五彩城，情侣出行。地点在阿勒泰，公交换乘方便，现场游客较多。这次玩了1天，人均花费约433元，拍照很出片。景点印象：五彩城是受风力和流水作用形成的侵蚀台地，走进其中，宛如走进一个光怪陆离的梦幻世界，丰富的色彩令人感到炫目。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '8%', 107);
