INSERT INTO `travel_review` VALUES (3147, 'TR003147', '龙山', '莱芜', '山东', '文化打卡', '秋季', 7, 1, 90.00, '否', 5, '7月去的龙山，和家人出行。地点在莱芜，公交换乘方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约90元，拍照很出片。景点印象：山东龙山风景区，位于莱芜市莱城区东北茶业口镇境内，总面积 240 万平方米。龙山因其独特的自然形态而得名。当你登山观望，蜿蜒起伏的自然山势，犹如一条巨龙静静盘卧，山脚下的龙潭，恰似一颗镶嵌在崇山峻岭中的明珠，形成相为呼应，蔚为壮观的“…整体感受是挺惊喜，很推荐。二刷意愿：否。', '0%', 84);
