INSERT INTO `travel_review` VALUES (3160, 'TR003160', '龙台观', '商洛', '陕西', '文化打卡', '春季', 2, 2, 1049.00, '是', 5, '2月去的龙台观，和家人出行。地点在商洛，地铁到达方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约1049元，历史文化气息浓。景点印象：龙台观位于丹凤县城东30公里处的铁峪铺镇花子沟村，观的对面有一天然溶洞名为黄龙洞。洞高数丈，洞深无底，洞内钟乳奇观，如龙腾虎跃，似玉树琼阁，造型精美。山腰一股龙泉喷泻成瀑布披岩而下，为天然浴泉，游人可沐。\n与洞相对的峻岩峰顶有龙台观…整体感受是特别满意，以后还会来。二刷意愿：是。', '0%', 59);
