INSERT INTO `travel_review` VALUES (3171, 'TR003171', '山门水库', '四平', '吉林', '拍照旅行', '冬季', 9, 1, 362.00, '是', 5, '9月去的山门水库，情侣出行。地点在四平，地铁到达方便，现场人不算多。这次玩了1天，人均花费约362元，历史文化气息浓。景点印象：从山门水库大堤南侧登杏花山，要攀登山脚下的“登天门”和山顶上的“揽月门”之间的3个样式各异的凉亭连接起来的148阶水泥石阶，石阶两旁，绿树成荫。繁花竟放。游人曾写下“曲曲云山路，巍巍揽月门，春风似有意，故醉旅游人”的语句。登上山顶，远…整体感受是特别满意，很推荐。二刷意愿：是。', '0%', 98);
