INSERT INTO `travel_review` VALUES (3179, 'TR003179', '四龙剪金山', '白银', '甘肃', '深度游', '冬季', 11, 4, 721.00, '是', 4, '11月去的四龙剪金山，和家人出行。地点在白银，自驾停车需要提前规划，现场人流量适中。这次玩了4天，人均花费约721元，拍照很出片。景点印象：县级文物保护单位。位于白银区四龙镇北 15 公里 ，距白银市区 40 公里 。剪金山原名百花山，始建于北宋天圣元年（公元 1032 年），清代乾隆十九年（公元 1754 年）两次维修扩建，全部古建筑面积约 7000 平方米 ，寺庙高大宏伟，颇为壮观。每年农历…整体感受是体验挺好，周末来刚好。二刷意愿：是。', '0%', 52);
