INSERT INTO `travel_review` VALUES (3210, 'TR003210', '玉华宫风景名胜区', '铜川', '陕西', '亲子出游', '春季', 2, 1, 584.00, '否', 5, '2月去的玉华宫风景名胜区，和朋友出行。地点在铜川，打车比较省心，现场游客较多。这次玩了1天，人均花费约584元，氛围感不错。景点印象：玉华宫景区集自然景观、人文景观于一体具有旅游观光、避暑度假、佛事活动三大功能是陕西北线旅游景点的一颗璀璨明珠。整体感受是挺惊喜，很推荐。二刷意愿：否。', '30%', 97);
