INSERT INTO `travel_review` VALUES (3222, 'TR003222', '会山森林自然保护区', '琼海', '海南', '周末短途', '春季', 1, 1, 431.00, '否', 3, '1月去的会山森林自然保护区，和家人出行。地点在琼海，自驾停车需要提前规划，现场游客较多。这次玩了1天，人均花费约431元，历史文化气息浓。景点印象：面积8万多亩。保护区建于1981年，其作用是保护、恢复和发展该地区的水源林，防止和减免泥沙冲积水库。它是一个有利于发展琼海森林综合经营的大林区。整体感受是还可以，避开高峰更好。二刷意愿：否。', '0%', 58);
INSERT INTO `travel_review` VALUES (3223, 'TR003223', '朝天宫', '十堰', '湖北', '城市漫游', '春季', 12, 2, 468.00, '否', 5, '12月去的朝天宫，一个人出行。地点在十堰，打车比较省心，现场人流量适中。这次玩了2天，人均花费约468元，历史文化气息浓。景点印象：朝天宫后峭壁高耸，雨时，瀑布飞泻；冬季，冰瀑高悬，极为壮观。整体感受是超出预期，值得专门打卡。二刷意愿：否。', '24%', 79);
INSERT INTO `travel_review` VALUES (3224, 'TR003224', '庄子钓鱼台', '菏泽', '山东', '周末短途', '冬季', 9, 6, 1374.00, '是', 5, '9月去的庄子钓鱼台，情侣出行。地点在菏泽，打车比较省心，现场人不算多。这次玩了6天，人均花费约1374元，历史文化气息浓。景点印象：庄子钓鱼台为全国十大著名钓鱼台之一且排行第二，仅次于北京国宾馆钓鱼台，是鄄城的八大景点之一。\n战国时期，道家学派创始人庄周曾垂钓于此，故称“庄子钓鱼台”，简称“钓鱼台”。后人曾在钓鱼台上建庙以祀庄子，其村亦以此名为庄子庙。台上旧有…整体感受是挺惊喜，很推荐。二刷意愿：是。', '7%', 50);
