INSERT INTO `travel_review` VALUES (3227, 'TR003227', '北齐石刻造像', '长治', '山西', '拍照旅行', '秋季', 6, 2, 829.00, '否', 5, '6月去的北齐石刻造像，和家人出行。地点在长治，地铁到达方便，现场人不算多。这次玩了2天，人均花费约829元，拍照很出片。景点印象：北齐石刻造像位于武乡县城西北35公里处的北良候村，石刻为佛教创始人释迦牟尼的立体造像。\n石像高3.9米，腰围2米，手长40厘米，背北面南，立于50厘米高的石雕莲花座上。石像刻线明显，披巾搭胸，细腰束带。雕线棱角分明，刀法洗炼，在个体石像中甚…整体感受是特别满意，以后还会来。二刷意愿：否。', '0%', 74);
