INSERT INTO `travel_review` VALUES (3235, 'TR003235', '麻姑仙境', '衡阳', '湖南', '深度游', '冬季', 9, 4, 812.00, '是', 5, '9月去的麻姑仙境，情侣出行。地点在衡阳，打车比较省心，现场人不算多。这次玩了4天，人均花费约812元，氛围感不错。景点印象：可以在灵芝喷泉旁日光浴、森林浴，十分惬意。 周边到处是盛开的野花，满眼绿荫，是传说中仙女麻姑酿酒的地方。整体感受是超出预期，以后还会来。二刷意愿：是。', '8%', 83);
