INSERT INTO `travel_review` VALUES (3252, 'TR003252', '江平田园', '河池', '广西', '周末短途', '秋季', 7, 1, 815.00, '否', 3, '7月去的江平田园，一个人出行。地点在河池，地铁到达方便，现场游客较多。这次玩了1天，人均花费约815元，拍照很出片。景点印象：东兰县武篆镇是一块无数先烈用鲜血浸染的红土地，是广西农民运动的发源地，当年邓小平、张云逸、韦拔群等老一辈无产阶级革命家曾在那里并肩战斗，写下了辉煌的历史篇章。其灿烂的革命历史和伟人们深深的足迹，吸引着全国各地的游客，每年前来谒访圣…整体感受是还可以，避开高峰更好。二刷意愿：否。', '10%', 37);
