INSERT INTO `travel_review` VALUES (3293, 'TR003293', '同乐镇生态新村', '河池', '广西', '亲子出游', '春季', 1, 2, 901.00, '否', 2, '1月去的同乐镇生态新村，一个人出行。地点在河池，打车比较省心，现场游客较多。这次玩了2天，人均花费约901元，拍照很出片。景点印象：乐业县位于广西西北部，地处黔桂两省三市（州）7县的结合部。全县辖4镇4乡，有88个村民委（社区），1084个村民小组，总面积2617平方公里，总人口16万，居住着壮、汉、瑶、苗、布依等多个民族。县城距百色市168公里，距首府南宁市428公里，距贵阳市3…整体感受是略失望，不建议高峰来。二刷意愿：否。', '8%', 65);
