INSERT INTO `travel_review` VALUES (3309, 'TR003309', '静湖度假村', '通辽', '内蒙古', '拍照旅行', '夏季', 5, 1, 419.00, '否', 5, '5月去的静湖度假村，和朋友出行。地点在通辽，公交换乘方便，现场人不算多。这次玩了1天，人均花费约419元，历史文化气息浓。景点印象：静湖度假村总面积2万亩，是一处融自然环境与人文景观于一体的、适宜休闲娱乐的好地方。这里独特的气候条件，使它夏季可避暑纳凉，游山玩水，让人心旷神怡；冬天可滑冰玩雪，欣赏雕品，令人赏心悦目。目前已建成蒙古大营餐厅、儿童乐园、水上娱乐等…整体感受是特别满意，值得专门打卡。二刷意愿：否。', '0%', 66);
