INSERT INTO `travel_review` VALUES (3325, 'TR003325', '贤清福居', '上饶', '江西', '拍照旅行', '夏季', 5, 6, 1823.00, '是', 4, '5月去的贤清福居，和朋友出行。地点在上饶，地铁到达方便，现场高峰时段比较拥挤。这次玩了6天，人均花费约1823元，历史文化气息浓。景点印象：景点本身有一定特色整体感受是体验挺好，可以安排半天到一天。二刷意愿：是。', '0%', 54);
INSERT INTO `travel_review` VALUES (3326, 'TR003326', '水丰景区', '丹东', '辽宁', '周末短途', '秋季', 7, 2, 470.00, '否', 5, '7月去的水丰景区，情侣出行。地点在丹东，自驾停车需要提前规划，现场游客较多。这次玩了2天，人均花费约470元，氛围感不错。景点印象：水丰景区素有东北地区第一大水库和辽宁淡水湖之称。远看两岸青山叠翠，古树参天，水线以下尽是刀削岩壁，沙石堆彻的天然景观。边境山水、界河文化、百年生态、传奇江坝、古老习俗、古朴民风，是水丰景区发展旅游的定位。主要景点有：水丰大坝网箱养…整体感受是超出预期，很推荐。二刷意愿：否。', '0%', 79);
INSERT INTO `travel_review` VALUES (3327, 'TR003327', '露水河国家森林公园原始林观赏区', '白山', '吉林', '拍照旅行', '夏季', 4, 1, 196.00, '否', 5, '4月去的露水河国家森林公园原始林观赏区，和家人出行。地点在白山，打车比较省心，现场游客较多。这次玩了1天，人均花费约196元，夜景表现很好。景点印象：景点本身有一定特色整体感受是超出预期，很推荐。二刷意愿：否。', '0%', 77);
INSERT INTO `travel_review` VALUES (3328, 'TR003328', '雅砻河', '山南', '西藏', '拍照旅行', '春季', 1, 3, 866.00, '是', 5, '1月去的雅砻河，情侣出行。地点在山南，公交换乘方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约866元，拍照很出片。景点印象：雅砻河藏语意为“从上游下来的大河”，发源于雅拉香波山，山上终年冰雪覆顶，云雾缭绕。雅砻河逶迤北行80公里，在泽当镇西边注入雅鲁藏布江，全长68公里。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '1%', 78);
