INSERT INTO `travel_review` VALUES (3380, 'TR003380', '临泽丹霞', '张掖', '甘肃', '城市漫游', '冬季', 11, 3, 767.00, '是', 5, '11月去的临泽丹霞，和家人出行。地点在张掖，打车比较省心，现场高峰时段比较拥挤。这次玩了3天，人均花费约767元，历史文化气息浓。景点印象：临泽丹霞面积博大，色彩艳丽，场面壮观，是我国北方干旱地区最典型的丹霞地貌，也是另一种地貌类型——七彩丘陵，其色彩之缤纷、面积之大冠绝全国，举世罕见。整体感受是超出预期，很推荐。二刷意愿：是。', '1%', 71);
