INSERT INTO `travel_review` VALUES (3438, 'TR003438', '金牛山', '营口', '辽宁', '亲子出游', '秋季', 6, 3, 347.00, '是', 5, '6月去的金牛山，一个人出行。地点在营口，地铁到达方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约347元，历史文化气息浓。景点印象：金牛山古人类遗址位于大石桥市永安镇西田屯村，是迄今为止东北地区最早的古人类居住址。1974年以来，国家、省市有关部门对金牛山古人类遗址进行多次发掘，除发现78种哺乳动物化石外，还发现人类使用的打制石器、人类居住面和人类用火的痕迹。\n1984…整体感受是超出预期，以后还会来。二刷意愿：是。', '3%', 48);
