INSERT INTO `travel_review` VALUES (3450, 'TR003450', '南尖岩景区', '丽水', '浙江', '深度游', '春季', 12, 1, 693.00, '否', 3, '12月去的南尖岩景区，一个人出行。地点在丽水，公交换乘方便，现场人流量适中。这次玩了1天，人均花费约693元，氛围感不错。景点印象：江浙炙手可热的摄影基地，可将云海、梯田、瀑布等多种丰富的景色一网打尽。 起个早床，在摄影长廊守候清晨山间云雾缭绕的梯田景观。整体感受是中规中矩，别抱太高期待。二刷意愿：否。', '22%', 19);
