INSERT INTO `travel_review` VALUES (3454, 'TR003454', '应县木塔', '朔州', '山西', '文化打卡', '秋季', 6, 4, 1199.00, '否', 2, '6月去的应县木塔，一个人出行。地点在朔州，自驾停车需要提前规划，现场人流量适中。这次玩了4天，人均花费约1199元，历史文化气息浓。景点印象：稀有的辽代古建筑，是我国现存最高最古老的木塔，建筑中没有用一根铁钉。 在第一层内，有高达11米的释迦摩尼佛像，还有色彩鲜艳的壁画。 塔上有明代两位皇帝亲自题写的匾额：“峻极神功”和“天下奇观”。整体感受是没达到预期，可考虑其他景点。二刷意愿：否。', '91%', 23);
