INSERT INTO `travel_review` VALUES (3466, 'TR003466', '马蹄生态文化旅游区', '张掖', '甘肃', '文化打卡', '春季', 1, 5, 1512.00, '是', 5, '1月去的马蹄生态文化旅游区，和朋友出行。地点在张掖，地铁到达方便，现场高峰时段比较拥挤。这次玩了5天，人均花费约1512元，历史文化气息浓。景点印象：参观岩壁中凿刻的千年石窟建筑群，壮观奇幻。 汉藏佛教交汇的寺院，可以看到同一地方不同的佛像和建筑风格。 登上佛窟内远望外面的祁连风光，草原山峦开阔壮美。整体感受是特别满意，以后还会来。二刷意愿：是。', '24%', 65);
