INSERT INTO `travel_review` VALUES (3487, 'TR003487', '七一冰川', '张掖', '甘肃', '周末短途', '冬季', 11, 2, 703.00, '是', 5, '11月去的七一冰川，情侣出行。地点在张掖，公交换乘方便，现场游客较多。这次玩了2天，人均花费约703元，氛围感不错。景点印象：“七一”冰川位于嘉峪关市西南116公里处的祁连山腹地，每到夏秋季节，冰峰在蓝天丽日下分外晶莹耀眼，与潺潺的溪流以及绿草如茵、鲜花盛开的高山牧场，共同构成一幅恬静而又充满生机的迷人画卷。整体感受是超出预期，很推荐。二刷意愿：是。', '13%', 89);
