INSERT INTO `travel_review` VALUES (3489, 'TR003489', '雾漫小东江', '郴州', '湖南', '亲子出游', '冬季', 11, 3, 749.00, '是', 5, '11月去的雾漫小东江，和家人出行。地点在郴州，公交换乘方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约749元，拍照很出片。景点印象：小东江位于资兴市内，水面面积达160平方公里，蓄水量81亿立方米，相当于半个洞庭湖。这里长年两岸峰峦叠翠，湖面水汽蒸腾，云雾缭绕，神秘绮丽，其雾时移时凝，宛如一条被仙女挥舞着的“白练”，美丽之极，堪称中华一绝。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '42%', 45);
