INSERT INTO `travel_review` VALUES (3495, 'TR003495', '乌苏浪子湖', '兴安盟', '内蒙古', '拍照旅行', '夏季', 5, 3, 1254.00, '是', 5, '5月去的乌苏浪子湖，情侣出行。地点在兴安盟，地铁到达方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约1254元，氛围感不错。景点印象：乌苏浪子湖为火山喷发的熔岩流在流动过程中堵塞哈拉哈河形成的湖泊，原名49号泡子，四面环山，水面如镜，水质肥美，盛产鲤鱼、白鱼等冷水鱼。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '9%', 75);
