INSERT INTO `travel_review` VALUES (3505, 'TR003505', '钟灵禅寺', '齐齐哈尔', '黑龙江', '亲子出游', '秋季', 8, 5, 1189.00, '否', 4, '8月去的钟灵禅寺，和家人出行。地点在齐齐哈尔，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了5天，人均花费约1189元，拍照很出片。景点印象：钟灵禅寺始建于1911年，位于齐齐哈尔境内，克东县昌盛乡。原名钟灵观，因缺乏道教神职人员，故改名为钟灵寺，现为佛事活动场所。\n整个庙宇建在绿荫之中，内有主殿1幢，大殿2重，配阁4座，占地6,000平方米，建筑面积600平方米，均为砖木结构，墙面…整体感受是还蛮满意，推荐来看看。二刷意愿：否。', '0%', 71);
