INSERT INTO `travel_review` VALUES (3522, 'TR003522', '湖心岛', '岳阳', '湖南', '深度游', '夏季', 4, 2, 993.00, '否', 4, '4月去的湖心岛，和家人出行。地点在岳阳，地铁到达方便，现场人不算多。这次玩了2天，人均花费约993元，氛围感不错。景点印象：位于龙源水库中央，岛上险峰怪石，弥不胜举，奇花异草，目不暇接；四围青山环抱，水波涟涟。远远望去，恰如白银盘里一青螺。整体感受是整体不错，可以安排半天到一天。二刷意愿：否。', '2%', 77);
