INSERT INTO `travel_review` VALUES (3558, 'TR003558', '东门老街', '深圳', '广东', '深度游', '夏季', 4, 1, 216.00, '否', 4, '4月去的东门老街，情侣出行。地点在深圳，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约216元，拍照很出片。景点印象：老牌商业步行街区，最早的商业中心，商店和小吃店聚集的地方，非常热闹。整体感受是还蛮满意，周末来刚好。二刷意愿：否。', '0%', 80);
INSERT INTO `travel_review` VALUES (3559, 'TR003559', '太行山', '焦作', '河南', '拍照旅行', '冬季', 9, 3, 888.00, '否', 5, '9月去的太行山，情侣出行。地点在焦作，打车比较省心，现场人流量适中。这次玩了3天，人均花费约888元，夜景表现很好。景点印象：太行山“青崖如点戴，赤壁若朝霞，树翳文禽，潭泓绿水，景物奇秀，为世所称”，是“北雄风光”的典型代表。整体感受是超出预期，值得专门打卡。二刷意愿：否。', '1%', 120);
