INSERT INTO `travel_review` VALUES (3608, 'TR003608', '锦阳湖生态园', '铜川', '陕西', '文化打卡', '春季', 2, 1, 157.00, '否', 3, '2月去的锦阳湖生态园，一个人出行。地点在铜川，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约157元，氛围感不错。景点印象：锦阳湖生态园是“省级旅游风景区”和“国家水利风景区”。锦阳湖水域6千亩，湖岸延绵10多公里，与铜川境内的药王山、玉华宫等风景名胜古迹融为了秦北一条旅游热线，被誉为渭北旱塬上一颗璀璨明珠。\n作家贾平凹先生《废都》一书便是创作于此，其后重…整体感受是中规中矩，避开高峰更好。二刷意愿：否。', '0%', 29);
