INSERT INTO `travel_review` VALUES (3638, 'TR003638', '大相国寺', '开封', '河南', '深度游', '春季', 1, 3, 627.00, '否', 3, '1月去的大相国寺，一个人出行。地点在开封，公交换乘方便，现场游客较多。这次玩了3天，人均花费约627元，夜景表现很好。景点印象：这里是当年北宋都城内的皇家寺院，寺内有众多文物陈列。整体感受是还可以，避开高峰更好。二刷意愿：否。', '52%', 33);
