INSERT INTO `travel_review` VALUES (3640, 'TR003640', '碧江天生桥景区', '铜仁', '贵州', '文化打卡', '冬季', 11, 1, 666.00, '否', 5, '11月去的碧江天生桥景区，和朋友出行。地点在铜仁，自驾停车需要提前规划，现场人不算多。这次玩了1天，人均花费约666元，夜景表现很好。景点印象：景点本身有一定特色整体感受是特别满意，很推荐。二刷意愿：否。', '5%', 85);
INSERT INTO `travel_review` VALUES (3641, 'TR003641', '普化寺', '怒江', '云南', '城市漫游', '冬季', 11, 3, 843.00, '否', 2, '11月去的普化寺，情侣出行。地点在怒江，地铁到达方便，现场人流量适中。这次玩了3天，人均花费约843元，历史文化气息浓。景点印象：云南怒江普化寺离重丁天主教堂不到一小时的路程，在东风村，沿着小道穿过村中民居，看到的藏式风格的简陋寺院就是了。从普化寺看石门关比在怒江边看石门关更加奇险。在这里拍摄更能体现石门关的险要。普化寺平时锁门，可以到旁边的小屋里找喇嘛帮忙…整体感受是略失望，不建议高峰来。二刷意愿：否。', '3%', 32);
INSERT INTO `travel_review` VALUES (3642, 'TR003642', '噶丹松赞林寺', '迪庆', '云南', '亲子出游', '夏季', 5, 3, 1002.00, '否', 5, '5月去的噶丹松赞林寺，和朋友出行。地点在迪庆，打车比较省心，现场人流量适中。这次玩了3天，人均花费约1002元，夜景表现很好。景点印象：景点本身有一定特色整体感受是超出预期，很推荐。二刷意愿：否。', '0%', 62);
INSERT INTO `travel_review` VALUES (3643, 'TR003643', '大漠沙湖滑雪场', '石嘴山', '宁夏', '城市漫游', '冬季', 9, 2, 826.00, '是', 4, '9月去的大漠沙湖滑雪场，和朋友出行。地点在石嘴山，地铁到达方便，现场人流量适中。这次玩了2天，人均花费约826元，氛围感不错。景点印象：沙湖滑雪场借助的是沙湖一望无垠的万亩冰园，得天独厚的自然条件也让来者乐此不疲。沙湖的优势在于溶身于冰天雪地的大自然之中，任何的娱乐完全可以发自内心，自娱自乐。这里的冰面娱乐设施充满童趣，诸如打老牛、溜冰车都是我们童年的游戏，信手拈…整体感受是体验挺好，周末来刚好。二刷意愿：是。', '0%', 52);
INSERT INTO `travel_review` VALUES (3644, 'TR003644', '青山咀', '江门', '广东', '深度游', '秋季', 6, 4, 1017.00, '否', 5, '6月去的青山咀，一个人出行。地点在江门，地铁到达方便，现场人不算多。这次玩了4天，人均花费约1017元，拍照很出片。景点印象：景点本身有一定特色整体感受是超出预期，以后还会来。二刷意愿：否。', '0%', 58);
INSERT INTO `travel_review` VALUES (3645, 'TR003645', '五老峰景区', '九江', '江西', '拍照旅行', '秋季', 7, 1, 511.00, '否', 2, '7月去的五老峰景区，情侣出行。地点在九江，打车比较省心，现场人不算多。这次玩了1天，人均花费约511元，氛围感不错。景点印象：庐山最雄伟险峻的五峰，形状恰似五位老翁，从不同角度看姿态各异。 登上山顶可以远眺鄱阳湖、市镇田地及江河交错等风光。整体感受是体验偏一般，不建议高峰来。二刷意愿：否。', '43%', 23);
