INSERT INTO `travel_review` VALUES (3647, 'TR003647', '神农架动植物标本馆', '神农架', '湖北', '亲子出游', '秋季', 6, 3, 906.00, '否', 4, '6月去的神农架动植物标本馆，一个人出行。地点在神农架，地铁到达方便，现场人流量适中。这次玩了3天，人均花费约906元，氛围感不错。景点印象：收藏了神农架植物标本2000多种，12000多号，共同显示了神农架植物所特有的古老性、丰富性和复杂性三大特点，共同构成了一座别致的物种基因库，珙桐、香果、银杏、连香、篦子杉等60余种孓遗物种，素有活化石之称；头顶一颗珠、文王一枝笔、江边一碗…整体感受是还蛮满意，可以安排半天到一天。二刷意愿：否。', '0%', 72);
