INSERT INTO `travel_review` VALUES (3653, 'TR003653', '莽措湖', '昌都', '西藏', '深度游', '春季', 1, 2, 349.00, '否', 2, '1月去的莽措湖，情侣出行。地点在昌都，自驾停车需要提前规划，现场人流量适中。这次玩了2天，人均花费约349元，拍照很出片。景点印象：莽措湖位于芒康中部莽岭乡境内，距县城 90 公里 ，国道 214 线往北 60 公里 处，海拔 4313 米 ，湖水面积 20 多平方公里。整体感受是体验偏一般，建议谨慎前往。二刷意愿：否。', '6%', 25);
INSERT INTO `travel_review` VALUES (3654, 'TR003654', '木兰陂', '莆田', '福建', '深度游', '春季', 2, 2, 865.00, '是', 4, '2月去的木兰陂，一个人出行。地点在莆田，地铁到达方便，现场人流量适中。这次玩了2天，人均花费约865元，历史文化气息浓。景点印象：整体环境还算干净整体感受是整体不错，推荐来看看。二刷意愿：是。', '1%', 94);
INSERT INTO `travel_review` VALUES (3655, 'TR003655', '小悬空寺', '大同', '山西', '拍照旅行', '冬季', 11, 2, 687.00, '否', 4, '11月去的小悬空寺，和家人出行。地点在大同，地铁到达方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约687元，氛围感不错。景点印象：山西广灵县城南有座壶山，上有大士庵和水神庙的合称“小悬空寺”。寺庙建于山巅。创建于北魏时期，现存为明代时期遗物。\n小悬空寺为平面八角形的建筑，有山门、正殿、东西殿、钟楼等。殿堂的雕刻手法细腻，钟楼结构玲珑，前有掖门穿过，周围设有回…整体感受是还蛮满意，可以安排半天到一天。二刷意愿：否。', '0%', 47);
INSERT INTO `travel_review` VALUES (3656, 'TR003656', '阁皂山', '宜春', '江西', '周末短途', '春季', 2, 5, 1402.00, '否', 4, '2月去的阁皂山，和朋友出行。地点在宜春，自驾停车需要提前规划，现场人流量适中。这次玩了5天，人均花费约1402元，历史文化气息浓。景点印象：阁皂山位于樟树市东南20公里处的东岸，绵亘200余里，因其“形如阁，色如皂”而得名,相传道学家葛玄曾在此修真司道，后云游四海，最终仍回到阁皂山。\n葛玄曾在骆驼峰峰之侧修建卧云庵，筑坛产灶，炼丹八载，终于炼成“九转金丹”。他服丹“飞升”后…整体感受是体验挺好，可以安排半天到一天。二刷意愿：否。', '7%', 100);
