INSERT INTO `travel_review` VALUES (3719, 'TR003719', '灵岩景区', '温州', '浙江', '文化打卡', '春季', 12, 3, 775.00, '否', 4, '12月去的灵岩景区，和家人出行。地点在温州，打车比较省心，现场游客较多。这次玩了3天，人均花费约775元，夜景表现很好。景点印象：“雁荡三绝”中规模最小，却景观丰富的一处，奇峰怪石让人浮想联翩。 看一场“灵岩飞渡”表演，崖壁和钢索上的高难度表演夺人眼球。 探访卧龙谷，在断肠崖回味《神雕侠侣》中小龙女纵身一跃的场景。整体感受是整体不错，可以安排半天到一天。二刷意愿：否。', '0%', 67);
