INSERT INTO `travel_review` VALUES (3722, 'TR003722', '神象山', '汕尾', '广东', '周末短途', '春季', 12, 4, 1265.00, '是', 5, '12月去的神象山，和朋友出行。地点在汕尾，地铁到达方便，现场游客较多。这次玩了4天，人均花费约1265元，氛围感不错。景点印象：神象山公园风景区位于南万镇南天湖旁，海拔653米！整座山因酷似一头大象而得名！山上树木莽莽苍苍！百年老树随处可见！说不出名的奇花异草争奇斗艳。为了游客能近距离的亲近大自然！观赏雄伟神象山，特开辟了登山险道！架设长200多米的登山木梯通往…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 109);
