INSERT INTO `travel_review` VALUES (3728, 'TR003728', '鼓浪屿', '厦门', '福建', '亲子出游', '春季', 2, 3, 846.00, '是', 5, '2月去的鼓浪屿，和朋友出行。地点在厦门，打车比较省心，现场高峰时段比较拥挤。这次玩了3天，人均花费约846元，拍照很出片。景点印象：世界文化遗产，特色店铺众多，建筑漂亮，生活气息和文艺范儿并重。整体感受是挺惊喜，很推荐。二刷意愿：是。', '68%', 63);
INSERT INTO `travel_review` VALUES (3729, 'TR003729', '石庙', '梧州', '广西', '亲子出游', '夏季', 3, 6, 1560.00, '是', 5, '3月去的石庙，情侣出行。地点在梧州，公交换乘方便，现场人不算多。这次玩了6天，人均花费约1560元，氛围感不错。景点印象：石庙——又称盘古庙，是岑溪市的一大自然景点，也是岑溪市最近正在大力开发的景点之一。石庙位于岑溪市水汶镇西南部，相对高度950米，占地面积170多亩，石庙四周群山怀抱，连绵起伏，直通云间。一条小溪由左向右环绕着山脚，与黄华河相接，连成一体…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 91);
INSERT INTO `travel_review` VALUES (3730, 'TR003730', '木格措', '甘孜藏族自治州', '四川', '拍照旅行', '春季', 2, 1, 455.00, '是', 5, '2月去的木格措，一个人出行。地点在甘孜藏族自治州，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约455元，历史文化气息浓。景点印象：清澈的湖水、蔚蓝的天空和清新的空气让人流连忘返。整体感受是超出预期，值得专门打卡。二刷意愿：是。', '7%', 90);
INSERT INTO `travel_review` VALUES (3731, 'TR003731', '博鳌高尔夫乡村俱乐部', '琼海', '海南', '文化打卡', '秋季', 8, 1, 415.00, '否', 2, '8月去的博鳌高尔夫乡村俱乐部，和朋友出行。地点在琼海，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约415元，拍照很出片。景点印象：博鳌高尔夫乡村俱乐部是博鳌大型综合性国际旅游度假开发区的重点项目。由于得天独厚的地理条件和开发人的精心设计，巧夺天工，经过两年多的建设和试营业，一座中国业内首创、亚洲唯一的全岛型林克斯风格的高尔夫球场终于在万泉河入海口处的沙坡岛上…整体感受是没达到预期，不建议高峰来。二刷意愿：否。', '1%', 76);
