INSERT INTO `travel_review` VALUES (3773, 'TR003773', '买力克阿瓦提古城', '和田', '新疆', '文化打卡', '夏季', 5, 1, 422.00, '否', 5, '5月去的买力克阿瓦提古城，情侣出行。地点在和田，公交换乘方便，现场游客较多。这次玩了1天，人均花费约422元，夜景表现很好。景点印象：位于和田城东南25公里的玉龙喀什河西岸，当地人称“什斯比尔”。1962年定为自治区重点文物保护单位。遗址南北长十公里，东西宽两公里。该城建于1500至1600年以前。\n遗址西侧沙山环立，冈峦起伏，南面昆仑山脉影影绰绰，高入云端，东面玉龙喀什河蜿…整体感受是超出预期，以后还会来。二刷意愿：否。', '0%', 103);
