INSERT INTO `travel_review` VALUES (3817, 'TR003817', '澄水洞旅游区', '咸宁', '湖北', '亲子出游', '冬季', 9, 1, 680.00, '是', 5, '9月去的澄水洞旅游区，和家人出行。地点在咸宁，公交换乘方便，现场游客较多。这次玩了1天，人均花费约680元，氛围感不错。景点印象：1968年，中苏边境局势紧张，国家准备应战，毛泽东主席下令汪东兴在鄂南为他修建战时住房。澄水洞地下工程，即是在这种背景下由当时的军委参谋长于1969年1月31日签署命令，亲自选址后始建的地下军事工程。整个工程神密而传奇，原计划投资3亿元，后因…整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '0%', 109);
INSERT INTO `travel_review` VALUES (3818, 'TR003818', '白马寺', '洛阳', '河南', '文化打卡', '冬季', 11, 1, 486.00, '否', 5, '11月去的白马寺，情侣出行。地点在洛阳，公交换乘方便，现场人流量适中。这次玩了1天，人均花费约486元，历史文化气息浓。景点印象：中国佛教的祖庭，寺内的“镇寺之宝”——元代的“夹贮干漆造像”，已有700年的历史。 观赏珍贵碑碣——元代书法家赵孟頫手书的《洛京白马寺祖庭记》。整体感受是特别满意，以后还会来。二刷意愿：否。', '49%', 70);
