INSERT INTO `travel_review` VALUES (3875, 'TR003875', '云石山', '赣州', '江西', '深度游', '冬季', 9, 2, 485.00, '是', 5, '9月去的云石山，情侣出行。地点在赣州，地铁到达方便，现场游客较多。这次玩了2天，人均花费约485元，夜景表现很好。景点印象：云石山位于瑞金市西南15公里。1934年7月临时中央政府从沙洲坝迁驻此地小山上的云山古寺，山中风景优美。1934年10月，中央机关编为红军中央纵队，从云石山出发开始长征，因而云石山被称为“长征第一山”。整体感受是特别满意，很推荐。二刷意愿：是。', '0%', 73);
