INSERT INTO `travel_review` VALUES (3915, 'TR003915', '石海湾青皮林自然保护区', '万宁', '海南', '拍照旅行', '秋季', 8, 1, 336.00, '否', 5, '8月去的石海湾青皮林自然保护区，和家人出行。地点在万宁，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约336元，历史文化气息浓。景点印象：1988年8月24日礼纪青皮林自然保护区被海南省人民政府宣布为海南省第一批省级重点风景名胜区和自然保护区。面积1．6万亩，建于1980年7月。建立此保护区的主要目的，在于保护海南热带森林的贵重树种青皮树。青皮树为龙脑香料，树高可达30米，胸径可达…整体感受是超出预期，很推荐。二刷意愿：否。', '0%', 83);
