INSERT INTO `travel_review` VALUES (3935, 'TR003935', '茶文化风情园', '临沧', '云南', '文化打卡', '春季', 2, 3, 1160.00, '否', 5, '2月去的茶文化风情园，情侣出行。地点在临沧，地铁到达方便，现场人不算多。这次玩了3天，人均花费约1160元，氛围感不错。景点印象：景点本身有一定特色整体感受是特别满意，以后还会来。二刷意愿：否。', '0%', 91);
INSERT INTO `travel_review` VALUES (3936, 'TR003936', '雷台汉墓', '武威', '甘肃', '城市漫游', '夏季', 4, 2, 705.00, '否', 3, '4月去的雷台汉墓，和朋友出行。地点在武威，地铁到达方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约705元，历史文化气息浓。景点印象：是1969年10月在雷台下发现的一处东汉晚期的大型砖石墓葬，因出土了文物珍宝，中国旅游标志铜奔马而著名。雷台是古代祭祀雷神的地方，因在一高约十米的土台上建有明朝中期建造的雷祖观而得名。据出土马俑胸前铭文记载，雷台汉墓系“守张掖长张君”之…整体感受是还可以，别抱太高期待。二刷意愿：否。', '67%', 51);
INSERT INTO `travel_review` VALUES (3937, 'TR003937', '龙门报国寺', '资阳', '四川', '深度游', '冬季', 11, 5, 1338.00, '是', 5, '11月去的龙门报国寺，情侣出行。地点在资阳，公交换乘方便，现场人流量适中。这次玩了5天，人均花费约1338元，夜景表现很好。景点印象：四川省乐至县龙门报国寺，始建于隋开皇二年（589），距今1400余年。报国寺位于乐至县龙门乡，距县城18公里。现存唐五代石碑二通；大小磨岩造像十余龛，造像考究，集各地造像之精粹，山水之灵气，给人以无限祥和与安宁；千年古树，壁立怪石，蔚为奇…整体感受是特别满意，以后还会来。二刷意愿：是。', '0%', 48);
