INSERT INTO `travel_review` VALUES (3939, 'TR003939', '三叠泉', '九江', '江西', '亲子出游', '夏季', 3, 5, 1374.00, '否', 5, '3月去的三叠泉，情侣出行。地点在九江，公交换乘方便，现场人流量适中。这次玩了5天，人均花费约1374元，拍照很出片。景点印象：号称“庐山第一奇观”，可以看到瀑布冲击三级盘石形成“三叠”。 下到三叠泉谷底，仰望瀑布飞洒而下，壮观震撼。整体感受是挺惊喜，以后还会来。二刷意愿：否。', '30%', 94);
INSERT INTO `travel_review` VALUES (3940, 'TR003940', '铁佛寺', '沧州', '河北', '周末短途', '春季', 1, 1, 463.00, '是', 4, '1月去的铁佛寺，一个人出行。地点在沧州，公交换乘方便，现场游客较多。这次玩了1天，人均花费约463元，历史文化气息浓。景点印象：观摩千年古寺，赏8米高巨大铁佛，领略佛教文化的悠久历史。整体感受是体验挺好，可以安排半天到一天。二刷意愿：是。', '14%', 55);
