INSERT INTO `travel_review` VALUES (3961, 'TR003961', '青山湖', '白山', '吉林', '亲子出游', '秋季', 7, 2, 821.00, '是', 5, '7月去的青山湖，一个人出行。地点在白山，地铁到达方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约821元，历史文化气息浓。景点印象：青山湖是省级名胜景点，位于白山市城郊2.5公里处， 是截河而成的人工湖，水质纯净，水面平稳，两岸众山耸立，山青水秀，植被完整，林相优美，是避暑游玩、垂钓的好去处。在这里既可游泳又可垂钓，青山湖水上廊亭曲曲折折，山上庙宇若隐若现，景区内…整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 64);
