INSERT INTO `travel_review` VALUES (3975, 'TR003975', '华安军工旅游区', '鹤岗', '黑龙江', '周末短途', '春季', 2, 4, 1146.00, '否', 5, '2月去的华安军工旅游区，情侣出行。地点在鹤岗，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了4天，人均花费约1146元，夜景表现很好。景点印象：座落在黑龙江上的名山岛，南临萝北口岸，北望俄罗斯的阿穆尔捷特。江水环绕，古木森森，鸟鸣嘤嘤，野趣横生，一派质朴、粗犷、天然无饰的自然生态风光。名山岛为江水中冲积而形成的岛屿，形成于清代末年，民国初期已成岛屿。岛上土质肥沃，树木成林…整体感受是挺惊喜，很推荐。二刷意愿：否。', '0%', 90);
