INSERT INTO `travel_review` VALUES (4040, 'TR004040', '沱江', '湘西', '湖南', '城市漫游', '春季', 2, 4, 1352.00, '是', 4, '2月去的沱江，和朋友出行。地点在湘西，公交换乘方便，现场高峰时段比较拥挤。这次玩了4天，人均花费约1352元，历史文化气息浓。景点印象：在沱江上泛舟，两边是百年历史的苗家吊脚楼，沿途有跳岩、古城墙、虹桥等凤古城的标志性景点。 清晨的沱江边，雾气重重，当地居民咚咚咚的在江边捶洗衣物。 沱江畔的的吊脚楼内，是古城客栈和餐馆集中的地方。整体感受是还蛮满意，可以安排半天到一天。二刷意愿：是。', '3%', 98);
