INSERT INTO `travel_review` VALUES (4050, 'TR004050', '南山文化旅游区', '三亚', '海南', '文化打卡', '冬季', 11, 5, 1607.00, '是', 5, '11月去的南山文化旅游区，情侣出行。地点在三亚，打车比较省心，现场高峰时段比较拥挤。这次玩了5天，人均花费约1607元，历史文化气息浓。景点印象：三亚礼佛必去之处，108米高的“南山海上观音”让人叹为观止。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '21%', 97);
INSERT INTO `travel_review` VALUES (4051, 'TR004051', '泊头清真寺', '沧州', '河北', '亲子出游', '春季', 2, 4, 1219.00, '否', 5, '2月去的泊头清真寺，和朋友出行。地点在沧州，地铁到达方便，现场人流量适中。这次玩了4天，人均花费约1219元，历史文化气息浓。景点印象：探访风格独特的清真寺建筑，领略伊斯兰教的文化风貌。整体感受是超出预期，以后还会来。二刷意愿：否。', '0%', 101);
