INSERT INTO `travel_review` VALUES (4053, 'TR004053', '南水水库', '韶关', '广东', '拍照旅行', '夏季', 3, 1, 634.00, '否', 3, '3月去的南水水库，和朋友出行。地点在韶关，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约634元，氛围感不错。景点印象：南水水库位于乳源县城西南16公里处，是广东省第二大人工湖，南水湖水质晶莹透碧，沿岸青山连绵，瑶寨竹木楼掩映在绿树丛中。在水库西北一个面积约一万亩的半岛上，建有中国南方第一个狩猎场。整体感受是体验一般，避开高峰更好。二刷意愿：否。', '3%', 77);
