INSERT INTO `travel_review` VALUES (4075, 'TR004075', '欣欣生态农业观光园', '淮安', '江苏', '亲子出游', '夏季', 5, 2, 527.00, '是', 5, '5月去的欣欣生态农业观光园，和家人出行。地点在淮安，打车比较省心，现场人流量适中。这次玩了2天，人均花费约527元，氛围感不错。景点印象：淮安市欣欣生态农业观光园位于涟水县保滩镇十堡村，距淮安市商业中心约12公里，离规划中的淮安机场约15公里，与淮安经济开发区毗邻，紧靠富士康、明基等大集团。京沪高速、淮涟一级公路交汇于此，古黄河穿境奔流。是实践传统农业向现代高效农业和多…整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 102);
