INSERT INTO `travel_review` VALUES (4106, 'TR004106', '秦家大院', '南充', '四川', '亲子出游', '春季', 1, 4, 729.00, '是', 5, '1月去的秦家大院，和家人出行。地点在南充，打车比较省心，现场人流量适中。这次玩了4天，人均花费约729元，氛围感不错。景点印象：秦家大院位于阆中古城南街，始建于清初，占地1000多平方米，是一座有30多间房屋的串株式三进、四合院，为古城中现存气势较为宏伟的民居大院。 秦家大院始建于清初。清后期，从甘肃天水迁居阆中一秦氏商人从王姓手中买下这座大院，1935年红军曾在此…整体感受是挺惊喜，很推荐。二刷意愿：是。', '4%', 71);
