INSERT INTO `travel_review` VALUES (4117, 'TR004117', '茂名江滨公园', '茂名', '广东', '深度游', '春季', 2, 1, 433.00, '是', 5, '2月去的茂名江滨公园，情侣出行。地点在茂名，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约433元，历史文化气息浓。景点印象：茂名江滨公园不足与一些大气的公园相比较，但是园内小巧的亭台楼阁却也和秀气的江南园林有点类似。树木葱茏的江滨公园不收门票，是一个消暑的好去处。从公园的湖边登到江堤上，视野更加开阔，茂名城的景色更显亮丽，公园增加了这座城市的亲和力。整体感受是超出预期，值得专门打卡。二刷意愿：是。', '0%', 91);
INSERT INTO `travel_review` VALUES (4118, 'TR004118', '可可托海景区', '阿勒泰', '新疆', '深度游', '夏季', 3, 5, 1419.00, '是', 4, '3月去的可可托海景区，情侣出行。地点在阿勒泰，打车比较省心，现场游客较多。这次玩了5天，人均花费约1419元，拍照很出片。景点印象：观赏峡谷间清澈的河流和茂密树林，环境优美。整体感受是体验挺好，推荐来看看。二刷意愿：是。', '100%', 48);
