INSERT INTO `travel_review` VALUES (4125, 'TR004125', '花山湖彩云洞', '曲靖', '云南', '城市漫游', '秋季', 6, 4, 1070.00, '否', 3, '6月去的花山湖彩云洞，和朋友出行。地点在曲靖，打车比较省心，现场人不算多。这次玩了4天，人均花费约1070元，氛围感不错。景点印象：“水晶流成瀑，玉石堆成山，岩石结成冰，翡翠串成帘。”这是曲靖市沾益县当地人对花山湖畔彩云洞的赞美。在云南众多的喀斯特溶洞中，彩云洞也许并不为人们熟悉，但它却是一个非常幽深、奇特、五彩斑斓的地下溶洞，最近才逐步开发而展露出它的璀璨光…整体感受是还可以，别抱太高期待。二刷意愿：否。', '0%', 38);
