INSERT INTO `travel_review` VALUES (4139, 'TR004139', '白马寺', '抚州', '江西', '亲子出游', '夏季', 4, 1, 360.00, '否', 5, '4月去的白马寺，情侣出行。地点在抚州，公交换乘方便，现场游客较多。这次玩了1天，人均花费约360元，氛围感不错。景点印象：在金溪黄通乡黄通村东南5公里的白马峰上，始建于北宋初年。相传本地一江姓进士隐居家后，在山顶盖起一屋，取名“玉马祠”，后一吴僧在屋旁建起一幢寺庙。一日，吴僧迎来一位身骑白马的道长，二人对话片刻，见栓在寺外的白马腾空而起，道长也无踪无…整体感受是特别满意，值得专门打卡。二刷意愿：否。', '0%', 114);
