INSERT INTO `travel_review` VALUES (4142, 'TR004142', '青州博物馆', '潍坊', '山东', '亲子出游', '夏季', 5, 3, 724.00, '否', 5, '5月去的青州博物馆，情侣出行。地点在潍坊，自驾停车需要提前规划，现场游客较多。这次玩了3天，人均花费约724元，夜景表现很好。景点印象：馆藏龙兴寺石刻佛教造像、全国唯一的殿试卷真迹等稀世珍宝。 国内藏品最多的县级博物馆，青州出土的玉器、石刻等文物众多。整体感受是挺惊喜，很推荐。二刷意愿：否。', '6%', 69);
INSERT INTO `travel_review` VALUES (4143, 'TR004143', '五道幢', '南阳', '河南', '文化打卡', '春季', 1, 1, 293.00, '否', 5, '1月去的五道幢，一个人出行。地点在南阳，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约293元，夜景表现很好。景点印象：景点本身有一定特色整体感受是超出预期，值得专门打卡。二刷意愿：否。', '2%', 74);
INSERT INTO `travel_review` VALUES (4144, 'TR004144', '姜楼镇乡村赋能展示中心', '滨州', '山东', '周末短途', '春季', 12, 1, 170.00, '否', 4, '12月去的姜楼镇乡村赋能展示中心，一个人出行。地点在滨州，地铁到达方便，现场人不算多。这次玩了1天，人均花费约170元，历史文化气息浓。景点印象：景点本身有一定特色整体感受是还蛮满意，推荐来看看。二刷意愿：否。', '0%', 77);
INSERT INTO `travel_review` VALUES (4145, 'TR004145', '卡若遗址', '昌都', '西藏', '深度游', '春季', 12, 1, 210.00, '否', 4, '12月去的卡若遗址，和朋友出行。地点在昌都，地铁到达方便，现场人不算多。这次玩了1天，人均花费约210元，拍照很出片。景点印象：卡诺遗址位于中国西南部西藏自治区的昌都县,是一处新石器时代晚期文化遗址，年代为距今4000～5000年。 卡若遗址发现于1978年，遗址总面积约1万平方米，是考古界公认的西藏三大原始文化遗址之一。整体感受是体验挺好，周末来刚好。二刷意愿：否。', '1%', 76);
INSERT INTO `travel_review` VALUES (4146, 'TR004146', '碧水岩', '贺州', '广西', '文化打卡', '春季', 12, 2, 579.00, '否', 4, '12月去的碧水岩，和家人出行。地点在贺州，地铁到达方便，现场人不算多。这次玩了2天，人均花费约579元，氛围感不错。景点印象：自治区级风景名胜区。位于国道323线和国道207线的交汇处，碧水岩风景区距离国道323线仅2千米，景区距贺州市区30千米，钟山县城14千米。是国内罕见的特大溶洞景观。于1990年初对外经营。\n碧水岩总规划面积450亩，其中有水面150亩。岩洞主线由18个大…整体感受是还蛮满意，推荐来看看。二刷意愿：否。', '0%', 78);
INSERT INTO `travel_review` VALUES (4147, 'TR004147', '三门峡大坝风景区', '三门峡', '河南', '亲子出游', '夏季', 5, 3, 726.00, '是', 4, '5月去的三门峡大坝风景区，一个人出行。地点在三门峡，自驾停车需要提前规划，现场人不算多。这次玩了3天，人均花费约726元，拍照很出片。景点印象：整体环境还算干净整体感受是整体不错，推荐来看看。二刷意愿：是。', '32%', 55);
