INSERT INTO `travel_review` VALUES (4149, 'TR004149', '刘邓大军挺进大别山第一纵队大胡岗革命旧址', '信阳', '河南', '拍照旅行', '秋季', 6, 6, 1482.00, '是', 5, '6月去的刘邓大军挺进大别山第一纵队大胡岗革命旧址，情侣出行。地点在信阳，公交换乘方便，现场高峰时段比较拥挤。这次玩了6天，人均花费约1482元，拍照很出片。景点印象：周边配套比较齐全整体感受是特别满意，以后还会来。二刷意愿：是。', '0%', 65);
INSERT INTO `travel_review` VALUES (4150, 'TR004150', '黄河大佛', '济源', '河南', '深度游', '冬季', 11, 1, 577.00, '是', 5, '11月去的黄河大佛，情侣出行。地点在济源，公交换乘方便，现场人不算多。这次玩了1天，人均花费约577元，历史文化气息浓。景点印象：黄河大佛\n在孟良寨对面崖壁上，有一石崖酷似大佛屹立在黄河峡谷岸边，称之为黄河大佛。大佛高80余米，宝相庄严、浑然天成，令世人叹为观之。有趣的是，由于小浪底水库蓄水，黄河大佛下部被淹没水中，成为天下第一“浴佛”了。整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 47);
INSERT INTO `travel_review` VALUES (4151, 'TR004151', '化城寺', '池州', '安徽', '深度游', '冬季', 10, 2, 492.00, '否', 4, '10月去的化城寺，一个人出行。地点在池州，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约492元，拍照很出片。景点印象：知名的九华山历史博物馆，是九华山的开山祖寺，同时也是地藏菩萨道场。整体感受是体验挺好，推荐来看看。二刷意愿：否。', '26%', 74);
