INSERT INTO `travel_review` VALUES (4160, 'TR004160', '锦江瀑布', '白山', '吉林', '拍照旅行', '夏季', 5, 5, 1276.00, '是', 5, '5月去的锦江瀑布，一个人出行。地点在白山，地铁到达方便，现场游客较多。这次玩了5天，人均花费约1276元，拍照很出片。景点印象：锦江瀑布又叫梯河瀑布，是二级瀑布，两级落差共70米。巨大水流聚然从黑褐色的火山岩陡崖上跌落，激起白色的水雾。瀑布声如雷鸣，水花四溅，靠近瀑布，就能感到水雾缭绕，全身凉透的感觉。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '3%', 85);
INSERT INTO `travel_review` VALUES (4161, 'TR004161', '安昌古镇', '绍兴', '浙江', '亲子出游', '夏季', 5, 1, 430.00, '是', 5, '5月去的安昌古镇，一个人出行。地点在绍兴，公交换乘方便，现场人流量适中。这次玩了1天，人均花费约430元，氛围感不错。景点印象：上过《舌尖上的中国》的安昌腊肠和仁昌酱油，来这里一定要尝尝。整体感受是挺惊喜，很推荐。二刷意愿：是。', '14%', 79);
