INSERT INTO `travel_review` VALUES (4163, 'TR004163', '海上田园', '深圳', '广东', '亲子出游', '秋季', 7, 2, 595.00, '是', 3, '7月去的海上田园，一个人出行。地点在深圳，地铁到达方便，现场人不算多。这次玩了2天，人均花费约595元，氛围感不错。景点印象：可以看水乡田园风貌和红树林湿地景观，逛仿古水上集市，吃农家菜，还有很多娱乐项目。整体感受是体验一般，避开高峰更好。二刷意愿：是。', '0%', 48);
INSERT INTO `travel_review` VALUES (4164, 'TR004164', '西递', '黄山', '安徽', '深度游', '冬季', 9, 3, 1261.00, '是', 5, '9月去的西递，和朋友出行。地点在黄山，地铁到达方便，现场人不算多。这次玩了3天，人均花费约1261元，夜景表现很好。景点印象：看胡文光牌坊、敬爱堂等精美的徽派建筑，欣赏建筑上的徽派三雕。整体感受是超出预期，很推荐。二刷意愿：是。', '16%', 60);
INSERT INTO `travel_review` VALUES (4165, 'TR004165', '七台河王尔东非遗博览馆', '七台河', '黑龙江', '文化打卡', '冬季', 10, 7, 1911.00, '是', 5, '10月去的七台河王尔东非遗博览馆，和家人出行。地点在七台河，自驾停车需要提前规划，现场人不算多。这次玩了7天，人均花费约1911元，氛围感不错。景点印象：周边配套比较齐全整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 48);
INSERT INTO `travel_review` VALUES (4166, 'TR004166', '遵义会议会址', '遵义', '贵州', '城市漫游', '秋季', 7, 3, 978.00, '是', 5, '7月去的遵义会议会址，情侣出行。地点在遵义，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了3天，人均花费约978元，拍照很出片。景点印象：在这里缅怀革命先烈，接受爱国主义教育。整体感受是挺惊喜，很推荐。二刷意愿：是。', '44%', 84);
INSERT INTO `travel_review` VALUES (4167, 'TR004167', '彭城广场', '徐州', '江苏', '拍照旅行', '秋季', 6, 4, 1000.00, '是', 4, '6月去的彭城广场，和家人出行。地点在徐州，自驾停车需要提前规划，现场人流量适中。这次玩了4天，人均花费约1000元，氛围感不错。景点印象：周边配套比较齐全整体感受是整体不错，可以安排半天到一天。二刷意愿：是。', '7%', 39);
INSERT INTO `travel_review` VALUES (4168, 'TR004168', '九天大峡谷', '莱芜', '山东', '文化打卡', '春季', 2, 6, 1510.00, '否', 5, '2月去的九天大峡谷，情侣出行。地点在莱芜，地铁到达方便，现场人不算多。这次玩了6天，人均花费约1510元，历史文化气息浓。景点印象：这里有高山之巅的淳朴民俗风情，有古老原始的深谷幽林，有高峡平湖的秀美景致。在蓝天白云、青山碧水的映衬下，整个村落如云中山寨、人间仙境，故被誉为“天上人家”。谷内呈原生状态，飞瀑、流泉、奇石、险峰、密林，多姿多彩，适宜探险、观光、避…整体感受是特别满意，以后还会来。二刷意愿：否。', '0%', 89);
INSERT INTO `travel_review` VALUES (4169, 'TR004169', '磨盘山', '吉林市', '吉林', '深度游', '春季', 2, 1, 555.00, '是', 5, '2月去的磨盘山，和家人出行。地点在吉林市，公交换乘方便，现场游客较多。这次玩了1天，人均花费约555元，拍照很出片。景点印象：磨盘山又叫小磨盘山，在丰满区前二道乡王相村境内。距市区15公里，总面积10平方公里。磨盘山顶峰形状如磨盘，因此而得名。该山南北走向，南北峰对峙，南侧面为长山顶，北侧为尖山顶。北侧主峰海拔783.8米。磨盘山山势陡峻。峰奇石秀，林木茂密，狼…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 85);
INSERT INTO `travel_review` VALUES (4170, 'TR004170', '华安军工旅游区', '鹤岗', '黑龙江', '亲子出游', '冬季', 10, 4, 1345.00, '否', 4, '10月去的华安军工旅游区，和朋友出行。地点在鹤岗，公交换乘方便，现场游客较多。这次玩了4天，人均花费约1345元，历史文化气息浓。景点印象：座落在黑龙江上的名山岛，南临萝北口岸，北望俄罗斯的阿穆尔捷特。江水环绕，古木森森，鸟鸣嘤嘤，野趣横生，一派质朴、粗犷、天然无饰的自然生态风光。名山岛为江水中冲积而形成的岛屿，形成于清代末年，民国初期已成岛屿。岛上土质肥沃，树木成林…整体感受是体验挺好，周末来刚好。二刷意愿：否。', '0%', 71);
