INSERT INTO `travel_review` VALUES (4222, 'TR004222', '女娲城址', '周口', '河南', '城市漫游', '冬季', 9, 2, 840.00, '否', 5, '9月去的女娲城址，情侣出行。地点在周口，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了2天，人均花费约840元，拍照很出片。景点印象：女娲，是我国古代神话传说中的人类始祖，她抟泥为人、化育万物、炼石补天并发明了笙簧乐器，对此《世本作篇》留有记载。《说文》曰：“娲，古之神圣女，化万物者也”。中国考古学者认为，古代传说中的女娲氏是部落首领，属仰韶文化，当在六七年之前…整体感受是超出预期，很推荐。二刷意愿：否。', '33%', 103);
INSERT INTO `travel_review` VALUES (4223, 'TR004223', '黑里河', '赤峰', '内蒙古', '深度游', '夏季', 4, 4, 1203.00, '否', 5, '4月去的黑里河，和朋友出行。地点在赤峰，打车比较省心，现场高峰时段比较拥挤。这次玩了4天，人均花费约1203元，拍照很出片。景点印象：“山深闻唤鹿，林黑自生风。松壑寒愈响，水溪咽复通“——黑里河是国家级自然保护区，被称为”塞外的西双版纳“。整体感受是超出预期，以后还会来。二刷意愿：否。', '0%', 67);
