INSERT INTO `travel_review` VALUES (4227, 'TR004227', '阳朔', '桂林', '广西', '城市漫游', '秋季', 6, 4, 1127.00, '是', 3, '6月去的阳朔，和家人出行。地点在桂林，自驾停车需要提前规划，现场游客较多。这次玩了4天，人均花费约1127元，历史文化气息浓。景点印象：“桂林山水甲天下，阳朔堪称甲桂林”, 阳朔绝无仅有的山水风光、独具魅力的地方文化，古往今来吸引了许多文人墨客、名流显要，全世界150多个国家和地区的300余名国家元首、政界要人曾驻足阳朔流连忘返。整体感受是中规中矩，避开高峰更好。二刷意愿：是。', '15%', 59);
