INSERT INTO `travel_review` VALUES (4251, 'TR004251', '仙堂寺', '长治', '山西', '拍照旅行', '冬季', 10, 3, 730.00, '否', 5, '10月去的仙堂寺，一个人出行。地点在长治，地铁到达方便，现场游客较多。这次玩了3天，人均花费约730元，历史文化气息浓。景点印象：在山西襄垣县城东北25公里仙堂山腰。四面环山，松柏苍翠，泉水蜿蜒寺侧，环境清静优美。寺址内外，五泉涌出，故又名五龙寺。创建年代不祥。相传某夜风寸雨大作，飞砂走石，林木倾坏，人呼马叫，翌日寺成，山门横额“仙堂”。明清两代屡有修葺，现存…整体感受是超出预期，很推荐。二刷意愿：否。', '0%', 75);
