INSERT INTO `travel_review` VALUES (4330, 'TR004330', '百寿坊', '菏泽', '山东', '深度游', '春季', 1, 4, 1519.00, '否', 5, '1月去的百寿坊，和朋友出行。地点在菏泽，打车比较省心，现场人流量适中。这次玩了4天，人均花费约1519元，拍照很出片。景点印象：百狮坊，位于单县境内，为清朝乾隆年间修建。百寿坊因正间上方心环雕一百个不同书体的“寿”字而闻名。整体感受是超出预期，值得专门打卡。二刷意愿：否。', '7%', 53);
