INSERT INTO `travel_review` VALUES (4381, 'TR004381', '石庙', '梧州', '广西', '拍照旅行', '夏季', 4, 1, 114.00, '是', 4, '4月去的石庙，和朋友出行。地点在梧州，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约114元，历史文化气息浓。景点印象：石庙——又称盘古庙，是岑溪市的一大自然景点，也是岑溪市最近正在大力开发的景点之一。石庙位于岑溪市水汶镇西南部，相对高度950米，占地面积170多亩，石庙四周群山怀抱，连绵起伏，直通云间。一条小溪由左向右环绕着山脚，与黄华河相接，连成一体…整体感受是体验挺好，可以安排半天到一天。二刷意愿：是。', '0%', 57);
