INSERT INTO `travel_review` VALUES (4386, 'TR004386', '布柳河仙人桥景区', '百色', '广西', '深度游', '秋季', 8, 1, 138.00, '是', 5, '8月去的布柳河仙人桥景区，和朋友出行。地点在百色，自驾停车需要提前规划，现场游客较多。这次玩了1天，人均花费约138元，拍照很出片。景点印象：广西乐业县磨里乡弄流屯边上有一处幽境--布柳河，它在乐业大石围天坑群以北，距县城51公里。传说中布柳河是从远山流出的酒泉，因为壮语中“布”的意思是泉，“柳”的意思是酒。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '1%', 106);
