INSERT INTO `travel_review` VALUES (4401, 'TR004401', '康益泉温泉', '廊坊', '河北', '文化打卡', '秋季', 7, 2, 249.00, '是', 5, '7月去的康益泉温泉，一个人出行。地点在廊坊，公交换乘方便，现场人不算多。这次玩了2天，人均花费约249元，历史文化气息浓。景点印象：位于固安县牛驼镇南，106国道西侧，距北京70公里。独特的大型露天温泉浴池，水性温热而富含多种元素，浴之可温经通络、畅达气血，祛寒舒筋，消除疲劳，强身健体，疗效独特，常浴可使肌肤润滑光亮。室外桑拿室、康乐中心等设施相配套，能使步入康益…整体感受是超出预期，很推荐。二刷意愿：是。', '50%', 78);
INSERT INTO `travel_review` VALUES (4402, 'TR004402', '宜春明月山旅游区', '宜春', '江西', '深度游', '夏季', 4, 5, 893.00, '是', 5, '4月去的宜春明月山旅游区，情侣出行。地点在宜春，自驾停车需要提前规划，现场人不算多。这次玩了5天，人均花费约893元，夜景表现很好。景点印象：在秀美青山中登山锻炼，还有河流和众多瀑布可供观赏。 步行通过崖壁上的青云栈道，脚下是透明玻璃，非常刺激。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '53%', 86);
INSERT INTO `travel_review` VALUES (4403, 'TR004403', '云南省墨江北回归线标志园-观星亭', '普洱', '云南', '城市漫游', '秋季', 6, 2, 961.00, '否', 5, '6月去的云南省墨江北回归线标志园-观星亭，情侣出行。地点在普洱，地铁到达方便，现场人流量适中。这次玩了2天，人均花费约961元，夜景表现很好。景点印象：整体环境还算干净整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '0%', 79);
INSERT INTO `travel_review` VALUES (4404, 'TR004404', '玉皇殿', '鹤壁', '河南', '周末短途', '秋季', 7, 2, 1176.00, '否', 4, '7月去的玉皇殿，和朋友出行。地点在鹤壁，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了2天，人均花费约1176元，历史文化气息浓。景点印象：周边配套比较齐全整体感受是整体不错，周末来刚好。二刷意愿：否。', '0%', 65);
INSERT INTO `travel_review` VALUES (4405, 'TR004405', '高山村明清民居民俗文化旅游风景区', '玉林', '广西', '亲子出游', '春季', 2, 2, 589.00, '否', 5, '2月去的高山村明清民居民俗文化旅游风景区，和家人出行。地点在玉林，地铁到达方便，现场游客较多。这次玩了2天，人均花费约589元，氛围感不错。景点印象：高山村，人称“进士村”。村民明礼、诚信、好学，历代人才辈出。明万历年间（1574年），村里便办起了“独堆坡书房”，随后各个家族竞相开办启学蒙馆、大馆、私塾等，到清未全村共有15间。自清乾隆二十二年（1757）到清末150年间，高山村共出4名进士…整体感受是挺惊喜，很推荐。二刷意愿：否。', '12%', 78);
