INSERT INTO `travel_review` VALUES (4411, 'TR004411', '都市胡杨林', '北疆', '新疆', '文化打卡', '夏季', 4, 5, 1296.00, '否', 3, '4月去的都市胡杨林，情侣出行。地点在北疆，地铁到达方便，现场高峰时段比较拥挤。这次玩了5天，人均花费约1296元，拍照很出片。景点印象：景点本身有一定特色整体感受是中规中矩，避开高峰更好。二刷意愿：否。', '0%', 41);
INSERT INTO `travel_review` VALUES (4412, 'TR004412', '明故城墙', '济宁', '山东', '深度游', '春季', 12, 2, 80.00, '是', 4, '12月去的明故城墙，情侣出行。地点在济宁，打车比较省心，现场高峰时段比较拥挤。这次玩了2天，人均花费约80元，夜景表现很好。景点印象：城墙顶部建成中华民族传统文化教育长廊；城墙外是长达6公里的环城水系公园，形成一条休闲观光旅游带；城墙内为石板马道，形成一条民俗旅游线。整体感受是体验挺好，周末来刚好。二刷意愿：是。', '0%', 77);
INSERT INTO `travel_review` VALUES (4413, 'TR004413', '赵公山', '成都', '四川', '城市漫游', '春季', 1, 1, 340.00, '否', 4, '1月去的赵公山，和家人出行。地点在成都，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约340元，拍照很出片。景点印象：传说中财神赵公明归隐处，也是户外爱好者的理想登山之地。整体感受是整体不错，周末来刚好。二刷意愿：否。', '0%', 58);
INSERT INTO `travel_review` VALUES (4414, 'TR004414', '司徒小镇', '晋城', '山西', '拍照旅行', '春季', 1, 3, 609.00, '否', 2, '1月去的司徒小镇，和家人出行。地点在晋城，公交换乘方便，现场游客较多。这次玩了3天，人均花费约609元，拍照很出片。景点印象：漫步古色古香的小镇，欣赏震撼人心的千人打铁花表演，感受穿越千年的山西味道。整体感受是没达到预期，可考虑其他景点。二刷意愿：否。', '2%', 52);
INSERT INTO `travel_review` VALUES (4415, 'TR004415', '黑山头城址', '呼伦贝尔', '内蒙古', '拍照旅行', '春季', 1, 3, 886.00, '否', 4, '1月去的黑山头城址，情侣出行。地点在呼伦贝尔，自驾停车需要提前规划，现场人流量适中。这次玩了3天，人均花费约886元，氛围感不错。景点印象：黑山头城址是金、元时期的遗址，距今已经有700多年。整体感受是体验挺好，推荐来看看。二刷意愿：否。', '7%', 62);
INSERT INTO `travel_review` VALUES (4416, 'TR004416', '秦始皇帝陵博物院(兵马俑)', '西安', '陕西', '周末短途', '秋季', 7, 5, 1654.00, '是', 5, '7月去的秦始皇帝陵博物院(兵马俑)，情侣出行。地点在西安，公交换乘方便，现场人流量适中。这次玩了5天，人均花费约1654元，拍照很出片。景点印象：举世闻名的秦兵马俑，世界第八大奇迹，重现两千年前军队的姿态。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '66%', 92);
