INSERT INTO `travel_review` VALUES (4455, 'TR004455', '云杉坪', '丽江', '云南', '深度游', '冬季', 11, 6, 2072.00, '否', 4, '11月去的云杉坪，情侣出行。地点在丽江，打车比较省心，现场人不算多。这次玩了6天，人均花费约2072元，历史文化气息浓。景点印象：穿越茂密云杉丛林，在大草坪前观看雪峰，景色壮观优美。整体感受是还蛮满意，推荐来看看。二刷意愿：否。', '10%', 62);
INSERT INTO `travel_review` VALUES (4456, 'TR004456', '文庙', '内江', '四川', '亲子出游', '冬季', 11, 1, 260.00, '否', 3, '11月去的文庙，情侣出行。地点在内江，自驾停车需要提前规划，现场游客较多。这次玩了1天，人均花费约260元，氛围感不错。景点印象：资中文庙在资中县城北门外。北宋雍熙年间（984-987）始建于县城东街，清道光九年（1829）迁此重建。资中文庙占地7035平方米，建筑面积2191平方米。主体建筑及布局仿山东曲阜孔庙，灵星门、大成门、大成殿排列于南北中轴线上，东西厢房、钟楼、鼓楼…整体感受是还可以，按需选择。二刷意愿：否。', '0%', 31);
INSERT INTO `travel_review` VALUES (4457, 'TR004457', '禹帽峰', '临汾', '山西', '深度游', '夏季', 5, 1, 408.00, '是', 5, '5月去的禹帽峰，和家人出行。地点在临汾，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约408元，拍照很出片。景点印象：在壶口瀑布东岸，龙王庙后，有一座孤峰，犹如天上飘下的一顶帽子扣在壶口岸边。\n在夕阳余辉照射下，远远望去，它似乎在风中悠悠而动。在光线渐暗的时候，它又似乎飘飘欲下，颇有清幽之感。这座孤峰．就是石帽山，又叫“禹帽峰”。传说这座孤峰是禹…整体感受是超出预期，很推荐。二刷意愿：是。', '1%', 85);
