INSERT INTO `travel_review` VALUES (4460, 'TR004460', '古格王国遗址', '阿里', '西藏', '亲子出游', '夏季', 5, 2, 886.00, '否', 5, '5月去的古格王国遗址，和朋友出行。地点在阿里，地铁到达方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约886元，氛围感不错。景点印象：古格遗址内残存的壁画非常精美。 夕阳下的古格遗址雄浑沧桑，是摄友们最爱的场景。整体感受是超出预期，很推荐。二刷意愿：否。', '61%', 110);
