INSERT INTO `travel_review` VALUES (4464, 'TR004464', '念青唐古拉山', '那曲', '西藏', '城市漫游', '秋季', 7, 2, 778.00, '是', 5, '7月去的念青唐古拉山，情侣出行。地点在那曲，公交换乘方便，现场游客较多。这次玩了2天，人均花费约778元，拍照很出片。景点印象：念青唐古拉山位于中国西藏自治区，属断块山。西接冈底斯山脉，东南延伸与横断山脉伯舒拉岭相接，中部略为向北凸出，同时将西藏划分成藏北.藏南.臧东南三大区域。长700千米，终年白雪皑皑，云雾缭绕。整体感受是超出预期，很推荐。二刷意愿：是。', '10%', 68);
