INSERT INTO `travel_review` VALUES (4470, 'TR004470', '屈原碑林', '岳阳', '湖南', '深度游', '春季', 1, 2, 706.00, '是', 5, '1月去的屈原碑林，和朋友出行。地点在岳阳，公交换乘方便，现场游客较多。这次玩了2天，人均花费约706元，历史文化气息浓。景点印象：是汩罗市政府近年在屈原风景区进行的一项规模浩大、气势雄伟、结构恢宏的园林式工程。主体结构由离骚阁、天问坛、九歌台、九章馆、招魂堂等五个部分组成。以屈原忧国忧民、上下求索的爱国主义精神为主题，将屈原的全部作品串成一个整体。五个建筑均…整体感受是超出预期，值得专门打卡。二刷意愿：是。', '0%', 91);
INSERT INTO `travel_review` VALUES (4471, 'TR004471', '井冈山革命博物馆', '吉安', '江西', '城市漫游', '夏季', 4, 4, 1259.00, '是', 5, '4月去的井冈山革命博物馆，和朋友出行。地点在吉安，打车比较省心，现场高峰时段比较拥挤。这次玩了4天，人均花费约1259元，拍照很出片。景点印象：看着那些伟人们的遗物和足迹，缅怀革命先烈。 各种高科技手段，带领游人回到那个战火纷飞的年代。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '17%', 75);
