INSERT INTO `travel_review` VALUES (4490, 'TR004490', '中国客家博物馆', '梅州', '广东', '周末短途', '春季', 12, 5, 1505.00, '是', 5, '12月去的中国客家博物馆，情侣出行。地点在梅州，公交换乘方便，现场人流量适中。这次玩了5天，人均花费约1505元，拍照很出片。景点印象：中国最大的客家博物馆，内设1个主馆和3个分馆，记录了客家人的历史和特性，了解客家文化从这里开始。整体感受是超出预期，值得专门打卡。二刷意愿：是。', '15%', 46);
INSERT INTO `travel_review` VALUES (4491, 'TR004491', '隆德县城', '固原', '宁夏', '亲子出游', '春季', 1, 2, 834.00, '否', 5, '1月去的隆德县城，和家人出行。地点在固原，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了2天，人均花费约834元，历史文化气息浓。景点印象：隆德县城位于六盘山西5公里的甜水河南岸。这里地势开阔，\"坦为兵冲\"，为历代兵家用兵之地。秦、汉时期朝那县治古城遗址，位于彭阳县城西15公里处的古城镇境内。地处茹河与任山河交汇处的茹河北岸三角平川正中，东濒店洼水库，西临朝那湫，北依罗家…整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '0%', 72);
