INSERT INTO `travel_review` VALUES (4502, 'TR004502', '大地湾遗址', '天水', '甘肃', '深度游', '冬季', 11, 1, 251.00, '否', 2, '11月去的大地湾遗址，和家人出行。地点在天水，公交换乘方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约251元，拍照很出片。景点印象：参观大地湾博物馆，了解新石器时期仰韶文化的知识。 观看新石器时期的村落，感受古人的生活场景。整体感受是没达到预期，可考虑其他景点。二刷意愿：否。', '1%', 29);
INSERT INTO `travel_review` VALUES (4503, 'TR004503', '箭竹林', '神农架', '湖北', '城市漫游', '冬季', 10, 4, 1036.00, '是', 5, '10月去的箭竹林，情侣出行。地点在神农架，打车比较省心，现场游客较多。这次玩了4天，人均花费约1036元，拍照很出片。景点印象：主要在大神农架近峰顶一带。竹丛生长异常稠密，每平方米达120多株；竿细长，仅若手指粗，橙黄发亮，坚实而柔韧，古人用其作箭，故名。据初步统计，包括小神农架的竹林，达46万余亩，密密麻麻，重叠无垠。“山脚炎夏山岭春，山麓艳秋山顶冰”的神农…整体感受是超出预期，很推荐。二刷意愿：是。', '4%', 118);
