INSERT INTO `travel_review` VALUES (4548, 'TR004548', '平河梁森林公园', '安康', '陕西', '周末短途', '秋季', 8, 1, 625.00, '是', 5, '8月去的平河梁森林公园，和朋友出行。地点在安康，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约625元，氛围感不错。景点印象：宁陕县的平河梁森林公园，犹如一个梦幻般的童话世界，将大地点缀成绚丽多姿的四季之美--勃然生机的春日；热烈、奔放的夏天；含羞、甜蜜的金秋；圣洁、晶莹的冬季。可谓四季景致变，美景看不足。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '0%', 67);
