INSERT INTO `travel_review` VALUES (4619, 'TR004619', '泉州中山街', '泉州', '福建', '拍照旅行', '秋季', 7, 2, 807.00, '是', 5, '7月去的泉州中山街，一个人出行。地点在泉州，打车比较省心，现场人不算多。这次玩了2天，人均花费约807元，氛围感不错。景点印象：中山街是骑楼式建筑，于上个世纪初兴旺发达起来，现已经渐渐成长为繁华的商业街。整体感受是挺惊喜，很推荐。二刷意愿：是。', '2%', 64);
INSERT INTO `travel_review` VALUES (4620, 'TR004620', '九华天池', '池州', '安徽', '深度游', '秋季', 6, 2, 425.00, '否', 3, '6月去的九华天池，情侣出行。地点在池州，地铁到达方便，现场人流量适中。这次玩了2天，人均花费约425元，拍照很出片。景点印象：国家4A级旅游景区，被誉为江南的“阿里山”，是旅游、度假、休闲、观光的理想境地。整体感受是还可以，避开高峰更好。二刷意愿：否。', '6%', 48);
INSERT INTO `travel_review` VALUES (4621, 'TR004621', '华南虎保护区', '抚州', '江西', '周末短途', '春季', 12, 2, 1132.00, '是', 5, '12月去的华南虎保护区，和朋友出行。地点在抚州，公交换乘方便，现场游客较多。这次玩了2天，人均花费约1132元，历史文化气息浓。景点印象：宜黄县位于江西省东部，地处武夷山山脉与雩山山脉向抚河平原过渡地带。全县土地总面积19.44万公项，其中林业用地面积15.09万公项，占土地总面积的77.6％。境内有3条南北走向的山脉，东支主峰军峰山，海拔1760.9米，中支主峰鱼牙嶂，海拔1467.9米，…整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 102);
INSERT INTO `travel_review` VALUES (4622, 'TR004622', '涂家祠堂', '达州', '四川', '城市漫游', '春季', 2, 3, 706.00, '是', 5, '2月去的涂家祠堂，和家人出行。地点在达州，自驾停车需要提前规划，现场游客较多。这次玩了3天，人均花费约706元，拍照很出片。景点印象：周边配套比较齐全整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 81);
