INSERT INTO `travel_review` VALUES (4651, 'TR004651', '中峰', '渭南', '陕西', '深度游', '秋季', 6, 3, 675.00, '是', 5, '6月去的中峰，情侣出行。地点在渭南，公交换乘方便，现场人流量适中。这次玩了3天，人均花费约675元，夜景表现很好。景点印象：中峰又称玉女峰。春秋时有一年青人名萧史，善吹洞箫，引来秦穆公之女弄玉的爱慕。弄玉抛弃荣华富贵，与夫君同来华山隐居，玉女峰由此得名。整体感受是超出预期，值得专门打卡。二刷意愿：是。', '9%', 67);
INSERT INTO `travel_review` VALUES (4652, 'TR004652', '新疆兵团军垦博物馆-新通航Y-11型飞机', '石河子', '新疆', '拍照旅行', '冬季', 9, 5, 1502.00, '否', 4, '9月去的新疆兵团军垦博物馆-新通航Y-11型飞机，一个人出行。地点在石河子，地铁到达方便，现场高峰时段比较拥挤。这次玩了5天，人均花费约1502元，夜景表现很好。景点印象：周边配套比较齐全整体感受是还蛮满意，可以安排半天到一天。二刷意愿：否。', '0%', 102);
INSERT INTO `travel_review` VALUES (4653, 'TR004653', '茶场', '百色', '广西', '深度游', '夏季', 5, 1, 228.00, '是', 3, '5月去的茶场，一个人出行。地点在百色，打车比较省心，现场人不算多。这次玩了1天，人均花费约228元，拍照很出片。景点印象：从靖西到百色市区有四百多公里，沿路依然是如画的风光。时而是在山中转，时而穿越平原。到达百色市区已是下午四点多。百色并不像我们想象中那么落后，城市的规划建筑都达到一定层次呢。\n从百色到凌云，九十多公里完全是盘山的路。绕着一座又一座的…整体感受是中规中矩，按需选择。二刷意愿：是。', '1%', 87);
