INSERT INTO `travel_review` VALUES (4655, 'TR004655', '三清坛', '定安', '海南', '亲子出游', '冬季', 9, 3, 1659.00, '否', 5, '9月去的三清坛，一个人出行。地点在定安，自驾停车需要提前规划，现场人流量适中。这次玩了3天，人均花费约1659元，夜景表现很好。景点印象：景点本身有一定特色整体感受是超出预期，很推荐。二刷意愿：否。', '0%', 88);
INSERT INTO `travel_review` VALUES (4656, 'TR004656', '广州塔', '广州', '广东', '亲子出游', '春季', 12, 2, 561.00, '是', 5, '12月去的广州塔，一个人出行。地点在广州，地铁到达方便，现场游客较多。这次玩了2天，人均花费约561元，拍照很出片。景点印象：“广”字造型别具创意，登塔可俯瞰广州市景，还能体验极限项目。整体感受是超出预期，很推荐。二刷意愿：是。', '26%', 102);
INSERT INTO `travel_review` VALUES (4657, 'TR004657', '佛山黄飞鸿纪念馆', '佛山', '广东', '亲子出游', '冬季', 10, 1, 80.00, '否', 5, '10月去的佛山黄飞鸿纪念馆，情侣出行。地点在佛山，打车比较省心，现场人不算多。这次玩了1天，人均花费约80元，氛围感不错。景点印象：馆内全面展示了近70年来围绕黄飞鸿而产生的各种文艺作品以及上千件珍贵文物。整体感受是超出预期，以后还会来。二刷意愿：否。', '10%', 99);
