INSERT INTO `travel_review` VALUES (4660, 'TR004660', '南山特产', '邵阳', '湖南', '城市漫游', '冬季', 9, 1, 1065.00, '否', 2, '9月去的南山特产，和家人出行。地点在邵阳，公交换乘方便，现场游客较多。这次玩了1天，人均花费约1065元，拍照很出片。景点印象：南山奶粉\n“南山”牌系列乳制品以“凉开水即溶，喝了不上火”蜚声全国，被誉为“南国净土里长出的绿色食品”，其中婴幼儿系列奶粉为“国家免检产品”。南山奶粉畅销全国近30个省、自治区、直辖市，成为全国奶粉行业十大畅销产品，在广大消费者的心…整体感受是略失望，不建议高峰来。二刷意愿：否。', '0%', 42);
INSERT INTO `travel_review` VALUES (4661, 'TR004661', '莫家街', '西宁', '青海', '城市漫游', '冬季', 9, 2, 756.00, '是', 4, '9月去的莫家街，情侣出行。地点在西宁，打车比较省心，现场游客较多。这次玩了2天，人均花费约756元，夜景表现很好。景点印象：景点本身有一定特色整体感受是还蛮满意，推荐来看看。二刷意愿：是。', '0%', 73);
INSERT INTO `travel_review` VALUES (4662, 'TR004662', '老山红战友之家', '文山', '云南', '深度游', '夏季', 4, 2, 535.00, '是', 5, '4月去的老山红战友之家，和朋友出行。地点在文山，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了2天，人均花费约535元，历史文化气息浓。景点印象：周边配套比较齐全整体感受是特别满意，以后还会来。二刷意愿：是。', '0%', 82);
INSERT INTO `travel_review` VALUES (4663, 'TR004663', '朱公书院', '亳州', '安徽', '亲子出游', '夏季', 5, 1, 525.00, '是', 5, '5月去的朱公书院，情侣出行。地点在亳州，自驾停车需要提前规划，现场人流量适中。这次玩了1天，人均花费约525元，夜景表现很好。景点印象：位于亳州市花戏楼东侧，紧邻岳飞庙，始建于康熙37年（1698），是亳州人为纪念康熙年间亳州知州朱之琏的德政而修建的生祠。乾隆25年（1760）重修，现作为花戏楼的附属建筑向游人开放。\n朱之琏，字商王，奉天人，进士出身。康熙31年（1692）任知州，…整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 66);
INSERT INTO `travel_review` VALUES (4664, 'TR004664', '石棚山', '连云港', '江苏', '亲子出游', '夏季', 3, 6, 1486.00, '是', 5, '3月去的石棚山，情侣出行。地点在连云港，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了6天，人均花费约1486元，氛围感不错。景点印象：石棚山是锦屏山景区当中自然景观和人文景观都相当丰富的地方。它位于海州城的东部不远处，掩映在几百亩桃园之中，春来一片花海。石棚山虽不太高，但怪石嶙峋，千奇百怪。古人凭借丰富的想象力，给许多顽石赋予了生命，什么万花岩、佛手岩、群龟探海…整体感受是超出预期，很推荐。二刷意愿：是。', '1%', 40);
INSERT INTO `travel_review` VALUES (4665, 'TR004665', '黄水大冲', '阜阳', '安徽', '周末短途', '夏季', 3, 3, 580.00, '否', 5, '3月去的黄水大冲，一个人出行。地点在阜阳，打车比较省心，现场高峰时段比较拥挤。这次玩了3天，人均花费约580元，历史文化气息浓。景点印象：整体环境还算干净整体感受是特别满意，值得专门打卡。二刷意愿：否。', '0%', 119);
INSERT INTO `travel_review` VALUES (4666, 'TR004666', '南海影视城', '佛山', '广东', '城市漫游', '冬季', 9, 2, 393.00, '是', 4, '9月去的南海影视城，和朋友出行。地点在佛山，打车比较省心，现场游客较多。这次玩了2天，人均花费约393元，氛围感不错。景点印象：《三国演义》和《太平天国》等多部影视剧的取景地，非常适合拍照，还有很多表演可看。整体感受是体验挺好，周末来刚好。二刷意愿：是。', '4%', 70);
INSERT INTO `travel_review` VALUES (4667, 'TR004667', '临淄墓群', '淄博', '山东', '亲子出游', '夏季', 3, 1, 469.00, '是', 5, '3月去的临淄墓群，和家人出行。地点在淄博，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约469元，氛围感不错。景点印象：在齐都临淄周围几十里的地面上，大约分布着150多座古墓，被称为“临淄墓群”。古墓的年代上起春秋中后期，下迄秦汉。墓主有国君、王侯、贵族、大夫、将军、名士等。墓的形制多为高大的封土墓，状如山丘。1977年，国家将“临淄墓群”公布为省级重点…整体感受是特别满意，以后还会来。二刷意愿：是。', '0%', 75);
INSERT INTO `travel_review` VALUES (4668, 'TR004668', '青青生态度假村', '新乡', '河南', '拍照旅行', '秋季', 7, 1, 303.00, '是', 5, '7月去的青青生态度假村，一个人出行。地点在新乡，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约303元，拍照很出片。景点印象：新乡市青青生态园位于新乡市凤泉区，由国家级文明村耿庄村2002年元月投资兴建，项目总投资5290万元，2003年国庆节正式营业。新乡市青青生态园是国家AA级旅游景点、全国首批农业旅游示范点。\n　　新乡市青青生态园是集高效农业、生态旅游、休闲度假…整体感受是超出预期，值得专门打卡。二刷意愿：是。', '0%', 53);
INSERT INTO `travel_review` VALUES (4669, 'TR004669', '宜君花溪谷景区-观景台', '铜川', '陕西', '周末短途', '春季', 12, 1, 80.00, '否', 3, '12月去的宜君花溪谷景区-观景台，情侣出行。地点在铜川，自驾停车需要提前规划，现场游客较多。这次玩了1天，人均花费约80元，夜景表现很好。景点印象：景点本身有一定特色整体感受是中规中矩，避开高峰更好。二刷意愿：否。', '0%', 75);
INSERT INTO `travel_review` VALUES (4670, 'TR004670', '拉卜楞寺', '甘南', '甘肃', '周末短途', '春季', 2, 3, 659.00, '否', 3, '2月去的拉卜楞寺，情侣出行。地点在甘南，打车比较省心，现场高峰时段比较拥挤。这次玩了3天，人均花费约659元，夜景表现很好。景点印象：规模巨大的藏传佛教寺院群，超长的转经长廊世界罕见。整体感受是体验一般，避开高峰更好。二刷意愿：否。', '58%', 64);
INSERT INTO `travel_review` VALUES (4671, 'TR004671', '紫云山', '许昌', '河南', '亲子出游', '秋季', 8, 2, 752.00, '否', 3, '8月去的紫云山，和家人出行。地点在许昌，打车比较省心，现场人流量适中。这次玩了2天，人均花费约752元，历史文化气息浓。景点印象：紫云山风景区位于河南省襄城县境内，311国道，郑南、许南公路穿境而过，距郑、汴、洛、宛均百余公里，平、许、漯15―60公里，与石人山飞少林寺、乾明寺联为一体。景区由九山十八峰，五湖一条河和众多文物古迹组成，面积40多平方公里。九山谓紫云山…整体感受是体验一般，避开高峰更好。二刷意愿：否。', '0%', 61);
INSERT INTO `travel_review` VALUES (4672, 'TR004672', '茨坪景区', '吉安', '江西', '城市漫游', '夏季', 3, 1, 615.00, '是', 5, '3月去的茨坪景区，和朋友出行。地点在吉安，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约615元，历史文化气息浓。景点印象：井冈山的游客大本营，吃住行购都能在此解决。 参观革命旧址群和革命纪念馆，了解那段热血沸腾的历史。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '14%', 88);
