INSERT INTO `travel_review` VALUES (4694, 'TR004694', '紫霄岩', '莆田', '福建', '亲子出游', '秋季', 6, 4, 1323.00, '否', 2, '6月去的紫霄岩，情侣出行。地点在莆田，公交换乘方便，现场游客较多。这次玩了4天，人均花费约1323元，氛围感不错。景点印象：在市区以北约10公里处，漫山遍野奇石嶙峋，千姿百态，故有“紫霄怪石”之称。山石肖人肖物，千姿百态，绝顶有“万岁石”，尤为峻拔。此外，还有“仙人冢”、“暖日台”、“三清石”、“太府厝”、“仙巾帽”、“观音石”、“石镜屏”等石景，各具风…整体感受是略失望，不建议高峰来。二刷意愿：否。', '1%', 16);
INSERT INTO `travel_review` VALUES (4695, 'TR004695', '卧鹿山效圣寺', '鞍山', '辽宁', '亲子出游', '秋季', 7, 5, 1682.00, '是', 4, '7月去的卧鹿山效圣寺，情侣出行。地点在鞍山，地铁到达方便，现场人流量适中。这次玩了5天，人均花费约1682元，夜景表现很好。景点印象：效圣寺位于岫岩城南22公里杨家堡镇松树秧村卧鹿山羊角峰下，俗称“老古庙”，是省内现存唯一大型石构古代庙宇。整个石庙建筑“石庙房、石佛像、石钟楼、石围墙”，令人叹为观止。1988年12月，效圣寺被列为省级文物保护单位。 效圣寺(老古庙)相传始…整体感受是还蛮满意，周末来刚好。二刷意愿：是。', '0%', 104);
INSERT INTO `travel_review` VALUES (4696, 'TR004696', '芦庄清真寺', '廊坊', '河北', '亲子出游', '秋季', 8, 1, 357.00, '否', 5, '8月去的芦庄清真寺，情侣出行。地点在廊坊，公交换乘方便，现场人流量适中。这次玩了1天，人均花费约357元，氛围感不错。景点印象：史记明永乐年间，燕王朱棣扫北，何氏祖先曾随燕王征战，屡建战功，受封武德将军。后迁至大厂县芦庄定居，并兴建清真寺。该寺经历修缮，1999年回族群众又集资重建。现在清真寺大殿为宫殿式建筑。大殿居中两面三刀旁南北讲堂相对，后殿凹壁，外角楼屹…整体感受是特别满意，很推荐。二刷意愿：否。', '0%', 100);
