INSERT INTO `travel_review` VALUES (4713, 'TR004713', '平桥石坝', '常州', '江苏', '周末短途', '冬季', 9, 3, 789.00, '否', 5, '9月去的平桥石坝，情侣出行。地点在常州，打车比较省心，现场人流量适中。这次玩了3天，人均花费约789元，氛围感不错。景点印象：大坝用浆砌石建成，河水沿大坝而下形成瀑布，雨后非常壮观。整体感受是挺惊喜，很推荐。二刷意愿：否。', '0%', 44);
