INSERT INTO `travel_review` VALUES (4748, 'TR004748', '老鹰嘴', '呼伦贝尔', '内蒙古', '拍照旅行', '夏季', 3, 2, 395.00, '是', 5, '3月去的老鹰嘴，情侣出行。地点在呼伦贝尔，公交换乘方便，现场游客较多。这次玩了2天，人均花费约395元，氛围感不错。景点印象：老鹰嘴位于额尔古纳市临江屯正北方7、8公里处，因为有一块岩石，状似老鹰的嘴而得名。这里草木葱茏，鸟语花香，宁静安逸；攀上山顶，还能远眺风景，是当地人都回去踏青赏秋的独特景点。整体感受是超出预期，很推荐。二刷意愿：是。', '14%', 42);
