INSERT INTO `travel_review` VALUES (4756, 'TR004756', '爱珲历史陈列馆', '黑河', '黑龙江', '拍照旅行', '秋季', 6, 5, 1142.00, '是', 5, '6月去的爱珲历史陈列馆，一个人出行。地点在黑河，打车比较省心，现场高峰时段比较拥挤。这次玩了5天，人均花费约1142元，夜景表现很好。景点印象：爱辉因《瑷珲条约》而闻名于世，爱辉历史陈列馆也因《瑷珲条约》而倍受世人关注。爱辉历史陈列馆记载了中俄关系的演变史。\n爱辉历史陈列馆始建于1975年6月，同年9月竣工并对外展出。初建馆时，定名为“爱辉反修展览馆”。1979年7月展览馆对展出的内…整体感受是特别满意，很推荐。二刷意愿：是。', '8%', 72);
