INSERT INTO `travel_review` VALUES (4780, 'TR004780', '江平田园', '河池', '广西', '亲子出游', '秋季', 6, 1, 292.00, '是', 5, '6月去的江平田园，情侣出行。地点在河池，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约292元，拍照很出片。景点印象：东兰县武篆镇是一块无数先烈用鲜血浸染的红土地，是广西农民运动的发源地，当年邓小平、张云逸、韦拔群等老一辈无产阶级革命家曾在那里并肩战斗，写下了辉煌的历史篇章。其灿烂的革命历史和伟人们深深的足迹，吸引着全国各地的游客，每年前来谒访圣…整体感受是超出预期，以后还会来。二刷意愿：是。', '10%', 47);
