INSERT INTO `travel_review` VALUES (4789, 'TR004789', '山神峪千佛洞', '吕梁', '山西', '城市漫游', '秋季', 6, 1, 480.00, '否', 3, '6月去的山神峪千佛洞，一个人出行。地点在吕梁，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约480元，拍照很出片。景点印象：在山西交口县城西20公里山神峪村。此地吕梁山脉纵横交错，林木茂密，山峪深遂。相传古时有位白须老者居此，出入隐现，人莫能测，乡人誉为山神，地名因之。峪西侧山崖下，凿有石洞一区，洞内石壁满雕佛像，计有一千零五十五尊，名曰千佛洞。洞中释迦…整体感受是中规中矩，避开高峰更好。二刷意愿：否。', '0%', 20);
