INSERT INTO `travel_review` VALUES (4800, 'TR004800', '兴伊措', '甘孜藏族自治州', '四川', '深度游', '夏季', 4, 4, 1296.00, '是', 4, '4月去的兴伊措，和朋友出行。地点在甘孜藏族自治州，自驾停车需要提前规划，现场游客较多。这次玩了4天，人均花费约1296元，氛围感不错。景点印象：兴伊措藏语意为“献湖”之意，它是海子山最大的湖泊，位于海子山中部，面积7.5平方公里，淡水湖。整体感受是体验挺好，可以安排半天到一天。二刷意愿：是。', '1%', 102);
INSERT INTO `travel_review` VALUES (4801, 'TR004801', '达斡尔哈拉新村', '齐齐哈尔', '黑龙江', '城市漫游', '夏季', 4, 3, 838.00, '否', 5, '4月去的达斡尔哈拉新村，和朋友出行。地点在齐齐哈尔，打车比较省心，现场游客较多。这次玩了3天，人均花费约838元，历史文化气息浓。景点印象：原哈拉村毁于1998年嫩江特大洪灾。经全国政协和中华慈善总会拨款救助，在省市区党委、政府的关怀下，于翌年重新建成现代化的哈拉新村。\n        哈拉新村地处齐查、齐林公路交汇处，东濒嫩江，西南与明月岛隔江相望。全村有居民300户，其中达斡尔族…整体感受是超出预期，值得专门打卡。二刷意愿：否。', '0%', 90);
