INSERT INTO `travel_review` VALUES (4824, 'TR004824', '芦庄清真寺', '廊坊', '河北', '深度游', '春季', 1, 5, 1333.00, '是', 5, '1月去的芦庄清真寺，和朋友出行。地点在廊坊，地铁到达方便，现场高峰时段比较拥挤。这次玩了5天，人均花费约1333元，拍照很出片。景点印象：史记明永乐年间，燕王朱棣扫北，何氏祖先曾随燕王征战，屡建战功，受封武德将军。后迁至大厂县芦庄定居，并兴建清真寺。该寺经历修缮，1999年回族群众又集资重建。现在清真寺大殿为宫殿式建筑。大殿居中两面三刀旁南北讲堂相对，后殿凹壁，外角楼屹…整体感受是特别满意，以后还会来。二刷意愿：是。', '0%', 74);
