INSERT INTO `travel_review` VALUES (4839, 'TR004839', '上窑国家森林公园', '淮南', '安徽', '文化打卡', '冬季', 9, 2, 1138.00, '是', 4, '9月去的上窑国家森林公园，一个人出行。地点在淮南，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约1138元，历史文化气息浓。景点印象：安徽上窑国家森林公园位于著名煤城淮南市东北部，横卧于美丽富饶的窑河之滨。地处东径117度06’，一117度10’，北纬32 度45’， 一32度47’，公园总面积10．4平方公里。上窑森林公园是于1992年11月26日，经原林业部批准 ，在国营上窑林场的基础上建…整体感受是整体不错，可以安排半天到一天。二刷意愿：是。', '0%', 70);
