INSERT INTO `travel_review` VALUES (4841, 'TR004841', '螺丝山青年公园', '铜陵', '安徽', '深度游', '冬季', 9, 1, 202.00, '是', 5, '9月去的螺丝山青年公园，和家人出行。地点在铜陵，打车比较省心，现场人流量适中。这次玩了1天，人均花费约202元，拍照很出片。景点印象：螺丝山景区地理位置优越，旅游资源丰富，且已列入铜都森林公园规划。开发建设螺丝山景区，既能满足市民生活娱乐的要求，又能体现城市特色，同时也为创建省和国家园林城市、文明城市做出贡献。螺丝山景区开发建设也是环境保护的重要措施，可以美化铜…整体感受是超出预期，值得专门打卡。二刷意愿：是。', '0%', 115);
