INSERT INTO `travel_review` VALUES (4876, 'TR004876', '孙中山故居纪念馆', '中山', '广东', '亲子出游', '夏季', 3, 4, 1036.00, '否', 5, '3月去的孙中山故居纪念馆，情侣出行。地点在中山，地铁到达方便，现场人不算多。这次玩了4天，人均花费约1036元，历史文化气息浓。景点印象：中山市有名的景点，孙中山于1866年在此出生，全国重点文物保护单位。整体感受是特别满意，很推荐。二刷意愿：否。', '31%', 48);
