INSERT INTO `travel_review` VALUES (4900, 'TR004900', '坝王岭长臂猿自然保护区', '昌江', '海南', '周末短途', '秋季', 6, 3, 975.00, '否', 5, '6月去的坝王岭长臂猿自然保护区，和家人出行。地点在昌江，地铁到达方便，现场人不算多。这次玩了3天，人均花费约975元，夜景表现很好。景点印象：保护区总面积35000多亩，这里山岳连绵，群峰叠翠，林海浩渺，古木参天，自然生态系统保存完整，热带生物资源极其丰富。沿着蜿蜒曲折的林区公路进入保护区，环顾四周，除生长着众多的名贵树种外，野生动物主食的各种野果树满山皆是，有馒头果、山石…整体感受是特别满意，值得专门打卡。二刷意愿：否。', '0%', 63);
