INSERT INTO `travel_review` VALUES (4961, 'TR004961', '绿洲宾馆旅游区', '鄂尔多斯', '内蒙古', '拍照旅行', '夏季', 3, 2, 885.00, '是', 4, '3月去的绿洲宾馆旅游区，情侣出行。地点在鄂尔多斯，打车比较省心，现场人流量适中。这次玩了2天，人均花费约885元，夜景表现很好。景点印象：绿洲宾馆坐落于鄂尔多斯市伊金霍洛旗乌兰木伦镇马家塔复垦区，从1998年开始，神东公司本着“复垦 绿化、国土再造”的环保政策，先后投入了2400万元的资金和大量的人力、物力，加大绿化 、美化等综合治理力度，不断改善复垦区的生态环境，加快发展旅…整体感受是还蛮满意，推荐来看看。二刷意愿：是。', '0%', 72);
