INSERT INTO `travel_review` VALUES (4976, 'TR004976', '天坑奇观', '曲靖', '云南', '城市漫游', '夏季', 3, 2, 656.00, '否', 4, '3月去的天坑奇观，情侣出行。地点在曲靖，打车比较省心，现场人流量适中。这次玩了2天，人均花费约656元，拍照很出片。景点印象：沾益县大坡乡境内有4道“天坑”，最宽的达180米、深170米，属地壳陷落而成，“天坑”内尚有恐龙时代的蕨类植物，是我省首次发现的大自然奇观。\n天坑在地理学上叫漏斗，是溶洞坍塌或地表水流人地下时溶蚀而成。在已往的历史岁月里，世界很多地方都有…整体感受是体验挺好，推荐来看看。二刷意愿：否。', '0%', 99);
