INSERT INTO `travel_review` VALUES (5006, 'TR005006', '雪岭云杉自然保护区', '伊犁', '新疆', '文化打卡', '夏季', 5, 1, 363.00, '否', 5, '5月去的雪岭云杉自然保护区，一个人出行。地点在伊犁，自驾停车需要提前规划，现场人不算多。这次玩了1天，人均花费约363元，氛围感不错。景点印象：雪岭云杉是天山林海中特有的一个树种。在巍巍天山深处，它苍劲挺拔、四季青翠、攀坡漫生、绵延不绝，犹如一道沿山而筑的绿色长城。风吹林海，松涛声声，绿波起伏，其势如潮。整体感受是挺惊喜，很推荐。二刷意愿：否。', '0%', 69);
