INSERT INTO `travel_review` VALUES (5088, 'TR005088', '拉加里王宫遗址', '山南', '西藏', '周末短途', '冬季', 10, 4, 1053.00, '是', 4, '10月去的拉加里王宫遗址，和朋友出行。地点在山南，打车比较省心，现场人流量适中。这次玩了4天，人均花费约1053元，拍照很出片。景点印象：拉加里王宫遗址位于西藏自治区曲松县城南侧，建于13世纪，是吐蕃王室外后裔家庭势力在历经萨迦和帕竹政权后保留下来的王权象征。整体感受是体验挺好，周末来刚好。二刷意愿：是。', '0%', 67);
