INSERT INTO `travel_review` VALUES (5103, 'TR005103', '会山森林自然保护区', '琼海', '海南', '深度游', '秋季', 8, 4, 928.00, '是', 5, '8月去的会山森林自然保护区，情侣出行。地点在琼海，打车比较省心，现场游客较多。这次玩了4天，人均花费约928元，历史文化气息浓。景点印象：面积8万多亩。保护区建于1981年，其作用是保护、恢复和发展该地区的水源林，防止和减免泥沙冲积水库。它是一个有利于发展琼海森林综合经营的大林区。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 56);
