INSERT INTO `travel_review` VALUES (5132, 'TR005132', '崇善寺', '太原', '山西', '周末短途', '夏季', 3, 2, 455.00, '是', 5, '3月去的崇善寺，情侣出行。地点在太原，打车比较省心，现场人不算多。这次玩了2天，人均花费约455元，夜景表现很好。景点印象：每年春节期间来自海内外的香客居士多云集于此，被太原市民誉为香火最旺的寺庙。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '10%', 85);
INSERT INTO `travel_review` VALUES (5133, 'TR005133', '黄河源', '果洛', '青海', '周末短途', '春季', 2, 2, 608.00, '否', 5, '2月去的黄河源，情侣出行。地点在果洛，打车比较省心，现场人流量适中。这次玩了2天，人均花费约608元，氛围感不错。景点印象：也许你无法想像黄河的源头竟不是洪水滚滚，而是由众多细微的清泉和有许多砂砾野草的荒滩而组成，但会让你感受袒露无疑的大自然之美。整体感受是挺惊喜，很推荐。二刷意愿：否。', '2%', 112);
INSERT INTO `travel_review` VALUES (5134, 'TR005134', '康益泉温泉', '廊坊', '河北', '文化打卡', '春季', 2, 2, 889.00, '否', 4, '2月去的康益泉温泉，和家人出行。地点在廊坊，地铁到达方便，现场人流量适中。这次玩了2天，人均花费约889元，夜景表现很好。景点印象：位于固安县牛驼镇南，106国道西侧，距北京70公里。独特的大型露天温泉浴池，水性温热而富含多种元素，浴之可温经通络、畅达气血，祛寒舒筋，消除疲劳，强身健体，疗效独特，常浴可使肌肤润滑光亮。室外桑拿室、康乐中心等设施相配套，能使步入康益…整体感受是整体不错，推荐来看看。二刷意愿：否。', '50%', 70);
