INSERT INTO `travel_review` VALUES (5187, 'TR005187', '太统森林公园', '平凉', '甘肃', '深度游', '春季', 12, 1, 232.00, '否', 5, '12月去的太统森林公园，和家人出行。地点在平凉，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约232元，历史文化气息浓。景点印象：“西来第一园”--太统森林公园，位于崆峒区西郊3.5公里处。占地面积21.7万亩。属省级自然保护区和森林公园,是天然动植物园。景区森林覆盖率70%，木本植物33科90多种，草本植物3000多种，实用真菌20余种。生栖有金钱豹、梅花鹿、狍子、麝、锦鸡等国…整体感受是超出预期，值得专门打卡。二刷意愿：否。', '0%', 58);
