INSERT INTO `travel_review` VALUES (5190, 'TR005190', '铜仁古城', '铜仁', '贵州', '城市漫游', '夏季', 3, 3, 1106.00, '否', 5, '3月去的铜仁古城，和家人出行。地点在铜仁，打车比较省心，现场高峰时段比较拥挤。这次玩了3天，人均花费约1106元，氛围感不错。景点印象：整体环境还算干净整体感受是特别满意，很推荐。二刷意愿：否。', '2%', 83);
INSERT INTO `travel_review` VALUES (5191, 'TR005191', '天生桥', '邵阳', '湖南', '城市漫游', '夏季', 3, 4, 1392.00, '是', 3, '3月去的天生桥，情侣出行。地点在邵阳，打车比较省心，现场高峰时段比较拥挤。这次玩了4天，人均花费约1392元，拍照很出片。景点印象：天生桥景区紧临广西，是莨山景区近年来新发现的最具特色的景区之一，区内山环水绕，群峰横列，赤壁对峙，万巷迷离，约有近50平方公里折大面积丹霞赤壁群景观，景观资源特色鲜明，个性突出，具有强劲的比较优势，是开发丹霞观光、生态旅游、休头娱乐…整体感受是中规中矩，避开高峰更好。二刷意愿：是。', '0%', 83);
INSERT INTO `travel_review` VALUES (5192, 'TR005192', '董永公园', '孝感', '湖北', '拍照旅行', '冬季', 10, 4, 1283.00, '否', 2, '10月去的董永公园，情侣出行。地点在孝感，地铁到达方便，现场人不算多。这次玩了4天，人均花费约1283元，氛围感不错。景点印象：董永公园位于孝感市槐荫大道东段，一九八四年建成，占地75亩，分为三个区域。\n园内有孝子祠、仙女池、槐荫树、鸳鸯楼、理丝桥、涤丝亭、白步梯和升仙台等景点12处。景点按董永卖身葬父、孝行感天、仙女下凡、百日姻缘等情节为线索建造，歌颂了孝感…整体感受是没达到预期，不建议高峰来。二刷意愿：否。', '0%', 25);
INSERT INTO `travel_review` VALUES (5193, 'TR005193', '黎都公园', '长治', '山西', '文化打卡', '春季', 1, 3, 697.00, '否', 5, '1月去的黎都公园，一个人出行。地点在长治，地铁到达方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约697元，夜景表现很好。景点印象：黎都-羊头岭，又叫黎侯岭，面积约6平方公里，岭上最高点海拔1047米，清光绪版《长治县志》记载：“黎侯岭，县西南三十里，黎泉出焉，有黎侯亭；诸山皆石，此独土山。”\n远古时期，华夏始祖炎帝率领其部落顺河东下，登上太行山，进入现在的长治县境…整体感受是特别满意，很推荐。二刷意愿：否。', '0%', 107);
