INSERT INTO `travel_review` VALUES (5195, 'TR005195', '凤凰山', '安康', '陕西', '文化打卡', '冬季', 10, 6, 1630.00, '否', 5, '10月去的凤凰山，情侣出行。地点在安康，地铁到达方便，现场高峰时段比较拥挤。这次玩了6天，人均花费约1630元，历史文化气息浓。景点印象：《兴安府志.凤凰山记》载：“陕之关南则见安阳之凤凰山，绵亘三百余里，势若游龙，即天下之名山，似难出其右者，盖此山上百仞芙蓉，朵朵活波，直逼青天，下有汉水迂，淙淙泉石，极桡幽韵，此亦终南一大名胜也。卧苍崖，荫栝柏，凭高远眺，但见忽聚…整体感受是特别满意，很推荐。二刷意愿：否。', '0%', 68);
