INSERT INTO `travel_review` VALUES (5251, 'TR005251', '李自成墓', '咸宁', '湖北', '周末短途', '冬季', 10, 1, 656.00, '否', 5, '10月去的李自成墓，和家人出行。地点在咸宁，地铁到达方便，现场人不算多。这次玩了1天，人均花费约656元，夜景表现很好。景点印象：在通山县九宫山下牛迹岭。李自成（1606一1645），明末农民起义领袖。本名鸿基，陕西省米脂人。据记载，大顺永昌二年（1645年）初夏，他由武昌挥师东下南京，因形势逆转，征途受阻，即取道九宫山转战江西，不意在山下李家铺突遭清军袭击，仓促突围，…整体感受是超出预期，很推荐。二刷意愿：否。', '0%', 34);
