INSERT INTO `travel_review` VALUES (5278, 'TR005278', '喇嘛岭寺', '林芝', '西藏', '深度游', '秋季', 8, 2, 615.00, '是', 5, '8月去的喇嘛岭寺，一个人出行。地点在林芝，公交换乘方便，现场人不算多。这次玩了2天，人均花费约615元，历史文化气息浓。景点印象：属藏传佛教四大教派之一的宁玛派（俗称红教）寺庙。整体感受是特别满意，很推荐。二刷意愿：是。', '1%', 70);
INSERT INTO `travel_review` VALUES (5279, 'TR005279', '美溪回龙湾度假村', '伊春', '黑龙江', '周末短途', '春季', 1, 1, 377.00, '否', 3, '1月去的美溪回龙湾度假村，和朋友出行。地点在伊春，公交换乘方便，现场游客较多。这次玩了1天，人均花费约377元，拍照很出片。景点印象：位于美溪汤旺河畔，距市区30公里，建于1993年，占地面积638.8万米。这里在传说中是黑龙的诞生地，因此而得名，至今还流传着有关黑龙的神秘传说。回龙湾是集旅游、度假 、避暑、观光为一体的四季旅游胜地。回龙湾树木繁茂，景色宜人，近百种野花逢时…整体感受是还可以，别抱太高期待。二刷意愿：否。', '4%', 66);
