INSERT INTO `travel_review` VALUES (5287, 'TR005287', '乌兰木图山', '阜新', '辽宁', '周末短途', '冬季', 10, 2, 195.00, '是', 5, '10月去的乌兰木图山，情侣出行。地点在阜新，公交换乘方便，现场游客较多。这次玩了2天，人均花费约195元，拍照很出片。景点印象：阜蒙县八家子乡境内的乌兰木图山，早年叫阿力玛图山。两个名都是蒙语的音译，前者汉译为“有红色树木之山”，后者译为“有梨之山”。梨山之名更久。\n　　这座山的主峰叫锅底山，海拔高度831.4米，是阜新市第一高峰。站在主峰上近观远眺，收入眼帘的…整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 74);
