INSERT INTO `travel_review` VALUES (5289, 'TR005289', '五老峰景区', '九江', '江西', '周末短途', '春季', 1, 4, 271.00, '是', 5, '1月去的五老峰景区，情侣出行。地点在九江，打车比较省心，现场游客较多。这次玩了4天，人均花费约271元，夜景表现很好。景点印象：庐山最雄伟险峻的五峰，形状恰似五位老翁，从不同角度看姿态各异。 登上山顶可以远眺鄱阳湖、市镇田地及江河交错等风光。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '43%', 79);
