INSERT INTO `travel_review` VALUES (5305, 'TR005305', '疏山寺', '抚州', '江西', '深度游', '冬季', 11, 3, 1178.00, '否', 4, '11月去的疏山寺，和家人出行。地点在抚州，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了3天，人均花费约1178元，历史文化气息浓。景点印象：疏山寺古刹位于抚河右侧，距江西省金溪县浒湾镇四公里。寺周五峰错落，风景优美，寺前平川五百余亩。青山似黛，绿水长流；疏山八景，如诗如画，真乃人间仙境。疏山寺始建于唐，重建于明，大修于1981年。唐中和三年，抚州刺史危全讽上表朝廷拨银筹款…整体感受是整体不错，推荐来看看。二刷意愿：否。', '0%', 57);
