INSERT INTO `travel_review` VALUES (5319, 'TR005319', '塔山阻击战纪念塔', '葫芦岛', '辽宁', '拍照旅行', '春季', 1, 5, 1153.00, '是', 5, '1月去的塔山阻击战纪念塔，一个人出行。地点在葫芦岛，公交换乘方便，现场高峰时段比较拥挤。这次玩了5天，人均花费约1153元，氛围感不错。景点印象：纪念塔位塔身背面有碑文。详述了战斗经过和英雄事迹。葫芦岛市区以东12公里的连山区塔山乡塔山村东楼台山顶, 西南距市区9公里。\n烈士塔建于1963年10月，是为缅怀1948年辽沈战役塔山阻击战革命烈士而建立的。塔址是明朝天启年间的烽火台，群众称“…整体感受是挺惊喜，很推荐。二刷意愿：是。', '2%', 57);
