INSERT INTO `travel_review` VALUES (5337, 'TR005337', '文心居', '日照', '山东', '亲子出游', '春季', 2, 7, 2135.00, '否', 5, '2月去的文心居，和朋友出行。地点在日照，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了7天，人均花费约2135元，历史文化气息浓。景点印象：这里有你喜欢的碧海金沙滩，风景优美，这里可以为你提供好的住宿，环境很好，还可以在屋顶上观看日出……整体感受是超出预期，很推荐。二刷意愿：否。', '1%', 74);
INSERT INTO `travel_review` VALUES (5338, 'TR005338', '峙峪遗址', '朔州', '山西', '亲子出游', '冬季', 11, 2, 747.00, '是', 5, '11月去的峙峪遗址，情侣出行。地点在朔州，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了2天，人均花费约747元，历史文化气息浓。景点印象：位于朔州城西北15公里的黑驼山脚下，是一处旧石器时代的人类遗址，中国科学院1963年发现。现为省级重点文物保护单位。这里除发现大批细小石器和大量动物化石外，还发掘出数百件有刻划痕迹的兽片和一件人类初期的武器――石旋.整体感受是特别满意，值得专门打卡。二刷意愿：是。', '2%', 79);
