INSERT INTO `travel_review` VALUES (5370, 'TR005370', '陶祖圣境', '无锡', '江苏', '文化打卡', '春季', 12, 1, 393.00, '是', 5, '12月去的陶祖圣境，一个人出行。地点在无锡，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约393元，氛围感不错。景点印象：欣赏漫山的竹林与慕蠡洞中的钟乳石，在范蠡陶坊亲手制作陶器。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '0%', 79);
