INSERT INTO `travel_review` VALUES (5385, 'TR005385', '香山寺', '铜川', '陕西', '周末短途', '秋季', 6, 1, 142.00, '否', 3, '6月去的香山寺，和朋友出行。地点在铜川，打车比较省心，现场人不算多。这次玩了1天，人均花费约142元，拍照很出片。景点印象：香山创建寺院，始于苛秦，盛于姚秦。曾迎龟兹高僧鸠摩罗什翻译梵经于此。宋雍熙年间修中峰崎峰洞，建圣果院、白雀寺。清代光绪年间修建各类楼殿亭阁90余间。整体感受是还可以，按需选择。二刷意愿：否。', '10%', 59);
