INSERT INTO `travel_review` VALUES (5454, 'TR005454', '走马塘古村落', '宁波', '浙江', '文化打卡', '冬季', 10, 6, 1197.00, '是', 5, '10月去的走马塘古村落，情侣出行。地点在宁波，自驾停车需要提前规划，现场人不算多。这次玩了6天，人均花费约1197元，氛围感不错。景点印象：宁波周边最值得探访的古村，原生态的古建筑群适合摄影采风。 在曲折的小巷深处探寻，不经意处的精致遗存让闲逛也充满惊喜。 夏日绽放的荷花与白墙黑瓦的马头墙相互映衬，好似一幅水墨画。整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 60);
