INSERT INTO `travel_review` VALUES (5458, 'TR005458', '归德府文庙', '商丘', '河南', '亲子出游', '秋季', 8, 1, 475.00, '是', 5, '8月去的归德府文庙，和朋友出行。地点在商丘，打车比较省心，现场游客较多。这次玩了1天，人均花费约475元，夜景表现很好。景点印象：归德府文庙位于商丘市睢阳区，坐落在商丘古城内，是河南省现存规模最大的文庙建筑，始建于明嘉靖三十四年至三十八年（公元1555年至1559年），距今已有近500年的历史。整体感受是超出预期，以后还会来。二刷意愿：是。', '25%', 79);
