INSERT INTO `travel_review` VALUES (5500, 'TR005500', '尼果自然保护区', '昌都', '西藏', '亲子出游', '夏季', 3, 5, 1134.00, '否', 4, '3月去的尼果自然保护区，情侣出行。地点在昌都，地铁到达方便，现场人不算多。这次玩了5天，人均花费约1134元，拍照很出片。景点印象：尼果自然保护区位于芒康县宗沙乡境内，距县城70多公里，尼果顾名思义是“神山之冠”的意思，原名叫“康 达藏”冠顶。相传西藏有三个“达藏”。其中两个达藏是堆 安日达藏、巴 魏宗达藏。一九九零年县人大批准尼果为自然保护区，此地山青水秀、云雾…整体感受是体验挺好，可以安排半天到一天。二刷意愿：否。', '0%', 62);
