INSERT INTO `travel_review` VALUES (5502, 'TR005502', '舒兰亮甲山旅游风景区', '吉林市', '吉林', '拍照旅行', '秋季', 8, 2, 626.00, '是', 5, '8月去的舒兰亮甲山旅游风景区，情侣出行。地点在吉林市，自驾停车需要提前规划，现场人流量适中。这次玩了2天，人均花费约626元，夜景表现很好。景点印象：亮甲山生态旅游风景区暨舒兰市青少年教育活动基地是集森林公园、生态观光旅游、娱乐、度假、爱国主义教育为一体的大型生态旅游风景区，位于舒兰市庆丰乡西部，舒九公路北侧，距离舒兰市22公里，距离吉林省省会长春市150公里，距离吉林省第二大城市…整体感受是超出预期，值得专门打卡。二刷意愿：是。', '0%', 105);
INSERT INTO `travel_review` VALUES (5503, 'TR005503', '石门坊', '潍坊', '山东', '拍照旅行', '夏季', 4, 1, 80.00, '否', 5, '4月去的石门坊，和朋友出行。地点在潍坊，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约80元，历史文化气息浓。景点印象：周边配套比较齐全整体感受是特别满意，值得专门打卡。二刷意愿：否。', '2%', 76);
INSERT INTO `travel_review` VALUES (5504, 'TR005504', '沙漠博物馆', '中卫', '宁夏', '深度游', '冬季', 11, 1, 494.00, '是', 5, '11月去的沙漠博物馆，和家人出行。地点在中卫，自驾停车需要提前规划，现场人流量适中。这次玩了1天，人均花费约494元，氛围感不错。景点印象：博物馆位于沙坡头区迎水桥镇旅游景区，在这里可以了解到沙漠科普知识，认识沙漠的历史文化，还可以参与沙漠互动游戏。整体感受是特别满意，以后还会来。二刷意愿：是。', '1%', 66);
