INSERT INTO `travel_review` VALUES (5679, 'TR005679', '红谷滩新区', '南昌', '江西', '城市漫游', '秋季', 7, 1, 483.00, '否', 5, '7月去的红谷滩新区，一个人出行。地点在南昌，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约483元，氛围感不错。景点印象：红谷滩，古称“鸿鹄滩”，地处南昌赣江之北，与南昌南部的主要城区隔江相望。在中部崛起的大潮中，为拓展城市规模，加速城市化进程，加快“一江两岸”城市格局的形成。整体感受是特别满意，值得专门打卡。二刷意愿：否。', '0%', 110);
