INSERT INTO `travel_review` VALUES (5702, 'TR005702', '惠州城遗址', '朝阳', '辽宁', '文化打卡', '夏季', 3, 1, 589.00, '否', 5, '3月去的惠州城遗址，一个人出行。地点在朝阳，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约589元，夜景表现很好。景点印象：惠州城遗址位于建平中部建平镇八家村所在地，城址四面环山，东临老哈河支流――蹦河。城址长方形，东西638米，南北592米。城墙存高2-4米，底宽12米，城四角筑角台（东北角台水冲毁），现东南角台保存较好，高6米，底径15米。\n城墙间隔70-100米筑一…整体感受是超出预期，以后还会来。二刷意愿：否。', '0%', 67);
