INSERT INTO `travel_review` VALUES (5704, 'TR005704', '哈素海', '呼和浩特', '内蒙古', '深度游', '秋季', 6, 4, 1321.00, '是', 5, '6月去的哈素海，和朋友出行。地点在呼和浩特，公交换乘方便，现场游客较多。这次玩了4天，人均花费约1321元，拍照很出片。景点印象：驾一叶小舟品“塞外西湖”，集北方的旷野和南方的清柔于一身。整体感受是超出预期，很推荐。二刷意愿：是。', '8%', 80);
INSERT INTO `travel_review` VALUES (5705, 'TR005705', '古塔历史文化公园', '锦州', '辽宁', '周末短途', '春季', 1, 6, 1938.00, '否', 2, '1月去的古塔历史文化公园，一个人出行。地点在锦州，地铁到达方便，现场高峰时段比较拥挤。这次玩了6天，人均花费约1938元，拍照很出片。景点印象：古塔历史文化公园的园林设计风格继承了中国传统造园的精华，运用了现代风景园林的设计手法，借鉴了欧美园林的成功经验，充分表达了时代特点和辽西地方特色。\n千年古塔与现代园林合为一处，历史文化和现代文明融为一体，以其特有的园林风格而成为锦…整体感受是略失望，建议谨慎前往。二刷意愿：否。', '10%', 16);
