INSERT INTO `travel_review` VALUES (5717, 'TR005717', '太行山大峡谷', '长治', '山西', '城市漫游', '春季', 2, 1, 665.00, '是', 5, '2月去的太行山大峡谷，和家人出行。地点在长治，自驾停车需要提前规划，现场人流量适中。这次玩了1天，人均花费约665元，历史文化气息浓。景点印象：中国最美十大峡谷之一，千峰竞秀，万壑争奇，被称为“天然大氧吧”。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '24%', 117);
INSERT INTO `travel_review` VALUES (5718, 'TR005718', '红叶谷', '济南', '山东', '城市漫游', '冬季', 11, 1, 301.00, '是', 5, '11月去的红叶谷，一个人出行。地点在济南，公交换乘方便，现场人不算多。这次玩了1天，人均花费约301元，氛围感不错。景点印象：秋季来此，登高远眺山谷，可赏山谷中满山红叶，层林尽染，无比鲜艳。 蔷薇园、樱花园、百合园，每年会举行各种花展，景色非常绚丽。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '3%', 102);
