INSERT INTO `travel_review` VALUES (5722, 'TR005722', '京娘湖', '邯郸', '河北', '拍照旅行', '冬季', 11, 2, 625.00, '是', 4, '11月去的京娘湖，和家人出行。地点在邯郸，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约625元，氛围感不错。景点印象：赤红崖壁环绕着碧绿湖水，景色壮美奇幻，十分适合摄影。整体感受是整体不错，可以安排半天到一天。二刷意愿：是。', '6%', 63);
INSERT INTO `travel_review` VALUES (5723, 'TR005723', '七连山', '日照', '山东', '拍照旅行', '夏季', 4, 1, 587.00, '否', 4, '4月去的七连山，情侣出行。地点在日照，公交换乘方便，现场人不算多。这次玩了1天，人均花费约587元，历史文化气息浓。景点印象：七连山有“北方小庐山”之称，因境内高低起伏的山峰而闻名，数千巨石山头相连，造型各异景色优美，与庐山山水有异曲同工之妙。整体感受是整体不错，推荐来看看。二刷意愿：否。', '0%', 67);
