INSERT INTO `travel_review` VALUES (5779, 'TR005779', '野马饲养放生基地', '哈密', '新疆', '周末短途', '秋季', 7, 1, 555.00, '否', 5, '7月去的野马饲养放生基地，和朋友出行。地点在哈密，自驾停车需要提前规划，现场游客较多。这次玩了1天，人均花费约555元，氛围感不错。景点印象：浦氏野马的学名叫“普尔热瓦尔斯基马”，原来是新疆野马，因俄罗斯探险家普尔热瓦尔斯基1876年捕猎到欧洲就以他的名字命名。19世纪中后期由于探险家的掠杀和其它原因，新疆野马在自己的故乡消声遗迹了。全世界的存量也不足1000匹，是比大熊猫还要珍…整体感受是超出预期，很推荐。二刷意愿：否。', '0%', 116);
