INSERT INTO `travel_review` VALUES (5806, 'TR005806', '圣仙洞', '娄底', '湖南', '亲子出游', '夏季', 4, 2, 943.00, '否', 2, '4月去的圣仙洞，一个人出行。地点在娄底，地铁到达方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约943元，氛围感不错。景点印象：圣仙洞位于市郊尖子山白石岩腰。此洞穿通整个尖子山内腹，有洞口通向山顶。洞内的景观有正宫殿、观音殿、水晶殿、万家灶、千层塔、大象厅、玉兰园、瀑布岩、葫芦台、阳河口、神龟潭等大小厅堂14个，还有隐龙宫、舍身岩、南天门、北天门、银河口、地…整体感受是体验偏一般，建议谨慎前往。二刷意愿：否。', '0%', 35);
