INSERT INTO `travel_review` VALUES (5817, 'TR005817', '双牌水库', '永州', '湖南', '拍照旅行', '夏季', 4, 3, 892.00, '否', 5, '4月去的双牌水库，和家人出行。地点在永州，自驾停车需要提前规划，现场人流量适中。这次玩了3天，人均花费约892元，拍照很出片。景点印象：双牌水库景区位于双牌周冲口的湘江主支流潇水上，距永州市35km，始建于1958年，1962年完工。工程由大坝、溢洪道、引水系统、电站厂房、通航建筑等组成。大坝为混凝土双支墩大头坝，坝顶高程176.5m，最大坝高58.8m，坝顶长311m，宽6m。水库总容量6.9…整体感受是挺惊喜，以后还会来。二刷意愿：否。', '0%', 91);
