INSERT INTO `travel_review` VALUES (5850, 'TR005850', '梅湾湖', '眉山', '四川', '亲子出游', '春季', 1, 1, 432.00, '是', 5, '1月去的梅湾湖，和家人出行。地点在眉山，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约432元，氛围感不错。景点印象：梅湾湖，又名梅湾水库。位于丹棱县城西中隆乡梅湾村，距县城6公里，是七十年代大兴水利时建造的人工湖。集雨面积15.3平方公里，总库容1015万立方米，设计灌面3.16万亩，属中型水利工程，居丹棱水利工程之首。控灌丹棱镇、中隆乡、何场乡和唐河乡，…整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 116);
