INSERT INTO `travel_review` VALUES (5872, 'TR005872', '八台山风景名胜区', '达州', '四川', '拍照旅行', '冬季', 9, 4, 940.00, '否', 5, '9月去的八台山风景名胜区，和朋友出行。地点在达州，打车比较省心，现场游客较多。这次玩了4天，人均花费约940元，历史文化气息浓。景点印象：八台山风景名胜区由八台山、龙潭河、百藏堂、驮山四大鹌鹑区组成的八台山省级风景名胜区。其有各类景点100多人，总面积120平方千米，位于川东北的万源市境地内。\n主景区八台山的主峰海拔2273米，游人登顶可观日出、云海、佛光等景观。山下龙潭河滩…整体感受是挺惊喜，以后还会来。二刷意愿：否。', '0%', 95);
