INSERT INTO `travel_review` VALUES (5898, 'TR005898', '同心天池', '兴安盟', '内蒙古', '深度游', '冬季', 9, 2, 575.00, '是', 5, '9月去的同心天池，情侣出行。地点在兴安盟，公交换乘方便，现场游客较多。这次玩了2天，人均花费约575元，夜景表现很好。景点印象：天池位于阿尔山东北74公里的天池岭上，海拔1332.3米，有484级台阶。按海拔高度排列，紧随新疆天山山脉博格达峰天池和吉林省的白头山天池之后，居全国第三。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '2%', 82);
