INSERT INTO `travel_review` VALUES (5914, 'TR005914', '黄蜂窝茶山', '梅州', '广东', '周末短途', '夏季', 3, 1, 474.00, '是', 5, '3月去的黄蜂窝茶山，和家人出行。地点在梅州，打车比较省心，现场人流量适中。这次玩了1天，人均花费约474元，氛围感不错。景点印象：黄蜂窝茶山旅游区，于一九九零年建成，是集种茶、采茶、制茶、宣传茶文化的名茶示范基地和旅游观光的旅游区。整体感受是超出预期，值得专门打卡。二刷意愿：是。', '5%', 61);
