INSERT INTO `travel_review` VALUES (5917, 'TR005917', '老鹰嘴', '呼伦贝尔', '内蒙古', '深度游', '春季', 2, 1, 579.00, '是', 5, '2月去的老鹰嘴，一个人出行。地点在呼伦贝尔，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约579元，氛围感不错。景点印象：老鹰嘴位于额尔古纳市临江屯正北方7、8公里处，因为有一块岩石，状似老鹰的嘴而得名。这里草木葱茏，鸟语花香，宁静安逸；攀上山顶，还能远眺风景，是当地人都回去踏青赏秋的独特景点。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '14%', 68);
