INSERT INTO `travel_review` VALUES (5928, 'TR005928', '敦煌博物馆', '酒泉', '甘肃', '亲子出游', '春季', 2, 2, 346.00, '是', 4, '2月去的敦煌博物馆，情侣出行。地点在酒泉，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约346元，拍照很出片。景点印象：参观莫高窟内没有开放的石窟模样，还有重要文物“敦煌遗书”，了解敦煌的历史。 可以参观丝绸之路的历史文物，麒麟砖等文物十分罕见。整体感受是体验挺好，推荐来看看。二刷意愿：是。', '7%', 70);
