INSERT INTO `travel_review` VALUES (5934, 'TR005934', '飞龙洞', '吉安', '江西', '周末短途', '夏季', 5, 2, 499.00, '是', 5, '5月去的飞龙洞，和朋友出行。地点在吉安，公交换乘方便，现场游客较多。这次玩了2天，人均花费约499元，拍照很出片。景点印象：位于桐木岭附近山腰上,是一个巨大的溶洞,洞口通道是一先倾斜后直立的孔穴。洞内石钟乳、石笋，石柱、石花等琳琅满目，奇幻多姿，现已成为井冈山著名的风景点之一。整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 79);
INSERT INTO `travel_review` VALUES (5935, 'TR005935', '韩屯渡口', '吉林市', '吉林', '亲子出游', '秋季', 7, 1, 429.00, '否', 2, '7月去的韩屯渡口，和朋友出行。地点在吉林市，自驾停车需要提前规划，现场游客较多。这次玩了1天，人均花费约429元，氛围感不错。景点印象：韩屯渡口位于吉林市龙潭区乌拉街满族镇雾凇岛对面的渡口附近,由于该渡口对面的雾凇岛上没有住宿，所以游客多在韩屯驻扎。从韩屯渡口摆渡到对岸就可以到雾凇岛。整体感受是略失望，建议谨慎前往。二刷意愿：否。', '5%', 19);
