INSERT INTO `travel_review` VALUES (5956, 'TR005956', '长坡旧城遗址', '茂名', '广东', '城市漫游', '夏季', 4, 3, 837.00, '是', 5, '4月去的长坡旧城遗址，一个人出行。地点在茂名，公交换乘方便，现场人流量适中。这次玩了3天，人均花费约837元，拍照很出片。景点印象：“旧城遗址”是茂名市仅有的二个省级重点文物保护单位之一(另一个是高州“宝光塔\")，也是我省较古老的、唯一保存较完好的古城池遗址，具有1400多年的历史。旧城据府、县志记载：旧城原为电白郡、县治所。南朝萧梁时代(公元503―557)置电自郡，建郡…整体感受是超出预期，值得专门打卡。二刷意愿：是。', '0%', 78);
