INSERT INTO `travel_review` VALUES (5967, 'TR005967', '红色娘子军雕像', '琼海', '海南', '城市漫游', '冬季', 10, 1, 717.00, '否', 4, '10月去的红色娘子军雕像，情侣出行。地点在琼海，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约717元，历史文化气息浓。景点印象：位于琼海市南门的街心公园，于1985年8月1日落成揭幕。雕像由花岗石雕刻而成，坐北向南，高3．7米，连底座总高6．8米。座基石板铺设，四周呈六角形，围以石栏杆，占地面积40平方米。雕像后面是园林花圃等。红色娘子军纪念雕像将红军女战士脚穿草鞋、…整体感受是整体不错，推荐来看看。二刷意愿：否。', '2%', 53);
