INSERT INTO `travel_review` VALUES (5998, 'TR005998', '仙峪', '渭南', '陕西', '周末短途', '秋季', 8, 4, 1257.00, '是', 5, '8月去的仙峪，一个人出行。地点在渭南，地铁到达方便，现场人不算多。这次玩了4天，人均花费约1257元，拍照很出片。景点印象：仙峪又名车箱谷，在华山峪西， 仙峪深五十余里，峪道窄狭清幽，山路崎岖蜿蜒，河流湍急，山石险峻，多处路段凿崖加栈凌空通过。进峪五里处，有斜岭横阻，令人有谷尽路绝之感，然越岭横度，又不能不平添一种柳暗花明的情趣。整体感受是超出预期，很推荐。二刷意愿：是。', '1%', 60);
