INSERT INTO `travel_review` VALUES (6019, 'TR006019', '河堤公园', '梧州', '广西', '亲子出游', '夏季', 3, 4, 929.00, '否', 2, '3月去的河堤公园，和朋友出行。地点在梧州，公交换乘方便，现场高峰时段比较拥挤。这次玩了4天，人均花费约929元，拍照很出片。景点印象：河堤公园即梧州市河东区沿西江堤岸而开辟的全长0.3公里的带状公园，面积约10公顷。解放前，这一带坑坑洼洼，垃圾成堆。解放后，经过30多年整治，建成了目前初具规模的长堤。1981年底建立河堤公园，进行绿化美化，筑起石墙护坡，围起花栏，修整道路…整体感受是略失望，建议谨慎前往。二刷意愿：否。', '0%', 31);
