INSERT INTO `travel_review` VALUES (6057, 'TR006057', '海马洲', '汕尾', '广东', '城市漫游', '夏季', 5, 2, 463.00, '否', 5, '5月去的海马洲，和家人出行。地点在汕尾，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了2天，人均花费约463元，氛围感不错。景点印象：海马洲地处东海经济开发试验区南端，系乌坎港临海南郊虎头山延伸出的小岛，俗称“虎舌”。该岛南临碣石湾，东靠虎头山，西北面隔海与陆地相望。岛长3000米，宽350～650米，总面积2平方公里。岛内地势平坦，沙滩平缓向大海延伸，沙滩洁净，海水清澈…整体感受是特别满意，以后还会来。二刷意愿：否。', '0%', 98);
