INSERT INTO `travel_review` VALUES (6072, 'TR006072', '聚星塔', '抚州', '江西', '周末短途', '秋季', 6, 5, 1271.00, '否', 4, '6月去的聚星塔，一个人出行。地点在抚州，地铁到达方便，现场游客较多。这次玩了5天，人均花费约1271元，氛围感不错。景点印象：为省级重点保护文物，始建于明万历四十二年（1614年），重修于乾隆十九年（1754年）。塔高30米，共7层，呈八角形，塔檐锯齿形，塔身自下而上逐层内收，叠托而上，基部砖石皆用糯米汁浇浆垒砌而成，塔梯在内外塔身夹墙之中，分左右盘旋而上，全塔根…整体感受是整体不错，周末来刚好。二刷意愿：否。', '0%', 70);
