INSERT INTO `travel_review` VALUES (6102, 'TR006102', '英山烈士陵园', '黄冈', '湖北', '深度游', '春季', 12, 7, 1733.00, '否', 2, '12月去的英山烈士陵园，和家人出行。地点在黄冈，打车比较省心，现场人流量适中。这次玩了7天，人均花费约1733元，历史文化气息浓。景点印象：英山烈士陵园,革命烈士碑上刻有毛泽东“为国牺牲，永垂不朽”的题词；董必武“英灵永在”；朱德、李先念“革命烈士永垂不朽”的敬题：王任重“革命烈士用自己的铁拳，推倒了压在中国人民身上的三座大山，用血肉换取了中国人民的解放，革命的烈士们…整体感受是略失望，可考虑其他景点。二刷意愿：否。', '0%', 31);
