INSERT INTO `travel_review` VALUES (6110, 'TR006110', '万发拨子遗址', '通化', '吉林', '文化打卡', '秋季', 6, 1, 405.00, '否', 4, '6月去的万发拨子遗址，和家人出行。地点在通化，打车比较省心，现场人流量适中。这次玩了1天，人均花费约405元，氛围感不错。景点印象：万发拨子遗址位于吉林省通化市郊金厂镇。遗址年代跨度长，分别相当于新石器、商周、春秋战国、西汉、魏晋及明代，大致涵盖了吉林省东南部、辽宁省东部及朝鲜半岛西北部的文化序列。\n遗址面积15万平方米，分为东西两部分，西部是生活居住区，东部则…整体感受是整体不错，周末来刚好。二刷意愿：否。', '20%', 33);
