INSERT INTO `travel_review` VALUES (6116, 'TR006116', '沭阳肖湖', '宿迁', '江苏', '文化打卡', '秋季', 6, 1, 474.00, '是', 5, '6月去的沭阳肖湖，和家人出行。地点在宿迁，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约474元，历史文化气息浓。景点印象：1997年5月，省农林厅批准建立嶂山森林公园。公园位于宿迁市区以北7公里处的宿豫县境内，总面积7.2平方公里，森林覆盖率达67.7%。地处马陵山南麓，南端为天然草坪，中间为丘陵，北部为平原，西侧为湖泊。山有锅框山、鏊子山、三台山(海拔73.4米)；水…整体感受是特别满意，很推荐。二刷意愿：是。', '0%', 83);
