INSERT INTO `travel_review` VALUES (6120, 'TR006120', '徐福村', '连云港', '江苏', '周末短途', '夏季', 4, 3, 1029.00, '否', 4, '4月去的徐福村，一个人出行。地点在连云港，打车比较省心，现场游客较多。这次玩了3天，人均花费约1029元，拍照很出片。景点印象：金山乡的徐福村是秦代徐福的故里。今天徐福被日本人民尊之为司农耕之神，在日本新宫市有徐福公园，园内有徐福墓。\n据历史记载，秦朝当地有一位民间医生名叫徐福，善医药，会针灸，救治了当地及附近的许多乡亲，后来被秦始皇派遣，出海采仙药，一去…整体感受是体验挺好，可以安排半天到一天。二刷意愿：否。', '0%', 63);
INSERT INTO `travel_review` VALUES (6121, 'TR006121', '玉女峰', '连云港', '江苏', '深度游', '冬季', 10, 1, 563.00, '是', 4, '10月去的玉女峰，情侣出行。地点在连云港，自驾停车需要提前规划，现场人不算多。这次玩了1天，人均花费约563元，夜景表现很好。景点印象：江苏省最高峰，海上日出，云台铺海，群山俯伏，阡陌纵横。整体感受是还蛮满意，推荐来看看。二刷意愿：是。', '1%', 64);
