INSERT INTO `travel_review` VALUES (6126, 'TR006126', '天马保护区', '六安', '安徽', '城市漫游', '秋季', 7, 1, 703.00, '否', 4, '7月去的天马保护区，情侣出行。地点在六安，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约703元，夜景表现很好。景点印象：安徽金寨天马自然保护区位于安徽省金寨县境内，总面积28913.7公顷。保护区由安徽省政府1982年批建的马宗岭保护区和1990年批建的天堂寨保护区合并而成，主要保护对象为北亚热带常绿、落叶阔叶混交林及其山地垂直带谱。整体感受是还蛮满意，周末来刚好。二刷意愿：否。', '0%', 61);
