INSERT INTO `travel_review` VALUES (6132, 'TR006132', '顷希阿尔故城', '阿克苏', '新疆', '城市漫游', '夏季', 3, 2, 359.00, '否', 4, '3月去的顷希阿尔故城，情侣出行。地点在阿克苏，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约359元，拍照很出片。景点印象：顷希阿尔故城，又名大故城。系汉唐遗存。位于库车县东南60公里冼的东湖戈壁之中。城略呈圆形，残存城基高约0.6米，周长924米。醅有一座已颓圮的周围约120米的土墩，原形难辨。据考，这座故城与轮台县的卓里特沁故城之形制略似，可能为汉代屯田时田…整体感受是还蛮满意，推荐来看看。二刷意愿：否。', '0%', 29);
