INSERT INTO `travel_review` VALUES (6139, 'TR006139', '女娲城址', '周口', '河南', '周末短途', '夏季', 4, 3, 768.00, '否', 5, '4月去的女娲城址，一个人出行。地点在周口，地铁到达方便，现场人流量适中。这次玩了3天，人均花费约768元，夜景表现很好。景点印象：女娲，是我国古代神话传说中的人类始祖，她抟泥为人、化育万物、炼石补天并发明了笙簧乐器，对此《世本作篇》留有记载。《说文》曰：“娲，古之神圣女，化万物者也”。中国考古学者认为，古代传说中的女娲氏是部落首领，属仰韶文化，当在六七年之前…整体感受是超出预期，值得专门打卡。二刷意愿：否。', '33%', 84);
