INSERT INTO `travel_review` VALUES (6148, 'TR006148', '循化撒拉族绿色家园', '海东', '青海', '亲子出游', '夏季', 5, 1, 855.00, '是', 4, '5月去的循化撒拉族绿色家园，情侣出行。地点在海东，公交换乘方便，现场人流量适中。这次玩了1天，人均花费约855元，夜景表现很好。景点印象：循化撒拉族绿色家园位于自治县东北，平均海拔2500米以上，主峰高4178米，山清水秀，数百种树木掩天蔽日，各种花草植物绿茵盖地，有人参、三七、贝母等名贵药材，还有大量的珍稀动物，有“高原西双版纳”之美称。整体感受是体验挺好，推荐来看看。二刷意愿：是。', '6%', 70);
