INSERT INTO `travel_review` VALUES (6189, 'TR006189', '土司城墙', '恩施', '湖北', '周末短途', '秋季', 6, 1, 461.00, '否', 5, '6月去的土司城墙，情侣出行。地点在恩施，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约461元，拍照很出片。景点印象：土司城墙以土司城进口处左侧为起点，全长2320米，墙面宽1.2米，随山修筑，依山取形，逶迤延绵、雄伟壮观。土司城墙也取意恩施州内许多山寨寨墙和城墙，如利川鱼木寨、咸丰女儿寨，以及恩施市与柳州城的古城墙等。游览土司城墙和烽火台，不能不使人…整体感受是超出预期，值得专门打卡。二刷意愿：否。', '6%', 80);
