INSERT INTO `travel_review` VALUES (6208, 'TR006208', '仙堂寺', '长治', '山西', '文化打卡', '春季', 1, 3, 990.00, '否', 5, '1月去的仙堂寺，情侣出行。地点在长治，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了3天，人均花费约990元，拍照很出片。景点印象：在山西襄垣县城东北25公里仙堂山腰。四面环山，松柏苍翠，泉水蜿蜒寺侧，环境清静优美。寺址内外，五泉涌出，故又名五龙寺。创建年代不祥。相传某夜风寸雨大作，飞砂走石，林木倾坏，人呼马叫，翌日寺成，山门横额“仙堂”。明清两代屡有修葺，现存…整体感受是特别满意，很推荐。二刷意愿：否。', '0%', 73);
