INSERT INTO `travel_review` VALUES (6212, 'TR006212', '朱家尖南沙景区', '舟山', '浙江', '深度游', '冬季', 10, 6, 1690.00, '是', 5, '10月去的朱家尖南沙景区，情侣出行。地点在舟山，自驾停车需要提前规划，现场人不算多。这次玩了6天，人均花费约1690元，历史文化气息浓。景点印象：欣赏形态各异的沙雕作品，游泳、玩沙子，DIY一件自己的沙雕。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '3%', 31);
INSERT INTO `travel_review` VALUES (6213, 'TR006213', '承天寺', '银川', '宁夏', '城市漫游', '秋季', 7, 5, 1549.00, '是', 5, '7月去的承天寺，一个人出行。地点在银川，打车比较省心，现场人流量适中。这次玩了5天，人均花费约1549元，氛围感不错。景点印象：宁夏回族自治区重点文物保护单位，人称“西塔”，是宁夏现存的一百多座古塔中最高的一座砖塔，收藏了许多宁夏历史、民族、军事等方面珍贵的文物。整体感受是超出预期，以后还会来。二刷意愿：是。', '5%', 95);
