INSERT INTO `travel_review` VALUES (6230, 'TR006230', '长汀太平桥', '龙岩', '福建', '城市漫游', '夏季', 5, 1, 377.00, '是', 5, '5月去的长汀太平桥，情侣出行。地点在龙岩，自驾停车需要提前规划，现场人不算多。这次玩了1天，人均花费约377元，拍照很出片。景点印象：长汀太平桥是一座双廊桥，全长近百米，造型典雅、古朴，翘角飞檐，犹如双龙飞渡汀江之上。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 68);
INSERT INTO `travel_review` VALUES (6231, 'TR006231', '绮罗古镇', '保山', '云南', '亲子出游', '秋季', 8, 3, 749.00, '否', 5, '8月去的绮罗古镇，和朋友出行。地点在保山，打车比较省心，现场高峰时段比较拥挤。这次玩了3天，人均花费约749元，夜景表现很好。景点印象：小桥流水，古树和那些青砖绿瓦，重檐式的辉煌建筑，构成了一幅宁静和谐的画面。整体感受是特别满意，以后还会来。二刷意愿：否。', '1%', 69);
