INSERT INTO `travel_review` VALUES (6245, 'TR006245', '太平湖', '黄山', '安徽', '文化打卡', '春季', 12, 2, 782.00, '是', 5, '12月去的太平湖，和朋友出行。地点在黄山，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约782元，拍照很出片。景点印象：沿湖畔散步，欣赏清澈的湖水；坐游船登陆猴岛，邂逅黄山短尾猴。整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 95);
