INSERT INTO `travel_review` VALUES (6248, 'TR006248', '九九归一', '琼海', '海南', '周末短途', '夏季', 5, 1, 507.00, '是', 4, '5月去的九九归一，一个人出行。地点在琼海，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约507元，夜景表现很好。景点印象：这个整体看上去状若莲花的景点名为：九九归一，古时数字中“九”是最大的数，古人说：“九九之数以合天道”。所谓“归一”即是教导警醒人们天、地、人本为一体。这九瓣比人高的莲花瓣儿以及花瓣儿上的观音像，象征着佛教所说的“九品莲台”。西方极…整体感受是体验挺好，周末来刚好。二刷意愿：是。', '0%', 18);
INSERT INTO `travel_review` VALUES (6249, 'TR006249', '双台河口自然保护区', '盘锦', '辽宁', '亲子出游', '冬季', 11, 1, 356.00, '是', 5, '11月去的双台河口自然保护区，情侣出行。地点在盘锦，公交换乘方便，现场游客较多。这次玩了1天，人均花费约356元，夜景表现很好。景点印象：双台河口国家级自然保护区从标介于东经121度30分－122度00分，北纬40度45分-41度10分，总面积12.8万公顷。是目前世界上保存最好，面积最大，植被类型最完整的生态地块。作为自然保护区1985年始建，1988年国务院以国发30号文件确定为国家级自然保护…整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '2%', 98);
