INSERT INTO `travel_review` VALUES (6277, 'TR006277', '白水仙', '吉安', '江西', '文化打卡', '冬季', 9, 3, 648.00, '是', 5, '9月去的白水仙，情侣出行。地点在吉安，打车比较省心，现场高峰时段比较拥挤。这次玩了3天，人均花费约648元，拍照很出片。景点印象：井冈山南面的遂川县，境内自然风光优美，人文景观丰富。白水仙、泉江、汤湖三个景区相互辉映，联成一片，面积达65平方公里。白水仙——泉江风景名胜区于1995年7月经江西省政府批准，列为省级重点风景名胜区。\n庙前约300米远的另一山中，还有个5级“…整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 71);
