INSERT INTO `travel_review` VALUES (6288, 'TR006288', '洪门葡萄村', '枣庄', '山东', '深度游', '冬季', 11, 4, 1105.00, '是', 5, '11月去的洪门葡萄村，和朋友出行。地点在枣庄，公交换乘方便，现场人流量适中。这次玩了4天，人均花费约1105元，氛围感不错。景点印象：抱犊崮－熊耳山－洪门葡萄村，1992年被统一规划为“山亭农业生态旅游示范园”，总面积178平方公里。近年来，园内坚持以农业资源为依托，以农产品为基础，以市场需求为导向，以经济效益为中心，以旅游为突破口，大力发展农业旅游，取得了可喜的成就…整体感受是特别满意，很推荐。二刷意愿：是。', '0%', 90);
