INSERT INTO `travel_review` VALUES (6314, 'TR006314', '皖中奇石馆', '巢湖', '安徽', '周末短途', '冬季', 10, 2, 455.00, '否', 5, '10月去的皖中奇石馆，情侣出行。地点在巢湖，自驾停车需要提前规划，现场人流量适中。这次玩了2天，人均花费约455元，夜景表现很好。景点印象：该馆系中国收藏家协会会员、青年画家王衍平创建。馆内收藏了灵壁石、无为军石、淮南龟纹石、歙县矾石、巢湖散兵石、六安锰石、巢湖斧劈石、皖南砂积石、石台钟乳石、庐江矾石、莹石等中外各地名石精品1000多件、300余吨。该馆还集知识性、趣味性为…整体感受是挺惊喜，以后还会来。二刷意愿：否。', '0%', 57);
