INSERT INTO `travel_review` VALUES (6345, 'TR006345', '莲花山原始森林公园', '吉林市', '吉林', '周末短途', '冬季', 10, 2, 855.00, '是', 5, '10月去的莲花山原始森林公园，和朋友出行。地点在吉林市，地铁到达方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约855元，历史文化气息浓。景点印象：莲花山原始森林公园处在长白山余脉哈达岭的中段，景区内山高林密，山脊保存着大片原始红松林，天然的林分结构使森林季相分明，具有观赏性。区域内峰峦起伏，古木参天。春夏秋季，山高林茂，响瀑飞溅，野果飘香；冬季时，白的山谷，银的雪坡，玉树琼…整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 83);
