INSERT INTO `travel_review` VALUES (6361, 'TR006361', '木兰围场', '承德', '河北', '城市漫游', '春季', 1, 4, 948.00, '是', 5, '1月去的木兰围场，一个人出行。地点在承德，自驾停车需要提前规划，现场人不算多。这次玩了4天，人均花费约948元，夜景表现很好。景点印象：清朝历代皇帝及皇家的狩猎场，电视剧《还珠格格》曾在此地取景。 夜晚能见到非常多的星星，乌兰布统草原的北沟适合拍摄日落。 在开阔的草原骑马不受场地限制，只要你马技过关，甚至可以让马小跑一段。整体感受是超出预期，很推荐。二刷意愿：是。', '15%', 80);
INSERT INTO `travel_review` VALUES (6362, 'TR006362', '闽江源生态旅游区（金铙山风景区）', '三明', '福建', '深度游', '夏季', 5, 5, 1257.00, '否', 5, '5月去的闽江源生态旅游区（金铙山风景区），和家人出行。地点在三明，自驾停车需要提前规划，现场人流量适中。这次玩了5天，人均花费约1257元，拍照很出片。景点印象：整体环境还算干净整体感受是特别满意，值得专门打卡。二刷意愿：否。', '1%', 57);
INSERT INTO `travel_review` VALUES (6363, 'TR006363', '西大寺', '昌吉', '新疆', '文化打卡', '秋季', 8, 3, 971.00, '否', 5, '8月去的西大寺，情侣出行。地点在昌吉，公交换乘方便，现场人不算多。这次玩了3天，人均花费约971元，拍照很出片。景点印象：当地称为“西大寺”，座落在北庭故城以西约700米处，地面原为一高大土丘，1978－1981年发掘，发现为古佛寺。其建筑规模之大，造型艺术之精美，是迄今北疆同类遗址所仅见。现已被国务院定为国家重点文物保护单位。\n寺庙座北朝南，有正殿、东西配殿等…整体感受是超出预期，很推荐。二刷意愿：否。', '1%', 82);
