INSERT INTO `travel_review` VALUES (6381, 'TR006381', '北流泉', '天水', '甘肃', '周末短途', '春季', 1, 1, 333.00, '是', 4, '1月去的北流泉，情侣出行。地点在天水，自驾停车需要提前规划，现场人不算多。这次玩了1天，人均花费约333元，氛围感不错。景点印象：北流泉位于南郭寺东院六角亭下，原名不详，自杜甫诗“水号北流泉”后千百年来一直称北流泉，延续至今。北流泉千百年来未见其涸。《天水县志》记：“东有泉，旱盈潦缩，祈雨极验”。此泉在天大旱时，水旺如旧。附近村民取水饮用，浇灌农田，不见其竭…整体感受是整体不错，可以安排半天到一天。二刷意愿：是。', '0%', 61);
INSERT INTO `travel_review` VALUES (6382, 'TR006382', '相石阶森林公园', '曲靖', '云南', '深度游', '春季', 1, 4, 910.00, '否', 5, '1月去的相石阶森林公园，和朋友出行。地点在曲靖，地铁到达方便，现场人不算多。这次玩了4天，人均花费约910元，历史文化气息浓。景点印象：林园绿树成荫，漫山遍野，鸟声蝉鸣传情，空气怡人，沁人心脾，行走林间宛如仙境。整体感受是特别满意，以后还会来。二刷意愿：否。', '0%', 91);
