INSERT INTO `travel_review` VALUES (6409, 'TR006409', '箭竹林', '神农架', '湖北', '城市漫游', '春季', 2, 1, 98.00, '否', 4, '2月去的箭竹林，和家人出行。地点在神农架，地铁到达方便，现场游客较多。这次玩了1天，人均花费约98元，夜景表现很好。景点印象：主要在大神农架近峰顶一带。竹丛生长异常稠密，每平方米达120多株；竿细长，仅若手指粗，橙黄发亮，坚实而柔韧，古人用其作箭，故名。据初步统计，包括小神农架的竹林，达46万余亩，密密麻麻，重叠无垠。“山脚炎夏山岭春，山麓艳秋山顶冰”的神农…整体感受是体验挺好，推荐来看看。二刷意愿：否。', '4%', 64);
