INSERT INTO `travel_review` VALUES (6424, 'TR006424', '梧州古墓群', '梧州', '广西', '深度游', '冬季', 11, 7, 1508.00, '否', 5, '11月去的梧州古墓群，情侣出行。地点在梧州，自驾停车需要提前规划，现场人流量适中。这次玩了7天，人均花费约1508元，氛围感不错。景点印象：位于市区的云盖山、螺山、莲花山一带，范围较分散。墓葬年代多数是西汉、东汉和两晋时期的，出土文物有大量的陶器、铜器、瓷器等。这表明梧州自汉代以来就是中国南方地区的一座重镇。整体感受是特别满意，很推荐。二刷意愿：否。', '0%', 133);
