INSERT INTO `travel_review` VALUES (6459, 'TR006459', '中条山', '运城', '山西', '城市漫游', '秋季', 8, 2, 659.00, '是', 5, '8月去的中条山，情侣出行。地点在运城，地铁到达方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约659元，历史文化气息浓。景点印象：位于山西省南部运城地区的夏县、闻喜、绛县、垣曲等县境内，地处山西省的最南端。1993年10月经林业部批准建立，占地面积50万亩。\n公园处于太行山脉南段，气候温和，属暖温带大陆性气候，北有涑水，南有黄河，有多条溪流从园内发源，分别注入涑水和…整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 68);
