INSERT INTO `travel_review` VALUES (6504, 'TR006504', '乌尔禾风城', '克拉玛依', '新疆', '深度游', '春季', 2, 1, 689.00, '否', 3, '2月去的乌尔禾风城，和家人出行。地点在克拉玛依，打车比较省心，现场游客较多。这次玩了1天，人均花费约689元，历史文化气息浓。景点印象：位于市区东北100多公里的乌尔干地，北倚哈拉阿拉特山，方圆约30余公里，是我国罕见的风蚀地貌。亿万年前，这里是淡水湖泊，地壳的沧桑剧变使它形成了戈壁平台，年复一年的风蚀雨剥，使地面形成沟壑、纵横深浅不一的石层，并将石层雕塑成各种奇形怪…整体感受是还可以，别抱太高期待。二刷意愿：否。', '6%', 31);
