INSERT INTO `travel_review` VALUES (6508, 'TR006508', '一线天', '邵阳', '湖南', '城市漫游', '秋季', 7, 2, 1027.00, '是', 5, '7月去的一线天，情侣出行。地点在邵阳，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约1027元，历史文化气息浓。景点印象：一线天\n位于南山牧场北部，距场部大坪11公里，此处森林密布，悬崖峭壁，岩缝长达100余米，宽处2米，窄处80公分，仅能过一个人，在岩缝里往上看，仅能看到一线天。整体感受是特别满意，很推荐。二刷意愿：是。', '5%', 55);
INSERT INTO `travel_review` VALUES (6509, 'TR006509', '永乐宫', '运城', '山西', '拍照旅行', '冬季', 9, 1, 658.00, '否', 5, '9月去的永乐宫，情侣出行。地点在运城，自驾停车需要提前规划，现场人不算多。这次玩了1天，人均花费约658元，历史文化气息浓。景点印象：目睹精美绝伦的元代壁画，代表作中二百多个神仙朝贺元始天尊，姿态各异，表情生动。 现存最大的元代道观，修建用了一百多年，建筑风格简洁明朗。整体感受是挺惊喜，以后还会来。二刷意愿：否。', '16%', 57);
