INSERT INTO `travel_review` VALUES (6530, 'TR006530', '御茶园', '南平', '福建', '亲子出游', '夏季', 4, 2, 468.00, '否', 3, '4月去的御茶园，和家人出行。地点在南平，公交换乘方便，现场游客较多。这次玩了2天，人均花费约468元，拍照很出片。景点印象：四曲溪南有一片依山傍水平地，这就是元代皇家御茶园的遗址。\n武夷山产茶历史悠久。据《崇安县志》记载：唐贞元年间（公元785－805年）武夷山一带已有蒸焙后研碎而塑成团状的“研膏”茶制造。这便是最早的武夷岩茶。宋代大文学家苏东坡在咏茶诗中赞…整体感受是体验一般，避开高峰更好。二刷意愿：否。', '14%', 100);
