INSERT INTO `travel_review` VALUES (6549, 'TR006549', '药泉山钟灵禅寺', '黑河', '黑龙江', '亲子出游', '春季', 2, 1, 289.00, '否', 4, '2月去的药泉山钟灵禅寺，情侣出行。地点在黑河，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约289元，拍照很出片。景点印象：药泉山钟灵禅寺坐落在五大连池风景名胜区老期火山药泉山的火山口中平旷之处，距火口垣尚有十余米的高程，它与火山堰塞湖和新老期火山相映生辉，构成了独特的人文景观，在火山口里建寺庙在世界上是唯一的，所以钟灵禅寺又号称火口第一寺。\n登药泉山…整体感受是体验挺好，可以安排半天到一天。二刷意愿：否。', '2%', 82);
