INSERT INTO `travel_review` VALUES (6580, 'TR006580', '莎车王墓', '喀什', '新疆', '深度游', '夏季', 5, 7, 1790.00, '是', 5, '5月去的莎车王墓，和朋友出行。地点在喀什，打车比较省心，现场游客较多。这次玩了7天，人均花费约1790元，拍照很出片。景点印象：陵墓占地1050平方米，虽历经数百年，其壁饰图案、建筑用料及结构布局，仍清晰如新。近年来，当地政府和群众，又专门为阿曼尼莎汗王妃另外修建了陵墓，其高大、精美，均超出了原王陵。它位于县城中汉城、回城之间，至今瞻仰者不绝于途。整体感受是超出预期，值得专门打卡。二刷意愿：是。', '0%', 84);
