INSERT INTO `travel_review` VALUES (6642, 'TR006642', '洪门葡萄村', '枣庄', '山东', '深度游', '春季', 2, 1, 297.00, '是', 5, '2月去的洪门葡萄村，情侣出行。地点在枣庄，打车比较省心，现场游客较多。这次玩了1天，人均花费约297元，夜景表现很好。景点印象：抱犊崮－熊耳山－洪门葡萄村，1992年被统一规划为“山亭农业生态旅游示范园”，总面积178平方公里。近年来，园内坚持以农业资源为依托，以农产品为基础，以市场需求为导向，以经济效益为中心，以旅游为突破口，大力发展农业旅游，取得了可喜的成就…整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 85);
