INSERT INTO `travel_review` VALUES (6668, 'TR006668', '汉王湖', '眉山', '四川', '亲子出游', '夏季', 4, 1, 427.00, '否', 2, '4月去的汉王湖，和家人出行。地点在眉山，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约427元，氛围感不错。景点印象：洪雅汉王湖又名总岗山水库，始建于1958年，竣工于1972年，位于洪雅县汉王乡总岗多悦镇、正山口乡再西行里，公路畅通。汉王湖属青衣江水系一支流--香樟河，筑坝蓄水，承灌洪雅、丹棱两县11个乡5万亩农田。汉王湖集雨面积达28平方公里，水域面2067700…整体感受是体验偏一般，不建议高峰来。二刷意愿：否。', '0%', 47);
