INSERT INTO `travel_review` VALUES (6683, 'TR006683', '杨家城', '天水', '甘肃', '文化打卡', '冬季', 10, 2, 1082.00, '否', 3, '10月去的杨家城，一个人出行。地点在天水，地铁到达方便，现场人不算多。这次玩了2天，人均花费约1082元，夜景表现很好。景点印象：该城始建于唐天宝年间（公元742-756）。五代至宋，州刺史杨宏信，长子杨重勋（重训）和孙杨光，世守麟州；次子杨业和孙杨延昭，都是宋代名将，北拒契丹，称雄一方。世人怀着对捍边英雄的崇敬心情，改呼此城为杨家城。城东南约70米处，原有松树3株，…整体感受是中规中矩，别抱太高期待。二刷意愿：否。', '0%', 78);
INSERT INTO `travel_review` VALUES (6684, 'TR006684', '荔波小七孔景区', '黔南', '贵州', '拍照旅行', '夏季', 5, 2, 621.00, '否', 4, '5月去的荔波小七孔景区，一个人出行。地点在黔南，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约621元，夜景表现很好。景点印象：集山、水、洞、林、瀑、湖等多种景观于一体，有“超级盆景”的美誉。整体感受是体验挺好，可以安排半天到一天。二刷意愿：否。', '77%', 79);
INSERT INTO `travel_review` VALUES (6685, 'TR006685', '音乐花海公园', '泰州', '江苏', '深度游', '冬季', 11, 6, 1428.00, '否', 5, '11月去的音乐花海公园，和家人出行。地点在泰州，打车比较省心，现场高峰时段比较拥挤。这次玩了6天，人均花费约1428元，氛围感不错。景点印象：周边配套比较齐全整体感受是超出预期，很推荐。二刷意愿：否。', '0%', 70);
INSERT INTO `travel_review` VALUES (6686, 'TR006686', '苏铁自然保护区', '攀枝花', '四川', '拍照旅行', '春季', 12, 2, 348.00, '否', 5, '12月去的苏铁自然保护区，情侣出行。地点在攀枝花，打车比较省心，现场人不算多。这次玩了2天，人均花费约348元，氛围感不错。景点印象：主要保护对象是攀枝花苏铁这一珍稀濒危植物及其生态环境。\n攀枝花苏铁是1971年发现的苏铁新种，1981年才正式定名，1984年被列入我国第一批珍稀濒危保护植物名录，攀枝花苏铁对于研究我国横断山脉植物区系的发生和发展，以及古生物、古生态、古气候…整体感受是超出预期，值得专门打卡。二刷意愿：否。', '3%', 75);
INSERT INTO `travel_review` VALUES (6687, 'TR006687', '同里古镇', '苏州', '江苏', '文化打卡', '秋季', 8, 2, 665.00, '是', 5, '8月去的同里古镇，和朋友出行。地点在苏州，打车比较省心，现场游客较多。这次玩了2天，人均花费约665元，氛围感不错。景点印象：五湖环抱的江南水乡古镇，走三桥，参观小巧精致的园林退思园。整体感受是超出预期，以后还会来。二刷意愿：是。', '11%', 77);
