INSERT INTO `travel_review` VALUES (6691, 'TR006691', '梅岭国家级风景名胜区', '南昌', '江西', '拍照旅行', '夏季', 4, 4, 1341.00, '是', 5, '4月去的梅岭国家级风景名胜区，和朋友出行。地点在南昌，打车比较省心，现场高峰时段比较拥挤。这次玩了4天，人均花费约1341元，氛围感不错。景点印象：梅岭景区内古迹众多，令人称奇。 梅岭之巅是观赏日出及云海的好位置。整体感受是超出预期，很推荐。二刷意愿：是。', '3%', 41);
INSERT INTO `travel_review` VALUES (6692, 'TR006692', '神龙谷', '丽水', '浙江', '拍照旅行', '夏季', 3, 1, 643.00, '是', 4, '3月去的神龙谷，和家人出行。地点在丽水，公交换乘方便，现场人流量适中。这次玩了1天，人均花费约643元，夜景表现很好。景点印象：看落差300米的三级瀑布——神龙飞瀑，感受水汽扑面而来的清凉。 景观围绕汤显祖、粟裕将军的生平展开，可一边赏景，一边了解他们的故事。整体感受是还蛮满意，推荐来看看。二刷意愿：是。', '4%', 101);
