INSERT INTO `travel_review` VALUES (6702, 'TR006702', '阿西里西韭菜坪', '毕节', '贵州', '深度游', '秋季', 8, 3, 896.00, '是', 5, '8月去的阿西里西韭菜坪，情侣出行。地点在毕节，公交换乘方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约896元，夜景表现很好。景点印象：周边配套比较齐全整体感受是特别满意，以后还会来。二刷意愿：是。', '0%', 79);
INSERT INTO `travel_review` VALUES (6703, 'TR006703', '寺儿湾石窟', '白银', '甘肃', '城市漫游', '夏季', 4, 1, 956.00, '否', 3, '4月去的寺儿湾石窟，和朋友出行。地点在白银，公交换乘方便，现场人流量适中。这次玩了1天，人均花费约956元，历史文化气息浓。景点印象：甘肃省省级文物保护单位。位于甘肃省白银市靖远县北湾镇寺儿湾。距离白银市约 50 公里，靖白公里从侧而过。是古丝绸之路上的集雕塑艺术、建筑艺术、文学艺术为一体的文物旅游景点。因这里有一寺一湾，便称寺儿湾，又因寺窟背依红罗山，亦称红罗寺。…整体感受是中规中矩，避开高峰更好。二刷意愿：否。', '0%', 50);
INSERT INTO `travel_review` VALUES (6704, 'TR006704', '莲花湖', '锦州', '辽宁', '亲子出游', '春季', 2, 2, 1184.00, '是', 5, '2月去的莲花湖，一个人出行。地点在锦州，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了2天，人均花费约1184元，氛围感不错。景点印象：莲花湖位于黑山县姜屯镇东北4公里处，在土城子村旁，有一块近千亩的水面， 湖内数万株自然生长的莲花亭亭玉立，硕大的绿叶上滚动的水珠晶滢透澈，粉中透白的莲花散发着迷人的芳香。水中菱角一串串，水下鱼儿成群结对嬉戏，竹杆支撑着小船在湖面滑行…整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 79);
INSERT INTO `travel_review` VALUES (6705, 'TR006705', '霍拉盆地', '大兴安岭', '黑龙江', '文化打卡', '春季', 2, 1, 454.00, '否', 5, '2月去的霍拉盆地，和家人出行。地点在大兴安岭，公交换乘方便，现场游客较多。这次玩了1天，人均花费约454元，拍照很出片。景点印象：神奇、美丽、富饶的霍拉盆地坐落在漠河县城西50公里的崇山峻岭中，盆地形如巨扇，闻名龙江大地的古莲河露天煤矿就诞生在这里。整体感受是挺惊喜，以后还会来。二刷意愿：否。', '1%', 60);
