INSERT INTO `travel_review` VALUES (6710, 'TR006710', '花卉水族馆', '邢台', '河北', '亲子出游', '春季', 2, 2, 845.00, '是', 5, '2月去的花卉水族馆，一个人出行。地点在邢台，打车比较省心，现场人流量适中。这次玩了2天，人均花费约845元，氛围感不错。景点印象：景点本身有一定特色整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 41);
INSERT INTO `travel_review` VALUES (6711, 'TR006711', '沙屯多级瀑布', '崇左', '广西', '拍照旅行', '秋季', 7, 1, 178.00, '否', 4, '7月去的沙屯多级瀑布，情侣出行。地点在崇左，公交换乘方便，现场游客较多。这次玩了1天，人均花费约178元，历史文化气息浓。景点印象：又称念底瀑布，位于沙屯的归春河段上的青山峡谷中，西距县城约50公里，国家二级景点。瀑布约宽 60米，总落差约20米，分七级奔流而下。两岸高山峻岭，丛林繁茂，古藤盘绕。河水从10米高的峡涧冲出，断崖飞泻，跌水在第一级下形成约 500平方米的清潭…整体感受是整体不错，周末来刚好。二刷意愿：否。', '2%', 76);
