INSERT INTO `travel_review` VALUES (6713, 'TR006713', '福多堂生态旅游村', '钦州', '广西', '亲子出游', '秋季', 8, 3, 868.00, '否', 5, '8月去的福多堂生态旅游村，一个人出行。地点在钦州，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了3天，人均花费约868元，氛围感不错。景点印象：福多堂生态旅游村，全国文明村、省级农业旅游示范点。位于。钦（州）浦（北）二级公路从村边穿过，距浦北县城约30公里。是钦州市目前最大的现代农业生态村。2003年以来福多堂在上级党委、政府和有关部门的指导下，以“城乡联谊、三级联创”活动为契…整体感受是挺惊喜，很推荐。二刷意愿：否。', '0%', 83);
