INSERT INTO `travel_review` VALUES (6727, 'TR006727', '爱河度假村', '本溪', '辽宁', '城市漫游', '夏季', 3, 2, 695.00, '否', 5, '3月去的爱河度假村，和朋友出行。地点在本溪，公交换乘方便，现场人不算多。这次玩了2天，人均花费约695元，拍照很出片。景点印象：山清水秀、景色宜人。风格别致的旅游别墅、幽静曲折的长廊小路、清澈细涌的欧式泳馆、释放身心疲惫的桑拿游泳、碧波荡漾的水上乐园、漂亮标准的钓鱼岛（垂钓区），还有东北最大的水上龙船餐厅。爱河度假村落成于一九九五年，占地面积三万公顷，群山…整体感受是特别满意，值得专门打卡。二刷意愿：否。', '0%', 123);
