INSERT INTO `travel_review` VALUES (6733, 'TR006733', '松鹤西湖滑雪狩猎场', '鹤岗', '黑龙江', '周末短途', '冬季', 10, 4, 1364.00, '否', 3, '10月去的松鹤西湖滑雪狩猎场，和家人出行。地点在鹤岗，自驾停车需要提前规划，现场游客较多。这次玩了4天，人均花费约1364元，历史文化气息浓。景点印象：该场位于西郊松鹤西湖公园的笃斯山，山上有两条长800米的雪道和一个小动物狩猎场，山下湖中有冰上旅游项目，包括：滑冰、冰滑梯、冰上保龄球、狗拉雪撬等，是冬季溜冰滑雪的乐园。整体感受是中规中矩，避开高峰更好。二刷意愿：否。', '0%', 67);
