INSERT INTO `travel_review` VALUES (6754, 'TR006754', '仙鹤洞', '广安', '四川', '文化打卡', '秋季', 8, 1, 428.00, '否', 2, '8月去的仙鹤洞，情侣出行。地点在广安，打车比较省心，现场人流量适中。这次玩了1天，人均花费约428元，拍照很出片。景点印象：仙鹤洞位于华蓥市溪口镇六池堡，海拔690米，距华蓥市区28公里。形成于二千万年前，总长约10公里，现已开发3公里。据传，仙鹤洞的“仙鹤”，是武汉黄鹤楼的黄鹤飞临至此，见此处风光秀丽，洞景壮观，就在该洞长久地住了下来，故名仙鹤洞。\n洞中景观…整体感受是略失望，不建议高峰来。二刷意愿：否。', '0%', 64);
