INSERT INTO `travel_review` VALUES (6768, 'TR006768', '天都山石窟', '中卫', '宁夏', '拍照旅行', '秋季', 7, 2, 647.00, '否', 4, '7月去的天都山石窟，一个人出行。地点在中卫，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约647元，历史文化气息浓。景点印象：天都山亦称西华山，位于海原县西安州古城西15里，从山口循沟进约2.5公里，便可望见一座古刹，这就是天都山石窟。因民间传说在山中发现过金牛，故此窟又叫金牛寺，当地人又因石窟中有神佛塑像亦称之为老爷寺。另外，古代还有\"荣光寺\"之称。整体感受是整体不错，可以安排半天到一天。二刷意愿：否。', '0%', 91);
