INSERT INTO `travel_review` VALUES (6781, 'TR006781', '达坂城风力发电站', '乌鲁木齐', '新疆', '亲子出游', '夏季', 5, 1, 281.00, '否', 5, '5月去的达坂城风力发电站，情侣出行。地点在乌鲁木齐，打车比较省心，现场人流量适中。这次玩了1天，人均花费约281元，氛围感不错。景点印象：拍摄戈壁之上的上百座巨大风车，景色十分壮观。整体感受是特别满意，值得专门打卡。二刷意愿：否。', '3%', 68);
INSERT INTO `travel_review` VALUES (6782, 'TR006782', '双湖', '那曲', '西藏', '亲子出游', '春季', 1, 3, 1006.00, '否', 4, '1月去的双湖，一个人出行。地点在那曲，自驾停车需要提前规划，现场游客较多。这次玩了3天，人均花费约1006元，历史文化气息浓。景点印象：蒙语为“胡尔巴努尔”意为“双湖”，地处喀纳斯湖西岸―恰其阿依特山南坡河谷中，北西走向，呈椭圆状，由相隔三百米左右的两个狭长小湖串连构成，长1200米，宽度不等，一般在300m左右，湖面积1.4km2，海拔1498米。整体感受是还蛮满意，推荐来看看。二刷意愿：否。', '1%', 36);
