INSERT INTO `travel_review` VALUES (6785, 'TR006785', '梁孝王墓', '商丘', '河南', '亲子出游', '秋季', 6, 3, 1202.00, '是', 5, '6月去的梁孝王墓，一个人出行。地点在商丘，打车比较省心，现场游客较多。这次玩了3天，人均花费约1202元，氛围感不错。景点印象：位于永城东北34公里芒砀山南脉保安山东侧山腰，距山顶约15米。梁孝王名刘武，汉言文帝次子，初封代王，后封淮阳王，文帝十二年（前168年）改封为梁王，史称梁孝王，死后葬此。其墓斩山为椁，穿石而藏，墓门向东，墓长56.62米。最宽处30.5米，严整壮…整体感受是特别满意，很推荐。二刷意愿：是。', '12%', 80);
