INSERT INTO `travel_review` VALUES (6823, 'TR006823', '归德府文庙', '商丘', '河南', '亲子出游', '夏季', 3, 1, 175.00, '否', 5, '3月去的归德府文庙，和家人出行。地点在商丘，地铁到达方便，现场游客较多。这次玩了1天，人均花费约175元，夜景表现很好。景点印象：归德府文庙位于商丘市睢阳区，坐落在商丘古城内，是河南省现存规模最大的文庙建筑，始建于明嘉靖三十四年至三十八年（公元1555年至1559年），距今已有近500年的历史。整体感受是挺惊喜，很推荐。二刷意愿：否。', '25%', 113);
