INSERT INTO `travel_review` VALUES (6829, 'TR006829', '青竹农家乐园', '阳江', '广东', '文化打卡', '冬季', 10, 1, 358.00, '是', 5, '10月去的青竹农家乐园，和朋友出行。地点在阳江，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约358元，夜景表现很好。景点印象：青竹农家乐园位于城郊头堡村，这里山青水秀，环境洁静如人。在头堡村内的青竹农家乐园已成为城市人休闲、娱乐和品尝农家菜的 最佳去处。这里的农民纯朴和热情好客，村内有原始古朴的民居，有富有特色的农家菜肴，有风景优美的河塘水景，有连片绿油…整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 95);
