INSERT INTO `travel_review` VALUES (6836, 'TR006836', '新湖', '黄石', '湖北', '城市漫游', '冬季', 10, 4, 1417.00, '是', 5, '10月去的新湖，和朋友出行。地点在黄石，自驾停车需要提前规划，现场人不算多。这次玩了4天，人均花费约1417元，拍照很出片。景点印象：整体环境还算干净整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 63);
INSERT INTO `travel_review` VALUES (6837, 'TR006837', '神龟山', '万宁', '海南', '城市漫游', '冬季', 9, 2, 641.00, '是', 5, '9月去的神龟山，一个人出行。地点在万宁，自驾停车需要提前规划，现场人流量适中。这次玩了2天，人均花费约641元，夜景表现很好。景点印象：位于兴隆华侨农场境内。三座山峰连成东西走向呈龟状山脉，主峰海拨高280余米，高低错落的山势，把龟的头部、身部、尾部勾画得形神兼备，栩栩如生，充分展示了大自然造物之伟大和神奇。山上建起\"神龟山楼阁\"和\"神龟山神庙\"两大景点，有清未民国初期…整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 97);
