INSERT INTO `travel_review` VALUES (6855, 'TR006855', '辉腾锡勒黄花沟草原旅游区', '乌兰察布', '内蒙古', '周末短途', '秋季', 6, 2, 619.00, '否', 5, '6月去的辉腾锡勒黄花沟草原旅游区，情侣出行。地点在乌兰察布，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约619元，拍照很出片。景点印象：塞外避暑胜地，夜晚天空中浩瀚的星辰让无数摄影爱好者流连忘返。整体感受是特别满意，很推荐。二刷意愿：否。', '33%', 106);
INSERT INTO `travel_review` VALUES (6856, 'TR006856', '狮子林', '苏州', '江苏', '文化打卡', '夏季', 5, 4, 1160.00, '否', 2, '5月去的狮子林，和家人出行。地点在苏州，地铁到达方便，现场人流量适中。这次玩了4天，人均花费约1160元，历史文化气息浓。景点印象：苏州四大名园之一，以假山闻名，数石狮子、钻石头迷宫乐趣无穷。整体感受是体验偏一般，可考虑其他景点。二刷意愿：否。', '48%', 42);
INSERT INTO `travel_review` VALUES (6857, 'TR006857', '凤凰山', '铜陵', '安徽', '亲子出游', '春季', 12, 1, 614.00, '否', 2, '12月去的凤凰山，和朋友出行。地点在铜陵，公交换乘方便，现场人流量适中。这次玩了1天，人均花费约614元，氛围感不错。景点印象：凤凰山形胜凤凰，由横山、面山、灵风山、潭山、金山等构成。境内山清水秀，风景如画，是铜陵家喻户晓的旅游胜地。早在明朝“景泰”年间，诗人周铎就书写“庐外山高播半天，石也孤井聚甘泉，凤凰一饮千年后，尚有遗迹万古传”等十六首“凤凰八景”组…整体感受是没达到预期，可考虑其他景点。二刷意愿：否。', '0%', 57);
