INSERT INTO `travel_review` VALUES (6870, 'TR006870', '龙湾火山湖', '白山', '吉林', '周末短途', '冬季', 10, 1, 460.00, '是', 5, '10月去的龙湾火山湖，和家人出行。地点在白山，自驾停车需要提前规划，现场人不算多。这次玩了1天，人均花费约460元，拍照很出片。景点印象：有长白山“第二天地”之称的龙湾火山湖位于靖宇县城西20公里处，由火山喷发而成。湖面面积为92公顷，周围植被保存完好，自然景观独特，湖中有鱼类十几种，湖边建有养殖场，饲养山鸡、蛇、鹅等，并且建有游人接待场所，食、宿、游极为方便。龙湾火山…整体感受是特别满意，很推荐。二刷意愿：是。', '0%', 92);
