INSERT INTO `travel_review` VALUES (6872, 'TR006872', '南关清真寺', '临夏', '甘肃', '文化打卡', '秋季', 7, 1, 225.00, '是', 4, '7月去的南关清真寺，情侣出行。地点在临夏，自驾停车需要提前规划，现场人不算多。这次玩了1天，人均花费约225元，拍照很出片。景点印象：位于临夏市解放路，在南门广场南侧，北濒红水河，是临夏穆斯林群众礼拜的宗教活动场所。始建于元代末年，以后随毁随修，相延至今。\n现存清真寺经1979年重修，由前厅和礼拜堂两部分组成。前厅为平台式，台基高2米，厅高8米，前竖10个圆柱。礼拜大殿…整体感受是整体不错，周末来刚好。二刷意愿：是。', '4%', 54);
