INSERT INTO `travel_review` VALUES (6894, 'TR006894', '紫云山', '许昌', '河南', '周末短途', '春季', 2, 3, 980.00, '是', 5, '2月去的紫云山，和朋友出行。地点在许昌，自驾停车需要提前规划，现场人流量适中。这次玩了3天，人均花费约980元，历史文化气息浓。景点印象：紫云山风景区位于河南省襄城县境内，311国道，郑南、许南公路穿境而过，距郑、汴、洛、宛均百余公里，平、许、漯15―60公里，与石人山飞少林寺、乾明寺联为一体。景区由九山十八峰，五湖一条河和众多文物古迹组成，面积40多平方公里。九山谓紫云山…整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 71);
