INSERT INTO `travel_review` VALUES (6958, 'TR006958', '明长城遗址', '嘉峪关', '甘肃', '文化打卡', '冬季', 11, 2, 640.00, '否', 5, '11月去的明长城遗址，一个人出行。地点在嘉峪关，公交换乘方便，现场游客较多。这次玩了2天，人均花费约640元，历史文化气息浓。景点印象：明长城遗址西起嘉峪关市嘉峪关，经酒泉，高台，临泽，张掖，山丹，永昌，民勤，武威，古浪，景泰等县，从五佛寺过黄河，在靖远县内沿黄河南岸延伸，高低起伏，一直东至山海关。整体感受是特别满意，以后还会来。二刷意愿：否。', '16%', 76);
INSERT INTO `travel_review` VALUES (6959, 'TR006959', '江郎山风景名胜区', '衢州', '浙江', '亲子出游', '冬季', 10, 3, 1041.00, '是', 5, '10月去的江郎山风景名胜区，和家人出行。地点在衢州，打车比较省心，现场人不算多。这次玩了3天，人均花费约1041元，拍照很出片。景点印象：顺着崖壁上几乎垂直的陡阶登顶江郎山，其险不输华山。整体感受是特别满意，很推荐。二刷意愿：是。', '30%', 59);
INSERT INTO `travel_review` VALUES (6960, 'TR006960', '贵州森林野生动物园', '贵阳', '贵州', '文化打卡', '夏季', 4, 1, 494.00, '否', 3, '4月去的贵州森林野生动物园，一个人出行。地点在贵阳，地铁到达方便，现场游客较多。这次玩了1天，人均花费约494元，拍照很出片。景点印象：参观东北虎、白虎等各种动物，欣赏精彩的驯兽表演。整体感受是还可以，避开高峰更好。二刷意愿：否。', '0%', 74);
