INSERT INTO `travel_review` VALUES (6973, 'TR006973', '铭德农业生态园', '钦州', '广西', '周末短途', '夏季', 5, 4, 561.00, '是', 5, '5月去的铭德农业生态园，情侣出行。地点在钦州，公交换乘方便，现场高峰时段比较拥挤。这次玩了4天，人均花费约561元，历史文化气息浓。景点印象：铭德生态园位于钦州城东郊金海湾东大街，黎合江往市区走400米处，是南宁、北海、钦州港、三娘湾交通要道的交汇点。园区山青水秀，有铁索桥横跨湖中，山边竹木草棚，花香鸟语，集钓虾、烧烤、饮食、休闲、娱乐于一体，是旅游者周末的好去处。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 79);
