INSERT INTO `travel_review` VALUES (6995, 'TR006995', '景忠山旅游区', '唐山', '河北', '深度游', '冬季', 11, 5, 1000.00, '否', 4, '11月去的景忠山旅游区，和家人出行。地点在唐山，公交换乘方便，现场人流量适中。这次玩了5天，人均花费约1000元，氛围感不错。景点印象：位于唐山市迁西县境内，距北京180公里。景区面积15平方公里，大小景点80余处。景忠山气韵典雅，古朴迷离，其观古之幽，探奇之妙，赏景之媚，不愧为京东第一名岫。整体感受是体验挺好，推荐来看看。二刷意愿：否。', '1%', 60);
