INSERT INTO `travel_review` VALUES (7035, 'TR007035', '宋氏祖居', '文昌', '海南', '周末短途', '冬季', 10, 6, 1534.00, '是', 5, '10月去的宋氏祖居，情侣出行。地点在文昌，打车比较省心，现场高峰时段比较拥挤。这次玩了6天，人均花费约1534元，夜景表现很好。景点印象：宋氏祖居位于文昌市昌洒镇古路园村，距海口市约80公里，坐落在一片果树环抱的山丘上，周围绿树成荫，环境幽静。 国母宋庆龄的高祖、曾祖、祖父3代都居于此地，其父宋耀如于1861年出生在这里。\n为纪念宋庆龄及其家族在中国近现代历史上留下的深远影…整体感受是特别满意，以后还会来。二刷意愿：是。', '9%', 57);
