INSERT INTO `travel_review` VALUES (7081, 'TR007081', '文化长廊', '五家渠', '新疆', '亲子出游', '秋季', 7, 1, 245.00, '否', 2, '7月去的文化长廊，和朋友出行。地点在五家渠，打车比较省心，现场游客较多。这次玩了1天，人均花费约245元，拍照很出片。景点印象：整体环境还算干净整体感受是略失望，可考虑其他景点。二刷意愿：否。', '0%', 49);
INSERT INTO `travel_review` VALUES (7082, 'TR007082', '黄河古渡', '运城', '山西', '亲子出游', '冬季', 10, 2, 796.00, '是', 5, '10月去的黄河古渡，和家人出行。地点在运城，打车比较省心，现场人不算多。这次玩了2天，人均花费约796元，夜景表现很好。景点印象：奔腾咆哮的黄河，一出龙门，被秦岭山脉阻拦，于是掉头向东，浩浩荡荡，蜿蜒于宽达10多公里的河道上，穿中原，过齐鲁，驰骋千里，汇入渤海。沿途山川险要，良田万顷，车马如潮，景色宜人。在黄河北岸的山西省境内，从上流到下流，相继有风陵渡、大禹…整体感受是特别满意，很推荐。二刷意愿：是。', '2%', 15);
INSERT INTO `travel_review` VALUES (7083, 'TR007083', '哀牢山', '玉溪', '云南', '周末短途', '夏季', 3, 1, 608.00, '是', 4, '3月去的哀牢山，和家人出行。地点在玉溪，公交换乘方便，现场人不算多。这次玩了1天，人均花费约608元，拍照很出片。景点印象：野生动物生长繁衍的重要栖息地，堪称真正的“原始森林”，层层叠叠，弯弯曲曲，别有一番景色。整体感受是体验挺好，推荐来看看。二刷意愿：是。', '5%', 40);
