INSERT INTO `travel_review` VALUES (7102, 'TR007102', '采石矶', '马鞍山', '安徽', '城市漫游', '夏季', 5, 1, 292.00, '是', 5, '5月去的采石矶，和朋友出行。地点在马鞍山，地铁到达方便，现场游客较多。这次玩了1天，人均花费约292元，历史文化气息浓。景点印象：因李白醉酒捉月，溺死于采石的传闻而著名，可寻访诗仙足迹。 登山顶三台阁，俯看秀丽的园林和壮阔的长江，日落时尤其美。 漫步悬于山壁的古栈道，近距离感受长江的险要。整体感受是超出预期，很推荐。二刷意愿：是。', '61%', 104);
INSERT INTO `travel_review` VALUES (7103, 'TR007103', '刘公岛景区', '威海', '山东', '亲子出游', '春季', 1, 1, 509.00, '是', 5, '1月去的刘公岛景区，情侣出行。地点在威海，打车比较省心，现场游客较多。这次玩了1天，人均花费约509元，氛围感不错。景点印象：甲午战争纪念地，可在岛上参观甲午战争遗址博物馆。整体感受是特别满意，很推荐。二刷意愿：是。', '55%', 81);
INSERT INTO `travel_review` VALUES (7104, 'TR007104', '山西黄河第一湾', '吕梁', '山西', '亲子出游', '秋季', 7, 3, 564.00, '否', 5, '7月去的山西黄河第一湾，和家人出行。地点在吕梁，打车比较省心，现场高峰时段比较拥挤。这次玩了3天，人均花费约564元，氛围感不错。景点印象：“天下黄河第一湾”位于山西省石楼县辛关镇，最佳观景点为马家畔。晋西高原，峰峦如涛，绵延不绝。黄河巨浪，呼啸而过，逝者如斯，亘古不息。黄河自唐古拉山始，流经四川、甘肃、宁夏，一路向东，经晋蒙交界的老牛湾垂直向南，在晋陕大峡谷中下部，…整体感受是特别满意，值得专门打卡。二刷意愿：否。', '9%', 99);
