INSERT INTO `travel_review` VALUES (7160, 'TR007160', '塔山阻击战纪念塔', '葫芦岛', '辽宁', '周末短途', '春季', 1, 1, 464.00, '是', 5, '1月去的塔山阻击战纪念塔，和家人出行。地点在葫芦岛，自驾停车需要提前规划，现场人流量适中。这次玩了1天，人均花费约464元，历史文化气息浓。景点印象：纪念塔位塔身背面有碑文。详述了战斗经过和英雄事迹。葫芦岛市区以东12公里的连山区塔山乡塔山村东楼台山顶, 西南距市区9公里。\n烈士塔建于1963年10月，是为缅怀1948年辽沈战役塔山阻击战革命烈士而建立的。塔址是明朝天启年间的烽火台，群众称“…整体感受是超出预期，很推荐。二刷意愿：是。', '2%', 47);
