INSERT INTO `travel_review` VALUES (7176, 'TR007176', '避暑山庄罗家园', '石嘴山', '宁夏', '城市漫游', '冬季', 9, 1, 397.00, '是', 4, '9月去的避暑山庄罗家园，和家人出行。地点在石嘴山，地铁到达方便，现场人不算多。这次玩了1天，人均花费约397元，历史文化气息浓。景点印象：位于惠农县燕子墩汪家村以东海拔3000多米的贺兰山脚下的王泉沟口，是贺兰山脚下的一片绿洲，罗家园以其秀丽的景色，潺潺的泉水，清凉的气候，山水的交汇，独特的绿洲和鬼斧神工的幽谷险峰，形成了贺兰山下一个美丽的风景区。\n罗家园总面积约3万多…整体感受是还蛮满意，周末来刚好。二刷意愿：是。', '0%', 74);
