INSERT INTO `travel_review` VALUES (7204, 'TR007204', '九九归一', '琼海', '海南', '拍照旅行', '夏季', 4, 2, 905.00, '否', 4, '4月去的九九归一，情侣出行。地点在琼海，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约905元，氛围感不错。景点印象：这个整体看上去状若莲花的景点名为：九九归一，古时数字中“九”是最大的数，古人说：“九九之数以合天道”。所谓“归一”即是教导警醒人们天、地、人本为一体。这九瓣比人高的莲花瓣儿以及花瓣儿上的观音像，象征着佛教所说的“九品莲台”。西方极…整体感受是整体不错，周末来刚好。二刷意愿：否。', '0%', 36);
INSERT INTO `travel_review` VALUES (7205, 'TR007205', '瑞龙庄园', '汕尾', '广东', '周末短途', '秋季', 7, 1, 715.00, '否', 3, '7月去的瑞龙庄园，和朋友出行。地点在汕尾，地铁到达方便，现场人不算多。这次玩了1天，人均花费约715元，夜景表现很好。景点印象：陆河瑞龙庄园位于陆河县南部，总面积10多万平方米，整个庄园是按照二十一世纪庄园新概念设计建设而成，是一座集绿色生态、休闲度假、娱乐健身、会议培训、无污染工业园的现代化庄园。庄园内食、住、娱、游、购等服务配套齐全。\n庄园有城楼瞻胜、关…整体感受是体验一般，别抱太高期待。二刷意愿：否。', '0%', 83);
