INSERT INTO `travel_review` VALUES (7234, 'TR007234', '舟曲沙滩森林公园', '甘南', '甘肃', '亲子出游', '冬季', 9, 1, 81.00, '否', 5, '9月去的舟曲沙滩森林公园，和家人出行。地点在甘南，自驾停车需要提前规划，现场人不算多。这次玩了1天，人均花费约81元，拍照很出片。景点印象：沙滩森林公园，国家级森林公园，总面积3万公顷。地处甘南藏族自治州舟曲县武坪乡境内，为全州十大香巴拉旅游王牌景区之一。整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '0%', 50);
