INSERT INTO `travel_review` VALUES (7236, 'TR007236', '安吉竹博园', '湖州', '浙江', '亲子出游', '冬季', 9, 2, 448.00, '是', 3, '9月去的安吉竹博园，和朋友出行。地点在湖州，打车比较省心，现场人不算多。这次玩了2天，人均花费约448元，氛围感不错。景点印象：走上空中阶梯俯瞰碧绿竹海，在大熊猫馆里欣赏国宝大熊猫的风采。整体感受是还可以，别抱太高期待。二刷意愿：是。', '1%', 71);
INSERT INTO `travel_review` VALUES (7237, 'TR007237', '陕县温泉', '三门峡', '河南', '文化打卡', '春季', 1, 2, 710.00, '是', 4, '1月去的陕县温泉，情侣出行。地点在三门峡，打车比较省心，现场高峰时段比较拥挤。这次玩了2天，人均花费约710元，夜景表现很好。景点印象：陕县温泉位于三门峡市西温塘村，距市区15公里，交通便利、风景优美。温泉位于汾渭热矿水带弧形转折处和山西裂谷边缘基地，构造复杂，是一个具有优越隔热条件的迳流区。区内发育有深达300多米的深大断裂，裂谷深部有较新的岩浆活动，巨大的侵入岩体…整体感受是整体不错，可以安排半天到一天。二刷意愿：是。', '8%', 101);
