INSERT INTO `travel_review` VALUES (7295, 'TR007295', '石门摩崖石刻', '怒江', '云南', '深度游', '夏季', 4, 4, 1206.00, '是', 4, '4月去的石门摩崖石刻，和家人出行。地点在怒江，地铁到达方便，现场游客较多。这次玩了4天，人均花费约1206元，氛围感不错。景点印象：石门摩崖石刻位于贡山县茨开镇东400米当打村怒江西岸高50米的崖壁上。系贡山通福贡的古驿道旁，因地势险要称为石门。民国38年（1949年）设治局长梁之彦题刻\"石门\"二字。此处尚存石刻碑文三通，条幅二方。上书\"万家生佛\"四字。石碑之一，立于民国36…整体感受是体验挺好，推荐来看看。二刷意愿：是。', '4%', 79);
