INSERT INTO `travel_review` VALUES (7362, 'TR007362', '龙山', '铁岭', '辽宁', '城市漫游', '秋季', 8, 1, 80.00, '否', 4, '8月去的龙山，情侣出行。地点在铁岭，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约80元，历史文化气息浓。景点印象：龙山风景名胜区位于铁岭市区中心，是辽宁省省级风景名胜区。风景区分为龙首山、柴河、帽山三大景区，总面积9.47平方公里，其中龙首山景区2.22平方公里，柴河景区2.32平方公里，帽山景区4.93平方公里。1991年龙山风景名胜区已被省政府命名为省级风景…整体感受是还蛮满意，可以安排半天到一天。二刷意愿：否。', '0%', 67);
INSERT INTO `travel_review` VALUES (7363, 'TR007363', '临沂滨河', '临沂', '山东', '深度游', '秋季', 8, 5, 1474.00, '是', 4, '8月去的临沂滨河，一个人出行。地点在临沂，地铁到达方便，现场高峰时段比较拥挤。这次玩了5天，人均花费约1474元，氛围感不错。景点印象：临沂滨河景区位于沂河、祊河城区段，北起汶泗路汤头桥和北外环，南至刘家道口水利枢纽，总面积57平方公里，是全国最大的城市湿地。滨河景区集“水、岸、滩、堤、路、景”于一体，是具有防洪、交通、景观、休闲、娱乐、文化、旅游等多功能的生态景区…整体感受是整体不错，周末来刚好。二刷意愿：是。', '0%', 70);
INSERT INTO `travel_review` VALUES (7364, 'TR007364', '嵩山风景名胜区', '郑州', '河南', '城市漫游', '冬季', 9, 4, 1003.00, '是', 5, '9月去的嵩山风景名胜区，一个人出行。地点在郑州，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了4天，人均花费约1003元，拍照很出片。景点印象：欣赏壮美的自然风光和奇特的地质奇观，感受丰富灿烂的佛教、道教和儒学文化。整体感受是特别满意，很推荐。二刷意愿：是。', '12%', 94);
INSERT INTO `travel_review` VALUES (7365, 'TR007365', '大连自然博物馆', '大连', '辽宁', '周末短途', '夏季', 4, 2, 400.00, '否', 5, '4月去的大连自然博物馆，情侣出行。地点在大连，公交换乘方便，现场游客较多。这次玩了2天，人均花费约400元，历史文化气息浓。景点印象：动植物标本和化石非常丰富，馆藏鹦鹉嘴龙化石等许多珍稀藏品。整体感受是特别满意，以后还会来。二刷意愿：否。', '5%', 102);
