INSERT INTO `travel_review` VALUES (7367, 'TR007367', '神农坛', '焦作', '河南', '周末短途', '夏季', 3, 1, 783.00, '是', 4, '3月去的神农坛，一个人出行。地点在焦作，公交换乘方便，现场游客较多。这次玩了1天，人均花费约783元，拍照很出片。景点印象：神农坛风景名胜区位于河南焦作沁阳市西北25公里处的太行山南麓，总面积50.2平方公里，是省级风景名胜区，因炎帝神农在此播五谷、尝百草而得名，由紫金顶、云阳河、仙神河、黑龙潭、白松岭、临川寺、悬谷山、尧舜路八大景区组成。\n神农坛风景区集旷…整体感受是体验挺好，可以安排半天到一天。二刷意愿：是。', '0%', 60);
