INSERT INTO `travel_review` VALUES (7379, 'TR007379', '沙屯多级瀑布', '崇左', '广西', '城市漫游', '冬季', 11, 2, 706.00, '是', 5, '11月去的沙屯多级瀑布，和朋友出行。地点在崇左，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约706元，历史文化气息浓。景点印象：又称念底瀑布，位于沙屯的归春河段上的青山峡谷中，西距县城约50公里，国家二级景点。瀑布约宽 60米，总落差约20米，分七级奔流而下。两岸高山峻岭，丛林繁茂，古藤盘绕。河水从10米高的峡涧冲出，断崖飞泻，跌水在第一级下形成约 500平方米的清潭…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '2%', 64);
