INSERT INTO `travel_review` VALUES (7396, 'TR007396', '拉加里王宫遗址', '山南', '西藏', '亲子出游', '冬季', 11, 5, 1112.00, '是', 5, '11月去的拉加里王宫遗址，一个人出行。地点在山南，打车比较省心，现场人不算多。这次玩了5天，人均花费约1112元，历史文化气息浓。景点印象：拉加里王宫遗址位于西藏自治区曲松县城南侧，建于13世纪，是吐蕃王室外后裔家庭势力在历经萨迦和帕竹政权后保留下来的王权象征。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 71);
