INSERT INTO `travel_review` VALUES (7459, 'TR007459', '拦海大堤', '连云港', '江苏', '城市漫游', '冬季', 10, 3, 1331.00, '否', 2, '10月去的拦海大堤，一个人出行。地点在连云港，自驾停车需要提前规划，现场人流量适中。这次玩了3天，人均花费约1331元，历史文化气息浓。景点印象：被人称为“海上长城”，通过大堤可由陆地直达连岛浴场和连岛海滨旅游度假区。整体感受是体验偏一般，不建议高峰来。二刷意愿：否。', '3%', 46);
INSERT INTO `travel_review` VALUES (7460, 'TR007460', '珠峰大本营', '日喀则', '西藏', '拍照旅行', '春季', 1, 4, 1250.00, '是', 5, '1月去的珠峰大本营，一个人出行。地点在日喀则，地铁到达方便，现场游客较多。这次玩了4天，人均花费约1250元，拍照很出片。景点印象：观赏拍摄珠峰的最好位置之一，也是在中国攀登珠峰的必经之地。整体感受是特别满意，以后还会来。二刷意愿：是。', '27%', 72);
