INSERT INTO `travel_review` VALUES (7466, 'TR007466', '无字碑', '咸阳', '陕西', '深度游', '夏季', 4, 1, 596.00, '否', 5, '4月去的无字碑，和家人出行。地点在咸阳，自驾停车需要提前规划，现场游客较多。这次玩了1天，人均花费约596元，氛围感不错。景点印象：无字碑是乾陵的著名石碑，用一块完整的巨石雕凿而成的是中国历代群碑中的巨制，无字碑在无数游人眼中不仅是乾陵的象征，更是女皇武则天的象征。整体感受是特别满意，以后还会来。二刷意愿：否。', '16%', 82);
