INSERT INTO `travel_review` VALUES (7482, 'TR007482', '光禄古镇', '楚雄州', '云南', '城市漫游', '秋季', 7, 1, 417.00, '是', 5, '7月去的光禄古镇，和朋友出行。地点在楚雄州，打车比较省心，现场人流量适中。这次玩了1天，人均花费约417元，历史文化气息浓。景点印象：光禄古镇位于云南省楚雄州姚安县北部12公里处，历史悠久，山川秀美，名胜古迹众多。\n光禄古镇素有“迤西文化名邦”、“花灯之乡”的美称。整个古镇建筑成“坤”字型，古建筑众多，古镇历 史悠久，长期以来，一直是古代治滇重镇。是古南方“丝绸之路…整体感受是挺惊喜，很推荐。二刷意愿：是。', '4%', 133);
