INSERT INTO `travel_review` VALUES (7535, 'TR007535', '海棠湾', '三亚', '海南', '亲子出游', '夏季', 4, 3, 765.00, '是', 5, '4月去的海棠湾，情侣出行。地点在三亚，公交换乘方便，现场人不算多。这次玩了3天，人均花费约765元，拍照很出片。景点印象：远离市区、更为原生态的宁静海滩，也坐落着众多高端酒店。整体感受是特别满意，以后还会来。二刷意愿：是。', '6%', 107);
INSERT INTO `travel_review` VALUES (7536, 'TR007536', '兴城古城', '葫芦岛', '辽宁', '城市漫游', '冬季', 9, 1, 101.00, '否', 5, '9月去的兴城古城，情侣出行。地点在葫芦岛，公交换乘方便，现场人不算多。这次玩了1天，人均花费约101元，氛围感不错。景点印象：登上古城墙，俯瞰保存完整的明代古城全貌。 参观蓟辽督师府、文庙等古迹，重温明清史话、领略民俗风情。整体感受是挺惊喜，很推荐。二刷意愿：否。', '40%', 87);
INSERT INTO `travel_review` VALUES (7537, 'TR007537', '白沙湖', '阿勒泰', '新疆', '深度游', '夏季', 3, 7, 1708.00, '否', 4, '3月去的白沙湖，和朋友出行。地点在阿勒泰，公交换乘方便，现场人不算多。这次玩了7天，人均花费约1708元，历史文化气息浓。景点印象：葱郁树木和远处的沙山倒映在湖水里，是摄影的绝佳地带。整体感受是整体不错，周末来刚好。二刷意愿：否。', '10%', 71);
INSERT INTO `travel_review` VALUES (7538, 'TR007538', '查济', '宣城', '安徽', '周末短途', '秋季', 7, 1, 498.00, '是', 4, '7月去的查济，和家人出行。地点在宣城，打车比较省心，现场人不算多。这次玩了1天，人均花费约498元，氛围感不错。景点印象：欣赏二甲祠等精美的徽派建筑，访古老的元代德公厅屋。 爱日堂是《荒村客栈》取景地，悦桂山庄是《生活启示录》里胡歌的老家。 在当地客栈品毛豆腐、喝茶，秋天吃新鲜的板栗和猕猴桃。整体感受是还蛮满意，可以安排半天到一天。二刷意愿：是。', '10%', 78);
INSERT INTO `travel_review` VALUES (7539, 'TR007539', '水心寨', '常德', '湖南', '城市漫游', '春季', 2, 2, 572.00, '是', 5, '2月去的水心寨，一个人出行。地点在常德，地铁到达方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约572元，氛围感不错。景点印象：桃源水心寨位于桃源境内沅江与夷望溪交汇之处，四面环水，高约数百尺，壁立陡峭，上攀山岩，前后人头脚相接，须抓住铁链而上。山岩原名水心岩，因南宋洞庭湖区农民起义军首领杨幺曾在此驻军，并立坛祭苍天，后人因此改名水心寨。寨顶有小观，自古就…整体感受是特别满意，很推荐。二刷意愿：是。', '11%', 52);
