INSERT INTO `travel_review` VALUES (7548, 'TR007548', '四龙剪金山', '白银', '甘肃', '拍照旅行', '春季', 2, 2, 715.00, '否', 4, '2月去的四龙剪金山，情侣出行。地点在白银，自驾停车需要提前规划，现场人流量适中。这次玩了2天，人均花费约715元，氛围感不错。景点印象：县级文物保护单位。位于白银区四龙镇北 15 公里 ，距白银市区 40 公里 。剪金山原名百花山，始建于北宋天圣元年（公元 1032 年），清代乾隆十九年（公元 1754 年）两次维修扩建，全部古建筑面积约 7000 平方米 ，寺庙高大宏伟，颇为壮观。每年农历…整体感受是整体不错，周末来刚好。二刷意愿：否。', '0%', 63);
