INSERT INTO `travel_review` VALUES (7592, 'TR007592', '鱼谷洞泉自然风景区', '保定', '河北', '城市漫游', '冬季', 10, 1, 546.00, '是', 5, '10月去的鱼谷洞泉自然风景区，情侣出行。地点在保定，地铁到达方便，现场游客较多。这次玩了1天，人均花费约546元，历史文化气息浓。景点印象：八大怪泉之一，每年谷雨节前后从泉口向外涌鱼，泉水也十分甘甜。整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 80);
INSERT INTO `travel_review` VALUES (7593, 'TR007593', '神农溪纤夫文化走廊', '恩施', '湖北', '亲子出游', '冬季', 11, 6, 1122.00, '否', 4, '11月去的神农溪纤夫文化走廊，和朋友出行。地点在恩施，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了6天，人均花费约1122元，拍照很出片。景点印象：乘坐游船，畅游在溪流中，两岸满目苍翠，悬崖峭壁上还有古老神秘的悬棺。 能够欣赏到当地的民族表演，还有船工们的三峡纤夫拉纤表演。整体感受是体验挺好，推荐来看看。二刷意愿：否。', '11%', 75);
