INSERT INTO `travel_review` VALUES (7595, 'TR007595', '五道豁洛影视城', '黑河', '黑龙江', '拍照旅行', '春季', 1, 3, 1207.00, '否', 3, '1月去的五道豁洛影视城，情侣出行。地点在黑河，打车比较省心，现场游客较多。这次玩了3天，人均花费约1207元，历史文化气息浓。景点印象：五道豁洛影视城位于黑龙江中方一侧，距黑河市区1.5公里处。五道豁洛岛旅游区共分为影视基地、黑龙湾、历史文物馆、原始人部落、天然动物园五个景区。后几个景区正在规划和修复之中。影视基地建于中俄界河―黑龙江的五道豁洛岛上，占地面积12万平方…整体感受是中规中矩，按需选择。二刷意愿：否。', '14%', 58);
