INSERT INTO `travel_review` VALUES (7597, 'TR007597', '红叶谷', '济南', '山东', '拍照旅行', '春季', 1, 1, 215.00, '否', 5, '1月去的红叶谷，情侣出行。地点在济南，公交换乘方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约215元，氛围感不错。景点印象：秋季来此，登高远眺山谷，可赏山谷中满山红叶，层林尽染，无比鲜艳。 蔷薇园、樱花园、百合园，每年会举行各种花展，景色非常绚丽。整体感受是特别满意，以后还会来。二刷意愿：否。', '3%', 127);
INSERT INTO `travel_review` VALUES (7598, 'TR007598', '德云社', '南京', '江苏', '文化打卡', '秋季', 6, 1, 634.00, '否', 2, '6月去的德云社，情侣出行。地点在南京，地铁到达方便，现场游客较多。这次玩了1天，人均花费约634元，拍照很出片。景点印象：南京德云社剧场位于南京市老门东步行街箍桶巷128号，是由郭德纲先生创立的北京德云社在南京建立的分社。剧场建筑为中式传统建筑，面积近1200平方米，可容纳观众260人左右。整体感受是略失望，不建议高峰来。二刷意愿：否。', '0%', 88);
