INSERT INTO `travel_review` VALUES (7615, 'TR007615', '巧家药山', '昭通', '云南', '亲子出游', '冬季', 9, 3, 923.00, '否', 5, '9月去的巧家药山，一个人出行。地点在昭通，公交换乘方便，现场游客较多。这次玩了3天，人均花费约923元，历史文化气息浓。景点印象：药山位于巧家县境内。金沙江和牛栏江环山而过。药山山体面积220平方公里，主峰金顶山海拔4042米，雄踞于昭通群峰之上。\n由于受北―东向构成控制发育成型，药山走向近于北―东。西坡地势陡峭，悬崖绝壁从两江汇流的谷地中凌宵而起，柱地擎天，高不可…整体感受是特别满意，很推荐。二刷意愿：否。', '0%', 107);
