INSERT INTO `travel_review` VALUES (7664, 'TR007664', '二十里铺拱北', '固原', '宁夏', '拍照旅行', '秋季', 8, 1, 434.00, '否', 4, '8月去的二十里铺拱北，和朋友出行。地点在固原，地铁到达方便，现场人不算多。这次玩了1天，人均花费约434元，夜景表现很好。景点印象：固原县城南二十里，平银公路的东侧，渡过清水河，在树木葱郁的幽雅环境中，依山势矗立着一座集中国传统建筑和伊斯兰建筑风格于一体的寺院，气势恢宏、古朴典雅、肃穆神密，这就是闻名国内的固原二十里铺拱北。\n二十里铺拱北自康熙十六年创建，因诸…整体感受是整体不错，推荐来看看。二刷意愿：否。', '0%', 60);
