INSERT INTO `travel_review` VALUES (7677, 'TR007677', '崇安寺', '晋城', '山西', '亲子出游', '秋季', 8, 1, 569.00, '是', 5, '8月去的崇安寺，情侣出行。地点在晋城，打车比较省心，现场人不算多。这次玩了1天，人均花费约569元，夜景表现很好。景点印象：崇安寺，古称凌烟寺，位于山西省陵川县崇文镇西北的卧龙岗上，大有居高临下，俯瞰全城的雄伟气魄，\"先有崇安，后有陵川\"的远古说法在当地流传甚广。\n崇安寺的创始年代已无从稽考，唐初原名为\"丈八佛寺\'，宋太平兴国元年？？公元976年？？敕命为崇…整体感受是特别满意，以后还会来。二刷意愿：是。', '2%', 109);
