INSERT INTO `travel_review` VALUES (7693, 'TR007693', '花洲书院', '南阳', '河南', '拍照旅行', '春季', 2, 5, 1181.00, '是', 5, '2月去的花洲书院，一个人出行。地点在南阳，打车比较省心，现场高峰时段比较拥挤。这次玩了5天，人均花费约1181元，历史文化气息浓。景点印象：周边配套比较齐全整体感受是特别满意，以后还会来。二刷意愿：是。', '2%', 105);
INSERT INTO `travel_review` VALUES (7694, 'TR007694', '长江索道', '重庆', '重庆', '周末短途', '冬季', 10, 1, 275.00, '否', 5, '10月去的长江索道，一个人出行。地点在重庆，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约275元，氛围感不错。景点印象：乘坐索道从空中滑向长江对岸，沿途欣赏山城的钢筋森林和两岸景色。整体感受是特别满意，以后还会来。二刷意愿：否。', '31%', 21);
INSERT INTO `travel_review` VALUES (7695, 'TR007695', '茶马古道', '雅安', '四川', '文化打卡', '冬季', 10, 1, 564.00, '否', 5, '10月去的茶马古道，情侣出行。地点在雅安，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约564元，夜景表现很好。景点印象：茶马古道是我国古代川、滇、藏地区的一条交通要道，是中国西南民族经济文化交流的走廊。整体感受是特别满意，值得专门打卡。二刷意愿：否。', '1%', 99);
INSERT INTO `travel_review` VALUES (7696, 'TR007696', '天脊龙门', '衢州', '浙江', '深度游', '夏季', 3, 2, 361.00, '否', 2, '3月去的天脊龙门，和朋友出行。地点在衢州，公交换乘方便，现场人流量适中。这次玩了2天，人均花费约361元，夜景表现很好。景点印象：以“龙”为卖点的峡谷瀑布景观，绿树掩映中水流不断，夏天玩水十分清凉。 走在山崖间百余米的悬空索桥上，赏山谷中青翠宜人的景色。 坐飞天大滑索下山，体验失重俯冲的惊险刺激。整体感受是体验偏一般，不建议高峰来。二刷意愿：否。', '8%', 46);
INSERT INTO `travel_review` VALUES (7697, 'TR007697', '长白山大峡谷', '白山', '吉林', '周末短途', '春季', 2, 1, 583.00, '否', 4, '2月去的长白山大峡谷，情侣出行。地点在白山，打车比较省心，现场人流量适中。这次玩了1天，人均花费约583元，拍照很出片。景点印象：位于白山市扶松县境内，是近几年发现的自然奇观，可与美国大峡谷相媲美。长白山大峡谷长70多公里，乃火山爆发后熔岩石表面的火山灰和泥土被江水及雨水冲刷而成。北锦江流经谷底，只见两岸怪石林立，奇景叠生，栩栩如生，美不胜收。整体感受是整体不错，推荐来看看。二刷意愿：否。', '26%', 77);
INSERT INTO `travel_review` VALUES (7698, 'TR007698', '洋浦湾', '儋州', '海南', '拍照旅行', '秋季', 6, 1, 425.00, '是', 5, '6月去的洋浦湾，和朋友出行。地点在儋州，公交换乘方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约425元，夜景表现很好。景点印象：周边配套比较齐全整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 128);
INSERT INTO `travel_review` VALUES (7699, 'TR007699', '圣迹苍岩', '河源', '广东', '城市漫游', '冬季', 9, 3, 854.00, '否', 4, '9月去的圣迹苍岩，和朋友出行。地点在河源，地铁到达方便，现场游客较多。这次玩了3天，人均花费约854元，拍照很出片。景点印象：圣迹苍岩旅游区座落在广东省连平县重点生态保护区内，位于105国道边，距离连平县城10公里，风景如画，素以优美的田园景色著称。景区的旅游事业迅速发展。现已建成以生态文化为主题，集观光农业、休闲度假、客家风情、美食购物于一体，环境优美，品…整体感受是还蛮满意，可以安排半天到一天。二刷意愿：否。', '4%', 43);
