INSERT INTO `travel_review` VALUES (7701, 'TR007701', '东狮山', '宁德', '福建', '深度游', '秋季', 6, 4, 906.00, '是', 5, '6月去的东狮山，一个人出行。地点在宁德，公交换乘方便，现场游客较多。这次玩了4天，人均花费约906元，氛围感不错。景点印象：东狮山是太姥山脉的主峰，海拔1480米，气势雄伟。东狮山属花岗岩地貌，岩体、岩洞千姿百态。整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 115);
