INSERT INTO `travel_review` VALUES (7775, 'TR007775', '龙凤岩', '抚州', '江西', '周末短途', '冬季', 9, 1, 770.00, '否', 2, '9月去的龙凤岩，一个人出行。地点在抚州，打车比较省心，现场人不算多。这次玩了1天，人均花费约770元，氛围感不错。景点印象：位于广昌县城西偏南16公里的东华山下，方圆十多公里，奇峰、怪石、山泉、楼宇均具物色。楼亭梵宇依岩而设，东西石壁相蹯踞，状如龙凤腾翔。前岩洞穴内有一所庙宇，是龙凤岩的“大门”，沿着小径和溪流可进入中岩。中岩洞内可容纳上百人。岩洞高处飞…整体感受是体验偏一般，可考虑其他景点。二刷意愿：否。', '0%', 48);
