INSERT INTO `travel_review` VALUES (7799, 'TR007799', '紫团山', '长治', '山西', '亲子出游', '春季', 1, 2, 625.00, '是', 4, '1月去的紫团山，一个人出行。地点在长治，公交换乘方便，现场人流量适中。这次玩了2天，人均花费约625元，拍照很出片。景点印象：壶关有个避暑胜地叫紫团山。在壶关县东南60公里的树掌镇。紫团山又名翠微山，抱犊山。晋代旅游家抱朴子在游历了我国名山丽川后曾写道：“天下佳山者南五夷，北抱犊。”北抱犊山就是指的这里。因山腰有一形成于30万年前的天然溶洞，坐东面西，每天日…整体感受是还蛮满意，周末来刚好。二刷意愿：是。', '4%', 40);
INSERT INTO `travel_review` VALUES (7800, 'TR007800', '张学良旧居', '沈阳', '辽宁', '拍照旅行', '秋季', 6, 1, 207.00, '是', 5, '6月去的张学良旧居，和朋友出行。地点在沈阳，打车比较省心，现场游客较多。这次玩了1天，人均花费约207元，拍照很出片。景点印象：参观大青楼、赵一荻故居等著名建筑，以及张氏父子的墨宝与遗存文物。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '38%', 78);
INSERT INTO `travel_review` VALUES (7801, 'TR007801', '简州新城龙马湖公园', '资阳', '四川', '周末短途', '冬季', 10, 2, 80.00, '是', 5, '10月去的简州新城龙马湖公园，和家人出行。地点在资阳，打车比较省心，现场人流量适中。这次玩了2天，人均花费约80元，夜景表现很好。景点印象：周边配套比较齐全整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 91);
INSERT INTO `travel_review` VALUES (7802, 'TR007802', '金代石拱桥', '朝阳', '辽宁', '周末短途', '春季', 1, 3, 858.00, '否', 4, '1月去的金代石拱桥，情侣出行。地点在朝阳，地铁到达方便，现场人不算多。这次玩了3天，人均花费约858元，拍照很出片。景点印象：在凌源市天盛号乡天盛号村外的一片沙质荒地上，发掘出一座古代石拱桥，经考证确定的金代民用石拱桥。\n石拱桥横跨古河床，为上下拱结构，是一座五柱头、四栏板的单孔石拱桥。桥宽4.7米，长3.8米，高3.4米，拱宽3.5米，两边有八字迎水墙，桥拱孔道跨…整体感受是整体不错，可以安排半天到一天。二刷意愿：否。', '0%', 60);
INSERT INTO `travel_review` VALUES (7803, 'TR007803', '江西贵溪华夏奇石博览馆', '鹰潭', '江西', '亲子出游', '秋季', 8, 1, 859.00, '否', 5, '8月去的江西贵溪华夏奇石博览馆，情侣出行。地点在鹰潭，公交换乘方便，现场人流量适中。这次玩了1天，人均花费约859元，拍照很出片。景点印象：周边配套比较齐全整体感受是挺惊喜，很推荐。二刷意愿：否。', '0%', 95);
INSERT INTO `travel_review` VALUES (7804, 'TR007804', '北流泉', '天水', '甘肃', '拍照旅行', '春季', 2, 7, 1894.00, '否', 5, '2月去的北流泉，和朋友出行。地点在天水，地铁到达方便，现场人流量适中。这次玩了7天，人均花费约1894元，拍照很出片。景点印象：北流泉位于南郭寺东院六角亭下，原名不详，自杜甫诗“水号北流泉”后千百年来一直称北流泉，延续至今。北流泉千百年来未见其涸。《天水县志》记：“东有泉，旱盈潦缩，祈雨极验”。此泉在天大旱时，水旺如旧。附近村民取水饮用，浇灌农田，不见其竭…整体感受是特别满意，很推荐。二刷意愿：否。', '0%', 111);
