INSERT INTO `travel_review` VALUES (7856, 'TR007856', '怪山', '通辽', '内蒙古', '深度游', '秋季', 6, 6, 1877.00, '否', 3, '6月去的怪山，和家人出行。地点在通辽，地铁到达方便，现场游客较多。这次玩了6天，人均花费约1877元，夜景表现很好。景点印象：怪山旅游区位于内蒙古霍林郭勒市西北14公里处，距通辽市政府所在地科尔沁区320公里，占地11.4平方公里。景区内分营业区、水库区和自然保护区。怪山由地壳运动时挤压而形成，山脉长度约2000米，海拔1199.3米。闻名于世的怪山耸立在哈布其勒水库岸边…整体感受是还可以，别抱太高期待。二刷意愿：否。', '4%', 31);
INSERT INTO `travel_review` VALUES (7857, 'TR007857', '秀山历史文化公园', '玉溪', '云南', '周末短途', '秋季', 7, 3, 879.00, '是', 2, '7月去的秀山历史文化公园，情侣出行。地点在玉溪，地铁到达方便，现场人流量适中。这次玩了3天，人均花费约879元，拍照很出片。景点印象：玉溪秀山历史文化公园，位于云南玉溪通海县城南隅，峰顶海拔2060米，垂直高度近200米，辖区面积7.6平方公里，游览面积155万平方米，建筑面积5万余平方米。秀山历史文化公园是玉溪地区重要风景区之一。秀山之秀在于绿，茂密的林木把整座山掩盖得严严…整体感受是略失望，建议谨慎前往。二刷意愿：是。', '0%', 80);
