INSERT INTO `travel_review` VALUES (7873, 'TR007873', '荆江分洪工程纪念碑', '荆州', '湖北', '文化打卡', '秋季', 7, 3, 998.00, '否', 5, '7月去的荆江分洪工程纪念碑，和朋友出行。地点在荆州，公交换乘方便，现场人流量适中。这次玩了3天，人均花费约998元，历史文化气息浓。景点印象：在荆江南岸公安县太平口与北岸沙市大堤上。共有两组。为纪念1952年完成的荆江分洪工程而建。分洪区位于荆江和虎渡河之间，面积921平方公里，进洪闸长1054米，高46． 5米，分设54孔，每孔跨度18米，气势磅礴，雄伟壮观。碑为方形塔式，3层，高10余米…整体感受是挺惊喜，以后还会来。二刷意愿：否。', '6%', 64);
