INSERT INTO `travel_review` VALUES (7887, 'TR007887', '谢鲁天堂温泉休闲度假村', '玉林', '广西', '文化打卡', '冬季', 10, 1, 394.00, '是', 5, '10月去的谢鲁天堂温泉休闲度假村，和朋友出行。地点在玉林，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约394元，历史文化气息浓。景点印象：距县城25公里，离玉林市70公里，至华南第一大港口城市湛江约133公里，是按国际四星标准设计和建设的、以先进温泉养生理念打造的精致休闲、保健养生的建筑类人文风景旅游区。\n度假中心内有被称为“岭南第一泉”、岭南唯一的可泡可喝的飞龙山温矿泉，…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '12%', 85);
