INSERT INTO `travel_review` VALUES (7906, 'TR007906', '谢鲁天堂温泉休闲度假村', '玉林', '广西', '亲子出游', '夏季', 3, 4, 1244.00, '是', 4, '3月去的谢鲁天堂温泉休闲度假村，一个人出行。地点在玉林，公交换乘方便，现场人不算多。这次玩了4天，人均花费约1244元，夜景表现很好。景点印象：距县城25公里，离玉林市70公里，至华南第一大港口城市湛江约133公里，是按国际四星标准设计和建设的、以先进温泉养生理念打造的精致休闲、保健养生的建筑类人文风景旅游区。\n度假中心内有被称为“岭南第一泉”、岭南唯一的可泡可喝的飞龙山温矿泉，…整体感受是体验挺好，推荐来看看。二刷意愿：是。', '12%', 67);
