INSERT INTO `travel_review` VALUES (7957, 'TR007957', '苍儿会生态旅游区', '吕梁', '山西', '城市漫游', '春季', 12, 2, 1002.00, '是', 5, '12月去的苍儿会生态旅游区，和朋友出行。地点在吕梁，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约1002元，历史文化气息浓。景点印象：山西·吕梁山·苍儿会生态旅游经济区为国家级森林公园，总面积360平方公里，地处女皇武则天故里山西省吕梁市文水县。距山西省省会太原仅80公里，全程1小时。\n经济园区有着丰富的森林植被资源和独特的自然景观，还有历史悠久的人文景观，这里森林葱…整体感受是超出预期，很推荐。二刷意愿：是。', '9%', 103);
