INSERT INTO `travel_review` VALUES (7999, 'TR007999', '八台山风景名胜区', '达州', '四川', '亲子出游', '秋季', 8, 2, 733.00, '否', 2, '8月去的八台山风景名胜区，和朋友出行。地点在达州，地铁到达方便，现场人不算多。这次玩了2天，人均花费约733元，夜景表现很好。景点印象：八台山风景名胜区由八台山、龙潭河、百藏堂、驮山四大鹌鹑区组成的八台山省级风景名胜区。其有各类景点100多人，总面积120平方千米，位于川东北的万源市境地内。\n主景区八台山的主峰海拔2273米，游人登顶可观日出、云海、佛光等景观。山下龙潭河滩…整体感受是体验偏一般，不建议高峰来。二刷意愿：否。', '0%', 33);
