INSERT INTO `travel_review` VALUES (8021, 'TR008021', '峙峪遗址', '朔州', '山西', '深度游', '冬季', 10, 1, 210.00, '是', 5, '10月去的峙峪遗址，情侣出行。地点在朔州，打车比较省心，现场人流量适中。这次玩了1天，人均花费约210元，历史文化气息浓。景点印象：位于朔州城西北15公里的黑驼山脚下，是一处旧石器时代的人类遗址，中国科学院1963年发现。现为省级重点文物保护单位。这里除发现大批细小石器和大量动物化石外，还发掘出数百件有刻划痕迹的兽片和一件人类初期的武器――石旋.整体感受是特别满意，以后还会来。二刷意愿：是。', '2%', 119);
