INSERT INTO `travel_review` VALUES (8077, 'TR008077', '江西省国际体育健身运动中心', '宜春', '江西', '拍照旅行', '秋季', 7, 1, 80.00, '是', 5, '7月去的江西省国际体育健身运动中心，情侣出行。地点在宜春，地铁到达方便，现场人不算多。这次玩了1天，人均花费约80元，拍照很出片。景点印象：江西省国际体育健身运动中心，位于江西南方环保机制总公司生产科研基地奉新县境内越山脚下，距省会南昌市80公里，占地面积10平方公里，境内丘陵起伏、森林密布、清澈的潦河贯穿全境，是天然的健身休闲胜地，既有自然风光，又有现代特色。\n本中心隶…整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 107);
