INSERT INTO `travel_review` VALUES (8138, 'TR008138', '白水岭热带森林', '万宁', '海南', '周末短途', '春季', 2, 1, 642.00, '是', 5, '2月去的白水岭热带森林，一个人出行。地点在万宁，公交换乘方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约642元，氛围感不错。景点印象：属热带原始森林，总面积45700多亩，这里生长着茂密的热带山地雨季林，林中栖息着种类众多的珍稀动物，被誉为海南物华天宝之地，是热带森林旅游观光的好去处。\n进入保护区古林绿海之中，那林海涛声，时而咆哮，时而低吟。立于山巅俯视，日挂中天，树…整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 121);
