INSERT INTO `travel_review` VALUES (8161, 'TR008161', '北流泉', '天水', '甘肃', '深度游', '秋季', 7, 3, 1170.00, '否', 5, '7月去的北流泉，和朋友出行。地点在天水，地铁到达方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约1170元，拍照很出片。景点印象：北流泉位于南郭寺东院六角亭下，原名不详，自杜甫诗“水号北流泉”后千百年来一直称北流泉，延续至今。北流泉千百年来未见其涸。《天水县志》记：“东有泉，旱盈潦缩，祈雨极验”。此泉在天大旱时，水旺如旧。附近村民取水饮用，浇灌农田，不见其竭…整体感受是特别满意，很推荐。二刷意愿：否。', '0%', 81);
