INSERT INTO `travel_review` VALUES (8164, 'TR008164', '三和牡丹景区', '临汾', '山西', '文化打卡', '春季', 2, 3, 920.00, '否', 2, '2月去的三和牡丹景区，一个人出行。地点在临汾，打车比较省心，现场高峰时段比较拥挤。这次玩了3天，人均花费约920元，氛围感不错。景点印象：位于山西晋南的古县历史悠久，文化底蕴深厚。据史记载，早在六千多年前仰韶文化时期当地已有人群居住繁衍，上古时期曾是大禹治水之地。在烟波浩渺的历史长河中，古县涌现出蔺相如等著名政治家，近代的古县还留有朱德、刘少奇、邓小平、薄一波、陈赓…整体感受是略失望，建议谨慎前往。二刷意愿：否。', '0%', 87);
