INSERT INTO `travel_review` VALUES (8205, 'TR008205', '天主教堂', '抚州', '江西', '文化打卡', '冬季', 10, 2, 846.00, '否', 2, '10月去的天主教堂，和家人出行。地点在抚州，打车比较省心，现场高峰时段比较拥挤。这次玩了2天，人均花费约846元，夜景表现很好。景点印象：位于临川市文昌桥东的灵山路，始建于清光绪三十四年（1908年），竣工于民国7年（1918年），是全国第三大天主教堂，歌特式建筑，整个教堂占地面积3850平方米，建筑面积2109平方米，教堂长62米，宽34米，高30米，前后共有六座塔楼，正面为钟楼，整个…整体感受是略失望，建议谨慎前往。二刷意愿：否。', '11%', 43);
