INSERT INTO `travel_review` VALUES (8245, 'TR008245', '通济湖风景区', '金华', '浙江', '周末短途', '秋季', 8, 1, 337.00, '否', 4, '8月去的通济湖风景区，情侣出行。地点在金华，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约337元，拍照很出片。景点印象：通济湖也称通济桥水库，现已成为一旅游景点。位于浙江省浦江县城西3公里处，浦阳江上游。 景区面积6平方公里，库容量5800万立方米，水域面积5平方公里。湖中有岛屿6个，半岛数十，景点10余处，有“百岛湖”之称。济湖(通济桥水库)，库容量5800万立…整体感受是体验挺好，推荐来看看。二刷意愿：否。', '0%', 78);
