INSERT INTO `travel_review` VALUES (8254, 'TR008254', '福建土楼(永定)景区', '龙岩', '福建', '拍照旅行', '冬季', 10, 3, 722.00, '否', 5, '10月去的福建土楼(永定)景区，和朋友出行。地点在龙岩，打车比较省心，现场人不算多。这次玩了3天，人均花费约722元，历史文化气息浓。景点印象：中国建筑史上的奇葩，独一无二的神奇山居建筑凸显着聚族而居的客家人的古老传统。整体感受是特别满意，值得专门打卡。二刷意愿：否。', '72%', 109);
INSERT INTO `travel_review` VALUES (8255, 'TR008255', '东晋壁画墓', '朝阳', '辽宁', '城市漫游', '夏季', 3, 3, 1568.00, '否', 3, '3月去的东晋壁画墓，和家人出行。地点在朝阳，地铁到达方便，现场人流量适中。这次玩了3天，人均花费约1568元，氛围感不错。景点印象：东晋壁画墓，位于十二台乡袁台子村，呈长方形，石筑墓室，墓内有百室和小龛，墓壁白灰面，并施彩绘画面，墓顶绘有鸟， 星云阁，墓壁绘墓主像，侍女图、射猎图、 秦食图、庖橱图、庭院图，极具考古价值。整体感受是体验一般，别抱太高期待。二刷意愿：否。', '0%', 40);
INSERT INTO `travel_review` VALUES (8256, 'TR008256', '国清景区', '台州', '浙江', '周末短途', '夏季', 5, 5, 1132.00, '是', 5, '5月去的国清景区，和朋友出行。地点在台州，自驾停车需要提前规划，现场游客较多。这次玩了5天，人均花费约1132元，拍照很出片。景点印象：清静从容的隋代古刹，中国天台宗祖庭，游天台的必到景点之一。 在寺内礼佛祈福，观隋塔、唐樟、宋藤，品味隋唐遗韵。整体感受是挺惊喜，很推荐。二刷意愿：是。', '21%', 97);
