INSERT INTO `travel_review` VALUES (8259, 'TR008259', '龙潭瀑布', '商洛', '陕西', '周末短途', '夏季', 3, 2, 452.00, '否', 5, '3月去的龙潭瀑布，一个人出行。地点在商洛，公交换乘方便，现场游客较多。这次玩了2天，人均花费约452元，氛围感不错。景点印象：州东百里，龙驹寨东河，即涌峪河，两峰对峙，一水直泻为瀑布，下为龙潭，潭中有巨石连岸，危步临之，真奇观也。\n[注释]危步：小心谨慎地行走。此景在今舟凤县城东北2．5公里处。整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '0%', 98);
