INSERT INTO `travel_review` VALUES (8343, 'TR008343', '绝望坡', '吉安', '江西', '文化打卡', '冬季', 10, 2, 1042.00, '是', 5, '10月去的绝望坡，情侣出行。地点在吉安，自驾停车需要提前规划，现场游客较多。这次玩了2天，人均花费约1042元，氛围感不错。景点印象：绝望坡最陡的山坡大概有70°角，具有冒险精神的人可以去尝试。此地云雾缭绕，大大小小的山坡有二十多个，最起码要走上几个小时，有一种永远看不到尽头的感觉。整体感受是特别满意，很推荐。二刷意愿：是。', '17%', 95);
INSERT INTO `travel_review` VALUES (8344, 'TR008344', '大连自然博物馆', '大连', '辽宁', '拍照旅行', '春季', 1, 3, 491.00, '否', 5, '1月去的大连自然博物馆，情侣出行。地点在大连，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了3天，人均花费约491元，氛围感不错。景点印象：动植物标本和化石非常丰富，馆藏鹦鹉嘴龙化石等许多珍稀藏品。整体感受是特别满意，值得专门打卡。二刷意愿：否。', '5%', 106);
