INSERT INTO `travel_review` VALUES (8376, 'TR008376', '甘坑古镇', '深圳', '广东', '亲子出游', '春季', 12, 2, 317.00, '否', 5, '12月去的甘坑古镇，情侣出行。地点在深圳，地铁到达方便，现场游客较多。这次玩了2天，人均花费约317元，夜景表现很好。景点印象：有着百年历史的原生态客家古镇，是体验农作、闲逛、吃客家菜的好去处。整体感受是特别满意，以后还会来。二刷意愿：否。', '0%', 114);
INSERT INTO `travel_review` VALUES (8377, 'TR008377', '云门山风景区', '潍坊', '山东', '城市漫游', '春季', 12, 2, 612.00, '否', 5, '12月去的云门山风景区，一个人出行。地点在潍坊，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了2天，人均花费约612元，夜景表现很好。景点印象：青州标志性景点之一，赏石龛造像和摩崖石刻，登上山顶可尽览城区风光。整体感受是挺惊喜，很推荐。二刷意愿：否。', '11%', 97);
