INSERT INTO `travel_review` VALUES (8379, 'TR008379', '广丰村水乡游', '中山', '广东', '城市漫游', '春季', 2, 3, 733.00, '是', 5, '2月去的广丰村水乡游，情侣出行。地点在中山，打车比较省心，现场人不算多。这次玩了3天，人均花费约733元，拍照很出片。景点印象：水乡旅游点位于城区之北三公里的广丰村。这里一派水乡田野气息。该游点的特色是提供游乐品尝服务。项目有：自由划，欣赏水乡；漫步橙园，自由采摘；提供鱼具，水塘垂钓，如果有兴趣还可到附近的餐厅下锅品尝自己钓到的鱼；品尝这里种植的鲜茉莉花茶…整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 60);
