INSERT INTO `travel_review` VALUES (8385, 'TR008385', '老爷岭', '锦州', '辽宁', '周末短途', '冬季', 9, 3, 1115.00, '否', 5, '9月去的老爷岭，一个人出行。地点在锦州，打车比较省心，现场游客较多。这次玩了3天，人均花费约1115元，历史文化气息浓。景点印象：老爷岭风景区位于闾山西麓，座落在义县东大榆树堡镇境内。是国家级自然保护区。老爷岭建有上下两院，上院有出巡殿、武圣殿、三清殿，建在义县与北宁“山界”处因寺中所塑为关公像，故称老爷庙，山便因庙而得名。附近山势险要，林木葱荫，站在上院远…整体感受是挺惊喜，以后还会来。二刷意愿：否。', '0%', 76);
