INSERT INTO `travel_review` VALUES (8388, 'TR008388', '仙庾风景', '株洲', '湖南', '文化打卡', '春季', 1, 1, 559.00, '是', 5, '1月去的仙庾风景，一个人出行。地点在株洲，公交换乘方便，现场人流量适中。这次玩了1天，人均花费约559元，历史文化气息浓。景点印象：仙庾风景名胜区位于株洲市荷塘区东北方仙庾镇境内，有公路直达市中心，路距15公里。东与浏阳毗邻，南距大京风景区10多公里，景区两侧有株浏公路、茶马公路通过，交通十分便利。\n仙庾岭主峰海拔233米，位于主峰之上的文昌阁又名仙庾塔，为八角形石…整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 103);
