INSERT INTO `travel_review` VALUES (8400, 'TR008400', '罗哲烈士墓', '株洲', '湖南', '拍照旅行', '秋季', 6, 2, 429.00, '否', 5, '6月去的罗哲烈士墓，一个人出行。地点在株洲，地铁到达方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约429元，拍照很出片。景点印象：位于马家河乡高塘村，距县城17公里， 墓冢朝西偏南，三沙土筑成，底径2.3米，堆高0.5米，墓围上方竖汉白玉石碑3块，边框与碑顶饰花岗岩，总高2米。正中墓碑阴刻毛泽东主席手书“罗哲烈士之墓”，两旁为墓志，记载烈士生平事迹。\n罗哲烈士是早期中共…整体感受是特别满意，很推荐。二刷意愿：否。', '0%', 82);
