INSERT INTO `travel_review` VALUES (8405, 'TR008405', '泗水塔', '南阳', '河南', '城市漫游', '秋季', 8, 3, 798.00, '是', 5, '8月去的泗水塔，情侣出行。地点在南阳，打车比较省心，现场游客较多。这次玩了3天，人均花费约798元，历史文化气息浓。景点印象：泗洲塔又称泗水塔，位于唐河县城东南隅菩提寺旧址内。宋绍圣二年（1095年）建，高47.33米。底层坐落在台基上，南面辟一拱形门，第二至十层每层各辟1门。下均置砖雕斗拱，转角处有风铎，檐下为平座，塔内有塔心柱，柱之周围筑盘88旋石阶踏道，第一层…整体感受是特别满意，很推荐。二刷意愿：是。', '0%', 52);
