INSERT INTO `travel_review` VALUES (8467, 'TR008467', '毕升森林公园', '黄冈', '湖北', '拍照旅行', '春季', 2, 1, 271.00, '是', 5, '2月去的毕升森林公园，和朋友出行。地点在黄冈，打车比较省心，现场人不算多。这次玩了1天，人均花费约271元，氛围感不错。景点印象：毕升森林公园位于湖北省英山县城北郊，占地约一万亩，三十二处人文景点分布全园，自一九九八年建园以来，共接待游客近五十万人次。\n这里自然风光秀美：既有原始森林的恬静，又有现代都市的繁华；既有蓝天白云的广阔，又有小桥流水的温柔。这里人文…整体感受是特别满意，以后还会来。二刷意愿：是。', '0%', 117);
