INSERT INTO `travel_review` VALUES (8474, 'TR008474', '王家屏墓', '朔州', '山西', '拍照旅行', '春季', 2, 2, 1070.00, '是', 4, '2月去的王家屏墓，和家人出行。地点在朔州，公交换乘方便，现场游客较多。这次玩了2天，人均花费约1070元，氛围感不错。景点印象：位于山阴县西南15公里的泥河乡河阳堡村南，是明代著名政治家王家屏之墓，为省级重点文物保护单位。王家屏墓占地 10168平方米，规模宏大，地面享堂犹存，有石人、石羊、石马等仪仗及碑石10通，碑文大部分为圣旨加封等内容，现已破坏严重。整体感受是还蛮满意，可以安排半天到一天。二刷意愿：是。', '0%', 50);
