INSERT INTO `travel_review` VALUES (8478, 'TR008478', '岳阳门', '岳阳', '湖南', '城市漫游', '春季', 2, 1, 254.00, '是', 5, '2月去的岳阳门，和家人出行。地点在岳阳，地铁到达方便，现场游客较多。这次玩了1天，人均花费约254元，夜景表现很好。景点印象：上跨雄伟的岳阳楼，下临浩淼的洞庭湖水。岳阳门就是岳阳的古城西门。古时候，岳阳有五座城门。叫湘春门的是东门，叫迎薰门是南门，叫楚望门的是北门，西门就是岳阳门，还有一座小西门。整体感受是超出预期，值得专门打卡。二刷意愿：是。', '1%', 80);
