INSERT INTO `travel_review` VALUES (8492, 'TR008492', '沭阳肖湖', '宿迁', '江苏', '拍照旅行', '春季', 2, 1, 463.00, '否', 5, '2月去的沭阳肖湖，一个人出行。地点在宿迁，公交换乘方便，现场人流量适中。这次玩了1天，人均花费约463元，氛围感不错。景点印象：1997年5月，省农林厅批准建立嶂山森林公园。公园位于宿迁市区以北7公里处的宿豫县境内，总面积7.2平方公里，森林覆盖率达67.7%。地处马陵山南麓，南端为天然草坪，中间为丘陵，北部为平原，西侧为湖泊。山有锅框山、鏊子山、三台山(海拔73.4米)；水…整体感受是挺惊喜，很推荐。二刷意愿：否。', '0%', 127);
