INSERT INTO `travel_review` VALUES (8495, 'TR008495', '天柱山', '安庆', '安徽', '城市漫游', '春季', 2, 5, 992.00, '是', 5, '2月去的天柱山，和朋友出行。地点在安庆，打车比较省心，现场高峰时段比较拥挤。这次玩了5天，人均花费约992元，氛围感不错。景点印象：观雄峰、怪石、奇洞、云海，领略“古南岳”绝美风光。整体感受是超出预期，值得专门打卡。二刷意愿：是。', '18%', 74);
