INSERT INTO `travel_review` VALUES (8497, 'TR008497', '东方大学城', '廊坊', '河北', '亲子出游', '夏季', 5, 1, 688.00, '是', 4, '5月去的东方大学城，情侣出行。地点在廊坊，打车比较省心，现场人流量适中。这次玩了1天，人均花费约688元，历史文化气息浓。景点印象：东方大学城位于廊坊市经济技术开发区，紧靠京津塘高速公路，距北京40公里，天津60公里。\n东方大学城占地2万亩，计划投资120亿元人民币，10年内要完成包括教学楼、科研实验楼、现代图书馆、运动中心、老师公寓以及幼教、小学、中学、医疗、商业餐饮…整体感受是整体不错，周末来刚好。二刷意愿：是。', '100%', 72);
