INSERT INTO `travel_review` VALUES (8514, 'TR008514', '清水泉旅游度假村', '昌吉', '新疆', '亲子出游', '夏季', 5, 1, 661.00, '否', 2, '5月去的清水泉旅游度假村，和家人出行。地点在昌吉，自驾停车需要提前规划，现场人不算多。这次玩了1天，人均花费约661元，历史文化气息浓。景点印象：位于硫磺沟镇以南8公里处，头屯河西岸，依山傍水，占地面积45708平方米，约67亩，总建筑面积1630平方米，景区内有一眼泉水涌出地面，甘甜清澈，潺潺不息，得名清水泉。 泉水蜿蜒流淌，形成多处天然水潭，泉水叮咚，自然回响。度假村内野生植被繁盛…整体感受是没达到预期，可考虑其他景点。二刷意愿：否。', '0%', 37);
