INSERT INTO `travel_review` VALUES (8528, 'TR008528', '台山凤凰峡小九寨', '江门', '广东', '文化打卡', '春季', 1, 4, 795.00, '否', 2, '1月去的台山凤凰峡小九寨，和家人出行。地点在江门，自驾停车需要提前规划，现场人流量适中。这次玩了4天，人均花费约795元，拍照很出片。景点印象：看绿林环绕，听流水潺潺，尽享原生态之美。整体感受是略失望，不建议高峰来。二刷意愿：否。', '0%', 46);
INSERT INTO `travel_review` VALUES (8529, 'TR008529', '嘎学岩画', '昌都', '西藏', '城市漫游', '春季', 2, 2, 971.00, '是', 5, '2月去的嘎学岩画，情侣出行。地点在昌都，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约971元，氛围感不错。景点印象：八宿嘎学岩画位于八宿县城以西5公里的巴冬牧场处。山高坡大路陡，交通不便，骑行约一天路程方可到达。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '1%', 50);
