INSERT INTO `travel_review` VALUES (8583, 'TR008583', '白龙庙', '吕梁', '山西', '周末短途', '夏季', 3, 3, 656.00, '是', 5, '3月去的白龙庙，情侣出行。地点在吕梁，自驾停车需要提前规划，现场人流量适中。这次玩了3天，人均花费约656元，夜景表现很好。景点印象：白龙庙位于岚县城西22公里与兴县接壤的白龙山腰部。该山原名大万山，因建有白龙庙而得名，是吕梁山向北延伸的一条支脉。它山势雄伟，挺拔俊秀，群峰耸立，层峦叠嶂。遍山苍松翠柏，名花异草，既有珍贵的省鸟褐马鸡及麋鹿、貂、麝等珍稀动物，又有“…整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 74);
