INSERT INTO `travel_review` VALUES (8586, 'TR008586', '蛇洞山', '齐齐哈尔', '黑龙江', '拍照旅行', '夏季', 3, 1, 304.00, '否', 5, '3月去的蛇洞山，和朋友出行。地点在齐齐哈尔，地铁到达方便，现场游客较多。这次玩了1天，人均花费约304元，氛围感不错。景点印象：位于齐齐哈尔市碾子山区西部4.5公里，占地面积300公顷，最高峰龙峰海拔406米，是国家“AA”级风景区。景区划分为六个功能区，包括以蛇洞山为主的主景区、利用雅鲁河水面开辟水上游乐区、野营区、动植物观赏区、宗教区、服务区，将休闲、娱乐、观赏…整体感受是挺惊喜，很推荐。二刷意愿：否。', '0%', 52);
