INSERT INTO `travel_review` VALUES (8619, 'TR008619', '福建省苏维埃政府旧址', '龙岩', '福建', '亲子出游', '春季', 12, 1, 463.00, '是', 3, '12月去的福建省苏维埃政府旧址，一个人出行。地点在龙岩，打车比较省心，现场人不算多。这次玩了1天，人均花费约463元，夜景表现很好。景点印象：福建省苏维埃政府旧址，全国重点文物保护单位，位于福建省长汀县汀州镇兆征路41号。该址宋代为汀州禁军署地，元代为汀州卫署址，明、清两代辟为试院，是汀州历史极具象征意义的一处古迹。1932年3月18日，福建省第一次工农兵代表大会在此隆重召开，…整体感受是体验一般，避开高峰更好。二刷意愿：是。', '1%', 56);
