INSERT INTO `travel_review` VALUES (8636, 'TR008636', '土司城墙', '恩施', '湖北', '深度游', '春季', 12, 2, 502.00, '是', 3, '12月去的土司城墙，和家人出行。地点在恩施，公交换乘方便，现场人流量适中。这次玩了2天，人均花费约502元，夜景表现很好。景点印象：土司城墙以土司城进口处左侧为起点，全长2320米，墙面宽1.2米，随山修筑，依山取形，逶迤延绵、雄伟壮观。土司城墙也取意恩施州内许多山寨寨墙和城墙，如利川鱼木寨、咸丰女儿寨，以及恩施市与柳州城的古城墙等。游览土司城墙和烽火台，不能不使人…整体感受是还可以，按需选择。二刷意愿：是。', '6%', 48);
