INSERT INTO `travel_review` VALUES (8668, 'TR008668', '寿丘', '济宁', '山东', '周末短途', '冬季', 11, 2, 1037.00, '否', 3, '11月去的寿丘，情侣出行。地点在济宁，地铁到达方便，现场游客较多。这次玩了2天，人均花费约1037元，拍照很出片。景点印象：寿丘为中华民族始祖黄帝的诞生地。现寿丘院为景灵宫前部，少昊陵为景灵宫后部。院内现有二碑，东为\"万人愁\"碑，上无字，体积巨大为中国石碑之最。整体感受是体验一般，按需选择。二刷意愿：否。', '0%', 40);
