INSERT INTO `travel_review` VALUES (8713, 'TR008713', '南澫码头', '北海', '广西', '亲子出游', '夏季', 3, 1, 249.00, '是', 4, '3月去的南澫码头，和朋友出行。地点在北海，公交换乘方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约249元，拍照很出片。景点印象：渔港，岛上最重要的经济中心集散地，全岛最美丽的海景，清澈的海水，蔚蓝的天空。整体感受是还蛮满意，推荐来看看。二刷意愿：是。', '0%', 86);
