INSERT INTO `travel_review` VALUES (8747, 'TR008747', '月亮山', '中卫', '宁夏', '城市漫游', '春季', 2, 5, 1156.00, '是', 5, '2月去的月亮山，和朋友出行。地点在中卫，地铁到达方便，现场人不算多。这次玩了5天，人均花费约1156元，夜景表现很好。景点印象：月亮山是西吉县境内最高的山脉，位于县城西北部西吉、海原两县交界处，白城乡东北。属屈吴山余脉，因其形状近似弧月而得名。主峰海拔2633米，上下山路程约七华里，西麓有宝河沟，故又名七里宝山。\n月亮山东南接六盘山余脉--西峰岭，西北与西华山接…整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '25%', 91);
