INSERT INTO `travel_review` VALUES (8828, 'TR008828', '曹州武术馆', '菏泽', '山东', '拍照旅行', '冬季', 10, 2, 378.00, '是', 5, '10月去的曹州武术馆，和家人出行。地点在菏泽，地铁到达方便，现场人流量适中。这次玩了2天，人均花费约378元，氛围感不错。景点印象：曹州武术馆是国家教委、体委批准认可的一所大型规范化、军事化教武育人的训练基地。本馆指导思想是：“以文保武”，“以武促文”、“以质量求生存”，“以信誉求发展”以法治馆，以德育人，培养“四有”人才，以传授和发扬中华武术为已任。整体感受是超出预期，值得专门打卡。二刷意愿：是。', '0%', 77);
