INSERT INTO `travel_review` VALUES (8844, 'TR008844', '郑维山将军故里', '信阳', '河南', '亲子出游', '秋季', 8, 2, 537.00, '是', 4, '8月去的郑维山将军故里，和朋友出行。地点在信阳，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约537元，拍照很出片。景点印象：郑维山将军1915年出生于河南新县泗店乡，是我党、我军的高级将领，他13岁参加革命，15岁入党，历任八十八师师长、六十三军军长、二十兵团代司令员、北京军区司令员、南京军区司令员。在抗美援朝战争期间，他大胆地在美军视为固若金汤的“密苏里防线…整体感受是还蛮满意，周末来刚好。二刷意愿：是。', '0%', 75);
