INSERT INTO `travel_review` VALUES (8966, 'TR008966', '静湖度假村', '通辽', '内蒙古', '城市漫游', '春季', 1, 4, 978.00, '否', 2, '1月去的静湖度假村，和家人出行。地点在通辽，地铁到达方便，现场人流量适中。这次玩了4天，人均花费约978元，拍照很出片。景点印象：静湖度假村总面积2万亩，是一处融自然环境与人文景观于一体的、适宜休闲娱乐的好地方。这里独特的气候条件，使它夏季可避暑纳凉，游山玩水，让人心旷神怡；冬天可滑冰玩雪，欣赏雕品，令人赏心悦目。目前已建成蒙古大营餐厅、儿童乐园、水上娱乐等…整体感受是没达到预期，建议谨慎前往。二刷意愿：否。', '0%', 50);
