INSERT INTO `travel_review` VALUES (8990, 'TR008990', '朱然陈列馆', '马鞍山', '安徽', '亲子出游', '秋季', 7, 7, 1342.00, '是', 5, '7月去的朱然陈列馆，和家人出行。地点在马鞍山，打车比较省心，现场人不算多。这次玩了7天，人均花费约1342元，氛围感不错。景点印象：朱然陈列馆位于安徽省马鞍山市区南部的雨山乡境内，为三国东吴大将朱然之墓。朱然墓发掘于1984年6月，出土许多珍贵文物，部分漆器填补了三国美术史的空白，也是已发掘东吴墓葬中墓主身份最高、墓葬规模最大的、时间最早的一座大墓，被列为80年代中…整体感受是特别满意，很推荐。二刷意愿：是。', '25%', 77);
