INSERT INTO `travel_review` VALUES (8994, 'TR008994', '北京路步行街', '广州', '广东', '城市漫游', '冬季', 10, 1, 595.00, '是', 5, '10月去的北京路步行街，和朋友出行。地点在广州，打车比较省心，现场人流量适中。这次玩了1天，人均花费约595元，氛围感不错。景点印象：如同去北京一般会去王府井大街逛逛一样，来广州也必去北京路步行街。整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 97);
INSERT INTO `travel_review` VALUES (8995, 'TR008995', '石梁飞瀑', '台州', '浙江', '亲子出游', '夏季', 4, 5, 1162.00, '否', 4, '4月去的石梁飞瀑，和家人出行。地点在台州，打车比较省心，现场高峰时段比较拥挤。这次玩了5天，人均花费约1162元，氛围感不错。景点印象：巨大的天生石梁与飞瀑，搭配出风格独到的美好构图。 瀑布边康有为、米芾题写的摩崖石刻，为石梁增色不少。整体感受是体验挺好，周末来刚好。二刷意愿：否。', '14%', 35);
INSERT INTO `travel_review` VALUES (8996, 'TR008996', '八棵树村基督教活动点', '铁岭', '辽宁', '拍照旅行', '秋季', 7, 4, 714.00, '是', 4, '7月去的八棵树村基督教活动点，情侣出行。地点在铁岭，地铁到达方便，现场人不算多。这次玩了4天，人均花费约714元，历史文化气息浓。景点印象：周边配套比较齐全整体感受是还蛮满意，可以安排半天到一天。二刷意愿：是。', '0%', 34);
INSERT INTO `travel_review` VALUES (8997, 'TR008997', '陕西历史博物馆秦汉馆', '咸阳', '陕西', '周末短途', '秋季', 8, 1, 295.00, '否', 5, '8月去的陕西历史博物馆秦汉馆，情侣出行。地点在咸阳，自驾停车需要提前规划，现场人流量适中。这次玩了1天，人均花费约295元，历史文化气息浓。景点印象：整体环境还算干净整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '0%', 77);
INSERT INTO `travel_review` VALUES (8998, 'TR008998', '梅州千佛塔', '梅州', '广东', '周末短途', '冬季', 10, 5, 1202.00, '否', 3, '10月去的梅州千佛塔，和朋友出行。地点在梅州，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了5天，人均花费约1202元，夜景表现很好。景点印象：千佛宝塔的塔中上下共三干尊佛，构成塔中有塔，塔上有塔，铁佛、玉佛、金佛共容一塔的特色，为梅州一大艺术杰作，是东南胜境之奇观。整体感受是还可以，别抱太高期待。二刷意愿：否。', '35%', 35);
