INSERT INTO `travel_review` VALUES (9000, 'TR009000', '二道白河', '延边', '吉林', '亲子出游', '夏季', 5, 3, 967.00, '是', 5, '5月去的二道白河，情侣出行。地点在延边，地铁到达方便，现场人流量适中。这次玩了3天，人均花费约967元，夜景表现很好。景点印象：长白山下第一镇，风光秀丽旖旎。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '19%', 105);
INSERT INTO `travel_review` VALUES (9001, 'TR009001', '络丝潭', '安阳', '河南', '城市漫游', '夏季', 5, 1, 456.00, '是', 5, '5月去的络丝潭，一个人出行。地点在安阳，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约456元，历史文化气息浓。景点印象：处在青年洞西约1公里处的络丝潭风景区，亦被人称为“天桥断”。“络丝潭”因其潭深达一络蚕丝而得名，又因浊漳河有“九峡十八断”，此处是一较大断崭跌水，上有连接豫、冀两省的峡谷索桥，故又称“天桥断”。这里有漳河名胜“小三峡”，可放艇畅游…整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 58);
