INSERT INTO `travel_review` VALUES (9004, 'TR009004', '肯斯瓦特水库', '北疆', '新疆', '周末短途', '冬季', 9, 3, 1018.00, '否', 5, '9月去的肯斯瓦特水库，一个人出行。地点在北疆，自驾停车需要提前规划，现场人流量适中。这次玩了3天，人均花费约1018元，拍照很出片。景点印象：整体环境还算干净整体感受是超出预期，很推荐。二刷意愿：否。', '0%', 110);
INSERT INTO `travel_review` VALUES (9005, 'TR009005', '月牙湾', '鹤岗', '黑龙江', '城市漫游', '春季', 2, 1, 613.00, '否', 5, '2月去的月牙湾，和朋友出行。地点在鹤岗，公交换乘方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约613元，夜景表现很好。景点印象：整体环境还算干净整体感受是特别满意，很推荐。二刷意愿：否。', '0%', 72);
INSERT INTO `travel_review` VALUES (9006, 'TR009006', '二郎山庄', '四平', '吉林', '城市漫游', '冬季', 9, 3, 701.00, '否', 3, '9月去的二郎山庄，和朋友出行。地点在四平，公交换乘方便，现场人不算多。这次玩了3天，人均花费约701元，夜景表现很好。景点印象：二郎山庄位于吉林省四平市山门镇境内，建在海拔二百九十三米号称长白第一山上，占地面积15万平方米。风景区内自然景观绚丽多彩、景色宜人，内容丰富，是集自然风光，宗教信仰，历史故事，古老传说为一体。每逢农历四月初用八、十八、二十八庙会之日…整体感受是体验一般，别抱太高期待。二刷意愿：否。', '0%', 35);
INSERT INTO `travel_review` VALUES (9007, 'TR009007', '灵光寺', '梅州', '广东', '拍照旅行', '春季', 12, 6, 1374.00, '否', 3, '12月去的灵光寺，和朋友出行。地点在梅州，地铁到达方便，现场人流量适中。这次玩了6天，人均花费约1374元，夜景表现很好。景点印象：该寺原名圣寿寺，是广东省四大名刹之一，相传为唐代懿宗咸通年间高僧潘了拳创建，至今已有一千多年历史。生死树、菠萝顶、顶无叶合称灵光三绝，无笃石螺、片生熟鱼、五色雀合称灵光三奇。整体感受是中规中矩，按需选择。二刷意愿：否。', '35%', 27);
