INSERT INTO `travel_review` VALUES (9016, 'TR009016', '天门山国家森林公园', '张家界', '湖南', '周末短途', '秋季', 7, 4, 768.00, '否', 2, '7月去的天门山国家森林公园，情侣出行。地点在张家界，公交换乘方便，现场高峰时段比较拥挤。这次玩了4天，人均花费约768元，夜景表现很好。景点印象：7500米的观光索道，180度转弯的通天大道，还有贴壁悬空的玻璃栈道。整体感受是没达到预期，可考虑其他景点。二刷意愿：否。', '42%', 25);
INSERT INTO `travel_review` VALUES (9017, 'TR009017', '云山屯', '安顺', '贵州', '周末短途', '春季', 1, 2, 597.00, '否', 2, '1月去的云山屯，情侣出行。地点在安顺，地铁到达方便，现场人流量适中。这次玩了2天，人均花费约597元，拍照很出片。景点印象：作为数百年前留下的历史“化石”，云山屯和它所代表的屯堡文化，已经成了黔中一道靓丽的人文景观，让人们去感受那深隧的过去。整体感受是没达到预期，建议谨慎前往。二刷意愿：否。', '0%', 26);
INSERT INTO `travel_review` VALUES (9018, 'TR009018', '嫩江旅游度假村', '白城', '吉林', '周末短途', '冬季', 10, 4, 902.00, '否', 3, '10月去的嫩江旅游度假村，和朋友出行。地点在白城，打车比较省心，现场人流量适中。这次玩了4天，人均花费约902元，历史文化气息浓。景点印象：嫩江旅游渡假村位于大安市嫩江右岸，距市中心3公里，占地面积5.28公顷，建筑面积达5100平方米，水路、铁路便通，是一处良好的旅游胜地。\n  　这里一年四季分明，景色迷人，碧绿的江水上叶叶白帆轻轻飘荡，豪华的游船长鸣远航，江岸上绿草成荫，草原…整体感受是中规中矩，避开高峰更好。二刷意愿：否。', '0%', 68);
