INSERT INTO `travel_review` VALUES (9093, 'TR009093', '双锁山烈士陵园', '亳州', '安徽', '城市漫游', '秋季', 6, 2, 451.00, '否', 5, '6月去的双锁山烈士陵园，和家人出行。地点在亳州，公交换乘方便，现场人流量适中。这次玩了2天，人均花费约451元，夜景表现很好。景点印象：1983年有小涧区委、区公所修建，用以纪念当地在抗日战争、解放战争时期牺牲的烈士 。蒙城县城西北地区25公里小涧镇东侧 双锁山旁依涡河，南北走向，延绵约十华里。北有狼山，南有黄柏山、尖山，可谓群山环抱。五代时，当地女英雄刘金定以此山立寨护…整体感受是超出预期，以后还会来。二刷意愿：否。', '0%', 63);
