INSERT INTO `travel_review` VALUES (9122, 'TR009122', '钦州坭兴陶艺有限公司', '钦州', '广西', '周末短途', '夏季', 3, 5, 1390.00, '是', 5, '3月去的钦州坭兴陶艺有限公司，一个人出行。地点在钦州，自驾停车需要提前规划，现场游客较多。这次玩了5天，人均花费约1390元，历史文化气息浓。景点印象：广西工业旅游示范点,是一家集坭兴陶工艺品研究、开发、生产、经营于一体的实体。主要通过以公司化运作为载体，拯救和发扬光大“钦州坭兴”这一具有千年历史的文化瑰宝而创建。产品以中、高档次的旅游工艺品、礼品、和高附加值的艺术藏品为主。2000…整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 91);
