INSERT INTO `travel_review` VALUES (9124, 'TR009124', '洱海', '大理', '云南', '亲子出游', '夏季', 5, 3, 1076.00, '是', 5, '5月去的洱海，和家人出行。地点在大理，公交换乘方便，现场游客较多。这次玩了3天，人均花费约1076元，历史文化气息浓。景点印象：郁郁青山脚下的蔚蓝湖泊，大理“风花雪月”四大名景之一。整体感受是超出预期，值得专门打卡。二刷意愿：是。', '56%', 91);
