INSERT INTO `travel_review` VALUES (9126, 'TR009126', '云石山', '赣州', '江西', '拍照旅行', '秋季', 8, 3, 1240.00, '是', 5, '8月去的云石山，和家人出行。地点在赣州，自驾停车需要提前规划，现场人不算多。这次玩了3天，人均花费约1240元，氛围感不错。景点印象：云石山位于瑞金市西南15公里。1934年7月临时中央政府从沙洲坝迁驻此地小山上的云山古寺，山中风景优美。1934年10月，中央机关编为红军中央纵队，从云石山出发开始长征，因而云石山被称为“长征第一山”。整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 82);
INSERT INTO `travel_review` VALUES (9127, 'TR009127', '曲龙银城', '阿里', '西藏', '亲子出游', '冬季', 9, 5, 1308.00, '否', 5, '9月去的曲龙银城，和家人出行。地点在阿里，打车比较省心，现场高峰时段比较拥挤。这次玩了5天，人均花费约1308元，夜景表现很好。景点印象：曲龙银城，又称穹隆银城。象雄国的古都——“大鹏之地”，它比古格王国更大年代更久远，而风化破坏也更为严重。整体感受是特别满意，很推荐。二刷意愿：否。', '1%', 82);
