INSERT INTO `travel_review` VALUES (9152, 'TR009152', '潭湖', '抚州', '江西', '亲子出游', '春季', 2, 2, 735.00, '否', 4, '2月去的潭湖，和朋友出行。地点在抚州，地铁到达方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约735元，历史文化气息浓。景点印象：潭湖风景区位于南丰县城东南部，距县城18公里。湖面面积6175亩，山林面积1.7万亩，山上林木茂盛，覆盖率达98%。景区内自然生态环境优美，气候宜人，空气清新，水质清澈无污染，冬暖夏凉，素有“小庐山”之美称。这里被定为全国生态经济示范点和省水…整体感受是还蛮满意，可以安排半天到一天。二刷意愿：否。', '33%', 47);
