INSERT INTO `travel_review` VALUES (9158, 'TR009158', '拉乌山', '昌都', '西藏', '深度游', '夏季', 3, 5, 1470.00, '否', 3, '3月去的拉乌山，一个人出行。地点在昌都，打车比较省心，现场人流量适中。这次玩了5天，人均花费约1470元，夜景表现很好。景点印象：拉乌山是川藏公路318国道西藏芒康境内的一个平缓的山口,山顶有一个比较壮观的经幡阵，整整占了一个山头。 拉乌山口海拔4338米，但站在垭口上如果有天眼的话就可俯看金沙江和澜沧江了。整体感受是中规中矩，按需选择。二刷意愿：否。', '16%', 46);
