INSERT INTO `travel_review` VALUES (9162, 'TR009162', '金莲洞风景区', '陇南', '甘肃', '文化打卡', '秋季', 6, 1, 80.00, '否', 5, '6月去的金莲洞风景区，一个人出行。地点在陇南，公交换乘方便，现场游客较多。这次玩了1天，人均花费约80元，拍照很出片。景点印象：金莲洞位于成县店村乡新村仙洞湾山腰，一名华阳洞，洞阔400余米，入则渐小，约500米深处仍有一小洞，人不能入，深不可测。洞内密布钟乳石，多呈莲花状，故名。\n据载，元成宗元贞二年（1296年）至大德六年（1302年）间，道士刘道通、罗道隐者，在此…整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '0%', 52);
