INSERT INTO `travel_review` VALUES (9197, 'TR009197', '桂坑', '汕尾', '广东', '拍照旅行', '冬季', 9, 4, 279.00, '否', 5, '9月去的桂坑，和家人出行。地点在汕尾，打车比较省心，现场高峰时段比较拥挤。这次玩了4天，人均花费约279元，夜景表现很好。景点印象：桂坑景区以山地景观为主，分布在龙潭水库（水库容量1.08亿立方米，集水面积11平方公里）周围，可开发土地面积9.5平方公里。在该景区内，有人字峰山，该山主峰海拔高740米，山峰上的“打鼓潭”泉水自上而泻，川流不息，水质清甜可口，水量充沛，经科…整体感受是超出预期，以后还会来。二刷意愿：否。', '0%', 85);
