INSERT INTO `travel_review` VALUES (9200, 'TR009200', '毛墓遗址', '许昌', '河南', '深度游', '夏季', 4, 1, 617.00, '是', 5, '4月去的毛墓遗址，一个人出行。地点在许昌，公交换乘方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约617元，夜景表现很好。景点印象：位于许昌市东16公里的五女店镇毛王村金龟岗上，又称毛承相墓。毛 ，字孝先，原籍陈留平丘 （今河南封丘县）人，兴平二年（195年）投奔曹操，辟为治中从事，后把家室亦迁于京郊（今五女店毛王村）。毛是曹操的重臣，先后任治中从事、墓府功曹、丞相…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 81);
INSERT INTO `travel_review` VALUES (9201, 'TR009201', '上海海洋水族馆', '上海', '上海', '亲子出游', '春季', 1, 2, 798.00, '是', 5, '1月去的上海海洋水族馆，情侣出行。地点在上海，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约798元，拍照很出片。景点印象：观赏各种海洋生物，漫步海底隧道，感受五彩缤纷的海底世界。整体感受是超出预期，以后还会来。二刷意愿：是。', '3%', 78);
