INSERT INTO `travel_review` VALUES (9215, 'TR009215', '卓果特沁古城', '巴音郭楞', '新疆', '周末短途', '秋季', 7, 1, 881.00, '否', 5, '7月去的卓果特沁古城，和家人出行。地点在巴音郭楞，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约881元，历史文化气息浓。景点印象：位于轮台县城东南约20公里处，东汉至唐时代遗址，相传城为三重，城为土筑，略作圆形，周约1200米，城垣已颓，仅余高6～7米的土岗。中有一环形小湖，湖中心有一高台似为古代建筑遗址，南面有二小土丘，左边者似为仓库，右边者似为官署遗址。城东南隅…整体感受是特别满意，以后还会来。二刷意愿：否。', '0%', 33);
