INSERT INTO `travel_review` VALUES (9231, 'TR009231', '孔雀山', '莱芜', '山东', '亲子出游', '春季', 2, 1, 722.00, '否', 3, '2月去的孔雀山，和家人出行。地点在莱芜，公交换乘方便，现场游客较多。这次玩了1天，人均花费约722元，历史文化气息浓。景点印象：孔雀山景区北邻齐长城，西靠华山森林公园，南接悬羊吊鼓山，东傍雪野湖、马鞍山。三面环山，一面傍水。该旅游区横距4.3公里，纵距5.2公里，总面积22.36平方公里。整个地形东缓西陡，海拔最高点800米，最低点306米。风景区内山峻石奇，主要景观有大…整体感受是中规中矩，避开高峰更好。二刷意愿：否。', '0%', 66);
