INSERT INTO `travel_review` VALUES (9250, 'TR009250', '梅山水库', '六安', '安徽', '城市漫游', '秋季', 6, 2, 995.00, '是', 5, '6月去的梅山水库，和朋友出行。地点在六安，打车比较省心，现场高峰时段比较拥挤。这次玩了2天，人均花费约995元，拍照很出片。景点印象：安徽梅山水库风景区位于鄂、豫、皖三省交界处的大别山腹地，坐落于有将军县之称的安徽省金寨县县城南端。50年代建成的时称世界第一高的钢筋混凝土连拱坝巍然屹立于景区内。景区丰富的“绿色”旅游资源同县域“红色”革命传统紧密相联，形成了自己独…整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '19%', 66);
