INSERT INTO `travel_review` VALUES (9259, 'TR009259', '青松山狩猎场', '齐齐哈尔', '黑龙江', '亲子出游', '秋季', 6, 3, 1069.00, '否', 3, '6月去的青松山狩猎场，情侣出行。地点在齐齐哈尔，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了3天，人均花费约1069元，拍照很出片。景点印象：青松山对外开放狩猎场是我国对外开放的第一座全封闭型 山鸡狩猎场。位于齐齐哈尔市北郊，距城区五十公里。座落在 茂密的森林之中。猎区内既有水源，又有灌木丛和浆果林，生 态环境优美，为山鸡的生息繁衍提供了优越的自然条件。\n　　猎场建有现代化…整体感受是中规中矩，按需选择。二刷意愿：否。', '1%', 22);
