INSERT INTO `travel_review` VALUES (9320, 'TR009320', '双牌水库', '永州', '湖南', '拍照旅行', '春季', 1, 4, 1125.00, '否', 4, '1月去的双牌水库，和朋友出行。地点在永州，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了4天，人均花费约1125元，拍照很出片。景点印象：双牌水库景区位于双牌周冲口的湘江主支流潇水上，距永州市35km，始建于1958年，1962年完工。工程由大坝、溢洪道、引水系统、电站厂房、通航建筑等组成。大坝为混凝土双支墩大头坝，坝顶高程176.5m，最大坝高58.8m，坝顶长311m，宽6m。水库总容量6.9…整体感受是整体不错，可以安排半天到一天。二刷意愿：否。', '0%', 43);
