INSERT INTO `travel_review` VALUES (9322, 'TR009322', '石猴山滑雪场', '伊春', '黑龙江', '拍照旅行', '夏季', 4, 2, 964.00, '否', 5, '4月去的石猴山滑雪场，和家人出行。地点在伊春，地铁到达方便，现场人流量适中。这次玩了2天，人均花费约964元，夜景表现很好。景点印象：朗乡镇座落在伊春小兴安岭南麓苍翠欲滴,烟浩淼淼的林海中,这里三山半落,绿水中分,恰似格林童话中的意境. 石猴山滑雪场位于朗乡镇南3.5公里处石猴山脚下,它交通便利,离林中园鹿场28公里,离头道沟漂游69公里,古城依兰85公里,已经形成了旅游一条线格局…整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '0%', 105);
