INSERT INTO `travel_review` VALUES (9400, 'TR009400', '紫溪山', '楚雄州', '云南', '深度游', '春季', 2, 2, 235.00, '是', 5, '2月去的紫溪山，和朋友出行。地点在楚雄州，打车比较省心，现场高峰时段比较拥挤。这次玩了2天，人均花费约235元，氛围感不错。景点印象：从楚雄州首府鹿城驱车沿滇缅公路西去近15公里，再顺着新修的沥青路，蜿蜒而上10多公里，便进入紫溪山森林公园。只见在这一片雄伟的山间，一望无际的松林郁郁葱葱，掩映在松林之间的马樱花，一到冬春之交，更含苞怒放，鲜艳艳、红彤彤地映照着群山。…整体感受是超出预期，很推荐。二刷意愿：是。', '2%', 71);
