INSERT INTO `travel_review` VALUES (9439, 'TR009439', '棋盘山', '沈阳', '辽宁', '深度游', '夏季', 4, 1, 850.00, '是', 5, '4月去的棋盘山，情侣出行。地点在沈阳，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约850元，拍照很出片。景点印象：山峦与湖水相映，夏天可以饱览荷塘风光，秋天枫叶绽红，是摄影的好时机。整体感受是挺惊喜，很推荐。二刷意愿：是。', '4%', 102);
