INSERT INTO `travel_review` VALUES (9569, 'TR009569', '景德镇民窑博物馆', '景德镇', '江西', '拍照旅行', '冬季', 11, 6, 1686.00, '否', 2, '11月去的景德镇民窑博物馆，和朋友出行。地点在景德镇，打车比较省心，现场人流量适中。这次玩了6天，人均花费约1686元，夜景表现很好。景点印象：丰富的文化遗存反映了七百年间陶瓷工艺史上重大变革和集中国古代制瓷历史之大成的过程。整体感受是略失望，建议谨慎前往。二刷意愿：否。', '5%', 33);
