INSERT INTO `travel_review` VALUES (9583, 'TR009583', '二郎山庄', '四平', '吉林', '文化打卡', '秋季', 8, 6, 1423.00, '否', 2, '8月去的二郎山庄，一个人出行。地点在四平，地铁到达方便，现场高峰时段比较拥挤。这次玩了6天，人均花费约1423元，氛围感不错。景点印象：二郎山庄位于吉林省四平市山门镇境内，建在海拔二百九十三米号称长白第一山上，占地面积15万平方米。风景区内自然景观绚丽多彩、景色宜人，内容丰富，是集自然风光，宗教信仰，历史故事，古老传说为一体。每逢农历四月初用八、十八、二十八庙会之日…整体感受是没达到预期，不建议高峰来。二刷意愿：否。', '0%', 78);
