INSERT INTO `travel_review` VALUES (9598, 'TR009598', '大连海昌东方水城', '大连', '辽宁', '深度游', '春季', 1, 3, 890.00, '是', 5, '1月去的大连海昌东方水城，和家人出行。地点在大连，打车比较省心，现场游客较多。这次玩了3天，人均花费约890元，氛围感不错。景点印象：漫步于欧式建筑与水城风光中，感受威尼斯水城般的异域风情。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 105);
