INSERT INTO `travel_review` VALUES (9602, 'TR009602', '达斡尔哈拉新村', '齐齐哈尔', '黑龙江', '周末短途', '冬季', 10, 3, 942.00, '是', 5, '10月去的达斡尔哈拉新村，和朋友出行。地点在齐齐哈尔，自驾停车需要提前规划，现场人流量适中。这次玩了3天，人均花费约942元，氛围感不错。景点印象：原哈拉村毁于1998年嫩江特大洪灾。经全国政协和中华慈善总会拨款救助，在省市区党委、政府的关怀下，于翌年重新建成现代化的哈拉新村。\n        哈拉新村地处齐查、齐林公路交汇处，东濒嫩江，西南与明月岛隔江相望。全村有居民300户，其中达斡尔族…整体感受是超出预期，值得专门打卡。二刷意愿：是。', '0%', 54);
