INSERT INTO `travel_review` VALUES (9605, 'TR009605', '药泉山钟灵禅寺', '黑河', '黑龙江', '深度游', '秋季', 8, 2, 724.00, '是', 5, '8月去的药泉山钟灵禅寺，一个人出行。地点在黑河，地铁到达方便，现场游客较多。这次玩了2天，人均花费约724元，历史文化气息浓。景点印象：药泉山钟灵禅寺坐落在五大连池风景名胜区老期火山药泉山的火山口中平旷之处，距火口垣尚有十余米的高程，它与火山堰塞湖和新老期火山相映生辉，构成了独特的人文景观，在火山口里建寺庙在世界上是唯一的，所以钟灵禅寺又号称火口第一寺。\n登药泉山…整体感受是超出预期，以后还会来。二刷意愿：是。', '2%', 69);
