INSERT INTO `travel_review` VALUES (9630, 'TR009630', '善人桥', '沧州', '河北', '周末短途', '春季', 1, 1, 890.00, '是', 5, '1月去的善人桥，和家人出行。地点在沧州，打车比较省心，现场游客较多。这次玩了1天，人均花费约890元，夜景表现很好。景点印象：沧州单桥距沧州献县城南6公里，横跨在滹沱河故道上，当地人称单桥，又名善人桥。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 73);
INSERT INTO `travel_review` VALUES (9631, 'TR009631', '孔庙', '济宁', '山东', '拍照旅行', '春季', 12, 2, 980.00, '是', 4, '12月去的孔庙，和家人出行。地点在济宁，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约980元，历史文化气息浓。景点印象：游走于规模庞大的孔庙建筑群，探访历朝古迹与祭孔文化。整体感受是还蛮满意，周末来刚好。二刷意愿：是。', '69%', 34);
