INSERT INTO `travel_review` VALUES (9644, 'TR009644', '梅山水库', '六安', '安徽', '亲子出游', '夏季', 5, 3, 577.00, '否', 3, '5月去的梅山水库，和家人出行。地点在六安，公交换乘方便，现场游客较多。这次玩了3天，人均花费约577元，氛围感不错。景点印象：安徽梅山水库风景区位于鄂、豫、皖三省交界处的大别山腹地，坐落于有将军县之称的安徽省金寨县县城南端。50年代建成的时称世界第一高的钢筋混凝土连拱坝巍然屹立于景区内。景区丰富的“绿色”旅游资源同县域“红色”革命传统紧密相联，形成了自己独…整体感受是中规中矩，按需选择。二刷意愿：否。', '19%', 58);
