INSERT INTO `travel_review` VALUES (9678, 'TR009678', '念青唐古拉山', '那曲', '西藏', '文化打卡', '冬季', 11, 1, 123.00, '否', 5, '11月去的念青唐古拉山，一个人出行。地点在那曲，自驾停车需要提前规划，现场人不算多。这次玩了1天，人均花费约123元，氛围感不错。景点印象：念青唐古拉山位于中国西藏自治区，属断块山。西接冈底斯山脉，东南延伸与横断山脉伯舒拉岭相接，中部略为向北凸出，同时将西藏划分成藏北.藏南.臧东南三大区域。长700千米，终年白雪皑皑，云雾缭绕。整体感受是特别满意，值得专门打卡。二刷意愿：否。', '10%', 76);
