INSERT INTO `travel_review` VALUES (9688, 'TR009688', '前南峪', '邢台', '河北', '亲子出游', '夏季', 3, 1, 231.00, '否', 5, '3月去的前南峪，情侣出行。地点在邢台，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约231元，拍照很出片。景点印象：前南峪生态观光旅游区位于邢台市西60公里处。规划面积38平方公里，分为七大景区，内有自然景观和人文景观80多处。全国爱国主义教育示范基地――抗大陈列馆、纪念碑和大型浮雕像矗立在景区入口处：笔架山、练胆峡、斧劈峰、七星阁、文昌阁、泽后亭等…整体感受是超出预期，很推荐。二刷意愿：否。', '0%', 40);
