INSERT INTO `travel_review` VALUES (9713, 'TR009713', '乌鲁瓦提水利枢纽工程', '和田', '新疆', '城市漫游', '夏季', 5, 1, 552.00, '否', 5, '5月去的乌鲁瓦提水利枢纽工程，情侣出行。地点在和田，公交换乘方便，现场人不算多。这次玩了1天，人均花费约552元，拍照很出片。景点印象：乌鲁瓦提水利枢纽工程位于昆仑山南麓的喀拉喀什河上游山口处、和田县浪如乡境内。距和田市71公里，有泊油路和砂石路可达。属于山谷拦河水库，具有灌溉、防洪、发电、养鱼、生态保护及旅游等多，\n该枢纽工程由主坝及副坝、右岸开启式岸边溢洪道、泄…整体感受是挺惊喜，很推荐。二刷意愿：否。', '0%', 93);
