INSERT INTO `travel_review` VALUES (9743, 'TR009743', '朝阳鸟化石国家地质公园', '朝阳', '辽宁', '文化打卡', '冬季', 9, 2, 765.00, '否', 3, '9月去的朝阳鸟化石国家地质公园，和朋友出行。地点在朝阳，打车比较省心，现场人不算多。这次玩了2天，人均花费约765元，历史文化气息浓。景点印象：陈列着迄今世界上最早的鸟类和开花植物的化石标本。 观赏当地出土的恐龙、爬行类、昆虫类等多种化石标本。 行走在化石发掘现场，观察中生代化石的剖面。整体感受是中规中矩，别抱太高期待。二刷意愿：否。', '25%', 90);
