INSERT INTO `travel_review` VALUES (9746, 'TR009746', '香加', '海西', '青海', '亲子出游', '冬季', 10, 2, 821.00, '是', 5, '10月去的香加，一个人出行。地点在海西，打车比较省心，现场人流量适中。这次玩了2天，人均花费约821元，夜景表现很好。景点印象：在都兰垭口西64公里的地方，有一座小镇叫香日德。从这里弯向南就可进入布尔汗布达山腹地，也是进入巴隆野生动物保护区的一条通道。香加河谷地带的南面就是布尔汗布达山脉，有常年不化的雪峰，发源于布尔汗布达山脉和果洛州的冬给措那湖的托索河流经…整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '0%', 64);
