INSERT INTO `travel_review` VALUES (9764, 'TR009764', '白坡山', '攀枝花', '四川', '拍照旅行', '秋季', 7, 2, 814.00, '否', 5, '7月去的白坡山，和家人出行。地点在攀枝花，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了2天，人均花费约814元，氛围感不错。景点印象：米易普威的白坡山自然保护区，海拨1200-3400米，土壤气候、植被呈垂直分布。原始森林以云南松为主，根本问题无 数藤蔓纽结缠绕，古木森森，杜鹃争春，还有珍禽奇兽出没。\n攀枝花气候温暖，终年无雪，但普威是其中的例外，由于海拨较高，加之境内原…整体感受是挺惊喜，以后还会来。二刷意愿：否。', '3%', 122);
