INSERT INTO `travel_review` VALUES (9805, 'TR009805', '澜沧江风光', '西双版纳', '云南', '城市漫游', '冬季', 10, 4, 1043.00, '否', 3, '10月去的澜沧江风光，情侣出行。地点在西双版纳，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了4天，人均花费约1043元，拍照很出片。景点印象：乘船欣赏澜沧江风光，观看当地特色舞蹈。整体感受是还可以，避开高峰更好。二刷意愿：否。', '21%', 36);
INSERT INTO `travel_review` VALUES (9806, 'TR009806', '巧家药山', '昭通', '云南', '城市漫游', '冬季', 10, 1, 739.00, '是', 5, '10月去的巧家药山，和朋友出行。地点在昭通，公交换乘方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约739元，氛围感不错。景点印象：药山位于巧家县境内。金沙江和牛栏江环山而过。药山山体面积220平方公里，主峰金顶山海拔4042米，雄踞于昭通群峰之上。\n由于受北―东向构成控制发育成型，药山走向近于北―东。西坡地势陡峭，悬崖绝壁从两江汇流的谷地中凌宵而起，柱地擎天，高不可…整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '0%', 90);
