INSERT INTO `travel_review` VALUES (9810, 'TR009810', '紫金矿业', '龙岩', '福建', '亲子出游', '夏季', 4, 3, 762.00, '是', 5, '4月去的紫金矿业，和家人出行。地点在龙岩，自驾停车需要提前规划，现场游客较多。这次玩了3天，人均花费约762元，历史文化气息浓。景点印象：紫金矿业集团由上杭县矿产公司发展而来，是上杭人民的骄傲和经济发展的象征，内有资金地质矿产博物馆和林丹羽毛球馆，是到了上杭县城必去的地方。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 57);
