INSERT INTO `travel_review` VALUES (9814, 'TR009814', '海河', '天津', '天津', '拍照旅行', '夏季', 5, 3, 784.00, '是', 5, '5月去的海河，一个人出行。地点在天津，地铁到达方便，现场人不算多。这次玩了3天，人均花费约784元，拍照很出片。景点印象：海河两岸汇聚了天津最精华的街景，夜晚景色绚烂迷人。整体感受是特别满意，很推荐。二刷意愿：是。', '30%', 96);
INSERT INTO `travel_review` VALUES (9815, 'TR009815', '沱沱河气象站', '那曲', '西藏', '文化打卡', '秋季', 8, 3, 930.00, '是', 4, '8月去的沱沱河气象站，情侣出行。地点在那曲，打车比较省心，现场人不算多。这次玩了3天，人均花费约930元，氛围感不错。景点印象：长江源头唐古拉山麓，屹立着一座设备先进而齐全的气象观测基本站----沱沱河气象站，坐落在海拔4700多米处，是世界上海拔最高的气象观测基本站。总面积约250平方公里，平均海拔4，000米以上的青藏高原，有“世界屋脊”和“地球的第三极”之称，它对…整体感受是还蛮满意，可以安排半天到一天。二刷意愿：是。', '1%', 71);
