INSERT INTO `travel_review` VALUES (9841, 'TR009841', '繁昌窑遗址', '芜湖', '安徽', '亲子出游', '秋季', 6, 1, 80.00, '否', 4, '6月去的繁昌窑遗址，一个人出行。地点在芜湖，打车比较省心，现场人流量适中。这次玩了1天，人均花费约80元，拍照很出片。景点印象：繁昌窑遗址分布在安徽省繁昌县城南郊和西郊的山地丘陵地带，为宋代窑址。\n已发现窑址多处，其中以位于繁昌县南郊的柯家村窑址面积最大，是繁昌窑的主要生产区域，具有代表性。柯家村窑主要烧造青白釉瓷器，其次烧白釉瓷器。种类多为壶、碗、碟、杯…整体感受是整体不错，推荐来看看。二刷意愿：否。', '0%', 49);
