INSERT INTO `travel_review` VALUES (9861, 'TR009861', '马湖风景名胜区', '凉山', '四川', '深度游', '春季', 1, 2, 472.00, '是', 4, '1月去的马湖风景名胜区，情侣出行。地点在凉山，打车比较省心，现场人流量适中。这次玩了2天，人均花费约472元，历史文化气息浓。景点印象：马湖风景名胜区位于凉山彝族自治州雷波县境内，景区总面积128平方公里。由秀丽的马湖、金沙江峡谷、原始密林等部分组成，是小凉山深处一颗耀眼的风景“明珠”。1993年被省人民政府批准为省级风景名胜区。\n马湖属高原大型天然深水湖泊，水域面积7.3…整体感受是还蛮满意，推荐来看看。二刷意愿：是。', '1%', 98);
