INSERT INTO `travel_review` VALUES (9864, 'TR009864', '神树', '阿拉善盟', '内蒙古', '文化打卡', '夏季', 4, 1, 653.00, '否', 2, '4月去的神树，和家人出行。地点在阿拉善盟，打车比较省心，现场人流量适中。这次玩了1天，人均花费约653元，夜景表现很好。景点印象：神树据说是我国境内最古老、最大、最粗的一棵胡杨树，树龄800多年。整体感受是体验偏一般，建议谨慎前往。二刷意愿：否。', '5%', 41);
