INSERT INTO `travel_review` VALUES (9868, 'TR009868', '朱载育墓', '焦作', '河南', '深度游', '冬季', 9, 3, 679.00, '否', 5, '9月去的朱载育墓，情侣出行。地点在焦作，公交换乘方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约679元，历史文化气息浓。景点印象：朱载育墓位于沁阳县东北15公里处的山王庄乡张坡村东九峰山下。北依太行，南瞰怀川，墓周流水潺潺，环境优雅。原有明代书法家王铎书写的神道碑，抗日战争时期被日军炸毁。墓上原有高大封土堆，墓面有神道，神道两侧有石像生等，\"文化大革命\"开始后，…整体感受是超出预期，以后还会来。二刷意愿：否。', '0%', 71);
