INSERT INTO `travel_review` VALUES (9893, 'TR009893', '田阳布洛陀芒果风情园', '百色', '广西', '亲子出游', '冬季', 10, 2, 557.00, '是', 5, '10月去的田阳布洛陀芒果风情园，和家人出行。地点在百色，公交换乘方便，现场人不算多。这次玩了2天，人均花费约557元，夜景表现很好。景点印象：田阳县布洛陀芒果风情园是2003年推出的农业旅游项目。景区位于该县东部，距县城7公里。景区规划总面积704公顷，现已开发150多公顷。园内种有芒果、龙眼、荔枝、大青枣等水果品种，其中芒果品种38个，芒果特色品种有田阳香芒、红金煌芒、凯特芒等。…整体感受是特别满意，很推荐。二刷意愿：是。', '1%', 88);
