INSERT INTO `travel_review` VALUES (9896, 'TR009896', '紫荆山公园', '平凉', '甘肃', '亲子出游', '秋季', 7, 4, 1095.00, '否', 2, '7月去的紫荆山公园，和朋友出行。地点在平凉，地铁到达方便，现场人流量适中。这次玩了4天，人均花费约1095元，氛围感不错。景点印象：紫荆山，平地突兀于庄浪县城之中，因山阴遍植紫荆树而得名。历为山城形胜，1986年被县政府辟为公园。紫荆山游览区面积1.5万平方米，集自然景观与人文景观于一体，山势玲珑剔透，雄浑壮观，环境幽雅，令人陶醉。“洛河横烟”、“紫荆香霭”等景观及…整体感受是体验偏一般，不建议高峰来。二刷意愿：否。', '0%', 75);
