INSERT INTO `travel_review` VALUES (9916, 'TR009916', '花乡农家乐旅游区', '益阳', '湖南', '深度游', '秋季', 6, 5, 1653.00, '否', 5, '6月去的花乡农家乐旅游区，一个人出行。地点在益阳，打车比较省心，现场人流量适中。这次玩了5天，人均花费约1653元，历史文化气息浓。景点印象：益阳花乡农家乐旅游区位于赫山区黄泥湖乡仙蜂岭村，距益阳市中心城区6.5公里，被资水和志溪河环抱。\n仙蜂岭是闻名遐尔的花会之乡。早在上个世纪九十年代，仙蜂岭人集前辈的智慧和经验，进行花卉苗木的生产栽培。\n至今发展到300多户花农，1600多亩花…整体感受是挺惊喜，很推荐。二刷意愿：否。', '0%', 65);
