INSERT INTO `travel_review` VALUES (9938, 'TR009938', '华八井', '东营', '山东', '拍照旅行', '秋季', 8, 2, 746.00, '否', 5, '8月去的华八井，情侣出行。地点在东营，地铁到达方便，现场人不算多。这次玩了2天，人均花费约746元，氛围感不错。景点印象：华八井是在燕山以南，太行山以东 ，大别山以北，渤海湾以西40万平方公里的华北平原内进行石油资源普查的第八口探井。位于东营市东营区东营村。1961年4月16日，该井首次用9毫米油嘴求产，获日产8.1吨工业油流，成为当时东部渤海湾地区第一口见原油的…整体感受是特别满意，以后还会来。二刷意愿：否。', '0%', 95);
