INSERT INTO `travel_review` VALUES (9960, 'TR009960', '青海久治年保玉则国家地质公园', '果洛', '青海', '深度游', '冬季', 9, 1, 213.00, '是', 5, '9月去的青海久治年保玉则国家地质公园，情侣出行。地点在果洛，打车比较省心，现场游客较多。这次玩了1天，人均花费约213元，拍照很出片。景点印象：雪山、花海、湖泊景色绝美，是摄影家们热爱的天堂。 神山周围面积广大景色多样，是徒步爱好者心中的优质路线。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '74%', 76);
INSERT INTO `travel_review` VALUES (9961, 'TR009961', '城市绿谷景区', '南通', '江苏', '周末短途', '冬季', 10, 2, 1413.00, '是', 4, '10月去的城市绿谷景区，一个人出行。地点在南通，打车比较省心，现场高峰时段比较拥挤。这次玩了2天，人均花费约1413元，历史文化气息浓。景点印象：苏北最大的双式私家园林，植被丰富、水流清秀，还有一系列游乐项目。整体感受是体验挺好，周末来刚好。二刷意愿：是。', '0%', 68);
INSERT INTO `travel_review` VALUES (9962, 'TR009962', '榆树崴子', '齐齐哈尔', '黑龙江', '文化打卡', '春季', 2, 6, 1648.00, '否', 4, '2月去的榆树崴子，和朋友出行。地点在齐齐哈尔，打车比较省心，现场人流量适中。这次玩了6天，人均花费约1648元，氛围感不错。景点印象：位于齐齐哈尔市昂昂溪区榆树崴子，始建于1993年，在市中心城区西南15公里处，总面积1.6万亩，以得天独厚的江岸自然风光而著称。游览区西北是浩荡的嫩江，沿江沙丘连绵起伏，东南部是万亩稻田。区内由数百株百年以上树龄的榆树组成的榆树林，林内花…整体感受是还蛮满意，可以安排半天到一天。二刷意愿：否。', '0%', 104);
