INSERT INTO `travel_review` VALUES (9964, 'TR009964', '嵩山风景名胜区', '郑州', '河南', '城市漫游', '夏季', 4, 2, 667.00, '是', 5, '4月去的嵩山风景名胜区，和朋友出行。地点在郑州，地铁到达方便，现场人不算多。这次玩了2天，人均花费约667元，氛围感不错。景点印象：欣赏壮美的自然风光和奇特的地质奇观，感受丰富灿烂的佛教、道教和儒学文化。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '12%', 77);
INSERT INTO `travel_review` VALUES (9965, 'TR009965', '星湖旅游景区', '肇庆', '广东', '城市漫游', '冬季', 11, 4, 1138.00, '是', 5, '11月去的星湖旅游景区，和朋友出行。地点在肇庆，打车比较省心，现场高峰时段比较拥挤。这次玩了4天，人均花费约1138元，氛围感不错。景点印象：湖面划分为五个湖：东湖、青莲湖、中心湖、波海湖、里湖，堤上杨柳、凤凰木成行。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '20%', 46);
