INSERT INTO `travel_review` VALUES (9968, 'TR009968', '千坝草原', '陇南', '甘肃', '拍照旅行', '夏季', 4, 1, 663.00, '否', 5, '4月去的千坝草原，一个人出行。地点在陇南，自驾停车需要提前规划，现场游客较多。这次玩了1天，人均花费约663元，氛围感不错。景点印象：千坝草原位于武都东南部，距离城30公里，海拔在2100-3090米之间，总面积10.075万亩；东至分水岭滴水崖，西至北沙柳梁，南至千沟坝，北至前梁的边梁，地形为东西狭长22公里，南北距离17公里。境内以八坝、八坑、三坪、六洞、二池而负盛名。\n境内共…整体感受是特别满意，很推荐。二刷意愿：否。', '3%', 90);
