INSERT INTO `travel_review` VALUES (9972, 'TR009972', '陆九渊之墓', '抚州', '江西', '周末短途', '春季', 2, 1, 200.00, '是', 5, '2月去的陆九渊之墓，一个人出行。地点在抚州，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约200元，氛围感不错。景点印象：座落于金溪县陆坊乡青田村东山上，1957年被列为江西省省级保护文物。陆九渊，字子静，号象山，陆坊乡青田人，是南宋时与朱熹双峰对峙的理学大师、哲学家、教育家，在历史上有深远影响。其理学又称“心学”，提出“心即理”、“宇宙便是吾心，吾心便…整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 61);
