INSERT INTO `travel_review` VALUES (10011, 'TR010011', '空山洞', '荆门', '湖北', '拍照旅行', '夏季', 3, 1, 576.00, '是', 5, '3月去的空山洞，和朋友出行。地点在荆门，公交换乘方便，现场游客较多。这次玩了1天，人均花费约576元，拍照很出片。景点印象：湖北荆门空山洞被誉为华中第一溶洞，洞内景观惟妙惟肖，光怪陆离，造型有神，互争奇观，构成了千姿百态的自然景观。最神奇的是洞内一组能敲击发音并且符合音律的钟乳石，被地质界和音乐界称为绝无仅有的世间一绝——天然“石编钟”。整体感受是特别满意，很推荐。二刷意愿：是。', '6%', 82);
INSERT INTO `travel_review` VALUES (10012, 'TR010012', '丰宁坝上草原', '承德', '河北', '周末短途', '夏季', 5, 7, 1897.00, '否', 3, '5月去的丰宁坝上草原，一个人出行。地点在承德，公交换乘方便，现场人不算多。这次玩了7天，人均花费约1897元，氛围感不错。景点印象：紧邻北京市区，适合夏天游玩的避暑胜地。整体感受是中规中矩，按需选择。二刷意愿：否。', '18%', 35);
INSERT INTO `travel_review` VALUES (10013, 'TR010013', '董氏砖雕墓', '临汾', '山西', '文化打卡', '夏季', 3, 2, 595.00, '否', 4, '3月去的董氏砖雕墓，和朋友出行。地点在临汾，打车比较省心，现场游客较多。这次玩了2天，人均花费约595元，氛围感不错。景点印象：在山西侯马市西北郊基建工地发现，1959年和1969年，分别迁于山西考古研究所候马工作站院内。墓主人一名董海，一名董明，先后于金明昌七年（1196年）和大安二年（1210年）埋葬。均为仿木构砖雕墓，平面皆方形。董海墓为前后两室，系我国北方地区传统…整体感受是整体不错，可以安排半天到一天。二刷意愿：否。', '0%', 57);
