INSERT INTO `travel_review` VALUES (10028, 'TR010028', '五四广场', '青岛', '山东', '亲子出游', '春季', 1, 3, 1321.00, '否', 3, '1月去的五四广场，情侣出行。地点在青岛，打车比较省心，现场人不算多。这次玩了3天，人均花费约1321元，拍照很出片。景点印象：为纪念“五四运动”而建，有青岛标志性雕塑“五月的风”。整体感受是中规中矩，按需选择。二刷意愿：否。', '61%', 64);
INSERT INTO `travel_review` VALUES (10029, 'TR010029', '袁家村', '咸阳', '陕西', '周末短途', '冬季', 10, 1, 452.00, '否', 3, '10月去的袁家村，和朋友出行。地点在咸阳，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约452元，拍照很出片。景点印象：中原腹地的“关中印象体验地”，可欣赏颇具关中风味的明清式建筑。整体感受是中规中矩，避开高峰更好。二刷意愿：否。', '5%', 62);
INSERT INTO `travel_review` VALUES (10030, 'TR010030', '中山詹园', '中山', '广东', '拍照旅行', '冬季', 9, 2, 766.00, '是', 4, '9月去的中山詹园，一个人出行。地点在中山，打车比较省心，现场高峰时段比较拥挤。这次玩了2天，人均花费约766元，历史文化气息浓。景点印象：岭南地区最大的古典私家庭院，有着南方庭院典型的幽静，是个漫步摄影的好去处。整体感受是体验挺好，可以安排半天到一天。二刷意愿：是。', '9%', 34);
INSERT INTO `travel_review` VALUES (10031, 'TR010031', '梁野山', '龙岩', '福建', '亲子出游', '夏季', 5, 2, 1108.00, '否', 2, '5月去的梁野山，和家人出行。地点在龙岩，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约1108元，拍照很出片。景点印象：奇山异石、千峰竞秀的梁野山，是进行森林探险、生态旅游的首选之地。整体感受是略失望，建议谨慎前往。二刷意愿：否。', '0%', 37);
INSERT INTO `travel_review` VALUES (10032, 'TR010032', '黑马井汉墓群', '红河', '云南', '深度游', '夏季', 5, 4, 796.00, '是', 5, '5月去的黑马井汉墓群，情侣出行。地点在红河，公交换乘方便，现场高峰时段比较拥挤。这次玩了4天，人均花费约796元，历史文化气息浓。景点印象：在个旧市城区南40余公里卡房镇黑马井村西一平缓的山坡上，面积近万平方米。1989－1995年间，曾先后三次进行抢救性发掘，发掘面积1500平方米，清理古墓十五座。出土了青铜器、玉石器、漆器、铁器和陶器（原始釉陶罐）、五铢钱等300多件器物。有一颗…整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 72);
