INSERT INTO `travel_review` VALUES (10046, 'TR010046', '罗通山', '通化', '吉林', '城市漫游', '春季', 12, 2, 1093.00, '否', 2, '12月去的罗通山，情侣出行。地点在通化，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约1093元，夜景表现很好。景点印象：罗通山原名骆驼山,位于柳河县城东北部,总面积6267公顷,林地面积4933公顷,山高林密,最高海拔为1090米。该区有丰富的森林资源、动植物资源,素以城古、洞幽、林密、崖险、壁奇、峰峻、景秀而著称。建在罗通山上的古城是吉林省重点文物保护单位和风景名…整体感受是略失望，可考虑其他景点。二刷意愿：否。', '0%', 52);
