INSERT INTO `travel_review` VALUES (10067, 'TR010067', '七一冰川', '张掖', '甘肃', '城市漫游', '冬季', 11, 2, 109.00, '否', 3, '11月去的七一冰川，一个人出行。地点在张掖，打车比较省心，现场游客较多。这次玩了2天，人均花费约109元，历史文化气息浓。景点印象：“七一”冰川位于嘉峪关市西南116公里处的祁连山腹地，每到夏秋季节，冰峰在蓝天丽日下分外晶莹耀眼，与潺潺的溪流以及绿草如茵、鲜花盛开的高山牧场，共同构成一幅恬静而又充满生机的迷人画卷。整体感受是体验一般，别抱太高期待。二刷意愿：否。', '13%', 48);
