INSERT INTO `travel_review` VALUES (10099, 'TR010099', '神农园', '株洲', '湖南', '深度游', '秋季', 8, 2, 628.00, '是', 5, '8月去的神农园，和家人出行。地点在株洲，自驾停车需要提前规划，现场人流量适中。这次玩了2天，人均花费约628元，夜景表现很好。景点印象：神农园是株洲市电力集团物业发展有限公司在高新区邓城村原有耕地基础上开发出的高科技种植园及养殖园，是一个集农业科技、旅游观光、休闲娱乐为一体的新型产业基地。\n园内有楠竹群建筑物、农家四合院、泰式竹楼、傣家竹楼等景点供人观赏、休闲，能…整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 105);
