INSERT INTO `travel_review` VALUES (10117, 'TR010117', '钟楼', '泉州', '福建', '周末短途', '秋季', 6, 7, 1791.00, '否', 3, '6月去的钟楼，一个人出行。地点在泉州，打车比较省心，现场高峰时段比较拥挤。这次玩了7天，人均花费约1791元，夜景表现很好。景点印象：泉州钟楼是1934年建设东西街十字路时建的标准钟楼，具有欧洲风格。整体感受是体验一般，按需选择。二刷意愿：否。', '3%', 56);
INSERT INTO `travel_review` VALUES (10118, 'TR010118', '白水岭热带森林', '万宁', '海南', '亲子出游', '秋季', 7, 6, 1440.00, '否', 2, '7月去的白水岭热带森林，情侣出行。地点在万宁，自驾停车需要提前规划，现场游客较多。这次玩了6天，人均花费约1440元，拍照很出片。景点印象：属热带原始森林，总面积45700多亩，这里生长着茂密的热带山地雨季林，林中栖息着种类众多的珍稀动物，被誉为海南物华天宝之地，是热带森林旅游观光的好去处。\n进入保护区古林绿海之中，那林海涛声，时而咆哮，时而低吟。立于山巅俯视，日挂中天，树…整体感受是略失望，不建议高峰来。二刷意愿：否。', '0%', 38);
