INSERT INTO `travel_review` VALUES (10126, 'TR010126', '凤县', '宝鸡', '陕西', '文化打卡', '秋季', 7, 6, 1598.00, '是', 5, '7月去的凤县，一个人出行。地点在宝鸡，打车比较省心，现场高峰时段比较拥挤。这次玩了6天，人均花费约1598元，拍照很出片。景点印象：凤县古称“凤州”，始建于秦朝。地处陕西省宝鸡市西南，位于东经106°24′54″~107°7′30″，北纬33°34′57″~34°18′21″。因地连陕甘，又处入川孔道，北依秦岭主脊，南接紫柏山，古栈道贯通全境，故有“秦蜀咽喉，汉北锁钥”之称。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 97);
