INSERT INTO `travel_review` VALUES (10195, 'TR010195', '梧州古墓群', '梧州', '广西', '拍照旅行', '夏季', 4, 1, 697.00, '否', 4, '4月去的梧州古墓群，和家人出行。地点在梧州，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约697元，历史文化气息浓。景点印象：位于市区的云盖山、螺山、莲花山一带，范围较分散。墓葬年代多数是西汉、东汉和两晋时期的，出土文物有大量的陶器、铜器、瓷器等。这表明梧州自汉代以来就是中国南方地区的一座重镇。整体感受是整体不错，可以安排半天到一天。二刷意愿：否。', '0%', 36);
