INSERT INTO `travel_review` VALUES (10263, 'TR010263', '小孤山人类遗址', '鞍山', '辽宁', '深度游', '秋季', 6, 4, 1163.00, '否', 4, '6月去的小孤山人类遗址，和家人出行。地点在鞍山，地铁到达方便，现场人流量适中。这次玩了4天，人均花费约1163元，夜景表现很好。景点印象：又称“仙人洞”。座落鞍山海城东南45公里处，是天然石洞。洞口宽敞，洞宽4.9米，纵深22.5米。洞门上方刻有\"王洞\"二字，据查是明万历年间所立。洞中挖掘出旧石器时代晚期与新石器时代文化遗迹和遗物，距今约4万年至1万年，与北京周口店山顶洞人文化…整体感受是还蛮满意，推荐来看看。二刷意愿：否。', '0%', 58);
