INSERT INTO `travel_review` VALUES (10287, 'TR010287', '“九•一八”历史博物馆', '沈阳', '辽宁', '深度游', '秋季', 8, 3, 1393.00, '是', 5, '8月去的“九•一八”历史博物馆，和家人出行。地点在沈阳，公交换乘方便，现场游客较多。这次玩了3天，人均花费约1393元，夜景表现很好。景点印象：意义深刻的爱国主义教育基地，陈列着大量的日军侵华罪证。整体感受是超出预期，以后还会来。二刷意愿：是。', '13%', 78);
INSERT INTO `travel_review` VALUES (10288, 'TR010288', '涌泉寺', '福州', '福建', '深度游', '秋季', 8, 6, 1474.00, '否', 4, '8月去的涌泉寺，一个人出行。地点在福州，地铁到达方便，现场游客较多。这次玩了6天，人均花费约1474元，氛围感不错。景点印象：福州市鼓山涌泉寺为“闽刹之冠”，又是全国重点寺庙之一。整体感受是还蛮满意，可以安排半天到一天。二刷意愿：否。', '6%', 63);
