INSERT INTO `travel_review` VALUES (10380, 'TR010380', '一万泉旅游度假村', '昌吉', '新疆', '周末短途', '秋季', 7, 6, 1714.00, '是', 5, '7月去的一万泉旅游度假村，和家人出行。地点在昌吉，公交换乘方便，现场高峰时段比较拥挤。这次玩了6天，人均花费约1714元，氛围感不错。景点印象：一万泉旅游度假村为国家AAA级景区，位于农六师奇台农场以南天山无名峰下，源于哈拉萨依沟，有众多泉水汇成一股清流，常年不息，故名“一万泉”。\n　　此景点是北疆东部天山北坡最好的天然草场之一，自然降水丰富，山梁阴坡翠松挺拔，阳坡牧草茂盛，…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 103);
