INSERT INTO `travel_review` VALUES (10411, 'TR010411', '万山岛', '珠海', '广东', '亲子出游', '夏季', 3, 5, 1269.00, '否', 4, '3月去的万山岛，和朋友出行。地点在珠海，公交换乘方便，现场人流量适中。这次玩了5天，人均花费约1269元，夜景表现很好。景点印象：富有神奇色彩的小岛，亚洲奇观浮石湾、妈祖祭典、海蚀地貌都是海岛的浓郁特色。整体感受是整体不错，可以安排半天到一天。二刷意愿：否。', '0%', 67);
