INSERT INTO `travel_review` VALUES (10413, 'TR010413', '仙人洞', '九江', '江西', '城市漫游', '春季', 12, 4, 769.00, '是', 5, '12月去的仙人洞，情侣出行。地点在九江，公交换乘方便，现场人流量适中。这次玩了4天，人均花费约769元，历史文化气息浓。景点印象：庐山景点之一，幽深处有清泉下滴，名为一滴泉，云雾缭绕之时，似几分仙气。整体感受是特别满意，很推荐。二刷意愿：是。', '34%', 35);
INSERT INTO `travel_review` VALUES (10414, 'TR010414', '黑龙山庄度假村', '黑河', '黑龙江', '深度游', '春季', 2, 3, 945.00, '是', 3, '2月去的黑龙山庄度假村，一个人出行。地点在黑河，地铁到达方便，现场人不算多。这次玩了3天，人均花费约945元，拍照很出片。景点印象：黑龙山庄度假村建于1995年，是黑河第一家私营旅游企业，林地面积13晌，自主使用权50年。她坐落在黑龙江西郊7公里的黑龙江畔，与俄罗斯一江之隔，鸡犬之声相闻。依山傍水、风景秀丽、景色宜人。\n山庄的自然资源十分丰富，各种应季的山野菜，优质的矿…整体感受是体验一般，避开高峰更好。二刷意愿：是。', '0%', 44);
INSERT INTO `travel_review` VALUES (10415, 'TR010415', '额尔古纳界河', '呼伦贝尔', '内蒙古', '拍照旅行', '冬季', 10, 4, 1043.00, '是', 4, '10月去的额尔古纳界河，和朋友出行。地点在呼伦贝尔，打车比较省心，现场人流量适中。这次玩了4天，人均花费约1043元，历史文化气息浓。景点印象：额尔古纳界河 \"额尔古纳\"是蒙古语，为\"捧呈、递献\"之意。当海拉尔河从大兴安岭发源，流至呼伦贝尔草原西部赉诺尔北阿巴该图附近时，突然转向东北流去，其形正成165\'，有如人捧呈递献东西之状，故从此处改河名为额尔古纳河。整体感受是还蛮满意，推荐来看看。二刷意愿：是。', '9%', 61);
