INSERT INTO `travel_review` VALUES (10436, 'TR010436', '冈仁波齐', '阿里', '西藏', '城市漫游', '春季', 12, 1, 504.00, '是', 5, '12月去的冈仁波齐，一个人出行。地点在阿里，公交换乘方便，现场游客较多。这次玩了1天，人均花费约504元，夜景表现很好。景点印象：冈仁波齐是公认的神山，山势壮丽秀美，被《中国国家地理》杂志评选为中国最美的十大名山之一。 每年春秋两季，是转山的最佳时刻。尤其是藏历马年，来此转山的朝圣者络绎不绝。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '70%', 92);
INSERT INTO `travel_review` VALUES (10437, 'TR010437', '白龙洞景区', '黑河', '黑龙江', '周末短途', '夏季', 4, 4, 1132.00, '否', 5, '4月去的白龙洞景区，一个人出行。地点在黑河，地铁到达方便，现场人流量适中。这次玩了4天，人均花费约1132元，历史文化气息浓。景点印象：景点本身有一定特色整体感受是挺惊喜，以后还会来。二刷意愿：否。', '5%', 67);
INSERT INTO `travel_review` VALUES (10438, 'TR010438', '灵光寺', '梅州', '广东', '亲子出游', '秋季', 7, 6, 1547.00, '否', 5, '7月去的灵光寺，和朋友出行。地点在梅州，自驾停车需要提前规划，现场游客较多。这次玩了6天，人均花费约1547元，历史文化气息浓。景点印象：该寺原名圣寿寺，是广东省四大名刹之一，相传为唐代懿宗咸通年间高僧潘了拳创建，至今已有一千多年历史。生死树、菠萝顶、顶无叶合称灵光三绝，无笃石螺、片生熟鱼、五色雀合称灵光三奇。整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '35%', 89);
