INSERT INTO `travel_review` VALUES (10445, 'TR010445', '玉龙湖', '泸州', '四川', '周末短途', '春季', 1, 2, 409.00, '否', 5, '1月去的玉龙湖，一个人出行。地点在泸州，地铁到达方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约409元，历史文化气息浓。景点印象：玉龙湖风景区位于泸县东部立石镇、毗卢镇境内，原名三溪口水库，占地13平方公里，其中水面6平方公里，南北长25公里，蓄水2510立方米，灌田10万亩，年起水成鱼300多吨。玉龙湖地理位置极佳。处在重庆、内江、泸州三角区中，泸永公路旁，幅射面宽、交…整体感受是特别满意，值得专门打卡。二刷意愿：否。', '25%', 90);
