INSERT INTO `travel_review` VALUES (10455, 'TR010455', '安义古村', '南昌', '江西', '文化打卡', '秋季', 7, 1, 679.00, '是', 3, '7月去的安义古村，和家人出行。地点在南昌，公交换乘方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约679元，夜景表现很好。景点印象：南昌西郊原汁原味的古村群，周末郊游的好地方。 欣赏亭亭如盖的千年古樟、气势恢宏的世大夫第，感受历史气息。整体感受是还可以，别抱太高期待。二刷意愿：是。', '1%', 52);
