INSERT INTO `travel_review` VALUES (10457, 'TR010457', '周总理视察大营纪念馆', '三门峡', '河南', '深度游', '夏季', 4, 5, 1116.00, '是', 5, '4月去的周总理视察大营纪念馆，和朋友出行。地点在三门峡，地铁到达方便，现场游客较多。这次玩了5天，人均花费约1116元，夜景表现很好。景点印象：周恩来总理视察大营纪念馆座落在陕县大营镇大营村中心，距三门峡市区20公里。该馆落成于1977年，主体建筑连同外宾接待室和综合展览馆，总面积为2360平方米。馆内陈列有1958年4月24日周恩来总理视察大营时的照片和有关实物，还有彭德怀、习仲勋及河…整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 102);
