INSERT INTO `travel_review` VALUES (10492, 'TR010492', '哈熊沟', '昌吉', '新疆', '亲子出游', '春季', 12, 1, 461.00, '否', 2, '12月去的哈熊沟，情侣出行。地点在昌吉，公交换乘方便，现场游客较多。这次玩了1天，人均花费约461元，历史文化气息浓。景点印象：哈熊沟位于米泉县城东南47公里处的天山山区，这里山景、水景、雪景都十分迷人。山岭长满云杉，云杉随山势而起伏层叠，犹如排空的翠浪。山风吹来时，绿涛滚涌，满山遍野仿佛都在涌动，一派瑰丽雄奇的景致。哈熊沟空气凉爽湿润，水质极好，游人到此无…整体感受是略失望，建议谨慎前往。二刷意愿：否。', '1%', 41);
