INSERT INTO `travel_review` VALUES (10537, 'TR010537', '哈拉新村', '齐齐哈尔', '黑龙江', '周末短途', '冬季', 10, 1, 442.00, '否', 5, '10月去的哈拉新村，和家人出行。地点在齐齐哈尔，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约442元，拍照很出片。景点印象：蛇洞山风景区位于齐齐哈尔市碾子山区西部4.5公里，占地面积300公顷，最高峰龙峰海拔406米，是国家“AA”级风景区。景区由青石崖、蛇洞山、龙峰、佛尔寺及西河园等景观构成。区内峰峦起伏，怪石嶙峋，各景点错落有致、浑然一体，龟、牛、蛙、龙、狮…整体感受是超出预期，很推荐。二刷意愿：否。', '0%', 53);
