INSERT INTO `travel_review` VALUES (10554, 'TR010554', '永兴湖', '乌兰察布', '内蒙古', '周末短途', '夏季', 5, 2, 309.00, '是', 5, '5月去的永兴湖，情侣出行。地点在乌兰察布，打车比较省心，现场游客较多。这次玩了2天，人均花费约309元，夜景表现很好。景点印象：永兴湖的形成距今有50多万年，有商业活动2000多年。永兴湖的山不高，湖水不大，但山水相映，秀丽多姿，群山环抱，湖面如镜，候鸟啼鸣，树影婆娑，空气清新，小河流水等绿色景观，以及篝火晚会，乡土文化，令人陶醉，流连忘返。钓鱼、爬山、游泳、划…整体感受是特别满意，很推荐。二刷意愿：是。', '0%', 39);
