INSERT INTO `travel_review` VALUES (10639, 'TR010639', '马过河景区', '曲靖', '云南', '周末短途', '冬季', 9, 3, 746.00, '否', 5, '9月去的马过河景区，和家人出行。地点在曲靖，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了3天，人均花费约746元，拍照很出片。景点印象：马龙县马过河风景名胜区地处滇中高原马龙县境内，由马过河、万亩草场、香炉山三个片区组成，共有37个景点，景区面积28平方公里。马过河风景名胜区以溪流平湖、陡壁峭岩、瀑布、跌水为特色，森林植被保存了滇中地区原生植被和生态景观，景区溪水、瀑…整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '0%', 100);
