INSERT INTO `travel_review` VALUES (10665, 'TR010665', '褒斜栈道', '汉中', '陕西', '周末短途', '秋季', 8, 2, 509.00, '是', 5, '8月去的褒斜栈道，情侣出行。地点在汉中，公交换乘方便，现场游客较多。这次玩了2天，人均花费约509元，氛围感不错。景点印象：褒斜道是中国历史上最古老的道路之一，对政治、经济、文化的发展起过重大作用，在交通史上占有极其重要的地位。在唐宋时期，褒斜道是兵家行军必经之路，同时又是商旅的要道。整体感受是超出预期，很推荐。二刷意愿：是。', '10%', 62);
