INSERT INTO `travel_review` VALUES (10686, 'TR010686', '念湖', '曲靖', '云南', '城市漫游', '夏季', 5, 4, 443.00, '是', 5, '5月去的念湖，和家人出行。地点在曲靖，自驾停车需要提前规划，现场人流量适中。这次玩了4天，人均花费约443元，夜景表现很好。景点印象：念湖是位于曲靖市会泽县大桥乡和昭通交界处的黑颈鹤自然保护区。它原本是云南高原中一个不起眼的乡镇。一个颇具时代特征的名字，叫“跃进水库”又名“念湖”[1] 。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '5%', 79);
