INSERT INTO `travel_review` VALUES (10716, 'TR010716', '海战博物馆', '东莞', '广东', '周末短途', '秋季', 6, 1, 253.00, '是', 5, '6月去的海战博物馆，和朋友出行。地点在东莞，公交换乘方便，现场人流量适中。这次玩了1天，人均花费约253元，夜景表现很好。景点印象：鸦片战争主题博物馆，全国禁毒教育基地，是一座专题性与遗址性相结合的博物馆。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '5%', 105);
INSERT INTO `travel_review` VALUES (10717, 'TR010717', '五柳龙泉', '宿州', '安徽', '深度游', '秋季', 8, 4, 1254.00, '是', 5, '8月去的五柳龙泉，和朋友出行。地点在宿州，公交换乘方便，现场人不算多。这次玩了4天，人均花费约1254元，氛围感不错。景点印象：五柳省级风景名胜区位于宿州市市区北约30公里的夹沟镇，处于徐州图库、淮北、宿州三市的中心，总面积35平方公里，这里以“山青、水秀、洞奇、泉灵、稻香”而闻名，景区南、西、北三面环山，植物种类繁多，气候宜人。\n主景区内龙泉湖碧波荡漾、水质…整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 64);
