INSERT INTO `travel_review` VALUES (10769, 'TR010769', '第十二窟（离垢地菩萨洞）', '大同', '山西', '周末短途', '秋季', 6, 3, 1163.00, '是', 4, '6月去的第十二窟（离垢地菩萨洞），和家人出行。地点在大同，打车比较省心，现场游客较多。这次玩了3天，人均花费约1163元，氛围感不错。景点印象：第十二窟离垢地菩萨洞，俗称“音乐窟”，该窟内乐器雕刻的形制、演奏方式以及乐队的组合形式，集中体现了北魏宫廷乐队风貌和社会音乐制度，是研究中国古代音乐史的珍贵资料。整体感受是体验挺好，周末来刚好。二刷意愿：是。', '0%', 84);
