INSERT INTO `travel_review` VALUES (10783, 'TR010783', '青云塔', '万宁', '海南', '深度游', '夏季', 5, 7, 1598.00, '否', 5, '5月去的青云塔，情侣出行。地点在万宁，地铁到达方便，现场游客较多。这次玩了7天，人均花费约1598元，历史文化气息浓。景点印象：当地亦称这\"山尾岭\"、\"万州塔\"。青云塔体为八角形，用火砖和零星石料砌成，塔高约27米，分七层七檐。顶层正中，突出一个八棱柱，柱顶托道一个球形塔刹。底层内壁为八角形，上面六层内壁均为圆形，每层从不同方向对开两个拱门，一供观赏，二供通风透…整体感受是挺惊喜，很推荐。二刷意愿：否。', '0%', 49);
