INSERT INTO `travel_review` VALUES (10802, 'TR010802', '抚顺苏子河漂流', '抚顺', '辽宁', '拍照旅行', '秋季', 7, 4, 838.00, '否', 5, '7月去的抚顺苏子河漂流，情侣出行。地点在抚顺，打车比较省心，现场高峰时段比较拥挤。这次玩了4天，人均花费约838元，拍照很出片。景点印象：苏子河漂流位于新宾满族自治县境内的苏子河中段，距市区90余公里，乘车经202国道和东南公路仅1小时就可以到达。坐在船筏上沿途可欣赏到冰湖沟、望石谷、石龙峡、望松台、奇峰山、卧龙岭、怪石涯、万古峡、刺激关等景观。漂流段全长13公里，漂流全程…整体感受是特别满意，很推荐。二刷意愿：否。', '0%', 68);
