INSERT INTO `travel_review` VALUES (10853, 'TR010853', '中卫高庙', '中卫', '宁夏', '深度游', '冬季', 11, 1, 374.00, '否', 5, '11月去的中卫高庙，和朋友出行。地点在中卫，地铁到达方便，现场人不算多。这次玩了1天，人均花费约374元，拍照很出片。景点印象：一座建在高台上的寺庙，不大的面积内集中了260多间楼阁，极为紧凑有序。 三教合一，同时可以敬拜佛祖、玉帝和孔子、关老爷。整体感受是挺惊喜，以后还会来。二刷意愿：否。', '21%', 61);
INSERT INTO `travel_review` VALUES (10854, 'TR010854', '华南虎保护区', '抚州', '江西', '周末短途', '春季', 12, 4, 892.00, '否', 4, '12月去的华南虎保护区，和家人出行。地点在抚州，自驾停车需要提前规划，现场人流量适中。这次玩了4天，人均花费约892元，拍照很出片。景点印象：宜黄县位于江西省东部，地处武夷山山脉与雩山山脉向抚河平原过渡地带。全县土地总面积19.44万公项，其中林业用地面积15.09万公项，占土地总面积的77.6％。境内有3条南北走向的山脉，东支主峰军峰山，海拔1760.9米，中支主峰鱼牙嶂，海拔1467.9米，…整体感受是体验挺好，可以安排半天到一天。二刷意愿：否。', '0%', 57);
