INSERT INTO `travel_review` VALUES (10865, 'TR010865', '洪江古商城', '怀化', '湖南', '深度游', '夏季', 3, 7, 1655.00, '是', 5, '3月去的洪江古商城，一个人出行。地点在怀化，自驾停车需要提前规划，现场人流量适中。这次玩了7天，人均花费约1655元，历史文化气息浓。景点印象：景点本身有一定特色整体感受是超出预期，很推荐。二刷意愿：是。', '32%', 101);
INSERT INTO `travel_review` VALUES (10866, 'TR010866', '赛罕乌拉', '赤峰', '内蒙古', '周末短途', '春季', 2, 1, 203.00, '否', 5, '2月去的赛罕乌拉，和朋友出行。地点在赤峰，公交换乘方便，现场游客较多。这次玩了1天，人均花费约203元，夜景表现很好。景点印象：赛罕乌拉自然保护区是一个以保护森林、草原、湿地等多样生态系统和珍稀濒危野生动植物及西辽河上游水原涵养林为主的山地综合性自然保护区，总面积为10.04万公顷。\n该保护区2000年4月被国务院批准为国家级自然保护区，1999年被国际鸟类联盟确定为世…整体感受是超出预期，很推荐。二刷意愿：否。', '0%', 108);
INSERT INTO `travel_review` VALUES (10867, 'TR010867', '新昌大佛寺景区', '绍兴', '浙江', '亲子出游', '春季', 2, 3, 897.00, '否', 5, '2月去的新昌大佛寺景区，和家人出行。地点在绍兴，地铁到达方便，现场人流量适中。这次玩了3天，人均花费约897元，氛围感不错。景点印象：在大佛殿看江南最古老的石窟大佛，还有金碧辉煌的弥勒塑像。整体感受是超出预期，值得专门打卡。二刷意愿：否。', '1%', 86);
