INSERT INTO `travel_review` VALUES (10870, 'TR010870', '“九•一八”历史博物馆', '沈阳', '辽宁', '文化打卡', '秋季', 7, 2, 753.00, '否', 3, '7月去的“九•一八”历史博物馆，和家人出行。地点在沈阳，公交换乘方便，现场人流量适中。这次玩了2天，人均花费约753元，夜景表现很好。景点印象：意义深刻的爱国主义教育基地，陈列着大量的日军侵华罪证。整体感受是还可以，避开高峰更好。二刷意愿：否。', '13%', 61);
