INSERT INTO `travel_review` VALUES (10884, 'TR010884', '莫干山风景名胜区', '湖州', '浙江', '文化打卡', '春季', 12, 3, 904.00, '否', 5, '12月去的莫干山风景名胜区，和家人出行。地点在湖州，地铁到达方便，现场游客较多。这次玩了3天，人均花费约904元，氛围感不错。景点印象：长三角热门避暑地，漫步竹海之间，欣赏山中颇有韵味的老别墅。整体感受是特别满意，以后还会来。二刷意愿：否。', '13%', 95);
INSERT INTO `travel_review` VALUES (10885, 'TR010885', '德夯大峡谷', '湘西', '湖南', '周末短途', '秋季', 8, 2, 165.00, '是', 5, '8月去的德夯大峡谷，和家人出行。地点在湘西，打车比较省心，现场高峰时段比较拥挤。这次玩了2天，人均花费约165元，历史文化气息浓。景点印象：看上去晃晃悠悠悬在山顶主跨达1176米的矮寨大桥，车行通过绝对挑战胆量！ 矮寨大桥下有13个180度发卡弯的矮寨公路，看一眼就觉得十分惊险！ 地处张家界-凤凰一线上，游客却很少，山清水秀间享受一份清静。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 74);
