INSERT INTO `travel_review` VALUES (10892, 'TR010892', '上封寺', '衡阳', '湖南', '拍照旅行', '夏季', 3, 1, 135.00, '是', 5, '3月去的上封寺，一个人出行。地点在衡阳，打车比较省心，现场游客较多。这次玩了1天，人均花费约135元，氛围感不错。景点印象：距离衡山风景区内最佳看日出地点——“望日台”只有五分钟路程。 附近有不少的酒店和农家乐宾馆，住宿在这里便于次日凌晨观看日出。 寺内每日都有“早晚课”，住宿在附近聆听晨钟暮鼓，净化心灵。整体感受是超出预期，值得专门打卡。二刷意愿：是。', '13%', 104);
