INSERT INTO `travel_review` VALUES (10942, 'TR010942', '高颐阙', '雅安', '四川', '文化打卡', '春季', 2, 1, 250.00, '否', 4, '2月去的高颐阙，情侣出行。地点在雅安，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约250元，历史文化气息浓。景点印象：东汉益州太守高颐及其弟高实的墓阙，四川保存最完整、最精美的石阙，全国重点文物保护单位。在雅安市姚桥镇汉碑村。东汉建安十四年（209年）建造。两阙相距13.6米，阙间有高君宋碑及巨型石辟邪。两阙北壁皆有阴刻隶书铭文，东阙为\"汉故益州太守武阴…整体感受是还蛮满意，周末来刚好。二刷意愿：否。', '0%', 50);
