INSERT INTO `travel_review` VALUES (10946, 'TR010946', '万岁山', '开封', '河南', '深度游', '夏季', 5, 1, 664.00, '否', 5, '5月去的万岁山，和家人出行。地点在开封，打车比较省心，现场人流量适中。这次玩了1天，人均花费约664元，历史文化气息浓。景点印象：万岁山藏自然山水美与人工美于一体，括天下之绝，含古今之胜，集我国古代南北园林建筑艺术之大成，荟萃华夏名山大川雄伟、险峻、奇秀、幽美、畅旷诸特色，成为全国山水奇景的一个缩影，堪称世界一绝。整体感受是超出预期，值得专门打卡。二刷意愿：否。', '1%', 81);
