INSERT INTO `travel_review` VALUES (10970, 'TR010970', '朱然陈列馆', '马鞍山', '安徽', '城市漫游', '春季', 1, 2, 1046.00, '否', 3, '1月去的朱然陈列馆，一个人出行。地点在马鞍山，打车比较省心，现场高峰时段比较拥挤。这次玩了2天，人均花费约1046元，夜景表现很好。景点印象：朱然陈列馆位于安徽省马鞍山市区南部的雨山乡境内，为三国东吴大将朱然之墓。朱然墓发掘于1984年6月，出土许多珍贵文物，部分漆器填补了三国美术史的空白，也是已发掘东吴墓葬中墓主身份最高、墓葬规模最大的、时间最早的一座大墓，被列为80年代中…整体感受是还可以，别抱太高期待。二刷意愿：否。', '25%', 50);
