INSERT INTO `travel_review` VALUES (11006, 'TR011006', '湖心岛', '岳阳', '湖南', '文化打卡', '夏季', 5, 1, 354.00, '否', 4, '5月去的湖心岛，一个人出行。地点在岳阳，打车比较省心，现场人流量适中。这次玩了1天，人均花费约354元，氛围感不错。景点印象：位于龙源水库中央，岛上险峰怪石，弥不胜举，奇花异草，目不暇接；四围青山环抱，水波涟涟。远远望去，恰如白银盘里一青螺。整体感受是体验挺好，推荐来看看。二刷意愿：否。', '2%', 54);
