INSERT INTO `travel_review` VALUES (11019, 'TR011019', '蒙山大佛', '太原', '山西', '深度游', '冬季', 9, 1, 330.00, '是', 5, '9月去的蒙山大佛，和家人出行。地点在太原，公交换乘方便，现场游客较多。这次玩了1天，人均花费约330元，拍照很出片。景点印象：蒙山大佛主峰高1325米，比目前全国最大的乐山大佛略高，蒙山晓月也是旧太原八景之一。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '3%', 99);
INSERT INTO `travel_review` VALUES (11020, 'TR011020', '苏铁自然保护区', '攀枝花', '四川', '文化打卡', '冬季', 10, 3, 787.00, '否', 5, '10月去的苏铁自然保护区，一个人出行。地点在攀枝花，打车比较省心，现场人不算多。这次玩了3天，人均花费约787元，夜景表现很好。景点印象：主要保护对象是攀枝花苏铁这一珍稀濒危植物及其生态环境。\n攀枝花苏铁是1971年发现的苏铁新种，1981年才正式定名，1984年被列入我国第一批珍稀濒危保护植物名录，攀枝花苏铁对于研究我国横断山脉植物区系的发生和发展，以及古生物、古生态、古气候…整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '3%', 83);
INSERT INTO `travel_review` VALUES (11021, 'TR011021', '龚滩古镇乌江画廊', '重庆', '重庆', '深度游', '冬季', 11, 1, 489.00, '是', 5, '11月去的龚滩古镇乌江画廊，和家人出行。地点在重庆，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约489元，夜景表现很好。景点印象：周边配套比较齐全整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 92);
INSERT INTO `travel_review` VALUES (11022, 'TR011022', '南山风景旅游区', '伊春', '黑龙江', '拍照旅行', '春季', 2, 2, 647.00, '否', 2, '2月去的南山风景旅游区，一个人出行。地点在伊春，打车比较省心，现场人不算多。这次玩了2天，人均花费约647元，夜景表现很好。景点印象：南山风景旅游区始建于1993年，景区占地面积为3500公顷，山体平均海拔420米，其中兴安塔主峰海拔653米，塔高47米，是景区的标志性建筑。南山景区地势起伏、峰谷迂回、空间富于变化、自然形成山体，峰容坡地构成风景区多种的地貌景观。景区森林覆盖率…整体感受是略失望，建议谨慎前往。二刷意愿：否。', '0%', 44);
