INSERT INTO `travel_review` VALUES (11042, 'TR011042', '连环湖水禽狩猎场', '大庆', '黑龙江', '文化打卡', '夏季', 3, 6, 1366.00, '是', 4, '3月去的连环湖水禽狩猎场，和家人出行。地点在大庆，打车比较省心，现场游客较多。这次玩了6天，人均花费约1366元，历史文化气息浓。景点印象：连环湖水禽狩猎场位于黑龙江省西南部杜尔伯特蒙古族自治县境内，它是一个南北长60多公里，东西宽20多公里，由18个泡泊相互连接组成的淡水湖，总面积5．8万公顷。这里芦苇丛生，湖湾密布，栖息着水鸭等禽类249种，其中可猎禽类49种，是极好的天然水…整体感受是还蛮满意，周末来刚好。二刷意愿：是。', '0%', 60);
