INSERT INTO `travel_review` VALUES (11080, 'TR011080', '桃源洞', '株洲', '湖南', '城市漫游', '春季', 1, 1, 461.00, '否', 2, '1月去的桃源洞，一个人出行。地点在株洲，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约461元，夜景表现很好。景点印象：桃源洞的地形、地貌、地质和气候等自然条件构成独特的自然生态环境，使他不仅成为天然动植物物种基因库，而且成为不可多得的森林旅游福地，令世人神往的人间仙景。\n丰富的动植物资源 桃源洞属华南、华东等多种植物区第成份的交汇处和过渡地，植物…整体感受是没达到预期，不建议高峰来。二刷意愿：否。', '0%', 20);
