INSERT INTO `travel_review` VALUES (11099, 'TR011099', '都兰国际狩猎场', '海西', '青海', '深度游', '春季', 2, 4, 1174.00, '是', 5, '2月去的都兰国际狩猎场，情侣出行。地点在海西，公交换乘方便，现场高峰时段比较拥挤。这次玩了4天，人均花费约1174元，历史文化气息浓。景点印象：都兰国际狩猎场是青海第一个对外开放的狩猎场。地处青藏高原北部的山地向高原主体过渡地段上的柴达木盆地东南部，海西州都兰县南部 ，面积13000多公顷，为高原高寒大陆性气候，每年5月植被开始返青，种类较多。场内山峦起伏，谷地地势平坦，平均海…整体感受是特别满意，很推荐。二刷意愿：是。', '0%', 50);
