INSERT INTO `travel_review` VALUES (11119, 'TR011119', '太阳湖', '可可西里', '青海', '亲子出游', '秋季', 8, 2, 651.00, '否', 2, '8月去的太阳湖，一个人出行。地点在可可西里，公交换乘方便，现场人流量适中。这次玩了2天，人均花费约651元，氛围感不错。景点印象：太阳湖是每个进入可可西里保护区的人必经的地方，不仅因为有着优美的湖景，更最重要的是这里是唯一的淡水补寄，许多人选择在湖边扎营。整体感受是体验偏一般，不建议高峰来。二刷意愿：否。', '0%', 72);
INSERT INTO `travel_review` VALUES (11120, 'TR011120', '孟达天池', '海东', '青海', '拍照旅行', '秋季', 8, 3, 942.00, '否', 5, '8月去的孟达天池，和家人出行。地点在海东，打车比较省心，现场游客较多。这次玩了3天，人均花费约942元，拍照很出片。景点印象：拍摄高原上山川围绕的碧绿湖泊，景色优美。 漫步古树绿植之间，感受西北少见的清新自然。整体感受是特别满意，值得专门打卡。二刷意愿：否。', '0%', 96);
