INSERT INTO `travel_review` VALUES (11123, 'TR011123', '凤雏庵', '咸宁', '湖北', '城市漫游', '秋季', 6, 5, 1092.00, '是', 5, '6月去的凤雏庵，一个人出行。地点在咸宁，打车比较省心，现场人流量适中。这次玩了5天，人均花费约1092元，氛围感不错。景点印象：位于南屏山东南的金鸾山上。走近金鸾山，山门横额上“赤壁古风”几个大字赫然醒目。相传三国时庞统曾隐居于此。原建筑简陋，后世屡次扩建，但又迭遭兵焚。现存殿室数间，系清道光二十六年（1846年）重建，建国后曾维修，青砖灰瓦，甚为古朴。主室有…整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 78);
