INSERT INTO `travel_review` VALUES (11132, 'TR011132', '北城滩城堡遗址', '白银', '甘肃', '文化打卡', '夏季', 4, 2, 308.00, '否', 2, '4月去的北城滩城堡遗址，和朋友出行。地点在白银，自驾停车需要提前规划，现场游客较多。这次玩了2天，人均花费约308元，拍照很出片。景点印象：省级文物保护单位。位于靖远县城北 130 公里 处的双龙乡北城村黄河东岸，隔河与景泰县五佛寺对峙。古城呈方形，面积 35000 平方米 ，系夯土板筑，城墙下宽 5.8m ，残高 3.3m ，夯土层厚 10cm 。城门设在南面，并有凸形瓮城遗址，城墙夯土层夹有小砂…整体感受是没达到预期，不建议高峰来。二刷意愿：否。', '0%', 32);
