INSERT INTO `travel_review` VALUES (11188, 'TR011188', '瑞云寺', '朔州', '山西', '拍照旅行', '秋季', 8, 3, 791.00, '是', 5, '8月去的瑞云寺，一个人出行。地点在朔州，打车比较省心，现场人不算多。这次玩了3天，人均花费约791元，氛围感不错。景点印象：瑞云寺，位于山阴县沙家寺村。全部建筑原有山门、钟鼓二楼、东西厢房、瑞云宝殿、大雄宝殿、谦公和尚寿塔、砖塔等。据旧志书记载，寺始建于金代明昌二年（1191），明、清、民国时期，皆有修茸。谦公和尚寿塔，建在瑞云宝殿之后，为元延佑五年（1318…整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 109);
