INSERT INTO `travel_review` VALUES (11191, 'TR011191', '滇西抗战纪念馆', '保山', '云南', '文化打卡', '冬季', 10, 5, 1671.00, '否', 5, '10月去的滇西抗战纪念馆，和朋友出行。地点在保山，打车比较省心，现场人不算多。这次玩了5天，人均花费约1671元，夜景表现很好。景点印象：整体环境还算干净整体感受是挺惊喜，很推荐。二刷意愿：否。', '24%', 73);
INSERT INTO `travel_review` VALUES (11192, 'TR011192', '博鳌鸳鸯岛', '琼海', '海南', '深度游', '冬季', 9, 1, 532.00, '是', 5, '9月去的博鳌鸳鸯岛，情侣出行。地点在琼海，打车比较省心，现场游客较多。这次玩了1天，人均花费约532元，历史文化气息浓。景点印象：玉带滩位于万泉河入海口。说起江河入海口，人们自然会联想起长江、黄河入海口，或尼罗河、亚马逊河入海口。然而与众不同的是，万泉河入海口有条长达2．5公里的狭窄沙坝， 横亘在万泉河和南海之间，那就是玉带滩。玉带滩是一条自然形成的地形狭长的…整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 112);
