INSERT INTO `travel_review` VALUES (11225, 'TR011225', '圣托里尼·蓝顶海景温泉', '秦皇岛', '河北', '城市漫游', '夏季', 5, 1, 655.00, '否', 5, '5月去的圣托里尼·蓝顶海景温泉，情侣出行。地点在秦皇岛，打车比较省心，现场人流量适中。这次玩了1天，人均花费约655元，拍照很出片。景点印象：整体环境还算干净整体感受是超出预期，值得专门打卡。二刷意愿：否。', '0%', 71);
INSERT INTO `travel_review` VALUES (11226, 'TR011226', '康益泉温泉', '廊坊', '河北', '亲子出游', '春季', 12, 5, 1154.00, '否', 5, '12月去的康益泉温泉，和朋友出行。地点在廊坊，自驾停车需要提前规划，现场人流量适中。这次玩了5天，人均花费约1154元，氛围感不错。景点印象：位于固安县牛驼镇南，106国道西侧，距北京70公里。独特的大型露天温泉浴池，水性温热而富含多种元素，浴之可温经通络、畅达气血，祛寒舒筋，消除疲劳，强身健体，疗效独特，常浴可使肌肤润滑光亮。室外桑拿室、康乐中心等设施相配套，能使步入康益…整体感受是挺惊喜，以后还会来。二刷意愿：否。', '50%', 98);
INSERT INTO `travel_review` VALUES (11227, 'TR011227', '花乡农家乐旅游区', '益阳', '湖南', '周末短途', '夏季', 5, 2, 528.00, '否', 2, '5月去的花乡农家乐旅游区，和家人出行。地点在益阳，公交换乘方便，现场游客较多。这次玩了2天，人均花费约528元，氛围感不错。景点印象：益阳花乡农家乐旅游区位于赫山区黄泥湖乡仙蜂岭村，距益阳市中心城区6.5公里，被资水和志溪河环抱。\n仙蜂岭是闻名遐尔的花会之乡。早在上个世纪九十年代，仙蜂岭人集前辈的智慧和经验，进行花卉苗木的生产栽培。\n至今发展到300多户花农，1600多亩花…整体感受是略失望，可考虑其他景点。二刷意愿：否。', '0%', 53);
