INSERT INTO `travel_review` VALUES (11230, 'TR011230', '寨下大峡谷', '三明', '福建', '亲子出游', '夏季', 4, 2, 762.00, '是', 5, '4月去的寨下大峡谷，一个人出行。地点在三明，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了2天，人均花费约762元，夜景表现很好。景点印象：世外桃源般的地质奇观，原始生态保存得非常好，是观赏丹霞地貌的绝佳观景处。整体感受是超出预期，很推荐。二刷意愿：是。', '12%', 79);
INSERT INTO `travel_review` VALUES (11231, 'TR011231', '祠堂山山野公园', '汕尾', '广东', '文化打卡', '春季', 1, 1, 123.00, '是', 5, '1月去的祠堂山山野公园，一个人出行。地点在汕尾，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约123元，拍照很出片。景点印象：风景区包括南告水库、南万红维林和古莎椤自然保护区。南告水库由于自然风光 美，被称为“南天湖”。南告水库是截洪蓄水与引水发电双蒹的大型水库，库区周围群 山环抱，青山绿水，湖面如镜，水库拦水大坝建筑气势宏伟。\n南万红维林基地位于南万镇，…整体感受是特别满意，很推荐。二刷意愿：是。', '0%', 77);
