INSERT INTO `travel_review` VALUES (11239, 'TR011239', '禅窟寺', '滁州', '安徽', '城市漫游', '冬季', 10, 2, 499.00, '是', 5, '10月去的禅窟寺，和家人出行。地点在滁州，打车比较省心，现场人不算多。这次玩了2天，人均花费约499元，氛围感不错。景点印象：禅窟寺休闲度假胜地位于韭山国家森林公园内，距凤阳县城35公里,占地面积8.5平方公里，共有森林浴场、禅窟寺、禅窟洞、摩崖石刻等大小景点五十多个。\n整个景区群山奔凑,叠嶂连云；山下幽谷深邃，溪流潺潺；山间鸟语花香，藤树缠绕；山上流云雾海，岚…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 91);
