INSERT INTO `travel_review` VALUES (11246, 'TR011246', '云石山', '赣州', '江西', '周末短途', '秋季', 8, 6, 1503.00, '否', 2, '8月去的云石山，情侣出行。地点在赣州，打车比较省心，现场人流量适中。这次玩了6天，人均花费约1503元，夜景表现很好。景点印象：云石山位于瑞金市西南15公里。1934年7月临时中央政府从沙洲坝迁驻此地小山上的云山古寺，山中风景优美。1934年10月，中央机关编为红军中央纵队，从云石山出发开始长征，因而云石山被称为“长征第一山”。整体感受是体验偏一般，不建议高峰来。二刷意愿：否。', '0%', 47);
