INSERT INTO `travel_review` VALUES (11266, 'TR011266', '连环湖水禽狩猎场', '大庆', '黑龙江', '城市漫游', '秋季', 6, 1, 526.00, '是', 5, '6月去的连环湖水禽狩猎场，和朋友出行。地点在大庆，公交换乘方便，现场游客较多。这次玩了1天，人均花费约526元，夜景表现很好。景点印象：连环湖水禽狩猎场位于黑龙江省西南部杜尔伯特蒙古族自治县境内，它是一个南北长60多公里，东西宽20多公里，由18个泡泊相互连接组成的淡水湖，总面积5．8万公顷。这里芦苇丛生，湖湾密布，栖息着水鸭等禽类249种，其中可猎禽类49种，是极好的天然水…整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 99);
