INSERT INTO `travel_review` VALUES (11273, 'TR011273', '呼图壁公园', '昌吉', '新疆', '拍照旅行', '秋季', 7, 2, 583.00, '是', 5, '7月去的呼图壁公园，一个人出行。地点在昌吉，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了2天，人均花费约583元，拍照很出片。景点印象：位于呼图壁县城东风路西端的呼图壁公园是镶嵌在县城内一颗灿烂的明珠,占地面积350亩。一九九四年开始筹建,二OOO年十月一日正式向游人开放,二OO四年被评定为国家A级旅游景区。新近修建的人工湖、芙蓉池、长廊亭榭、游泳池等，均蕴涵着江南水乡的特色…整体感受是特别满意，很推荐。二刷意愿：是。', '0%', 77);
