INSERT INTO `travel_review` VALUES (11357, 'TR011357', '云石山', '赣州', '江西', '拍照旅行', '夏季', 5, 4, 1289.00, '否', 4, '5月去的云石山，和朋友出行。地点在赣州，地铁到达方便，现场游客较多。这次玩了4天，人均花费约1289元，拍照很出片。景点印象：云石山位于瑞金市西南15公里。1934年7月临时中央政府从沙洲坝迁驻此地小山上的云山古寺，山中风景优美。1934年10月，中央机关编为红军中央纵队，从云石山出发开始长征，因而云石山被称为“长征第一山”。整体感受是还蛮满意，可以安排半天到一天。二刷意愿：否。', '0%', 77);
