INSERT INTO `travel_review` VALUES (11380, 'TR011380', '曹州武术馆', '菏泽', '山东', '拍照旅行', '夏季', 4, 2, 687.00, '否', 5, '4月去的曹州武术馆，和朋友出行。地点在菏泽，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约687元，拍照很出片。景点印象：曹州武术馆是国家教委、体委批准认可的一所大型规范化、军事化教武育人的训练基地。本馆指导思想是：“以文保武”，“以武促文”、“以质量求生存”，“以信誉求发展”以法治馆，以德育人，培养“四有”人才，以传授和发扬中华武术为已任。整体感受是超出预期，很推荐。二刷意愿：否。', '0%', 72);
