INSERT INTO `travel_review` VALUES (11396, 'TR011396', '凤县', '宝鸡', '陕西', '文化打卡', '春季', 2, 2, 1012.00, '否', 2, '2月去的凤县，和朋友出行。地点在宝鸡，地铁到达方便，现场人流量适中。这次玩了2天，人均花费约1012元，氛围感不错。景点印象：凤县古称“凤州”，始建于秦朝。地处陕西省宝鸡市西南，位于东经106°24′54″~107°7′30″，北纬33°34′57″~34°18′21″。因地连陕甘，又处入川孔道，北依秦岭主脊，南接紫柏山，古栈道贯通全境，故有“秦蜀咽喉，汉北锁钥”之称。整体感受是略失望，可考虑其他景点。二刷意愿：否。', '0%', 75);
