INSERT INTO `travel_review` VALUES (11433, 'TR011433', '欣欣生态农业观光园', '淮安', '江苏', '深度游', '冬季', 11, 2, 649.00, '是', 5, '11月去的欣欣生态农业观光园，情侣出行。地点在淮安，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约649元，氛围感不错。景点印象：淮安市欣欣生态农业观光园位于涟水县保滩镇十堡村，距淮安市商业中心约12公里，离规划中的淮安机场约15公里，与淮安经济开发区毗邻，紧靠富士康、明基等大集团。京沪高速、淮涟一级公路交汇于此，古黄河穿境奔流。是实践传统农业向现代高效农业和多…整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 65);
