INSERT INTO `travel_review` VALUES (11439, 'TR011439', '沈阳金融博物馆', '沈阳', '辽宁', '深度游', '春季', 12, 4, 1318.00, '是', 4, '12月去的沈阳金融博物馆，情侣出行。地点在沈阳，公交换乘方便，现场人流量适中。这次玩了4天，人均花费约1318元，夜景表现很好。景点印象：观赏各种中外古钱币，了解金融与证券业的发展史。整体感受是还蛮满意，可以安排半天到一天。二刷意愿：是。', '6%', 64);
INSERT INTO `travel_review` VALUES (11440, 'TR011440', '棋盘滩', '百色', '广西', '深度游', '春季', 2, 6, 1944.00, '否', 5, '2月去的棋盘滩，情侣出行。地点在百色，公交换乘方便，现场人不算多。这次玩了6天，人均花费约1944元，历史文化气息浓。景点印象：棋盘滩风景区由棋盘滩、莲花山、寄情谷、独木成林、布洛佗石像等景点构成。棋盘滩是棋盘滩风景区的核心。棋盘滩形成于2亿多年前，是地壳运动过程中的产物。这种地质结构称为“剪节理”。这种地质结构方式许多地方都有，但一般来说别处都是在斜坡上…整体感受是特别满意，值得专门打卡。二刷意愿：否。', '2%', 95);
