INSERT INTO `travel_review` VALUES (11506, 'TR011506', '吞力黑衣壮民族风情园', '百色', '广西', '拍照旅行', '春季', 2, 2, 717.00, '是', 5, '2月去的吞力黑衣壮民族风情园，一个人出行。地点在百色，地铁到达方便，现场人流量适中。这次玩了2天，人均花费约717元，氛围感不错。景点印象：吞力屯地处那坡县北部的石山区，属城厢镇龙华村所管辖，全屯共57户250多人，为壮族支系“黑衣壮”的聚居地之一。由于居住条件恶劣，交通不便，信息闭塞，2002年以前该屯年人均纯收入仅900元，属城厢镇典型的特困屯之一。 时光荏苒，斗转星移，吞力…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '2%', 38);
