INSERT INTO `travel_review` VALUES (11535, 'TR011535', '哈达河', '鸡西', '黑龙江', '深度游', '夏季', 5, 3, 778.00, '是', 5, '5月去的哈达河，和朋友出行。地点在鸡西，公交换乘方便，现场游客较多。这次玩了3天，人均花费约778元，历史文化气息浓。景点印象：哈达河风景区分为8个景点，分别为卧驼峰、石崖湾、群峰山、平台山、阴阳鱼靶场、钓鱼和坝下服务区。哈达和湖面宽阔，两艘游艇，供游人观赏湖面和周围景点，景区内人文景观，建筑风格独特，以贴近自然为主，湖湾，山峦，潭水，曲径古朴协调，称为景…整体感受是超出预期，以后还会来。二刷意愿：是。', '5%', 55);
