INSERT INTO `travel_review` VALUES (11552, 'TR011552', '洪崖洞民俗风貌区', '重庆', '重庆', '周末短途', '冬季', 9, 4, 1269.00, '否', 2, '9月去的洪崖洞民俗风貌区，和朋友出行。地点在重庆，公交换乘方便，现场高峰时段比较拥挤。这次玩了4天，人均花费约1269元，拍照很出片。景点印象：在具有巴渝特色的山地吊脚楼建筑群内，赏江景，品尝当地美食。整体感受是体验偏一般，可考虑其他景点。二刷意愿：否。', '60%', 23);
INSERT INTO `travel_review` VALUES (11553, 'TR011553', '天壶峰', '临沂', '山东', '亲子出游', '秋季', 7, 1, 434.00, '是', 5, '7月去的天壶峰，一个人出行。地点在临沂，打车比较省心，现场人流量适中。这次玩了1天，人均花费约434元，夜景表现很好。景点印象：传说蒙山上有座蟠桃园，是王母娘娘领着仙女亲手栽的。王母娘娘查看了许多名山大川，觉得蒙山有一种其它地方所没有的灵气和仙气、雨水足，气候适宜，就在这里种了七棵蟠桃树。每年三月初二，王母娘娘都派仙女到云蒙山摘蟠桃，然后开蟠桃大会，请各路…整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 77);
