INSERT INTO `travel_review` VALUES (11589, 'TR011589', '漳平市博物馆', '龙岩', '福建', '城市漫游', '冬季', 10, 3, 1092.00, '否', 3, '10月去的漳平市博物馆，一个人出行。地点在龙岩，公交换乘方便，现场游客较多。这次玩了3天，人均花费约1092元，夜景表现很好。景点印象：漳平市博物馆坐落在风景优美、环境幽静和具有历史文化象征意义的东山公园风景区内，馆内记录了漳平的悠久历史，文化底蕴深厚。整体感受是体验一般，避开高峰更好。二刷意愿：否。', '0%', 62);
