INSERT INTO `travel_review` VALUES (11606, 'TR011606', '中国内陆海拔零点', '吐鲁番', '新疆', '周末短途', '夏季', 4, 1, 231.00, '是', 5, '4月去的中国内陆海拔零点，和朋友出行。地点在吐鲁番，公交换乘方便，现场游客较多。这次玩了1天，人均花费约231元，夜景表现很好。景点印象：位于新疆吐鲁番亚尔乡巴村境内。地理坐标为东经89度11分。北纬42度56分，“零点”西至交河故城13公里，东至高昌故城50公里，北至苏公塔2公里，南至艾丁湖最低点30公里。“零点”属特殊地理位置。\n新疆吐鲁番盆地是中国最低的内陆盆地，也是世界第二…整体感受是超出预期，以后还会来。二刷意愿：是。', '1%', 56);
