INSERT INTO `travel_review` VALUES (11611, 'TR011611', '栈道', '广元', '四川', '拍照旅行', '冬季', 10, 2, 572.00, '是', 4, '10月去的栈道，和家人出行。地点在广元，公交换乘方便，现场人不算多。这次玩了2天，人均花费约572元，拍照很出片。景点印象：栈道之名，起时相当古老，《史记》上述：“栈道千里，通于蜀汉。”栈道的路线与石牛道路线相同，由于石牛道穿过狭谷地段多，为在狭谷中开辟道路，多在陡岩上架木成道。石牛道上的栈道，《宋会要辑稿?道路》说：北宋时，入川大路自凤州到剑门关直入…整体感受是整体不错，周末来刚好。二刷意愿：是。', '5%', 49);
