INSERT INTO `travel_review` VALUES (11646, 'TR011646', '蛇洞山', '齐齐哈尔', '黑龙江', '文化打卡', '春季', 12, 1, 651.00, '否', 2, '12月去的蛇洞山，情侣出行。地点在齐齐哈尔，自驾停车需要提前规划，现场人不算多。这次玩了1天，人均花费约651元，历史文化气息浓。景点印象：位于齐齐哈尔市碾子山区西部4.5公里，占地面积300公顷，最高峰龙峰海拔406米，是国家“AA”级风景区。景区划分为六个功能区，包括以蛇洞山为主的主景区、利用雅鲁河水面开辟水上游乐区、野营区、动植物观赏区、宗教区、服务区，将休闲、娱乐、观赏…整体感受是略失望，可考虑其他景点。二刷意愿：否。', '0%', 51);
