INSERT INTO `travel_review` VALUES (11656, 'TR011656', '青岛钓鱼吧海钓', '聊城', '山东', '周末短途', '冬季', 9, 2, 484.00, '是', 5, '9月去的青岛钓鱼吧海钓，和家人出行。地点在聊城，自驾停车需要提前规划，现场人流量适中。这次玩了2天，人均花费约484元，夜景表现很好。景点印象：在这里放松自己，回归自然，品一口青岛啤酒，甩一根鱼竿，与大海零距离接触，体验一下潜水的神秘带来的一场前所未有的海上尊贵旅途整体感受是特别满意，以后还会来。二刷意愿：是。', '0%', 105);
