INSERT INTO `travel_review` VALUES (11700, 'TR011700', '松鹤西湖滑雪狩猎场', '鹤岗', '黑龙江', '拍照旅行', '夏季', 3, 2, 694.00, '是', 5, '3月去的松鹤西湖滑雪狩猎场，和朋友出行。地点在鹤岗，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约694元，氛围感不错。景点印象：该场位于西郊松鹤西湖公园的笃斯山，山上有两条长800米的雪道和一个小动物狩猎场，山下湖中有冰上旅游项目，包括：滑冰、冰滑梯、冰上保龄球、狗拉雪撬等，是冬季溜冰滑雪的乐园。整体感受是超出预期，值得专门打卡。二刷意愿：是。', '0%', 53);
