INSERT INTO `travel_review` VALUES (11703, 'TR011703', '凌云塔', '孝感', '湖北', '拍照旅行', '夏季', 4, 2, 763.00, '否', 3, '4月去的凌云塔，情侣出行。地点在孝感，打车比较省心，现场高峰时段比较拥挤。这次玩了2天，人均花费约763元，氛围感不错。景点印象：在应城市区南3.5公里大富水故道东岸。清道光二十八年（1848年）兴建。初为3层，以“文峰象征”之意称文笔塔。同治十年（1871年）重修，取“高耸入云”之意，易为今名。七层六面，高30余米，砖石砌筑，楼阁式，门窗、柱枋、斗拱、檐角等多仿木结构，…整体感受是中规中矩，别抱太高期待。二刷意愿：否。', '0%', 42);
