INSERT INTO `travel_review` VALUES (11745, 'TR011745', '天坛山', '晋城', '山西', '拍照旅行', '秋季', 7, 3, 781.00, '否', 2, '7月去的天坛山，一个人出行。地点在晋城，打车比较省心，现场高峰时段比较拥挤。这次玩了3天，人均花费约781元，氛围感不错。景点印象：天坛山，又名阳洛山，位于市城区西北约31公里处，海拔1711米，为王屋山主峰。绝顶有坛。传为轩辕帝祈天之所，故名天坛；又因与东岳泰山鼎峙，谓之西顶，俗称老爷顶。天坛山高耸入云，独柱凌空。人们登上山顶，翘首太空，云霞眩目；远望黄河，细流如…整体感受是没达到预期，可考虑其他景点。二刷意愿：否。', '0%', 44);
