INSERT INTO `travel_review` VALUES (11758, 'TR011758', '南天门', '神农架', '湖北', '拍照旅行', '秋季', 6, 2, 806.00, '否', 5, '6月去的南天门，一个人出行。地点在神农架，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约806元，拍照很出片。景点印象：南天门海拔2602.7米，山势巍峨，山口雄壮，风景优美，人行其上，如登南天，是“野人”经常出没的地方，这里设有野考大本营。整体感受是特别满意，值得专门打卡。二刷意愿：否。', '1%', 100);
INSERT INTO `travel_review` VALUES (11759, 'TR011759', '呼图壁公园', '昌吉', '新疆', '深度游', '冬季', 11, 3, 821.00, '否', 5, '11月去的呼图壁公园，和家人出行。地点在昌吉，地铁到达方便，现场人流量适中。这次玩了3天，人均花费约821元，氛围感不错。景点印象：位于呼图壁县城东风路西端的呼图壁公园是镶嵌在县城内一颗灿烂的明珠,占地面积350亩。一九九四年开始筹建,二OOO年十月一日正式向游人开放,二OO四年被评定为国家A级旅游景区。新近修建的人工湖、芙蓉池、长廊亭榭、游泳池等，均蕴涵着江南水乡的特色…整体感受是超出预期，值得专门打卡。二刷意愿：否。', '0%', 93);
INSERT INTO `travel_review` VALUES (11760, 'TR011760', '九鲤湖风景区', '莆田', '福建', '深度游', '夏季', 4, 2, 787.00, '是', 5, '4月去的九鲤湖风景区，和朋友出行。地点在莆田，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约787元，拍照很出片。景点印象：看历史文化名湖，赏九鲤飞瀑天下奇景，湖光山色尽收眼底。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '23%', 97);
