INSERT INTO `travel_review` VALUES (11765, 'TR011765', '柏窳山', '吕梁', '山西', '周末短途', '秋季', 7, 5, 1598.00, '否', 4, '7月去的柏窳山，和家人出行。地点在吕梁，公交换乘方便，现场高峰时段比较拥挤。这次玩了5天，人均花费约1598元，氛围感不错。景点印象：位于中阳县城东五公里处，峰峦峭拔，松柏叠翠。山腰有金代创建的道教庙宇――龙泉观。庙堂依山而筑，布局严谨，结构精巧。庙中有清冽甘醇的“龙泉水”。相传农历三月十七为圣母生日，这里届时举办庙会，游人香客云集山巅，汲取龙泉圣水，观赏柏窳胜…整体感受是体验挺好，推荐来看看。二刷意愿：否。', '0%', 87);
