INSERT INTO `travel_review` VALUES (11774, 'TR011774', '花石浪遗址', '商洛', '陕西', '亲子出游', '春季', 12, 2, 558.00, '否', 4, '12月去的花石浪遗址，情侣出行。地点在商洛，打车比较省心，现场游客较多。这次玩了2天，人均花费约558元，夜景表现很好。景点印象：花石浪遗址位于陕西省洛南县城关镇东河村后花石浪山上，是两个相距约30米的旧石器时代洞穴，时代距今约50万年。\n这里发现早期人类牙齿化石，被命名为“洛南人牙齿化石”。南洞的发现尤为丰富，在20余平方米的洞室内及洞口附近，有多达3万件以上的石…整体感受是整体不错，推荐来看看。二刷意愿：否。', '0%', 37);
