INSERT INTO `travel_review` VALUES (11792, 'TR011792', '黄河古栈道', '三门峡', '河南', '周末短途', '春季', 2, 1, 471.00, '是', 5, '2月去的黄河古栈道，和家人出行。地点在三门峡，自驾停车需要提前规划，现场人不算多。这次玩了1天，人均花费约471元，氛围感不错。景点印象：黄河古栈道位于三门峡大坝下游北岸紧靠黄河的陡壁悬崖上，共有两条。一条离河面较高，一条离河面较低，都是紧挨着石壁的冲击处开凿的。\n从遗迹上可以看出，黄河古栈道是在紧靠三门峡谷的黄河两岸徒壁的河水冲击处开凿出一条狭窄的石路，再在路断处…整体感受是超出预期，以后还会来。二刷意愿：是。', '4%', 86);
INSERT INTO `travel_review` VALUES (11793, 'TR011793', '青海省博物馆', '西宁', '青海', '文化打卡', '夏季', 5, 3, 665.00, '否', 2, '5月去的青海省博物馆，一个人出行。地点在西宁，地铁到达方便，现场人不算多。这次玩了3天，人均花费约665元，历史文化气息浓。景点印象：系统了解青海历史、各民族文化、藏传佛教知识的绝佳选择。整体感受是略失望，可考虑其他景点。二刷意愿：否。', '5%', 92);
