INSERT INTO `travel_review` VALUES (11807, 'TR011807', '玉带滩', '琼海', '海南', '深度游', '春季', 12, 4, 1426.00, '否', 3, '12月去的玉带滩，和家人出行。地点在琼海，自驾停车需要提前规划，现场人不算多。这次玩了4天，人均花费约1426元，拍照很出片。景点印象：分隔海、河的天然沙滩半岛，景色独特，国内少有。整体感受是中规中矩，避开高峰更好。二刷意愿：否。', '50%', 80);
