INSERT INTO `travel_review` VALUES (11833, 'TR011833', '七仙岭温泉', '保亭', '海南', '城市漫游', '冬季', 10, 2, 80.00, '是', 5, '10月去的七仙岭温泉，一个人出行。地点在保亭，公交换乘方便，现场人流量适中。这次玩了2天，人均花费约80元，历史文化气息浓。景点印象：海南目前最大的温泉之一。区内气温适宜，空气清新，环境幽静。整体感受是特别满意，以后还会来。二刷意愿：是。', '4%', 114);
