INSERT INTO `travel_review` VALUES (11853, 'TR011853', '延安国家森林公园', '延安', '陕西', '文化打卡', '夏季', 3, 3, 764.00, '是', 4, '3月去的延安国家森林公园，情侣出行。地点在延安，地铁到达方便，现场人不算多。这次玩了3天，人均花费约764元，氛围感不错。景点印象：国家惟一的城郊生态型森林公园，是以森林景观为主导，融自然景观、人文景观与黄土风情为一体，是进行革命传统教育，游览观光，避暑度假等多种旅游活动场所。整体感受是体验挺好，可以安排半天到一天。二刷意愿：是。', '0%', 69);
