INSERT INTO `travel_review` VALUES (11900, 'TR011900', '高椅岭旅游区', '郴州', '湖南', '拍照旅行', '春季', 1, 1, 442.00, '是', 5, '1月去的高椅岭旅游区，情侣出行。地点在郴州，自驾停车需要提前规划，现场人不算多。这次玩了1天，人均花费约442元，拍照很出片。景点印象：高椅岭风景区是一处罕见的丹霞地貌处女地，景区树石相间、红岩绿水、险寨奇涧，构成一幅幅美丽的山水画卷，是一处不可多得的丹霞地貌奇观。整体感受是超出预期，很推荐。二刷意愿：是。', '35%', 64);
