INSERT INTO `travel_review` VALUES (11914, 'TR011914', '湖心岛', '岳阳', '湖南', '城市漫游', '秋季', 7, 6, 1560.00, '是', 5, '7月去的湖心岛，情侣出行。地点在岳阳，自驾停车需要提前规划，现场人不算多。这次玩了6天，人均花费约1560元，拍照很出片。景点印象：位于龙源水库中央，岛上险峰怪石，弥不胜举，奇花异草，目不暇接；四围青山环抱，水波涟涟。远远望去，恰如白银盘里一青螺。整体感受是超出预期，值得专门打卡。二刷意愿：是。', '2%', 43);
