INSERT INTO `travel_review` VALUES (11917, 'TR011917', '郎德苗寨', '黔东南', '贵州', '城市漫游', '秋季', 7, 5, 1152.00, '否', 4, '7月去的郎德苗寨，和朋友出行。地点在黔东南，公交换乘方便，现场游客较多。这次玩了5天，人均花费约1152元，夜景表现很好。景点印象：这里依山傍水，四面被群山环抱，没有被过度开发，适合向往清净的朋友。整体感受是体验挺好，周末来刚好。二刷意愿：否。', '7%', 101);
