INSERT INTO `travel_review` VALUES (11919, 'TR011919', '关帝山', '吕梁', '山西', '城市漫游', '秋季', 6, 3, 577.00, '是', 5, '6月去的关帝山，和家人出行。地点在吕梁，地铁到达方便，现场游客较多。这次玩了3天，人均花费约577元，夜景表现很好。景点印象：在山西省吕梁山中段地跨交城、方山两县之间，有一个蕴藏着丰富动植物资源的天然宝库，这就是距太原市150公里的关帝山（又称宫帝山、南阳山、三层崖）国家森林公园。该公园设在庞泉沟国家级自然保护区内，1992年9月经林业部批准建立，面积78万亩。整体感受是特别满意，以后还会来。二刷意愿：是。', '0%', 86);
INSERT INTO `travel_review` VALUES (11920, 'TR011920', '泸山', '凉山', '四川', '深度游', '春季', 12, 3, 965.00, '是', 5, '12月去的泸山，和朋友出行。地点在凉山，地铁到达方便，现场人不算多。这次玩了3天，人均花费约965元，拍照很出片。景点印象：拔地而起的泸山，以“半壁撑霄汉，宁城列画屏”的气势与邛海构成川西南一大景区之一。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '6%', 118);
