INSERT INTO `travel_review` VALUES (11949, 'TR011949', '仰天湖大草原', '郴州', '湖南', '深度游', '秋季', 6, 4, 951.00, '是', 5, '6月去的仰天湖大草原，和朋友出行。地点在郴州，打车比较省心，现场人流量适中。这次玩了4天，人均花费约951元，历史文化气息浓。景点印象：仰天湖，又称仰天湖大草原，是在苔质台地草原腹地中镶嵌着一汪碧绿的水泊，景区内不仅囊括了高原旷野上的草原湿地景观，也有千姿百态、鬼斧神工的安源石林和平头山寨，还涵盖有十里杜鹃、雾海重田、高山观日、晴雪云耕、通天洞峡、滴水岱瀑等十大景…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '5%', 85);
