INSERT INTO `travel_review` VALUES (11959, 'TR011959', '哈斯哈吉甫陵墓', '喀什', '新疆', '城市漫游', '冬季', 9, 3, 656.00, '是', 5, '9月去的哈斯哈吉甫陵墓，情侣出行。地点在喀什，公交换乘方便，现场人不算多。这次玩了3天，人均花费约656元，夜景表现很好。景点印象：玉素甫·哈斯哈吉甫是维吾尔族伟大的思想家，他于公元1069年-1070年间，以当时的维吾尔文完成了13290行的长诗《福乐智慧》。\n玉素甫·哈斯哈吉甫墓，座落在喀什市体育路十二小学院内，占地965平方米。玉素甫.哈斯哈吉甫墓是一组富于维吾尔传统建筑…整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '3%', 86);
