INSERT INTO `travel_review` VALUES (11967, 'TR011967', '乌兰夫纪念馆', '呼和浩特', '内蒙古', '深度游', '冬季', 10, 1, 544.00, '否', 4, '10月去的乌兰夫纪念馆，和家人出行。地点在呼和浩特，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约544元，历史文化气息浓。景点印象：追寻乌兰夫的昔日足迹，了解前辈们投身革命、艰苦奋斗的历史。整体感受是还蛮满意，可以安排半天到一天。二刷意愿：否。', '0%', 59);
