INSERT INTO `travel_review` VALUES (11985, 'TR011985', '三绝碑', '漯河', '河南', '拍照旅行', '秋季', 7, 2, 342.00, '否', 2, '7月去的三绝碑，情侣出行。地点在漯河，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了2天，人均花费约342元，氛围感不错。景点印象：三绝碑即《受禅表》碑和《公卿将军上尊号奏》碑，位于许昌市西南17公里处的繁城镇汉献帝庙内。《受禅表》碑，高3.22米，宽1.02米，厚0.28米，圭形，上有碑穿额题篆书阳文“受禅表”三字。碑文22行，每行49字，字1寸2分，隶书阴镌，内容首先阐明禅让…整体感受是没达到预期，不建议高峰来。二刷意愿：否。', '7%', 66);
