INSERT INTO `travel_review` VALUES (12014, 'TR012014', '应县木塔', '朔州', '山西', '拍照旅行', '春季', 1, 4, 894.00, '否', 5, '1月去的应县木塔，和朋友出行。地点在朔州，打车比较省心，现场人流量适中。这次玩了4天，人均花费约894元，拍照很出片。景点印象：稀有的辽代古建筑，是我国现存最高最古老的木塔，建筑中没有用一根铁钉。 在第一层内，有高达11米的释迦摩尼佛像，还有色彩鲜艳的壁画。 塔上有明代两位皇帝亲自题写的匾额：“峻极神功”和“天下奇观”。整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '91%', 105);
