INSERT INTO `travel_review` VALUES (12019, 'TR012019', '宝日陶勒盖鸣沙山', '阿拉善盟', '内蒙古', '文化打卡', '春季', 1, 1, 514.00, '否', 4, '1月去的宝日陶勒盖鸣沙山，和朋友出行。地点在阿拉善盟，自驾停车需要提前规划，现场人不算多。这次玩了1天，人均花费约514元，历史文化气息浓。景点印象：宝日陶勒盖鸣沙山，高达二百多米，峰峦陡峭，沙脊如刃，高低错落。整体感受是还蛮满意，推荐来看看。二刷意愿：否。', '0%', 96);
