INSERT INTO `travel_review` VALUES (12034, 'TR012034', '多宝佛塔话珍奇', '襄阳', '湖北', '深度游', '夏季', 4, 1, 760.00, '是', 5, '4月去的多宝佛塔话珍奇，情侣出行。地点在襄阳，打车比较省心，现场人流量适中。这次玩了1天，人均花费约760元，夜景表现很好。景点印象：距隆中一箭之遥，有一座寺庙，叫广德寺。它离山不远，在一片空旷的田野上。南望，是巍巍清山，北眺，是滔滔汉水。寺院方方正正，四外有整整齐齐的护寺河，除东山门外，别处进不了寺院。这恐怕是其它很多寺院所没有的。此寺以刹深殿高而著称于世，更…整体感受是特别满意，很推荐。二刷意愿：是。', '22%', 109);
