INSERT INTO `travel_review` VALUES (12041, 'TR012041', '庙后山古人类遗址', '本溪', '辽宁', '文化打卡', '春季', 2, 6, 1165.00, '是', 5, '2月去的庙后山古人类遗址，一个人出行。地点在本溪，地铁到达方便，现场高峰时段比较拥挤。这次玩了6天，人均花费约1165元，氛围感不错。景点印象：庙后山位于本溪满族自治县山城子村东，距本溪水洞15公里，也是游关门山和汤沟温泉的必经之地。这座古人类遗址，自1978年发现，至1982年，国家、省和市考古工作者在这里先后进行了四次重点发掘。出土了大量古生物化石、石器和用火痕迹。考古学家认为…整体感受是超出预期，值得专门打卡。二刷意愿：是。', '0%', 62);
INSERT INTO `travel_review` VALUES (12042, 'TR012042', '花台景区-观景台', '池州', '安徽', '周末短途', '冬季', 11, 3, 1318.00, '否', 5, '11月去的花台景区-观景台，和朋友出行。地点在池州，地铁到达方便，现场人流量适中。这次玩了3天，人均花费约1318元，拍照很出片。景点印象：花台景区自然景观原始、清净，终年嘉木葱茏，泉水叮咚，享有九华最美的景区之称。整体感受是特别满意，以后还会来。二刷意愿：否。', '6%', 70);
