INSERT INTO `travel_review` VALUES (12044, 'TR012044', '梦幻锦江', '铜仁', '贵州', '周末短途', '秋季', 8, 4, 1097.00, '是', 4, '8月去的梦幻锦江，和朋友出行。地点在铜仁，自驾停车需要提前规划，现场人不算多。这次玩了4天，人均花费约1097元，历史文化气息浓。景点印象：“梦幻锦江”依托三江公园，把锦江两岸自然景观和人文景观用现代灯光先进技术与艺术手段巧妙融合，突出景观特色，集休闲、娱乐、游览等功能为一体。以清新、优美的自然风光与文化景观创造出梦幻般的意境。整体感受是体验挺好，可以安排半天到一天。二刷意愿：是。', '2%', 53);
