INSERT INTO `travel_review` VALUES (12046, 'TR012046', '合肥市科技馆(蜀西湖馆区)', '合肥', '安徽', '拍照旅行', '夏季', 5, 2, 944.00, '否', 3, '5月去的合肥市科技馆(蜀西湖馆区)，情侣出行。地点在合肥，公交换乘方便，现场游客较多。这次玩了2天，人均花费约944元，历史文化气息浓。景点印象：整体环境还算干净整体感受是中规中矩，别抱太高期待。二刷意愿：否。', '0%', 67);
INSERT INTO `travel_review` VALUES (12047, 'TR012047', '伏曦太昊陵', '周口', '河南', '城市漫游', '秋季', 7, 2, 495.00, '否', 5, '7月去的伏曦太昊陵，和家人出行。地点在周口，公交换乘方便，现场人不算多。这次玩了2天，人均花费约495元，历史文化气息浓。景点印象：太昊伏羲是我国远古神话传说中的一个圣明帝王，他“为百王先”，居三皇之一，列五帝之首。他在人类社会从母系向父系，由野蛮向文明进化时期，以自已的聪明和智慧，立下了齐天功绩。后人因此称他为“始祖”、“斯文鼻祖”。“太昊”即是人们对伏羲的…整体感受是挺惊喜，以后还会来。二刷意愿：否。', '50%', 68);
