INSERT INTO `travel_review` VALUES (12078, 'TR012078', '中华水浒城', '咸宁', '湖北', '拍照旅行', '冬季', 10, 3, 489.00, '否', 5, '10月去的中华水浒城，情侣出行。地点在咸宁，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了3天，人均花费约489元，历史文化气息浓。景点印象：中华水浒城,陆水湖中的中华水浒城,是中央电视台为摄制大型电视巨片《水浒传》而兴建的3个外景拍摄基地之一(另两个为江苏无锡及广西合浦)。中华水浒城现已成为传播中华传统文化、集山林、湖、岛野趣、风景优美的多功能旅游区。“郊野一条街”由大小…整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '0%', 105);
