INSERT INTO `travel_review` VALUES (12099, 'TR012099', '马过河景区', '曲靖', '云南', '深度游', '冬季', 10, 5, 1123.00, '是', 5, '10月去的马过河景区，和家人出行。地点在曲靖，自驾停车需要提前规划，现场人不算多。这次玩了5天，人均花费约1123元，氛围感不错。景点印象：马龙县马过河风景名胜区地处滇中高原马龙县境内，由马过河、万亩草场、香炉山三个片区组成，共有37个景点，景区面积28平方公里。马过河风景名胜区以溪流平湖、陡壁峭岩、瀑布、跌水为特色，森林植被保存了滇中地区原生植被和生态景观，景区溪水、瀑…整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 73);
