INSERT INTO `travel_review` VALUES (12123, 'TR012123', '锡林郭勒草原', '锡林郭勒盟', '内蒙古', '深度游', '秋季', 8, 7, 1645.00, '是', 5, '8月去的锡林郭勒草原，一个人出行。地点在锡林郭勒盟，地铁到达方便，现场高峰时段比较拥挤。这次玩了7天，人均花费约1645元，氛围感不错。景点印象：草原旅游资源丰富、以草原类型完整而著称于世，片片白云在无尽的蓝天中飘游，牧人策马，牛羊游动，美不胜收。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '26%', 70);
INSERT INTO `travel_review` VALUES (12124, 'TR012124', '九龙谷景区', '莆田', '福建', '城市漫游', '夏季', 4, 5, 1044.00, '否', 5, '4月去的九龙谷景区，情侣出行。地点在莆田，地铁到达方便，现场游客较多。这次玩了5天，人均花费约1044元，夜景表现很好。景点印象：看各类珍稀动植物，呼吸森林氧吧的纯正氧气，最后记得要和小鹿来次亲密接触哦！整体感受是特别满意，以后还会来。二刷意愿：否。', '5%', 73);
