INSERT INTO `travel_review` VALUES (12127, 'TR012127', '谷林尧陵', '菏泽', '山东', '周末短途', '夏季', 4, 2, 844.00, '是', 4, '4月去的谷林尧陵，和朋友出行。地点在菏泽，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约844元，夜景表现很好。景点印象：尧陵又称尧王墓，乃帝尧所葬之处，《吕氏春秋》云：“尧葬谷林”，其址在距鄄城县城7公里的富春乡谷林，故名“谷林尧陵”。\n尧，姓伊祁，名放勋，号陶唐氏，系轩辕黄帝五世孙，父帝喾，母庆都。司马迁列之为五帝之一。尧以钦明文思四德安其民，亲睦…整体感受是整体不错，周末来刚好。二刷意愿：是。', '0%', 48);
