INSERT INTO `travel_review` VALUES (12176, 'TR012176', '东江湖旅游区', '郴州', '湖南', '拍照旅行', '秋季', 8, 3, 1090.00, '否', 3, '8月去的东江湖旅游区，和朋友出行。地点在郴州，地铁到达方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约1090元，氛围感不错。景点印象：东江湖风景旅游区，位于资兴市东江镇境内，景区包含了雾漫小东江、龙景峡谷等多个景区以及大量水上娱乐项目，是郴州必玩景区之一。整体感受是体验一般，别抱太高期待。二刷意愿：否。', '40%', 28);
INSERT INTO `travel_review` VALUES (12177, 'TR012177', '宏村景区', '黄山', '安徽', '亲子出游', '秋季', 8, 1, 613.00, '否', 5, '8月去的宏村景区，和家人出行。地点在黄山，自驾停车需要提前规划，现场游客较多。这次玩了1天，人均花费约613元，拍照很出片。景点印象：徽派古村中的代表，可拍摄南湖、月沼美景，欣赏精致的徽派三雕。整体感受是特别满意，值得专门打卡。二刷意愿：否。', '48%', 50);
INSERT INTO `travel_review` VALUES (12178, 'TR012178', '罗丛岩', '贵港', '广西', '周末短途', '秋季', 7, 1, 302.00, '是', 5, '7月去的罗丛岩，情侣出行。地点在贵港，打车比较省心，现场人不算多。这次玩了1天，人均花费约302元，历史文化气息浓。景点印象：罗丛岩座落于方圆五六公里的平原上，平地崛起石山9座，当中一座高70米，长350米，宽80米，座北朝南，状若履舟，被誉为道家七十二福地之一的“天南福地”——“罗丛岩月”是桂平八景之一。\n罗丛岩内溶洞遍布，岩道通透，奇形怪状的钟乳石分布其间，…整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 118);
