INSERT INTO `travel_review` VALUES (12253, 'TR012253', '狮子岩', '常德', '湖南', '亲子出游', '秋季', 6, 4, 942.00, '是', 5, '6月去的狮子岩，一个人出行。地点在常德，打车比较省心，现场人不算多。这次玩了4天，人均花费约942元，夜景表现很好。景点印象：位于景区南端虎形山东侧的轿顶山，是花岩溪景区的一大奇观。一道岩墙，兀立山腰，形状如狮，因此得名。跃狮子英武、剽悍，昂首北望，雄视蓝天。狮身高5.3米,长19米,宽1―2米，尾巴是一块十多吨重的长方条石，斜倚狮身的背部。观赏狮子岩，常令人遐…整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 77);
