INSERT INTO `travel_review` VALUES (12268, 'TR012268', '诸葛八卦村', '金华', '浙江', '周末短途', '春季', 1, 1, 442.00, '否', 5, '1月去的诸葛八卦村，和家人出行。地点在金华，公交换乘方便，现场游客较多。这次玩了1天，人均花费约442元，历史文化气息浓。景点印象：诸葛亮后裔最大的聚居地，是个古朴而宁静的古村。村里保留了大量按九宫八卦布局的徽派老建筑，十分独特。\n丞相祠堂、大公堂尤值得一看，参观其中的展览感受诸葛氏族的文化底蕴。整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '8%', 79);
