INSERT INTO `travel_review` VALUES (12271, 'TR012271', '拉姆央措湖', '迪庆', '云南', '拍照旅行', '冬季', 9, 2, 751.00, '否', 5, '9月去的拉姆央措湖，和朋友出行。地点在迪庆，打车比较省心，现场人流量适中。这次玩了2天，人均花费约751元，拍照很出片。景点印象：湖中四季有各种水鸟生息，站在扎仓大殿顶上观望拉姆央措湖，它是一个佛自然的投影。整体感受是特别满意，以后还会来。二刷意愿：否。', '1%', 80);
