INSERT INTO `travel_review` VALUES (12276, 'TR012276', '朱家角古镇景区', '上海', '上海', '深度游', '冬季', 9, 1, 454.00, '是', 5, '9月去的朱家角古镇景区，一个人出行。地点在上海，自驾停车需要提前规划，现场游客较多。这次玩了1天，人均花费约454元，夜景表现很好。景点印象：上海周边游览古镇的首选之地，在青砖白墙间感受水乡的静谧。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '2%', 80);
INSERT INTO `travel_review` VALUES (12277, 'TR012277', '山东博物馆', '济南', '山东', '拍照旅行', '冬季', 9, 1, 514.00, '否', 2, '9月去的山东博物馆，和朋友出行。地点在济南，自驾停车需要提前规划，现场人流量适中。这次玩了1天，人均花费约514元，历史文化气息浓。景点印象：古代文物数量大、种类多，可全面了解山东历史文化。 山东地区出土的大量新石器时代文物是馆藏特色。整体感受是略失望，不建议高峰来。二刷意愿：否。', '7%', 83);
INSERT INTO `travel_review` VALUES (12278, 'TR012278', '舍利塔', '济源', '河南', '文化打卡', '春季', 2, 3, 758.00, '否', 4, '2月去的舍利塔，情侣出行。地点在济源，地铁到达方便，现场人不算多。这次玩了3天，人均花费约758元，氛围感不错。景点印象：延庆寺舍利塔位于市城区西北延庆寺内。因塔下埋舍利佛珠，故名。亦称龙潭寺塔。宋景右元年（公元1034年），济源县通慧禅院比丘法言提供舍利佛珠数十粒，与济源县延庆寺主持省初步共同创建。\n塔门南向，高28.16米，为七层密檐式六棱砖塔。塔檐由简…整体感受是体验挺好，周末来刚好。二刷意愿：否。', '0%', 94);
INSERT INTO `travel_review` VALUES (12279, 'TR012279', '红谷滩新区', '南昌', '江西', '城市漫游', '夏季', 3, 1, 470.00, '否', 5, '3月去的红谷滩新区，一个人出行。地点在南昌，打车比较省心，现场人不算多。这次玩了1天，人均花费约470元，历史文化气息浓。景点印象：红谷滩，古称“鸿鹄滩”，地处南昌赣江之北，与南昌南部的主要城区隔江相望。在中部崛起的大潮中，为拓展城市规模，加速城市化进程，加快“一江两岸”城市格局的形成。整体感受是特别满意，以后还会来。二刷意愿：否。', '0%', 89);
