INSERT INTO `travel_review` VALUES (12292, 'TR012292', '大洪山绿林寨', '荆门', '湖北', '城市漫游', '秋季', 7, 1, 263.00, '是', 5, '7月去的大洪山绿林寨，和家人出行。地点在荆门，公交换乘方便，现场人流量适中。这次玩了1天，人均花费约263元，氛围感不错。景点印象：是国务院1988年同张家界、九寨沟等景区同批次批准的国家级风景区。绿林寨是西汉末年王匡王凤绿林起义的策源地，也是汉光武帝刘秀的发祥地，极具历史人文内涵。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '6%', 81);
INSERT INTO `travel_review` VALUES (12293, 'TR012293', '赤水丹霞旅游区·大瀑布', '遵义', '贵州', '城市漫游', '冬季', 10, 2, 1021.00, '是', 4, '10月去的赤水丹霞旅游区·大瀑布，情侣出行。地点在遵义，打车比较省心，现场人流量适中。这次玩了2天，人均花费约1021元，夜景表现很好。景点印象：景区内的赤水大瀑布是我国丹霞地貌上最大的瀑布。整体感受是体验挺好，可以安排半天到一天。二刷意愿：是。', '9%', 61);
