INSERT INTO `travel_review` VALUES (12295, 'TR012295', '汀州府城隍庙', '龙岩', '福建', '深度游', '春季', 12, 6, 1498.00, '是', 5, '12月去的汀州府城隍庙，一个人出行。地点在龙岩，自驾停车需要提前规划，现场游客较多。这次玩了6天，人均花费约1498元，氛围感不错。景点印象：汀州城隍庙位于福建省长汀县（城关）汀州镇兆征路。城隍是汉民族宗教文化中普遍崇祀的重要神祇，大多由有功于地方民众的名臣英雄充当，是汉族民间和道教信奉 守护城池之神。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '0%', 44);
