INSERT INTO `travel_review` VALUES (12300, 'TR012300', '李时珍纪念馆', '黄冈', '湖北', '文化打卡', '秋季', 7, 1, 296.00, '否', 4, '7月去的李时珍纪念馆，情侣出行。地点在黄冈，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约296元，拍照很出片。景点印象：李时珍（1518-1593），是我国明代著名的医学家、药物学家，为纪念对人类作出伟大贡献的这位科学巨人，在湖北省蕲春县蕲州镇李时珍墓所在地竹林湖村建立了李时珍纪念馆。整个纪念馆占地面积50000平方米，由本草碑廊、纪念展览、药物馆、百草药园、墓…整体感受是整体不错，可以安排半天到一天。二刷意愿：否。', '0%', 66);
