INSERT INTO `travel_review` VALUES (12324, 'TR012324', '古谯楼', '莆田', '福建', '亲子出游', '冬季', 11, 3, 854.00, '是', 5, '11月去的古谯楼，和朋友出行。地点在莆田，地铁到达方便，现场人不算多。这次玩了3天，人均花费约854元，历史文化气息浓。景点印象：座落在市区中心文献路。北宋太平兴国八年（公元983 年）兴化军治所迁移莆田时设置的子城城门和门楼。绍兴六年（1136年）因火灾焚毁，知军刘登重建，并置更鼓刻漏于其上，故称鼓楼。后几经毁建。现建筑物是清康熙三十六年（1697年）重建、嘉庆八年（…整体感受是超出预期，以后还会来。二刷意愿：是。', '3%', 44);
