INSERT INTO `travel_review` VALUES (12351, 'TR012351', '神农溪纤夫文化走廊', '恩施', '湖北', '文化打卡', '春季', 1, 4, 1143.00, '是', 5, '1月去的神农溪纤夫文化走廊，和朋友出行。地点在恩施，公交换乘方便，现场高峰时段比较拥挤。这次玩了4天，人均花费约1143元，历史文化气息浓。景点印象：乘坐游船，畅游在溪流中，两岸满目苍翠，悬崖峭壁上还有古老神秘的悬棺。 能够欣赏到当地的民族表演，还有船工们的三峡纤夫拉纤表演。整体感受是超出预期，值得专门打卡。二刷意愿：是。', '11%', 81);
INSERT INTO `travel_review` VALUES (12352, 'TR012352', '豫园', '上海', '上海', '城市漫游', '夏季', 3, 1, 484.00, '是', 4, '3月去的豫园，和家人出行。地点在上海，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约484元，拍照很出片。景点印象：市区留存完好的江南古典园林，亭台楼阁雕梁画栋。整体感受是整体不错，可以安排半天到一天。二刷意愿：是。', '33%', 73);
