INSERT INTO `travel_review` VALUES (12356, 'TR012356', '康益泉温泉', '廊坊', '河北', '城市漫游', '春季', 1, 7, 1522.00, '是', 5, '1月去的康益泉温泉，情侣出行。地点在廊坊，自驾停车需要提前规划，现场游客较多。这次玩了7天，人均花费约1522元，拍照很出片。景点印象：位于固安县牛驼镇南，106国道西侧，距北京70公里。独特的大型露天温泉浴池，水性温热而富含多种元素，浴之可温经通络、畅达气血，祛寒舒筋，消除疲劳，强身健体，疗效独特，常浴可使肌肤润滑光亮。室外桑拿室、康乐中心等设施相配套，能使步入康益…整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '50%', 55);
