INSERT INTO `travel_review` VALUES (12366, 'TR012366', '建水文庙', '红河', '云南', '周末短途', '春季', 2, 3, 1057.00, '否', 2, '2月去的建水文庙，和朋友出行。地点在红河，公交换乘方便，现场人流量适中。这次玩了3天，人均花费约1057元，拍照很出片。景点印象：文庙占地宽广规模宏大，内部建筑精美绝伦，是古代建筑艺术的宝库。 每年9月28日的祭孔大典宏达庄严，堪称一场视觉和古典礼仪的盛宴。整体感受是没达到预期，建议谨慎前往。二刷意愿：否。', '10%', 86);
INSERT INTO `travel_review` VALUES (12367, 'TR012367', '东莞龙凤山庄影视度假村', '东莞', '广东', '亲子出游', '春季', 1, 3, 494.00, '是', 5, '1月去的东莞龙凤山庄影视度假村，和家人出行。地点在东莞，打车比较省心，现场高峰时段比较拥挤。这次玩了3天，人均花费约494元，夜景表现很好。景点印象：龙凤山庄气候宜人、全年无霜，加上纯天然的山林地貌，环境幽雅、空气清新、上百种珍稀植物，高达百分之七十五的绿色覆盖，是闹市中的世外桃源，钢铁森林里的天然氧吧。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '2%', 104);
