INSERT INTO `travel_review` VALUES (12441, 'TR012441', '陆将军府', '亳州', '安徽', '城市漫游', '春季', 1, 1, 337.00, '是', 4, '1月去的陆将军府，和家人出行。地点在亳州，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约337元，拍照很出片。景点印象：陆将军府又名陆瓦房，是蒙城人陆建章任陕西督军时建造的府第，现为蒙城县重点文物保护单位。\n府第面阔七间，东西长27.3米，南北长60米。中厅、东、西厢房及后马房于1938年被日军焚毁，现仅存前房和后厅共14间，均为砖木结构。大门两旁各立一块上马…整体感受是整体不错，推荐来看看。二刷意愿：是。', '0%', 73);
