INSERT INTO `travel_review` VALUES (12497, 'TR012497', '梨树沟开发实验基地', '齐齐哈尔', '黑龙江', '拍照旅行', '秋季', 6, 3, 1128.00, '是', 5, '6月去的梨树沟开发实验基地，一个人出行。地点在齐齐哈尔，自驾停车需要提前规划，现场人流量适中。这次玩了3天，人均花费约1128元，历史文化气息浓。景点印象：是省园艺所1992年进行规划设计，1994年确定为黑龙江省西部地区梨树开发实验基地。经过多年的扩大种植，现在梨树沟已栽植各种果树近万亩，品种包括梨、苹果、沙果、李子、杏、葡萄等近30品种，年产各种果品150万公斤，除供应本地区市民外，还远销周…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 92);
