INSERT INTO `travel_review` VALUES (12500, 'TR012500', '当穹错', '那曲', '西藏', '文化打卡', '冬季', 11, 1, 703.00, '是', 5, '11月去的当穹错，和朋友出行。地点在那曲，公交换乘方便，现场人不算多。这次玩了1天，人均花费约703元，拍照很出片。景点印象：当穹错也作当雄错、当穷错，位于那曲地区尼玛县境内，是一片高原咸水湖，湖泊西部有一座高出湖面约48米、面积0.4平方公里的小岛。整体感受是超出预期，以后还会来。二刷意愿：是。', '2%', 62);
