INSERT INTO `travel_review` VALUES (12504, 'TR012504', '钟灵禅寺', '齐齐哈尔', '黑龙江', '拍照旅行', '春季', 1, 1, 856.00, '否', 5, '1月去的钟灵禅寺，情侣出行。地点在齐齐哈尔，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约856元，历史文化气息浓。景点印象：钟灵禅寺始建于1911年，位于齐齐哈尔境内，克东县昌盛乡。原名钟灵观，因缺乏道教神职人员，故改名为钟灵寺，现为佛事活动场所。\n整个庙宇建在绿荫之中，内有主殿1幢，大殿2重，配阁4座，占地6,000平方米，建筑面积600平方米，均为砖木结构，墙面…整体感受是特别满意，以后还会来。二刷意愿：否。', '0%', 64);
