INSERT INTO `travel_review` VALUES (12538, 'TR012538', '高坊水库', '抚州', '江西', '周末短途', '春季', 12, 1, 743.00, '是', 5, '12月去的高坊水库，和家人出行。地点在抚州，地铁到达方便，现场人不算多。这次玩了1天，人均花费约743元，夜景表现很好。景点印象：座落在陆坊乡高坊村，建于黄通港上，集雨面积102平方公里，年平均流量为每秒3.8立方米。1958年动工兴建，次年春大坝基本落成。1960年开始蓄水，配套工程1969年完工。为增加库容，扩大灌溉面积和解决县城用电，1990年动工扩建，加高堤坝5米，蓄水量…整体感受是超出预期，值得专门打卡。二刷意愿：是。', '0%', 80);
