INSERT INTO `travel_review` VALUES (12552, 'TR012552', '西大寺', '昌吉', '新疆', '拍照旅行', '冬季', 10, 4, 1157.00, '否', 5, '10月去的西大寺，情侣出行。地点在昌吉，地铁到达方便，现场人不算多。这次玩了4天，人均花费约1157元，夜景表现很好。景点印象：当地称为“西大寺”，座落在北庭故城以西约700米处，地面原为一高大土丘，1978－1981年发掘，发现为古佛寺。其建筑规模之大，造型艺术之精美，是迄今北疆同类遗址所仅见。现已被国务院定为国家重点文物保护单位。\n寺庙座北朝南，有正殿、东西配殿等…整体感受是超出预期，以后还会来。二刷意愿：否。', '1%', 103);
