INSERT INTO `travel_review` VALUES (12576, 'TR012576', '阿凡提民俗风情园', '吐鲁番', '新疆', '文化打卡', '秋季', 6, 4, 1369.00, '否', 5, '6月去的阿凡提民俗风情园，一个人出行。地点在吐鲁番，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了4天，人均花费约1369元，氛围感不错。景点印象：阿凡提风情园位于吐鲁番葡萄沟中部最能代表神奇自然景观特色的地段，距离吐鲁番市12公里，占地近30亩。是葡萄沟内最具有鲜明主题文化风格的游览胜地之一。园内杏树成林，桑树遮日，这里不仅有吐鲁番常见的景观景色，更有充满了浓郁维吾尔民间文化、…整体感受是特别满意，值得专门打卡。二刷意愿：否。', '0%', 69);
