INSERT INTO `travel_review` VALUES (12602, 'TR012602', '边靖楼', '忻州', '山西', '拍照旅行', '冬季', 9, 5, 1338.00, '否', 3, '9月去的边靖楼，一个人出行。地点在忻州，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了5天，人均花费约1338元，夜景表现很好。景点印象：亦名谯楼、鼓楼，在代县城中央，始建于明洪武七年（一三七四年），明成化7年（公元1471年）火焚，后成化十二年（一四七六年）重建，清康熙、雍正、嘉庆、道光年间均加修葺。一九五八年定为山西省重点文物保护单位。\n边靖楼外观雄伟、大方、古朴，…整体感受是中规中矩，按需选择。二刷意愿：否。', '2%', 53);
INSERT INTO `travel_review` VALUES (12603, 'TR012603', '沱江', '湘西', '湖南', '城市漫游', '春季', 12, 4, 1363.00, '否', 3, '12月去的沱江，和朋友出行。地点在湘西，自驾停车需要提前规划，现场游客较多。这次玩了4天，人均花费约1363元，拍照很出片。景点印象：在沱江上泛舟，两边是百年历史的苗家吊脚楼，沿途有跳岩、古城墙、虹桥等凤古城的标志性景点。 清晨的沱江边，雾气重重，当地居民咚咚咚的在江边捶洗衣物。 沱江畔的的吊脚楼内，是古城客栈和餐馆集中的地方。整体感受是中规中矩，避开高峰更好。二刷意愿：否。', '3%', 55);
