INSERT INTO `travel_review` VALUES (12634, 'TR012634', '湖田古窑遗址', '景德镇', '江西', '周末短途', '夏季', 5, 3, 698.00, '是', 5, '5月去的湖田古窑遗址，一个人出行。地点在景德镇，打车比较省心，现场高峰时段比较拥挤。这次玩了3天，人均花费约698元，夜景表现很好。景点印象：湖田窑是我国宋、元两代各大制瓷规模最大、延续烧造时间最长、生产的瓷器最精美的古代窑场。遗址保存的遗物非常丰富，历代古窑遍地。整体感受是超出预期，值得专门打卡。二刷意愿：是。', '10%', 72);
