INSERT INTO `travel_review` VALUES (12656, 'TR012656', '燕秦长城', '朝阳', '辽宁', '拍照旅行', '秋季', 8, 3, 1263.00, '否', 3, '8月去的燕秦长城，和家人出行。地点在朝阳，打车比较省心，现场人不算多。这次玩了3天，人均花费约1263元，氛围感不错。景点印象：在建平县北部努鲁儿虎山的崇山峻岭之中，断断续续地盘亘着一条被当地群众称为“石龙”或“土龙”的古代长城遗迹。经考证，这就是历史上著名的燕秦长城。\n战国时期，朝阳地区属于燕国的领地。当时，居住在东北的东胡族经常侵扰燕国，双方交战频繁。…整体感受是还可以，别抱太高期待。二刷意愿：否。', '0%', 68);
