INSERT INTO `travel_review` VALUES (12683, 'TR012683', '老鹰嘴', '呼伦贝尔', '内蒙古', '周末短途', '秋季', 7, 3, 856.00, '是', 4, '7月去的老鹰嘴，一个人出行。地点在呼伦贝尔，地铁到达方便，现场人流量适中。这次玩了3天，人均花费约856元，氛围感不错。景点印象：老鹰嘴位于额尔古纳市临江屯正北方7、8公里处，因为有一块岩石，状似老鹰的嘴而得名。这里草木葱茏，鸟语花香，宁静安逸；攀上山顶，还能远眺风景，是当地人都回去踏青赏秋的独特景点。整体感受是整体不错，推荐来看看。二刷意愿：是。', '14%', 61);
