INSERT INTO `travel_review` VALUES (12708, 'TR012708', '汉中市博物馆', '汉中', '陕西', '亲子出游', '夏季', 3, 2, 329.00, '是', 5, '3月去的汉中市博物馆，和朋友出行。地点在汉中，地铁到达方便，现场游客较多。这次玩了2天，人均花费约329元，历史文化气息浓。景点印象：当年的汉高祖刘邦的汉中王府，望江楼是汉中标志性的古建筑。整体感受是特别满意，很推荐。二刷意愿：是。', '22%', 60);
