INSERT INTO `travel_review` VALUES (12711, 'TR012711', '金沙滩墓群', '朔州', '山西', '深度游', '春季', 1, 1, 543.00, '是', 3, '1月去的金沙滩墓群，和家人出行。地点在朔州，打车比较省心，现场游客较多。这次玩了1天，人均花费约543元，夜景表现很好。景点印象：金沙滩墓群在怀仁县城南25公里的金沙滩镇第三作村南及尚南头村西一带。年代为汉代。大型封土的墓葬现存共16个，没有封土的墓葬比比皆是。\n配合基建施工曾发掘了7个大中型、30余个小型墓葬，大多数是汉代墓。大中型墓都是砖室墓，分为单室墓、多室…整体感受是中规中矩，避开高峰更好。二刷意愿：是。', '0%', 46);
