INSERT INTO `travel_review` VALUES (12717, 'TR012717', '李坑景区', '上饶', '江西', '深度游', '春季', 2, 5, 1296.00, '是', 4, '2月去的李坑景区，情侣出行。地点在上饶，打车比较省心，现场人不算多。这次玩了5天，人均花费约1296元，拍照很出片。景点印象：欣赏小桥流水人家的徽派景象，看南宋武状元李知诚的故居等精美建筑。整体感受是整体不错，推荐来看看。二刷意愿：是。', '33%', 64);
