INSERT INTO `travel_review` VALUES (12719, 'TR012719', '唐布拉风景区', '伊犁', '新疆', '深度游', '秋季', 7, 2, 193.00, '是', 5, '7月去的唐布拉风景区，一个人出行。地点在伊犁，打车比较省心，现场游客较多。这次玩了2天，人均花费约193元，历史文化气息浓。景点印象：唐布拉百里风景区有草原、温泉、雪峰、河流为主要特色，这里有芳草萋萋，流水滔滔，雪岭云杉相辉映，高山白云相依相伴，胜似人间仙景的唐布拉大草原；有一步一景，如诗如画。整体感受是超出预期，以后还会来。二刷意愿：是。', '5%', 104);
