INSERT INTO `travel_review` VALUES (12722, 'TR012722', '罗丛岩', '贵港', '广西', '文化打卡', '春季', 2, 3, 616.00, '是', 5, '2月去的罗丛岩，和家人出行。地点在贵港，地铁到达方便，现场游客较多。这次玩了3天，人均花费约616元，氛围感不错。景点印象：罗丛岩座落于方圆五六公里的平原上，平地崛起石山9座，当中一座高70米，长350米，宽80米，座北朝南，状若履舟，被誉为道家七十二福地之一的“天南福地”——“罗丛岩月”是桂平八景之一。\n罗丛岩内溶洞遍布，岩道通透，奇形怪状的钟乳石分布其间，…整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 77);
INSERT INTO `travel_review` VALUES (12723, 'TR012723', '兴凯湖国家级自然保护区', '鸡西', '黑龙江', '城市漫游', '夏季', 4, 3, 734.00, '是', 5, '4月去的兴凯湖国家级自然保护区，和家人出行。地点在鸡西，地铁到达方便，现场人不算多。这次玩了3天，人均花费约734元，拍照很出片。景点印象：周边配套比较齐全整体感受是特别满意，以后还会来。二刷意愿：是。', '0%', 94);
INSERT INTO `travel_review` VALUES (12724, 'TR012724', '富家桥异蛇村', '永州', '湖南', '亲子出游', '夏季', 3, 3, 866.00, '是', 4, '3月去的富家桥异蛇村，和家人出行。地点在永州，公交换乘方便，现场人流量适中。这次玩了3天，人均花费约866元，氛围感不错。景点印象：永州“异蛇”之可怕，世人皆知。早在公元854年，柳宗元笔下的《捕蛇者说》中就有记载，称它“触草木，尽死；以啮人，无御之者。”永州真的产这么一种剧毒无比的“异蛇”吗？带着疑惑，我们来到当地有名的“异蛇村”。\n其实，“异蛇村”并非一个行…整体感受是还蛮满意，周末来刚好。二刷意愿：是。', '0%', 76);
