INSERT INTO `travel_review` VALUES (12737, 'TR012737', '青海久治年保玉则国家地质公园', '果洛', '青海', '深度游', '夏季', 4, 5, 1667.00, '否', 3, '4月去的青海久治年保玉则国家地质公园，和家人出行。地点在果洛，打车比较省心，现场高峰时段比较拥挤。这次玩了5天，人均花费约1667元，夜景表现很好。景点印象：雪山、花海、湖泊景色绝美，是摄影家们热爱的天堂。 神山周围面积广大景色多样，是徒步爱好者心中的优质路线。整体感受是中规中矩，避开高峰更好。二刷意愿：否。', '74%', 8);
