INSERT INTO `travel_review` VALUES (12745, 'TR012745', '穹窿银城', '那曲', '西藏', '文化打卡', '春季', 1, 3, 952.00, '否', 4, '1月去的穹窿银城，一个人出行。地点在那曲，公交换乘方便，现场人流量适中。这次玩了3天，人均花费约952元，历史文化气息浓。景点印象：穹隆银城，也有的叫琼隆银堡，藏语为“琼隆威卡尔”，是西藏古象雄王国的都城，位于海拔4400米的卡尔东山顶，面积10余万平方米。整体感受是体验挺好，可以安排半天到一天。二刷意愿：否。', '0%', 78);
