INSERT INTO `travel_review` VALUES (12756, 'TR012756', '拦海大堤', '连云港', '江苏', '文化打卡', '春季', 2, 1, 559.00, '否', 4, '2月去的拦海大堤，和朋友出行。地点在连云港，公交换乘方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约559元，氛围感不错。景点印象：被人称为“海上长城”，通过大堤可由陆地直达连岛浴场和连岛海滨旅游度假区。整体感受是还蛮满意，推荐来看看。二刷意愿：否。', '3%', 49);
INSERT INTO `travel_review` VALUES (12757, 'TR012757', '白水洞', '邵阳', '湖南', '拍照旅行', '春季', 1, 1, 648.00, '是', 5, '1月去的白水洞，一个人出行。地点在邵阳，打车比较省心，现场人不算多。这次玩了1天，人均花费约648元，氛围感不错。景点印象：白水洞风景名胜区位于湘中新邵县境内，核心景区在严塘镇白水村。 早在明代， 白水洞就是湘中的旅游胜地，文人墨客纷来沓至， 多有赞咏。清人杨太灏著有《白水洞游记》、 李厚培著有《白水洞纪胜集》。白水洞风景名胜区于1999年经省人民政 府正式批…整体感受是特别满意，很推荐。二刷意愿：是。', '10%', 55);
