INSERT INTO `travel_review` VALUES (12762, 'TR012762', '雁南飞茶田景区', '梅州', '广东', '拍照旅行', '春季', 12, 3, 950.00, '是', 5, '12月去的雁南飞茶田景区，和家人出行。地点在梅州，公交换乘方便，现场人不算多。这次玩了3天，人均花费约950元，氛围感不错。景点印象：雁南飞茶田景区坐落于梅县雁洋镇，阴那山山麓之下，聚天地灵气，揽自然之优，是远离城市喧嚣，走进客家文化，静心享受慢生活的好去处。整体感受是特别满意，以后还会来。二刷意愿：是。', '30%', 76);
