INSERT INTO `travel_review` VALUES (12769, 'TR012769', '甘肃尕海则岔自然保护区-尕海湖', '甘南', '甘肃', '周末短途', '春季', 1, 4, 1108.00, '是', 5, '1月去的甘肃尕海则岔自然保护区-尕海湖，一个人出行。地点在甘南，打车比较省心，现场游客较多。这次玩了4天，人均花费约1108元，历史文化气息浓。景点印象：观看草原中心的海子，晴天时蓝天白云倒影湖中十分美丽。 七八月份湖边野花遍地，是摄影的绝妙之地！整体感受是特别满意，值得专门打卡。二刷意愿：是。', '35%', 98);
INSERT INTO `travel_review` VALUES (12770, 'TR012770', '塔敏查干沙漠旅游景区', '通辽', '内蒙古', '周末短途', '冬季', 10, 4, 1066.00, '是', 5, '10月去的塔敏查干沙漠旅游景区，一个人出行。地点在通辽，打车比较省心，现场高峰时段比较拥挤。这次玩了4天，人均花费约1066元，历史文化气息浓。景点印象：塔敏查干沙漠，塔敏查干，蒙语，译为“魔鬼”或“地狱”，号称“八百里瀚海”。在酷热的夏日，沙漠深处偶而会出现“沙市蜃楼”的奇观。整体感受是特别满意，很推荐。二刷意愿：是。', '4%', 81);
