INSERT INTO `travel_review` VALUES (12827, 'TR012827', '石空寺石窟', '中卫', '宁夏', '周末短途', '夏季', 3, 3, 900.00, '否', 4, '3月去的石空寺石窟，和家人出行。地点在中卫，公交换乘方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约900元，氛围感不错。景点印象：位于中宁县城北15公里处，原有大佛洞、卧佛洞、观音洞、龙王洞、灵光洞等石窟，石窟前建有寺院，寺院中还有各类神佛塑像。但是由于这里是腾格里沙漠的南缘，风沙大，加上在晚清时期社会动乱，寺院荒废，石窟逐渐被流沙埋没。到了20世纪40年代末，仅…整体感受是整体不错，周末来刚好。二刷意愿：否。', '1%', 46);
