INSERT INTO `travel_review` VALUES (12838, 'TR012838', '石硖龙眼母本园', '贵港', '广西', '拍照旅行', '冬季', 11, 4, 1222.00, '是', 5, '11月去的石硖龙眼母本园，一个人出行。地点在贵港，自驾停车需要提前规划，现场人不算多。这次玩了4天，人均花费约1222元，拍照很出片。景点印象：石硖龙眼母本园位于广西平南县大新镇，南宁至梧州、平南至容县二级公路从旁边穿过，距平南县城30公里，占地120多亩，始建于1927年。\n母本园是1927年覃姓乡绅留学日本早稻田大学归来，利用学到的嫁接技术，将村民在山上的石缝中发现一株果大肉脆的龙…整体感受是特别满意，很推荐。二刷意愿：是。', '0%', 90);
