INSERT INTO `travel_review` VALUES (12859, 'TR012859', '封江生态旅游区', '随州', '湖北', '城市漫游', '秋季', 8, 6, 1352.00, '否', 4, '8月去的封江生态旅游区，和家人出行。地点在随州，打车比较省心，现场高峰时段比较拥挤。这次玩了6天，人均花费约1352元，氛围感不错。景点印象：封江水库两岸山峦连绵起伏，库汊水岛犬牙交错，形成了封江独具特色的库区风光。27公里长的水域犹如一幅画廊，14万亩山场四季如画：春季山花烂漫，映山红满山遍野；夏日绿树成荫，满目青翠；秋天叶红果熟，四处飘香；冬时雪压青松，银装素裹。库区上…整体感受是还蛮满意，周末来刚好。二刷意愿：否。', '0%', 67);
