INSERT INTO `travel_review` VALUES (12873, 'TR012873', '茶场', '百色', '广西', '城市漫游', '秋季', 8, 2, 976.00, '否', 2, '8月去的茶场，和朋友出行。地点在百色，打车比较省心，现场人不算多。这次玩了2天，人均花费约976元，历史文化气息浓。景点印象：从靖西到百色市区有四百多公里，沿路依然是如画的风光。时而是在山中转，时而穿越平原。到达百色市区已是下午四点多。百色并不像我们想象中那么落后，城市的规划建筑都达到一定层次呢。\n从百色到凌云，九十多公里完全是盘山的路。绕着一座又一座的…整体感受是没达到预期，建议谨慎前往。二刷意愿：否。', '1%', 40);
