INSERT INTO `travel_review` VALUES (12906, 'TR012906', '南极村', '湛江', '广东', '深度游', '冬季', 9, 5, 1411.00, '否', 5, '9月去的南极村，情侣出行。地点在湛江，打车比较省心，现场高峰时段比较拥挤。这次玩了5天，人均花费约1411元，夜景表现很好。景点印象：中国大陆南极村（角尾乡）位于广东省徐闻县西南部，被琼州海峡和北部湾所拥环，地形似伸向大海的牛角，面积37平方公里，人口3.2万人。 南极村灯楼角和台湾的鹅銮鼻、海南临高角并称中国南三端。南极村位于东经109°55′，北纬20°13′。古有“极南…整体感受是超出预期，以后还会来。二刷意愿：否。', '0%', 74);
