INSERT INTO `travel_review` VALUES (12951, 'TR012951', '武关遗址', '商洛', '陕西', '周末短途', '春季', 2, 2, 400.00, '否', 2, '2月去的武关遗址，情侣出行。地点在商洛，地铁到达方便，现场游客较多。这次玩了2天，人均花费约400元，氛围感不错。景点印象：位于丹凤县东武关河的北岸,与函谷关,萧关,大散关成为“秦之四塞”。武关历史悠久，远在春秋时即以建置,明曰“少习关”,战国时改为“武关”。关城建立在峡谷间一座较为平坦的高地上,北依高峻的少习山,南濒险要。关城周长1.5公里，城墙用土筑,略成方…整体感受是略失望，可考虑其他景点。二刷意愿：否。', '0%', 52);
