INSERT INTO `travel_review` VALUES (12966, 'TR012966', '海南省博物馆', '海口', '海南', '城市漫游', '春季', 12, 1, 80.00, '否', 3, '12月去的海南省博物馆，一个人出行。地点在海口，自驾停车需要提前规划，现场游客较多。这次玩了1天，人均花费约80元，夜景表现很好。景点印象：来此可全面了解海南的历史、文化、少数民族风情，丰富知识面。整体感受是中规中矩，避开高峰更好。二刷意愿：否。', '4%', 101);
INSERT INTO `travel_review` VALUES (12967, 'TR012967', '九女湖', '晋城', '山西', '周末短途', '夏季', 3, 2, 270.00, '是', 4, '3月去的九女湖，和朋友出行。地点在晋城，打车比较省心，现场游客较多。这次玩了2天，人均花费约270元，夜景表现很好。景点印象：九仙女湖旅游风景区--位于山西省阳城县，是传说中仙女下凡游玩之处所，湖中矗立有九女仙台，台上建有九女仙祠，是阳城古城八景之一。曾是历代文人墨客经常观光旅游的地方。\n九女湖地处太行山和中条山交汇的沁河峡谷之中，它是阳城县继国家级自然风…整体感受是还蛮满意，推荐来看看。二刷意愿：是。', '11%', 70);
INSERT INTO `travel_review` VALUES (12968, 'TR012968', '兜率岩', '郴州', '湖南', '深度游', '春季', 12, 1, 516.00, '是', 5, '12月去的兜率岩，一个人出行。地点在郴州，打车比较省心，现场游客较多。这次玩了1天，人均花费约516元，氛围感不错。景点印象：兜率岩位于资兴市东江水库中的一座岛屿上，内有铜钟洞、锣鼓洞、彩石洞等，洞中有洞，璀璨夺目。兜率岩面积很大，洞长5公里多，步道从上到下迂回曲折，走一圈大约1公里左右，里面的溶岩非常壮观，有铜钟洞、锣鼓洞、彩石洞等，可谓洞中有洞。整体感受是挺惊喜，很推荐。二刷意愿：是。', '8%', 91);
