INSERT INTO `travel_review` VALUES (13005, 'TR013005', '福严寺', '衡阳', '湖南', '深度游', '夏季', 4, 2, 542.00, '是', 4, '4月去的福严寺，和朋友出行。地点在衡阳，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约542元，历史文化气息浓。景点印象：禅宗“南岳系”在此开派，被佛家弟子誉为“天下法院”。 寺庙旁还有上千年的古泉和古树，据说是当年慧思禅师亲自挖掘和栽植的。整体感受是体验挺好，周末来刚好。二刷意愿：是。', '8%', 19);
