INSERT INTO `travel_review` VALUES (13012, 'TR013012', '卧牛湖', '黑河', '黑龙江', '亲子出游', '秋季', 6, 1, 280.00, '是', 5, '6月去的卧牛湖，一个人出行。地点在黑河，公交换乘方便，现场人不算多。这次玩了1天，人均花费约280元，拍照很出片。景点印象：卧牛湖风景区地处黑河市爱辉区上马厂乡卧牛河村，距黑河市区14公里，位于黑呼公路16公里处，面积为50平方公里，与俄布拉戈维申斯克市隔江相望，是黑河市省级名胜风景区。\n卧牛湖湖区夏季山青水秀，冬季银妆素裹，具备游览、观赏、避暑、度假、娱乐…整体感受是超出预期，以后还会来。二刷意愿：是。', '1%', 40);
