INSERT INTO `travel_review` VALUES (13015, 'TR013015', '伏皇后墓', '许昌', '河南', '深度游', '夏季', 3, 3, 987.00, '否', 2, '3月去的伏皇后墓，和朋友出行。地点在许昌，打车比较省心，现场人流量适中。这次玩了3天，人均花费约987元，夜景表现很好。景点印象：位于许昌市南15公里的冢刘村东北隅，是为汉献帝的皇后伏寿之陵墓。墓高10米，占地1730平方米，冢前有两小墓，为二皇子墓。伏皇后在汉献帝兴平二年（公元159年）被立为皇后，建安十九年（公元214年）怨恨曹诛董承，与父伏完密谋曹操，事情泄漏，曹将…整体感受是略失望，不建议高峰来。二刷意愿：否。', '0%', 33);
