INSERT INTO `travel_review` VALUES (13049, 'TR013049', '龙进溪', '宜昌', '湖北', '亲子出游', '秋季', 7, 2, 158.00, '是', 5, '7月去的龙进溪，一个人出行。地点在宜昌，公交换乘方便，现场人流量适中。这次玩了2天，人均花费约158元，历史文化气息浓。景点印象：“龙溪桥下春波绿，曾是惊鸿照影来”，乘峡江渔船，赏溪观泉，品古老渔文化。整体感受是超出预期，很推荐。二刷意愿：是。', '1%', 75);
INSERT INTO `travel_review` VALUES (13050, 'TR013050', '塞罕坝国家森林公园', '承德', '河北', '拍照旅行', '秋季', 8, 1, 550.00, '是', 5, '8月去的塞罕坝国家森林公园，一个人出行。地点在承德，打车比较省心，现场人流量适中。这次玩了1天，人均花费约550元，拍照很出片。景点印象：有广袤的草原和森林，景色十分壮美，是北京附近观看塞外风光的最佳去处。 每到秋季，黄红两色的树木和草原层林尽染，可以轻易拍出摄影大片。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '17%', 63);
