INSERT INTO `travel_review` VALUES (13102, 'TR013102', '清东陵', '唐山', '河北', '亲子出游', '秋季', 6, 3, 743.00, '否', 5, '6月去的清东陵，和家人出行。地点在唐山，地铁到达方便，现场人流量适中。这次玩了3天，人均花费约743元，夜景表现很好。景点印象：中国最大的皇陵建筑群，埋葬着顺治、康熙、乾隆及慈禧、香妃等众多皇室成员。 欣赏令人震撼的裕陵地宫雕刻、慈禧陵“凤上龙下”浮雕等精美的建筑杰作。整体感受是超出预期，值得专门打卡。二刷意愿：否。', '28%', 91);
