INSERT INTO `travel_review` VALUES (13106, 'TR013106', '苏铁保护区', '攀枝花', '四川', '城市漫游', '夏季', 4, 1, 481.00, '是', 5, '4月去的苏铁保护区，和朋友出行。地点在攀枝花，公交换乘方便，现场游客较多。这次玩了1天，人均花费约481元，历史文化气息浓。景点印象：在攀枝花市西区所属的的巴关河西岸的丰家梁子一带，海拔2000米左右，分布着一片十分珍贵的天然苏铁林。\n苏铁亦称铁树，最早出现在在距今约2亿8千万年前的地球古生代二迭纪。它历经沧桑，几度盛衰。现存的苏铁类植物，仅一科10属约110种，被誉为植物…整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 78);
