INSERT INTO `travel_review` VALUES (13127, 'TR013127', '喇嘛库伦庙', '锡林郭勒盟', '内蒙古', '文化打卡', '秋季', 8, 2, 186.00, '是', 5, '8月去的喇嘛库伦庙，和家人出行。地点在锡林郭勒盟，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约186元，拍照很出片。景点印象：喇嘛库伦庙位于旗所在地乌里雅斯太镇，是蒙古地区喇嘛教“三大库伦”之一，又名“施集庙”，建寺主人为罗布宫其格拉希活佛。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '1%', 59);
