INSERT INTO `travel_review` VALUES (13130, 'TR013130', '鄂豫皖苏区首府烈士陵园', '信阳', '河南', '拍照旅行', '春季', 2, 4, 1146.00, '否', 5, '2月去的鄂豫皖苏区首府烈士陵园，一个人出行。地点在信阳，公交换乘方便，现场高峰时段比较拥挤。这次玩了4天，人均花费约1146元，夜景表现很好。景点印象：鄂豫皖苏区革命烈士陵园建于1957年、占地330亩由大门、烈士浮雕墙、烈士纪念碑、烈士纪念堂、革命斗争史陈列室、吴焕先半身塑像、烈士纪念亭、烈士墓地八大部分组成。\n大门 为现代建筑，园名由原国家主席李先念亲笔题写。\n烈士浮雕墙 用花岗岩雕塑…整体感受是挺惊喜，以后还会来。二刷意愿：否。', '0%', 96);
INSERT INTO `travel_review` VALUES (13131, 'TR013131', '总兵府', '汕头', '广东', '文化打卡', '春季', 2, 2, 434.00, '是', 5, '2月去的总兵府，一个人出行。地点在汕头，公交换乘方便，现场人不算多。这次玩了2天，人均花费约434元，历史文化气息浓。景点印象：是全国唯一的海岛总兵府，历史文化的内涵丰富，对台关系意义深远。整体感受是挺惊喜，很推荐。二刷意愿：是。', '11%', 57);
