INSERT INTO `travel_review` VALUES (13158, 'TR013158', '天生桥', '邵阳', '湖南', '深度游', '夏季', 4, 2, 752.00, '否', 4, '4月去的天生桥，情侣出行。地点在邵阳，打车比较省心，现场人流量适中。这次玩了2天，人均花费约752元，历史文化气息浓。景点印象：天生桥景区紧临广西，是莨山景区近年来新发现的最具特色的景区之一，区内山环水绕，群峰横列，赤壁对峙，万巷迷离，约有近50平方公里折大面积丹霞赤壁群景观，景观资源特色鲜明，个性突出，具有强劲的比较优势，是开发丹霞观光、生态旅游、休头娱乐…整体感受是体验挺好，周末来刚好。二刷意愿：否。', '0%', 72);
