INSERT INTO `travel_review` VALUES (13180, 'TR013180', '阳泉水帘洞瀑布', '阳泉', '山西', '文化打卡', '春季', 12, 5, 1750.00, '否', 5, '12月去的阳泉水帘洞瀑布，和家人出行。地点在阳泉，公交换乘方便，现场高峰时段比较拥挤。这次玩了5天，人均花费约1750元，氛围感不错。景点印象：位于娘子关城东门东南方向的500米处。飞瀑奔泻，悬流百尺，散缕似珠，山城沟谷中泉眼累累。当地人称为“海眼”的悬泉，是众泉眼中最大的一个。瀑布落差30余米，宽约10多米，“海眼”泉水翻滚，激起层层白色浪花，响声震耳。平地涌出的泉水，从“海…整体感受是特别满意，很推荐。二刷意愿：否。', '0%', 61);
