INSERT INTO `travel_review` VALUES (13210, 'TR013210', '野趣沟', '河源', '广东', '城市漫游', '夏季', 4, 1, 412.00, '否', 3, '4月去的野趣沟，情侣出行。地点在河源，地铁到达方便，现场人不算多。这次玩了1天，人均花费约412元，历史文化气息浓。景点印象：赏奇秀山水，体味自然野趣，更有独特的暗洞漂流。整体感受是体验一般，避开高峰更好。二刷意愿：否。', '4%', 76);
