INSERT INTO `travel_review` VALUES (13213, 'TR013213', '黄遵宪纪念馆', '梅州', '广东', '拍照旅行', '冬季', 11, 3, 994.00, '是', 5, '11月去的黄遵宪纪念馆，情侣出行。地点在梅州，打车比较省心，现场高峰时段比较拥挤。这次玩了3天，人均花费约994元，氛围感不错。景点印象：清末爱国诗人黄遵宪的故居名为“人境庐”，坐落在梅州市东3公里处的周溪畔，庐舍内环境优美，曲径通幽，书香四溢。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '35%', 51);
INSERT INTO `travel_review` VALUES (13214, 'TR013214', '南屏景区', '黄山', '安徽', '深度游', '秋季', 6, 6, 1738.00, '是', 5, '6月去的南屏景区，情侣出行。地点在黄山，地铁到达方便，现场人流量适中。这次玩了6天，人均花费约1738元，历史文化气息浓。景点印象：以祠堂为特色的徽派古村，《菊豆》的取景地，游人不多，很清静。整体感受是特别满意，很推荐。二刷意愿：是。', '3%', 70);
INSERT INTO `travel_review` VALUES (13215, 'TR013215', '陕县温泉', '三门峡', '河南', '周末短途', '春季', 12, 1, 299.00, '否', 5, '12月去的陕县温泉，和朋友出行。地点在三门峡，公交换乘方便，现场人不算多。这次玩了1天，人均花费约299元，历史文化气息浓。景点印象：陕县温泉位于三门峡市西温塘村，距市区15公里，交通便利、风景优美。温泉位于汾渭热矿水带弧形转折处和山西裂谷边缘基地，构造复杂，是一个具有优越隔热条件的迳流区。区内发育有深达300多米的深大断裂，裂谷深部有较新的岩浆活动，巨大的侵入岩体…整体感受是挺惊喜，很推荐。二刷意愿：否。', '8%', 57);
