INSERT INTO `travel_review` VALUES (13228, 'TR013228', '关王庙', '阳泉', '山西', '拍照旅行', '冬季', 11, 4, 1071.00, '否', 5, '11月去的关王庙，一个人出行。地点在阳泉，地铁到达方便，现场高峰时段比较拥挤。这次玩了4天，人均花费约1071元，拍照很出片。景点印象：关王庙又称关帝庙，俗称老爷庙，位于郊区白泉乡林里村南。殿宇由绿树、红墙萦围。占地面积近7000平方米，分内外两大院落。关王庙建成已有900多年，据有关资料证实，是我国最早的关羽庙建筑。关王庙以关王正殿为主，由献殿、马殿、南北配殿，以及外…整体感受是超出预期，以后还会来。二刷意愿：否。', '7%', 128);
