INSERT INTO `travel_review` VALUES (13233, 'TR013233', '华容古道', '荆州', '湖北', '拍照旅行', '春季', 2, 1, 536.00, '否', 5, '2月去的华容古道，和家人出行。地点在荆州，打车比较省心，现场人流量适中。这次玩了1天，人均花费约536元，历史文化气息浓。景点印象：在监利县城西南12公里。即曹桥至毛家口的一条湖区小路，长7.5公里。监利古称华容，原县城位于今县城北30公里。《资治通鉴》注：“从此道可至华容县也”，故名。据载：东汉建安十三年（208年），曹操兵败赤壁走此，遇泥陷，急令军士负草填之，赢者饥…整体感受是超出预期，值得专门打卡。二刷意愿：否。', '0%', 91);
