INSERT INTO `travel_review` VALUES (13249, 'TR013249', '雾漫小东江', '郴州', '湖南', '文化打卡', '春季', 12, 1, 818.00, '是', 5, '12月去的雾漫小东江，情侣出行。地点在郴州，打车比较省心，现场游客较多。这次玩了1天，人均花费约818元，历史文化气息浓。景点印象：小东江位于资兴市内，水面面积达160平方公里，蓄水量81亿立方米，相当于半个洞庭湖。这里长年两岸峰峦叠翠，湖面水汽蒸腾，云雾缭绕，神秘绮丽，其雾时移时凝，宛如一条被仙女挥舞着的“白练”，美丽之极，堪称中华一绝。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '42%', 110);
INSERT INTO `travel_review` VALUES (13250, 'TR013250', '刘老桥', '阜阳', '安徽', '城市漫游', '冬季', 9, 4, 935.00, '否', 5, '9月去的刘老桥，情侣出行。地点在阜阳，自驾停车需要提前规划，现场人流量适中。这次玩了4天，人均花费约935元，历史文化气息浓。景点印象：景点本身有一定特色整体感受是挺惊喜，很推荐。二刷意愿：否。', '0%', 54);
INSERT INTO `travel_review` VALUES (13251, 'TR013251', '铁门关', '巴音郭楞', '新疆', '拍照旅行', '冬季', 11, 3, 1047.00, '是', 5, '11月去的铁门关，情侣出行。地点在巴音郭楞，打车比较省心，现场高峰时段比较拥挤。这次玩了3天，人均花费约1047元，夜景表现很好。景点印象：铁门关位于库尔勒市北郊8公里处，扼孔雀河上游陡峭峡谷的出口，曾是南北疆交通的天险要冲，古代“丝绸之路”中道咽喉。晋代在这里设关，因其险固，故称\"铁门关\"，列为中国古代二十六名关之一。整体感受是挺惊喜，很推荐。二刷意愿：是。', '2%', 70);
