INSERT INTO `travel_review` VALUES (13253, 'TR013253', '香山寺', '铜川', '陕西', '深度游', '秋季', 8, 1, 519.00, '是', 4, '8月去的香山寺，和家人出行。地点在铜川，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约519元，夜景表现很好。景点印象：香山创建寺院，始于苛秦，盛于姚秦。曾迎龟兹高僧鸠摩罗什翻译梵经于此。宋雍熙年间修中峰崎峰洞，建圣果院、白雀寺。清代光绪年间修建各类楼殿亭阁90余间。整体感受是整体不错，周末来刚好。二刷意愿：是。', '10%', 85);
