INSERT INTO `travel_review` VALUES (13261, 'TR013261', '伪满皇宫博物院', '长春', '吉林', '文化打卡', '夏季', 5, 2, 555.00, '否', 5, '5月去的伪满皇宫博物院，和朋友出行。地点在长春，打车比较省心，现场游客较多。这次玩了2天，人均花费约555元，夜景表现很好。景点印象：末代皇帝溥仪的宫殿，了解溥仪曾经的生活和工作环境，铭记历史。整体感受是挺惊喜，很推荐。二刷意愿：否。', '47%', 84);
