INSERT INTO `travel_review` VALUES (13264, 'TR013264', '龙华寺', '贵港', '广西', '周末短途', '夏季', 3, 7, 1828.00, '是', 5, '3月去的龙华寺，一个人出行。地点在贵港，地铁到达方便，现场游客较多。这次玩了7天，人均花费约1828元，拍照很出片。景点印象：广西桂平市西山龙华寺始建于宋朝，清康熙乾隆、同治年间曾三次重修，一九七四、八八年又两次重修，现为钢筋水泥结构。几经重修后，一九九О年重修开光。殿阁雄伟巍峨，香火甚盛，香客进香，参禅礼拜，佛殿生辉。\n龙华古寺，又名上寺，至今已传四十…整体感受是超出预期，值得专门打卡。二刷意愿：是。', '0%', 99);
INSERT INTO `travel_review` VALUES (13265, 'TR013265', '极影', '昭通', '云南', '亲子出游', '秋季', 8, 2, 1016.00, '否', 5, '8月去的极影，和朋友出行。地点在昭通，地铁到达方便，现场人不算多。这次玩了2天，人均花费约1016元，夜景表现很好。景点印象：周边配套比较齐全整体感受是挺惊喜，很推荐。二刷意愿：否。', '0%', 72);
