INSERT INTO `travel_review` VALUES (13267, 'TR013267', '哲蚌寺', '拉萨', '西藏', '深度游', '春季', 1, 3, 597.00, '是', 5, '1月去的哲蚌寺，情侣出行。地点在拉萨，自驾停车需要提前规划，现场游客较多。这次玩了3天，人均花费约597元，夜景表现很好。景点印象：藏传佛教最大的寺院，每年的雪顿节晒佛仪式是藏区最大规模的展佛。整体感受是挺惊喜，很推荐。二刷意愿：是。', '19%', 68);
INSERT INTO `travel_review` VALUES (13268, 'TR013268', '南诏风情岛', '大理', '云南', '拍照旅行', '夏季', 3, 1, 509.00, '是', 3, '3月去的南诏风情岛，一个人出行。地点在大理，地铁到达方便，现场人不算多。这次玩了1天，人均花费约509元，历史文化气息浓。景点印象：民族风情浓郁的美丽小岛，有据说是世界上最高的汉白玉观音像。整体感受是还可以，按需选择。二刷意愿：是。', '19%', 82);
INSERT INTO `travel_review` VALUES (13269, 'TR013269', '义井遗址', '焦作', '河南', '深度游', '冬季', 10, 1, 218.00, '是', 5, '10月去的义井遗址，情侣出行。地点在焦作，自驾停车需要提前规划，现场游客较多。这次玩了1天，人均花费约218元，夜景表现很好。景点印象：义井遗址位于孟县城西5公里处义井村村西的曹马沟内。遗址南北长700余米，东西宽450米，总面积约31.5万平方米，文化层厚约3-5米。经过多次考察，采集到的石器有石刀、石铲等，陶器有豆、瓮、澄滤器、甑、大口尊等，以灰陶居多，也发现有少量黑陶。纹…整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 48);
