INSERT INTO `travel_review` VALUES (13281, 'TR013281', '中苏街', '呼伦贝尔', '内蒙古', '拍照旅行', '夏季', 4, 2, 441.00, '是', 4, '4月去的中苏街，和朋友出行。地点在呼伦贝尔，打车比较省心，现场游客较多。这次玩了2天，人均花费约441元，夜景表现很好。景点印象：中苏街在解放前称博士街，是满洲里早期隆太号、恒盛福、福海长、吉顺富、义聚德、尼基金旅馆等众多商家聚集地。解放后为纪念中国与前苏联的友好合作改称中苏街。整体感受是体验挺好，周末来刚好。二刷意愿：是。', '2%', 46);
