INSERT INTO `travel_review` VALUES (13284, 'TR013284', '磨盘山', '吉林市', '吉林', '深度游', '秋季', 8, 4, 832.00, '是', 5, '8月去的磨盘山，和家人出行。地点在吉林市，打车比较省心，现场人不算多。这次玩了4天，人均花费约832元，历史文化气息浓。景点印象：磨盘山又叫小磨盘山，在丰满区前二道乡王相村境内。距市区15公里，总面积10平方公里。磨盘山顶峰形状如磨盘，因此而得名。该山南北走向，南北峰对峙，南侧面为长山顶，北侧为尖山顶。北侧主峰海拔783.8米。磨盘山山势陡峻。峰奇石秀，林木茂密，狼…整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 87);
