INSERT INTO `travel_review` VALUES (13295, 'TR013295', '千家坪公园', '安康', '陕西', '文化打卡', '秋季', 8, 1, 80.00, '是', 4, '8月去的千家坪公园，和家人出行。地点在安康，公交换乘方便，现场游客较多。这次玩了1天，人均花费约80元，历史文化气息浓。景点印象：千家坪公园位处化龙山。化龙山属陕渝交界的大巴山高峰，地处陕西最南端，其主区属于平利千家坪国营林场，主峰海拔2917.2米，故有“巴山屋脊”之称。是岚河、浪河、红石河、平溪河的发源地。这里有着原始森林的迷人风光和神秘文化，是一个具有独特的…整体感受是整体不错，推荐来看看。二刷意愿：是。', '0%', 55);
