INSERT INTO `travel_review` VALUES (13351, 'TR013351', '大沟湾景区', '鄂尔多斯', '内蒙古', '城市漫游', '夏季', 3, 4, 1109.00, '否', 4, '3月去的大沟湾景区，一个人出行。地点在鄂尔多斯，打车比较省心，现场高峰时段比较拥挤。这次玩了4天，人均花费约1109元，历史文化气息浓。景点印象：大沟湾是大自然的杰作，它位于城川镇东南 18 公里处，因发源于陕西省白宇山北麓的无定河注入城川大沟湾村而得名。大沟湾不仅以优质 “红星 ”苹果、红尾鲤鱼和避暑盛地 - 滴哨沟而驰名四海，更以是古“河套人”的故乡而闻名于世。\n本世纪四十年代，…整体感受是体验挺好，可以安排半天到一天。二刷意愿：否。', '3%', 54);
