INSERT INTO `travel_review` VALUES (13367, 'TR013367', '叶斗峰', '忻州', '山西', '城市漫游', '春季', 2, 1, 938.00, '是', 5, '2月去的叶斗峰，和家人出行。地点在忻州，地铁到达方便，现场人不算多。这次玩了1天，人均花费约938元，夜景表现很好。景点印象：台顶气候异常寒冷，通常9月见雪，4月解冻，台背阴面有常年不化的冰雪。整体感受是超出预期，以后还会来。二刷意愿：是。', '9%', 75);
INSERT INTO `travel_review` VALUES (13368, 'TR013368', '洪泽湖', '淮安', '江苏', '深度游', '春季', 1, 1, 231.00, '否', 4, '1月去的洪泽湖，和家人出行。地点在淮安，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约231元，拍照很出片。景点印象：洪泽湖是我国著名的五大淡水湖之一，国家4A级旅游景点，素有“日出斗金”的美誉，盛产洪泽湖大闸蟹等名产。整体感受是体验挺好，推荐来看看。二刷意愿：否。', '32%', 97);
