INSERT INTO `travel_review` VALUES (13370, 'TR013370', '黄遵宪纪念馆', '梅州', '广东', '亲子出游', '夏季', 3, 6, 2049.00, '是', 4, '3月去的黄遵宪纪念馆，和家人出行。地点在梅州，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了6天，人均花费约2049元，拍照很出片。景点印象：清末爱国诗人黄遵宪的故居名为“人境庐”，坐落在梅州市东3公里处的周溪畔，庐舍内环境优美，曲径通幽，书香四溢。整体感受是体验挺好，推荐来看看。二刷意愿：是。', '35%', 90);
