INSERT INTO `travel_review` VALUES (13374, 'TR013374', '诸葛八卦村', '金华', '浙江', '拍照旅行', '春季', 12, 2, 466.00, '否', 3, '12月去的诸葛八卦村，情侣出行。地点在金华，地铁到达方便，现场游客较多。这次玩了2天，人均花费约466元，拍照很出片。景点印象：诸葛亮后裔最大的聚居地，是个古朴而宁静的古村。村里保留了大量按九宫八卦布局的徽派老建筑，十分独特。\n丞相祠堂、大公堂尤值得一看，参观其中的展览感受诸葛氏族的文化底蕴。整体感受是中规中矩，避开高峰更好。二刷意愿：否。', '8%', 55);
