INSERT INTO `travel_review` VALUES (13416, 'TR013416', '天盆风景区', '巴中', '四川', '亲子出游', '春季', 1, 2, 406.00, '是', 5, '1月去的天盆风景区，和家人出行。地点在巴中，自驾停车需要提前规划，现场人流量适中。这次玩了2天，人均花费约406元，氛围感不错。景点印象：位于通江东北的空山景区，属高原盆地景观，海拔1450--2108米，幅员面积60平方千米，地势开阔，空间博大，有80多个著名景点，主要分布在空山乡、临江乡、两河口乡一带。该景区把奇特的溶岩地貌，神秘的原始森林与二战时期李先念亲自指挥空山战役的遗…整体感受是超出预期，很推荐。二刷意愿：是。', '5%', 77);
