INSERT INTO `travel_review` VALUES (13426, 'TR013426', '吴玉章故居', '自贡', '四川', '周末短途', '秋季', 8, 4, 1196.00, '否', 2, '8月去的吴玉章故居，和朋友出行。地点在自贡，自驾停车需要提前规划，现场人流量适中。这次玩了4天，人均花费约1196元，氛围感不错。景点印象：周边配套比较齐全整体感受是略失望，可考虑其他景点。二刷意愿：否。', '20%', 59);
INSERT INTO `travel_review` VALUES (13427, 'TR013427', '峙峪遗址', '朔州', '山西', '亲子出游', '秋季', 6, 1, 766.00, '否', 5, '6月去的峙峪遗址，一个人出行。地点在朔州，公交换乘方便，现场人不算多。这次玩了1天，人均花费约766元，拍照很出片。景点印象：位于朔州城西北15公里的黑驼山脚下，是一处旧石器时代的人类遗址，中国科学院1963年发现。现为省级重点文物保护单位。这里除发现大批细小石器和大量动物化石外，还发掘出数百件有刻划痕迹的兽片和一件人类初期的武器――石旋.整体感受是特别满意，值得专门打卡。二刷意愿：否。', '2%', 94);
INSERT INTO `travel_review` VALUES (13428, 'TR013428', '平安宏济堂国药文化馆', '海东', '青海', '深度游', '春季', 1, 3, 904.00, '否', 5, '1月去的平安宏济堂国药文化馆，和朋友出行。地点在海东，公交换乘方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约904元，氛围感不错。景点印象：周边配套比较齐全整体感受是特别满意，以后还会来。二刷意愿：否。', '0%', 91);
INSERT INTO `travel_review` VALUES (13429, 'TR013429', '密苑云顶乐园（云顶滑雪场）', '张家口', '河北', '文化打卡', '夏季', 5, 1, 624.00, '否', 5, '5月去的密苑云顶乐园（云顶滑雪场），和家人出行。地点在张家口，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约624元，夜景表现很好。景点印象：景点本身有一定特色整体感受是特别满意，很推荐。二刷意愿：否。', '0%', 76);
INSERT INTO `travel_review` VALUES (13430, 'TR013430', '中山影视城', '中山', '广东', '深度游', '夏季', 4, 2, 258.00, '是', 5, '4月去的中山影视城，情侣出行。地点在中山，地铁到达方便，现场游客较多。这次玩了2天，人均花费约258元，夜景表现很好。景点印象：有多国展区，摄影爱好者的天堂，很多新婚夫妇也选择在此拍摄婚纱照。整体感受是超出预期，很推荐。二刷意愿：是。', '17%', 73);
INSERT INTO `travel_review` VALUES (13431, 'TR013431', '太平古镇', '泸州', '四川', '拍照旅行', '夏季', 4, 4, 1098.00, '否', 4, '4月去的太平古镇，和朋友出行。地点在泸州，打车比较省心，现场游客较多。这次玩了4天，人均花费约1098元，拍照很出片。景点印象：著名的四渡赤水就发生在太平镇，至今镇内仍遗留着许多当年红军的遗址。整体感受是体验挺好，周末来刚好。二刷意愿：否。', '5%', 78);
INSERT INTO `travel_review` VALUES (13432, 'TR013432', '一天门', '十堰', '湖北', '周末短途', '春季', 12, 1, 434.00, '否', 2, '12月去的一天门，和朋友出行。地点在十堰，打车比较省心，现场游客较多。这次玩了1天，人均花费约434元，历史文化气息浓。景点印象：在攀登武当山金顶的古神道上，建有三座天门，额书一天门、二天门、三天门。三座天门均为明永乐十年在元代旧址上敕建，砖石结构，歇山顶式，下层为石雕须弥座，石雕的水盘檐为仿木结构。三座天门气势恢宏，依次屹立在数千级饰栏石阶之间，古人赞美曰…整体感受是没达到预期，可考虑其他景点。二刷意愿：否。', '4%', 39);
