INSERT INTO `travel_review` VALUES (13435, 'TR013435', '丹山赤水', '宁波', '浙江', '亲子出游', '秋季', 8, 1, 667.00, '否', 4, '8月去的丹山赤水，和家人出行。地点在宁波，自驾停车需要提前规划，现场人不算多。这次玩了1天，人均花费约667元，历史文化气息浓。景点印象：山下的柿林村几乎家家户户种柿子，石头垒砌的老房子有不同于江南古镇的韵味。 秋天柿子成熟时，村里、山上的柿子树结满诱人的柿子，天然好吃又便宜。整体感受是整体不错，周末来刚好。二刷意愿：否。', '1%', 73);
