INSERT INTO `travel_review` VALUES (13450, 'TR013450', '滨州国际会展中心', '滨州', '山东', '文化打卡', '秋季', 7, 4, 827.00, '否', 3, '7月去的滨州国际会展中心，和朋友出行。地点在滨州，地铁到达方便，现场高峰时段比较拥挤。这次玩了4天，人均花费约827元，夜景表现很好。景点印象：景点本身有一定特色整体感受是中规中矩，别抱太高期待。二刷意愿：否。', '0%', 59);
INSERT INTO `travel_review` VALUES (13451, 'TR013451', '新村银杏园', '临沂', '山东', '周末短途', '冬季', 10, 1, 470.00, '否', 5, '10月去的新村银杏园，情侣出行。地点在临沂，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约470元，夜景表现很好。景点印象：山东省郯城县新村乡因盛产银杏而闻名全国，是名副其实的“银杏之乡”。全乡银杏种植面积28000多亩，银杏结果大树23000多株，年产银杏干果100多万公斤，银杏采叶圃20000多亩，年产银杏干叶4000多吨，出圃银杏苗木5000多万株/年，在全国率先研究开发…整体感受是超出预期，很推荐。二刷意愿：否。', '10%', 83);
INSERT INTO `travel_review` VALUES (13452, 'TR013452', '未苏湾', '黄石', '湖北', '城市漫游', '秋季', 7, 2, 485.00, '否', 5, '7月去的未苏湾，和朋友出行。地点在黄石，打车比较省心，现场人不算多。这次玩了2天，人均花费约485元，夜景表现很好。景点印象：周边配套比较齐全整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '0%', 91);
INSERT INTO `travel_review` VALUES (13453, 'TR013453', '冠山', '阳泉', '山西', '文化打卡', '夏季', 4, 3, 886.00, '是', 2, '4月去的冠山，一个人出行。地点在阳泉，公交换乘方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约886元，夜景表现很好。景点印象：山西省冠山森林公园位于山西省东部的平定县城关镇内，公园总面积709。4公顷，最高海拔1152米，植物种类丰富，有古松、奇树35株，医用药材160余种，危崖峭立，松柏参天，山光水色瑰丽，景色四季宜人，更有佛寺书院、石峒亭阁、乔宇诗碑、傅山篆刻，…整体感受是体验偏一般，建议谨慎前往。二刷意愿：是。', '0%', 46);
INSERT INTO `travel_review` VALUES (13454, 'TR013454', '大佛寺', '西宁', '青海', '城市漫游', '秋季', 6, 2, 315.00, '否', 5, '6月去的大佛寺，和家人出行。地点在西宁，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约315元，历史文化气息浓。景点印象：佛殿内塑有三贤哲巨大塑像，故取名大佛寺，被看作藏传佛教“后弘期”的祖庭。整体感受是挺惊喜，很推荐。二刷意愿：否。', '2%', 64);
INSERT INTO `travel_review` VALUES (13455, 'TR013455', '赤壁古战场', '咸宁', '湖北', '文化打卡', '夏季', 4, 2, 1139.00, '是', 4, '4月去的赤壁古战场，和家人出行。地点在咸宁，自驾停车需要提前规划，现场人流量适中。这次玩了2天，人均花费约1139元，夜景表现很好。景点印象：古代著名战役中尚存原貌的古战场，回味三国时期的故事。整体感受是整体不错，周末来刚好。二刷意愿：是。', '0%', 88);
