INSERT INTO `travel_review` VALUES (13465, 'TR013465', '云杉坪', '丽江', '云南', '亲子出游', '冬季', 11, 1, 300.00, '是', 5, '11月去的云杉坪，情侣出行。地点在丽江，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约300元，氛围感不错。景点印象：穿越茂密云杉丛林，在大草坪前观看雪峰，景色壮观优美。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '10%', 112);
INSERT INTO `travel_review` VALUES (13466, 'TR013466', '大澳渔村', '阳江', '广东', '文化打卡', '冬季', 10, 1, 804.00, '否', 4, '10月去的大澳渔村，和朋友出行。地点在阳江，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约804元，氛围感不错。景点印象：东平大澳渔村是一个古老的渔港，位于阳东县东平镇东南，史称“六澳之首”，是中国古代南方“海上丝绸之路”的必经港口。昔日港口商贸繁盛，与广州的“十三行”相并列，史称“十三行尾”。\n大澳渔村至今仍然保持古渔村风貌，遗迹众多，古色古香，为…整体感受是体验挺好，周末来刚好。二刷意愿：否。', '2%', 73);
