INSERT INTO `travel_review` VALUES (13473, 'TR013473', '李家龙宫遗址', '天水', '甘肃', '拍照旅行', '夏季', 5, 1, 341.00, '否', 4, '5月去的李家龙宫遗址，和朋友出行。地点在天水，地铁到达方便，现场游客较多。这次玩了1天，人均花费约341元，氛围感不错。景点印象：唐朝中叶在这里建有上、中、下三组雄伟的建筑，称为\"李家龙宫\"，殿堂林立，建筑巍峨，规模宏大，且规格较高，自古以来，李姓后裔均在此祭祀祖先，其中主祭堂悬挂\"陇西堂\"匾额。整体感受是还蛮满意，可以安排半天到一天。二刷意愿：否。', '2%', 43);
