INSERT INTO `travel_review` VALUES (13477, 'TR013477', '黎都公园', '长治', '山西', '周末短途', '秋季', 8, 6, 1829.00, '是', 3, '8月去的黎都公园，情侣出行。地点在长治，打车比较省心，现场人流量适中。这次玩了6天，人均花费约1829元，夜景表现很好。景点印象：黎都-羊头岭，又叫黎侯岭，面积约6平方公里，岭上最高点海拔1047米，清光绪版《长治县志》记载：“黎侯岭，县西南三十里，黎泉出焉，有黎侯亭；诸山皆石，此独土山。”\n远古时期，华夏始祖炎帝率领其部落顺河东下，登上太行山，进入现在的长治县境…整体感受是中规中矩，按需选择。二刷意愿：是。', '0%', 51);
