INSERT INTO `travel_review` VALUES (13482, 'TR013482', '遂昌金矿国家矿山公园', '丽水', '浙江', '亲子出游', '春季', 12, 1, 192.00, '否', 2, '12月去的遂昌金矿国家矿山公园，一个人出行。地点在丽水，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约192元，拍照很出片。景点印象：坐上小火车进入矿洞，走进明代金窟，过一把矿工瘾。 拿着小盆子去金池淘金，抱一抱25斤的大金砖，讨个好彩头。整体感受是体验偏一般，建议谨慎前往。二刷意愿：否。', '4%', 73);
