INSERT INTO `travel_review` VALUES (13518, 'TR013518', '灵光寺', '梅州', '广东', '深度游', '夏季', 4, 1, 584.00, '否', 4, '4月去的灵光寺，情侣出行。地点在梅州，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约584元，拍照很出片。景点印象：该寺原名圣寿寺，是广东省四大名刹之一，相传为唐代懿宗咸通年间高僧潘了拳创建，至今已有一千多年历史。生死树、菠萝顶、顶无叶合称灵光三绝，无笃石螺、片生熟鱼、五色雀合称灵光三奇。整体感受是还蛮满意，推荐来看看。二刷意愿：否。', '35%', 65);
