INSERT INTO `travel_review` VALUES (13537, 'TR013537', '凤凰山龛群', '济源', '河南', '文化打卡', '夏季', 3, 3, 403.00, '否', 5, '3月去的凤凰山龛群，一个人出行。地点在济源，地铁到达方便，现场游客较多。这次玩了3天，人均花费约403元，拍照很出片。景点印象：凤凰山龛群\n孤山东面，山梁褶皱起伏，犹如凤凰展翅，洼前有一山峰突起，恰似凤头，故名凤凰山。峰顶有祖师庙，山洼中有夫子崖、老君龛、娘娘龛十多处宗教文化胜迹，吸引着众多善男信女虔诚朝拜，香火非常旺盛。整体感受是特别满意，以后还会来。二刷意愿：否。', '0%', 105);
