INSERT INTO `travel_review` VALUES (13582, 'TR013582', '渔湖景区', '和田', '新疆', '城市漫游', '春季', 2, 2, 873.00, '否', 5, '2月去的渔湖景区，情侣出行。地点在和田，地铁到达方便，现场人流量适中。这次玩了2天，人均花费约873元，历史文化气息浓。景点印象：鱼湖位于塔克拉玛干沙漠南缘的民丰县境内，鱼湖维吾尔语\"比勒克力克\"，意思是有鱼的地方。出县城沿315国道东行40公里处，距沙漠公路终端13公里。鱼湖是民丰县重要的水产基地，又是人们向往的旅游景区。\n鱼湖总长20多公里，宽约1.2-2.0公里，湖泊面…整体感受是挺惊喜，很推荐。二刷意愿：否。', '0%', 91);
