INSERT INTO `travel_review` VALUES (13597, 'TR013597', '白鹭保护区', '宿迁', '江苏', '深度游', '冬季', 9, 1, 146.00, '否', 5, '9月去的白鹭保护区，一个人出行。地点在宿迁，公交换乘方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约146元，氛围感不错。景点印象：洪泽农场鸟类自然保护区处于泗洪县东南，处于徐洪河和安东河下游，总面积5.22平方公里，核心区58.4公顷。2001年经江苏省人民政府批准列入洪泽湖湿地升级自然保护区。鸟类保护区季风显著，气候温和、光照充足。湿地常年水深0.6米，水体清澈透明。物…整体感受是超出预期，很推荐。二刷意愿：否。', '0%', 57);
