INSERT INTO `travel_review` VALUES (13618, 'TR013618', '张北坝上草原', '张家口', '河北', '文化打卡', '冬季', 10, 1, 544.00, '是', 5, '10月去的张北坝上草原，情侣出行。地点在张家口，自驾停车需要提前规划，现场人流量适中。这次玩了1天，人均花费约544元，拍照很出片。景点印象：蓝天、白云、草地和羊群完美结合，在草原上走走看看，拍拍照片。 白天在草原上骑马，晚上参加篝火晚会，吃着烤全羊。 参加夏季张北草原音乐节，享受摇滚音乐的魅力。整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 64);
