INSERT INTO `travel_review` VALUES (13620, 'TR013620', '龙虎山风景区', '鹰潭', '江西', '周末短途', '夏季', 3, 2, 671.00, '是', 5, '3月去的龙虎山风景区，和家人出行。地点在鹰潭，公交换乘方便，现场人流量适中。这次玩了2天，人均花费约671元，拍照很出片。景点印象：道教的发源地，可探寻道教文化遗迹，观赏风水极好的自然风光。 乘竹筏在泸溪河上看两岸丹霞地貌山景，感觉非常棒。 在仙水岩看升棺表演，以及神秘的古越人崖墓悬棺。整体感受是挺惊喜，很推荐。二刷意愿：是。', '70%', 85);
