INSERT INTO `travel_review` VALUES (13627, 'TR013627', '峰岩山寨', '伊春', '黑龙江', '文化打卡', '春季', 2, 5, 1394.00, '是', 5, '2月去的峰岩山寨，一个人出行。地点在伊春，公交换乘方便，现场高峰时段比较拥挤。这次玩了5天，人均花费约1394元，历史文化气息浓。景点印象：峰岩山寨位于黑龙江伊春市金山屯区，该度假村具有原始自然风光，群山环绕，森林繁茂，度假村内设有山泉湖和俄式木刻楞别墅等配套设施。屋内陈设十分别致，吸引了众多游客前来观光旅游。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '2%', 73);
