INSERT INTO `travel_review` VALUES (13659, 'TR013659', '石海湾青皮林自然保护区', '万宁', '海南', '拍照旅行', '夏季', 3, 1, 284.00, '是', 4, '3月去的石海湾青皮林自然保护区，和朋友出行。地点在万宁，自驾停车需要提前规划，现场游客较多。这次玩了1天，人均花费约284元，氛围感不错。景点印象：1988年8月24日礼纪青皮林自然保护区被海南省人民政府宣布为海南省第一批省级重点风景名胜区和自然保护区。面积1．6万亩，建于1980年7月。建立此保护区的主要目的，在于保护海南热带森林的贵重树种青皮树。青皮树为龙脑香料，树高可达30米，胸径可达…整体感受是还蛮满意，可以安排半天到一天。二刷意愿：是。', '0%', 78);
