INSERT INTO `travel_review` VALUES (13686, 'TR013686', '宋氏祖居', '文昌', '海南', '周末短途', '秋季', 6, 2, 623.00, '是', 5, '6月去的宋氏祖居，一个人出行。地点在文昌，公交换乘方便，现场人流量适中。这次玩了2天，人均花费约623元，氛围感不错。景点印象：宋氏祖居位于文昌市昌洒镇古路园村，距海口市约80公里，坐落在一片果树环抱的山丘上，周围绿树成荫，环境幽静。 国母宋庆龄的高祖、曾祖、祖父3代都居于此地，其父宋耀如于1861年出生在这里。\n为纪念宋庆龄及其家族在中国近现代历史上留下的深远影…整体感受是挺惊喜，很推荐。二刷意愿：是。', '9%', 102);
