INSERT INTO `travel_review` VALUES (13715, 'TR013715', '须弥山石窟', '固原', '宁夏', '亲子出游', '春季', 2, 3, 1307.00, '否', 3, '2月去的须弥山石窟，和家人出行。地点在固原，打车比较省心，现场高峰时段比较拥挤。这次玩了3天，人均花费约1307元，拍照很出片。景点印象：这里有北魏到隋唐各个朝代不同风格的石窟。 唐代大佛楼内的佛像，比云冈和龙门石窟的主佛像还高大。整体感受是体验一般，避开高峰更好。二刷意愿：否。', '41%', 91);
INSERT INTO `travel_review` VALUES (13716, 'TR013716', '清水泉旅游度假村', '昌吉', '新疆', '深度游', '秋季', 8, 1, 537.00, '否', 5, '8月去的清水泉旅游度假村，和家人出行。地点在昌吉，公交换乘方便，现场人流量适中。这次玩了1天，人均花费约537元，氛围感不错。景点印象：位于硫磺沟镇以南8公里处，头屯河西岸，依山傍水，占地面积45708平方米，约67亩，总建筑面积1630平方米，景区内有一眼泉水涌出地面，甘甜清澈，潺潺不息，得名清水泉。 泉水蜿蜒流淌，形成多处天然水潭，泉水叮咚，自然回响。度假村内野生植被繁盛…整体感受是超出预期，以后还会来。二刷意愿：否。', '0%', 62);
