INSERT INTO `travel_review` VALUES (13733, 'TR013733', '透龙山', '伊春', '黑龙江', '拍照旅行', '冬季', 10, 3, 1011.00, '是', 5, '10月去的透龙山，一个人出行。地点在伊春，地铁到达方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约1011元，历史文化气息浓。景点印象：透龙山庄位于小兴安岭南麓的铁力市，距哈市240公里，乘火车、汽车只需2-3小时。这里有神秘的千年古洞，罕见的奇石怪树，秀丽的湖光山色，甘甜的清泉溪水，宝贵的原始湿地。是您休闲度假、旅游观光的理想去处。这里天常蓝、水常清、山常绿，有天然\"…整体感受是特别满意，很推荐。二刷意愿：是。', '0%', 64);
