INSERT INTO `travel_review` VALUES (13833, 'TR013833', '江西省国际体育健身运动中心', '宜春', '江西', '拍照旅行', '春季', 1, 1, 779.00, '是', 4, '1月去的江西省国际体育健身运动中心，和朋友出行。地点在宜春，自驾停车需要提前规划，现场人不算多。这次玩了1天，人均花费约779元，拍照很出片。景点印象：江西省国际体育健身运动中心，位于江西南方环保机制总公司生产科研基地奉新县境内越山脚下，距省会南昌市80公里，占地面积10平方公里，境内丘陵起伏、森林密布、清澈的潦河贯穿全境，是天然的健身休闲胜地，既有自然风光，又有现代特色。\n本中心隶…整体感受是还蛮满意，可以安排半天到一天。二刷意愿：是。', '0%', 88);
