INSERT INTO `travel_review` VALUES (13848, 'TR013848', '叶赫风景名胜区', '四平', '吉林', '深度游', '夏季', 4, 2, 344.00, '否', 5, '4月去的叶赫风景名胜区，和家人出行。地点在四平，打车比较省心，现场人不算多。这次玩了2天，人均花费约344元，夜景表现很好。景点印象：叶赫风景名胜区位于吉辽两省结合部，吉林省梨树县东南部――叶赫满族镇内，是连接开发区内山门、二龙湖风景区旅游线的纽带。总面积 68 平方公里，集满族历史文化特色与自然山水风光于一体，风格独特，是我国北方少有的旅游胜地。\n叶赫，是满族的重…整体感受是挺惊喜，很推荐。二刷意愿：否。', '0%', 63);
INSERT INTO `travel_review` VALUES (13849, 'TR013849', '长江三峡', '宜昌', '湖北', '亲子出游', '冬季', 11, 2, 635.00, '是', 5, '11月去的长江三峡，一个人出行。地点在宜昌，地铁到达方便，现场人不算多。这次玩了2天，人均花费约635元，夜景表现很好。景点印象：长江三峡是万里长江大峡谷之一，其间有三个国家5A级旅游景区，名胜古迹众多。整体感受是特别满意，以后还会来。二刷意愿：是。', '0%', 69);
