INSERT INTO `travel_review` VALUES (13905, 'TR013905', '伊斯兰商街', '呼和浩特', '内蒙古', '拍照旅行', '秋季', 6, 2, 733.00, '是', 5, '6月去的伊斯兰商街，和朋友出行。地点在呼和浩特，地铁到达方便，现场游客较多。这次玩了2天，人均花费约733元，历史文化气息浓。景点印象：汇聚当地宗教风格建筑，感受千百年浓厚的宗教文化。整体感受是挺惊喜，很推荐。二刷意愿：是。', '30%', 85);
