INSERT INTO `travel_review` VALUES (13907, 'TR013907', '箭竹海', '阿坝', '四川', '亲子出游', '冬季', 10, 4, 1078.00, '是', 5, '10月去的箭竹海，一个人出行。地点在阿坝，公交换乘方便，现场高峰时段比较拥挤。这次玩了4天，人均花费约1078元，夜景表现很好。景点印象：电影《英雄》的取景地之一，有大量的箭竹，是大熊猫喜欢的食物。整体感受是挺惊喜，很推荐。二刷意愿：是。', '22%', 86);
INSERT INTO `travel_review` VALUES (13908, 'TR013908', '禹帽峰', '临汾', '山西', '深度游', '春季', 12, 6, 1575.00, '否', 5, '12月去的禹帽峰，情侣出行。地点在临汾，公交换乘方便，现场高峰时段比较拥挤。这次玩了6天，人均花费约1575元，夜景表现很好。景点印象：在壶口瀑布东岸，龙王庙后，有一座孤峰，犹如天上飘下的一顶帽子扣在壶口岸边。\n在夕阳余辉照射下，远远望去，它似乎在风中悠悠而动。在光线渐暗的时候，它又似乎飘飘欲下，颇有清幽之感。这座孤峰．就是石帽山，又叫“禹帽峰”。传说这座孤峰是禹…整体感受是超出预期，以后还会来。二刷意愿：否。', '1%', 100);
INSERT INTO `travel_review` VALUES (13909, 'TR013909', '金银岛', '汕头', '广东', '文化打卡', '冬季', 9, 1, 526.00, '是', 5, '9月去的金银岛，一个人出行。地点在汕头，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约526元，夜景表现很好。景点印象：金银岛三面环海，碧波荡漾，岛上曲径通幽，阴凉无比。整体感受是特别满意，以后还会来。二刷意愿：是。', '10%', 84);
