INSERT INTO `travel_review` VALUES (13912, 'TR013912', '大西路', '镇江', '江苏', '周末短途', '秋季', 8, 1, 225.00, '是', 5, '8月去的大西路，一个人出行。地点在镇江，公交换乘方便，现场人不算多。这次玩了1天，人均花费约225元，氛围感不错。景点印象：大西路是中国江苏省镇江市的一条著名街道，为著名的商业区，东西走向，东起解放路，西至伯先路、西津古渡，全长1959米，宽度为10-12米。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '1%', 121);
