INSERT INTO `travel_review` VALUES (13914, 'TR013914', '洪江市沅神度假区星空庭院', '怀化', '湖南', '亲子出游', '冬季', 9, 3, 1065.00, '是', 4, '9月去的洪江市沅神度假区星空庭院，和朋友出行。地点在怀化，打车比较省心，现场高峰时段比较拥挤。这次玩了3天，人均花费约1065元，夜景表现很好。景点印象：景点本身有一定特色整体感受是整体不错，推荐来看看。二刷意愿：是。', '0%', 68);
INSERT INTO `travel_review` VALUES (13915, 'TR013915', '大桥景区', '丹东', '辽宁', '文化打卡', '夏季', 3, 3, 705.00, '是', 5, '3月去的大桥景区，和朋友出行。地点在丹东，自驾停车需要提前规划，现场游客较多。这次玩了3天，人均花费约705元，拍照很出片。景点印象：鸭绿江断桥是鸭绿江上第一桥，一九零九年五月动工，一九一一年十月竣工，由当时殖民机构-----日本驻朝总督府铁道所建。始为铁路桥，长九百四十四点二米，宽十一米，共十二孔。从中方数第四孔为开闭梁，以四号墩为周，可旋转九十度，便于过往船只航…整体感受是特别满意，很推荐。二刷意愿：是。', '3%', 83);
INSERT INTO `travel_review` VALUES (13916, 'TR013916', '大桂山', '贺州', '广西', '周末短途', '春季', 12, 2, 687.00, '是', 5, '12月去的大桂山，情侣出行。地点在贺州，公交换乘方便，现场人不算多。这次玩了2天，人均花费约687元，氛围感不错。景点印象：位于贺州市南面，距市区40公里，公园占地3000公倾，是桂东、桂林两地区唯一拥有成片森林的旅游度假胜地。公园内林海茫茫，山水如画，鸟语花香，风景绮丽，集森林、奇峰、雾海、垂岩、飞瀑、高峡平温、天然矿泉水于一体。还有人文景观和优美的神话传…整体感受是特别满意，以后还会来。二刷意愿：是。', '0%', 107);
INSERT INTO `travel_review` VALUES (13917, 'TR013917', '雅丹地质公园', '酒泉', '甘肃', '文化打卡', '夏季', 4, 2, 884.00, '是', 5, '4月去的雅丹地质公园，和朋友出行。地点在酒泉，打车比较省心，现场高峰时段比较拥挤。这次玩了2天，人均花费约884元，历史文化气息浓。景点印象：观赏造型各异的雅丹地貌群，景色奇幻壮观，是拍出摄影大片的绝妙地点。整体感受是特别满意，很推荐。二刷意愿：是。', '49%', 97);
INSERT INTO `travel_review` VALUES (13918, 'TR013918', '曹操公园', '亳州', '安徽', '拍照旅行', '春季', 1, 3, 953.00, '否', 5, '1月去的曹操公园，和朋友出行。地点在亳州，打车比较省心，现场人流量适中。这次玩了3天，人均花费约953元，历史文化气息浓。景点印象：曹操公园，过去称曹氏公园，位于安徽省亳州市2010年改名为曹操公园，因园内有曹操家族墓群而得名。公园占地300亩，建筑为仿汉建筑，气势恢宏。公园共分为纪念区、陵墓区、静休区、游乐区四部分。纪念区以曹操纪念馆为主体，面积2200平方米，内置曹…整体感受是超出预期，很推荐。二刷意愿：否。', '16%', 84);
