INSERT INTO `travel_review` VALUES (13958, 'TR013958', '湾头伊斯兰教徒墓葬群', '万宁', '海南', '深度游', '春季', 12, 2, 800.00, '否', 4, '12月去的湾头伊斯兰教徒墓葬群，和家人出行。地点在万宁，打车比较省心，现场游客较多。这次玩了2天，人均花费约800元，氛围感不错。景点印象：位于陵水胰与三亚市郊接壤的陵水湾畔海滩上，其墓葬群延伸到三亚市境的番岭坡共有四十多座。据史载，早在隋唐代时，中东一带阿拉伯各国的穆斯林人开始驾船跨越印度洋，经我国南海到达泉州、广州一带经商贸易。当时海南岛南部到东部沿海地带正处于先…整体感受是整体不错，周末来刚好。二刷意愿：否。', '0%', 72);
