INSERT INTO `travel_review` VALUES (13961, 'TR013961', '吞力黑衣壮民族风情园', '百色', '广西', '周末短途', '秋季', 8, 1, 516.00, '否', 2, '8月去的吞力黑衣壮民族风情园，情侣出行。地点在百色，公交换乘方便，现场人流量适中。这次玩了1天，人均花费约516元，氛围感不错。景点印象：吞力屯地处那坡县北部的石山区，属城厢镇龙华村所管辖，全屯共57户250多人，为壮族支系“黑衣壮”的聚居地之一。由于居住条件恶劣，交通不便，信息闭塞，2002年以前该屯年人均纯收入仅900元，属城厢镇典型的特困屯之一。 时光荏苒，斗转星移，吞力…整体感受是体验偏一般，建议谨慎前往。二刷意愿：否。', '2%', 44);
