INSERT INTO `travel_review` VALUES (13968, 'TR013968', '梓童山鬼谷洞', '淄博', '山东', '文化打卡', '春季', 1, 3, 1156.00, '否', 5, '1月去的梓童山鬼谷洞，一个人出行。地点在淄博，打车比较省心，现场高峰时段比较拥挤。这次玩了3天，人均花费约1156元，夜景表现很好。景点印象：该风景区地处205国道淄博段梓童山车站以东3.5公里处的藏梓村东，占地面积100公顷。该风景区再现了鬼谷子在梓童山鬼谷洞授徒讲学、叱咤风云的历史风貌和北宋孝子王樵以忠孝流芳千谷的遗韵，整个景区群山环抱，绿树成荫，流水潺潺，鸟语花香，自然景…整体感受是超出预期，很推荐。二刷意愿：否。', '0%', 108);
