INSERT INTO `travel_review` VALUES (14020, 'TR014020', '加榜梯田', '黔东南', '贵州', '文化打卡', '秋季', 8, 6, 1754.00, '是', 5, '8月去的加榜梯田，情侣出行。地点在黔东南，公交换乘方便，现场人不算多。这次玩了6天，人均花费约1754元，夜景表现很好。景点印象：加榜梯田集天下梯田之精华，它比云南元阳梯田更加秀丽，比广西龙胜梯田更加壮观，极具魅力。整体感受是特别满意，以后还会来。二刷意愿：是。', '5%', 91);
INSERT INTO `travel_review` VALUES (14021, 'TR014021', '禾木风景区', '阿勒泰', '新疆', '城市漫游', '冬季', 10, 2, 862.00, '是', 3, '10月去的禾木风景区，和家人出行。地点在阿勒泰，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了2天，人均花费约862元，氛围感不错。景点印象：木屋、河流、森林构成的童话世界，每年九十月份有漫山黄叶，观景台可观赏绝美全景。整体感受是还可以，别抱太高期待。二刷意愿：是。', '49%', 42);
