INSERT INTO `travel_review` VALUES (14025, 'TR014025', '太极湖村', '宣城', '安徽', '周末短途', '冬季', 10, 6, 1849.00, '否', 4, '10月去的太极湖村，一个人出行。地点在宣城，打车比较省心，现场游客较多。这次玩了6天，人均花费约1849元，夜景表现很好。景点印象：以砖雕门楼取胜的徽派古村，精细的砖雕能叠加到九层之多。 章氏宗祠木雕精美，里面的明代蟠龙香亭上，六条蟠龙栩栩如生。 整个村庄像幅太极图，4月可赏油菜花。整体感受是整体不错，可以安排半天到一天。二刷意愿：否。', '5%', 55);
