INSERT INTO `travel_review` VALUES (14088, 'TR014088', '恒山', '大同', '山西', '城市漫游', '夏季', 3, 2, 704.00, '是', 5, '3月去的恒山，一个人出行。地点在大同，打车比较省心，现场高峰时段比较拥挤。这次玩了2天，人均花费约704元，夜景表现很好。景点印象：“五岳”中的北岳，登上主峰天峰岭俯瞰群山，豁然开朗。 手脚并用爬上恒宗殿前的103级陡阶，体验恒山的人文魅力。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '50%', 45);
