INSERT INTO `travel_review` VALUES (14096, 'TR014096', '避暑山庄', '承德', '河北', '深度游', '春季', 2, 2, 617.00, '否', 4, '2月去的避暑山庄，情侣出行。地点在承德，地铁到达方便，现场人流量适中。这次玩了2天，人均花费约617元，夜景表现很好。景点印象：中国现存最大的古典皇家园林，面积是颐和园的两倍。 看气派的皇家建筑，还有仿江南园林的湖区。 “烟雨楼”是电视剧《还珠格格》里“漱芳斋”的取景地。整体感受是还蛮满意，推荐来看看。二刷意愿：否。', '35%', 67);
INSERT INTO `travel_review` VALUES (14097, 'TR014097', '懿德太子墓', '咸阳', '陕西', '文化打卡', '夏季', 3, 3, 956.00, '是', 5, '3月去的懿德太子墓，和朋友出行。地点在咸阳，公交换乘方便，现场人不算多。这次玩了3天，人均花费约956元，氛围感不错。景点印象：武则天孙子的陵墓，是距离乾陵最近的陪葬墓。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '20%', 87);
INSERT INTO `travel_review` VALUES (14098, 'TR014098', '千叶湖风景区', '通化', '吉林', '文化打卡', '夏季', 3, 2, 700.00, '是', 5, '3月去的千叶湖风景区，一个人出行。地点在通化，自驾停车需要提前规划，现场游客较多。这次玩了2天，人均花费约700元，拍照很出片。景点印象：吉林通化千叶湖冰雪旅游大世界，位于通化市区江南1公里处，属城区滑雪场。集吃、喝、玩、住一体，冰雪兼备，以旅游为主，适合大众要求的冰雪旅游大世界，项目全面、安全、刺激，占地16000平方米，是全国最早的第一座日伪时期修建的滑雪场。经长白山…整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 80);
