INSERT INTO `travel_review` VALUES (14102, 'TR014102', '石漫滩', '平顶山', '河南', '拍照旅行', '冬季', 9, 2, 726.00, '是', 5, '9月去的石漫滩，和家人出行。地点在平顶山，打车比较省心，现场人流量适中。这次玩了2天，人均花费约726元，历史文化气息浓。景点印象：是在1987年拟建的“石漫滩森林植物园总体规划方案”的基础上，经国家林业部审定，于1992年2月以林造批字（92）154号文批复同意建立的45处国家级森林公园之一。\n位置辖区：森林公园位于河南省中部、舞钢南部、伏牛山东麓，黄淮平原西侧。包括石漫滩…整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 79);
