INSERT INTO `travel_review` VALUES (14107, 'TR014107', '逢简水乡', '佛山', '广东', '城市漫游', '春季', 2, 6, 1653.00, '否', 5, '2月去的逢简水乡，和家人出行。地点在佛山，地铁到达方便，现场高峰时段比较拥挤。这次玩了6天，人均花费约1653元，历史文化气息浓。景点印象：岭南水乡一绝，有“广东周庄”之称，建于宋代的明远桥非常值得一看。整体感受是挺惊喜，以后还会来。二刷意愿：否。', '6%', 69);
INSERT INTO `travel_review` VALUES (14108, 'TR014108', '稻香园度假村', '阿克苏', '新疆', '周末短途', '冬季', 10, 5, 1237.00, '否', 3, '10月去的稻香园度假村，情侣出行。地点在阿克苏，自驾停车需要提前规划，现场人流量适中。这次玩了5天，人均花费约1237元，夜景表现很好。景点印象：稻香园度假村位于温宿县郊外2公里处的托呼啦村，占地面积80亩，其中绿树面积就达60亩。度假村里建有大木屋、小木屋、演义厅、宾馆、蒙古包、帐篷、游泳馆、钓鱼池、棋牌室、会议室、健身室、网球室、乒乓球室、卡拉OK、餐厅等设施和景点，集食、住…整体感受是还可以，避开高峰更好。二刷意愿：否。', '0%', 81);
