INSERT INTO `travel_review` VALUES (14123, 'TR014123', '拉甫乔克故城', '哈密', '新疆', '深度游', '夏季', 4, 4, 1011.00, '否', 5, '4月去的拉甫乔克故城，和家人出行。地点在哈密，地铁到达方便，现场人流量适中。这次玩了4天，人均花费约1011元，历史文化气息浓。景点印象：拉甫乔克故城位于哈密市西约60千米的四堡乡喀尔鲁克渠两岸。故城由渠东面的南、北两城和渠西一城组成。渠西一城仅存长约100米的东城墙遗址。渠东之北城，南北约180米，东西约150米，城墙残高2米，宽3米，城四角有残存的了望台。城内有土墩和房屋残…整体感受是特别满意，值得专门打卡。二刷意愿：否。', '0%', 92);
