INSERT INTO `travel_review` VALUES (14147, 'TR014147', '海心沙亚运公园', '广州', '广东', '城市漫游', '春季', 12, 4, 1101.00, '否', 3, '12月去的海心沙亚运公园，和朋友出行。地点在广州，打车比较省心，现场人流量适中。这次玩了4天，人均花费约1101元，历史文化气息浓。景点印象：夜景非常漂亮，可以观赏珠江两岸璀璨夜景，夜游广州的好去处。整体感受是体验一般，避开高峰更好。二刷意愿：否。', '8%', 6);
INSERT INTO `travel_review` VALUES (14148, 'TR014148', '光明顶', '黄山', '安徽', '文化打卡', '春季', 12, 3, 1022.00, '否', 5, '12月去的光明顶，情侣出行。地点在黄山，打车比较省心，现场人不算多。这次玩了3天，人均花费约1022元，拍照很出片。景点印象：黄山第二高峰，视野开阔，登顶可看四周群峰、日出、日落、云海。整体感受是挺惊喜，以后还会来。二刷意愿：否。', '34%', 60);
