INSERT INTO `travel_review` VALUES (14187, 'TR014187', '封江生态旅游区', '随州', '湖北', '深度游', '春季', 2, 2, 632.00, '否', 5, '2月去的封江生态旅游区，和家人出行。地点在随州，自驾停车需要提前规划，现场游客较多。这次玩了2天，人均花费约632元，历史文化气息浓。景点印象：封江水库两岸山峦连绵起伏，库汊水岛犬牙交错，形成了封江独具特色的库区风光。27公里长的水域犹如一幅画廊，14万亩山场四季如画：春季山花烂漫，映山红满山遍野；夏日绿树成荫，满目青翠；秋天叶红果熟，四处飘香；冬时雪压青松，银装素裹。库区上…整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '0%', 72);
