INSERT INTO `travel_review` VALUES (14189, 'TR014189', '谢鲁天堂温泉休闲度假村', '玉林', '广西', '城市漫游', '冬季', 9, 3, 922.00, '是', 5, '9月去的谢鲁天堂温泉休闲度假村，和朋友出行。地点在玉林，地铁到达方便，现场游客较多。这次玩了3天，人均花费约922元，历史文化气息浓。景点印象：距县城25公里，离玉林市70公里，至华南第一大港口城市湛江约133公里，是按国际四星标准设计和建设的、以先进温泉养生理念打造的精致休闲、保健养生的建筑类人文风景旅游区。\n度假中心内有被称为“岭南第一泉”、岭南唯一的可泡可喝的飞龙山温矿泉，…整体感受是挺惊喜，很推荐。二刷意愿：是。', '12%', 63);
INSERT INTO `travel_review` VALUES (14190, 'TR014190', '河南博物院', '郑州', '河南', '深度游', '春季', 12, 3, 233.00, '否', 5, '12月去的河南博物院，情侣出行。地点在郑州，自驾停车需要提前规划，现场人不算多。这次玩了3天，人均花费约233元，拍照很出片。景点印象：观赏先秦时代的神器莲鹤方壶、云纹铜禁、妇好鸮尊，聆听悠远神秘的中国古乐。整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '18%', 104);
