INSERT INTO `travel_review` VALUES (14206, 'TR014206', '寿春城遗址', '六安', '安徽', '城市漫游', '夏季', 4, 1, 545.00, '否', 2, '4月去的寿春城遗址，情侣出行。地点在六安，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约545元，氛围感不错。景点印象：寿春城遗址位于安徽省寿县城关寿春镇、城南九龙乡境内。寿春城作为战国时期楚国的最后一座都城，有着非常丰富的楚文化遗存。\n遗址布局方整规矩，总面积26．35平方公里，其规模仅次于燕下都。该城东、西、北三面临水，南有西南小城。城内呈矩形分成1…整体感受是没达到预期，不建议高峰来。二刷意愿：否。', '0%', 33);
