INSERT INTO `travel_review` VALUES (14212, 'TR014212', '灵岩景区', '温州', '浙江', '亲子出游', '冬季', 11, 4, 1100.00, '是', 5, '11月去的灵岩景区，和家人出行。地点在温州，地铁到达方便，现场游客较多。这次玩了4天，人均花费约1100元，夜景表现很好。景点印象：“雁荡三绝”中规模最小，却景观丰富的一处，奇峰怪石让人浮想联翩。 看一场“灵岩飞渡”表演，崖壁和钢索上的高难度表演夺人眼球。 探访卧龙谷，在断肠崖回味《神雕侠侣》中小龙女纵身一跃的场景。整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 84);
