INSERT INTO `travel_review` VALUES (14243, 'TR014243', '拉乌山', '昌都', '西藏', '周末短途', '春季', 1, 4, 994.00, '否', 5, '1月去的拉乌山，和家人出行。地点在昌都，打车比较省心，现场人不算多。这次玩了4天，人均花费约994元，氛围感不错。景点印象：拉乌山是川藏公路318国道西藏芒康境内的一个平缓的山口,山顶有一个比较壮观的经幡阵，整整占了一个山头。 拉乌山口海拔4338米，但站在垭口上如果有天眼的话就可俯看金沙江和澜沧江了。整体感受是超出预期，以后还会来。二刷意愿：否。', '16%', 83);
