INSERT INTO `travel_review` VALUES (14245, 'TR014245', '御河生态园', '大同', '山西', '拍照旅行', '冬季', 9, 2, 429.00, '否', 4, '9月去的御河生态园，和家人出行。地点在大同，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了2天，人均花费约429元，历史文化气息浓。景点印象：御河生态园，南北长5.5公里，使昔日贫瘠、荒凉的御河两岸重现风光，一条河流能给予一座城市以灵魂，河畔生态园使城市物华得以体现，城市的审美和灵性凭河而含，籍园而展，御河蓄水，御园绽绿。整体感受是整体不错，可以安排半天到一天。二刷意愿：否。', '1%', 51);
