INSERT INTO `travel_review` VALUES (14301, 'TR014301', '白哈巴', '北疆', '新疆', '深度游', '秋季', 6, 1, 590.00, '否', 4, '6月去的白哈巴，一个人出行。地点在北疆，地铁到达方便，现场人不算多。这次玩了1天，人均花费约590元，氛围感不错。景点印象：一个五颜六色的童话世界，傍晚光线柔和，村旁雪山泛红，北疆拍摄日落的最佳地带。整体感受是整体不错，可以安排半天到一天。二刷意愿：否。', '40%', 43);
INSERT INTO `travel_review` VALUES (14302, 'TR014302', '老君犁沟', '渭南', '陕西', '文化打卡', '夏季', 5, 3, 1044.00, '是', 5, '5月去的老君犁沟，和家人出行。地点在渭南，自驾停车需要提前规划，现场游客较多。这次玩了3天，人均花费约1044元，历史文化气息浓。景点印象：整体环境还算干净整体感受是特别满意，很推荐。二刷意愿：是。', '2%', 90);
INSERT INTO `travel_review` VALUES (14303, 'TR014303', '水杉山庄', '广安', '四川', '拍照旅行', '夏季', 4, 1, 517.00, '否', 2, '4月去的水杉山庄，情侣出行。地点在广安，打车比较省心，现场人不算多。这次玩了1天，人均花费约517元，拍照很出片。景点印象：水杉山庄位于华蓥市天池镇仰天窝，属华蓥山森林公园一期工程，1997年建成使用。山庄地处高山，四周环绕着上万亩天然白夹竹、阔叶林和杉木、马尾松人工林，分布有“植物活化石”水杉林、枫树林、柳杉林、花竹和小石林等景点，冬可观雪景，盛夏可避暑…整体感受是略失望，建议谨慎前往。二刷意愿：否。', '0%', 52);
