INSERT INTO `travel_review` VALUES (14370, 'TR014370', '易门龙泉', '玉溪', '云南', '文化打卡', '夏季', 3, 1, 686.00, '否', 2, '3月去的易门龙泉，情侣出行。地点在玉溪，公交换乘方便，现场人不算多。这次玩了1天，人均花费约686元，氛围感不错。景点印象：易门龙泉国家森林公园是1992年国家林业局批准建立的森林公园，公园文化、历史悠久，从留传至今的匾额、楹联和石壁题字考证，早在唐朝末年这里就兴修庙亭，成为滇中夷人文化活动的中心。如今自清朝雍正年间就延续下来的农历“二月二”祭龙庙会，已成…整体感受是略失望，不建议高峰来。二刷意愿：否。', '0%', 29);
