INSERT INTO `travel_review` VALUES (14536, 'TR014536', '龙山', '铁岭', '辽宁', '深度游', '夏季', 5, 1, 406.00, '否', 5, '5月去的龙山，情侣出行。地点在铁岭，公交换乘方便，现场人流量适中。这次玩了1天，人均花费约406元，历史文化气息浓。景点印象：龙山风景名胜区位于铁岭市区中心，是辽宁省省级风景名胜区。风景区分为龙首山、柴河、帽山三大景区，总面积9.47平方公里，其中龙首山景区2.22平方公里，柴河景区2.32平方公里，帽山景区4.93平方公里。1991年龙山风景名胜区已被省政府命名为省级风景…整体感受是特别满意，以后还会来。二刷意愿：否。', '0%', 60);
