INSERT INTO `travel_review` VALUES (14546, 'TR014546', '沈家门渔港', '舟山', '浙江', '文化打卡', '夏季', 5, 2, 961.00, '是', 5, '5月去的沈家门渔港，和家人出行。地点在舟山，打车比较省心，现场人流量适中。这次玩了2天，人均花费约961元，氛围感不错。景点印象：游览舟山诸岛的中转站。吹着海风吃海鲜、喝啤酒，格外惬意。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '18%', 30);
INSERT INTO `travel_review` VALUES (14547, 'TR014547', '仙口', '吉安', '江西', '深度游', '夏季', 4, 5, 1134.00, '是', 5, '4月去的仙口，和家人出行。地点在吉安，打车比较省心，现场高峰时段比较拥挤。这次玩了5天，人均花费约1134元，拍照很出片。景点印象：景区面积494公顷，是一个正规划开发的新景区。这里的山石、温泉、瀑布、高山田园等自然风光和独特的客家风情，引人入胜，让人留连忘返。\n牛头冲、长坪瀑布 牛头冲、长坪两瀑布是仙口景区的一大自然景观。牛头冲瀑布四十余米，长坪瀑布一百八十余米…整体感受是超出预期，值得专门打卡。二刷意愿：是。', '0%', 77);
