INSERT INTO `travel_review` VALUES (14611, 'TR014611', '长白山国际度假区', '白山', '吉林', '周末短途', '秋季', 7, 4, 1167.00, '否', 3, '7月去的长白山国际度假区，情侣出行。地点在白山，公交换乘方便，现场高峰时段比较拥挤。这次玩了4天，人均花费约1167元，夜景表现很好。景点印象：度假小镇位于长白山国际度假区的中心，由滑雪服务中心、大剧院、商业街、娱乐中心、温泉洗浴中心、公寓式酒店及人工湖等设施组成。通过借鉴欧美滑雪小镇的形式，充分体现了国际级旅游度假区的高端品质。 项目的酒店区环绕度假小镇，共同形成旅游度…整体感受是还可以，别抱太高期待。二刷意愿：否。', '2%', 18);
