INSERT INTO `travel_review` VALUES (14618, 'TR014618', '哈尔挠', '白城', '吉林', '文化打卡', '秋季', 7, 4, 1077.00, '否', 5, '7月去的哈尔挠，情侣出行。地点在白城，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了4天，人均花费约1077元，夜景表现很好。景点印象：“哈尔挠”是蒙族语言的音译，意思是黑色的水泡。它位于八百里瀚海的东北部，嫩江的西岸，是莫莫格国家级自然保护区的核心区，是国家A级湿地资源。旅游区内建有哈尔挠水库和哈尔挠旅游度假村。\n哈尔挠水库是1979年8月吉林省水利厅批准修建的。目前…整体感受是超出预期，以后还会来。二刷意愿：否。', '0%', 65);
