INSERT INTO `travel_review` VALUES (14654, 'TR014654', '南凉虎台遗址公园', '西宁', '青海', '拍照旅行', '春季', 1, 3, 725.00, '是', 5, '1月去的南凉虎台遗址公园，和朋友出行。地点在西宁，打车比较省心，现场人流量适中。这次玩了3天，人均花费约725元，氛围感不错。景点印象：东晋十六国时期南凉王朝的阅兵台，历史悠久，可以凭吊怀古。整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 89);
