INSERT INTO `travel_review` VALUES (14657, 'TR014657', '东圳水库', '莆田', '福建', '拍照旅行', '春季', 1, 2, 93.00, '是', 5, '1月去的东圳水库，一个人出行。地点在莆田，公交换乘方便，现场游客较多。这次玩了2天，人均花费约93元，夜景表现很好。景点印象：位于市区西北8公里许的莆田县常太乡东圳尾村，是福建大型水库之一，具有灌溉、防洪、发电、航运、养殖、游览等作用。水库拦河大坝长360米，高58米，顶宽8米，象一座巨大的屏障，横亘在天马、地龙两山峡谷之间，拦住了自仙游九鲤湖奔流而下的溪水，…整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '5%', 63);
INSERT INTO `travel_review` VALUES (14658, 'TR014658', '绍兴博物馆', '绍兴', '浙江', '拍照旅行', '夏季', 5, 1, 254.00, '是', 4, '5月去的绍兴博物馆，和朋友出行。地点在绍兴，公交换乘方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约254元，夜景表现很好。景点印象：小而精致的城市博物馆，可以在这里快速了解吴越历史。整体感受是体验挺好，周末来刚好。二刷意愿：是。', '1%', 46);
