INSERT INTO `travel_review` VALUES (14669, 'TR014669', '云冈石窟', '大同', '山西', '深度游', '冬季', 11, 2, 606.00, '否', 5, '11月去的云冈石窟，和家人出行。地点在大同，打车比较省心，现场高峰时段比较拥挤。这次玩了2天，人均花费约606元，历史文化气息浓。景点印象：中国三大石窟之一，雕刻融合了中西艺术风格，感受北魏艺术精品的魅力。整体感受是特别满意，值得专门打卡。二刷意愿：否。', '82%', 80);
INSERT INTO `travel_review` VALUES (14670, 'TR014670', '鼓楼', '银川', '宁夏', '亲子出游', '春季', 12, 4, 1051.00, '是', 5, '12月去的鼓楼，一个人出行。地点在银川，打车比较省心，现场人不算多。这次玩了4天，人均花费约1051元，拍照很出片。景点印象：闹市区中的百年古建筑，寻觅美食还可一览古迹夜景。整体感受是超出预期，值得专门打卡。二刷意愿：是。', '17%', 94);
INSERT INTO `travel_review` VALUES (14671, 'TR014671', '马勒别墅', '上海', '上海', '城市漫游', '春季', 1, 2, 309.00, '是', 5, '1月去的马勒别墅，情侣出行。地点在上海，打车比较省心，现场人不算多。这次玩了2天，人均花费约309元，氛围感不错。景点印象：浪漫华丽的挪威城堡式建筑，室内装修却又不失中国风情。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '3%', 90);
INSERT INTO `travel_review` VALUES (14672, 'TR014672', '亚丁村', '甘孜藏族自治州', '四川', '城市漫游', '夏季', 5, 3, 1116.00, '是', 4, '5月去的亚丁村，一个人出行。地点在甘孜藏族自治州，地铁到达方便，现场游客较多。这次玩了3天，人均花费约1116元，历史文化气息浓。景点印象：景色绝美，宛若人间仙境，是绝佳的摄影取景地。整体感受是整体不错，可以安排半天到一天。二刷意愿：是。', '6%', 103);
INSERT INTO `travel_review` VALUES (14673, 'TR014673', '甘肃省科学技术厅白银市人民政府共建孵化器', '白银', '甘肃', '文化打卡', '秋季', 8, 5, 1236.00, '是', 5, '8月去的甘肃省科学技术厅白银市人民政府共建孵化器，情侣出行。地点在白银，地铁到达方便，现场高峰时段比较拥挤。这次玩了5天，人均花费约1236元，拍照很出片。景点印象：整体环境还算干净整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 78);
