INSERT INTO `travel_review` VALUES (14676, 'TR014676', '树正瀑布', '阿坝', '四川', '文化打卡', '夏季', 4, 1, 742.00, '是', 4, '4月去的树正瀑布，情侣出行。地点在阿坝，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约742元，氛围感不错。景点印象：进入沟内的第一个瀑布，也是最小的一个，瀑布形状如巨形莲花瓣。整体感受是整体不错，推荐来看看。二刷意愿：是。', '6%', 90);
INSERT INTO `travel_review` VALUES (14677, 'TR014677', '双鸭山东北黑峰保护区', '双鸭山', '黑龙江', '拍照旅行', '夏季', 4, 2, 768.00, '否', 5, '4月去的双鸭山东北黑峰保护区，和朋友出行。地点在双鸭山，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了2天，人均花费约768元，氛围感不错。景点印象：位于黑龙江省饶河境内，面积270000公顷，1980年经黑龙江人民政府批准建立，1997年晋升为国家级，主要保护对象为东北黑蜂及蜜源植物。\n东北黑蜂是20 世纪初由乌苏里江东引入的远东蜂，经长期的自然选择和人工选择，形成的适应黑龙江气候和蜜源特点，…整体感受是特别满意，以后还会来。二刷意愿：否。', '0%', 56);
