INSERT INTO `travel_review` VALUES (14684, 'TR014684', '安乐温泉', '安顺', '贵州', '周末短途', '春季', 2, 1, 323.00, '是', 4, '2月去的安乐温泉，情侣出行。地点在安顺，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约323元，拍照很出片。景点印象：安乐温泉位于关岭花江乐安寨。《永宁州志》载：“一路三井，两旁水极清凉，唯中一井温如鼎沸，冬可濯足，居人常浴于此焉。”温泉处于烂田坝中，长约500米，宽约200米。整体感受是体验挺好，推荐来看看。二刷意愿：是。', '0%', 37);
