INSERT INTO `travel_review` VALUES (14750, 'TR014750', '滇池', '昆明', '云南', '深度游', '春季', 12, 1, 551.00, '是', 5, '12月去的滇池，情侣出行。地点在昆明，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约551元，历史文化气息浓。景点印象：五百里滇池烟波浩渺，登山俯瞰、乘船游湖、漫步喂鸟都非常惬意。整体感受是特别满意，以后还会来。二刷意愿：是。', '32%', 65);
INSERT INTO `travel_review` VALUES (14751, 'TR014751', '勐远仙境', '西双版纳', '云南', '亲子出游', '春季', 2, 3, 1047.00, '否', 2, '2月去的勐远仙境，和家人出行。地点在西双版纳，公交换乘方便，现场游客较多。这次玩了3天，人均花费约1047元，氛围感不错。景点印象：景点本身有一定特色整体感受是没达到预期，可考虑其他景点。二刷意愿：否。', '2%', 34);
INSERT INTO `travel_review` VALUES (14752, 'TR014752', '东圳水库', '莆田', '福建', '亲子出游', '秋季', 8, 3, 703.00, '是', 5, '8月去的东圳水库，情侣出行。地点在莆田，公交换乘方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约703元，夜景表现很好。景点印象：位于市区西北8公里许的莆田县常太乡东圳尾村，是福建大型水库之一，具有灌溉、防洪、发电、航运、养殖、游览等作用。水库拦河大坝长360米，高58米，顶宽8米，象一座巨大的屏障，横亘在天马、地龙两山峡谷之间，拦住了自仙游九鲤湖奔流而下的溪水，…整体感受是超出预期，以后还会来。二刷意愿：是。', '5%', 62);
INSERT INTO `travel_review` VALUES (14753, 'TR014753', '融水田头苗寨', '柳州', '广西', '文化打卡', '夏季', 5, 2, 429.00, '是', 5, '5月去的融水田头苗寨，和家人出行。地点在柳州，打车比较省心，现场人流量适中。这次玩了2天，人均花费约429元，夜景表现很好。景点印象：景点本身有一定特色整体感受是特别满意，以后还会来。二刷意愿：是。', '3%', 87);
INSERT INTO `travel_review` VALUES (14754, 'TR014754', '云石山', '赣州', '江西', '城市漫游', '冬季', 9, 2, 521.00, '否', 4, '9月去的云石山，情侣出行。地点在赣州，自驾停车需要提前规划，现场游客较多。这次玩了2天，人均花费约521元，拍照很出片。景点印象：云石山位于瑞金市西南15公里。1934年7月临时中央政府从沙洲坝迁驻此地小山上的云山古寺，山中风景优美。1934年10月，中央机关编为红军中央纵队，从云石山出发开始长征，因而云石山被称为“长征第一山”。整体感受是整体不错，周末来刚好。二刷意愿：否。', '0%', 87);
INSERT INTO `travel_review` VALUES (14755, 'TR014755', '海湾公园', '厦门', '福建', '文化打卡', '春季', 12, 2, 881.00, '否', 5, '12月去的海湾公园，情侣出行。地点在厦门，打车比较省心，现场人不算多。这次玩了2天，人均花费约881元，拍照很出片。景点印象：可在公园内远眺大海，吹海风，附近的酒吧街更是泡吧族们的最爱。整体感受是特别满意，很推荐。二刷意愿：否。', '2%', 54);
INSERT INTO `travel_review` VALUES (14756, 'TR014756', '王家屏墓', '朔州', '山西', '深度游', '春季', 1, 2, 752.00, '是', 5, '1月去的王家屏墓，和家人出行。地点在朔州，打车比较省心，现场人流量适中。这次玩了2天，人均花费约752元，历史文化气息浓。景点印象：位于山阴县西南15公里的泥河乡河阳堡村南，是明代著名政治家王家屏之墓，为省级重点文物保护单位。王家屏墓占地 10168平方米，规模宏大，地面享堂犹存，有石人、石羊、石马等仪仗及碑石10通，碑文大部分为圣旨加封等内容，现已破坏严重。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 89);
