INSERT INTO `travel_review` VALUES (14765, 'TR014765', '大观公园', '昆明', '云南', '拍照旅行', '秋季', 7, 6, 1717.00, '否', 2, '7月去的大观公园，一个人出行。地点在昆明，地铁到达方便，现场人不算多。这次玩了6天，人均花费约1717元，历史文化气息浓。景点印象：滇池北畔的优美公园，园内古迹众多，尤其大观楼更是闻名全国。整体感受是略失望，建议谨慎前往。二刷意愿：否。', '0%', 59);
