INSERT INTO `travel_review` VALUES (14767, 'TR014767', '广府古城', '邯郸', '河北', '周末短途', '秋季', 8, 2, 621.00, '是', 5, '8月去的广府古城，和家人出行。地点在邯郸，打车比较省心，现场高峰时段比较拥挤。这次玩了2天，人均花费约621元，历史文化气息浓。景点印象：漫步古城，参观大气城墙和城内的古老建筑。 古城四周环绕池水，有芦苇荡、荷塘等，可以拍摄水上城墙的美丽景色。整体感受是特别满意，以后还会来。二刷意愿：是。', '6%', 87);
