INSERT INTO `travel_review` VALUES (14778, 'TR014778', '天童禅寺', '宁波', '浙江', '周末短途', '冬季', 10, 3, 560.00, '否', 5, '10月去的天童禅寺，一个人出行。地点在宁波，自驾停车需要提前规划，现场游客较多。这次玩了3天，人均花费约560元，历史文化气息浓。景点印象：太白山麓的千年古刹，环境清幽，寺院最高处的应真亭风光无限。整体感受是超出预期，很推荐。二刷意愿：否。', '1%', 92);
INSERT INTO `travel_review` VALUES (14779, 'TR014779', '古银州摩崖石刻', '榆林', '陕西', '周末短途', '春季', 1, 1, 471.00, '是', 5, '1月去的古银州摩崖石刻，情侣出行。地点在榆林，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约471元，拍照很出片。景点印象：无定河南岸石崖之上，有“古银州”三字的摩崖石刻，宽8.3米，高3米，每字宽1.5米，高1.8米，字距为1米。\n民国二十三年(1934年)时任县长严建章主持勒石，阴刻楷书，刚健雄宏，蔚为壮观。由本县清末进士高增爵邀请段祺瑞政府总统徐世昌所书。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '1%', 68);
