INSERT INTO `travel_review` VALUES (14823, 'TR014823', '恐龙谷', '长治', '山西', '文化打卡', '秋季', 6, 2, 377.00, '是', 4, '6月去的恐龙谷，和朋友出行。地点在长治，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了2天，人均花费约377元，历史文化气息浓。景点印象：恐龙谷风景区背靠卧虎山，面向卧龙山。卧龙山因形状似虎而且每年秋冬季节登临山顶有时能听到虎啸之声而得名。卧龙山传说年大禹治水时，此山有青龙、黑龙、火龙三条龙盘住山间而得名。恐龙谷风景区共有七处景点：一是乘船游览世界八大奇迹之一红旗渠…整体感受是体验挺好，周末来刚好。二刷意愿：是。', '4%', 38);
