INSERT INTO `travel_review` VALUES (14846, 'TR014846', '骆马湖湖滨浴场', '宿迁', '江苏', '文化打卡', '冬季', 11, 2, 901.00, '否', 5, '11月去的骆马湖湖滨浴场，情侣出行。地点在宿迁，自驾停车需要提前规划，现场人流量适中。这次玩了2天，人均花费约901元，氛围感不错。景点印象：骆马湖湖滨浴场，位于骆马湖东岸，这里水域广阔，水岸浅缓，水波平静，水质清新，透明度居全省淡水湖之最。浴场正在建设成为集休闲、旅游、观光、度假一体的娱乐场所。骆马湖湖滨浴场得天独厚的自然优势，将带来新一轮旅游新浪潮。整体感受是特别满意，很推荐。二刷意愿：否。', '28%', 82);
