INSERT INTO `travel_review` VALUES (14861, 'TR014861', '天梯山景区', '邢台', '河北', '文化打卡', '夏季', 3, 1, 782.00, '否', 3, '3月去的天梯山景区，和家人出行。地点在邢台，公交换乘方便，现场人流量适中。这次玩了1天，人均花费约782元，历史文化气息浓。景点印象：登山走在悬空古桥和吊桥之间，感受天梯山地貌的独特和险峻。 走进一个个形状各异的天然山洞，观看雕像、石刻等古迹。 乘船进入金水洞，观赏古洞内的钟乳石美景。整体感受是还可以，避开高峰更好。二刷意愿：否。', '0%', 20);
