INSERT INTO `travel_review` VALUES (14888, 'TR014888', '老爷岭', '锦州', '辽宁', '亲子出游', '秋季', 8, 5, 1359.00, '否', 4, '8月去的老爷岭，和家人出行。地点在锦州，地铁到达方便，现场人流量适中。这次玩了5天，人均花费约1359元，氛围感不错。景点印象：老爷岭风景区位于闾山西麓，座落在义县东大榆树堡镇境内。是国家级自然保护区。老爷岭建有上下两院，上院有出巡殿、武圣殿、三清殿，建在义县与北宁“山界”处因寺中所塑为关公像，故称老爷庙，山便因庙而得名。附近山势险要，林木葱荫，站在上院远…整体感受是还蛮满意，推荐来看看。二刷意愿：否。', '0%', 56);
