INSERT INTO `travel_review` VALUES (15007, 'TR015007', '南锣鼓巷', '北京', '北京', '周末短途', '春季', 12, 1, 354.00, '是', 4, '12月去的南锣鼓巷，一个人出行。地点在北京，地铁到达方便，现场游客较多。这次玩了1天，人均花费约354元，夜景表现很好。景点印象：老北京胡同与小资情调结合，文艺青年的必逛之地。整体感受是还蛮满意，周末来刚好。二刷意愿：是。', '40%', 29);
