INSERT INTO `travel_review` VALUES (15017, 'TR015017', '铺前胜利老街', '文昌', '海南', '周末短途', '夏季', 4, 4, 943.00, '否', 5, '4月去的铺前胜利老街，和朋友出行。地点在文昌，地铁到达方便，现场人不算多。这次玩了4天，人均花费约943元，历史文化气息浓。景点印象：走在这不足五百米的老街上，能感受到到当时繁华。现在很多老字号的手艺还在这条街上传承着。整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '0%', 73);
