INSERT INTO `travel_review` VALUES (15046, 'TR015046', '江城八仙山', '百色', '广西', '城市漫游', '夏季', 3, 5, 1212.00, '是', 5, '3月去的江城八仙山，一个人出行。地点在百色，打车比较省心，现场人流量适中。这次玩了5天，人均花费约1212元，夜景表现很好。景点印象：从田东县城乘汽车出发，横渡右江，沿着蜿蜒的山间公路往南行驶50公里，山清水秀的江城便出现在眼前。那是一个壮人聚居的圩场。古榕江潺潺穿流其中，灌溉着两岸肥沃的田野；玲珑秀丽的群山，仿佛一道天然的古代城墙，环抱着一马平川的盆地。“江城”…整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 43);
