INSERT INTO `travel_review` VALUES (15054, 'TR015054', '湾头伊斯兰教徒墓葬群', '万宁', '海南', '周末短途', '夏季', 4, 5, 1179.00, '否', 4, '4月去的湾头伊斯兰教徒墓葬群，和家人出行。地点在万宁，地铁到达方便，现场游客较多。这次玩了5天，人均花费约1179元，夜景表现很好。景点印象：位于陵水胰与三亚市郊接壤的陵水湾畔海滩上，其墓葬群延伸到三亚市境的番岭坡共有四十多座。据史载，早在隋唐代时，中东一带阿拉伯各国的穆斯林人开始驾船跨越印度洋，经我国南海到达泉州、广州一带经商贸易。当时海南岛南部到东部沿海地带正处于先…整体感受是整体不错，可以安排半天到一天。二刷意愿：否。', '0%', 77);
