INSERT INTO `travel_review` VALUES (15096, 'TR015096', '义井遗址', '焦作', '河南', '周末短途', '春季', 12, 1, 80.00, '是', 5, '12月去的义井遗址，情侣出行。地点在焦作，打车比较省心，现场人流量适中。这次玩了1天，人均花费约80元，夜景表现很好。景点印象：义井遗址位于孟县城西5公里处义井村村西的曹马沟内。遗址南北长700余米，东西宽450米，总面积约31.5万平方米，文化层厚约3-5米。经过多次考察，采集到的石器有石刀、石铲等，陶器有豆、瓮、澄滤器、甑、大口尊等，以灰陶居多，也发现有少量黑陶。纹…整体感受是特别满意，很推荐。二刷意愿：是。', '0%', 67);
