INSERT INTO `travel_review` VALUES (15102, 'TR015102', '安顺场渡口与翼王亭', '雅安', '四川', '拍照旅行', '春季', 2, 6, 1317.00, '是', 5, '2月去的安顺场渡口与翼王亭，和朋友出行。地点在雅安，公交换乘方便，现场人不算多。这次玩了6天，人均花费约1317元，拍照很出片。景点印象：安顺场原名紫打地，地势险要。清代同治二年5月，太平天国箕王石达开在此全军覆没。1935年5月，中国工农红军长征在此强渡大渡河成功，安顺场由此载人中国革命史册，1980年被列为省级文物保护单位。渡口遗址建有“中国工农红军强渡大渡河纪念碑”，塑…整体感受是超出预期，以后还会来。二刷意愿：是。', '1%', 102);
