INSERT INTO `travel_review` VALUES (15145, 'TR015145', '董必武旧居', '黄冈', '湖北', '周末短途', '夏季', 5, 7, 1166.00, '否', 5, '5月去的董必武旧居，情侣出行。地点在黄冈，公交换乘方便，现场游客较多。这次玩了7天，人均花费约1166元，氛围感不错。景点印象：董必武旧居在红安县城民主街。旧居为一栋7间中式平房，坐西向东，面积120平方米。正中一间为小堂屋，上方香台依墙高置，大条桌放于中央，两张圆椅分列两旁，下方存放着董必武母亲用过的纺线车、织布机和灯架。堂屋北面的后半间房，是董必武诞生地，…整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '0%', 72);
