INSERT INTO `travel_review` VALUES (15175, 'TR015175', '青青生态度假村', '新乡', '河南', '周末短途', '夏季', 5, 2, 316.00, '是', 5, '5月去的青青生态度假村，和朋友出行。地点在新乡，打车比较省心，现场人不算多。这次玩了2天，人均花费约316元，夜景表现很好。景点印象：新乡市青青生态园位于新乡市凤泉区，由国家级文明村耿庄村2002年元月投资兴建，项目总投资5290万元，2003年国庆节正式营业。新乡市青青生态园是国家AA级旅游景点、全国首批农业旅游示范点。\n　　新乡市青青生态园是集高效农业、生态旅游、休闲度假…整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '0%', 57);
