INSERT INTO `travel_review` VALUES (15242, 'TR015242', '楠溪江风景旅游区', '温州', '浙江', '拍照旅行', '春季', 2, 1, 457.00, '是', 5, '2月去的楠溪江风景旅游区，一个人出行。地点在温州，自驾停车需要提前规划，现场人不算多。这次玩了1天，人均花费约457元，氛围感不错。景点印象：坐在竹筏上欣赏楠溪江的迷人景致，春夏的溪流和田园如梦似幻。 赏石桅岩的石景，看九漈石门台的瀑布，探寻隐秘的古村落，各有韵味。整体感受是超出预期，很推荐。二刷意愿：是。', '18%', 83);
