INSERT INTO `travel_review` VALUES (15275, 'TR015275', '青年洞', '安阳', '河南', '深度游', '冬季', 11, 7, 1598.00, '是', 5, '11月去的青年洞，情侣出行。地点在安阳，打车比较省心，现场游客较多。这次玩了7天，人均花费约1598元，氛围感不错。景点印象：由分水苑风景区驱车上行30公里，即可达青年洞风景区。这里山高路险，红旗渠悬挂在巍峨雄险的太行山悬崖绝壁之上，更使你领略到“人工天河”的无尽诗意，主景“青年洞”靠断壁而凿，从大山之中穿通而过，为你展现出一幅雄壮的画卷，将太行美景“雄、…整体感受是特别满意，很推荐。二刷意愿：是。', '4%', 98);
