INSERT INTO `travel_review` VALUES (15277, 'TR015277', '南天门', '神农架', '湖北', '亲子出游', '夏季', 5, 6, 1669.00, '是', 5, '5月去的南天门，和朋友出行。地点在神农架，自驾停车需要提前规划，现场人不算多。这次玩了6天，人均花费约1669元，历史文化气息浓。景点印象：南天门海拔2602.7米，山势巍峨，山口雄壮，风景优美，人行其上，如登南天，是“野人”经常出没的地方，这里设有野考大本营。整体感受是超出预期，很推荐。二刷意愿：是。', '1%', 88);
INSERT INTO `travel_review` VALUES (15278, 'TR015278', '怀化大峡谷', '怀化', '湖南', '拍照旅行', '秋季', 7, 5, 1545.00, '是', 5, '7月去的怀化大峡谷，情侣出行。地点在怀化，打车比较省心，现场人不算多。这次玩了5天，人均花费约1545元，夜景表现很好。景点印象：整体环境还算干净整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 81);
INSERT INTO `travel_review` VALUES (15279, 'TR015279', '尖山寺', '汕尾', '广东', '拍照旅行', '夏季', 3, 2, 584.00, '是', 5, '3月去的尖山寺，和朋友出行。地点在汕尾，公交换乘方便，现场人不算多。这次玩了2天，人均花费约584元，历史文化气息浓。景点印象：尖山寺始建于清光绪年间，一直是粤东客属信众向往圣地。那里山峦起伏，林木葱茏，四季常青，流水潺潺，花香鸟语，环境幽雅。系一佛教活动寺宇。近年来，陆河籍香港信民为弘扬中华文化，提倡固有道德，将寺修新，现已有男、女法师护寺，并列入香港宗…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 63);
