INSERT INTO `travel_review` VALUES (15282, 'TR015282', '黄河旅游区', '忻州', '山西', '城市漫游', '春季', 1, 3, 1039.00, '否', 3, '1月去的黄河旅游区，和朋友出行。地点在忻州，打车比较省心，现场高峰时段比较拥挤。这次玩了3天，人均花费约1039元，氛围感不错。景点印象：忻州的黄河旅游区，包括偏关、河曲和保德三县。黄河经过内蒙托克托县的河日镇后，急转直下，进人约180公里长的\"晋陕峡谷\"之中，此段黄河，咆哮奔腾，水面时宽时窄，河谷深切，山势险要，河水湍急，气势磅礴，十分壮观。特别是在汹涌澎湃的黄河之中…整体感受是中规中矩，别抱太高期待。二刷意愿：否。', '0%', 60);
