INSERT INTO `travel_review` VALUES (15305, 'TR015305', '恒山', '大同', '山西', '城市漫游', '夏季', 5, 3, 909.00, '否', 4, '5月去的恒山，和朋友出行。地点在大同，打车比较省心，现场游客较多。这次玩了3天，人均花费约909元，氛围感不错。景点印象：“五岳”中的北岳，登上主峰天峰岭俯瞰群山，豁然开朗。 手脚并用爬上恒宗殿前的103级陡阶，体验恒山的人文魅力。整体感受是体验挺好，可以安排半天到一天。二刷意愿：否。', '50%', 59);
