INSERT INTO `travel_review` VALUES (15307, 'TR015307', '班公错', '阿里', '西藏', '亲子出游', '冬季', 10, 2, 466.00, '是', 5, '10月去的班公错，一个人出行。地点在阿里，打车比较省心，现场游客较多。这次玩了2天，人均花费约466元，历史文化气息浓。景点印象：班公措位于中印边界，湖面狭长，雪山环绕，风光秀美。 乘船环绕鸟岛一周，观赏大量珍稀鸟类的生活。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '27%', 82);
