INSERT INTO `travel_review` VALUES (15325, 'TR015325', '石漫滩', '平顶山', '河南', '深度游', '春季', 2, 2, 456.00, '是', 3, '2月去的石漫滩，情侣出行。地点在平顶山，公交换乘方便，现场人流量适中。这次玩了2天，人均花费约456元，历史文化气息浓。景点印象：是在1987年拟建的“石漫滩森林植物园总体规划方案”的基础上，经国家林业部审定，于1992年2月以林造批字（92）154号文批复同意建立的45处国家级森林公园之一。\n位置辖区：森林公园位于河南省中部、舞钢南部、伏牛山东麓，黄淮平原西侧。包括石漫滩…整体感受是体验一般，按需选择。二刷意愿：是。', '0%', 60);
