INSERT INTO `travel_review` VALUES (15328, 'TR015328', '紫岩山', '德阳', '四川', '文化打卡', '春季', 1, 5, 1306.00, '是', 5, '1月去的紫岩山，和朋友出行。地点在德阳，打车比较省心，现场游客较多。这次玩了5天，人均花费约1306元，夜景表现很好。景点印象：紫岩山又名绵竹山，地处成都平原与岷山山脉交汇处，西北面高山天作，群峰叠翠。沱江之源绵远河蜿蜒出群山，一泻千里，形成成都平原北端的一个扇形冲击面棗绵竹市平坝区。在这片山地与平原交汇处，分布着许多名胜古迹和优美的自然景观，有风光秀丽的…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 90);
