INSERT INTO `travel_review` VALUES (15334, 'TR015334', '丰本农业科技园', '中山', '广东', '亲子出游', '夏季', 5, 1, 698.00, '是', 5, '5月去的丰本农业科技园，和家人出行。地点在中山，地铁到达方便，现场游客较多。这次玩了1天，人均花费约698元，历史文化气息浓。景点印象：丰本农业科技园,是中山市新崛起的一家集“旅游、度假、休闲、娱乐、品尝、生产、科普”于一体的亮点景区。\n该园位于民众镇“翡翠长廊”大道的左侧。东临珠江入海口，南望中山巷，走京珠高速半小时车程分别可达广州市区和澳门，距深圳1小时车程，距…整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 103);
