INSERT INTO `travel_review` VALUES (15342, 'TR015342', '大明宫国家遗址公园', '西安', '陕西', '周末短途', '夏季', 3, 1, 325.00, '否', 3, '3月去的大明宫国家遗址公园，和家人出行。地点在西安，打车比较省心，现场人流量适中。这次玩了1天，人均花费约325元，氛围感不错。景点印象：穿越千年，回到唐帝国最为辉煌的宫殿群中，感受那个恢弘的时代。整体感受是体验一般，避开高峰更好。二刷意愿：否。', '13%', 22);
INSERT INTO `travel_review` VALUES (15343, 'TR015343', '大梅沙海滨公园', '深圳', '广东', '文化打卡', '春季', 1, 3, 478.00, '否', 3, '1月去的大梅沙海滨公园，一个人出行。地点在深圳，打车比较省心，现场高峰时段比较拥挤。这次玩了3天，人均花费约478元，拍照很出片。景点印象：深圳最大的免费海滨浴场，看海游泳，享受亚热带海滨风光，非常惬意。整体感受是还可以，按需选择。二刷意愿：否。', '9%', 81);
