INSERT INTO `travel_review` VALUES (15358, 'TR015358', '神龟山', '万宁', '海南', '城市漫游', '冬季', 9, 3, 861.00, '否', 5, '9月去的神龟山，情侣出行。地点在万宁，地铁到达方便，现场游客较多。这次玩了3天，人均花费约861元，历史文化气息浓。景点印象：位于兴隆华侨农场境内。三座山峰连成东西走向呈龟状山脉，主峰海拨高280余米，高低错落的山势，把龟的头部、身部、尾部勾画得形神兼备，栩栩如生，充分展示了大自然造物之伟大和神奇。山上建起\"神龟山楼阁\"和\"神龟山神庙\"两大景点，有清未民国初期…整体感受是特别满意，值得专门打卡。二刷意愿：否。', '0%', 101);
