INSERT INTO `travel_review` VALUES (15370, 'TR015370', '临泽丹霞', '张掖', '甘肃', '城市漫游', '冬季', 9, 2, 567.00, '否', 2, '9月去的临泽丹霞，情侣出行。地点在张掖，打车比较省心，现场游客较多。这次玩了2天，人均花费约567元，拍照很出片。景点印象：临泽丹霞面积博大，色彩艳丽，场面壮观，是我国北方干旱地区最典型的丹霞地貌，也是另一种地貌类型——七彩丘陵，其色彩之缤纷、面积之大冠绝全国，举世罕见。整体感受是没达到预期，不建议高峰来。二刷意愿：否。', '1%', 32);
