INSERT INTO `travel_review` VALUES (15374, 'TR015374', '寺儿湾石窟', '白银', '甘肃', '亲子出游', '夏季', 3, 7, 1466.00, '否', 5, '3月去的寺儿湾石窟，一个人出行。地点在白银，公交换乘方便，现场高峰时段比较拥挤。这次玩了7天，人均花费约1466元，拍照很出片。景点印象：甘肃省省级文物保护单位。位于甘肃省白银市靖远县北湾镇寺儿湾。距离白银市约 50 公里，靖白公里从侧而过。是古丝绸之路上的集雕塑艺术、建筑艺术、文学艺术为一体的文物旅游景点。因这里有一寺一湾，便称寺儿湾，又因寺窟背依红罗山，亦称红罗寺。…整体感受是超出预期，值得专门打卡。二刷意愿：否。', '0%', 94);
