INSERT INTO `travel_review` VALUES (15388, 'TR015388', '中国长寿城', '眉山', '四川', '亲子出游', '冬季', 11, 3, 1125.00, '是', 5, '11月去的中国长寿城，一个人出行。地点在眉山，打车比较省心，现场人不算多。这次玩了3天，人均花费约1125元，拍照很出片。景点印象：彭山，是汉张纲晋李密的故乡，城市雕塑\"忠孝之邦\"，成为彭山人弘扬传统美德的警示与见证；彭山，是古代长寿老人彭祖的生栖之地，长寿文化源远流长，据全国第四次人口普查表明，彭山百岁老人的比例高出全国平均水平的17倍；彭山，是世界茶叶的发源地…整体感受是特别满意，以后还会来。二刷意愿：是。', '0%', 114);
