INSERT INTO `travel_review` VALUES (15396, 'TR015396', '白龙庙', '吕梁', '山西', '深度游', '夏季', 4, 2, 905.00, '是', 4, '4月去的白龙庙，和朋友出行。地点在吕梁，打车比较省心，现场人流量适中。这次玩了2天，人均花费约905元，氛围感不错。景点印象：白龙庙位于岚县城西22公里与兴县接壤的白龙山腰部。该山原名大万山，因建有白龙庙而得名，是吕梁山向北延伸的一条支脉。它山势雄伟，挺拔俊秀，群峰耸立，层峦叠嶂。遍山苍松翠柏，名花异草，既有珍贵的省鸟褐马鸡及麋鹿、貂、麝等珍稀动物，又有“…整体感受是体验挺好，周末来刚好。二刷意愿：是。', '0%', 77);
