INSERT INTO `travel_review` VALUES (15455, 'TR015455', '采石矶', '马鞍山', '安徽', '周末短途', '秋季', 8, 1, 614.00, '是', 5, '8月去的采石矶，情侣出行。地点在马鞍山，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约614元，历史文化气息浓。景点印象：因李白醉酒捉月，溺死于采石的传闻而著名，可寻访诗仙足迹。 登山顶三台阁，俯看秀丽的园林和壮阔的长江，日落时尤其美。 漫步悬于山壁的古栈道，近距离感受长江的险要。整体感受是超出预期，很推荐。二刷意愿：是。', '61%', 75);
