INSERT INTO `travel_review` VALUES (15562, 'TR015562', '嫩江旅游度假村', '白城', '吉林', '文化打卡', '春季', 2, 1, 724.00, '否', 4, '2月去的嫩江旅游度假村，一个人出行。地点在白城，打车比较省心，现场人流量适中。这次玩了1天，人均花费约724元，历史文化气息浓。景点印象：嫩江旅游渡假村位于大安市嫩江右岸，距市中心3公里，占地面积5.28公顷，建筑面积达5100平方米，水路、铁路便通，是一处良好的旅游胜地。\n  　这里一年四季分明，景色迷人，碧绿的江水上叶叶白帆轻轻飘荡，豪华的游船长鸣远航，江岸上绿草成荫，草原…整体感受是还蛮满意，推荐来看看。二刷意愿：否。', '0%', 71);
