INSERT INTO `travel_review` VALUES (15596, 'TR015596', '江北老街', '梅州', '广东', '深度游', '夏季', 3, 2, 511.00, '是', 5, '3月去的江北老街，和家人出行。地点在梅州，打车比较省心，现场人不算多。这次玩了2天，人均花费约511元，氛围感不错。景点印象：梅州市目前所保存的旧骑楼建筑，主要在位于江北老城区的凌风路一带。街区内尚保存许多中西合璧的客家民居，其建筑形态有楼有院、组合多样，复古风十足。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 124);
