INSERT INTO `travel_review` VALUES (15601, 'TR015601', '新村银杏园', '临沂', '山东', '亲子出游', '春季', 1, 2, 553.00, '否', 4, '1月去的新村银杏园，情侣出行。地点在临沂，打车比较省心，现场游客较多。这次玩了2天，人均花费约553元，历史文化气息浓。景点印象：山东省郯城县新村乡因盛产银杏而闻名全国，是名副其实的“银杏之乡”。全乡银杏种植面积28000多亩，银杏结果大树23000多株，年产银杏干果100多万公斤，银杏采叶圃20000多亩，年产银杏干叶4000多吨，出圃银杏苗木5000多万株/年，在全国率先研究开发…整体感受是整体不错，推荐来看看。二刷意愿：否。', '10%', 87);
