INSERT INTO `travel_review` VALUES (15613, 'TR015613', '屯垦第一连', '石河子', '新疆', '拍照旅行', '夏季', 4, 1, 701.00, '否', 5, '4月去的屯垦第一连，和朋友出行。地点在石河子，自驾停车需要提前规划，现场游客较多。这次玩了1天，人均花费约701元，历史文化气息浓。景点印象：位于石河子境内的玛纳斯河西岸的红山北麓。这里原是五十年代垦荒连队的驻地，保存着当年垦荒时的地窝子群、干打垒伙房、蓄水涝坝等军垦遗迹，还有木轮牛车、木犁、石磨等垦荒工具和生活用品。2002年--2003年，农八师152团投资300多万元，在当年垦荒…整体感受是特别满意，很推荐。二刷意愿：否。', '0%', 82);
