INSERT INTO `travel_review` VALUES (15641, 'TR015641', '莲花湖', '锦州', '辽宁', '亲子出游', '夏季', 3, 3, 754.00, '是', 5, '3月去的莲花湖，和家人出行。地点在锦州，自驾停车需要提前规划，现场人不算多。这次玩了3天，人均花费约754元，氛围感不错。景点印象：莲花湖位于黑山县姜屯镇东北4公里处，在土城子村旁，有一块近千亩的水面， 湖内数万株自然生长的莲花亭亭玉立，硕大的绿叶上滚动的水珠晶滢透澈，粉中透白的莲花散发着迷人的芳香。水中菱角一串串，水下鱼儿成群结对嬉戏，竹杆支撑着小船在湖面滑行…整体感受是超出预期，值得专门打卡。二刷意愿：是。', '0%', 72);
