INSERT INTO `travel_review` VALUES (15694, 'TR015694', '白水岭热带森林', '万宁', '海南', '城市漫游', '春季', 1, 6, 1752.00, '是', 5, '1月去的白水岭热带森林，和朋友出行。地点在万宁，公交换乘方便，现场人流量适中。这次玩了6天，人均花费约1752元，夜景表现很好。景点印象：属热带原始森林，总面积45700多亩，这里生长着茂密的热带山地雨季林，林中栖息着种类众多的珍稀动物，被誉为海南物华天宝之地，是热带森林旅游观光的好去处。\n进入保护区古林绿海之中，那林海涛声，时而咆哮，时而低吟。立于山巅俯视，日挂中天，树…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 79);
