INSERT INTO `travel_review` VALUES (15715, 'TR015715', '麒麟菜养殖基地', '琼海', '海南', '亲子出游', '春季', 1, 1, 235.00, '否', 4, '1月去的麒麟菜养殖基地，和家人出行。地点在琼海，公交换乘方便，现场人不算多。这次玩了1天，人均花费约235元，夜景表现很好。景点印象：麒麟菜又名石花菜，是珍贵的热带海洋藻类，生长在海底珊瑚礁上，有\"海底庄稼\"之称，是制造琼脂的原料。这里全国惟一的麒麟菜养殖基地，游人不仅能欣赏热带海滨风光，而且能品尝凉拌麒麟菜，体会潜海采摘麒麟菜的乐趣。整体感受是还蛮满意，推荐来看看。二刷意愿：否。', '0%', 83);
