INSERT INTO `travel_review` VALUES (15730, 'TR015730', '普定穿洞遗址', '安顺', '贵州', '城市漫游', '秋季', 6, 1, 121.00, '是', 5, '6月去的普定穿洞遗址，情侣出行。地点在安顺，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约121元，历史文化气息浓。景点印象：普定穿洞遗址是旧石器时代晚期遗址，位于安顺市普定县城西5公里处的一座孤山上，山下四周是溶蚀性盆地。穿洞洞口朝南，前后相通。洞口海拔1,286 米，山顶与谷地的相对高度为87米，洞口 于孤峰半腰，洞口距地面26米，为一石灰岩质溶洞，因洞口南北对…整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 82);
