INSERT INTO `travel_review` VALUES (15808, 'TR015808', '板壁岩', '神农架', '湖北', '深度游', '春季', 1, 1, 242.00, '是', 4, '1月去的板壁岩，和朋友出行。地点在神农架，自驾停车需要提前规划，现场游客较多。这次玩了1天，人均花费约242元，氛围感不错。景点印象：原始森林中的一片石林，怪石林立，姿态各异。 神农架“野人”出没的地方，说不定可以与“野人”兄弟不期而遇。整体感受是整体不错，推荐来看看。二刷意愿：是。', '26%', 34);
