INSERT INTO `travel_review` VALUES (15819, 'TR015819', '绝地争锋', '临汾', '山西', '亲子出游', '夏季', 4, 3, 720.00, '是', 4, '4月去的绝地争锋，情侣出行。地点在临汾，打车比较省心，现场人不算多。这次玩了3天，人均花费约720元，拍照很出片。景点印象：黄河壶口一带，古为晋国与少数民族狄人的分界线，又是秦晋两国的分疆处，虽然晋陕峡谷的黄河两岸山高壁陡，往来交通不便，但有古渡可通，加上此地河槽稳固、窄狭易渡，冬季结冰坚实可载车骑，所以历朝当局多在此置关设隘，驻兵把守，作为进攻对方的…整体感受是还蛮满意，可以安排半天到一天。二刷意愿：是。', '0%', 52);
