INSERT INTO `travel_review` VALUES (15847, 'TR015847', '慕士塔格冰川公园', '喀什', '新疆', '深度游', '冬季', 9, 1, 336.00, '否', 4, '9月去的慕士塔格冰川公园，情侣出行。地点在喀什，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约336元，历史文化气息浓。景点印象：慕士塔格冰川公园位于塔什库尔干县、世界著名的“冰山之父”—7546米的慕士塔格峰裙带下，该公园方圆20公里，距县城72公里，距314国道12公里，平均海拔5000米，有美丽的“绿弓湖”在此停留。游客可以看到冰川的雄伟、冰蛇的秀丽、冰塔、冰洞的多姿…整体感受是还蛮满意，可以安排半天到一天。二刷意愿：否。', '3%', 73);
