INSERT INTO `travel_review` VALUES (15885, 'TR015885', '长白山大峡谷', '白山', '吉林', '亲子出游', '春季', 1, 1, 259.00, '否', 3, '1月去的长白山大峡谷，一个人出行。地点在白山，打车比较省心，现场人不算多。这次玩了1天，人均花费约259元，夜景表现很好。景点印象：位于白山市扶松县境内，是近几年发现的自然奇观，可与美国大峡谷相媲美。长白山大峡谷长70多公里，乃火山爆发后熔岩石表面的火山灰和泥土被江水及雨水冲刷而成。北锦江流经谷底，只见两岸怪石林立，奇景叠生，栩栩如生，美不胜收。整体感受是中规中矩，按需选择。二刷意愿：否。', '26%', 28);
