INSERT INTO `travel_review` VALUES (15902, 'TR015902', '扎什伦布寺', '日喀则', '西藏', '文化打卡', '冬季', 11, 1, 624.00, '是', 5, '11月去的扎什伦布寺，一个人出行。地点在日喀则，公交换乘方便，现场游客较多。这次玩了1天，人均花费约624元，历史文化气息浓。景点印象：后藏地区最大的寺庙，历代班禅的驻锡地，格鲁派六大寺庙之一。整体感受是特别满意，很推荐。二刷意愿：是。', '53%', 81);
INSERT INTO `travel_review` VALUES (15903, 'TR015903', '元丰监铸钱遗址', '梧州', '广西', '城市漫游', '秋季', 6, 3, 847.00, '否', 5, '6月去的元丰监铸钱遗址，情侣出行。地点在梧州，公交换乘方便，现场人流量适中。这次玩了3天，人均花费约847元，历史文化气息浓。景点印象：位于梧州钱鉴路近桂江河边，面积2万多平方米。1964年，\n广西博物馆和梧州博物馆共同发掘清理遗址，发现铸钱的炼炉、操作坑、贮水池、小水沟及柱子洞等60多处，出土了一批铜钱、铁器、陶瓷器等665件，\n铜钱有崇宁通宝、圣宋元宝、崇宁重宝、政和通宝…整体感受是挺惊喜，以后还会来。二刷意愿：否。', '0%', 64);
