INSERT INTO `travel_review` VALUES (15926, 'TR015926', '东龙山遗址', '商洛', '陕西', '文化打卡', '秋季', 6, 2, 690.00, '是', 5, '6月去的东龙山遗址，和朋友出行。地点在商洛，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约690元，氛围感不错。景点印象：1997年6月商洛地区文物管理委员会调查发现，即与考古所联合发掘，已揭露面积1500平方米，发现房址15座、灰坑221个、墓葬75座，出土一批夏商周时期的石器、骨器、玉器、陶器和碎铜器，分别测定了夏与商的分期和商与周的分期，已被国家夏商周断代工程…整体感受是特别满意，很推荐。二刷意愿：是。', '0%', 100);
