INSERT INTO `travel_review` VALUES (15950, 'TR015950', '东北沦陷史陈列馆', '长春', '吉林', '文化打卡', '秋季', 8, 5, 1347.00, '是', 5, '8月去的东北沦陷史陈列馆，一个人出行。地点在长春，打车比较省心，现场人流量适中。这次玩了5天，人均花费约1347元，夜景表现很好。景点印象：是以展示日本侵略中国东北史实，进行现代史教育和爱国主义的好场所。整体感受是超出预期，很推荐。二刷意愿：是。', '4%', 114);
INSERT INTO `travel_review` VALUES (15951, 'TR015951', '浆水泉', '济南', '山东', '拍照旅行', '春季', 2, 1, 468.00, '是', 5, '2月去的浆水泉，一个人出行。地点在济南，打车比较省心，现场游客较多。这次玩了1天，人均花费约468元，氛围感不错。景点印象：浆水泉公园在回龙山、老虎山脚下，因有济南七十二名泉之一的浆水泉坐落在回龙山脚下便命名为浆水泉公园。乘坐49路公共汽车到浆水泉下车，再步行300米就到达浆水泉公园。整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 86);
