INSERT INTO `travel_review` VALUES (16032, 'TR016032', '穹窿银城', '那曲', '西藏', '周末短途', '冬季', 9, 1, 675.00, '否', 2, '9月去的穹窿银城，情侣出行。地点在那曲，自驾停车需要提前规划，现场人流量适中。这次玩了1天，人均花费约675元，拍照很出片。景点印象：穹隆银城，也有的叫琼隆银堡，藏语为“琼隆威卡尔”，是西藏古象雄王国的都城，位于海拔4400米的卡尔东山顶，面积10余万平方米。整体感受是体验偏一般，建议谨慎前往。二刷意愿：否。', '0%', 63);
