INSERT INTO `travel_review` VALUES (16041, 'TR016041', '安新县', '雄安新区', '河北', '城市漫游', '夏季', 3, 6, 1167.00, '否', 3, '3月去的安新县，情侣出行。地点在雄安新区，地铁到达方便，现场人不算多。这次玩了6天，人均花费约1167元，氛围感不错。景点印象：安新县是河北省保定市下辖县，位于河北省中部，县境东与雄县相连，北与容城毗邻，并与之一起成为雄安新区。安新县因受历史上冀中拗陷和黄河改道及太行山东麓永定河、滹沱河冲积扇的影响，形成特殊形貌。西南北有冲积洼地平原，东有华北平原最大的淡…整体感受是体验一般，按需选择。二刷意愿：否。', '0%', 44);
