INSERT INTO `travel_review` VALUES (16070, 'TR016070', '雾漫小东江', '郴州', '湖南', '拍照旅行', '春季', 12, 3, 1140.00, '否', 5, '12月去的雾漫小东江，和朋友出行。地点在郴州，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了3天，人均花费约1140元，历史文化气息浓。景点印象：小东江位于资兴市内，水面面积达160平方公里，蓄水量81亿立方米，相当于半个洞庭湖。这里长年两岸峰峦叠翠，湖面水汽蒸腾，云雾缭绕，神秘绮丽，其雾时移时凝，宛如一条被仙女挥舞着的“白练”，美丽之极，堪称中华一绝。整体感受是超出预期，很推荐。二刷意愿：否。', '42%', 48);
