INSERT INTO `travel_review` VALUES (16179, 'TR016179', '小鸟天堂', '江门', '广东', '文化打卡', '春季', 2, 2, 723.00, '是', 5, '2月去的小鸟天堂，和家人出行。地点在江门，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了2天，人均花费约723元，氛围感不错。景点印象：赏百鸟归巢的壮美景色，寻找巴金笔下的《鸟的天堂》。整体感受是特别满意，以后还会来。二刷意愿：是。', '8%', 73);
INSERT INTO `travel_review` VALUES (16180, 'TR016180', '观音洞', '儋州', '海南', '周末短途', '春季', 2, 2, 592.00, '是', 5, '2月去的观音洞，和朋友出行。地点在儋州，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了2天，人均花费约592元，拍照很出片。景点印象：观音洞是位于海南省儋州市莲花峰上的一个石灰石大溶洞，由于溶洞规模宏大，景色神奇，古传是观音菩萨曾经在此修炼而得名。\n莲花峰上的观音洞，古木葱郁，四季山花灿漫，地表较大。观音洞口共有3处，相距约60米，溶洞宽大，长500米、宽6米多，高达10…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '3%', 129);
INSERT INTO `travel_review` VALUES (16181, 'TR016181', '抚顺努尔哈赤冰雪大世界', '抚顺', '辽宁', '文化打卡', '秋季', 7, 4, 770.00, '是', 5, '7月去的抚顺努尔哈赤冰雪大世界，一个人出行。地点在抚顺，自驾停车需要提前规划，现场人流量适中。这次玩了4天，人均花费约770元，氛围感不错。景点印象：抚顺努尔哈赤冰雪大世界于2000年10月28日举行奠基开工仪式。该项目坐落在抚顺著名风景区萨尔浒区内，预计投资4000万元，占地50万平方米，集滑雪、滑冰、冰雕、雪雕、狩猎为一体。并首次投入科技含量高，新奇刺激的火箭蹦极、进口雪地摩托车、雪地卡…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 81);
INSERT INTO `travel_review` VALUES (16182, 'TR016182', '蓝月湖', '丽江', '云南', '城市漫游', '冬季', 9, 5, 1168.00, '是', 5, '9月去的蓝月湖，一个人出行。地点在丽江，公交换乘方便，现场人不算多。这次玩了5天，人均花费约1168元，氛围感不错。景点印象：奇幻透蓝的湖水，是拍婚纱照的绝佳背景。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '0%', 82);
