INSERT INTO `travel_review` VALUES (16184, 'TR016184', '宝格达乌拉山', '锡林郭勒盟', '内蒙古', '深度游', '夏季', 4, 2, 702.00, '否', 2, '4月去的宝格达乌拉山，和家人出行。地点在锡林郭勒盟，公交换乘方便，现场游客较多。这次玩了2天，人均花费约702元，历史文化气息浓。景点印象：宝格达乌拉山旅游区位于新巴尔虎右旗阿拉坦额莫勒镇正南45公里的广阔草原之上，这里原始而粗犷，秀丽而洁净。宝格达乌拉山依靠浓郁的宗教祭祀文化和独特的风土人情，吸引着众多国内外游客。最具特色的是民间祭祀圣山--宝格达乌拉山，它海拔922.3米…整体感受是略失望，建议谨慎前往。二刷意愿：否。', '3%', 60);
