INSERT INTO `travel_review` VALUES (16273, 'TR016273', '陆九渊之墓', '抚州', '江西', '拍照旅行', '夏季', 3, 2, 347.00, '否', 4, '3月去的陆九渊之墓，一个人出行。地点在抚州，地铁到达方便，现场游客较多。这次玩了2天，人均花费约347元，夜景表现很好。景点印象：座落于金溪县陆坊乡青田村东山上，1957年被列为江西省省级保护文物。陆九渊，字子静，号象山，陆坊乡青田人，是南宋时与朱熹双峰对峙的理学大师、哲学家、教育家，在历史上有深远影响。其理学又称“心学”，提出“心即理”、“宇宙便是吾心，吾心便…整体感受是整体不错，推荐来看看。二刷意愿：否。', '0%', 30);
