INSERT INTO `travel_review` VALUES (16277, 'TR016277', '盘山', '天津', '天津', '周末短途', '冬季', 10, 1, 352.00, '否', 3, '10月去的盘山，和家人出行。地点在天津，打车比较省心，现场人不算多。这次玩了1天，人均花费约352元，氛围感不错。景点印象：山景磅礴又秀美，随着高度变化看奇松、奇石、流水等多种美景。整体感受是体验一般，避开高峰更好。二刷意愿：否。', '1%', 67);
INSERT INTO `travel_review` VALUES (16278, 'TR016278', '丁公遗址', '滨州', '山东', '周末短途', '秋季', 7, 3, 934.00, '否', 4, '7月去的丁公遗址，和家人出行。地点在滨州，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了3天，人均花费约934元，夜景表现很好。景点印象：丁公遗址位于邹平县苑城乡丁公村东，东西长约300米，南北宽约200米。在遗址中发现大量龙山文化及岳石文化遗物。所采集的文物标本除蚌器外，主要有石铲、磨制石斧等石器，还有骨簇、骨针及具有龙山文化典型特征的蛋壳陶片。陶器中有小陶罐，为泥质灰…整体感受是整体不错，可以安排半天到一天。二刷意愿：否。', '0%', 60);
