INSERT INTO `travel_review` VALUES (16280, 'TR016280', '凤凰山', '安康', '陕西', '亲子出游', '夏季', 4, 1, 473.00, '是', 4, '4月去的凤凰山，和家人出行。地点在安康，公交换乘方便，现场人流量适中。这次玩了1天，人均花费约473元，历史文化气息浓。景点印象：《兴安府志.凤凰山记》载：“陕之关南则见安阳之凤凰山，绵亘三百余里，势若游龙，即天下之名山，似难出其右者，盖此山上百仞芙蓉，朵朵活波，直逼青天，下有汉水迂，淙淙泉石，极桡幽韵，此亦终南一大名胜也。卧苍崖，荫栝柏，凭高远眺，但见忽聚…整体感受是体验挺好，可以安排半天到一天。二刷意愿：是。', '0%', 67);
