INSERT INTO `travel_review` VALUES (16283, 'TR016283', '十万大山国家森林公园', '防城港', '广西', '亲子出游', '夏季', 5, 1, 506.00, '否', 5, '5月去的十万大山国家森林公园，和朋友出行。地点在防城港，打车比较省心，现场人流量适中。这次玩了1天，人均花费约506元，氛围感不错。景点印象：看重峦叠嶂的原始风光，沿途溪瀑河流层层叠叠，可谓山水如画。整体感受是特别满意，值得专门打卡。二刷意愿：否。', '8%', 65);
