INSERT INTO `travel_review` VALUES (16287, 'TR016287', '阳坝梅园沟', '陇南', '甘肃', '亲子出游', '春季', 12, 3, 772.00, '是', 5, '12月去的阳坝梅园沟，和家人出行。地点在陇南，公交换乘方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约772元，拍照很出片。景点印象：阳坝梅园沟是省级风景名胜区，被省内外誉为“美丽神奇的梅园”。总面积150平方公里，森林覆盖率高达70%，沿途风光绵延百余里，素有“陇上版纳”和“世界名茶之乡”之称。沟谷绵延几十华里，林木茂盛，湖光山色，风光旑旎，这里无山不青，无水不秀，…整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '0%', 69);
INSERT INTO `travel_review` VALUES (16288, 'TR016288', '山海关', '秦皇岛', '河北', '城市漫游', '秋季', 8, 6, 1363.00, '否', 5, '8月去的山海关，和家人出行。地点在秦皇岛，公交换乘方便，现场人不算多。这次玩了6天，人均花费约1363元，拍照很出片。景点印象：“不到长城非好汉”，登上镇远楼，感受天下第一关的雄姿。整体感受是挺惊喜，很推荐。二刷意愿：否。', '0%', 56);
INSERT INTO `travel_review` VALUES (16289, 'TR016289', '铁农园艺园', '齐齐哈尔', '黑龙江', '亲子出游', '秋季', 8, 4, 1213.00, '否', 5, '8月去的铁农园艺园，情侣出行。地点在齐齐哈尔，打车比较省心，现场高峰时段比较拥挤。这次玩了4天，人均花费约1213元，历史文化气息浓。景点印象：齐齐哈尔铁农园艺园度假村创建于2000年，位于齐齐哈尔市北郊9公里，占地面积1050亩，隶属于哈铁齐齐哈尔先兴集团农副业基地，是国家AAA级旅游景区，全国首批农业旅游示范点。\n铁农园艺园度假村是黑龙江省西部地区较大的绿色生态园林度假村，在齐齐…整体感受是特别满意，值得专门打卡。二刷意愿：否。', '0%', 54);
