INSERT INTO `travel_review` VALUES (16309, 'TR016309', '清远银盏谷水帘洞', '清远', '广东', '文化打卡', '冬季', 10, 1, 363.00, '是', 5, '10月去的清远银盏谷水帘洞，和家人出行。地点在清远，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约363元，拍照很出片。景点印象：银盏谷水帘洞具有《西游记》神话故事里花果山水帘洞般的神话色彩，国内首次发现。洞内山水相连，秀峰环抱，溪水涟涟，溪谷险峻，原始森林、瀑布群尽入眼底。当您徒步穿越水帘洞时，恍入仙境，顿时心旷神怡。洞内不时溢出的神秘感让您不断感受到大自…整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 68);
