INSERT INTO `travel_review` VALUES (16400, 'TR016400', '孙中山故居纪念馆', '中山', '广东', '亲子出游', '夏季', 3, 6, 1934.00, '否', 2, '3月去的孙中山故居纪念馆，和朋友出行。地点在中山，公交换乘方便，现场游客较多。这次玩了6天，人均花费约1934元，氛围感不错。景点印象：中山市有名的景点，孙中山于1866年在此出生，全国重点文物保护单位。整体感受是略失望，建议谨慎前往。二刷意愿：否。', '31%', 36);
