INSERT INTO `travel_review` VALUES (16405, 'TR016405', '麦积山石窟', '天水', '甘肃', '拍照旅行', '秋季', 6, 1, 602.00, '是', 4, '6月去的麦积山石窟，情侣出行。地点在天水，地铁到达方便，现场游客较多。这次玩了1天，人均花费约602元，夜景表现很好。景点印象：中国佛教“四大石窟”之一，参观众多古代造像，感叹佛教艺术的精彩辉煌。整体感受是还蛮满意，可以安排半天到一天。二刷意愿：是。', '87%', 68);
