INSERT INTO `travel_review` VALUES (16407, 'TR016407', '象山', '荆门', '湖北', '亲子出游', '春季', 12, 4, 1170.00, '否', 3, '12月去的象山，和朋友出行。地点在荆门，打车比较省心，现场人流量适中。这次玩了4天，人均花费约1170元，历史文化气息浓。景点印象：在荆门市西郊。原名蒙山，因象山先生陆九渊曾讲学于此而称今名。历为游览胜地。南北向，长600米，宽250米，海拔176米。现为占地50余万平方米的龙泉公园重要组成部分。有龙泉书院、陆夫子词、老莱山庄、蒙泉、龙泉、惠泉、顺口泉、文明湖、讲经台、…整体感受是体验一般，别抱太高期待。二刷意愿：否。', '0%', 47);
