INSERT INTO `travel_review` VALUES (16425, 'TR016425', '南山特产', '邵阳', '湖南', '文化打卡', '秋季', 8, 3, 1076.00, '否', 5, '8月去的南山特产，情侣出行。地点在邵阳，地铁到达方便，现场人不算多。这次玩了3天，人均花费约1076元，氛围感不错。景点印象：南山奶粉\n“南山”牌系列乳制品以“凉开水即溶，喝了不上火”蜚声全国，被誉为“南国净土里长出的绿色食品”，其中婴幼儿系列奶粉为“国家免检产品”。南山奶粉畅销全国近30个省、自治区、直辖市，成为全国奶粉行业十大畅销产品，在广大消费者的心…整体感受是超出预期，值得专门打卡。二刷意愿：否。', '0%', 73);
INSERT INTO `travel_review` VALUES (16426, 'TR016426', '北普陀山', '锦州', '辽宁', '城市漫游', '春季', 12, 2, 466.00, '是', 5, '12月去的北普陀山，和家人出行。地点在锦州，地铁到达方便，现场人不算多。这次玩了2天，人均花费约466元，拍照很出片。景点印象：坐落于山中的庞大佛教建筑群，北方著名的祈福胜地。 参观古老的北普陀禅寺与东北最大的露天观音佛像。 坐一次刺激的滑索，登上鸡冠山顶俯瞰景区全景。整体感受是特别满意，以后还会来。二刷意愿：是。', '12%', 86);
