INSERT INTO `travel_review` VALUES (16498, 'TR016498', '嘉陵江', '陇南', '甘肃', '深度游', '夏季', 5, 4, 1093.00, '否', 4, '5月去的嘉陵江，一个人出行。地点在陇南，公交换乘方便，现场高峰时段比较拥挤。这次玩了4天，人均花费约1093元，历史文化气息浓。景点印象：“汉水南入嘉陵道而为嘉陵水”，江名由此而来，嘉陵江发源于秦岭南麓，流经陕、甘、川至重庆流入长江。沿江两岸奇峰壁立、怪石嶙峋、森林茂密、泉瀑众多、美不胜收。整体感受是整体不错，周末来刚好。二刷意愿：否。', '41%', 101);
