INSERT INTO `travel_review` VALUES (16524, 'TR016524', '香山', '陇南', '甘肃', '深度游', '夏季', 3, 2, 604.00, '否', 5, '3月去的香山，一个人出行。地点在陇南，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了2天，人均花费约604元，历史文化气息浓。景点印象：香山位于甘肃省礼县境内，主要保护森林生态系统、名胜古迹以及珍稀动物等。区内有天然林3730公顷，飞播造林4000公顷。已知有高等植物120科250属500余种；野生动物中兽类30余种，鸟类50种，爬行类10种，两栖类10种，鱼类9种，昆虫类数百种，属国家重…整体感受是超出预期，以后还会来。二刷意愿：否。', '3%', 71);
