INSERT INTO `travel_review` VALUES (16531, 'TR016531', '扎尕那', '甘南', '甘肃', '拍照旅行', '夏季', 4, 3, 1083.00, '是', 5, '4月去的扎尕那，和朋友出行。地点在甘南，打车比较省心，现场人不算多。这次玩了3天，人均花费约1083元，历史文化气息浓。景点印象：峭丽岩壁围绕下沿山而建的藏族古村，随处放眼都有如画美景。 每天清晨山间总有云雾缭绕，景色宛若仙境。 观看当地藏族人们的劳作和生活，感受原始藏寨的淳朴安详。整体感受是超出预期，很推荐。二刷意愿：是。', '28%', 120);
