INSERT INTO `travel_review` VALUES (16680, 'TR016680', '商均墓', '商丘', '河南', '拍照旅行', '冬季', 9, 1, 353.00, '是', 5, '9月去的商均墓，和家人出行。地点在商丘，地铁到达方便，现场人不算多。这次玩了1天，人均花费约353元，历史文化气息浓。景点印象：位于虞城县利民镇西南商均墓村后。墓前原有祠宇，后废。清康熙四十一年（1702）虞城知县程本节曾撰文立碑二通。雍正十年（1732）建社稷商均坛，每年春秋致祭。墓周古木参天，并有守林人看护。现仅存墓冢，高约4米，周长110米。为县级文物保护单位。整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 80);
INSERT INTO `travel_review` VALUES (16681, 'TR016681', '瀑里', '阳泉', '山西', '深度游', '冬季', 9, 2, 641.00, '是', 5, '9月去的瀑里，和家人出行。地点在阳泉，自驾停车需要提前规划，现场游客较多。这次玩了2天，人均花费约641元，氛围感不错。景点印象：景点本身有一定特色整体感受是超出预期，值得专门打卡。二刷意愿：是。', '0%', 69);
INSERT INTO `travel_review` VALUES (16682, 'TR016682', '卡若遗址', '昌都', '西藏', '深度游', '秋季', 8, 5, 1224.00, '是', 5, '8月去的卡若遗址，情侣出行。地点在昌都，地铁到达方便，现场人流量适中。这次玩了5天，人均花费约1224元，氛围感不错。景点印象：卡诺遗址位于中国西南部西藏自治区的昌都县,是一处新石器时代晚期文化遗址，年代为距今4000～5000年。 卡若遗址发现于1978年，遗址总面积约1万平方米，是考古界公认的西藏三大原始文化遗址之一。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '1%', 92);
INSERT INTO `travel_review` VALUES (16683, 'TR016683', '厦门园林植物园', '厦门', '福建', '拍照旅行', '春季', 12, 2, 838.00, '是', 5, '12月去的厦门园林植物园，和朋友出行。地点在厦门，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约838元，氛围感不错。景点印象：环境很好的植物园，有多种稀有植物景观，也适合周末爬山休闲。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '10%', 90);
