INSERT INTO `travel_review` VALUES (16694, 'TR016694', '漳河风景名胜区', '荆门', '湖北', '深度游', '秋季', 6, 1, 388.00, '是', 4, '6月去的漳河风景名胜区，和家人出行。地点在荆门，自驾停车需要提前规划，现场人流量适中。这次玩了1天，人均花费约388元，夜景表现很好。景点印象：漳河风景名胜区位于湖北荆门，地处古三国战场的中心地带，背靠荆山，面向江汉平原，是张家界、古隆中、长江三峡等旅游热线的黄金腹地。景区内有山水景观和山石景观两大类，尤以山水景观最具特色。整体感受是还蛮满意，周末来刚好。二刷意愿：是。', '0%', 57);
