INSERT INTO `travel_review` VALUES (16698, 'TR016698', '汾酒工业园林', '吕梁', '山西', '亲子出游', '冬季', 10, 4, 458.00, '是', 5, '10月去的汾酒工业园林，和朋友出行。地点在吕梁，公交换乘方便，现场游客较多。这次玩了4天，人均花费约458元，拍照很出片。景点印象：山西杏花村汾酒集团是我国最大的名白酒生产基地之一，他们生产的中国驰名商品“杏花村”汾酒、竹叶青远销50多个国家和地区，年销售收入近10个亿，年出口创汇2000万美元。进入新世纪，面对WTO带来的机遇和挑战，杏花村汾酒集团公司在把握中国白酒业…整体感受是超出预期，很推荐。二刷意愿：是。', '5%', 70);
