INSERT INTO `travel_review` VALUES (16701, 'TR016701', '哈斯哈吉甫陵墓', '喀什', '新疆', '拍照旅行', '秋季', 7, 1, 602.00, '是', 4, '7月去的哈斯哈吉甫陵墓，和家人出行。地点在喀什，地铁到达方便，现场游客较多。这次玩了1天，人均花费约602元，氛围感不错。景点印象：玉素甫·哈斯哈吉甫是维吾尔族伟大的思想家，他于公元1069年-1070年间，以当时的维吾尔文完成了13290行的长诗《福乐智慧》。\n玉素甫·哈斯哈吉甫墓，座落在喀什市体育路十二小学院内，占地965平方米。玉素甫.哈斯哈吉甫墓是一组富于维吾尔传统建筑…整体感受是还蛮满意，推荐来看看。二刷意愿：是。', '3%', 77);
