INSERT INTO `travel_review` VALUES (16736, 'TR016736', '茶马古道', '玉溪', '云南', '拍照旅行', '春季', 2, 5, 1381.00, '是', 5, '2月去的茶马古道，一个人出行。地点在玉溪，公交换乘方便，现场游客较多。这次玩了5天，人均花费约1381元，拍照很出片。景点印象：茶马古道是中国西南民族经济文化交流的走廊，是一条世界上自然风光最壮观，文化最为神秘的旅游绝品线路，它蕴藏着开发不尽的文化遗产。整体感受是超出预期，值得专门打卡。二刷意愿：是。', '5%', 74);
