INSERT INTO `travel_review` VALUES (16748, 'TR016748', '上党战役指挥部旧址', '长治', '山西', '深度游', '冬季', 11, 1, 395.00, '否', 5, '11月去的上党战役指挥部旧址，和朋友出行。地点在长治，地铁到达方便，现场游客较多。这次玩了1天，人均花费约395元，氛围感不错。景点印象：位于离襄垣县城西23公里处的大平村，是上党战役指挥部的一个旧址。1945年l0月，刘伯承司令员和邓小平政委率晋冀鲁豫军区指挥部由崔蒙移驻这里，住在小东院孙树章家。在这里指挥了决定上党战役胜负的老爷山、磨盘垴打援战和土落截击战，取得了上党战…整体感受是挺惊喜，很推荐。二刷意愿：否。', '0%', 90);
