INSERT INTO `travel_review` VALUES (16803, 'TR016803', '鹿峰山风景区', '玉林', '广西', '深度游', '秋季', 7, 1, 498.00, '是', 5, '7月去的鹿峰山风景区，情侣出行。地点在玉林，公交换乘方便，现场人不算多。这次玩了1天，人均花费约498元，拍照很出片。景点印象：这里有秀美的山水之景，更有别致的“地球心脏”溶洞景观。整体感受是挺惊喜，很推荐。二刷意愿：是。', '12%', 53);
INSERT INTO `travel_review` VALUES (16804, 'TR016804', '银盘山', '常德', '湖南', '亲子出游', '秋季', 7, 3, 1083.00, '是', 5, '7月去的银盘山，和朋友出行。地点在常德，自驾停车需要提前规划，现场游客较多。这次玩了3天，人均花费约1083元，氛围感不错。景点印象：银盘山位于五溪湖北岸，神公寨东侧，三面环水，其状如盘，故名银盘山。一侧是青松岭，东侧有哨楼，这里山水清幽，景色宜人，是旅途中游憩之所。\n登上银盘山，面对碧绿的湖水，灿烂的鲜花，奔泻的山泉武，飞动的流云，你一定会乐而忘返的。\n银盘山…整体感受是特别满意，以后还会来。二刷意愿：是。', '0%', 102);
