INSERT INTO `travel_review` VALUES (16828, 'TR016828', '胜金口千佛洞', '吐鲁番', '新疆', '文化打卡', '春季', 1, 4, 1096.00, '是', 5, '1月去的胜金口千佛洞，一个人出行。地点在吐鲁番，公交换乘方便，现场游客较多。这次玩了4天，人均花费约1096元，拍照很出片。景点印象：胜金口千佛洞位于吐鲁番市以东40公里的胜金口。千佛洞属高昌故城系列的佛教建筑之一，始于唐代，建筑规模庞大，到20世纪初时，仍有12座寺院。经斯坦因等劫掠后，损坏严重。现残存洞窟10个，发现有回鹘文壁画及回鹘文题记，山下附属建筑中还出土有婆…整体感受是超出预期，值得专门打卡。二刷意愿：是。', '0%', 105);
