INSERT INTO `travel_review` VALUES (16835, 'TR016835', '泰顺廊桥', '温州', '浙江', '亲子出游', '秋季', 6, 5, 1504.00, '否', 4, '6月去的泰顺廊桥，和朋友出行。地点在温州，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了5天，人均花费约1504元，夜景表现很好。景点印象：现泰顺境内保存完好的唐、宋、明、清代的木拱廊桥达30余座，是中国古代建筑的瑰宝。整体感受是体验挺好，可以安排半天到一天。二刷意愿：否。', '0%', 50);
INSERT INTO `travel_review` VALUES (16836, 'TR016836', '天涯亭', '钦州', '广西', '拍照旅行', '冬季', 10, 2, 315.00, '是', 5, '10月去的天涯亭，和家人出行。地点在钦州，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了2天，人均花费约315元，氛围感不错。景点印象：传为北宋庆历年间（1041-1048）知州陶弼始建。因“钦地南临大洋，西接交趾（今越南），去京师万里，故以天涯名，与合浦之称为海角者一也”。\n天涯亭初建于城东平南古渡头，明洪武五年（1372年）同知郭携迁城内东门口重建。1935年迁建今址，故又称“…整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '0%', 77);
