INSERT INTO `travel_review` VALUES (16869, 'TR016869', '达盖图音额博勒者', '锡林郭勒盟', '内蒙古', '深度游', '夏季', 5, 1, 231.00, '否', 4, '5月去的达盖图音额博勒者，和朋友出行。地点在锡林郭勒盟，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约231元，拍照很出片。景点印象：景点本身有一定特色整体感受是体验挺好，可以安排半天到一天。二刷意愿：否。', '0%', 69);
INSERT INTO `travel_review` VALUES (16870, 'TR016870', '驼铃梦坡沙漠公园', '昌吉', '新疆', '深度游', '夏季', 4, 6, 1493.00, '是', 5, '4月去的驼铃梦坡沙漠公园，一个人出行。地点在昌吉，地铁到达方便，现场人不算多。这次玩了6天，人均花费约1493元，夜景表现很好。景点印象：准噶尔盆地古尔班通古特沙漠南缘，是一片原始、粗犷、一望无垠的沙漠世界，又是一座天然的荒漠植物园，葱绿的梭梭、茂密的胡杨、沁人心脾的沙枣、飘逸羽叶的三芒草，以丑为美的猪毛菜、富有药用价值的大黄、大芸黄芪、“叮铛”作声的铃铛刺、形似鹿…整体感受是超出预期，很推荐。二刷意愿：是。', '1%', 97);
INSERT INTO `travel_review` VALUES (16871, 'TR016871', '瀑里', '阳泉', '山西', '深度游', '秋季', 8, 2, 596.00, '是', 5, '8月去的瀑里，和家人出行。地点在阳泉，地铁到达方便，现场人不算多。这次玩了2天，人均花费约596元，氛围感不错。景点印象：周边配套比较齐全整体感受是超出预期，值得专门打卡。二刷意愿：是。', '0%', 56);
