INSERT INTO `travel_review` VALUES (16874, 'TR016874', '卧牛湖', '黑河', '黑龙江', '深度游', '春季', 12, 1, 596.00, '是', 5, '12月去的卧牛湖，情侣出行。地点在黑河，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约596元，历史文化气息浓。景点印象：卧牛湖风景区地处黑河市爱辉区上马厂乡卧牛河村，距黑河市区14公里，位于黑呼公路16公里处，面积为50平方公里，与俄布拉戈维申斯克市隔江相望，是黑河市省级名胜风景区。\n卧牛湖湖区夏季山青水秀，冬季银妆素裹，具备游览、观赏、避暑、度假、娱乐…整体感受是特别满意，以后还会来。二刷意愿：是。', '1%', 128);
