INSERT INTO `travel_review` VALUES (16879, 'TR016879', '竹山景区', '防城港', '广西', '亲子出游', '冬季', 10, 3, 757.00, '否', 3, '10月去的竹山景区，和家人出行。地点在防城港，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了3天，人均花费约757元，历史文化气息浓。景点印象：竹山景区位于北仑河入海口，是海陆交汇处。中国大陆海岸线东起鸭绿江，西至北仑河，这里是中国大陆海岸线的最西端，又是陆路边界线的起点，其对面隔海相望是越南的芒街市和万柱海滩。这里是大清国一号界碑，还是北仑河国家海洋自然生态保护区。历史…整体感受是还可以，按需选择。二刷意愿：否。', '13%', 55);
INSERT INTO `travel_review` VALUES (16880, 'TR016880', '林坑', '温州', '浙江', '文化打卡', '春季', 1, 1, 257.00, '是', 5, '1月去的林坑，和家人出行。地点在温州，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约257元，历史文化气息浓。景点印象：历史悠久的古村落，拥有楠溪江保存较完整的山地民居，掩映在青山绿水中。整体感受是挺惊喜，很推荐。二刷意愿：是。', '7%', 87);
