INSERT INTO `travel_review` VALUES (16894, 'TR016894', '朱仙镇岳飞庙', '开封', '河南', '城市漫游', '夏季', 4, 1, 130.00, '是', 5, '4月去的朱仙镇岳飞庙，一个人出行。地点在开封，打车比较省心，现场游客较多。这次玩了1天，人均花费约130元，历史文化气息浓。景点印象：岳飞庙整体恢宏庄严，碑亭林立，刻绘塑铸，丰富多彩。整体感受是特别满意，很推荐。二刷意愿：是。', '1%', 122);
