INSERT INTO `travel_review` VALUES (16896, 'TR016896', '桂东南抗日武装起义纪念塔', '玉林', '广西', '拍照旅行', '冬季', 10, 2, 747.00, '是', 5, '10月去的桂东南抗日武装起义纪念塔，和家人出行。地点在玉林，地铁到达方便，现场人不算多。这次玩了2天，人均花费约747元，夜景表现很好。景点印象：纪念塔，于1992年3月5日奠基，有用石头雕刻而成的侏罗纪时代的恐龙沟，有巨石龟、石兔、石羊、石牛构成的独占鳌头风景点。整体感受是特别满意，以后还会来。二刷意愿：是。', '0%', 57);
INSERT INTO `travel_review` VALUES (16897, 'TR016897', '情侣路', '珠海', '广东', '亲子出游', '春季', 1, 3, 1123.00, '否', 2, '1月去的情侣路，情侣出行。地点在珠海，公交换乘方便，现场人不算多。这次玩了3天，人均花费约1123元，拍照很出片。景点印象：珠海的城市名片，漫步海边，欣赏珠海渔女雕像。整体感受是略失望，可考虑其他景点。二刷意愿：否。', '24%', 50);
