INSERT INTO `travel_review` VALUES (16904, 'TR016904', '乐亭海滨旅游区', '唐山', '河北', '城市漫游', '春季', 1, 5, 981.00, '是', 5, '1月去的乐亭海滨旅游区，和朋友出行。地点在唐山，自驾停车需要提前规划，现场人不算多。这次玩了5天，人均花费约981元，氛围感不错。景点印象：位于乐亭县境内，在秦、唐、沧环渤海开发区中部，东与昌黎黄金海岸、南戴河景区为邻，距天津220公里，北京280公里。景区总面积88平方公里，包括石臼坨、腰坨、打网岗等岛屿和碧海屿场、金银滩浴场、姜各庄森林公园及唐港、李大钊故居等景点。景区内…整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 74);
