INSERT INTO `travel_review` VALUES (16916, 'TR016916', '望月湖', '眉山', '四川', '文化打卡', '春季', 1, 2, 356.00, '否', 5, '1月去的望月湖，和朋友出行。地点在眉山，打车比较省心，现场游客较多。这次玩了2天，人均花费约356元，拍照很出片。景点印象：源起于\"蛤蟆望月\"传说的望月湖位于眉山县唯一的一座中型水库--两河口水库，该湖距眉山县城22公里，座落于眉山县郑军乡境内，交通方便，风景秀丽，与香火旺盛的华藏寺毗邻，相距六百余米，遥相呼应，各具特色，互为补充。整体感受是特别满意，很推荐。二刷意愿：否。', '0%', 88);
