INSERT INTO `travel_review` VALUES (16923, 'TR016923', '沱江', '湘西', '湖南', '拍照旅行', '秋季', 8, 2, 688.00, '否', 5, '8月去的沱江，和家人出行。地点在湘西，打车比较省心，现场游客较多。这次玩了2天，人均花费约688元，历史文化气息浓。景点印象：在沱江上泛舟，两边是百年历史的苗家吊脚楼，沿途有跳岩、古城墙、虹桥等凤古城的标志性景点。 清晨的沱江边，雾气重重，当地居民咚咚咚的在江边捶洗衣物。 沱江畔的的吊脚楼内，是古城客栈和餐馆集中的地方。整体感受是特别满意，以后还会来。二刷意愿：否。', '3%', 68);
