INSERT INTO `travel_review` VALUES (16955, 'TR016955', '归德府文庙', '商丘', '河南', '文化打卡', '夏季', 5, 2, 554.00, '是', 5, '5月去的归德府文庙，和家人出行。地点在商丘，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了2天，人均花费约554元，拍照很出片。景点印象：归德府文庙位于商丘市睢阳区，坐落在商丘古城内，是河南省现存规模最大的文庙建筑，始建于明嘉靖三十四年至三十八年（公元1555年至1559年），距今已有近500年的历史。整体感受是超出预期，值得专门打卡。二刷意愿：是。', '25%', 49);
