INSERT INTO `travel_review` VALUES (17012, 'TR017012', '古堰画乡景区', '丽水', '浙江', '周末短途', '冬季', 9, 2, 770.00, '否', 4, '9月去的古堰画乡景区，和家人出行。地点在丽水，公交换乘方便，现场游客较多。这次玩了2天，人均花费约770元，拍照很出片。景点印象：临着瓯江，景色秀美又不失大气，街边常能看到支着画板创作的人。 逛江滨古街的画室和特色小店，淘些特色小玩意儿。 看千年水利工程通济堰，一半平静一半汹涌的水面甚是抢眼。整体感受是整体不错，周末来刚好。二刷意愿：否。', '28%', 53);
INSERT INTO `travel_review` VALUES (17013, 'TR017013', '紫阳街', '台州', '浙江', '深度游', '夏季', 4, 6, 1699.00, '是', 3, '4月去的紫阳街，一个人出行。地点在台州，公交换乘方便，现场人不算多。这次玩了6天，人均花费约1699元，历史文化气息浓。景点印象：周边配套比较齐全整体感受是中规中矩，按需选择。二刷意愿：是。', '14%', 10);
INSERT INTO `travel_review` VALUES (17014, 'TR017014', '翠云山', '抚州', '江西', '深度游', '秋季', 7, 3, 1000.00, '否', 4, '7月去的翠云山，一个人出行。地点在抚州，自驾停车需要提前规划，现场人流量适中。这次玩了3天，人均花费约1000元，夜景表现很好。景点印象：在县南，距县城2公里，海拔498.2米，一年四季青苍可爱，云烟缭峦，岗峦回合，瀑布悬流。山谷口两峰对峙，中间夹着一条狭窄山径称为翠云关。山中有桂花岩、罗汉洞、月石、跃马泉、鸣玉泉、试茗泉诸胜景，王安石、陆九韶等先后作诗吟此。山中的翠云寺…整体感受是还蛮满意，可以安排半天到一天。二刷意愿：否。', '0%', 58);
