INSERT INTO `travel_review` VALUES (17023, 'TR017023', '太子殿', '十堰', '湖北', '深度游', '夏季', 3, 3, 936.00, '否', 2, '3月去的太子殿，和朋友出行。地点在十堰，打车比较省心，现场游客较多。这次玩了3天，人均花费约936元，夜景表现很好。景点印象：太子读书殿里，布置得独具匠心，少年真武读书的壁画，石案、笔墨、古籍等，所营造的刻苦读书的氛围，让人联想到当年幼年太子生活学习的艰辛、信心和恒心。整体感受是体验偏一般，可考虑其他景点。二刷意愿：否。', '3%', 49);
INSERT INTO `travel_review` VALUES (17024, 'TR017024', '云南省博物馆', '昆明', '云南', '文化打卡', '春季', 2, 1, 258.00, '否', 3, '2月去的云南省博物馆，情侣出行。地点在昆明，打车比较省心，现场人流量适中。这次玩了1天，人均花费约258元，夜景表现很好。景点印象：展品种类齐全数目众多，是了解云南历史、文化的最佳去处。整体感受是体验一般，别抱太高期待。二刷意愿：否。', '0%', 49);
INSERT INTO `travel_review` VALUES (17025, 'TR017025', '五彩山', '阿克苏', '新疆', '拍照旅行', '冬季', 9, 1, 247.00, '是', 5, '9月去的五彩山，情侣出行。地点在阿克苏，打车比较省心，现场人流量适中。这次玩了1天，人均花费约247元，氛围感不错。景点印象：在中国，有好多地方都有“五彩山”，然而新疆的五彩山以其特有的气势和少见的雅丹地貌而闻名于世。整体感受是特别满意，以后还会来。二刷意愿：是。', '3%', 73);
