INSERT INTO `travel_review` VALUES (17028, 'TR017028', '徐福村', '连云港', '江苏', '周末短途', '秋季', 7, 3, 899.00, '是', 5, '7月去的徐福村，和朋友出行。地点在连云港，自驾停车需要提前规划，现场人流量适中。这次玩了3天，人均花费约899元，历史文化气息浓。景点印象：金山乡的徐福村是秦代徐福的故里。今天徐福被日本人民尊之为司农耕之神，在日本新宫市有徐福公园，园内有徐福墓。\n据历史记载，秦朝当地有一位民间医生名叫徐福，善医药，会针灸，救治了当地及附近的许多乡亲，后来被秦始皇派遣，出海采仙药，一去…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 80);
