INSERT INTO `travel_review` VALUES (17056, 'TR017056', '九成功生态园', '鄂尔多斯', '内蒙古', '城市漫游', '秋季', 7, 4, 953.00, '是', 5, '7月去的九成功生态园，和家人出行。地点在鄂尔多斯，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了4天，人均花费约953元，历史文化气息浓。景点印象：九成功生态园座落于鄂尔多斯市东胜区罕台镇九成功村，是国家AAA级旅游景区。东距鄂尔多斯市区20公里，南距一代天骄成吉思汗陵80公里，西距世珍园40公里，北距世界著名旅游景区响沙湾65公里。人类第一条高速公路秦直道从这里经过；窟野河的第一支流…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 87);
