INSERT INTO `travel_review` VALUES (17083, 'TR017083', '云海波涛', '铜仁', '贵州', '文化打卡', '春季', 1, 5, 1375.00, '是', 5, '1月去的云海波涛，和朋友出行。地点在铜仁，打车比较省心，现场高峰时段比较拥挤。这次玩了5天，人均花费约1375元，历史文化气息浓。景点印象：从金顶远望，白云无际，浓密处如堆积的新絮,稀疏时象漂洗的轻纱，风起云涌如汹？ヅ炫鹊耐蚯悴ㄌ巍Ｊ币？时现的山峰，恰似大海中的小岛。云波扑面而来，四周白范茫一片，使人飘飘若仙，清人诗云相会处，凭空移步作神仙。整体感受是超出预期，值得专门打卡。二刷意愿：是。', '2%', 39);
