INSERT INTO `travel_review` VALUES (17093, 'TR017093', '龙鹄山', '眉山', '四川', '文化打卡', '夏季', 3, 1, 568.00, '否', 4, '3月去的龙鹄山，一个人出行。地点在眉山，自驾停车需要提前规划，现场人不算多。这次玩了1天，人均花费约568元，历史文化气息浓。景点印象：龙鹄山，距丹棱县城约3公里。唐代名\"龙鹤山\"，自南宋孝宗皇帝手书\"龙鹄山\"三字赐史学家李焘后更名。龙鹄山山势奇特，恰似一个巍巍巨人，端坐于环绕的群山之中，有人说它像莲台打坐的佛祖，左手拈决，右手抚膝，神态肃穆。据当地人说，足有48座\"磕头…整体感受是体验挺好，推荐来看看。二刷意愿：否。', '0%', 29);
