INSERT INTO `travel_review` VALUES (17124, 'TR017124', '观竹楼', '益阳', '湖南', '周末短途', '秋季', 8, 3, 1153.00, '否', 5, '8月去的观竹楼，和朋友出行。地点在益阳，打车比较省心，现场游客较多。这次玩了3天，人均花费约1153元，历史文化气息浓。景点印象：相传清代文人墨客乐于观竹，县衙为此而建之，解放后1974年修复。观竹楼座落在洪山竹海的极高点，登上观竹楼，一望无际的竹海尽收眼底，令人心旷神怡，留连忘返。整体感受是挺惊喜，很推荐。二刷意愿：否。', '0%', 114);
