INSERT INTO `travel_review` VALUES (17142, 'TR017142', '莲花山', '来宾', '广西', '文化打卡', '秋季', 7, 3, 592.00, '否', 4, '7月去的莲花山，和家人出行。地点在来宾，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了3天，人均花费约592元，氛围感不错。景点印象：巨大的天然氧吧，负离子含量高，空气中略带花香，实属人生一大享受！整体感受是整体不错，推荐来看看。二刷意愿：否。', '12%', 70);
INSERT INTO `travel_review` VALUES (17143, 'TR017143', '上党战役指挥部旧址', '长治', '山西', '城市漫游', '春季', 2, 1, 715.00, '是', 5, '2月去的上党战役指挥部旧址，情侣出行。地点在长治，打车比较省心，现场人不算多。这次玩了1天，人均花费约715元，夜景表现很好。景点印象：位于离襄垣县城西23公里处的大平村，是上党战役指挥部的一个旧址。1945年l0月，刘伯承司令员和邓小平政委率晋冀鲁豫军区指挥部由崔蒙移驻这里，住在小东院孙树章家。在这里指挥了决定上党战役胜负的老爷山、磨盘垴打援战和土落截击战，取得了上党战…整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 55);
