INSERT INTO `travel_review` VALUES (17146, 'TR017146', '大丰斗龙庄园', '盐城', '江苏', '文化打卡', '夏季', 5, 3, 565.00, '是', 5, '5月去的大丰斗龙庄园，一个人出行。地点在盐城，打车比较省心，现场人流量适中。这次玩了3天，人均花费约565元，氛围感不错。景点印象：大丰斗龙庄园地处大丰斗龙港南侧，占地总面积为10600亩。其中水面养殖10000亩。庄园以生态学为原理，充分利用大丰地区的自然优势，结合当地古文化、民俗农情，形成一个集生态保护、农业发展、旅游度假为一体的多文化发展的庄园体系。目前，建有花卉…整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 86);
