INSERT INTO `travel_review` VALUES (17180, 'TR017180', '牛头山国家森林公园', '金华', '浙江', '深度游', '春季', 12, 3, 882.00, '否', 5, '12月去的牛头山国家森林公园，和朋友出行。地点在金华，打车比较省心，现场人流量适中。这次玩了3天，人均花费约882元，氛围感不错。景点印象：走走横跨两座山头的金锁桥，长长的悬索桥惊险刺激。 冬天泡温泉，夏天玩漂流，滋味各不相同。整体感受是超出预期，值得专门打卡。二刷意愿：否。', '2%', 71);
INSERT INTO `travel_review` VALUES (17181, 'TR017181', '诸葛墓祠', '德阳', '四川', '文化打卡', '夏季', 3, 2, 604.00, '是', 5, '3月去的诸葛墓祠，一个人出行。地点在德阳，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约604元，拍照很出片。景点印象：绵竹诸葛瞻父子墓祠（又名诸葛双忠祠），是四川省重要的蜀汉遗迹之一。它与成都武侯祠遥遥相对，都是为了纪念诸葛一门“三世忠贞”而建的。 \n在成都武侯祠大殿内供奉有诸葛亮祖孙三代于一堂的塑像，而绵竹双忠祠原有的塑像也是祖孙三代，前殿祀诸葛…整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '0%', 40);
