INSERT INTO `travel_review` VALUES (17184, 'TR017184', '七一冰川', '张掖', '甘肃', '周末短途', '夏季', 3, 3, 954.00, '否', 4, '3月去的七一冰川，和朋友出行。地点在张掖，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了3天，人均花费约954元，夜景表现很好。景点印象：“七一”冰川位于嘉峪关市西南116公里处的祁连山腹地，每到夏秋季节，冰峰在蓝天丽日下分外晶莹耀眼，与潺潺的溪流以及绿草如茵、鲜花盛开的高山牧场，共同构成一幅恬静而又充满生机的迷人画卷。整体感受是体验挺好，推荐来看看。二刷意愿：否。', '13%', 90);
