INSERT INTO `travel_review` VALUES (17200, 'TR017200', '东坡书院', '儋州', '海南', '亲子出游', '春季', 2, 2, 679.00, '否', 5, '2月去的东坡书院，和朋友出行。地点在儋州，打车比较省心，现场游客较多。这次玩了2天，人均花费约679元，夜景表现很好。景点印象：探访历史上著名的苏轼讲学场所，寻觅一代大师的足迹。整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '37%', 98);
INSERT INTO `travel_review` VALUES (17201, 'TR017201', '五堡墓地', '哈密', '新疆', '拍照旅行', '冬季', 11, 3, 847.00, '否', 4, '11月去的五堡墓地，和朋友出行。地点在哈密，公交换乘方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约847元，氛围感不错。景点印象：位于哈密市五堡乡政府西北2公里。南距五堡水库约1公里。青铜时代文化遗存。为原始社会晚期阶段的氏族公社墓地，距今约3000余年。海拔525米。1990年被列为新疆维吾尔自治区文物保护单位。\n出土随葬品除墓主随身鞋帽、衣服外，大多是日常用品和生产工…整体感受是整体不错，周末来刚好。二刷意愿：否。', '0%', 74);
INSERT INTO `travel_review` VALUES (17202, 'TR017202', '殷墟', '安阳', '河南', '深度游', '春季', 2, 2, 920.00, '是', 5, '2月去的殷墟，和朋友出行。地点在安阳，自驾停车需要提前规划，现场游客较多。这次玩了2天，人均花费约920元，氛围感不错。景点印象：出土了大量的珍贵文物，包括司母戊大方鼎、妇好鸮尊等。整体感受是超出预期，以后还会来。二刷意愿：是。', '45%', 54);
INSERT INTO `travel_review` VALUES (17203, 'TR017203', '喜德寺', '拉萨', '西藏', '城市漫游', '夏季', 5, 3, 741.00, '是', 5, '5月去的喜德寺，情侣出行。地点在拉萨，地铁到达方便，现场游客较多。这次玩了3天，人均花费约741元，拍照很出片。景点印象：它非常古老，是拉萨四大林之一，始建于公元9世纪初的吐蕃王朝。整体感受是超出预期，值得专门打卡。二刷意愿：是。', '0%', 95);
