INSERT INTO `travel_review` VALUES (17206, 'TR017206', '敦煌博物馆', '酒泉', '甘肃', '城市漫游', '夏季', 5, 1, 309.00, '是', 4, '5月去的敦煌博物馆，和家人出行。地点在酒泉，地铁到达方便，现场人不算多。这次玩了1天，人均花费约309元，拍照很出片。景点印象：参观莫高窟内没有开放的石窟模样，还有重要文物“敦煌遗书”，了解敦煌的历史。 可以参观丝绸之路的历史文物，麒麟砖等文物十分罕见。整体感受是体验挺好，推荐来看看。二刷意愿：是。', '7%', 90);
INSERT INTO `travel_review` VALUES (17207, 'TR017207', '曹州武术馆', '菏泽', '山东', '文化打卡', '秋季', 6, 1, 445.00, '否', 5, '6月去的曹州武术馆，情侣出行。地点在菏泽，公交换乘方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约445元，氛围感不错。景点印象：曹州武术馆是国家教委、体委批准认可的一所大型规范化、军事化教武育人的训练基地。本馆指导思想是：“以文保武”，“以武促文”、“以质量求生存”，“以信誉求发展”以法治馆，以德育人，培养“四有”人才，以传授和发扬中华武术为已任。整体感受是特别满意，值得专门打卡。二刷意愿：否。', '0%', 81);
