INSERT INTO `travel_review` VALUES (17218, 'TR017218', '李自成墓', '咸宁', '湖北', '城市漫游', '夏季', 5, 2, 670.00, '否', 4, '5月去的李自成墓，和家人出行。地点在咸宁，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了2天，人均花费约670元，拍照很出片。景点印象：在通山县九宫山下牛迹岭。李自成（1606一1645），明末农民起义领袖。本名鸿基，陕西省米脂人。据记载，大顺永昌二年（1645年）初夏，他由武昌挥师东下南京，因形势逆转，征途受阻，即取道九宫山转战江西，不意在山下李家铺突遭清军袭击，仓促突围，…整体感受是整体不错，可以安排半天到一天。二刷意愿：否。', '0%', 63);
