INSERT INTO `travel_review` VALUES (17242, 'TR017242', '吞力黑衣壮民族风情园', '百色', '广西', '周末短途', '春季', 2, 1, 438.00, '否', 2, '2月去的吞力黑衣壮民族风情园，一个人出行。地点在百色，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约438元，历史文化气息浓。景点印象：吞力屯地处那坡县北部的石山区，属城厢镇龙华村所管辖，全屯共57户250多人，为壮族支系“黑衣壮”的聚居地之一。由于居住条件恶劣，交通不便，信息闭塞，2002年以前该屯年人均纯收入仅900元，属城厢镇典型的特困屯之一。 时光荏苒，斗转星移，吞力…整体感受是没达到预期，不建议高峰来。二刷意愿：否。', '2%', 0);
