INSERT INTO `travel_review` VALUES (17260, 'TR017260', '松鹤西湖滑雪狩猎场', '鹤岗', '黑龙江', '周末短途', '夏季', 4, 6, 1489.00, '是', 5, '4月去的松鹤西湖滑雪狩猎场，一个人出行。地点在鹤岗，公交换乘方便，现场人不算多。这次玩了6天，人均花费约1489元，夜景表现很好。景点印象：该场位于西郊松鹤西湖公园的笃斯山，山上有两条长800米的雪道和一个小动物狩猎场，山下湖中有冰上旅游项目，包括：滑冰、冰滑梯、冰上保龄球、狗拉雪撬等，是冬季溜冰滑雪的乐园。整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 78);
