INSERT INTO `travel_review` VALUES (17263, 'TR017263', '吕祖泉', '莱芜', '山东', '周末短途', '春季', 1, 1, 376.00, '是', 5, '1月去的吕祖泉，一个人出行。地点在莱芜，地铁到达方便，现场游客较多。这次玩了1天，人均花费约376元，夜景表现很好。景点印象：吕祖泉旅游区位于著名的雪野水库北侧，距济南 60 公里、莱芜 30 公里，占地 3800 亩。据传吕洞宾在此修炼成仙，这里三面环山，森林茂密，山泉常年不断，自然景观众多，比较有名的有：白水泉、仙乳峰、仙乳石、仙拳、仙脚印、睡天鹅石、神蛙石、怪兽…整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 94);
