INSERT INTO `travel_review` VALUES (17268, 'TR017268', '菩萨庙镇小岛', '丹东', '辽宁', '文化打卡', '春季', 12, 1, 603.00, '否', 5, '12月去的菩萨庙镇小岛，一个人出行。地点在丹东，地铁到达方便，现场游客较多。这次玩了1天，人均花费约603元，拍照很出片。景点印象：位于菩萨庙镇南的小岛，距孤山镇15公里,由大小14个小岛组成， 其中六个较大岛有海堤相连，陆域面积17平方公里，岛南海滩白沙细软，水清无尘，三面青山环抱，南面一望无际大海，海天一色。小岛形状各异，各具特色，有熊猫、骏马、园林等奇形怪礁，是…整体感受是特别满意，以后还会来。二刷意愿：否。', '0%', 38);
