INSERT INTO `travel_review` VALUES (17278, 'TR017278', '南山特产', '邵阳', '湖南', '文化打卡', '秋季', 6, 2, 590.00, '是', 4, '6月去的南山特产，和家人出行。地点在邵阳，地铁到达方便，现场人流量适中。这次玩了2天，人均花费约590元，拍照很出片。景点印象：南山奶粉\n“南山”牌系列乳制品以“凉开水即溶，喝了不上火”蜚声全国，被誉为“南国净土里长出的绿色食品”，其中婴幼儿系列奶粉为“国家免检产品”。南山奶粉畅销全国近30个省、自治区、直辖市，成为全国奶粉行业十大畅销产品，在广大消费者的心…整体感受是整体不错，推荐来看看。二刷意愿：是。', '0%', 81);
