INSERT INTO `travel_review` VALUES (17292, 'TR017292', '张居正墓', '荆州', '湖北', '城市漫游', '春季', 2, 1, 452.00, '否', 5, '2月去的张居正墓，一个人出行。地点在荆州，打车比较省心，现场人不算多。这次玩了1天，人均花费约452元，氛围感不错。景点印象：在荆州市沙市西北张家台。张居正（1525-1582），明政治家，字叔大，号太岳，世居江陵。嘉靖进士，神宗时为相，曾下令清丈土地，推行一条鞭法，改革赋税制度，裁减冗员，加强边防，浚治河道等都有成效。死后葬此。墓前原有石人、石马等附属文物，现…整体感受是超出预期，很推荐。二刷意愿：否。', '0%', 68);
