INSERT INTO `travel_review` VALUES (17306, 'TR017306', '梭筛', '安顺', '贵州', '城市漫游', '秋季', 6, 2, 209.00, '否', 5, '6月去的梭筛，和家人出行。地点在安顺，自驾停车需要提前规划，现场游客较多。这次玩了2天，人均花费约209元，历史文化气息浓。景点印象：位于贵州省西线风景旅游区境内，地域位置优越，风景区总面积55平方公里。具有比较丰富的岩溶地貌。\n为特征的自然景观和人文景观。峡谷风光秀丽的梭筛水库，该水库因建设普定水电站而形成高峡平湖，主要有双龙峡景点、剑门峡景点、虎跳峡景点、尤其…整体感受是挺惊喜，很推荐。二刷意愿：否。', '0%', 57);
