INSERT INTO `travel_review` VALUES (17325, 'TR017325', '莽山森林温泉', '郴州', '湖南', '周末短途', '秋季', 8, 1, 584.00, '否', 2, '8月去的莽山森林温泉，情侣出行。地点在郴州，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约584元，历史文化气息浓。景点印象：蟒山森林温泉位于莽山国家森林公园入口1公里处，依托莽山良好的生态环境，有着深厚的文化底蕴和独特的建筑风格，环境宁静自然，空气清新。整体感受是体验偏一般，不建议高峰来。二刷意愿：否。', '1%', 71);
