INSERT INTO `travel_review` VALUES (17335, 'TR017335', '棋盘滩', '百色', '广西', '亲子出游', '秋季', 8, 6, 1445.00, '否', 5, '8月去的棋盘滩，和家人出行。地点在百色，公交换乘方便，现场高峰时段比较拥挤。这次玩了6天，人均花费约1445元，氛围感不错。景点印象：棋盘滩风景区由棋盘滩、莲花山、寄情谷、独木成林、布洛佗石像等景点构成。棋盘滩是棋盘滩风景区的核心。棋盘滩形成于2亿多年前，是地壳运动过程中的产物。这种地质结构称为“剪节理”。这种地质结构方式许多地方都有，但一般来说别处都是在斜坡上…整体感受是特别满意，以后还会来。二刷意愿：否。', '2%', 69);
