INSERT INTO `travel_review` VALUES (17350, 'TR017350', '梅湾湖', '眉山', '四川', '深度游', '夏季', 5, 2, 679.00, '否', 4, '5月去的梅湾湖，情侣出行。地点在眉山，公交换乘方便，现场人不算多。这次玩了2天，人均花费约679元，氛围感不错。景点印象：梅湾湖，又名梅湾水库。位于丹棱县城西中隆乡梅湾村，距县城6公里，是七十年代大兴水利时建造的人工湖。集雨面积15.3平方公里，总库容1015万立方米，设计灌面3.16万亩，属中型水利工程，居丹棱水利工程之首。控灌丹棱镇、中隆乡、何场乡和唐河乡，…整体感受是还蛮满意，推荐来看看。二刷意愿：否。', '0%', 57);
