INSERT INTO `travel_review` VALUES (17370, 'TR017370', '万岁山', '开封', '河南', '亲子出游', '春季', 1, 1, 549.00, '否', 2, '1月去的万岁山，一个人出行。地点在开封，打车比较省心，现场人流量适中。这次玩了1天，人均花费约549元，历史文化气息浓。景点印象：万岁山藏自然山水美与人工美于一体，括天下之绝，含古今之胜，集我国古代南北园林建筑艺术之大成，荟萃华夏名山大川雄伟、险峻、奇秀、幽美、畅旷诸特色，成为全国山水奇景的一个缩影，堪称世界一绝。整体感受是没达到预期，建议谨慎前往。二刷意愿：否。', '1%', 42);
