INSERT INTO `travel_review` VALUES (17374, 'TR017374', '曲龙银城', '阿里', '西藏', '周末短途', '春季', 2, 5, 1210.00, '是', 5, '2月去的曲龙银城，一个人出行。地点在阿里，自驾停车需要提前规划，现场人流量适中。这次玩了5天，人均花费约1210元，夜景表现很好。景点印象：曲龙银城，又称穹隆银城。象雄国的古都——“大鹏之地”，它比古格王国更大年代更久远，而风化破坏也更为严重。整体感受是挺惊喜，很推荐。二刷意愿：是。', '1%', 66);
