INSERT INTO `travel_review` VALUES (17380, 'TR017380', '中苏街', '呼伦贝尔', '内蒙古', '深度游', '夏季', 5, 2, 678.00, '是', 4, '5月去的中苏街，情侣出行。地点在呼伦贝尔，公交换乘方便，现场人不算多。这次玩了2天，人均花费约678元，夜景表现很好。景点印象：中苏街在解放前称博士街，是满洲里早期隆太号、恒盛福、福海长、吉顺富、义聚德、尼基金旅馆等众多商家聚集地。解放后为纪念中国与前苏联的友好合作改称中苏街。整体感受是还蛮满意，可以安排半天到一天。二刷意愿：是。', '2%', 40);
INSERT INTO `travel_review` VALUES (17381, 'TR017381', '聚奎塔', '琼海', '海南', '城市漫游', '春季', 2, 3, 1213.00, '否', 5, '2月去的聚奎塔，情侣出行。地点在琼海，打车比较省心，现场高峰时段比较拥挤。这次玩了3天，人均花费约1213元，拍照很出片。景点印象：聚奎塔高近30米，一共七层，每升高一层，高与宽都相应缩减。塔身中空，底有塔座，四周有墙，正门朝北，楣上端有石匾，上书“聚奎塔”。塔体仿唐代建筑，造型古朴别致。外表每层由八个墙面构成，属楼阁式砖檐塔，七面各筑一个假门，只有一面筑真门。…整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '3%', 74);
