INSERT INTO `travel_review` VALUES (17392, 'TR017392', '王家屏墓', '朔州', '山西', '文化打卡', '秋季', 6, 2, 402.00, '否', 5, '6月去的王家屏墓，和家人出行。地点在朔州，打车比较省心，现场游客较多。这次玩了2天，人均花费约402元，拍照很出片。景点印象：位于山阴县西南15公里的泥河乡河阳堡村南，是明代著名政治家王家屏之墓，为省级重点文物保护单位。王家屏墓占地 10168平方米，规模宏大，地面享堂犹存，有石人、石羊、石马等仪仗及碑石10通，碑文大部分为圣旨加封等内容，现已破坏严重。整体感受是挺惊喜，很推荐。二刷意愿：否。', '0%', 84);
