INSERT INTO `travel_review` VALUES (17478, 'TR017478', '络丝潭', '安阳', '河南', '深度游', '冬季', 9, 2, 1016.00, '是', 5, '9月去的络丝潭，和家人出行。地点在安阳，打车比较省心，现场游客较多。这次玩了2天，人均花费约1016元，氛围感不错。景点印象：处在青年洞西约1公里处的络丝潭风景区，亦被人称为“天桥断”。“络丝潭”因其潭深达一络蚕丝而得名，又因浊漳河有“九峡十八断”，此处是一较大断崭跌水，上有连接豫、冀两省的峡谷索桥，故又称“天桥断”。这里有漳河名胜“小三峡”，可放艇畅游…整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 97);
INSERT INTO `travel_review` VALUES (17479, 'TR017479', '南禅寺', '忻州', '山西', '城市漫游', '冬季', 11, 4, 1354.00, '是', 4, '11月去的南禅寺，情侣出行。地点在忻州，公交换乘方便，现场人流量适中。这次玩了4天，人均花费约1354元，拍照很出片。景点印象：寺中的大佛殿，是我国现存较为古老的木结构建筑。 寺中的大殿、殿内的彩塑和砖雕，还有寺内的石狮、石塔，都是唐代的遗物。整体感受是整体不错，可以安排半天到一天。二刷意愿：是。', '7%', 69);
