INSERT INTO `travel_review` VALUES (17489, 'TR017489', '龙园', '天水', '甘肃', '亲子出游', '春季', 1, 2, 642.00, '否', 5, '1月去的龙园，和朋友出行。地点在天水，打车比较省心，现场人不算多。这次玩了2天，人均花费约642元，拍照很出片。景点印象：位于渭水之滨，文山之阴，坐西面东，占地一十三亩。主体成纪殿，乃歇山重檐九开间明清式建筑。长四十五米、高二十七米，进深一十三米六。整体感受是特别满意，以后还会来。二刷意愿：否。', '0%', 73);
INSERT INTO `travel_review` VALUES (17490, 'TR017490', '南昆山国家森林公园', '惠州', '广东', '亲子出游', '秋季', 7, 2, 508.00, '是', 5, '7月去的南昆山国家森林公园，和家人出行。地点在惠州，地铁到达方便，现场游客较多。这次玩了2天，人均花费约508元，夜景表现很好。景点印象：很大的森林公园，植物种类特别多，3月可以在天堂顶看到绚烂的杜鹃花海。整体感受是超出预期，很推荐。二刷意愿：是。', '10%', 69);
INSERT INTO `travel_review` VALUES (17491, 'TR017491', '飞天山风景区', '郴州', '湖南', '深度游', '夏季', 3, 1, 290.00, '是', 5, '3月去的飞天山风景区，和朋友出行。地点在郴州，打车比较省心，现场人不算多。这次玩了1天，人均花费约290元，夜景表现很好。景点印象：飞天山国家地质公园以寨（堡）丹霞地貌为主，包容了白垩纪断陷盆地，石炭纪岩溶洞穴和温泉水体等地质遗迹类型，石田、石笋、石钟乳、石柱、石幔、石帘密布，形态各异，气象万千，集山、水、林、洞、佛为一体，聚雄、奇、险、秀、巧为一身。区内除了…整体感受是挺惊喜，以后还会来。二刷意愿：是。', '4%', 116);
