INSERT INTO `travel_review` VALUES (17500, 'TR017500', '大唐秦王陵', '宝鸡', '陕西', '深度游', '冬季', 9, 1, 531.00, '否', 3, '9月去的大唐秦王陵，和朋友出行。地点在宝鸡，公交换乘方便，现场人不算多。这次玩了1天，人均花费约531元，氛围感不错。景点印象：大唐秦王陵是陕西省重点文物保护单位，大唐秦王陵博物馆位于陕西宝鸡市北坡公园顶，是展示唐末秦王李茂贞及夫人刘氏“同茔不同穴”的合葬陵寝为样板的专题博物馆。整体感受是体验一般，按需选择。二刷意愿：否。', '0%', 43);
