INSERT INTO `travel_review` VALUES (17517, 'TR017517', '锦江瀑布', '白山', '吉林', '文化打卡', '春季', 1, 2, 658.00, '否', 5, '1月去的锦江瀑布，情侣出行。地点在白山，地铁到达方便，现场人不算多。这次玩了2天，人均花费约658元，氛围感不错。景点印象：锦江瀑布又叫梯河瀑布，是二级瀑布，两级落差共70米。巨大水流聚然从黑褐色的火山岩陡崖上跌落，激起白色的水雾。瀑布声如雷鸣，水花四溅，靠近瀑布，就能感到水雾缭绕，全身凉透的感觉。整体感受是特别满意，值得专门打卡。二刷意愿：否。', '3%', 76);
