INSERT INTO `travel_review` VALUES (17541, 'TR017541', '古龙山大峡谷', '百色', '广西', '文化打卡', '秋季', 6, 1, 467.00, '是', 5, '6月去的古龙山大峡谷，情侣出行。地点在百色，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约467元，拍照很出片。景点印象：乘船漂流在清新山水和壮观溶洞之间，感受大自然的秀美和奇幻。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '0%', 111);
INSERT INTO `travel_review` VALUES (17542, 'TR017542', '乌兰木图山', '阜新', '辽宁', '周末短途', '春季', 1, 4, 738.00, '是', 5, '1月去的乌兰木图山，和家人出行。地点在阜新，自驾停车需要提前规划，现场游客较多。这次玩了4天，人均花费约738元，氛围感不错。景点印象：阜蒙县八家子乡境内的乌兰木图山，早年叫阿力玛图山。两个名都是蒙语的音译，前者汉译为“有红色树木之山”，后者译为“有梨之山”。梨山之名更久。\n　　这座山的主峰叫锅底山，海拔高度831.4米，是阜新市第一高峰。站在主峰上近观远眺，收入眼帘的…整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 103);
