INSERT INTO `travel_review` VALUES (17545, 'TR017545', '圣弥厄尔教堂', '青岛', '山东', '深度游', '冬季', 9, 1, 823.00, '否', 2, '9月去的圣弥厄尔教堂，一个人出行。地点在青岛，地铁到达方便，现场人不算多。这次玩了1天，人均花费约823元，夜景表现很好。景点印象：青岛著名的西洋建筑，拍摄最洋气留念照，附近景点众多。整体感受是没达到预期，可考虑其他景点。二刷意愿：否。', '53%', 27);
INSERT INTO `travel_review` VALUES (17546, 'TR017546', '水库', '保山', '云南', '亲子出游', '秋季', 7, 1, 320.00, '是', 5, '7月去的水库，一个人出行。地点在保山，打车比较省心，现场游客较多。这次玩了1天，人均花费约320元，历史文化气息浓。景点印象：周边配套比较齐全整体感受是超出预期，值得专门打卡。二刷意愿：是。', '0%', 64);
INSERT INTO `travel_review` VALUES (17547, 'TR017547', '东大山', '张掖', '甘肃', '城市漫游', '春季', 12, 1, 567.00, '否', 5, '12月去的东大山，和朋友出行。地点在张掖，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约567元，历史文化气息浓。景点印象：东大山自然保护区是河西走廊北山的一部分，东经100度45分-100度51分，北纬39度0分-39度04分，距张掖市城东30km处，呈西北西走向。东大山是中生代以来发育成的断块山，属阿拉善台块的一部分，在大地貌上具有断块山的一般特征。 保护区各类森林是河西…整体感受是超出预期，值得专门打卡。二刷意愿：否。', '0%', 65);
INSERT INTO `travel_review` VALUES (17548, 'TR017548', '紫岩山', '德阳', '四川', '文化打卡', '夏季', 5, 3, 914.00, '是', 5, '5月去的紫岩山，和朋友出行。地点在德阳，打车比较省心，现场人流量适中。这次玩了3天，人均花费约914元，氛围感不错。景点印象：紫岩山又名绵竹山，地处成都平原与岷山山脉交汇处，西北面高山天作，群峰叠翠。沱江之源绵远河蜿蜒出群山，一泻千里，形成成都平原北端的一个扇形冲击面棗绵竹市平坝区。在这片山地与平原交汇处，分布着许多名胜古迹和优美的自然景观，有风光秀丽的…整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 91);
INSERT INTO `travel_review` VALUES (17549, 'TR017549', '沙土湾', '澄迈', '海南', '深度游', '秋季', 8, 1, 175.00, '否', 5, '8月去的沙土湾，情侣出行。地点在澄迈，自驾停车需要提前规划，现场游客较多。这次玩了1天，人均花费约175元，夜景表现很好。景点印象：景点本身有一定特色整体感受是特别满意，很推荐。二刷意愿：否。', '0%', 79);
INSERT INTO `travel_review` VALUES (17550, 'TR017550', '三色湖', '昌都', '西藏', '周末短途', '春季', 1, 1, 261.00, '是', 5, '1月去的三色湖，一个人出行。地点在昌都，自驾停车需要提前规划，现场人不算多。这次玩了1天，人均花费约261元，历史文化气息浓。景点印象：三色湖距县城近50公里。从县城驱车，途经连片的沙棘林，穿过藏东风格独具的村庄，就可以到达海拔4200米左右的三色湖群。\n白湖藏语称“错嘎”，湖色灰白，绿树倒映湖面，鱼儿跳跃湖上。黑湖藏语称“错那”，三湖中面积最大，远看似墨，群山环抱，深…整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 97);
INSERT INTO `travel_review` VALUES (17551, 'TR017551', '群英湖', '焦作', '河南', '深度游', '夏季', 3, 1, 474.00, '是', 5, '3月去的群英湖，情侣出行。地点在焦作，地铁到达方便，现场人不算多。这次玩了1天，人均花费约474元，氛围感不错。景点印象：群英湖风景名胜区地处太行山前沿，面积约25平方公里，跨越焦作市区、修武县、博爱县与山西省晋城市地界。 群英湖风景区内景点集中，分布均匀。河流、湖泊深秀，高山、峡谷险峻，悬崖、溶洞遍布，奇峰、怪石林立。有寺庙、古树，有台地、草坪，有丛…整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 44);
INSERT INTO `travel_review` VALUES (17552, 'TR017552', '太行屋脊景区', '安阳', '河南', '文化打卡', '夏季', 5, 2, 698.00, '否', 5, '5月去的太行屋脊景区，一个人出行。地点在安阳，打车比较省心，现场人不算多。这次玩了2天，人均花费约698元，夜景表现很好。景点印象：周边配套比较齐全整体感受是特别满意，以后还会来。二刷意愿：否。', '4%', 100);
INSERT INTO `travel_review` VALUES (17553, 'TR017553', '一天门', '十堰', '湖北', '深度游', '冬季', 11, 2, 554.00, '是', 5, '11月去的一天门，和朋友出行。地点在十堰，地铁到达方便，现场游客较多。这次玩了2天，人均花费约554元，历史文化气息浓。景点印象：在攀登武当山金顶的古神道上，建有三座天门，额书一天门、二天门、三天门。三座天门均为明永乐十年在元代旧址上敕建，砖石结构，歇山顶式，下层为石雕须弥座，石雕的水盘檐为仿木结构。三座天门气势恢宏，依次屹立在数千级饰栏石阶之间，古人赞美曰…整体感受是超出预期，很推荐。二刷意愿：是。', '4%', 89);
