INSERT INTO `travel_review` VALUES (17569, 'TR017569', '雪帽山', '营口', '辽宁', '城市漫游', '秋季', 8, 4, 1237.00, '是', 5, '8月去的雪帽山，一个人出行。地点在营口，自驾停车需要提前规划，现场人不算多。这次玩了4天，人均花费约1237元，拍照很出片。景点印象：雪帽山位于盖州市九寨镇，山峻林密，古朴原始，风光秀丽。山上土质肥沃，植被丰富，生长着几十个种类、近千亩的阔叶林，以及上百种中草药和山野菜。一年四季花开不断。\n       这里还生活着几十种野生动物，随时可见松鼠、山鸡跳跃山间，野鹿、狍子…整体感受是超出预期，值得专门打卡。二刷意愿：是。', '6%', 100);
