INSERT INTO `travel_review` VALUES (17604, 'TR017604', '五顶山国家森林公园', '佳木斯', '黑龙江', '拍照旅行', '秋季', 7, 3, 1075.00, '是', 5, '7月去的五顶山国家森林公园，和家人出行。地点在佳木斯，地铁到达方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约1075元，拍照很出片。景点印象：国家AA级旅游风景区五顶山森林公园由卧虎力山和乌尔古力山两条山脉组成，位于富锦城东南11公里处，为西北东南走向，总面积3806公顷，乌尔古力山主峰海拔543米。\n　　五顶山国家森林公园有10多个景区，整个五顶山上有108座碉堡。1958年花果山园艺场…整体感受是超出预期，以后还会来。二刷意愿：是。', '5%', 99);
