INSERT INTO `travel_review` VALUES (17614, 'TR017614', '茂兰喀斯特森林', '黔南', '贵州', '城市漫游', '夏季', 4, 4, 1170.00, '是', 5, '4月去的茂兰喀斯特森林，和家人出行。地点在黔南，自驾停车需要提前规划，现场人流量适中。这次玩了4天，人均花费约1170元，拍照很出片。景点印象：茂兰自然保护区是国家级自然保护区，也是南方喀斯特自然遗产最重要的组成部分，这里分布着喀斯特的森林、山水、溶洞和珍稀动植物，这里还生活着布依、水族、瑶族等少数民族几千名原始居民。整体感受是超出预期，值得专门打卡。二刷意愿：是。', '18%', 61);
