INSERT INTO `travel_review` VALUES (17640, 'TR017640', '渡蚁桥', '随州', '湖北', '拍照旅行', '夏季', 5, 1, 80.00, '是', 5, '5月去的渡蚁桥，和家人出行。地点在随州，公交换乘方便，现场人不算多。这次玩了1天，人均花费约80元，拍照很出片。景点印象：在广水市西原应山县城南郊。为纪念北来宋庠、宋祁以竹渡蚁而建，故名。宋库（996一1066）与其弟宋祁（998-1061），安陆（今属湖北）人，后迁开封雍丘（今河南杞县）。皆北宋大臣，有文名，时称“二宋”。天圣二年（1024年）二宋同举进士，库名列第…整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 98);
