INSERT INTO `travel_review` VALUES (17646, 'TR017646', '将军石山庄', '鹤岗', '黑龙江', '拍照旅行', '冬季', 10, 4, 1236.00, '否', 5, '10月去的将军石山庄，和家人出行。地点在鹤岗，打车比较省心，现场游客较多。这次玩了4天，人均花费约1236元，拍照很出片。景点印象：将军石山庄(国家3A级风景区)――始建于1974年。当时是知青点。1986年改建并起名为将军石山庄。位于鹤岗市南郊21公里处，地处小兴安岭南麓，与佳木斯、伊春交界，景色旖丽，是我市唯一一处具有悠久历史文化传说的旅游景点。将军石山、横盘山扼守山庄…整体感受是超出预期，以后还会来。二刷意愿：否。', '0%', 77);
