INSERT INTO `travel_review` VALUES (17736, 'TR017736', '东方大学城', '廊坊', '河北', '文化打卡', '冬季', 9, 3, 1013.00, '否', 4, '9月去的东方大学城，和家人出行。地点在廊坊，打车比较省心，现场人不算多。这次玩了3天，人均花费约1013元，拍照很出片。景点印象：东方大学城位于廊坊市经济技术开发区，紧靠京津塘高速公路，距北京40公里，天津60公里。\n东方大学城占地2万亩，计划投资120亿元人民币，10年内要完成包括教学楼、科研实验楼、现代图书馆、运动中心、老师公寓以及幼教、小学、中学、医疗、商业餐饮…整体感受是还蛮满意，周末来刚好。二刷意愿：否。', '100%', 49);
