INSERT INTO `travel_review` VALUES (17775, 'TR017775', '师宗通玄洞', '曲靖', '云南', '亲子出游', '春季', 1, 4, 1132.00, '是', 4, '1月去的师宗通玄洞，和家人出行。地点在曲靖，地铁到达方便，现场人流量适中。这次玩了4天，人均花费约1132元，氛围感不错。景点印象：师宗的通玄洞，分上洞、中洞、水洞（水洞尚未对外开放）。\n上洞高大宽敞，洞中有山，洞中套洞，大厅一个连着一个， 钟乳石千姿百态，多为白色和朱红色。最为典型的是“两重天”，因下层呈朱红色，上层为乳白石，故人们把它形象地称为两重天。它的顶…整体感受是整体不错，可以安排半天到一天。二刷意愿：是。', '0%', 72);
