INSERT INTO `travel_review` VALUES (17814, 'TR017814', '灵岩寺', '济南', '山东', '拍照旅行', '春季', 2, 3, 552.00, '否', 5, '2月去的灵岩寺，情侣出行。地点在济南，打车比较省心，现场人不算多。这次玩了3天，人均花费约552元，拍照很出片。景点印象：欣赏九层辟支塔塔基上的浮雕；寺后山上可访卓锡泉、袈裟泉及甘露泉。整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '2%', 75);
