INSERT INTO `travel_review` VALUES (17816, 'TR017816', '桃花岛风景区', '舟山', '浙江', '拍照旅行', '冬季', 9, 1, 616.00, '是', 5, '9月去的桃花岛风景区，和朋友出行。地点在舟山，打车比较省心，现场人流量适中。这次玩了1天，人均花费约616元，氛围感不错。景点印象：登岛寻觅《射雕英雄传》踪迹，在安期峰俯瞰舟山群岛的迷人风光。整体感受是特别满意，很推荐。二刷意愿：是。', '11%', 92);
INSERT INTO `travel_review` VALUES (17817, 'TR017817', '云龙河地缝', '恩施', '湖北', '城市漫游', '春季', 12, 6, 1155.00, '是', 5, '12月去的云龙河地缝，一个人出行。地点在恩施，公交换乘方便，现场高峰时段比较拥挤。这次玩了6天，人均花费约1155元，夜景表现很好。景点印象：世界上唯一两岸不同地质年代的地缝。绝壁环峰从，地缝接飞瀑整体感受是特别满意，以后还会来。二刷意愿：是。', '11%', 84);
