INSERT INTO `travel_review` VALUES (17820, 'TR017820', '恩施大峡谷', '恩施', '湖北', '文化打卡', '秋季', 7, 2, 377.00, '是', 4, '7月去的恩施大峡谷，一个人出行。地点在恩施，地铁到达方便，现场游客较多。这次玩了2天，人均花费约377元，夜景表现很好。景点印象：层层叠叠的峰丛，近乎垂直于峡谷的大断崖。整体感受是整体不错，可以安排半天到一天。二刷意愿：是。', '55%', 51);
INSERT INTO `travel_review` VALUES (17821, 'TR017821', '庐山北门', '九江', '江西', '深度游', '春季', 2, 3, 617.00, '是', 5, '2月去的庐山北门，和朋友出行。地点在九江，打车比较省心，现场人流量适中。这次玩了3天，人均花费约617元，拍照很出片。景点印象：庐山北门坐落于九江市庐山区威家镇，是原庐山登山口处，占地108060平方米。主要包括游客换乘服务中心大楼（天和楼）、停车场、迎宾广场、”庐山真面目”石雕景观模型、雕塑石柱门和冰川景观石等，能同时容纳3000多名游客。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 64);
INSERT INTO `travel_review` VALUES (17822, 'TR017822', '黄河古渡', '运城', '山西', '深度游', '夏季', 4, 1, 305.00, '否', 5, '4月去的黄河古渡，情侣出行。地点在运城，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约305元，历史文化气息浓。景点印象：奔腾咆哮的黄河，一出龙门，被秦岭山脉阻拦，于是掉头向东，浩浩荡荡，蜿蜒于宽达10多公里的河道上，穿中原，过齐鲁，驰骋千里，汇入渤海。沿途山川险要，良田万顷，车马如潮，景色宜人。在黄河北岸的山西省境内，从上流到下流，相继有风陵渡、大禹…整体感受是超出预期，很推荐。二刷意愿：否。', '2%', 111);
INSERT INTO `travel_review` VALUES (17823, 'TR017823', '一天门', '十堰', '湖北', '亲子出游', '夏季', 3, 6, 1881.00, '否', 4, '3月去的一天门，和朋友出行。地点在十堰，打车比较省心，现场游客较多。这次玩了6天，人均花费约1881元，夜景表现很好。景点印象：在攀登武当山金顶的古神道上，建有三座天门，额书一天门、二天门、三天门。三座天门均为明永乐十年在元代旧址上敕建，砖石结构，歇山顶式，下层为石雕须弥座，石雕的水盘檐为仿木结构。三座天门气势恢宏，依次屹立在数千级饰栏石阶之间，古人赞美曰…整体感受是还蛮满意，可以安排半天到一天。二刷意愿：否。', '4%', 62);
