INSERT INTO `travel_review` VALUES (17840, 'TR017840', '五峰山', '固原', '宁夏', '文化打卡', '冬季', 10, 3, 790.00, '是', 5, '10月去的五峰山，和朋友出行。地点在固原，地铁到达方便，现场游客较多。这次玩了3天，人均花费约790元，拍照很出片。景点印象：五峰山，海拔1523米，山势奇特，中分五指，故名。位于彭阳县城东16公里处的城阳乡韩寨村。北依长城塬，南濒茹河，西临深涧，东接山谷。漫山沙棘葱笼，松柏苍翠，山桃成荫，花红似火，碧草如茵，鸟语花香。似镶嵌在茹河北岸的一颗绿色宝石。身临其境…整体感受是超出预期，值得专门打卡。二刷意愿：是。', '0%', 57);
