INSERT INTO `travel_review` VALUES (17857, 'TR017857', '一线天景区', '南平', '福建', '深度游', '秋季', 8, 3, 789.00, '否', 2, '8月去的一线天景区，和朋友出行。地点在南平，公交换乘方便，现场人不算多。这次玩了3天，人均花费约789元，氛围感不错。景点印象：探身洞中，仰观崖顶裂隙，可见天光一线奇景，最窄处只有30厘米宽。整体感受是略失望，不建议高峰来。二刷意愿：否。', '40%', 40);
INSERT INTO `travel_review` VALUES (17858, 'TR017858', '国家牡丹园', '洛阳', '河南', '亲子出游', '冬季', 10, 2, 869.00, '是', 5, '10月去的国家牡丹园，情侣出行。地点在洛阳，自驾停车需要提前规划，现场游客较多。这次玩了2天，人均花费约869元，拍照很出片。景点印象：每年的四月，游客可以在园中欣赏到几十万株、上千个品种的牡丹花，还能一睹“千年牡丹王”的风采。整体感受是超出预期，以后还会来。二刷意愿：是。', '2%', 86);
