INSERT INTO `travel_review` VALUES (17862, 'TR017862', '运城关公故里文化旅游景区', '运城', '山西', '城市漫游', '秋季', 6, 3, 622.00, '否', 5, '6月去的运城关公故里文化旅游景区，情侣出行。地点在运城，自驾停车需要提前规划，现场游客较多。这次玩了3天，人均花费约622元，夜景表现很好。景点印象：在关羽的家乡，朝拜武圣人关羽，瞻仰关帝祖庙。 这里是国内始建早、规模较大较完整的庙宇。 观赏庙悬挂的康熙、乾隆、咸丰三位皇帝亲笔、钦定的匾额。整体感受是超出预期，值得专门打卡。二刷意愿：否。', '30%', 90);
