INSERT INTO `travel_review` VALUES (17865, 'TR017865', '木心美术馆', '嘉兴', '浙江', '城市漫游', '春季', 2, 4, 1221.00, '是', 5, '2月去的木心美术馆，和家人出行。地点在嘉兴，公交换乘方便，现场高峰时段比较拥挤。这次玩了4天，人均花费约1221元，历史文化气息浓。景点印象：临水而立的美术馆，收藏了木心先生的毕生心血与美学遗产。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '0%', 48);
INSERT INTO `travel_review` VALUES (17866, 'TR017866', '巧家药山', '昭通', '云南', '亲子出游', '秋季', 6, 5, 1703.00, '是', 4, '6月去的巧家药山，情侣出行。地点在昭通，公交换乘方便，现场人流量适中。这次玩了5天，人均花费约1703元，历史文化气息浓。景点印象：药山位于巧家县境内。金沙江和牛栏江环山而过。药山山体面积220平方公里，主峰金顶山海拔4042米，雄踞于昭通群峰之上。\n由于受北―东向构成控制发育成型，药山走向近于北―东。西坡地势陡峭，悬崖绝壁从两江汇流的谷地中凌宵而起，柱地擎天，高不可…整体感受是整体不错，周末来刚好。二刷意愿：是。', '0%', 64);
