INSERT INTO `travel_review` VALUES (17880, 'TR017880', '西岭归樵', '铜仁', '贵州', '深度游', '春季', 2, 1, 469.00, '否', 5, '2月去的西岭归樵，一个人出行。地点在铜仁，打车比较省心，现场游客较多。这次玩了1天，人均花费约469元，氛围感不错。景点印象：铜仁城的西郊，山坡绵延，山上草木茂盛，城内百姓所需的柴禾，都在这里砍伐。每当傍晚时分，夕阳西下，樵夫们砍柴归来，一路唱着山歌，前后呼应，酣畅欢快，还有什么比这更悦耳动听的呢？整体感受是超出预期，值得专门打卡。二刷意愿：否。', '2%', 77);
