INSERT INTO `travel_review` VALUES (17957, 'TR017957', '芦仙湖', '百色', '广西', '拍照旅行', '冬季', 9, 5, 1492.00, '是', 4, '9月去的芦仙湖，情侣出行。地点在百色，自驾停车需要提前规划，现场人不算多。这次玩了5天，人均花费约1492元，拍照很出片。景点印象：总投资400万元的平果县芦仙湖风景区水上游乐项目对游人试业开放。目前，该景区共有快艇、电动船、手划船、脚踏船等游船63艘，可同时供200名游客上船游玩。\n该风景区位于平果县马头镇炼沙村那马屯，原名那马水库。据史料记载，该水库是平果县的第一…整体感受是整体不错，周末来刚好。二刷意愿：是。', '1%', 92);
