INSERT INTO `travel_review` VALUES (18018, 'TR018018', '尖山', '陇南', '甘肃', '深度游', '秋季', 6, 4, 1162.00, '否', 5, '6月去的尖山，情侣出行。地点在陇南，打车比较省心，现场人不算多。这次玩了4天，人均花费约1162元，拍照很出片。景点印象：位于甘肃省南部文县境内，东经104度40分-104度51分，北纬32度57分-33度02分之间，面积100.41平方公里。海拔820-3113米，为北亚热带湿润气候与暖温带湿润气候交汇地带。其主要保护对象为大熊猫及其栖息地。区内植物种类丰富，属国家保护的珍贵树种有…整体感受是特别满意，值得专门打卡。二刷意愿：否。', '3%', 85);
