INSERT INTO `travel_review` VALUES (18023, 'TR018023', '锦江瀑布', '白山', '吉林', '亲子出游', '夏季', 3, 2, 297.00, '是', 5, '3月去的锦江瀑布，和朋友出行。地点在白山，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约297元，氛围感不错。景点印象：锦江瀑布又叫梯河瀑布，是二级瀑布，两级落差共70米。巨大水流聚然从黑褐色的火山岩陡崖上跌落，激起白色的水雾。瀑布声如雷鸣，水花四溅，靠近瀑布，就能感到水雾缭绕，全身凉透的感觉。整体感受是超出预期，以后还会来。二刷意愿：是。', '3%', 73);
