INSERT INTO `travel_review` VALUES (18053, 'TR018053', '西华公园', '文山', '云南', '深度游', '冬季', 10, 1, 869.00, '是', 4, '10月去的西华公园，和朋友出行。地点在文山，公交换乘方便，现场人不算多。这次玩了1天，人均花费约869元，拍照很出片。景点印象：周边配套比较齐全整体感受是体验挺好，可以安排半天到一天。二刷意愿：是。', '0%', 58);
INSERT INTO `travel_review` VALUES (18054, 'TR018054', '长白山大峡谷', '白山', '吉林', '拍照旅行', '冬季', 11, 4, 1537.00, '是', 4, '11月去的长白山大峡谷，情侣出行。地点在白山，打车比较省心，现场游客较多。这次玩了4天，人均花费约1537元，氛围感不错。景点印象：位于白山市扶松县境内，是近几年发现的自然奇观，可与美国大峡谷相媲美。长白山大峡谷长70多公里，乃火山爆发后熔岩石表面的火山灰和泥土被江水及雨水冲刷而成。北锦江流经谷底，只见两岸怪石林立，奇景叠生，栩栩如生，美不胜收。整体感受是还蛮满意，推荐来看看。二刷意愿：是。', '26%', 29);
