INSERT INTO `travel_review` VALUES (18057, 'TR018057', '西平森林公园', '鞍山', '辽宁', '城市漫游', '冬季', 9, 7, 1911.00, '是', 5, '9月去的西平森林公园，和朋友出行。地点在鞍山，公交换乘方便，现场游客较多。这次玩了7天，人均花费约1911元，历史文化气息浓。景点印象：西平省级森林公园是辽河平原上不可多得的绿色资源，地处千山、医巫闾山的交通要道上。公园占地5400亩，苍松翠柏连绵不绝，碧水蓝天共成一色。园内生长百余种木本植物和多种野生动物，形成独特的野生生态环境。人工湖、狐狸洞、雁尾湖渔场、金色沙滩…整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 99);
