INSERT INTO `travel_review` VALUES (18070, 'TR018070', '大漠沙湖滑雪场', '石嘴山', '宁夏', '周末短途', '夏季', 4, 1, 297.00, '是', 5, '4月去的大漠沙湖滑雪场，和朋友出行。地点在石嘴山，打车比较省心，现场人流量适中。这次玩了1天，人均花费约297元，历史文化气息浓。景点印象：沙湖滑雪场借助的是沙湖一望无垠的万亩冰园，得天独厚的自然条件也让来者乐此不疲。沙湖的优势在于溶身于冰天雪地的大自然之中，任何的娱乐完全可以发自内心，自娱自乐。这里的冰面娱乐设施充满童趣，诸如打老牛、溜冰车都是我们童年的游戏，信手拈…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 134);
