INSERT INTO `travel_review` VALUES (18075, 'TR018075', '景忠山旅游区', '唐山', '河北', '深度游', '春季', 12, 1, 355.00, '否', 5, '12月去的景忠山旅游区，情侣出行。地点在唐山，自驾停车需要提前规划，现场游客较多。这次玩了1天，人均花费约355元，夜景表现很好。景点印象：位于唐山市迁西县境内，距北京180公里。景区面积15平方公里，大小景点80余处。景忠山气韵典雅，古朴迷离，其观古之幽，探奇之妙，赏景之媚，不愧为京东第一名岫。整体感受是超出预期，值得专门打卡。二刷意愿：否。', '1%', 95);
