INSERT INTO `travel_review` VALUES (18103, 'TR018103', '长白山漂流', '白山', '吉林', '城市漫游', '夏季', 5, 2, 952.00, '是', 5, '5月去的长白山漂流，一个人出行。地点在白山，自驾停车需要提前规划，现场人流量适中。这次玩了2天，人均花费约952元，氛围感不错。景点印象：长白山有很多漂流，比较知名的有长白山池西景区内的松花江漂流、长白山池北景区内的森林峡谷漂流和古洞漂流。长白山森林峡谷漂流距长白山30公里处。坐上皮筏，一路乘风破浪，尽情体验“中流击水，浪遏飞舟”的感觉。古洞河风光漂流从永庆乡东清大桥…整体感受是特别满意，以后还会来。二刷意愿：是。', '2%', 90);
