INSERT INTO `travel_review` VALUES (18162, 'TR018162', '古银州摩崖石刻', '榆林', '陕西', '城市漫游', '冬季', 10, 1, 545.00, '是', 5, '10月去的古银州摩崖石刻，和家人出行。地点在榆林，地铁到达方便，现场人不算多。这次玩了1天，人均花费约545元，夜景表现很好。景点印象：无定河南岸石崖之上，有“古银州”三字的摩崖石刻，宽8.3米，高3米，每字宽1.5米，高1.8米，字距为1米。\n民国二十三年(1934年)时任县长严建章主持勒石，阴刻楷书，刚健雄宏，蔚为壮观。由本县清末进士高增爵邀请段祺瑞政府总统徐世昌所书。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '1%', 64);
INSERT INTO `travel_review` VALUES (18163, 'TR018163', '哲蚌寺', '拉萨', '西藏', '深度游', '夏季', 4, 5, 1038.00, '是', 5, '4月去的哲蚌寺，情侣出行。地点在拉萨，地铁到达方便，现场人流量适中。这次玩了5天，人均花费约1038元，历史文化气息浓。景点印象：藏传佛教最大的寺院，每年的雪顿节晒佛仪式是藏区最大规模的展佛。整体感受是挺惊喜，很推荐。二刷意愿：是。', '19%', 113);
INSERT INTO `travel_review` VALUES (18164, 'TR018164', '敦煌夜市', '酒泉', '甘肃', '文化打卡', '夏季', 3, 2, 985.00, '是', 5, '3月去的敦煌夜市，和朋友出行。地点在酒泉，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约985元，夜景表现很好。景点印象：沙州夜市是敦煌旅游精品线路上的一个重要旅游景点。位于敦煌市阳关东路，是敦煌市最大的夜市。 \n这里以其鲜明的地方特色和浓郁的民俗风情，被誉为敦煌“夜景图”和“风情画”。随着沙州市场夜市服务设施不断完美，服务项目的丰富多彩，敦煌沙州夜市…整体感受是挺惊喜，很推荐。二刷意愿：是。', '6%', 49);
