INSERT INTO `travel_review` VALUES (18169, 'TR018169', '漫湾百里长湖', '临沧', '云南', '文化打卡', '秋季', 8, 1, 567.00, '否', 5, '8月去的漫湾百里长湖，情侣出行。地点在临沧，公交换乘方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约567元，拍照很出片。景点印象：澜沧江流经临沧境内二百多公里，在此段流域上建成的三座百万级千瓦大电站：漫湾、大朝山、小湾电站--亚洲最高坝电站，三大电站形成了气势磅礴，雄伟壮丽的澜沧江高峡百里长湖景观。湖面平静秀丽，胡湾半岛星罗棋布，两岸山峰秀丽，苍峻巍峨，珍稀动…整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '0%', 70);
