INSERT INTO `travel_review` VALUES (18171, 'TR018171', '叙昌酱园', '嘉兴', '浙江', '城市漫游', '夏季', 3, 1, 346.00, '是', 5, '3月去的叙昌酱园，情侣出行。地点在嘉兴，打车比较省心，现场人流量适中。这次玩了1天，人均花费约346元，拍照很出片。景点印象：来叙昌买些酱料当手信，晒场中一排排扣着斗笠的酱缸很适合拍照。整体感受是特别满意，很推荐。二刷意愿：是。', '1%', 91);
INSERT INTO `travel_review` VALUES (18172, 'TR018172', '止锚湾', '葫芦岛', '辽宁', '深度游', '冬季', 11, 1, 409.00, '否', 5, '11月去的止锚湾，一个人出行。地点在葫芦岛，公交换乘方便，现场人流量适中。这次玩了1天，人均花费约409元，拍照很出片。景点印象：游人较少，可看矗立在海中的巨大礁石。 白天可在海滩戏水，夜晚可在海滩吃海鲜、放飞孔明灯。整体感受是超出预期，以后还会来。二刷意愿：否。', '10%', 107);
INSERT INTO `travel_review` VALUES (18173, 'TR018173', '乌素特水上雅丹地质公园', '海西', '青海', '周末短途', '秋季', 8, 2, 751.00, '是', 5, '8月去的乌素特水上雅丹地质公园，和家人出行。地点在海西，地铁到达方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约751元，夜景表现很好。景点印象：景点本身有一定特色整体感受是特别满意，值得专门打卡。二刷意愿：是。', '1%', 69);
INSERT INTO `travel_review` VALUES (18174, 'TR018174', '神农架风景区', '神农架', '湖北', '周末短途', '冬季', 9, 7, 1767.00, '否', 3, '9月去的神农架风景区，和家人出行。地点在神农架，公交换乘方便，现场人流量适中。这次玩了7天，人均花费约1767元，拍照很出片。景点印象：位于茫茫的原始森林中，完全远离嚣和浑浊的城市。 处处都是古树参天，空气中散发着草木的气息，一个天然的大氧吧。 这里有神秘的野人出没，还能观赏到珍稀的金丝猴和古老的金丝燕。 攀登“华中屋脊”，在山峰中遥望华中第一高峰——神农顶。整体感受是中规中矩，按需选择。二刷意愿：否。', '31%', 79);
INSERT INTO `travel_review` VALUES (18175, 'TR018175', '平桥石坝', '常州', '江苏', '文化打卡', '冬季', 11, 2, 867.00, '否', 2, '11月去的平桥石坝，情侣出行。地点在常州，打车比较省心，现场人流量适中。这次玩了2天，人均花费约867元，历史文化气息浓。景点印象：大坝用浆砌石建成，河水沿大坝而下形成瀑布，雨后非常壮观。整体感受是略失望，建议谨慎前往。二刷意愿：否。', '0%', 32);
INSERT INTO `travel_review` VALUES (18176, 'TR018176', '鄂豫皖苏区首府烈士陵园', '信阳', '河南', '拍照旅行', '秋季', 6, 6, 1709.00, '是', 5, '6月去的鄂豫皖苏区首府烈士陵园，和朋友出行。地点在信阳，打车比较省心，现场高峰时段比较拥挤。这次玩了6天，人均花费约1709元，拍照很出片。景点印象：鄂豫皖苏区革命烈士陵园建于1957年、占地330亩由大门、烈士浮雕墙、烈士纪念碑、烈士纪念堂、革命斗争史陈列室、吴焕先半身塑像、烈士纪念亭、烈士墓地八大部分组成。\n大门 为现代建筑，园名由原国家主席李先念亲笔题写。\n烈士浮雕墙 用花岗岩雕塑…整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 100);
