INSERT INTO `travel_review` VALUES (18206, 'TR018206', '亭湖宾榭', '万宁', '海南', '亲子出游', '冬季', 11, 2, 809.00, '否', 5, '11月去的亭湖宾榭，情侣出行。地点在万宁，公交换乘方便，现场游客较多。这次玩了2天，人均花费约809元，氛围感不错。景点印象：是个游览休息、度假的理想地方，属海南农垦旅游接待点。亭湖宾榭座落在东兴农场场部铺天盖地的热带绿色植物、椰子、橡胶、胡椒、咖啡等热带的绿海中，房前屋后，林木葱翠，路旁繁花似锦，凉风吹拂，树轻摆花摇曳，加之鸟语林间，蝶蜂恋花，一派春意…整体感受是超出预期，以后还会来。二刷意愿：否。', '0%', 107);
