INSERT INTO `travel_review` VALUES (18217, 'TR018217', '七一冰川', '张掖', '甘肃', '拍照旅行', '夏季', 3, 1, 80.00, '否', 5, '3月去的七一冰川，一个人出行。地点在张掖，地铁到达方便，现场游客较多。这次玩了1天，人均花费约80元，历史文化气息浓。景点印象：“七一”冰川位于嘉峪关市西南116公里处的祁连山腹地，每到夏秋季节，冰峰在蓝天丽日下分外晶莹耀眼，与潺潺的溪流以及绿草如茵、鲜花盛开的高山牧场，共同构成一幅恬静而又充满生机的迷人画卷。整体感受是超出预期，以后还会来。二刷意愿：否。', '13%', 77);
