INSERT INTO `travel_review` VALUES (18281, 'TR018281', '青云观', '沧州', '河北', '拍照旅行', '秋季', 6, 6, 1433.00, '是', 5, '6月去的青云观，和朋友出行。地点在沧州，公交换乘方便，现场高峰时段比较拥挤。这次玩了6天，人均花费约1433元，历史文化气息浓。景点印象：青云观,位于沧州市东北的青县觉道庄,西距青县县城20公里。观内有殿堂15座,供奉80尊神像,是华北平原上历史悠久的道观。相传春秋战国时期,老子—李耳弃周守藏室史官出行,云游四方至此地隐居,传经布道,民众由此相聚而居,逐渐形成村落,起名为道德庄。至…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 52);
