INSERT INTO `travel_review` VALUES (18294, 'TR018294', '盐湖', '固原', '宁夏', '亲子出游', '秋季', 6, 2, 640.00, '是', 4, '6月去的盐湖，和朋友出行。地点在固原，打车比较省心，现场高峰时段比较拥挤。这次玩了2天，人均花费约640元，氛围感不错。景点印象：盐湖位于盐池盆地中心，海拔1980米，总土地面积950调。其四周为西华山和甘肃省靖远县黄家洼山所环抱，山中泉涧，溪流尽入湖中，天降雨雪之水汇集盐池，虽经百代而不枯竭。盐湖四周土壤中含有丰富的芒硝、氯化钠等矿物质，极易溶于水，并向洼地中心…整体感受是整体不错，推荐来看看。二刷意愿：是。', '16%', 67);
