INSERT INTO `travel_review` VALUES (18339, 'TR018339', '高山村明清民居民俗文化旅游风景区', '玉林', '广西', '深度游', '夏季', 3, 3, 985.00, '否', 4, '3月去的高山村明清民居民俗文化旅游风景区，和家人出行。地点在玉林，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了3天，人均花费约985元，拍照很出片。景点印象：高山村，人称“进士村”。村民明礼、诚信、好学，历代人才辈出。明万历年间（1574年），村里便办起了“独堆坡书房”，随后各个家族竞相开办启学蒙馆、大馆、私塾等，到清未全村共有15间。自清乾隆二十二年（1757）到清末150年间，高山村共出4名进士…整体感受是整体不错，推荐来看看。二刷意愿：否。', '12%', 84);
INSERT INTO `travel_review` VALUES (18340, 'TR018340', '天都峰', '黄山', '安徽', '深度游', '夏季', 4, 2, 561.00, '是', 5, '4月去的天都峰，和朋友出行。地点在黄山，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约561元，拍照很出片。景点印象：黄山三大主峰中最险的一座，可登顶鲫鱼背，在万丈悬崖上行走。整体感受是挺惊喜，很推荐。二刷意愿：是。', '11%', 105);
