INSERT INTO `travel_review` VALUES (18348, 'TR018348', '藤县太平狮山度假区', '梧州', '广西', '周末短途', '冬季', 10, 1, 457.00, '否', 3, '10月去的藤县太平狮山度假区，和家人出行。地点在梧州，公交换乘方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约457元，历史文化气息浓。景点印象：藤县太平狮山度假区，为自治区区级风景名胜区。太平狮山，距县城60公里。属丹霞地貌，面积为65平方公里，有不同形状的山峰数十个，最高峰为岑山寨，海拨519米，其余多为300－400米。北面的峰峦由东南向西北呈“一”字形，与桂林梧州公路平行，沿公…整体感受是中规中矩，按需选择。二刷意愿：否。', '0%', 50);
