INSERT INTO `travel_review` VALUES (18353, 'TR018353', '金兰山', '信阳', '河南', '深度游', '夏季', 3, 2, 824.00, '否', 2, '3月去的金兰山，和家人出行。地点在信阳，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了2天，人均花费约824元，历史文化气息浓。景点印象：金兰山国家森林公园，地处亚热带向暧温带过渡地带，是我国华东、华中、华北三大植物区系交汇处和我国动植物南迁北移的缓冲带，森林资源丰富，树木种类繁多。有森林面积3072公顷，森林覆盖率93.1%，植物种类2000多种，其中国家重点保护植物19种。有…整体感受是略失望，不建议高峰来。二刷意愿：否。', '0%', 53);
INSERT INTO `travel_review` VALUES (18354, 'TR018354', '拉姆央措湖', '迪庆', '云南', '城市漫游', '春季', 2, 1, 581.00, '是', 2, '2月去的拉姆央措湖，和朋友出行。地点在迪庆，地铁到达方便，现场人不算多。这次玩了1天，人均花费约581元，拍照很出片。景点印象：湖中四季有各种水鸟生息，站在扎仓大殿顶上观望拉姆央措湖，它是一个佛自然的投影。整体感受是没达到预期，不建议高峰来。二刷意愿：是。', '1%', 56);
