INSERT INTO `travel_review` VALUES (18397, 'TR018397', '峙峪遗址', '朔州', '山西', '亲子出游', '秋季', 7, 3, 692.00, '否', 5, '7月去的峙峪遗址，和朋友出行。地点在朔州，打车比较省心，现场游客较多。这次玩了3天，人均花费约692元，氛围感不错。景点印象：位于朔州城西北15公里的黑驼山脚下，是一处旧石器时代的人类遗址，中国科学院1963年发现。现为省级重点文物保护单位。这里除发现大批细小石器和大量动物化石外，还发掘出数百件有刻划痕迹的兽片和一件人类初期的武器――石旋.整体感受是特别满意，值得专门打卡。二刷意愿：否。', '2%', 67);
