INSERT INTO `travel_review` VALUES (18414, 'TR018414', '衡阳水濂洞景区', '衡阳', '湖南', '文化打卡', '夏季', 3, 1, 528.00, '否', 2, '3月去的衡阳水濂洞景区，一个人出行。地点在衡阳，自驾停车需要提前规划，现场游客较多。这次玩了1天，人均花费约528元，拍照很出片。景点印象：青山绿水中，高达50多米的瀑布飞流直下，阳光照耀在飞瀑上，时常有彩虹出现。 景区内的山崖石壁上，有唐宋以来百余处题刻，如唐代怀素的“醉”等。整体感受是略失望，不建议高峰来。二刷意愿：否。', '10%', 55);
