INSERT INTO `travel_review` VALUES (18423, 'TR018423', '平靖关', '随州', '湖北', '深度游', '冬季', 11, 1, 248.00, '否', 3, '11月去的平靖关，和家人出行。地点在随州，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约248元，历史文化气息浓。景点印象：在广水市区北30公里的桐柏山脉与大别山脉交会处。雄关险隘，群峰列峙，系著名的“义阳三关”中的西关（中关武阳，即今广水北武胜关；东关黄崛，即今大悟县九里关），扼鄂豫两省襟喉，为古今中原要道，乃兵家用武之地。历史悠久，胜迹远闻。古名“冥…整体感受是中规中矩，避开高峰更好。二刷意愿：否。', '0%', 43);
