INSERT INTO `travel_review` VALUES (18453, 'TR018453', '卧牛湖', '黑河', '黑龙江', '城市漫游', '冬季', 10, 2, 866.00, '否', 5, '10月去的卧牛湖，和朋友出行。地点在黑河，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约866元，历史文化气息浓。景点印象：卧牛湖风景区地处黑河市爱辉区上马厂乡卧牛河村，距黑河市区14公里，位于黑呼公路16公里处，面积为50平方公里，与俄布拉戈维申斯克市隔江相望，是黑河市省级名胜风景区。\n卧牛湖湖区夏季山青水秀，冬季银妆素裹，具备游览、观赏、避暑、度假、娱乐…整体感受是特别满意，以后还会来。二刷意愿：否。', '1%', 68);
