INSERT INTO `travel_review` VALUES (18476, 'TR018476', '叶赫风景名胜区', '四平', '吉林', '亲子出游', '春季', 12, 2, 405.00, '否', 5, '12月去的叶赫风景名胜区，情侣出行。地点在四平，地铁到达方便，现场游客较多。这次玩了2天，人均花费约405元，夜景表现很好。景点印象：叶赫风景名胜区位于吉辽两省结合部，吉林省梨树县东南部――叶赫满族镇内，是连接开发区内山门、二龙湖风景区旅游线的纽带。总面积 68 平方公里，集满族历史文化特色与自然山水风光于一体，风格独特，是我国北方少有的旅游胜地。\n叶赫，是满族的重…整体感受是特别满意，以后还会来。二刷意愿：否。', '0%', 74);
