INSERT INTO `travel_review` VALUES (18500, 'TR018500', '日照文山茶博园', '日照', '山东', '拍照旅行', '冬季', 9, 1, 244.00, '是', 5, '9月去的日照文山茶博园，情侣出行。地点在日照，打车比较省心，现场游客较多。这次玩了1天，人均花费约244元，夜景表现很好。景点印象：2009年，文山凤眉茶业斥资2000万元建成日照文山茶博园，公司位于东港区山东路西首。日照文山茶博园集自然景观、绿茶生态自采游、茶文化体验、民间茶艺表演于一身，使游客在亲手采茶、制茶、品茶的同时，深刻体味江北特有的茶文化和自然景观。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 91);
