INSERT INTO `travel_review` VALUES (18508, 'TR018508', '金海水晶宫', '本溪', '辽宁', '周末短途', '冬季', 11, 2, 561.00, '否', 5, '11月去的金海水晶宫，情侣出行。地点在本溪，打车比较省心，现场人不算多。这次玩了2天，人均花费约561元，历史文化气息浓。景点印象：石桥子开发区的金海水晶宫拥有国际标准竞赛泳道，不仅填补了本溪水上竞赛场馆的空白，馆内100平方米的儿童嬉水池，美国进口的水处理设备，泳池中央可升降的自动舞台等更为本溪开展冬季旅游增添了娱乐的场所。不仅可以满足全市城乡居民的冬季休闲度…整体感受是特别满意，以后还会来。二刷意愿：否。', '1%', 84);
