INSERT INTO `travel_review` VALUES (18632, 'TR018632', '鸣沙山', '昌吉', '新疆', '城市漫游', '夏季', 3, 1, 253.00, '否', 2, '3月去的鸣沙山，和朋友出行。地点在昌吉，自驾停车需要提前规划，现场人流量适中。这次玩了1天，人均花费约253元，夜景表现很好。景点印象：昌吉鸣沙山，哈萨克语称为\"阿依艾库木\"，意思是\"有声音的沙漠\"。木垒鸣沙山共有五座红色垄状沙山，其中最大的一座长度在500-600米，相对高度50-70米，呈西南一东北走向，沙山下为一片平坦的砾石间歇性河床。当汽车开近沙山时，似有雷鸣号角之声从沙…整体感受是没达到预期，建议谨慎前往。二刷意愿：否。', '9%', 53);
