INSERT INTO `travel_review` VALUES (18656, 'TR018656', '遮阳山', '定西', '甘肃', '拍照旅行', '春季', 12, 2, 645.00, '是', 4, '12月去的遮阳山，和朋友出行。地点在定西，地铁到达方便，现场游客较多。这次玩了2天，人均花费约645元，氛围感不错。景点印象：遮阳山古有岷州“小崆峒”之称，由西溪、东溪和夷门山三个景区组成。西溪由金家沟和若干岔峡组成，全长7.5公里，为全山的旅游精华所在。境内主要有临溪巨石、芸叟洞、三醉石、题诗崖、仙人祠、青羊洞、八音井、常家洞、锡庆寺、蛤蟆石等历史胜迹和…整体感受是还蛮满意，周末来刚好。二刷意愿：是。', '0%', 60);
