INSERT INTO `travel_review` VALUES (18717, 'TR018717', '天山天池', '北疆', '新疆', '城市漫游', '冬季', 9, 1, 217.00, '否', 5, '9月去的天山天池，和朋友出行。地点在北疆，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约217元，历史文化气息浓。景点印象：群山环抱中的高山湖泊，被皑皑雪山和挺拔的云松林所环抱。整体感受是特别满意，值得专门打卡。二刷意愿：否。', '37%', 136);
INSERT INTO `travel_review` VALUES (18718, 'TR018718', '杜鹃山', '雅安', '四川', '亲子出游', '春季', 1, 3, 519.00, '是', 5, '1月去的杜鹃山，和家人出行。地点在雅安，自驾停车需要提前规划，现场游客较多。这次玩了3天，人均花费约519元，拍照很出片。景点印象：荥经县杜鹃山原始森林公园（泡草湾）距县城30公里，拥有原始森林9628公顷，这里冬无严寒，夏无酷暑，年平均温度13℃，是我省保护最好、典型物种最丰富的亚热带常绿阔叶林带。“珙桐花开鸽飞舞，春来杜鹃映山红，熊猫戏竹金鸡鸣，休闲度假好去处”。…整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 76);
