INSERT INTO `travel_review` VALUES (18720, 'TR018720', '柘王宫遗址', '亳州', '安徽', '周末短途', '夏季', 4, 3, 1251.00, '是', 5, '4月去的柘王宫遗址，和朋友出行。地点在亳州，自驾停车需要提前规划，现场游客较多。这次玩了3天，人均花费约1251元，氛围感不错。景点印象：传为古时候侯爵的封地，建有三宫六院、72眼井。考古证实为北宋时期遗址，现为涡阳县重点文物保护单位。整体感受是超出预期，值得专门打卡。二刷意愿：是。', '0%', 96);
