INSERT INTO `travel_review` VALUES (18730, 'TR018730', '甘肃尕海则岔自然保护区-尕海湖', '甘南', '甘肃', '周末短途', '夏季', 4, 2, 719.00, '是', 4, '4月去的甘肃尕海则岔自然保护区-尕海湖，和家人出行。地点在甘南，公交换乘方便，现场游客较多。这次玩了2天，人均花费约719元，氛围感不错。景点印象：观看草原中心的海子，晴天时蓝天白云倒影湖中十分美丽。 七八月份湖边野花遍地，是摄影的绝妙之地！整体感受是体验挺好，推荐来看看。二刷意愿：是。', '35%', 57);
