INSERT INTO `travel_review` VALUES (18747, 'TR018747', '聚奎塔', '琼海', '海南', '周末短途', '冬季', 11, 2, 318.00, '是', 4, '11月去的聚奎塔，和家人出行。地点在琼海，公交换乘方便，现场人流量适中。这次玩了2天，人均花费约318元，历史文化气息浓。景点印象：聚奎塔高近30米，一共七层，每升高一层，高与宽都相应缩减。塔身中空，底有塔座，四周有墙，正门朝北，楣上端有石匾，上书“聚奎塔”。塔体仿唐代建筑，造型古朴别致。外表每层由八个墙面构成，属楼阁式砖檐塔，七面各筑一个假门，只有一面筑真门。…整体感受是还蛮满意，推荐来看看。二刷意愿：是。', '3%', 30);
