INSERT INTO `travel_review` VALUES (18756, 'TR018756', '兰家火山', '攀枝花', '四川', '文化打卡', '秋季', 7, 6, 1343.00, '否', 5, '7月去的兰家火山，和家人出行。地点在攀枝花，自驾停车需要提前规划，现场人不算多。这次玩了6天，人均花费约1343元，历史文化气息浓。景点印象：在攀枝花兰家火山、尖山，有一座国内最大的现代化的天然钒钛磁铁矿采矿场。它场面宏大，气势磅礴，每日成于上万吨矿石从这里运走，因此名闻遐迩。成了人们争相一睹的胜景。要俯瞰宏伟的采矿壮景及攀枝花矿山全貌，最佳视点便是登上海拔1620米的兰家…整体感受是超出预期，以后还会来。二刷意愿：否。', '0%', 80);
