INSERT INTO `travel_review` VALUES (18822, 'TR018822', '观山寺群', '茂名', '广东', '拍照旅行', '夏季', 5, 5, 1169.00, '否', 3, '5月去的观山寺群，和家人出行。地点在茂名，公交换乘方便，现场高峰时段比较拥挤。这次玩了5天，人均花费约1169元，拍照很出片。景点印象：观山寺群位于高州市之西的观山上，观山东临鉴江，南对南宫岭，山青水秀，风景迷人。明代以来，这里先后建起了观山寺、玉泉寺、吕仙殿、潘仙殿、报德祠等寺庙建筑群。民国期间，又开辟了中山公园，建有中山亭、若？？亭、茂植亭、咏风亭、襟江亭、旷…整体感受是还可以，按需选择。二刷意愿：否。', '0%', 47);
