INSERT INTO `travel_review` VALUES (18878, 'TR018878', '毛集社会发展综合实验区', '淮南', '安徽', '周末短途', '夏季', 3, 1, 616.00, '否', 4, '3月去的毛集社会发展综合实验区，一个人出行。地点在淮南，地铁到达方便，现场人不算多。这次玩了1天，人均花费约616元，历史文化气息浓。景点印象：毛集社会发展综合实验区地处淮北平原，属沿淮行蓄洪区，位于淮河与西淝河交汇处，东倚百里煤城淮南，西接京九明珠阜阳，南临历史文化名城寿县，北靠国投新集能源总公司。102省道穿境而过，境内淮河四季通航，距阜阳机场78公里，离铁路车站4公里，地…整体感受是还蛮满意，推荐来看看。二刷意愿：否。', '0%', 97);
