INSERT INTO `travel_review` VALUES (18889, 'TR018889', '文庙', '运城', '山西', '周末短途', '夏季', 4, 7, 1858.00, '否', 5, '4月去的文庙，情侣出行。地点在运城，自驾停车需要提前规划，现场游客较多。这次玩了7天，人均花费约1858元，拍照很出片。景点印象：位于县城东北隅，创建年代失考，2002年修复后向游人开放，中轴线上依次是：下马碑→大门→照壁→泮池→棂星门→大成门→东西廊房→御路石→大成殿。 大成殿现存为明代遗构，重檐歇山屋顶，四周有回廊，面宽七间，殿宇巍峨，气势宏伟，素有“三晋文…整体感受是超出预期，以后还会来。二刷意愿：否。', '2%', 42);
