INSERT INTO `travel_review` VALUES (18941, 'TR018941', '河南跑马岭地质公园', '新乡', '河南', '拍照旅行', '春季', 1, 3, 1236.00, '否', 2, '1月去的河南跑马岭地质公园，和朋友出行。地点在新乡，公交换乘方便，现场游客较多。这次玩了3天，人均花费约1236元，夜景表现很好。景点印象：登上山头是一片风吹草低见牛羊的广袤草原，马儿奔驰，风景优美而惬意。整体感受是略失望，建议谨慎前往。二刷意愿：否。', '1%', 79);
INSERT INTO `travel_review` VALUES (18942, 'TR018942', '青云寺', '榆林', '陕西', '深度游', '秋季', 6, 5, 1600.00, '否', 4, '6月去的青云寺，情侣出行。地点在榆林，打车比较省心，现场人流量适中。这次玩了5天，人均花费约1600元，历史文化气息浓。景点印象：青云寺是合道、佛教于一体的寺观 。寺依山傍水，绿树环绕，楼台殿阁，此起彼伏，朱柱彩棚，泥塑砖雕，堪称“ 榆溪胜境”。\n寺始建于明代，三迁而至今址。民国17年(公元1919年)重修扩建，总占地面 积40余亩，是陕北最大的仿古建筑群。寺内大小殿院十…整体感受是体验挺好，可以安排半天到一天。二刷意愿：否。', '3%', 48);
