INSERT INTO `travel_review` VALUES (18963, 'TR018963', '中苏街', '呼伦贝尔', '内蒙古', '周末短途', '夏季', 4, 2, 1136.00, '否', 5, '4月去的中苏街，情侣出行。地点在呼伦贝尔，公交换乘方便，现场人流量适中。这次玩了2天，人均花费约1136元，夜景表现很好。景点印象：中苏街在解放前称博士街，是满洲里早期隆太号、恒盛福、福海长、吉顺富、义聚德、尼基金旅馆等众多商家聚集地。解放后为纪念中国与前苏联的友好合作改称中苏街。整体感受是特别满意，很推荐。二刷意愿：否。', '2%', 106);
