INSERT INTO `travel_review` VALUES (18967, 'TR018967', '魏文帝庙', '许昌', '河南', '城市漫游', '春季', 2, 3, 941.00, '否', 4, '2月去的魏文帝庙，和家人出行。地点在许昌，自驾停车需要提前规划，现场游客较多。这次玩了3天，人均花费约941元，拍照很出片。景点印象：位于许昌城东南14公里的将官池乡郭集村西南，几座青灰殿堂掩映在苍松翠柏之中，自然和谐，幽美恬静。因庙建在遥观如山的高阜上，内中又有一幢高高的阁楼，所以人们都称它为“高庙”。该庙原为曹操所建曹氏家庙。魏明帝曹睿太和六年四月临许昌，到庙…整体感受是还蛮满意，推荐来看看。二刷意愿：否。', '0%', 51);
