INSERT INTO `travel_review` VALUES (18974, 'TR018974', '大丰斗龙庄园', '盐城', '江苏', '城市漫游', '夏季', 5, 1, 350.00, '否', 4, '5月去的大丰斗龙庄园，一个人出行。地点在盐城，打车比较省心，现场人不算多。这次玩了1天，人均花费约350元，历史文化气息浓。景点印象：大丰斗龙庄园地处大丰斗龙港南侧，占地总面积为10600亩。其中水面养殖10000亩。庄园以生态学为原理，充分利用大丰地区的自然优势，结合当地古文化、民俗农情，形成一个集生态保护、农业发展、旅游度假为一体的多文化发展的庄园体系。目前，建有花卉…整体感受是整体不错，可以安排半天到一天。二刷意愿：否。', '0%', 74);
