INSERT INTO `travel_review` VALUES (18979, 'TR018979', '勅赐禅定寺', '甘南', '甘肃', '拍照旅行', '秋季', 6, 3, 612.00, '否', 5, '6月去的勅赐禅定寺，一个人出行。地点在甘南，打车比较省心，现场人流量适中。这次玩了3天，人均花费约612元，夜景表现很好。景点印象：该寺是安多地区最古老的佛教寺院，在宗教历史上有很深远的影响。整体感受是挺惊喜，以后还会来。二刷意愿：否。', '0%', 72);
