INSERT INTO `travel_review` VALUES (19013, 'TR019013', '夹祭草堂', '莆田', '福建', '深度游', '冬季', 9, 2, 786.00, '否', 5, '9月去的夹祭草堂，和家人出行。地点在莆田，打车比较省心，现场游客较多。这次玩了2天，人均花费约786元，夜景表现很好。景点印象：在莆田县新县乡巩溪村的夹祭山上，离市区北面约30公里。草堂原为名副其实的草屋。宋乾道五年（1169年），兴化军知军钟离松把草屋改建为瓦房，题额“夹祭草堂”，供后人瞻仰。郑樵，字渔仲。是我国著名的历史学家。他宋崇宁三年（1104年）生于广业里…整体感受是特别满意，以后还会来。二刷意愿：否。', '0%', 105);
