INSERT INTO `travel_review` VALUES (19033, 'TR019033', '二郎山庄', '四平', '吉林', '周末短途', '冬季', 9, 3, 799.00, '否', 5, '9月去的二郎山庄，情侣出行。地点在四平，打车比较省心，现场高峰时段比较拥挤。这次玩了3天，人均花费约799元，历史文化气息浓。景点印象：二郎山庄位于吉林省四平市山门镇境内，建在海拔二百九十三米号称长白第一山上，占地面积15万平方米。风景区内自然景观绚丽多彩、景色宜人，内容丰富，是集自然风光，宗教信仰，历史故事，古老传说为一体。每逢农历四月初用八、十八、二十八庙会之日…整体感受是特别满意，以后还会来。二刷意愿：否。', '0%', 69);
