INSERT INTO `travel_review` VALUES (19071, 'TR019071', '买力克阿瓦提古城', '和田', '新疆', '拍照旅行', '秋季', 8, 1, 80.00, '否', 5, '8月去的买力克阿瓦提古城，情侣出行。地点在和田，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约80元，历史文化气息浓。景点印象：位于和田城东南25公里的玉龙喀什河西岸，当地人称“什斯比尔”。1962年定为自治区重点文物保护单位。遗址南北长十公里，东西宽两公里。该城建于1500至1600年以前。\n遗址西侧沙山环立，冈峦起伏，南面昆仑山脉影影绰绰，高入云端，东面玉龙喀什河蜿…整体感受是超出预期，以后还会来。二刷意愿：否。', '0%', 56);
