INSERT INTO `travel_review` VALUES (19078, 'TR019078', '沙屯叠瀑布', '崇左', '广西', '亲子出游', '秋季', 8, 2, 934.00, '是', 5, '8月去的沙屯叠瀑布，和朋友出行。地点在崇左，地铁到达方便，现场游客较多。这次玩了2天，人均花费约934元，拍照很出片。景点印象：沙屯叠瀑，位于大新县硕龙镇，距县城46公里，距崇左市区92公里，传说是七仙女下凡沐浴的地方，瀑布分成七级层层泻下，如垂帘挂珠，河水凝脂，结玉，，水声如歌，如诉，时有渔人乘竹筏于瀑布间出没，秀美景致，更增古朴神韵。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '1%', 44);
