INSERT INTO `travel_review` VALUES (19117, 'TR019117', '圣寿寺舍利塔', '运城', '山西', '拍照旅行', '夏季', 4, 3, 952.00, '否', 5, '4月去的圣寿寺舍利塔，和家人出行。地点在运城，打车比较省心，现场人不算多。这次玩了3天，人均花费约952元，拍照很出片。景点印象：在芮城县城北里许。创建于北宋天圣年间，明、清时曾予重修。现仅存宋建砖塔。增平面八角形，十三层，高约48米。塔身锥形，逐级向内收缩，檐下砖雕斗拱，完全仿木结构形制，古朴苍劲。塔中空。直达顶层，各层原有楼板，可缘梯攀登、现已不存。塔内保…整体感受是特别满意，以后还会来。二刷意愿：否。', '0%', 52);
