INSERT INTO `travel_review` VALUES (19158, 'TR019158', '归德府文庙', '商丘', '河南', '拍照旅行', '春季', 1, 1, 451.00, '是', 5, '1月去的归德府文庙，情侣出行。地点在商丘，自驾停车需要提前规划，现场人不算多。这次玩了1天，人均花费约451元，氛围感不错。景点印象：归德府文庙位于商丘市睢阳区，坐落在商丘古城内，是河南省现存规模最大的文庙建筑，始建于明嘉靖三十四年至三十八年（公元1555年至1559年），距今已有近500年的历史。整体感受是超出预期，很推荐。二刷意愿：是。', '25%', 93);
