INSERT INTO `travel_review` VALUES (19172, 'TR019172', '文庙', '运城', '山西', '亲子出游', '冬季', 9, 3, 916.00, '是', 5, '9月去的文庙，一个人出行。地点在运城，自驾停车需要提前规划，现场人不算多。这次玩了3天，人均花费约916元，拍照很出片。景点印象：位于县城东北隅，创建年代失考，2002年修复后向游人开放，中轴线上依次是：下马碑→大门→照壁→泮池→棂星门→大成门→东西廊房→御路石→大成殿。 大成殿现存为明代遗构，重檐歇山屋顶，四周有回廊，面宽七间，殿宇巍峨，气势宏伟，素有“三晋文…整体感受是特别满意，以后还会来。二刷意愿：是。', '2%', 89);
