INSERT INTO `travel_review` VALUES (19175, 'TR019175', '上党战役指挥部旧址', '长治', '山西', '拍照旅行', '秋季', 8, 3, 847.00, '是', 5, '8月去的上党战役指挥部旧址，和家人出行。地点在长治，自驾停车需要提前规划，现场人不算多。这次玩了3天，人均花费约847元，夜景表现很好。景点印象：位于离襄垣县城西23公里处的大平村，是上党战役指挥部的一个旧址。1945年l0月，刘伯承司令员和邓小平政委率晋冀鲁豫军区指挥部由崔蒙移驻这里，住在小东院孙树章家。在这里指挥了决定上党战役胜负的老爷山、磨盘垴打援战和土落截击战，取得了上党战…整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 97);
