INSERT INTO `travel_review` VALUES (19193, 'TR019193', '女娲城址', '周口', '河南', '深度游', '秋季', 6, 2, 1270.00, '否', 2, '6月去的女娲城址，和朋友出行。地点在周口，公交换乘方便，现场游客较多。这次玩了2天，人均花费约1270元，夜景表现很好。景点印象：女娲，是我国古代神话传说中的人类始祖，她抟泥为人、化育万物、炼石补天并发明了笙簧乐器，对此《世本作篇》留有记载。《说文》曰：“娲，古之神圣女，化万物者也”。中国考古学者认为，古代传说中的女娲氏是部落首领，属仰韶文化，当在六七年之前…整体感受是没达到预期，建议谨慎前往。二刷意愿：否。', '33%', 57);
