INSERT INTO `travel_review` VALUES (19199, 'TR019199', '萝卜岩楠木自然保护区', '三明', '福建', '亲子出游', '春季', 12, 4, 1376.00, '否', 5, '12月去的萝卜岩楠木自然保护区，和家人出行。地点在三明，地铁到达方便，现场高峰时段比较拥挤。这次玩了4天，人均花费约1376元，夜景表现很好。景点印象：萝卜岩楠木自然保护区，位于沙县和明溪交界处。两坡夹一沟，佑溪从中潺潺流过，形成萝卜岩、马头山、红血坑、紫竹洲四个部分。这是一个典型的以樟科和彀斗科为主的中亚热带常绿阔叶林带，有高等植物55个科、101个属、194种，尤其是区内有327公顷的…整体感受是挺惊喜，以后还会来。二刷意愿：否。', '0%', 58);
