INSERT INTO `travel_review` VALUES (19210, 'TR019210', '三和牡丹景区', '临汾', '山西', '亲子出游', '春季', 12, 2, 642.00, '否', 5, '12月去的三和牡丹景区，情侣出行。地点在临汾，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了2天，人均花费约642元，历史文化气息浓。景点印象：位于山西晋南的古县历史悠久，文化底蕴深厚。据史记载，早在六千多年前仰韶文化时期当地已有人群居住繁衍，上古时期曾是大禹治水之地。在烟波浩渺的历史长河中，古县涌现出蔺相如等著名政治家，近代的古县还留有朱德、刘少奇、邓小平、薄一波、陈赓…整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '0%', 50);
