INSERT INTO `travel_review` VALUES (19212, 'TR019212', '黄河古渡', '运城', '山西', '拍照旅行', '冬季', 9, 3, 587.00, '是', 5, '9月去的黄河古渡，一个人出行。地点在运城，打车比较省心，现场高峰时段比较拥挤。这次玩了3天，人均花费约587元，夜景表现很好。景点印象：奔腾咆哮的黄河，一出龙门，被秦岭山脉阻拦，于是掉头向东，浩浩荡荡，蜿蜒于宽达10多公里的河道上，穿中原，过齐鲁，驰骋千里，汇入渤海。沿途山川险要，良田万顷，车马如潮，景色宜人。在黄河北岸的山西省境内，从上流到下流，相继有风陵渡、大禹…整体感受是超出预期，值得专门打卡。二刷意愿：是。', '2%', 92);
INSERT INTO `travel_review` VALUES (19213, 'TR019213', '山西黄河第一湾', '吕梁', '山西', '深度游', '夏季', 3, 1, 80.00, '是', 5, '3月去的山西黄河第一湾，和家人出行。地点在吕梁，地铁到达方便，现场人不算多。这次玩了1天，人均花费约80元，历史文化气息浓。景点印象：“天下黄河第一湾”位于山西省石楼县辛关镇，最佳观景点为马家畔。晋西高原，峰峦如涛，绵延不绝。黄河巨浪，呼啸而过，逝者如斯，亘古不息。黄河自唐古拉山始，流经四川、甘肃、宁夏，一路向东，经晋蒙交界的老牛湾垂直向南，在晋陕大峡谷中下部，…整体感受是挺惊喜，很推荐。二刷意愿：是。', '9%', 70);
