INSERT INTO `travel_review` VALUES (19220, 'TR019220', '雅丹大峡谷', '巴音郭楞', '新疆', '周末短途', '冬季', 9, 6, 1728.00, '是', 5, '9月去的雅丹大峡谷，情侣出行。地点在巴音郭楞，打车比较省心，现场人不算多。这次玩了6天，人均花费约1728元，历史文化气息浓。景点印象：罗布泊雅丹地下大峡谷位于库尔勒市至尉犁县之间的东北方向，距尉犁县20多公里，是一个有着悠久的丝路文化、奇特地质公园的大峡谷。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '2%', 104);
