INSERT INTO `travel_review` VALUES (19265, 'TR019265', '金牛洞古采矿遗址', '铜陵', '安徽', '拍照旅行', '秋季', 6, 3, 716.00, '否', 5, '6月去的金牛洞古采矿遗址，和朋友出行。地点在铜陵，打车比较省心，现场人不算多。这次玩了3天，人均花费约716元，夜景表现很好。景点印象：金牛洞古采矿遗址，距市区30作公里。早先此处为一小山，山腰有一古洞。民间传说天上神牛私下凡间，因迷恋凤凰山风景而不思返。天帝屡屡唤之，神牛钻入此山中，化为金银铜。金牛洞由是得名。\n自八十年代以来，当地群众在此露采铁矿，久而久之，山被…整体感受是特别满意，很推荐。二刷意愿：否。', '0%', 47);
