INSERT INTO `travel_review` VALUES (19287, 'TR019287', '千里葡萄长廊', '和田', '新疆', '城市漫游', '冬季', 9, 4, 963.00, '是', 5, '9月去的千里葡萄长廊，情侣出行。地点在和田，打车比较省心，现场游客较多。这次玩了4天，人均花费约963元，氛围感不错。景点印象：和田县巴格其镇的农民为节省耕地，利用农田道路，将葡萄种在道路边上，枝蔓架在道路上方，多占天少占地，取得了明显的社会效益和经济效益。80年代初，和田县将这一创举大力推行，并进行了统一规划，以后逐年扩大，到目前为止，全县葡萄长廊达1500多…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '4%', 93);
