INSERT INTO `travel_review` VALUES (19289, 'TR019289', '太平湖', '黄山', '安徽', '文化打卡', '冬季', 10, 2, 608.00, '否', 3, '10月去的太平湖，一个人出行。地点在黄山，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了2天，人均花费约608元，夜景表现很好。景点印象：沿湖畔散步，欣赏清澈的湖水；坐游船登陆猴岛，邂逅黄山短尾猴。整体感受是还可以，别抱太高期待。二刷意愿：否。', '0%', 25);
INSERT INTO `travel_review` VALUES (19290, 'TR019290', '水泊梁山', '济宁', '山东', '周末短途', '冬季', 11, 1, 347.00, '否', 5, '11月去的水泊梁山，一个人出行。地点在济宁，打车比较省心，现场人流量适中。这次玩了1天，人均花费约347元，氛围感不错。景点印象：在《水浒传》故事的发祥地游览梁山山寨，感受水浒文化。 欣赏水浒情景剧与民间艺术表演，去古刹莲台寺礼佛祈福。整体感受是超出预期，值得专门打卡。二刷意愿：否。', '2%', 83);
