INSERT INTO `travel_review` VALUES (19295, 'TR019295', '郭氏生态湖度假村', '大庆', '黑龙江', '周末短途', '夏季', 3, 1, 497.00, '否', 5, '3月去的郭氏生态湖度假村，和朋友出行。地点在大庆，打车比较省心，现场人流量适中。这次玩了1天，人均花费约497元，拍照很出片。景点印象：郭氏生态湖位于乌裕尔河下游、301国道郭氏活鱼总店南1公里。距大庆市110公里，齐市40公里，水面2万余亩，盛产鲤鱼、鲫鱼、草鱼、胖头、黑鱼、嘎牙子、鲇鱼、柳根、虾、老头鱼、河蟹等几十种野生鱼类。栖息着丹顶鹤、大雁、白鹤、野鸭、河鸥、鸳鸯等…整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '0%', 89);
