INSERT INTO `travel_review` VALUES (19330, 'TR019330', '石空寺石窟', '中卫', '宁夏', '拍照旅行', '春季', 1, 1, 342.00, '否', 5, '1月去的石空寺石窟，和朋友出行。地点在中卫，地铁到达方便，现场游客较多。这次玩了1天，人均花费约342元，历史文化气息浓。景点印象：位于中宁县城北15公里处，原有大佛洞、卧佛洞、观音洞、龙王洞、灵光洞等石窟，石窟前建有寺院，寺院中还有各类神佛塑像。但是由于这里是腾格里沙漠的南缘，风沙大，加上在晚清时期社会动乱，寺院荒废，石窟逐渐被流沙埋没。到了20世纪40年代末，仅…整体感受是超出预期，以后还会来。二刷意愿：否。', '1%', 80);
