INSERT INTO `travel_review` VALUES (19340, 'TR019340', '贾登峪国家森林公园', '北疆', '新疆', '亲子出游', '春季', 1, 1, 1025.00, '是', 5, '1月去的贾登峪国家森林公园，和家人出行。地点在北疆，公交换乘方便，现场人流量适中。这次玩了1天，人均花费约1025元，拍照很出片。景点印象：观赏由围起的毡房群、山丘森林和欧式城堡等一起构成的美丽童话世界。 居住在内部色彩艳丽的毡房里，体验牧民们的淳朴生活。 交通便利，是徒步或坐车进入喀纳斯湖景区、禾木风景区的中转站。整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 43);
