INSERT INTO `travel_review` VALUES (19345, 'TR019345', '迎恩宫', '济源', '河南', '文化打卡', '冬季', 10, 2, 853.00, '是', 5, '10月去的迎恩宫，情侣出行。地点在济源，自驾停车需要提前规划，现场人流量适中。这次玩了2天，人均花费约853元，氛围感不错。景点印象：位于市城区西北29公里的三官坪村北的迎恩宫，北依黛珠峰，西临小有河。相传，唐初紫微宫道士为迎接皇帝或圣旨而建，故名。\n宫座北向阳，为三进院落，依山趁势，就岩砌台，逐级升高，错落有致。现存古建筑有山门、祖师大殿、四圣殿、吕祖殿、三官殿…整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 104);
