INSERT INTO `travel_review` VALUES (19363, 'TR019363', '祝圣寺', '衡阳', '湖南', '亲子出游', '冬季', 10, 1, 403.00, '是', 4, '10月去的祝圣寺，和朋友出行。地点在衡阳，地铁到达方便，现场游客较多。这次玩了1天，人均花费约403元，历史文化气息浓。景点印象：曾经是为康熙皇帝南巡而改建的行宫，寺内还保留着很多世俗题材的浮雕。 寺中罗汉堂的罗汉像，各个栩栩如生，姿态各异，是“南岳”中的至宝。整体感受是还蛮满意，推荐来看看。二刷意愿：是。', '5%', 66);
