INSERT INTO `travel_review` VALUES (19388, 'TR019388', '龙园', '天水', '甘肃', '拍照旅行', '冬季', 11, 1, 611.00, '否', 4, '11月去的龙园，情侣出行。地点在天水，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约611元，氛围感不错。景点印象：位于渭水之滨，文山之阴，坐西面东，占地一十三亩。主体成纪殿，乃歇山重檐九开间明清式建筑。长四十五米、高二十七米，进深一十三米六。整体感受是整体不错，推荐来看看。二刷意愿：否。', '0%', 100);
INSERT INTO `travel_review` VALUES (19389, 'TR019389', '金华山', '遂宁', '四川', '深度游', '夏季', 3, 4, 880.00, '否', 5, '3月去的金华山，情侣出行。地点在遂宁，自驾停车需要提前规划，现场人流量适中。这次玩了4天，人均花费约880元，氛围感不错。景点印象：位于金华城北，为国家级重点风景名胜区。海拔150-1200米，绵延250平方公里，像一条长龙横卧于古婺大地。全年气候湿润、云雾缥缈，环境清凉宜人，并以林海莽原、奇异洞景和黄大仙真源为特色，被游客公认为休闲度假的仙游胜地。\n金华山洞奇、石怪、山…整体感受是超出预期，值得专门打卡。二刷意愿：否。', '50%', 65);
