INSERT INTO `travel_review` VALUES (19397, 'TR019397', '儋州千年古盐田', '儋州', '海南', '城市漫游', '冬季', 9, 3, 1014.00, '否', 5, '9月去的儋州千年古盐田，和家人出行。地点在儋州，地铁到达方便，现场人不算多。这次玩了3天，人均花费约1014元，拍照很出片。景点印象：欣赏千年古盐田的壮观，领略古代劳动人民的智慧与伟大。整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '56%', 67);
INSERT INTO `travel_review` VALUES (19398, 'TR019398', '青云观', '沧州', '河北', '文化打卡', '冬季', 9, 5, 1435.00, '是', 5, '9月去的青云观，一个人出行。地点在沧州，地铁到达方便，现场高峰时段比较拥挤。这次玩了5天，人均花费约1435元，历史文化气息浓。景点印象：青云观,位于沧州市东北的青县觉道庄,西距青县县城20公里。观内有殿堂15座,供奉80尊神像,是华北平原上历史悠久的道观。相传春秋战国时期,老子—李耳弃周守藏室史官出行,云游四方至此地隐居,传经布道,民众由此相聚而居,逐渐形成村落,起名为道德庄。至…整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 75);
