INSERT INTO `travel_review` VALUES (19440, 'TR019440', '九九归一', '琼海', '海南', '文化打卡', '春季', 12, 4, 1159.00, '否', 5, '12月去的九九归一，一个人出行。地点在琼海，打车比较省心，现场游客较多。这次玩了4天，人均花费约1159元，夜景表现很好。景点印象：这个整体看上去状若莲花的景点名为：九九归一，古时数字中“九”是最大的数，古人说：“九九之数以合天道”。所谓“归一”即是教导警醒人们天、地、人本为一体。这九瓣比人高的莲花瓣儿以及花瓣儿上的观音像，象征着佛教所说的“九品莲台”。西方极…整体感受是超出预期，以后还会来。二刷意愿：否。', '0%', 61);
