INSERT INTO `travel_review` VALUES (19472, 'TR019472', '街津口赫哲族民族村', '佳木斯', '黑龙江', '城市漫游', '秋季', 7, 1, 310.00, '否', 5, '7月去的街津口赫哲族民族村，和家人出行。地点在佳木斯，公交换乘方便，现场游客较多。这次玩了1天，人均花费约310元，历史文化气息浓。景点印象：赫哲族是我国人口最少的民族，街津口是赫哲族集居地，总面积160平方公里，其中村寨建筑面积3500平方米。村寨布局基本为正方形，建筑多为汉族式瓦房。赫哲族素以三江为家，渔猎为主，形成了独特的生活方式和风俗习惯。民间文学为依玛坎、说胡力．民…整体感受是特别满意，值得专门打卡。二刷意愿：否。', '14%', 97);
