INSERT INTO `travel_review` VALUES (19478, 'TR019478', '小黑江森林公园', '普洱', '云南', '亲子出游', '秋季', 6, 4, 1173.00, '是', 5, '6月去的小黑江森林公园，一个人出行。地点在普洱，打车比较省心，现场人不算多。这次玩了4天，人均花费约1173元，拍照很出片。景点印象：小黑江森林公园位于普洱县与景谷县交界处，经营面积6245公顷，属思茅地区卫国林业局经营区。多年来，由于卫国林业局重视森林资源的保护，小黑江林区保持了山长青、水长流的秀美景色，吸引了越来越多的游客。为了把小黑江林区建设成为思茅地区的旅游…整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 78);
