INSERT INTO `travel_review` VALUES (19548, 'TR019548', '梧桐树王', '和田', '新疆', '拍照旅行', '春季', 2, 2, 1052.00, '否', 4, '2月去的梧桐树王，和家人出行。地点在和田，自驾停车需要提前规划，现场游客较多。这次玩了2天，人均花费约1052元，氛围感不错。景点印象：在墨玉县阿克萨拉依乡古勒巴格村境内，有一株极其古老的其那树，其那维吾尔语译为梧桐，即梧桐树。这株古梧桐树高约30米，主干胸径2.7米，主干胸围8.75米，树冠遮盖地面1.5亩。树龄经中科院植物研究所有关专家测定为1000年左右。\n阿克萨拉依乡古勒…整体感受是体验挺好，可以安排半天到一天。二刷意愿：否。', '4%', 71);
