INSERT INTO `travel_review` VALUES (19567, 'TR019567', '三色湖', '昌都', '西藏', '周末短途', '夏季', 4, 1, 169.00, '是', 3, '4月去的三色湖，和朋友出行。地点在昌都，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约169元，历史文化气息浓。景点印象：三色湖距县城近50公里。从县城驱车，途经连片的沙棘林，穿过藏东风格独具的村庄，就可以到达海拔4200米左右的三色湖群。\n白湖藏语称“错嘎”，湖色灰白，绿树倒映湖面，鱼儿跳跃湖上。黑湖藏语称“错那”，三湖中面积最大，远看似墨，群山环抱，深…整体感受是还可以，别抱太高期待。二刷意愿：是。', '0%', 85);
