INSERT INTO `travel_review` VALUES (19616, 'TR019616', '魔界风景区', '延边', '吉林', '周末短途', '冬季', 9, 5, 1221.00, '否', 4, '9月去的魔界风景区，和家人出行。地点在延边，地铁到达方便，现场高峰时段比较拥挤。这次玩了5天，人均花费约1221元，氛围感不错。景点印象：欣赏雾气流动于水面与林间的梦幻般画面，摄影爱好者不容错过。整体感受是还蛮满意，可以安排半天到一天。二刷意愿：否。', '14%', 71);
INSERT INTO `travel_review` VALUES (19617, 'TR019617', '龙潭野考站', '神农架', '湖北', '深度游', '冬季', 11, 5, 1375.00, '否', 5, '11月去的龙潭野考站，和朋友出行。地点在神农架，自驾停车需要提前规划，现场人流量适中。这次玩了5天，人均花费约1375元，夜景表现很好。景点印象：位于神农架国家级自然保护区内，是神农架野人考察的大本营，同时，也是金丝猴生活习性的重要观察点和野生动物救护站，内设野考工作展览室，如实反映国家对神农架野人两次考察的主要成果，有野人分布图，目击者照片，现场获取的野人毛发、粪便、竹窝…整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '1%', 71);
