INSERT INTO `travel_review` VALUES (19627, 'TR019627', '大韩寨清真寺', '廊坊', '河北', '深度游', '春季', 12, 3, 1259.00, '是', 4, '12月去的大韩寨清真寺，和家人出行。地点在廊坊，打车比较省心，现场游客较多。这次玩了3天，人均花费约1259元，氛围感不错。景点印象：始建年限无考。清光绪二十三年，由伊玛目白玉秀、乡老金殿朝等人出面筹资，从天津请来高级工匠，熔天津药五庙北寺和北京市面上牛街清真寺特点于一体修建而成。经历代，尤其是党的三中全会以来，多次外长葺，现大殿建筑面积540平方米。北讲堂和沐浴…整体感受是还蛮满意，推荐来看看。二刷意愿：是。', '0%', 13);
