INSERT INTO `travel_review` VALUES (19632, 'TR019632', '柘王宫遗址', '亳州', '安徽', '深度游', '冬季', 11, 2, 501.00, '否', 5, '11月去的柘王宫遗址，和家人出行。地点在亳州，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约501元，氛围感不错。景点印象：传为古时候侯爵的封地，建有三宫六院、72眼井。考古证实为北宋时期遗址，现为涡阳县重点文物保护单位。整体感受是特别满意，以后还会来。二刷意愿：否。', '0%', 56);
