INSERT INTO `travel_review` VALUES (19635, 'TR019635', '兴伊措', '甘孜藏族自治州', '四川', '文化打卡', '夏季', 5, 2, 993.00, '否', 5, '5月去的兴伊措，和朋友出行。地点在甘孜藏族自治州，地铁到达方便，现场人流量适中。这次玩了2天，人均花费约993元，氛围感不错。景点印象：兴伊措藏语意为“献湖”之意，它是海子山最大的湖泊，位于海子山中部，面积7.5平方公里，淡水湖。整体感受是特别满意，很推荐。二刷意愿：否。', '1%', 93);
INSERT INTO `travel_review` VALUES (19636, 'TR019636', '白龙江', '甘南', '甘肃', '亲子出游', '秋季', 6, 3, 1158.00, '否', 5, '6月去的白龙江，和家人出行。地点在甘南，公交换乘方便，现场人流量适中。这次玩了3天，人均花费约1158元，拍照很出片。景点印象：白龙江激情漂流位于青藏高原东部，甘南藏族自治州南端的迭部县。西南同四川省若尔盖县、九寨沟县毗邻，加之气候环境宜人，乡风民情纯朴，是国内外游人梦幻中的世外桃园。\n白龙江是长江的重要一级支流。白龙江激情漂流起自迭部县城以东2公里的亚古桥…整体感受是挺惊喜，很推荐。二刷意愿：否。', '1%', 42);
