INSERT INTO `travel_review` VALUES (19648, 'TR019648', '释迦多宝如来佛塔', '黄冈', '湖北', '周末短途', '春季', 1, 1, 676.00, '否', 5, '1月去的释迦多宝如来佛塔，和家人出行。地点在黄冈，地铁到达方便，现场人不算多。这次玩了1天，人均花费约676元，氛围感不错。景点印象：在五祖寺前一天门。据塔身铭记为北宋宣和三年（1121年）所建。系用素面灰色砂粒岩石砌成，八角五级，高5米，下设莲瓣束腰须弥座，束腰八角各设有挺拔劲健的托塔力士一尊。座上置塔身，形如立鼓，其南面凿佛龛，内供佛像端坐，龛右镌刻“释迦多宝如…整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '0%', 78);
