INSERT INTO `travel_review` VALUES (19660, 'TR019660', '仙峪', '渭南', '陕西', '深度游', '秋季', 7, 2, 1106.00, '否', 5, '7月去的仙峪，和朋友出行。地点在渭南，自驾停车需要提前规划，现场人流量适中。这次玩了2天，人均花费约1106元，夜景表现很好。景点印象：仙峪又名车箱谷，在华山峪西， 仙峪深五十余里，峪道窄狭清幽，山路崎岖蜿蜒，河流湍急，山石险峻，多处路段凿崖加栈凌空通过。进峪五里处，有斜岭横阻，令人有谷尽路绝之感，然越岭横度，又不能不平添一种柳暗花明的情趣。整体感受是挺惊喜，很推荐。二刷意愿：否。', '1%', 91);
