INSERT INTO `travel_review` VALUES (19698, 'TR019698', '文庙', '临沧', '云南', '城市漫游', '秋季', 8, 6, 1515.00, '否', 5, '8月去的文庙，一个人出行。地点在临沧，自驾停车需要提前规划，现场人不算多。这次玩了6天，人均花费约1515元，夜景表现很好。景点印象：在凤庆县城西文庙街。由鸣凤阁、崇圣殿、大成殿、大成门、棂星门、龙门石坊、泮池等建筑组成。占地12000平方米。始建一明万历三十四年（1606年），清康熙八年（1669年）迁建。大成殿重檐歇山顶，面阔18.3米，进深13米，檐下悬\"圣集大成\"、\"斯文在兹…整体感受是特别满意，很推荐。二刷意愿：否。', '0%', 74);
