INSERT INTO `travel_review` VALUES (19719, 'TR019719', '沧州齐堤', '沧州', '河北', '亲子出游', '冬季', 11, 2, 800.00, '是', 5, '11月去的沧州齐堤，情侣出行。地点在沧州，地铁到达方便，现场游客较多。这次玩了2天，人均花费约800元，氛围感不错。景点印象：战国时期，齐恒公为御黄河水所筑。位于孟村自治县南部的残堤尚有2米多高，30米宽，自西向东，迤逦曲折。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 64);
