INSERT INTO `travel_review` VALUES (19786, 'TR019786', '圆明园', '北京', '北京', '亲子出游', '夏季', 4, 2, 766.00, '是', 4, '4月去的圆明园，和家人出行。地点在北京，自驾停车需要提前规划，现场人流量适中。这次玩了2天，人均花费约766元，氛围感不错。景点印象：古老中国最深的一道伤疤，通过断壁残垣寻找当年帝国的辉煌掠影。整体感受是整体不错，周末来刚好。二刷意愿：是。', '32%', 79);
