INSERT INTO `travel_review` VALUES (19788, 'TR019788', '柒开淖旅游区', '鄂尔多斯', '内蒙古', '文化打卡', '春季', 2, 3, 1246.00, '是', 5, '2月去的柒开淖旅游区，一个人出行。地点在鄂尔多斯，自驾停车需要提前规划，现场游客较多。这次玩了3天，人均花费约1246元，夜景表现很好。景点印象：“柒开淖”是蒙语，意为“飘香的马奶湖”。历代高僧引用蒙古民族马奶圣洁之意将其赐名为“飘香的马奶湖”。从此，这里风调雨顺、五谷丰登，受到恩惠的人们为了表达敬重之意，在“柒开淖”的西侧和东侧分别建起“龙王庙”和“脑高布勒庙”。\n柒开淖…整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 70);
