INSERT INTO `travel_review` VALUES (19791, 'TR019791', '渔梁洲', '襄阳', '湖北', '城市漫游', '冬季', 11, 2, 322.00, '是', 4, '11月去的渔梁洲，一个人出行。地点在襄阳，地铁到达方便，现场人不算多。这次玩了2天，人均花费约322元，拍照很出片。景点印象：在襄樊市襄阳城南岘首山东北侧。因水落时洲人取竹木为梁用以捕鱼，故名。三面环水，一面依山，面积10余平方公里。水环山抱，土地肥沃，村落密布，林木昌盛，渔夫张网，牧童横笛，风光十分诱人。据《水经注》载：“沔水中有渔梁洲，为庞德公沂居。”…整体感受是体验挺好，周末来刚好。二刷意愿：是。', '0%', 91);
INSERT INTO `travel_review` VALUES (19792, 'TR019792', '龙子湖', '蚌埠', '安徽', '文化打卡', '夏季', 5, 2, 618.00, '是', 4, '5月去的龙子湖，和家人出行。地点在蚌埠，公交换乘方便，现场人不算多。这次玩了2天，人均花费约618元，氛围感不错。景点印象：龙子湖风景区座落于蚌埠市东郊，主要由龙湖、曹山、雪华山、西芦山及锥子山组成，大体呈三山夹一湖的独特地貌。整体感受是整体不错，可以安排半天到一天。二刷意愿：是。', '50%', 100);
