INSERT INTO `travel_review` VALUES (19861, 'TR019861', '农团生态旅游景区', '自贡', '四川', '拍照旅行', '春季', 12, 2, 1087.00, '是', 5, '12月去的农团生态旅游景区，情侣出行。地点在自贡，公交换乘方便，现场游客较多。这次玩了2天，人均花费约1087元，夜景表现很好。景点印象：农团生态旅游风景区地处自贡市区西南边缘，距自贡市区18公里，交通、通讯十分便利。风景区内均属深丘地貌，一般海拔400-480米之间，属岷江流域越溪河水系溜根河的发源地。乡内属大陆季风性气候，雨量充沛，无霜期长，湿润凉爽。多年平均气温17.1摄…整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 67);
