INSERT INTO `travel_review` VALUES (19902, 'TR019902', '中国长寿城', '眉山', '四川', '周末短途', '冬季', 10, 5, 1209.00, '否', 3, '10月去的中国长寿城，情侣出行。地点在眉山，公交换乘方便，现场人流量适中。这次玩了5天，人均花费约1209元，历史文化气息浓。景点印象：彭山，是汉张纲晋李密的故乡，城市雕塑\"忠孝之邦\"，成为彭山人弘扬传统美德的警示与见证；彭山，是古代长寿老人彭祖的生栖之地，长寿文化源远流长，据全国第四次人口普查表明，彭山百岁老人的比例高出全国平均水平的17倍；彭山，是世界茶叶的发源地…整体感受是体验一般，按需选择。二刷意愿：否。', '0%', 42);
