INSERT INTO `travel_review` VALUES (19912, 'TR019912', '赶羊沟', '雅安', '四川', '拍照旅行', '夏季', 5, 1, 541.00, '是', 4, '5月去的赶羊沟，和家人出行。地点在雅安，自驾停车需要提前规划，现场人不算多。这次玩了1天，人均花费约541元，拍照很出片。景点印象：赶羊沟位于县西部19公里，陇东镇西部，面积348平方公里。由赶羊沟、青龙峡、猫子湾、贵强湾、鹿井沟、东拉山沟等部分组成，有青龙峡、石窑头、龙揭盖、青草塘、半蓬山、中梁子、穿山梁子、双全窝、银山口、关门山、两河口及万亩桂花等众多景点，区…整体感受是还蛮满意，周末来刚好。二刷意愿：是。', '0%', 73);
