INSERT INTO `travel_review` VALUES (19915, 'TR019915', '青格里度假村', '博尔塔拉', '新疆', '亲子出游', '春季', 12, 1, 305.00, '否', 3, '12月去的青格里度假村，一个人出行。地点在博尔塔拉，公交换乘方便，现场人不算多。这次玩了1天，人均花费约305元，历史文化气息浓。景点印象：青格里，蒙古语的意思是条美丽清澈的河流，正是这条美丽的河流才孕育出了青河这片洁净而富饶的土地。走进青格里，不难发现一个个美丽而神奇的旅游景点。青河县旅游景点分布按线路可形成草原文化旅游线路、生态旅游线路、大漠风景旅游线路。\n草原旅…整体感受是还可以，别抱太高期待。二刷意愿：否。', '0%', 53);
