INSERT INTO `travel_review` VALUES (19965, 'TR019965', '砻市景区', '吉安', '江西', '周末短途', '春季', 12, 3, 584.00, '否', 5, '12月去的砻市景区，一个人出行。地点在吉安，公交换乘方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约584元，历史文化气息浓。景点印象：位于砻市镇，在黄洋界西南面，距茨坪50公里，是朱毛会师圣地。砻市是一个山清水秀的小山镇，位于井冈山北麓的莽莽丛林之中，城区面积8平方公理，全镇人口18000人。龙江河自南向北流贯全镇，两岸树木葱郁，会师圣地与山水生态相融合的意境逐步形成。…整体感受是超出预期，以后还会来。二刷意愿：否。', '0%', 98);
