INSERT INTO `travel_review` VALUES (19979, 'TR019979', '合山怀集风景区', '来宾', '广西', '周末短途', '秋季', 7, 3, 955.00, '否', 3, '7月去的合山怀集风景区，一个人出行。地点在来宾，自驾停车需要提前规划，现场人不算多。这次玩了3天，人均花费约955元，氛围感不错。景点印象：位于合山市河里乡怀集村。国道322线从库区东侧穿过，距离合山市区20公里，是山水型自然风景区.水库库区面积约1000亩，水面弯延狭长，三面青山环抱，南面红水河奔腾而过，景色壮观。库区中部有一个面积约10多亩的小岛，岛上常有野兔、野鸭出没，给水…整体感受是中规中矩，按需选择。二刷意愿：否。', '0%', 16);
