INSERT INTO `travel_review` VALUES (19987, 'TR019987', '西大圈', '七台河', '黑龙江', '拍照旅行', '冬季', 10, 1, 172.00, '否', 4, '10月去的西大圈，和朋友出行。地点在七台河，地铁到达方便，现场游客较多。这次玩了1天，人均花费约172元，氛围感不错。景点印象：西大圈森林公园风光旖旎，令观光者心旷神怡，流连忘返。公园内有极其丰富的自然景观，洪峡谷可供漂流，河水清澈见底，河道磐石错落、蜿蜒曲折，两岸树木高大茂盛，百鸟争鸣，百花争艳，景色秀美；卧龙峰可供攀登，峰顶是一座高43米、长350米的悬崖…整体感受是体验挺好，可以安排半天到一天。二刷意愿：否。', '0%', 74);
