INSERT INTO `travel_review` VALUES (19995, 'TR019995', '临淄墓群', '淄博', '山东', '亲子出游', '春季', 1, 2, 605.00, '是', 5, '1月去的临淄墓群，和朋友出行。地点在淄博，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约605元，夜景表现很好。景点印象：在齐都临淄周围几十里的地面上，大约分布着150多座古墓，被称为“临淄墓群”。古墓的年代上起春秋中后期，下迄秦汉。墓主有国君、王侯、贵族、大夫、将军、名士等。墓的形制多为高大的封土墓，状如山丘。1977年，国家将“临淄墓群”公布为省级重点…整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '0%', 77);
