INSERT INTO `travel_review` VALUES (20000, 'TR020000', '广州中山纪念堂', '广州', '广东', '城市漫游', '秋季', 6, 1, 365.00, '是', 5, '6月去的广州中山纪念堂，和朋友出行。地点在广州，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约365元，夜景表现很好。景点印象：中山纪念堂富有纪念意义，来此缅怀历史伟人。整体感受是特别满意，很推荐。二刷意愿：是。', '12%', 70);
INSERT INTO `travel_review` VALUES (20001, 'TR020001', '苏巴什古城', '阿克苏', '新疆', '文化打卡', '秋季', 8, 2, 474.00, '是', 5, '8月去的苏巴什古城，一个人出行。地点在阿克苏，公交换乘方便，现场游客较多。这次玩了2天，人均花费约474元，拍照很出片。景点印象：苏巴什故城实际叫“苏巴什佛寺”，又名“昭怙悝大寺”，波涛滚滚的库车河穿城而过。据说，这条河就是《西游记》里“子母河”的下游。故城遗址始建于东汉（公元1世纪），隋唐（公元6至8世纪）盛极一时。\n唐贞观二年（公元628年），著名高僧玄奘去印…整体感受是挺惊喜，很推荐。二刷意愿：是。', '1%', 49);
INSERT INTO `travel_review` VALUES (20002, 'TR020002', '三道门森林公园', '安康', '陕西', '亲子出游', '冬季', 10, 2, 930.00, '是', 4, '10月去的三道门森林公园，和家人出行。地点在安康，公交换乘方便，现场游客较多。这次玩了2天，人均花费约930元，拍照很出片。景点印象：陕西省镇坪三道门森林公园，位于陕西最南端大巴山中段北坡的马鞍山上，距县城5公里。位处南宫山、千家坪森林公园和四川巫溪双溪溶洞、巫山的小山峡、奉节白帝城等景区的中间位置。以4种气候类型、独有特色的天然植被、珍稀动植物和石山地貌为特色。…整体感受是整体不错，周末来刚好。二刷意愿：是。', '0%', 65);
