INSERT INTO `travel_review` VALUES (20015, 'TR020015', '花乡农家乐旅游区', '益阳', '湖南', '亲子出游', '冬季', 9, 2, 504.00, '是', 4, '9月去的花乡农家乐旅游区，和家人出行。地点在益阳，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约504元，历史文化气息浓。景点印象：益阳花乡农家乐旅游区位于赫山区黄泥湖乡仙蜂岭村，距益阳市中心城区6.5公里，被资水和志溪河环抱。\n仙蜂岭是闻名遐尔的花会之乡。早在上个世纪九十年代，仙蜂岭人集前辈的智慧和经验，进行花卉苗木的生产栽培。\n至今发展到300多户花农，1600多亩花…整体感受是体验挺好，可以安排半天到一天。二刷意愿：是。', '0%', 66);
INSERT INTO `travel_review` VALUES (20016, 'TR020016', '越王楼', '绵阳', '四川', '城市漫游', '秋季', 6, 7, 1833.00, '是', 4, '6月去的越王楼，情侣出行。地点在绵阳，自驾停车需要提前规划，现场人流量适中。这次玩了7天，人均花费约1833元，拍照很出片。景点印象：越王楼与黄鹤楼、滕王阁、岳阳楼并称唐代四大名楼，自唐以来，文人雅士题咏越王楼诗篇多达150余篇，故有学者称之为“天下诗文第一楼”。整体感受是还蛮满意，可以安排半天到一天。二刷意愿：是。', '6%', 97);
INSERT INTO `travel_review` VALUES (20017, 'TR020017', '须弥山石窟', '固原', '宁夏', '亲子出游', '秋季', 6, 1, 381.00, '是', 5, '6月去的须弥山石窟，情侣出行。地点在固原，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约381元，氛围感不错。景点印象：这里有北魏到隋唐各个朝代不同风格的石窟。 唐代大佛楼内的佛像，比云冈和龙门石窟的主佛像还高大。整体感受是超出预期，以后还会来。二刷意愿：是。', '41%', 102);
