INSERT INTO `travel_review` VALUES (20026, 'TR020026', '库木塔格沙漠', '北疆', '新疆', '深度游', '春季', 2, 6, 1576.00, '是', 3, '2月去的库木塔格沙漠，和家人出行。地点在北疆，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了6天，人均花费约1576元，历史文化气息浓。景点印象：是国内乃至世界罕见的与城市零距离的沙漠，千百年来沙不进人不退，十分罕见。整体感受是体验一般，别抱太高期待。二刷意愿：是。', '13%', 57);
