INSERT INTO `travel_review` VALUES (20030, 'TR020030', '东晋壁画墓', '朝阳', '辽宁', '文化打卡', '冬季', 11, 1, 407.00, '是', 5, '11月去的东晋壁画墓，情侣出行。地点在朝阳，打车比较省心，现场人不算多。这次玩了1天，人均花费约407元，夜景表现很好。景点印象：东晋壁画墓，位于十二台乡袁台子村，呈长方形，石筑墓室，墓内有百室和小龛，墓壁白灰面，并施彩绘画面，墓顶绘有鸟， 星云阁，墓壁绘墓主像，侍女图、射猎图、 秦食图、庖橱图、庭院图，极具考古价值。整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 112);
