INSERT INTO `travel_review` VALUES (20050, 'TR020050', '广东第一峰旅游风景区', '清远', '广东', '亲子出游', '秋季', 7, 3, 1126.00, '否', 3, '7月去的广东第一峰旅游风景区，和朋友出行。地点在清远，公交换乘方便，现场游客较多。这次玩了3天，人均花费约1126元，氛围感不错。景点印象：攀登广东最高峰，欣赏原始美景，星空与日落之景更是迷人。整体感受是中规中矩，按需选择。二刷意愿：否。', '3%', 98);
INSERT INTO `travel_review` VALUES (20051, 'TR020051', '谢鲁天堂温泉休闲度假村', '玉林', '广西', '亲子出游', '夏季', 3, 3, 1072.00, '是', 5, '3月去的谢鲁天堂温泉休闲度假村，情侣出行。地点在玉林，打车比较省心，现场游客较多。这次玩了3天，人均花费约1072元，夜景表现很好。景点印象：距县城25公里，离玉林市70公里，至华南第一大港口城市湛江约133公里，是按国际四星标准设计和建设的、以先进温泉养生理念打造的精致休闲、保健养生的建筑类人文风景旅游区。\n度假中心内有被称为“岭南第一泉”、岭南唯一的可泡可喝的飞龙山温矿泉，…整体感受是挺惊喜，很推荐。二刷意愿：是。', '12%', 68);
