INSERT INTO `travel_review` VALUES (20131, 'TR020131', '白马寺', '洛阳', '河南', '城市漫游', '春季', 12, 2, 367.00, '否', 5, '12月去的白马寺，和家人出行。地点在洛阳，公交换乘方便，现场人流量适中。这次玩了2天，人均花费约367元，历史文化气息浓。景点印象：中国佛教的祖庭，寺内的“镇寺之宝”——元代的“夹贮干漆造像”，已有700年的历史。 观赏珍贵碑碣——元代书法家赵孟頫手书的《洛京白马寺祖庭记》。整体感受是特别满意，以后还会来。二刷意愿：否。', '49%', 74);
