INSERT INTO `travel_review` VALUES (20143, 'TR020143', '关帝山', '吕梁', '山西', '深度游', '春季', 12, 5, 1250.00, '否', 4, '12月去的关帝山，和家人出行。地点在吕梁，公交换乘方便，现场人流量适中。这次玩了5天，人均花费约1250元，历史文化气息浓。景点印象：在山西省吕梁山中段地跨交城、方山两县之间，有一个蕴藏着丰富动植物资源的天然宝库，这就是距太原市150公里的关帝山（又称宫帝山、南阳山、三层崖）国家森林公园。该公园设在庞泉沟国家级自然保护区内，1992年9月经林业部批准建立，面积78万亩。整体感受是还蛮满意，可以安排半天到一天。二刷意愿：否。', '0%', 66);
