INSERT INTO `travel_review` VALUES (20230, 'TR020230', '高贵三潭', '随州', '湖北', '拍照旅行', '秋季', 8, 2, 808.00, '是', 5, '8月去的高贵三潭，和朋友出行。地点在随州，自驾停车需要提前规划，现场人流量适中。这次玩了2天，人均花费约808元，夜景表现很好。景点印象：高贵三潭风景区位于广水市北部，这里有清奇幽深的三叠瀑布\"一线天\"；闻名遐迩的雄关古道平靖关；碧波万顷的许家冲水库；峻险的鄂北第一峰大贵寺金顶，海拔908米；还有千姿百态、惟妙惟肖的\"双狮夺珠\"石，碧玉湖，天池，龙眼圣水井，罗汉池。这里林…整体感受是特别满意，很推荐。二刷意愿：是。', '0%', 75);
