INSERT INTO `travel_review` VALUES (20232, 'TR020232', '独库公路', '伊犁', '新疆', '城市漫游', '夏季', 3, 5, 1315.00, '否', 5, '3月去的独库公路，和朋友出行。地点在伊犁，打车比较省心，现场人流量适中。这次玩了5天，人均花费约1315元，拍照很出片。景点印象：独库公路全长561公里，横亘崇山峻岭，连接了众多少数民族聚居区。整体感受是特别满意，很推荐。二刷意愿：否。', '11%', 120);
INSERT INTO `travel_review` VALUES (20233, 'TR020233', '汤旺河国家公园', '伊春', '黑龙江', '城市漫游', '冬季', 9, 6, 1261.00, '否', 5, '9月去的汤旺河国家公园，情侣出行。地点在伊春，公交换乘方便，现场人流量适中。这次玩了6天，人均花费约1261元，氛围感不错。景点印象：黑龙江汤旺河国家公园地处小兴安岭南麓，植被覆盖率99.8%以上，以红松为主的针阔叶混交林是亚洲最完整、最具代表性的原始红松林生长地，素有“红松故乡”之美誉。整体感受是超出预期，很推荐。二刷意愿：否。', '31%', 34);
INSERT INTO `travel_review` VALUES (20234, 'TR020234', '普化寺', '怒江', '云南', '文化打卡', '春季', 2, 3, 1162.00, '是', 5, '2月去的普化寺，情侣出行。地点在怒江，自驾停车需要提前规划，现场人流量适中。这次玩了3天，人均花费约1162元，夜景表现很好。景点印象：云南怒江普化寺离重丁天主教堂不到一小时的路程，在东风村，沿着小道穿过村中民居，看到的藏式风格的简陋寺院就是了。从普化寺看石门关比在怒江边看石门关更加奇险。在这里拍摄更能体现石门关的险要。普化寺平时锁门，可以到旁边的小屋里找喇嘛帮忙…整体感受是特别满意，以后还会来。二刷意愿：是。', '3%', 93);
