INSERT INTO `travel_review` VALUES (20260, 'TR020260', '铭德农业生态园', '钦州', '广西', '拍照旅行', '冬季', 10, 1, 635.00, '是', 5, '10月去的铭德农业生态园，情侣出行。地点在钦州，公交换乘方便，现场游客较多。这次玩了1天，人均花费约635元，夜景表现很好。景点印象：铭德生态园位于钦州城东郊金海湾东大街，黎合江往市区走400米处，是南宁、北海、钦州港、三娘湾交通要道的交汇点。园区山青水秀，有铁索桥横跨湖中，山边竹木草棚，花香鸟语，集钓虾、烧烤、饮食、休闲、娱乐于一体，是旅游者周末的好去处。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 101);
