INSERT INTO `travel_review` VALUES (20278, 'TR020278', '延寿寺', '武威', '甘肃', '深度游', '夏季', 3, 3, 935.00, '否', 5, '3月去的延寿寺，和家人出行。地点在武威，地铁到达方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约935元，夜景表现很好。景点印象：原名曾家堡庙，坐落在武威市清源镇曾家堡村。现存建筑只有伽蓝菩萨殿、大雄宝殿等。伽蓝菩萨殿前卷后脊古柏掩映虽经历史剥蚀，仍不失当年风韵。大雄宝殿是寺中的正殿。“大雄”是释迦牟尼的尊号，意谓佛祖有大力，能伏烦恼魔、五阴魔、死魔、天子魔…整体感受是特别满意，以后还会来。二刷意愿：否。', '3%', 49);
