INSERT INTO `travel_review` VALUES (20352, 'TR020352', '大孤山旅游风景区', '四平', '吉林', '城市漫游', '春季', 2, 1, 699.00, '否', 4, '2月去的大孤山旅游风景区，和朋友出行。地点在四平，公交换乘方便，现场人不算多。这次玩了1天，人均花费约699元，拍照很出片。景点印象：大孤山旅游风景区为国家AA级旅游风景区，位于县城西南14公里。大孤山以独特的火山地貌景观为核心，集观光游览、科研考察、休闲度假、娱乐为一体综合性景区。\n　　大孤山为伊通火山群之首，是最高大的一座。满语名为“阿勒坦额墨勒”，意为金色的马…整体感受是还蛮满意，可以安排半天到一天。二刷意愿：否。', '0%', 66);
