INSERT INTO `travel_review` VALUES (20355, 'TR020355', '黄蜂窝茶山', '梅州', '广东', '深度游', '春季', 2, 1, 368.00, '是', 4, '2月去的黄蜂窝茶山，和朋友出行。地点在梅州，自驾停车需要提前规划，现场人不算多。这次玩了1天，人均花费约368元，拍照很出片。景点印象：黄蜂窝茶山旅游区，于一九九零年建成，是集种茶、采茶、制茶、宣传茶文化的名茶示范基地和旅游观光的旅游区。整体感受是还蛮满意，周末来刚好。二刷意愿：是。', '5%', 50);
