INSERT INTO `travel_review` VALUES (20358, 'TR020358', '透龙山', '伊春', '黑龙江', '拍照旅行', '秋季', 7, 6, 1826.00, '否', 4, '7月去的透龙山，情侣出行。地点在伊春，公交换乘方便，现场高峰时段比较拥挤。这次玩了6天，人均花费约1826元，夜景表现很好。景点印象：透龙山庄位于小兴安岭南麓的铁力市，距哈市240公里，乘火车、汽车只需2-3小时。这里有神秘的千年古洞，罕见的奇石怪树，秀丽的湖光山色，甘甜的清泉溪水，宝贵的原始湿地。是您休闲度假、旅游观光的理想去处。这里天常蓝、水常清、山常绿，有天然\"…整体感受是体验挺好，周末来刚好。二刷意愿：否。', '0%', 61);
