INSERT INTO `travel_review` VALUES (20362, 'TR020362', '双湖', '那曲', '西藏', '文化打卡', '秋季', 7, 3, 970.00, '是', 5, '7月去的双湖，和朋友出行。地点在那曲，公交换乘方便，现场人不算多。这次玩了3天，人均花费约970元，氛围感不错。景点印象：蒙语为“胡尔巴努尔”意为“双湖”，地处喀纳斯湖西岸―恰其阿依特山南坡河谷中，北西走向，呈椭圆状，由相隔三百米左右的两个狭长小湖串连构成，长1200米，宽度不等，一般在300m左右，湖面积1.4km2，海拔1498米。整体感受是超出预期，值得专门打卡。二刷意愿：是。', '1%', 63);
