INSERT INTO `travel_review` VALUES (20375, 'TR020375', '中共广西省工委旧址', '贺州', '广西', '文化打卡', '春季', 12, 2, 781.00, '否', 5, '12月去的中共广西省工委旧址，和家人出行。地点在贺州，打车比较省心，现场人不算多。这次玩了2天，人均花费约781元，拍照很出片。景点印象：中共广西省工委旧址位于黄姚镇姚江与珠江口汇合处，旧名宝珠观。因位于宝珠山旁而得名。宝珠观始建于明嘉靖三年（1524年），清乾隆九年’（1744年）和光绪二十年（1894年）两度重修。分上下两殿，皆雕梁画栋，石刻石柱、琉璃瓦盖。殿内有壁画，栩栩…整体感受是超出预期，值得专门打卡。二刷意愿：否。', '4%', 76);
