INSERT INTO `travel_review` VALUES (20393, 'TR020393', '南山古柏', '天水', '甘肃', '拍照旅行', '秋季', 7, 2, 500.00, '否', 4, '7月去的南山古柏，情侣出行。地点在天水，地铁到达方便，现场人流量适中。这次玩了2天，人均花费约500元，拍照很出片。景点印象：南郭寺中院内，一座砖砌花墙围护着一株古侧柏。树身分三枝，形如斧劈，南北倾伸。北倾两枝中一枝已枯断，每枝干径均在一米以上。这株古柏就是杜甫诗中所称的“老树”。 1986年，北京市园林科学研究所古树研究人员到南郭寺对这株侧柏进行实地考察。…整体感受是还蛮满意，周末来刚好。二刷意愿：否。', '1%', 41);
