INSERT INTO `travel_review` VALUES (20400, 'TR020400', '兰花山溶洞', '许昌', '河南', '周末短途', '夏季', 3, 2, 723.00, '是', 4, '3月去的兰花山溶洞，一个人出行。地点在许昌，打车比较省心，现场人不算多。这次玩了2天，人均花费约723元，历史文化气息浓。景点印象：位于鸠山乡金盆水库以下1500米处，洞体高、宽2――10米不等，长度约1200米，岩溶发育较好，钟乳石笋，石幔、石柱举目可见，是长江以北罕见的石灰岩溶洞，而且，这里四周植被繁茂，松柏翠绿，溪水环绕，景色宜人，加之紧邻大路，交通方便，有很高的…整体感受是还蛮满意，周末来刚好。二刷意愿：是。', '0%', 47);
