INSERT INTO `travel_review` VALUES (20421, 'TR020421', '中峰', '渭南', '陕西', '深度游', '冬季', 10, 5, 1517.00, '否', 4, '10月去的中峰，和家人出行。地点在渭南，地铁到达方便，现场高峰时段比较拥挤。这次玩了5天，人均花费约1517元，氛围感不错。景点印象：中峰又称玉女峰。春秋时有一年青人名萧史，善吹洞箫，引来秦穆公之女弄玉的爱慕。弄玉抛弃荣华富贵，与夫君同来华山隐居，玉女峰由此得名。整体感受是体验挺好，周末来刚好。二刷意愿：否。', '9%', 65);
