INSERT INTO `travel_review` VALUES (20467, 'TR020467', '孔子还乡祠', '商丘', '河南', '拍照旅行', '夏季', 3, 5, 1164.00, '是', 5, '3月去的孔子还乡祠，一个人出行。地点在商丘，公交换乘方便，现场高峰时段比较拥挤。这次玩了5天，人均花费约1164元，拍照很出片。景点印象：史籍记载，孔子的祖先是宋国人。西周初年，微子启封于宋。死后，其弟微仲继位。微仲死后，子宋公稽立。宋公稽死后，子丁公申立。丁公申死后，子泯(min)公共立。泯公共死后，弟炀公熙立。泯公共次子鲋祀杀炀公，欲立太子弗父何。弗父何不受，鲋祀自…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 90);
