INSERT INTO `travel_review` VALUES (20480, 'TR020480', '侗寨风情村', '邵阳', '湖南', '亲子出游', '秋季', 8, 4, 1153.00, '是', 5, '8月去的侗寨风情村，和朋友出行。地点在邵阳，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了4天，人均花费约1153元，氛围感不错。景点印象：侗寨风情村\n侗寨风情村距南山场部30公里，聚居着2800多名侗族乡亲，这里完整地保留着侗族人民原始、古朴、奇特的民族风情。村民住的全是一色的吊脚楼房；寨中有鼓楼、风雨桥，村民有自己的服饰、语言、节日、风俗，他们还时兴集体舞、对山歌、喝油…整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '0%', 64);
