INSERT INTO `travel_review` VALUES (20520, 'TR020520', '黑沟', '哈密', '新疆', '文化打卡', '春季', 12, 2, 679.00, '是', 4, '12月去的黑沟，一个人出行。地点在哈密，打车比较省心，现场高峰时段比较拥挤。这次玩了2天，人均花费约679元，历史文化气息浓。景点印象：距县城西南8公里处有一个山沟叫西黑沟。黑沟山高、沟长，植被茂盛，暖季一片葱笼墨绿，即使冬季大雪封盖，但松柏长青，依然苍翠，与墨色有不解之缘，才以黑命名，所以称“黑沟”。\n黑沟山高，雪冠终年晶莹闪耀，冰川纯白无瑕，与黑绿形成对比，是黑…整体感受是还蛮满意，周末来刚好。二刷意愿：是。', '0%', 100);
