INSERT INTO `travel_review` VALUES (20527, 'TR020527', '郛堤城', '沧州', '河北', '周末短途', '秋季', 6, 3, 518.00, '是', 5, '6月去的郛堤城，和朋友出行。地点在沧州，打车比较省心，现场人不算多。这次玩了3天，人均花费约518元，氛围感不错。景点印象：郛堤城位于沧州盐山县城关镇西北4公里处。呈方形，周长2.5公里，占地约31万平方米。城墙为粘土结构，人工夯筑，城基残留部分高于地面4至5米，宽7至13米。\n旧志有关该城的记载不一。有谓建于汉代以前，有谓汉合骑追侯公孙敖御匈奴屯兵之所及其封地。…整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 73);
