INSERT INTO `travel_review` VALUES (20540, 'TR020540', '当奈湿地', '大庆', '黑龙江', '深度游', '秋季', 8, 3, 993.00, '是', 5, '8月去的当奈湿地，一个人出行。地点在大庆，打车比较省心，现场游客较多。这次玩了3天，人均花费约993元，拍照很出片。景点印象：当奈人居生态村位于扎龙自然保护区腹地，总面积57万亩，现在仍然保持着完整的原始风貌，大小湖泊星罗棋布，生物类别多种多样，这里有丹顶鹤、大雁、野鸭等珍贵鸟类200多种。每到夏季，蓝天碧水，芦苇荡漾，群鱼戏莲，百鸟欢歌。\n当奈，蒙古族语“当…整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '3%', 44);
