INSERT INTO `travel_review` VALUES (20552, 'TR020552', '石门摩崖石刻', '怒江', '云南', '亲子出游', '夏季', 5, 5, 1591.00, '是', 4, '5月去的石门摩崖石刻，一个人出行。地点在怒江，打车比较省心，现场高峰时段比较拥挤。这次玩了5天，人均花费约1591元，历史文化气息浓。景点印象：石门摩崖石刻位于贡山县茨开镇东400米当打村怒江西岸高50米的崖壁上。系贡山通福贡的古驿道旁，因地势险要称为石门。民国38年（1949年）设治局长梁之彦题刻\"石门\"二字。此处尚存石刻碑文三通，条幅二方。上书\"万家生佛\"四字。石碑之一，立于民国36…整体感受是体验挺好，周末来刚好。二刷意愿：是。', '4%', 47);
