INSERT INTO `travel_review` VALUES (20591, 'TR020591', '金凤山', '雅安', '四川', '亲子出游', '冬季', 11, 3, 1058.00, '否', 2, '11月去的金凤山，和朋友出行。地点在雅安，打车比较省心，现场人流量适中。这次玩了3天，人均花费约1058元，夜景表现很好。景点印象：金凤山公园在雅安市城区旁，以金凤寺和高颐墓阙为主要景点。金凤寺始建于唐初，重建和扩建于明清，寺庙掩映在葱葱苍翠之中，环境幽雅，占地1万平方米。天王、弥勒、大雄、观音四殿和罗汉堂建筑规模宏大，是千年古刹。整体感受是没达到预期，可考虑其他景点。二刷意愿：否。', '0%', 64);
