INSERT INTO `travel_review` VALUES (20642, 'TR020642', '紫岩山', '德阳', '四川', '城市漫游', '冬季', 11, 2, 718.00, '是', 5, '11月去的紫岩山，和朋友出行。地点在德阳，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约718元，氛围感不错。景点印象：紫岩山又名绵竹山，地处成都平原与岷山山脉交汇处，西北面高山天作，群峰叠翠。沱江之源绵远河蜿蜒出群山，一泻千里，形成成都平原北端的一个扇形冲击面棗绵竹市平坝区。在这片山地与平原交汇处，分布着许多名胜古迹和优美的自然景观，有风光秀丽的…整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 112);
