INSERT INTO `travel_review` VALUES (20669, 'TR020669', '古龙山峡谷群风景区', '百色', '广西', '深度游', '夏季', 4, 6, 1313.00, '是', 5, '4月去的古龙山峡谷群风景区，和家人出行。地点在百色，打车比较省心，现场人不算多。这次玩了6天，人均花费约1313元，历史文化气息浓。景点印象：古龙山峡谷群景区坐落在靖西县东南的湖润镇新灵村境内，与通灵峡谷景区毗邻，属自治区级古龙山水源林保护区实验区范围，南宁--大新--靖西--云南富宁二级公路（20315省道）从景区中间穿过，距靖西县城30公里，离南宁238公里，对外交通便捷.景区可分…整体感受是超出预期，以后还会来。二刷意愿：是。', '4%', 95);
