INSERT INTO `travel_review` VALUES (20671, 'TR020671', '佛山祖庙', '佛山', '广东', '文化打卡', '夏季', 3, 3, 788.00, '否', 4, '3月去的佛山祖庙，和家人出行。地点在佛山，公交换乘方便，现场人不算多。这次玩了3天，人均花费约788元，历史文化气息浓。景点印象：佛山必游景点，三雕二塑的典型，黄飞鸿和叶问馆都在这里，还可以看武术和舞狮表演。整体感受是体验挺好，可以安排半天到一天。二刷意愿：否。', '31%', 75);
INSERT INTO `travel_review` VALUES (20672, 'TR020672', '黔阳古城', '怀化', '湖南', '周末短途', '夏季', 5, 3, 600.00, '否', 4, '5月去的黔阳古城，情侣出行。地点在怀化，地铁到达方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约600元，拍照很出片。景点印象：周边配套比较齐全整体感受是整体不错，周末来刚好。二刷意愿：否。', '10%', 93);
INSERT INTO `travel_review` VALUES (20673, 'TR020673', '王莽洞', '荆门', '湖北', '深度游', '冬季', 11, 5, 1192.00, '是', 5, '11月去的王莽洞，和家人出行。地点在荆门，地铁到达方便，现场人流量适中。这次玩了5天，人均花费约1192元，夜景表现很好。景点印象：王莽洞风景区为国家2A级景点，是太子山国家森林公园的核心景区，位于荆门市东南。是一个以优良的生态环境为基础，人文景观为辅，集观光、度假、探险、科考于一体的生态旅游风景区。 景区内森林植被茂盛，四季分明，气候宜人。景区主要以自然景观、…整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '0%', 73);
