INSERT INTO `travel_review` VALUES (20690, 'TR020690', '黄河大佛', '济源', '河南', '周末短途', '冬季', 9, 2, 721.00, '否', 5, '9月去的黄河大佛，和朋友出行。地点在济源，公交换乘方便，现场人不算多。这次玩了2天，人均花费约721元，氛围感不错。景点印象：黄河大佛\n在孟良寨对面崖壁上，有一石崖酷似大佛屹立在黄河峡谷岸边，称之为黄河大佛。大佛高80余米，宝相庄严、浑然天成，令世人叹为观之。有趣的是，由于小浪底水库蓄水，黄河大佛下部被淹没水中，成为天下第一“浴佛”了。整体感受是超出预期，值得专门打卡。二刷意愿：否。', '0%', 78);
INSERT INTO `travel_review` VALUES (20691, 'TR020691', '寒山寺', '苏州', '江苏', '周末短途', '春季', 1, 4, 1094.00, '否', 5, '1月去的寒山寺，一个人出行。地点在苏州，自驾停车需要提前规划，现场人不算多。这次玩了4天，人均花费约1094元，氛围感不错。景点印象：千年名寺，诗句“姑苏城外寒山寺”的出处，来此撞钟、祈福。整体感受是特别满意，以后还会来。二刷意愿：否。', '39%', 80);
