INSERT INTO `travel_review` VALUES (20723, 'TR020723', '西安州古城', '中卫', '宁夏', '深度游', '夏季', 4, 5, 1251.00, '是', 5, '4月去的西安州古城，情侣出行。地点在中卫，地铁到达方便，现场游客较多。这次玩了5天，人均花费约1251元，历史文化气息浓。景点印象：西安州古城，历史上称之为\"固靖之咽喉，甘凉之襟带\"；今天的西安州城，已是断垣残壁，北城倾塌严重，城墙仅存七八尺的漫坡状土垄，南城现存状况较好，城之四周可见当年的护城壕痕迹。整体感受是挺惊喜，很推荐。二刷意愿：是。', '1%', 64);
