INSERT INTO `travel_review` VALUES (20731, 'TR020731', '峨眉山生态猴区', '乐山', '四川', '深度游', '春季', 2, 7, 1768.00, '是', 5, '2月去的峨眉山生态猴区，和朋友出行。地点在乐山，打车比较省心，现场高峰时段比较拥挤。这次玩了7天，人均花费约1768元，拍照很出片。景点印象：国内最大的野生猴区，有很多霸气的猴子在这里玩耍。整体感受是超出预期，值得专门打卡。二刷意愿：是。', '8%', 92);
INSERT INTO `travel_review` VALUES (20732, 'TR020732', '绝地争锋', '临汾', '山西', '周末短途', '秋季', 8, 1, 497.00, '是', 5, '8月去的绝地争锋，情侣出行。地点在临汾，打车比较省心，现场游客较多。这次玩了1天，人均花费约497元，拍照很出片。景点印象：黄河壶口一带，古为晋国与少数民族狄人的分界线，又是秦晋两国的分疆处，虽然晋陕峡谷的黄河两岸山高壁陡，往来交通不便，但有古渡可通，加上此地河槽稳固、窄狭易渡，冬季结冰坚实可载车骑，所以历朝当局多在此置关设隘，驻兵把守，作为进攻对方的…整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 71);
