INSERT INTO `travel_review` VALUES (20746, 'TR020746', '白水洞', '邵阳', '湖南', '城市漫游', '春季', 12, 1, 122.00, '是', 5, '12月去的白水洞，和家人出行。地点在邵阳，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约122元，夜景表现很好。景点印象：白水洞风景名胜区位于湘中新邵县境内，核心景区在严塘镇白水村。 早在明代， 白水洞就是湘中的旅游胜地，文人墨客纷来沓至， 多有赞咏。清人杨太灏著有《白水洞游记》、 李厚培著有《白水洞纪胜集》。白水洞风景名胜区于1999年经省人民政 府正式批…整体感受是特别满意，很推荐。二刷意愿：是。', '10%', 85);
