INSERT INTO `travel_review` VALUES (20753, 'TR020753', '十九人堆', '株洲', '湖南', '亲子出游', '秋季', 7, 3, 711.00, '是', 5, '7月去的十九人堆，和朋友出行。地点在株洲，公交换乘方便，现场游客较多。这次玩了3天，人均花费约711元，历史文化气息浓。景点印象：1928年1月12日，渌口地区工农自卫军攻打渌口团防局失利，27名自卫军战士牺牲。渌口一片白色恐怖，殉难者家属不能前来收尸，除亲友出面领走部分尸外，还有张启茂、张华山、易元胜、袁发树、易升翠、张大桂、刘奉年、唐文申等18位烈士和l位外乡遇难者…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 94);
