INSERT INTO `travel_review` VALUES (20762, 'TR020762', '月亮湖', '衢州', '浙江', '拍照旅行', '夏季', 3, 4, 1263.00, '是', 4, '3月去的月亮湖，和家人出行。地点在衢州，自驾停车需要提前规划，现场游客较多。这次玩了4天，人均花费约1263元，拍照很出片。景点印象：江山月亮湖是国家水利风景区、浙江省爱国主义教育基地、国家级蜂业示范区、国家级蜂产品基地。因座落在江山最有名的太阳山下，取阴阳对应和山水相映成趣而得名。\n旅游区内自然景观和人文景观都十分丰富。有旅游区出土的国家二级文物春秋时期的打击…整体感受是整体不错，可以安排半天到一天。二刷意愿：是。', '0%', 57);
