INSERT INTO `travel_review` VALUES (20796, 'TR020796', '五女峰', '通化', '吉林', '文化打卡', '秋季', 6, 2, 1274.00, '否', 3, '6月去的五女峰，和朋友出行。地点在通化，打车比较省心，现场高峰时段比较拥挤。这次玩了2天，人均花费约1274元，夜景表现很好。景点印象：五女峰国家森林公园总面积68.6平方公里。森林覆盖率94.5％，年平均气温6.5℃，年降雨量947毫米。公园内植物有100多科，1000余种。园内共有较大山峰26座，海拔1000米以上的有17座。景区风景奇异秀丽，山高林密，大树参天，珍贵的松、椴、楸、桦树，…整体感受是还可以，避开高峰更好。二刷意愿：否。', '37%', 42);
