INSERT INTO `travel_review` VALUES (20798, 'TR020798', '建水燕子洞', '红河', '云南', '周末短途', '秋季', 8, 2, 449.00, '否', 5, '8月去的建水燕子洞，一个人出行。地点在红河，打车比较省心，现场人流量适中。这次玩了2天，人均花费约449元，夜景表现很好。景点印象：每年5-7月份在洞中观看庞大燕群出巢、回巢的壮观情景。 尝一下当地最地道原始的燕窝粥。 惊险奇绝的钟乳悬匾表演不可错过。整体感受是挺惊喜，很推荐。二刷意愿：否。', '3%', 75);
