INSERT INTO `travel_review` VALUES (20801, 'TR020801', '安乐温泉', '安顺', '贵州', '深度游', '春季', 1, 2, 911.00, '是', 5, '1月去的安乐温泉，一个人出行。地点在安顺，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约911元，氛围感不错。景点印象：安乐温泉位于关岭花江乐安寨。《永宁州志》载：“一路三井，两旁水极清凉，唯中一井温如鼎沸，冬可濯足，居人常浴于此焉。”温泉处于烂田坝中，长约500米，宽约200米。整体感受是超出预期，值得专门打卡。二刷意愿：是。', '0%', 83);
