INSERT INTO `travel_review` VALUES (20836, 'TR020836', '千里葡萄长廊', '和田', '新疆', '文化打卡', '夏季', 3, 1, 818.00, '否', 4, '3月去的千里葡萄长廊，和朋友出行。地点在和田，公交换乘方便，现场人流量适中。这次玩了1天，人均花费约818元，历史文化气息浓。景点印象：和田县巴格其镇的农民为节省耕地，利用农田道路，将葡萄种在道路边上，枝蔓架在道路上方，多占天少占地，取得了明显的社会效益和经济效益。80年代初，和田县将这一创举大力推行，并进行了统一规划，以后逐年扩大，到目前为止，全县葡萄长廊达1500多…整体感受是体验挺好，推荐来看看。二刷意愿：否。', '4%', 42);
