INSERT INTO `travel_review` VALUES (20848, 'TR020848', '新四军纪念林园区', '淮南', '安徽', '文化打卡', '夏季', 4, 4, 1302.00, '是', 4, '4月去的新四军纪念林园区，和朋友出行。地点在淮南，打车比较省心，现场人流量适中。这次玩了4天，人均花费约1302元，氛围感不错。景点印象：淮南新四军纪念林是2002年10月兴建的。纪念林位于上窑森林公园花果山上，以树和碑相结合。树以银杏和苍松翠柏结合，以银杏为主，象征着先辈们的革命精神万古长青。该林共植银杏树千余棵，是我市目前最大的银杏林。颂扬新四军精神的纪念碑矗立在山岗…整体感受是体验挺好，可以安排半天到一天。二刷意愿：是。', '0%', 41);
