INSERT INTO `travel_review` VALUES (20917, 'TR020917', '布柳河仙人桥景区', '百色', '广西', '周末短途', '冬季', 9, 2, 1008.00, '是', 5, '9月去的布柳河仙人桥景区，和朋友出行。地点在百色，地铁到达方便，现场游客较多。这次玩了2天，人均花费约1008元，拍照很出片。景点印象：广西乐业县磨里乡弄流屯边上有一处幽境--布柳河，它在乐业大石围天坑群以北，距县城51公里。传说中布柳河是从远山流出的酒泉，因为壮语中“布”的意思是泉，“柳”的意思是酒。整体感受是超出预期，以后还会来。二刷意愿：是。', '1%', 99);
