INSERT INTO `travel_review` VALUES (20922, 'TR020922', '周庄', '苏州', '江苏', '深度游', '夏季', 5, 2, 538.00, '否', 5, '5月去的周庄，和家人出行。地点在苏州，打车比较省心，现场人流量适中。这次玩了2天，人均花费约538元，拍照很出片。景点印象：小桥流水与人家，双桥水巷摇橹船，还有沈万三的足迹待你寻访。整体感受是挺惊喜，很推荐。二刷意愿：否。', '19%', 97);
