INSERT INTO `travel_review` VALUES (20924, 'TR020924', '额济纳神树', '阿拉善盟', '内蒙古', '亲子出游', '春季', 2, 3, 1107.00, '是', 5, '2月去的额济纳神树，情侣出行。地点在阿拉善盟，公交换乘方便，现场游客较多。这次玩了3天，人均花费约1107元，拍照很出片。景点印象：额济纳神树位于达来呼布镇北二十八公里，树高27米，直径约4米。三百年前土尔扈特人初来额济纳，胡杨林木密集，其中“神树”巍然耸立挺拔，枝叶繁茂。整体感受是超出预期，值得专门打卡。二刷意愿：是。', '8%', 75);
