INSERT INTO `travel_review` VALUES (20927, 'TR020927', '漳河风景名胜区', '荆门', '湖北', '文化打卡', '冬季', 9, 2, 588.00, '是', 4, '9月去的漳河风景名胜区，情侣出行。地点在荆门，地铁到达方便，现场游客较多。这次玩了2天，人均花费约588元，历史文化气息浓。景点印象：漳河风景名胜区位于湖北荆门，地处古三国战场的中心地带，背靠荆山，面向江汉平原，是张家界、古隆中、长江三峡等旅游热线的黄金腹地。景区内有山水景观和山石景观两大类，尤以山水景观最具特色。整体感受是整体不错，推荐来看看。二刷意愿：是。', '0%', 98);
INSERT INTO `travel_review` VALUES (20928, 'TR020928', '陕西黄河壶口瀑布', '延安', '陕西', '亲子出游', '秋季', 7, 4, 1192.00, '是', 5, '7月去的陕西黄河壶口瀑布，一个人出行。地点在延安，地铁到达方便，现场高峰时段比较拥挤。这次玩了4天，人均花费约1192元，拍照很出片。景点印象：世界上少见的金黄色瀑布，黄河水呼啸而下，气势磅礴，令人震撼。整体感受是超出预期，很推荐。二刷意愿：是。', '70%', 50);
INSERT INTO `travel_review` VALUES (20929, 'TR020929', '海马洲', '汕尾', '广东', '城市漫游', '夏季', 5, 3, 855.00, '否', 3, '5月去的海马洲，一个人出行。地点在汕尾，地铁到达方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约855元，拍照很出片。景点印象：海马洲地处东海经济开发试验区南端，系乌坎港临海南郊虎头山延伸出的小岛，俗称“虎舌”。该岛南临碣石湾，东靠虎头山，西北面隔海与陆地相望。岛长3000米，宽350～650米，总面积2平方公里。岛内地势平坦，沙滩平缓向大海延伸，沙滩洁净，海水清澈…整体感受是中规中矩，按需选择。二刷意愿：否。', '0%', 39);
