INSERT INTO `travel_review` VALUES (20935, 'TR020935', '湘江', '长沙', '湖南', '城市漫游', '春季', 12, 1, 564.00, '否', 5, '12月去的湘江，情侣出行。地点在长沙，打车比较省心，现场人流量适中。这次玩了1天，人均花费约564元，夜景表现很好。景点印象：长沙的母亲河，两岸是秀丽的长沙沿江风光带。整体感受是特别满意，值得专门打卡。二刷意愿：否。', '10%', 64);
INSERT INTO `travel_review` VALUES (20936, 'TR020936', '白水仙', '吉安', '江西', '深度游', '冬季', 10, 4, 892.00, '否', 5, '10月去的白水仙，和家人出行。地点在吉安，公交换乘方便，现场人不算多。这次玩了4天，人均花费约892元，拍照很出片。景点印象：井冈山南面的遂川县，境内自然风光优美，人文景观丰富。白水仙、泉江、汤湖三个景区相互辉映，联成一片，面积达65平方公里。白水仙——泉江风景名胜区于1995年7月经江西省政府批准，列为省级重点风景名胜区。\n庙前约300米远的另一山中，还有个5级“…整体感受是挺惊喜，很推荐。二刷意愿：否。', '0%', 56);
INSERT INTO `travel_review` VALUES (20937, 'TR020937', '库赛湖', '可可西里', '青海', '文化打卡', '秋季', 6, 4, 763.00, '是', 5, '6月去的库赛湖，一个人出行。地点在可可西里，地铁到达方便，现场人不算多。这次玩了4天，人均花费约763元，拍照很出片。景点印象：库赛湖湖区附近是荒漠草原地带，湖面海拔约达4470米。整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 133);
INSERT INTO `travel_review` VALUES (20938, 'TR020938', '塔山阻击战纪念塔', '葫芦岛', '辽宁', '亲子出游', '秋季', 6, 1, 658.00, '是', 5, '6月去的塔山阻击战纪念塔，一个人出行。地点在葫芦岛，地铁到达方便，现场人不算多。这次玩了1天，人均花费约658元，历史文化气息浓。景点印象：纪念塔位塔身背面有碑文。详述了战斗经过和英雄事迹。葫芦岛市区以东12公里的连山区塔山乡塔山村东楼台山顶, 西南距市区9公里。\n烈士塔建于1963年10月，是为缅怀1948年辽沈战役塔山阻击战革命烈士而建立的。塔址是明朝天启年间的烽火台，群众称“…整体感受是超出预期，值得专门打卡。二刷意愿：是。', '2%', 52);
