INSERT INTO `travel_review` VALUES (20940, 'TR020940', '龙湾火山湖', '白山', '吉林', '城市漫游', '春季', 1, 5, 1012.00, '否', 5, '1月去的龙湾火山湖，和家人出行。地点在白山，打车比较省心，现场人流量适中。这次玩了5天，人均花费约1012元，历史文化气息浓。景点印象：有长白山“第二天地”之称的龙湾火山湖位于靖宇县城西20公里处，由火山喷发而成。湖面面积为92公顷，周围植被保存完好，自然景观独特，湖中有鱼类十几种，湖边建有养殖场，饲养山鸡、蛇、鹅等，并且建有游人接待场所，食、宿、游极为方便。龙湾火山…整体感受是超出预期，值得专门打卡。二刷意愿：否。', '0%', 100);
