INSERT INTO `travel_review` VALUES (20972, 'TR020972', '马湖风景名胜区', '凉山', '四川', '亲子出游', '秋季', 7, 2, 663.00, '是', 5, '7月去的马湖风景名胜区，和朋友出行。地点在凉山，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约663元，拍照很出片。景点印象：马湖风景名胜区位于凉山彝族自治州雷波县境内，景区总面积128平方公里。由秀丽的马湖、金沙江峡谷、原始密林等部分组成，是小凉山深处一颗耀眼的风景“明珠”。1993年被省人民政府批准为省级风景名胜区。\n马湖属高原大型天然深水湖泊，水域面积7.3…整体感受是超出预期，值得专门打卡。二刷意愿：是。', '1%', 45);
