INSERT INTO `travel_review` VALUES (20977, 'TR020977', '黎母山国家森林公园', '琼中', '海南', '深度游', '夏季', 3, 6, 1487.00, '否', 3, '3月去的黎母山国家森林公园，和家人出行。地点在琼中，公交换乘方便，现场高峰时段比较拥挤。这次玩了6天，人均花费约1487元，氛围感不错。景点印象：整体环境还算干净整体感受是中规中矩，别抱太高期待。二刷意愿：否。', '13%', 65);
INSERT INTO `travel_review` VALUES (20978, 'TR020978', '舒兰森林公园', '吉林市', '吉林', '拍照旅行', '冬季', 9, 2, 649.00, '否', 5, '9月去的舒兰森林公园，和朋友出行。地点在吉林市，公交换乘方便，现场游客较多。这次玩了2天，人均花费约649元，夜景表现很好。景点印象：舒兰市森林公园旅游园区为吉林市级旅游经济开发区，建于1997年5月，总占地面积120公顷，其中绿地面积占90％以上。森林公园东靠万寿山，南接南九山，西依红石山，北与北九山相望，故称九龙宝地。据文书记载，清乾隆年间，乾隆皇帝东巡吉林时，曾到过…整体感受是挺惊喜，很推荐。二刷意愿：否。', '0%', 81);
INSERT INTO `travel_review` VALUES (20979, 'TR020979', '海南铜鼓岭景区', '文昌', '海南', '亲子出游', '冬季', 10, 2, 259.00, '是', 5, '10月去的海南铜鼓岭景区，和朋友出行。地点在文昌，打车比较省心，现场人流量适中。这次玩了2天，人均花费约259元，历史文化气息浓。景点印象：享受攀登原始山峰的乐趣，还可俯瞰浩瀚海景。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '48%', 85);
