INSERT INTO `travel_review` VALUES (20981, 'TR020981', '明十三陵', '北京', '北京', '亲子出游', '冬季', 11, 1, 869.00, '否', 4, '11月去的明十三陵，情侣出行。地点在北京，打车比较省心，现场人流量适中。这次玩了1天，人均花费约869元，夜景表现很好。景点印象：规模庞大、保存完好的皇家陵园，了解古代帝王陵墓建筑必去。整体感受是还蛮满意，推荐来看看。二刷意愿：否。', '14%', 94);
INSERT INTO `travel_review` VALUES (20982, 'TR020982', '嘉陵江', '陇南', '甘肃', '深度游', '冬季', 9, 4, 1486.00, '是', 5, '9月去的嘉陵江，情侣出行。地点在陇南，打车比较省心，现场人流量适中。这次玩了4天，人均花费约1486元，历史文化气息浓。景点印象：“汉水南入嘉陵道而为嘉陵水”，江名由此而来，嘉陵江发源于秦岭南麓，流经陕、甘、川至重庆流入长江。沿江两岸奇峰壁立、怪石嶙峋、森林茂密、泉瀑众多、美不胜收。整体感受是特别满意，很推荐。二刷意愿：是。', '41%', 91);
INSERT INTO `travel_review` VALUES (20983, 'TR020983', '鹿回头风景区', '三亚', '海南', '亲子出游', '冬季', 10, 3, 732.00, '否', 2, '10月去的鹿回头风景区，和家人出行。地点在三亚，公交换乘方便，现场游客较多。这次玩了3天，人均花费约732元，氛围感不错。景点印象：登高展望三亚城区风光与海岸美景，也是观赏日出日落的制高点。整体感受是体验偏一般，建议谨慎前往。二刷意愿：否。', '20%', 45);
INSERT INTO `travel_review` VALUES (20984, 'TR020984', '玄妙观', '荆州', '湖北', '文化打卡', '夏季', 3, 5, 1019.00, '是', 5, '3月去的玄妙观，一个人出行。地点在荆州，地铁到达方便，现场人流量适中。这次玩了5天，人均花费约1019元，拍照很出片。景点印象：景点本身有一定特色整体感受是特别满意，很推荐。二刷意愿：是。', '6%', 74);
INSERT INTO `travel_review` VALUES (20985, 'TR020985', '博鳌鸳鸯岛', '琼海', '海南', '亲子出游', '春季', 1, 4, 984.00, '是', 5, '1月去的博鳌鸳鸯岛，和家人出行。地点在琼海，自驾停车需要提前规划，现场游客较多。这次玩了4天，人均花费约984元，夜景表现很好。景点印象：玉带滩位于万泉河入海口。说起江河入海口，人们自然会联想起长江、黄河入海口，或尼罗河、亚马逊河入海口。然而与众不同的是，万泉河入海口有条长达2．5公里的狭窄沙坝， 横亘在万泉河和南海之间，那就是玉带滩。玉带滩是一条自然形成的地形狭长的…整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 95);
