INSERT INTO `travel_review` VALUES (20991, 'TR020991', '额济纳神树', '阿拉善盟', '内蒙古', '文化打卡', '夏季', 5, 3, 1036.00, '是', 4, '5月去的额济纳神树，和朋友出行。地点在阿拉善盟，公交换乘方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约1036元，氛围感不错。景点印象：额济纳神树位于达来呼布镇北二十八公里，树高27米，直径约4米。三百年前土尔扈特人初来额济纳，胡杨林木密集，其中“神树”巍然耸立挺拔，枝叶繁茂。整体感受是整体不错，可以安排半天到一天。二刷意愿：是。', '8%', 52);
