INSERT INTO `travel_review` VALUES (20997, 'TR020997', '袁家界景区', '张家界', '湖南', '周末短途', '夏季', 4, 2, 405.00, '是', 4, '4月去的袁家界景区，和朋友出行。地点在张家界，打车比较省心，现场人不算多。这次玩了2天，人均花费约405元，拍照很出片。景点印象：《阿凡达》中“哈利路亚山”的取景地，群峰环抱，经常云雾缭绕。整体感受是体验挺好，推荐来看看。二刷意愿：是。', '42%', 47);
INSERT INTO `travel_review` VALUES (20998, 'TR020998', '淮罗村', '阜阳', '安徽', '文化打卡', '春季', 12, 7, 1537.00, '否', 4, '12月去的淮罗村，情侣出行。地点在阜阳，打车比较省心，现场高峰时段比较拥挤。这次玩了7天，人均花费约1537元，拍照很出片。景点印象：景点本身有一定特色整体感受是还蛮满意，可以安排半天到一天。二刷意愿：否。', '0%', 58);
INSERT INTO `travel_review` VALUES (20999, 'TR020999', '沂蒙山旅游区龟蒙景区', '临沂', '山东', '亲子出游', '冬季', 10, 4, 1087.00, '否', 5, '10月去的沂蒙山旅游区龟蒙景区，和家人出行。地点在临沂，公交换乘方便，现场游客较多。这次玩了4天，人均花费约1087元，拍照很出片。景点印象：登临山东第二高峰“龟蒙顶”赏群山秀色，漫步于北方最长的悬崖栈道，体验悬空行走的刺激。整体感受是特别满意，值得专门打卡。二刷意愿：否。', '20%', 69);
INSERT INTO `travel_review` VALUES (21000, 'TR021000', '玉书阁(高庙)', '鄂州', '湖北', '拍照旅行', '冬季', 10, 3, 974.00, '否', 5, '10月去的玉书阁(高庙)，和家人出行。地点在鄂州，自驾停车需要提前规划，现场人不算多。这次玩了3天，人均花费约974元，拍照很出片。景点印象：周边配套比较齐全整体感受是超出预期，很推荐。二刷意愿：否。', '0%', 96);
INSERT INTO `travel_review` VALUES (21001, 'TR021001', '喀拉库勒湖', '克孜勒苏柯尔克孜', '新疆', '深度游', '春季', 1, 2, 764.00, '是', 4, '1月去的喀拉库勒湖，和朋友出行。地点在克孜勒苏柯尔克孜，打车比较省心，现场高峰时段比较拥挤。这次玩了2天，人均花费约764元，夜景表现很好。景点印象：高原湖泊-----喀拉库勒湖距阿图什220公里，海拔3600百米，面积为10平方公里，水深30多米，因湖水深邃幽黯，故名“喀拉库勒”（柯尔克孜语意为黑湖）。湖东面矗立着“冰山之父”慕士塔格峰，西面雄踞逶迤不绝的萨尔阔勒山脉；湖的南面是一片草原，一…整体感受是体验挺好，推荐来看看。二刷意愿：是。', '80%', 53);
INSERT INTO `travel_review` VALUES (21002, 'TR021002', '青羊宫', '成都', '四川', '文化打卡', '夏季', 5, 4, 1420.00, '否', 3, '5月去的青羊宫，和家人出行。地点在成都，打车比较省心，现场游客较多。这次玩了4天，人均花费约1420元，历史文化气息浓。景点印象：成都现存最古老的道观，敬香祈福，感受玄妙的道家气息。整体感受是中规中矩，按需选择。二刷意愿：否。', '23%', 45);
INSERT INTO `travel_review` VALUES (21003, 'TR021003', '塔克尔穆库尔沙漠', '可克达拉', '新疆', '拍照旅行', '秋季', 7, 3, 862.00, '是', 5, '7月去的塔克尔穆库尔沙漠，和朋友出行。地点在可克达拉，地铁到达方便，现场人流量适中。这次玩了3天，人均花费约862元，夜景表现很好。景点印象：周边配套比较齐全整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '0%', 110);
INSERT INTO `travel_review` VALUES (21004, 'TR021004', '西大圈', '七台河', '黑龙江', '城市漫游', '夏季', 4, 5, 1435.00, '是', 5, '4月去的西大圈，和朋友出行。地点在七台河，公交换乘方便，现场人流量适中。这次玩了5天，人均花费约1435元，夜景表现很好。景点印象：西大圈森林公园风光旖旎，令观光者心旷神怡，流连忘返。公园内有极其丰富的自然景观，洪峡谷可供漂流，河水清澈见底，河道磐石错落、蜿蜒曲折，两岸树木高大茂盛，百鸟争鸣，百花争艳，景色秀美；卧龙峰可供攀登，峰顶是一座高43米、长350米的悬崖…整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 111);
INSERT INTO `travel_review` VALUES (21005, 'TR021005', '麻阳河', '铜仁', '贵州', '文化打卡', '春季', 1, 2, 326.00, '否', 4, '1月去的麻阳河，和家人出行。地点在铜仁，打车比较省心，现场人不算多。这次玩了2天，人均花费约326元，夜景表现很好。景点印象：麻阳河国家级自然保护区境内国家一级保护动物黑叶猴野外种群数量经中科院博士生导师丁伟一行年初科学考察论证,区内有黑叶猴76群736只。其数量之多,密度之大,居全国之冠。考察同时查明,区内还有脊椎动物266种,国家一、二级保护动物32种,其中二级保护…整体感受是体验挺好，可以安排半天到一天。二刷意愿：否。', '2%', 65);
INSERT INTO `travel_review` VALUES (21006, 'TR021006', '厦地村', '宁德', '福建', '拍照旅行', '夏季', 5, 2, 571.00, '否', 5, '5月去的厦地村，一个人出行。地点在宁德，公交换乘方便，现场游客较多。这次玩了2天，人均花费约571元，氛围感不错。景点印象：周边配套比较齐全整体感受是超出预期，很推荐。二刷意愿：否。', '0%', 116);
INSERT INTO `travel_review` VALUES (21007, 'TR021007', '南山特产', '邵阳', '湖南', '亲子出游', '春季', 2, 5, 1394.00, '否', 5, '2月去的南山特产，和家人出行。地点在邵阳，打车比较省心，现场高峰时段比较拥挤。这次玩了5天，人均花费约1394元，氛围感不错。景点印象：南山奶粉\n“南山”牌系列乳制品以“凉开水即溶，喝了不上火”蜚声全国，被誉为“南国净土里长出的绿色食品”，其中婴幼儿系列奶粉为“国家免检产品”。南山奶粉畅销全国近30个省、自治区、直辖市，成为全国奶粉行业十大畅销产品，在广大消费者的心…整体感受是特别满意，以后还会来。二刷意愿：否。', '0%', 54);
