INSERT INTO `travel_review` VALUES (21028, 'TR021028', '文庙大成殿', '沧州', '河北', '城市漫游', '冬季', 10, 3, 874.00, '否', 2, '10月去的文庙大成殿，一个人出行。地点在沧州，打车比较省心，现场人流量适中。这次玩了3天，人均花费约874元，历史文化气息浓。景点印象：文庙大成殿坐落在沧州运河区晓市街北侧市群艺馆内。大成殿原系孔庙主殿，东西18米，南北9米，正面五门，殿内立柱24根，出檐2米，顶为绿釉。建筑雄伟。始建于宋辽年间（约1120-1150），明初创修规制渐备，明清以来历经17次修建。1981年河北省拨款修…整体感受是体验偏一般，不建议高峰来。二刷意愿：否。', '0%', 55);
