INSERT INTO `travel_review` VALUES (21070, 'TR021070', '上堡古国', '邵阳', '湖南', '城市漫游', '夏季', 3, 3, 1283.00, '是', 4, '3月去的上堡古国，一个人出行。地点在邵阳，自驾停车需要提前规划，现场人流量适中。这次玩了3天，人均花费约1283元，历史文化气息浓。景点印象：上堡古国地处绥宁县黄桑坪苗族乡，南抵城步南山景区，西接通道万佛山景区，为明朝侗苗民族起义根据地.整体感受是还蛮满意，可以安排半天到一天。二刷意愿：是。', '0%', 72);
