INSERT INTO `travel_review` VALUES (21087, 'TR021087', '小兴安岭第一漂', '伊春', '黑龙江', '周末短途', '冬季', 11, 2, 729.00, '是', 5, '11月去的小兴安岭第一漂，和朋友出行。地点在伊春，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约729元，氛围感不错。景点印象：位于金山屯区境内的大丰河全长 80公里，平均宽度30米，水深1－1.5米，河水纯净，清澈见底，河床由细沙和鹅卵石组成，赤脚站在滩上如同按摩一般。这里水流湍急，乘上双人橡皮船顺流而下，颠簸旋转，乐趣无穷。这里是伊春最早开发漂流旅游项目的地区…整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 90);
