INSERT INTO `travel_review` VALUES (21089, 'TR021089', '庐山花径', '九江', '江西', '亲子出游', '秋季', 7, 1, 419.00, '是', 5, '7月去的庐山花径，和家人出行。地点在九江，自驾停车需要提前规划，现场游客较多。这次玩了1天，人均花费约419元，夜景表现很好。景点印象：相传为唐白居易咏《大林寺桃花》之处，繁花似锦，曲径通幽，风景如画。整体感受是特别满意，很推荐。二刷意愿：是。', '35%', 85);
INSERT INTO `travel_review` VALUES (21090, 'TR021090', '沙面', '广州', '广东', '城市漫游', '秋季', 7, 1, 455.00, '是', 5, '7月去的沙面，情侣出行。地点在广州，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约455元，拍照很出片。景点印象：众多欧陆风情的建筑，超级适合拍照的地方，也十分适合漫步其间。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '30%', 87);
INSERT INTO `travel_review` VALUES (21091, 'TR021091', '青铜峡108塔', '吴忠', '宁夏', '周末短途', '秋季', 6, 2, 889.00, '是', 5, '6月去的青铜峡108塔，和家人出行。地点在吴忠，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约889元，历史文化气息浓。景点印象：108座喇嘛佛塔，面对黄河，依山而建，在最高等俯视四方，豪迈之情油然而生。 按照当地人习俗，顺时针绕塔几圈，消除人生的108种烦恼。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '20%', 71);
INSERT INTO `travel_review` VALUES (21092, 'TR021092', '额济纳神树', '阿拉善盟', '内蒙古', '周末短途', '春季', 2, 4, 815.00, '是', 5, '2月去的额济纳神树，和家人出行。地点在阿拉善盟，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了4天，人均花费约815元，拍照很出片。景点印象：额济纳神树位于达来呼布镇北二十八公里，树高27米，直径约4米。三百年前土尔扈特人初来额济纳，胡杨林木密集，其中“神树”巍然耸立挺拔，枝叶繁茂。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '8%', 93);
