INSERT INTO `travel_review` VALUES (21109, 'TR021109', '万山寺', '齐齐哈尔', '黑龙江', '拍照旅行', '秋季', 7, 2, 546.00, '是', 5, '7月去的万山寺，和家人出行。地点在齐齐哈尔，公交换乘方便，现场人流量适中。这次玩了2天，人均花费约546元，夜景表现很好。景点印象：原名患灵古院，在齐齐哈尔市中心城区西北7公里明月岛上，1926年始建，有玉皇阁、白阳阁、三星阁和三清阁，是呈菱形布局的仿古建筑群，所有建筑雕梁画栋，金碧辉煌雄伟壮观。十几个尊雕像，形象生动，妙趣横生。寺院坐落在草木丛中，景色宜人，为市…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 101);
