INSERT INTO `travel_review` VALUES (21145, 'TR021145', '双台河口自然保护区', '盘锦', '辽宁', '城市漫游', '冬季', 11, 2, 654.00, '否', 3, '11月去的双台河口自然保护区，一个人出行。地点在盘锦，地铁到达方便，现场人流量适中。这次玩了2天，人均花费约654元，氛围感不错。景点印象：双台河口国家级自然保护区从标介于东经121度30分－122度00分，北纬40度45分-41度10分，总面积12.8万公顷。是目前世界上保存最好，面积最大，植被类型最完整的生态地块。作为自然保护区1985年始建，1988年国务院以国发30号文件确定为国家级自然保护…整体感受是还可以，别抱太高期待。二刷意愿：否。', '2%', 63);
