INSERT INTO `travel_review` VALUES (21208, 'TR021208', '白龙江', '甘南', '甘肃', '城市漫游', '春季', 1, 3, 615.00, '是', 5, '1月去的白龙江，和朋友出行。地点在甘南，打车比较省心，现场游客较多。这次玩了3天，人均花费约615元，历史文化气息浓。景点印象：白龙江激情漂流位于青藏高原东部，甘南藏族自治州南端的迭部县。西南同四川省若尔盖县、九寨沟县毗邻，加之气候环境宜人，乡风民情纯朴，是国内外游人梦幻中的世外桃园。\n白龙江是长江的重要一级支流。白龙江激情漂流起自迭部县城以东2公里的亚古桥…整体感受是挺惊喜，以后还会来。二刷意愿：是。', '1%', 91);
