INSERT INTO `travel_review` VALUES (21213, 'TR021213', '徐福村', '连云港', '江苏', '周末短途', '夏季', 4, 1, 359.00, '否', 5, '4月去的徐福村，和家人出行。地点在连云港，打车比较省心，现场人流量适中。这次玩了1天，人均花费约359元，氛围感不错。景点印象：金山乡的徐福村是秦代徐福的故里。今天徐福被日本人民尊之为司农耕之神，在日本新宫市有徐福公园，园内有徐福墓。\n据历史记载，秦朝当地有一位民间医生名叫徐福，善医药，会针灸，救治了当地及附近的许多乡亲，后来被秦始皇派遣，出海采仙药，一去…整体感受是挺惊喜，很推荐。二刷意愿：否。', '0%', 70);
