INSERT INTO `travel_review` VALUES (21239, 'TR021239', '长廊怀古', '盐城', '江苏', '周末短途', '春季', 2, 4, 1181.00, '是', 5, '2月去的长廊怀古，和家人出行。地点在盐城，公交换乘方便，现场游客较多。这次玩了4天，人均花费约1181元，历史文化气息浓。景点印象：长廊长20余米，东首“聚仙亭”，西列“观湖楼”，好象书法家写的“一”字，从聚仙亭起笔到观湖楼收笔，这“一”字横空出世，为恬淡雅静的大纵湖划上了一道风景线，置身其间，面对大湖，心旷神怡，遐想万千。整体感受是特别满意，很推荐。二刷意愿：是。', '0%', 84);
