INSERT INTO `travel_review` VALUES (21255, 'TR021255', '汉画像石', '吕梁', '山西', '文化打卡', '秋季', 7, 2, 733.00, '是', 5, '7月去的汉画像石，情侣出行。地点在吕梁，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约733元，拍照很出片。景点印象：汉画像石是汉代人雕刻在墓室、祠堂四壁的装饰石刻壁画。它在内容上包括神话传说、典章制度、风土人情等各个方面。在艺术形式上它上承战国绘画古朴之风，下开魏晋风度艺术之先河，奠定了中国画的基本法规和规范。汉画像石同商周的青铜器、南北朝的石…整体感受是超出预期，值得专门打卡。二刷意愿：是。', '11%', 104);
