INSERT INTO `travel_review` VALUES (21273, 'TR021273', '天子山风景区', '张家界', '湖南', '亲子出游', '夏季', 3, 1, 356.00, '是', 5, '3月去的天子山风景区，一个人出行。地点在张家界，公交换乘方便，现场游客较多。这次玩了1天，人均花费约356元，氛围感不错。景点印象：观赏云雾、月夜、霞日、冬雪等壮丽风光，以及造型各异的山峰。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '42%', 85);
INSERT INTO `travel_review` VALUES (21274, 'TR021274', '农团生态旅游景区', '自贡', '四川', '城市漫游', '冬季', 11, 2, 343.00, '是', 5, '11月去的农团生态旅游景区，和家人出行。地点在自贡，公交换乘方便，现场人流量适中。这次玩了2天，人均花费约343元，夜景表现很好。景点印象：农团生态旅游风景区地处自贡市区西南边缘，距自贡市区18公里，交通、通讯十分便利。风景区内均属深丘地貌，一般海拔400-480米之间，属岷江流域越溪河水系溜根河的发源地。乡内属大陆季风性气候，雨量充沛，无霜期长，湿润凉爽。多年平均气温17.1摄…整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 104);
