INSERT INTO `travel_review` VALUES (21276, 'TR021276', '仙海旅游度假区', '绵阳', '四川', '拍照旅行', '春季', 2, 2, 881.00, '是', 4, '2月去的仙海旅游度假区，和朋友出行。地点在绵阳，地铁到达方便，现场游客较多。这次玩了2天，人均花费约881元，夜景表现很好。景点印象：仙海风景区水质优良，湖面宽广，植被繁茂，设有环湖公路，是众多骑行爱好者的天堂。整体感受是整体不错，周末来刚好。二刷意愿：是。', '0%', 73);
INSERT INTO `travel_review` VALUES (21277, 'TR021277', '塔山阻击战纪念塔', '葫芦岛', '辽宁', '深度游', '冬季', 10, 2, 998.00, '否', 5, '10月去的塔山阻击战纪念塔，情侣出行。地点在葫芦岛，自驾停车需要提前规划，现场游客较多。这次玩了2天，人均花费约998元，氛围感不错。景点印象：纪念塔位塔身背面有碑文。详述了战斗经过和英雄事迹。葫芦岛市区以东12公里的连山区塔山乡塔山村东楼台山顶, 西南距市区9公里。\n烈士塔建于1963年10月，是为缅怀1948年辽沈战役塔山阻击战革命烈士而建立的。塔址是明朝天启年间的烽火台，群众称“…整体感受是特别满意，值得专门打卡。二刷意愿：否。', '2%', 77);
INSERT INTO `travel_review` VALUES (21278, 'TR021278', '莱芜莲花山', '莱芜', '山东', '文化打卡', '夏季', 3, 3, 1087.00, '否', 3, '3月去的莱芜莲花山，情侣出行。地点在莱芜，地铁到达方便，现场人不算多。这次玩了3天，人均花费约1087元，夜景表现很好。景点印象：莲花山因汉武帝访仙到此，在山顶建“迎仙宫”，故又称宫山。有三十六山头，七十二深谷之称。整体感受是中规中矩，避开高峰更好。二刷意愿：否。', '0%', 61);
