INSERT INTO `travel_review` VALUES (21302, 'TR021302', '凉都茶文化博览馆', '六盘水', '贵州', '拍照旅行', '夏季', 3, 6, 1742.00, '否', 2, '3月去的凉都茶文化博览馆，一个人出行。地点在六盘水，打车比较省心，现场人流量适中。这次玩了6天，人均花费约1742元，拍照很出片。景点印象：周边配套比较齐全整体感受是没达到预期，建议谨慎前往。二刷意愿：否。', '0%', 1);
INSERT INTO `travel_review` VALUES (21303, 'TR021303', '南吉祥寺', '晋城', '山西', '深度游', '夏季', 3, 1, 528.00, '否', 4, '3月去的南吉祥寺，和家人出行。地点在晋城，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约528元，夜景表现很好。景点印象：在山西陵川县城西20公里平川村。原宋家川，唐贞观年间奉敕建造，宋天圣年间迁此重建，金、元、明、清屡有修葺。寺宇规模完整，前后两进院落，有山门（即天王殿）、中殿、后殿、左右配殿及两厢廊庑。中殿历史最古，宋建，后殿金建元修，山着眼点是经…整体感受是整体不错，推荐来看看。二刷意愿：否。', '0%', 42);
