INSERT INTO `travel_review` VALUES (21365, 'TR021365', '古银州摩崖石刻', '榆林', '陕西', '拍照旅行', '冬季', 9, 1, 201.00, '是', 5, '9月去的古银州摩崖石刻，和朋友出行。地点在榆林，公交换乘方便，现场人不算多。这次玩了1天，人均花费约201元，历史文化气息浓。景点印象：无定河南岸石崖之上，有“古银州”三字的摩崖石刻，宽8.3米，高3米，每字宽1.5米，高1.8米，字距为1米。\n民国二十三年(1934年)时任县长严建章主持勒石，阴刻楷书，刚健雄宏，蔚为壮观。由本县清末进士高增爵邀请段祺瑞政府总统徐世昌所书。整体感受是超出预期，以后还会来。二刷意愿：是。', '1%', 74);
