INSERT INTO `travel_review` VALUES (21378, 'TR021378', '关门山国家森林公园', '本溪', '辽宁', '文化打卡', '秋季', 6, 3, 301.00, '是', 5, '6月去的关门山国家森林公园，和朋友出行。地点在本溪，公交换乘方便，现场人不算多。这次玩了3天，人均花费约301元，氛围感不错。景点印象：著名的秋季赏枫胜地，随处可以捕捉到迷人的镜头。 登临山巅俯瞰绝美山水，景致秀丽堪称“东北小黄山”。 行走于溪流边、在茂密的林间吐纳最纯净的空气。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 111);
