INSERT INTO `travel_review` VALUES (21415, 'TR021415', '沙湖生态旅游区', '石嘴山', '宁夏', '城市漫游', '冬季', 9, 3, 748.00, '是', 5, '9月去的沙湖生态旅游区，情侣出行。地点在石嘴山，公交换乘方便，现场人流量适中。这次玩了3天，人均花费约748元，历史文化气息浓。景点印象：一处融江南水乡与大漠风光为一体的生态旅游景区。整体感受是挺惊喜，很推荐。二刷意愿：是。', '22%', 98);
