INSERT INTO `travel_review` VALUES (21417, 'TR021417', '汉阳陵国家考古遗址公园', '咸阳', '陕西', '文化打卡', '夏季', 5, 2, 521.00, '是', 5, '5月去的汉阳陵国家考古遗址公园，一个人出行。地点在咸阳，公交换乘方便，现场人流量适中。这次玩了2天，人均花费约521元，氛围感不错。景点印象：汉景帝的陵墓，能观赏到上千件陶俑，种类丰富，有武士俑、宫女宦官俑、动物俑等。 通过玻璃通道和幕墙，近距离接触地下博物馆中的上万件文物，有种置身于墓中的现场感。 可以参加模拟的考古实践，亲身体验考古工作的神秘和成就感。整体感受是特别满意，以后还会来。二刷意愿：是。', '29%', 97);
