INSERT INTO `travel_review` VALUES (21419, 'TR021419', '窦圌山景区', '绵阳', '四川', '文化打卡', '春季', 2, 1, 638.00, '否', 5, '2月去的窦圌山景区，和家人出行。地点在绵阳，打车比较省心，现场人流量适中。这次玩了1天，人均花费约638元，氛围感不错。景点印象：一座座山峰拔地而起，雄伟挺拔，山顶有刺激的走钢丝表演。整体感受是超出预期，值得专门打卡。二刷意愿：否。', '0%', 87);
INSERT INTO `travel_review` VALUES (21420, 'TR021420', '新期火山奇观观光区', '黑河', '黑龙江', '拍照旅行', '冬季', 10, 4, 1094.00, '否', 5, '10月去的新期火山奇观观光区，和家人出行。地点在黑河，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了4天，人均花费约1094元，拍照很出片。景点印象：新期火山奇观观光区，是世界地质公园的核心，景观带总面积50平方公里，地质形成年代距今280多年，属最新期喷发的火山。这里保存了世界上新期火山地质的全貌，对研究地球物理发展史具有重要意义。区域内新期火山喷发裸露熔岩台地浩瀚无垠十分壮观，…整体感受是超出预期，以后还会来。二刷意愿：否。', '0%', 91);
INSERT INTO `travel_review` VALUES (21421, 'TR021421', '关林庙', '洛阳', '河南', '城市漫游', '夏季', 5, 1, 306.00, '是', 3, '5月去的关林庙，和朋友出行。地点在洛阳，地铁到达方便，现场人不算多。这次玩了1天，人均花费约306元，拍照很出片。景点印象：这里埋葬着关羽的首级，是祭拜关二爷的圣地。 可以观赏到慈禧太后和光绪皇帝的亲笔御匾。 庙内有一百多尊清代的石刻小狮子，生动活泼，栩栩如生。整体感受是中规中矩，按需选择。二刷意愿：是。', '26%', 60);
