INSERT INTO `travel_review` VALUES (21494, 'TR021494', '酒泉公园', '酒泉', '甘肃', '深度游', '秋季', 6, 1, 729.00, '否', 5, '6月去的酒泉公园，和朋友出行。地点在酒泉，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约729元，拍照很出片。景点印象：酒泉公园位于鼓楼东1.9公里处，占地面积27万平方米，是河西走廊唯一保存完整的一座汉式园林，迄今已有2000多年的历史。园内有泉有湖，有山有石，建有酒泉胜迹、月洞金珠、西汉胜境、祁连澄波、烟云深处、曲苑餐秀、花月双清、芦伴晚舟八大景区。古…整体感受是挺惊喜，以后还会来。二刷意愿：否。', '1%', 100);
