INSERT INTO `travel_review` VALUES (21496, 'TR021496', '东晋壁画墓', '朝阳', '辽宁', '拍照旅行', '冬季', 9, 3, 1229.00, '否', 2, '9月去的东晋壁画墓，和朋友出行。地点在朝阳，打车比较省心，现场高峰时段比较拥挤。这次玩了3天，人均花费约1229元，拍照很出片。景点印象：东晋壁画墓，位于十二台乡袁台子村，呈长方形，石筑墓室，墓内有百室和小龛，墓壁白灰面，并施彩绘画面，墓顶绘有鸟， 星云阁，墓壁绘墓主像，侍女图、射猎图、 秦食图、庖橱图、庭院图，极具考古价值。整体感受是没达到预期，不建议高峰来。二刷意愿：否。', '0%', 70);
INSERT INTO `travel_review` VALUES (21497, 'TR021497', '御河生态园', '大同', '山西', '文化打卡', '冬季', 9, 1, 430.00, '是', 4, '9月去的御河生态园，情侣出行。地点在大同，公交换乘方便，现场人不算多。这次玩了1天，人均花费约430元，氛围感不错。景点印象：御河生态园，南北长5.5公里，使昔日贫瘠、荒凉的御河两岸重现风光，一条河流能给予一座城市以灵魂，河畔生态园使城市物华得以体现，城市的审美和灵性凭河而含，籍园而展，御河蓄水，御园绽绿。整体感受是体验挺好，可以安排半天到一天。二刷意愿：是。', '1%', 73);
