INSERT INTO `travel_review` VALUES (21499, 'TR021499', '透龙山', '伊春', '黑龙江', '文化打卡', '春季', 1, 1, 80.00, '否', 4, '1月去的透龙山，和朋友出行。地点在伊春，打车比较省心，现场游客较多。这次玩了1天，人均花费约80元，夜景表现很好。景点印象：透龙山庄位于小兴安岭南麓的铁力市，距哈市240公里，乘火车、汽车只需2-3小时。这里有神秘的千年古洞，罕见的奇石怪树，秀丽的湖光山色，甘甜的清泉溪水，宝贵的原始湿地。是您休闲度假、旅游观光的理想去处。这里天常蓝、水常清、山常绿，有天然\"…整体感受是还蛮满意，周末来刚好。二刷意愿：否。', '0%', 52);
