INSERT INTO `travel_review` VALUES (21505, 'TR021505', '韩屯渡口', '吉林市', '吉林', '深度游', '夏季', 5, 1, 537.00, '否', 4, '5月去的韩屯渡口，和家人出行。地点在吉林市，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约537元，历史文化气息浓。景点印象：韩屯渡口位于吉林市龙潭区乌拉街满族镇雾凇岛对面的渡口附近,由于该渡口对面的雾凇岛上没有住宿，所以游客多在韩屯驻扎。从韩屯渡口摆渡到对岸就可以到雾凇岛。整体感受是整体不错，可以安排半天到一天。二刷意愿：否。', '5%', 53);
