INSERT INTO `travel_review` VALUES (21516, 'TR021516', '沈园', '绍兴', '浙江', '文化打卡', '冬季', 9, 1, 507.00, '否', 5, '9月去的沈园，情侣出行。地点在绍兴，自驾停车需要提前规划，现场游客较多。这次玩了1天，人均花费约507元，历史文化气息浓。景点印象：陆游与唐婉邂逅的浪漫园林，沈园之夜的绍兴堂会表演不容错过。整体感受是超出预期，很推荐。二刷意愿：否。', '51%', 74);
