INSERT INTO `travel_review` VALUES (21518, 'TR021518', '丁公遗址', '滨州', '山东', '文化打卡', '冬季', 11, 3, 1077.00, '否', 4, '11月去的丁公遗址，一个人出行。地点在滨州，自驾停车需要提前规划，现场人流量适中。这次玩了3天，人均花费约1077元，夜景表现很好。景点印象：丁公遗址位于邹平县苑城乡丁公村东，东西长约300米，南北宽约200米。在遗址中发现大量龙山文化及岳石文化遗物。所采集的文物标本除蚌器外，主要有石铲、磨制石斧等石器，还有骨簇、骨针及具有龙山文化典型特征的蛋壳陶片。陶器中有小陶罐，为泥质灰…整体感受是体验挺好，周末来刚好。二刷意愿：否。', '0%', 88);
INSERT INTO `travel_review` VALUES (21519, 'TR021519', '蓝波湾温泉水世界', '咸阳', '陕西', '城市漫游', '秋季', 7, 2, 415.00, '否', 5, '7月去的蓝波湾温泉水世界，一个人出行。地点在咸阳，打车比较省心，现场人流量适中。这次玩了2天，人均花费约415元，氛围感不错。景点印象：周边配套比较齐全整体感受是超出预期，以后还会来。二刷意愿：否。', '0%', 62);
