INSERT INTO `travel_review` VALUES (21521, 'TR021521', '雪帽山', '营口', '辽宁', '亲子出游', '秋季', 6, 4, 1068.00, '否', 4, '6月去的雪帽山，情侣出行。地点在营口，自驾停车需要提前规划，现场人流量适中。这次玩了4天，人均花费约1068元，氛围感不错。景点印象：雪帽山位于盖州市九寨镇，山峻林密，古朴原始，风光秀丽。山上土质肥沃，植被丰富，生长着几十个种类、近千亩的阔叶林，以及上百种中草药和山野菜。一年四季花开不断。\n       这里还生活着几十种野生动物，随时可见松鼠、山鸡跳跃山间，野鹿、狍子…整体感受是体验挺好，周末来刚好。二刷意愿：否。', '6%', 58);
