INSERT INTO `travel_review` VALUES (21527, 'TR021527', '二佛寺', '自贡', '四川', '拍照旅行', '秋季', 8, 2, 938.00, '否', 5, '8月去的二佛寺，和家人出行。地点在自贡，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约938元，夜景表现很好。景点印象：荣县二佛寺沿崖林立，造像上千尊，唐宋时名“浮图崖”，亦称千佛崖。因其众多佛像装金饰彩，阳光照射，金碧辉煌，故又称“金碧崖”。\n佛像为唐代开凿的弥勒坐佛，佛高5.8米，宽2.6米。左右龛壁上，刻有28小龛120尊造佛。整体感受是特别满意，以后还会来。二刷意愿：否。', '0%', 71);
