INSERT INTO `travel_review` VALUES (21529, 'TR021529', '梅州五指石', '梅州', '广东', '深度游', '春季', 1, 1, 314.00, '是', 5, '1月去的梅州五指石，和家人出行。地点在梅州，自驾停车需要提前规划，现场人不算多。这次玩了1天，人均花费约314元，氛围感不错。景点印象：五指石因景区内的五座石峰拔地而起、形同五指擎天而得名。景区内树木葱茏、奇石林立，景区内设有高空栈道，移步换景，雄伟壮观。整体感受是特别满意，以后还会来。二刷意愿：是。', '0%', 118);
