INSERT INTO `travel_review` VALUES (21534, 'TR021534', '哈达铺镇', '陇南', '甘肃', '文化打卡', '春季', 1, 3, 932.00, '否', 5, '1月去的哈达铺镇，一个人出行。地点在陇南，打车比较省心，现场游客较多。这次玩了3天，人均花费约932元，拍照很出片。景点印象：哈达铺镇被誉为中国工农红军长征途中的“加油站”，被列为我省红色旅游景点及爱国主义教育基地。\n1978年，哈达铺红军长征纪念馆建成，之后分别被命名为全国重点文物保护单位和全国爱国主义教育示范基地，也是全国30条红色旅游精品线路和全国100个红…整体感受是超出预期，很推荐。二刷意愿：否。', '13%', 88);
INSERT INTO `travel_review` VALUES (21535, 'TR021535', '东寨港红树林', '海口', '海南', '文化打卡', '秋季', 8, 5, 1170.00, '否', 5, '8月去的东寨港红树林，和家人出行。地点在海口，地铁到达方便，现场人不算多。这次玩了5天，人均花费约1170元，夜景表现很好。景点印象：在海上森林公园，乘船穿行在红树林间，感受红树林的顽强生命力。整体感受是超出预期，很推荐。二刷意愿：否。', '4%', 112);
