INSERT INTO `travel_review` VALUES (21548, 'TR021548', '上封寺', '衡阳', '湖南', '周末短途', '春季', 1, 1, 86.00, '是', 5, '1月去的上封寺，一个人出行。地点在衡阳，自驾停车需要提前规划，现场游客较多。这次玩了1天，人均花费约86元，氛围感不错。景点印象：距离衡山风景区内最佳看日出地点——“望日台”只有五分钟路程。 附近有不少的酒店和农家乐宾馆，住宿在这里便于次日凌晨观看日出。 寺内每日都有“早晚课”，住宿在附近聆听晨钟暮鼓，净化心灵。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '13%', 73);
