INSERT INTO `travel_review` VALUES (21551, 'TR021551', '龙湾火山湖', '白山', '吉林', '文化打卡', '春季', 2, 3, 681.00, '是', 5, '2月去的龙湾火山湖，情侣出行。地点在白山，公交换乘方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约681元，夜景表现很好。景点印象：有长白山“第二天地”之称的龙湾火山湖位于靖宇县城西20公里处，由火山喷发而成。湖面面积为92公顷，周围植被保存完好，自然景观独特，湖中有鱼类十几种，湖边建有养殖场，饲养山鸡、蛇、鹅等，并且建有游人接待场所，食、宿、游极为方便。龙湾火山…整体感受是特别满意，以后还会来。二刷意愿：是。', '0%', 75);
