INSERT INTO `travel_review` VALUES (21567, 'TR021567', '一线天景区', '南平', '福建', '文化打卡', '春季', 12, 1, 361.00, '是', 5, '12月去的一线天景区，和朋友出行。地点在南平，地铁到达方便，现场游客较多。这次玩了1天，人均花费约361元，历史文化气息浓。景点印象：探身洞中，仰观崖顶裂隙，可见天光一线奇景，最窄处只有30厘米宽。整体感受是特别满意，以后还会来。二刷意愿：是。', '40%', 79);
