INSERT INTO `travel_review` VALUES (21662, 'TR021662', '江心屿', '温州', '浙江', '深度游', '秋季', 6, 1, 809.00, '是', 5, '6月去的江心屿，情侣出行。地点在温州，公交换乘方便，现场人不算多。这次玩了1天，人均花费约809元，历史文化气息浓。景点印象：参观江心寺、东西塔、领馆旧址等建筑，感受温州不同时期的历史,欣赏瓯江夜景，十分惬意。整体感受是超出预期，很推荐。二刷意愿：是。', '10%', 123);
INSERT INTO `travel_review` VALUES (21663, 'TR021663', '乾明寺', '许昌', '河南', '城市漫游', '冬季', 9, 3, 1007.00, '否', 2, '9月去的乾明寺，情侣出行。地点在许昌，自驾停车需要提前规划，现场人不算多。这次玩了3天，人均花费约1007元，夜景表现很好。景点印象：主体建筑占地15万平方米，被誉为“中州第一丛林”。\n乾明寺位于襄城县南1？？5公里首山之阴，故又称背影寺。创建于唐武德年间。后唐清泰元年(934年)僧省念禅师开山重修，明清两代历经修缮，规模雄伟，主体建筑占地15万平方米，被誉为“中州第一丛…整体感受是体验偏一般，不建议高峰来。二刷意愿：否。', '0%', 52);
