INSERT INTO `travel_review` VALUES (21676, 'TR021676', '杰桑·索南达杰纪念碑', '可可西里', '青海', '文化打卡', '冬季', 11, 4, 1323.00, '是', 4, '11月去的杰桑·索南达杰纪念碑，一个人出行。地点在可可西里，公交换乘方便，现场游客较多。这次玩了4天，人均花费约1323元，夜景表现很好。景点印象：杰桑·索南达杰被誉为可可西里野生动物保护第一人，在可可西里无人区与偷猎者搏斗时丧生。为了纪念他，人们在可可西里保护区昆仑山口建立了纪念碑。整体感受是还蛮满意，推荐来看看。二刷意愿：是。', '12%', 83);
