INSERT INTO `travel_review` VALUES (21687, 'TR021687', '磁湖', '黄石', '湖北', '城市漫游', '夏季', 3, 4, 1051.00, '否', 3, '3月去的磁湖，和家人出行。地点在黄石，打车比较省心，现场人不算多。这次玩了4天，人均花费约1051元，拍照很出片。景点印象：磁湖位于黄石市区中心，面积10平方公里，大于著名的杭州西湖，居全国市区内湖之首，磁湖以湖边盛产磁铁而得名。苏轼谪居黄州（今市）时，其弟苏辙由广陵乘船来黄州，舟经黄石江面，突遇风阻，曾由胜阳港入湖避风，苏轼闻讯后，寄诗相迎，辙亦以诗章…整体感受是还可以，避开高峰更好。二刷意愿：否。', '15%', 10);
