INSERT INTO `travel_review` VALUES (21716, 'TR021716', '黎都公园', '长治', '山西', '亲子出游', '冬季', 9, 1, 360.00, '是', 5, '9月去的黎都公园，和朋友出行。地点在长治，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约360元，历史文化气息浓。景点印象：黎都-羊头岭，又叫黎侯岭，面积约6平方公里，岭上最高点海拔1047米，清光绪版《长治县志》记载：“黎侯岭，县西南三十里，黎泉出焉，有黎侯亭；诸山皆石，此独土山。”\n远古时期，华夏始祖炎帝率领其部落顺河东下，登上太行山，进入现在的长治县境…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 70);
