INSERT INTO `travel_review` VALUES (21722, 'TR021722', '松花江观光索道', '哈尔滨', '黑龙江', '城市漫游', '夏季', 3, 1, 267.00, '否', 4, '3月去的松花江观光索道，和家人出行。地点在哈尔滨，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约267元，氛围感不错。景点印象：乘索道横跨松花江，从空中俯瞰江两岸风光。整体感受是还蛮满意，周末来刚好。二刷意愿：否。', '1%', 62);
