INSERT INTO `travel_review` VALUES (21724, 'TR021724', '双溪', '自贡', '四川', '文化打卡', '春季', 1, 4, 219.00, '否', 5, '1月去的双溪，和家人出行。地点在自贡，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了4天，人均花费约219元，夜景表现很好。景点印象：双溪，即梧枫水与寿水河这双溪汇合之处，是一个风水绝佳之地，位于荣县城西约2公里的旭水河源头。早年，这里有“书阁”，就是古荣州的图书馆；有“双溪王氏石穴”，就是北宋黄山谷题字的“地仙洞”，还有南宋诗人－容州通判陆游最喜爱的梅树。正是…整体感受是挺惊喜，以后还会来。二刷意愿：否。', '0%', 60);
