INSERT INTO `travel_review` VALUES (21751, 'TR021751', '河南跑马岭地质公园', '新乡', '河南', '文化打卡', '夏季', 4, 1, 751.00, '否', 4, '4月去的河南跑马岭地质公园，情侣出行。地点在新乡，自驾停车需要提前规划，现场人流量适中。这次玩了1天，人均花费约751元，历史文化气息浓。景点印象：登上山头是一片风吹草低见牛羊的广袤草原，马儿奔驰，风景优美而惬意。整体感受是体验挺好，推荐来看看。二刷意愿：否。', '1%', 31);
INSERT INTO `travel_review` VALUES (21752, 'TR021752', '塔山旅游风景区', '烟台', '山东', '周末短途', '秋季', 6, 3, 951.00, '否', 4, '6月去的塔山旅游风景区，情侣出行。地点在烟台，打车比较省心，现场高峰时段比较拥挤。这次玩了3天，人均花费约951元，拍照很出片。景点印象：登上山顶的三和塔眺望城区，天晴时还能望到海上的崆峒岛。 即可登山赏景、进香祈福，又能体验山下的各种游乐项目。整体感受是体验挺好，周末来刚好。二刷意愿：否。', '0%', 37);
