INSERT INTO `travel_review` VALUES (21754, 'TR021754', '包公湖', '开封', '河南', '亲子出游', '冬季', 11, 1, 772.00, '否', 4, '11月去的包公湖，情侣出行。地点在开封，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约772元，历史文化气息浓。景点印象：四周建筑古色古香，湖水清澈，虽是中原美景，却有着江南的风采。整体感受是还蛮满意，周末来刚好。二刷意愿：否。', '3%', 54);
INSERT INTO `travel_review` VALUES (21755, 'TR021755', '西安碑林博物馆', '西安', '陕西', '深度游', '秋季', 7, 5, 1262.00, '是', 4, '7月去的西安碑林博物馆，和朋友出行。地点在西安，地铁到达方便，现场游客较多。这次玩了5天，人均花费约1262元，夜景表现很好。景点印象：书法爱好者的真爱，能欣赏到颜真卿、柳公权等书法名家的碑刻。整体感受是还蛮满意，周末来刚好。二刷意愿：是。', '26%', 43);
INSERT INTO `travel_review` VALUES (21756, 'TR021756', '野马饲养放生基地', '哈密', '新疆', '亲子出游', '冬季', 10, 2, 1027.00, '是', 5, '10月去的野马饲养放生基地，和朋友出行。地点在哈密，地铁到达方便，现场人流量适中。这次玩了2天，人均花费约1027元，氛围感不错。景点印象：浦氏野马的学名叫“普尔热瓦尔斯基马”，原来是新疆野马，因俄罗斯探险家普尔热瓦尔斯基1876年捕猎到欧洲就以他的名字命名。19世纪中后期由于探险家的掠杀和其它原因，新疆野马在自己的故乡消声遗迹了。全世界的存量也不足1000匹，是比大熊猫还要珍…整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 90);
