INSERT INTO `travel_review` VALUES (21759, 'TR021759', '猴岛公园', '陵水', '海南', '拍照旅行', '夏季', 4, 4, 1041.00, '是', 5, '4月去的猴岛公园，和家人出行。地点在陵水，公交换乘方便，现场游客较多。这次玩了4天，人均花费约1041元，拍照很出片。景点印象：坐索道俯瞰岛屿与水上鱼排风光，在岛上近距离观看猕猴的活动。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '38%', 97);
INSERT INTO `travel_review` VALUES (21760, 'TR021760', '三块石', '海南藏族自治州', '青海', '周末短途', '春季', 12, 5, 1285.00, '否', 5, '12月去的三块石，和朋友出行。地点在海南藏族自治州，自驾停车需要提前规划，现场人不算多。这次玩了5天，人均花费约1285元，氛围感不错。景点印象：三块石在湖的西南部，由密集在一起的白色石灰岩礁石组成，怪石峥嵘，远远望去，形似三块巨大的巨鼎屹立于波涛之中，水拍浪激，惊心动魄，现栖息于礁石上的鸟类数量已超过鸟岛。整体感受是超出预期，值得专门打卡。二刷意愿：否。', '2%', 71);
