INSERT INTO `travel_review` VALUES (21784, 'TR021784', '呼伦贝尔草甸草原', '呼伦贝尔', '内蒙古', '周末短途', '春季', 12, 1, 387.00, '否', 4, '12月去的呼伦贝尔草甸草原，和朋友出行。地点在呼伦贝尔，自驾停车需要提前规划，现场游客较多。这次玩了1天，人均花费约387元，拍照很出片。景点印象：浩瀚无垠的苍穹,苍茫广阔的原野,和煦的微风与成群的牛羊，在这里你可以暂时告别喧嚣的城市，享受大草原的宁静与深远。整体感受是体验挺好，周末来刚好。二刷意愿：否。', '0%', 39);
