INSERT INTO `travel_review` VALUES (21801, 'TR021801', '天生桥', '邵阳', '湖南', '拍照旅行', '冬季', 10, 1, 260.00, '是', 5, '10月去的天生桥，一个人出行。地点在邵阳，打车比较省心，现场人不算多。这次玩了1天，人均花费约260元，氛围感不错。景点印象：天生桥景区紧临广西，是莨山景区近年来新发现的最具特色的景区之一，区内山环水绕，群峰横列，赤壁对峙，万巷迷离，约有近50平方公里折大面积丹霞赤壁群景观，景观资源特色鲜明，个性突出，具有强劲的比较优势，是开发丹霞观光、生态旅游、休头娱乐…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 79);
