INSERT INTO `travel_review` VALUES (21809, 'TR021809', '黄仙洞', '荆门', '湖北', '拍照旅行', '冬季', 9, 1, 460.00, '是', 5, '9月去的黄仙洞，和朋友出行。地点在荆门，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约460元，夜景表现很好。景点印象：黄仙洞位于大洪山脉南麓，相传黄石公曾在此休憩，故得名黄仙洞。洞内拥有四个世界级景级景观：边石池大厅、钙膜片边坝、石将军溶蚀石牙、三拱门景观。尤其是边石池，气势恢弘，波澜壮阔，被誉为世界溶洞之一绝。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '20%', 121);
