INSERT INTO `travel_review` VALUES (21811, 'TR021811', '金兰山', '信阳', '河南', '文化打卡', '春季', 1, 3, 1206.00, '否', 5, '1月去的金兰山，一个人出行。地点在信阳，公交换乘方便，现场人流量适中。这次玩了3天，人均花费约1206元，拍照很出片。景点印象：金兰山国家森林公园，地处亚热带向暧温带过渡地带，是我国华东、华中、华北三大植物区系交汇处和我国动植物南迁北移的缓冲带，森林资源丰富，树木种类繁多。有森林面积3072公顷，森林覆盖率93.1%，植物种类2000多种，其中国家重点保护植物19种。有…整体感受是挺惊喜，以后还会来。二刷意愿：否。', '0%', 126);
INSERT INTO `travel_review` VALUES (21812, 'TR021812', '卦台山', '天水', '甘肃', '亲子出游', '夏季', 4, 1, 427.00, '是', 5, '4月去的卦台山，和家人出行。地点在天水，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约427元，氛围感不错。景点印象：整体环境还算干净整体感受是超出预期，值得专门打卡。二刷意愿：是。', '0%', 86);
