INSERT INTO `travel_review` VALUES (21814, 'TR021814', '泉州府文庙', '泉州', '福建', '城市漫游', '春季', 2, 3, 1196.00, '否', 3, '2月去的泉州府文庙，一个人出行。地点在泉州，地铁到达方便，现场人不算多。这次玩了3天，人均花费约1196元，氛围感不错。景点印象：泉州府文庙始建于唐开元末年，其后几经修缮，现已经是东南地区较大的文庙建筑群。整体感受是还可以，避开高峰更好。二刷意愿：否。', '12%', 83);
INSERT INTO `travel_review` VALUES (21815, 'TR021815', '麒麟山', '鸡西', '黑龙江', '周末短途', '冬季', 11, 3, 942.00, '是', 4, '11月去的麒麟山，和朋友出行。地点在鸡西，打车比较省心，现场高峰时段比较拥挤。这次玩了3天，人均花费约942元，氛围感不错。景点印象：麒麟山风景区位于黑龙江省鸡东县兴农镇西侧，距鸡西市中心约42公里，它的特点是自然景观秀丽迷人，人文景观别致新颖、山峰陡峭、湖水清幽，是一处不可多得的旅游胜地。\n风景区的大门楼高8米、宽20米，采用的是中华民族传统的建筑风格，金色琉璃瓦、…整体感受是还蛮满意，推荐来看看。二刷意愿：是。', '0%', 82);
