INSERT INTO `travel_review` VALUES (21829, 'TR021829', '卡若遗址', '昌都', '西藏', '深度游', '冬季', 10, 2, 546.00, '是', 3, '10月去的卡若遗址，一个人出行。地点在昌都，打车比较省心，现场人不算多。这次玩了2天，人均花费约546元，夜景表现很好。景点印象：卡诺遗址位于中国西南部西藏自治区的昌都县,是一处新石器时代晚期文化遗址，年代为距今4000～5000年。 卡若遗址发现于1978年，遗址总面积约1万平方米，是考古界公认的西藏三大原始文化遗址之一。整体感受是中规中矩，别抱太高期待。二刷意愿：是。', '1%', 36);
