INSERT INTO `travel_review` VALUES (21902, 'TR021902', '关门山国家森林公园', '本溪', '辽宁', '亲子出游', '冬季', 9, 2, 610.00, '否', 3, '9月去的关门山国家森林公园，一个人出行。地点在本溪，地铁到达方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约610元，历史文化气息浓。景点印象：著名的秋季赏枫胜地，随处可以捕捉到迷人的镜头。 登临山巅俯瞰绝美山水，景致秀丽堪称“东北小黄山”。 行走于溪流边、在茂密的林间吐纳最纯净的空气。整体感受是体验一般，按需选择。二刷意愿：否。', '0%', 71);
