INSERT INTO `travel_review` VALUES (21940, 'TR021940', '神龟山', '万宁', '海南', '深度游', '秋季', 6, 2, 794.00, '否', 4, '6月去的神龟山，一个人出行。地点在万宁，自驾停车需要提前规划，现场游客较多。这次玩了2天，人均花费约794元，历史文化气息浓。景点印象：位于兴隆华侨农场境内。三座山峰连成东西走向呈龟状山脉，主峰海拨高280余米，高低错落的山势，把龟的头部、身部、尾部勾画得形神兼备，栩栩如生，充分展示了大自然造物之伟大和神奇。山上建起\"神龟山楼阁\"和\"神龟山神庙\"两大景点，有清未民国初期…整体感受是还蛮满意，推荐来看看。二刷意愿：否。', '0%', 55);
