INSERT INTO `travel_review` VALUES (21948, 'TR021948', '昭苏草原', '伊犁', '新疆', '拍照旅行', '冬季', 10, 2, 80.00, '否', 4, '10月去的昭苏草原，和朋友出行。地点在伊犁，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约80元，拍照很出片。景点印象：草原广袤壮美，夏季还有万亩油菜花在雪山下开放，是拍照摄影的绝佳胜地。 草原上有神秘的远古石人、古老的格登碑和圣佑庙等古迹，可以前去探寻。整体感受是整体不错，推荐来看看。二刷意愿：否。', '8%', 52);
