INSERT INTO `travel_review` VALUES (21966, 'TR021966', '梧桐树王', '和田', '新疆', '深度游', '冬季', 9, 1, 698.00, '否', 4, '9月去的梧桐树王，和家人出行。地点在和田，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约698元，拍照很出片。景点印象：在墨玉县阿克萨拉依乡古勒巴格村境内，有一株极其古老的其那树，其那维吾尔语译为梧桐，即梧桐树。这株古梧桐树高约30米，主干胸径2.7米，主干胸围8.75米，树冠遮盖地面1.5亩。树龄经中科院植物研究所有关专家测定为1000年左右。\n阿克萨拉依乡古勒…整体感受是还蛮满意，推荐来看看。二刷意愿：否。', '4%', 54);
