INSERT INTO `travel_review` VALUES (22011, 'TR022011', '白坡山', '攀枝花', '四川', '城市漫游', '秋季', 6, 1, 142.00, '否', 3, '6月去的白坡山，和家人出行。地点在攀枝花，公交换乘方便，现场游客较多。这次玩了1天，人均花费约142元，历史文化气息浓。景点印象：米易普威的白坡山自然保护区，海拨1200-3400米，土壤气候、植被呈垂直分布。原始森林以云南松为主，根本问题无 数藤蔓纽结缠绕，古木森森，杜鹃争春，还有珍禽奇兽出没。\n攀枝花气候温暖，终年无雪，但普威是其中的例外，由于海拨较高，加之境内原…整体感受是中规中矩，按需选择。二刷意愿：否。', '3%', 59);
