INSERT INTO `travel_review` VALUES (22020, 'TR022020', '海马洲', '汕尾', '广东', '深度游', '春季', 2, 4, 1163.00, '否', 4, '2月去的海马洲，和朋友出行。地点在汕尾，地铁到达方便，现场游客较多。这次玩了4天，人均花费约1163元，历史文化气息浓。景点印象：海马洲地处东海经济开发试验区南端，系乌坎港临海南郊虎头山延伸出的小岛，俗称“虎舌”。该岛南临碣石湾，东靠虎头山，西北面隔海与陆地相望。岛长3000米，宽350～650米，总面积2平方公里。岛内地势平坦，沙滩平缓向大海延伸，沙滩洁净，海水清澈…整体感受是还蛮满意，可以安排半天到一天。二刷意愿：否。', '0%', 53);
