INSERT INTO `travel_review` VALUES (22029, 'TR022029', '牛头山国家森林公园', '金华', '浙江', '深度游', '冬季', 10, 1, 497.00, '否', 5, '10月去的牛头山国家森林公园，情侣出行。地点在金华，公交换乘方便，现场游客较多。这次玩了1天，人均花费约497元，历史文化气息浓。景点印象：走走横跨两座山头的金锁桥，长长的悬索桥惊险刺激。 冬天泡温泉，夏天玩漂流，滋味各不相同。整体感受是超出预期，很推荐。二刷意愿：否。', '2%', 100);
