INSERT INTO `travel_review` VALUES (22154, 'TR022154', '正北楼', '盐城', '江苏', '文化打卡', '夏季', 4, 4, 1186.00, '否', 2, '4月去的正北楼，和家人出行。地点在盐城，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了4天，人均花费约1186元，氛围感不错。景点印象：在盐城市盐城中学校园内。建于1931年。1940年，刘少奇、陈毅曾在此居住和工作过，并在此召开过华中总指挥部会议。1941年初，即为抗日军政大学第五分校校部。该校在此约二年时间，培养了3000多名军政于部。正北楼是一座砖木混合结构的两层楼房，平面…整体感受是没达到预期，不建议高峰来。二刷意愿：否。', '0%', 58);
