INSERT INTO `travel_review` VALUES (22165, 'TR022165', '翠岩山', '锦州', '辽宁', '周末短途', '冬季', 11, 2, 720.00, '是', 5, '11月去的翠岩山，情侣出行。地点在锦州，公交换乘方便，现场游客较多。这次玩了2天，人均花费约720元，氛围感不错。景点印象：翠岩山位于锦州市区西北17公里处，在平坦大地的尽头， 一组群峰拔地而起，石壁如刀峭，嵯岈嶙峋，陡峭秀丽，好似一个由大自然用鬼神神功特意制作的大盆景。翠岩山石呈褐绿色，夏秋之季，青苔密布，峰峦苍翠，景色如画。翠岩山原名嵯岈山，俗称丫巴…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 110);
