INSERT INTO `travel_review` VALUES (22212, 'TR022212', '九仙山风景区', '日照', '山东', '拍照旅行', '夏季', 3, 4, 1198.00, '是', 5, '3月去的九仙山风景区，情侣出行。地点在日照，打车比较省心，现场高峰时段比较拥挤。这次玩了4天，人均花费约1198元，历史文化气息浓。景点印象：石窟幽洞比比皆是，还有大量植被与花卉，是齐鲁最大的野生药库。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '3%', 83);
