INSERT INTO `travel_review` VALUES (22214, 'TR022214', '黄河石林国家地质公园', '白银', '甘肃', '亲子出游', '冬季', 9, 2, 452.00, '否', 3, '9月去的黄河石林国家地质公园，情侣出行。地点在白银，公交换乘方便，现场人不算多。这次玩了2天，人均花费约452元，氛围感不错。景点印象：观赏宏大高耸的壮观石林，在戈壁之上感受苍凉悲壮。 乘驴车、坐羊皮筏子、围着篝火听西北小调，体验原始淳朴的西北民俗。整体感受是体验一般，别抱太高期待。二刷意愿：否。', '62%', 79);
