INSERT INTO `travel_review` VALUES (22217, 'TR022217', '永州金洞', '永州', '湖南', '城市漫游', '秋季', 7, 2, 905.00, '是', 4, '7月去的永州金洞，和家人出行。地点在永州，公交换乘方便，现场游客较多。这次玩了2天，人均花费约905元，氛围感不错。景点印象：永州金洞位于金洞国家森林公园，有“流金的仙人洞”之称，距祁阳火车站66公里，永州火车站83公里，至衡昆高速公路（2003年建成通车）祁阳金洞接口处仅26公里，来金洞国家森林公园游览区观光旅游，欣赏旖旎的自然风光，聆听动人的瑶族民歌；参加惊险…整体感受是整体不错，推荐来看看。二刷意愿：是。', '0%', 52);
