INSERT INTO `travel_review` VALUES (22258, 'TR022258', '斗柄塔', '文昌', '海南', '文化打卡', '冬季', 10, 1, 366.00, '否', 3, '10月去的斗柄塔，和朋友出行。地点在文昌，地铁到达方便，现场人不算多。这次玩了1天，人均花费约366元，历史文化气息浓。景点印象：七星岭林密草茂，动植物资源丰富，野生动物有野猪、山鸡、野兔、山龟、坡马、日獭、狐狸、松鼠等几十种。野生经济植物有仁酸、山姜、山薯、白藤、牛牯大力等好几十种。斗柄塔矗立于七星岭主峰上尤如七星生柄，故得名斗柄塔。塔建于明朝天启五上（公…整体感受是中规中矩，别抱太高期待。二刷意愿：否。', '0%', 48);
