INSERT INTO `travel_review` VALUES (22262, 'TR022262', '岱海遗址群', '乌兰察布', '内蒙古', '拍照旅行', '夏季', 3, 7, 1854.00, '否', 3, '3月去的岱海遗址群，一个人出行。地点在乌兰察布，地铁到达方便，现场人不算多。这次玩了7天，人均花费约1854元，夜景表现很好。景点印象：岱海遗址群是新石器时代的文化遗址。该遗址由王墓山、老虎山、园子沟等三处典型遗址组成。\n墓山遗址分成上、中、下三区，总面积约17万平方米。已清理出半地穴式房址21座、灰坑15个，其年代为距今6000年至5000年左右。\n老虎山遗址是“老虎山文化”的…整体感受是体验一般，别抱太高期待。二刷意愿：否。', '2%', 35);
