INSERT INTO `travel_review` VALUES (22284, 'TR022284', '朱载育墓', '焦作', '河南', '城市漫游', '春季', 2, 2, 137.00, '是', 5, '2月去的朱载育墓，和朋友出行。地点在焦作，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约137元，夜景表现很好。景点印象：朱载育墓位于沁阳县东北15公里处的山王庄乡张坡村东九峰山下。北依太行，南瞰怀川，墓周流水潺潺，环境优雅。原有明代书法家王铎书写的神道碑，抗日战争时期被日军炸毁。墓上原有高大封土堆，墓面有神道，神道两侧有石像生等，\"文化大革命\"开始后，…整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 95);
