INSERT INTO `travel_review` VALUES (22287, 'TR022287', '龙潭', '达州', '四川', '亲子出游', '冬季', 10, 2, 513.00, '否', 5, '10月去的龙潭，和家人出行。地点在达州，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约513元，拍照很出片。景点印象：位于八台山东侧，从上崩口到下崩口河段长10km，上崩口的右侧支流抠壁子沟，发源于八台山的东北角，长约6km，沟谷两侧是原始森林。龙潭河景区风光秀丽幽雅，景物丰富多彩，融山景、峰景、谷景、河景、瀑景、洞景、生景以及村景于一体。\n从上崩口至下…整体感受是特别满意，很推荐。二刷意愿：否。', '0%', 80);
