INSERT INTO `travel_review` VALUES (22313, 'TR022313', '山前景区', '池州', '安徽', '深度游', '春季', 2, 2, 841.00, '是', 4, '2月去的山前景区，和朋友出行。地点在池州，公交换乘方便，现场人不算多。这次玩了2天，人均花费约841元，氛围感不错。景点印象：介于柯村景区与九华街景区之间，一天门、二天门、三天门将该景区串为一体，自然景观与寺庙建筑星罗棋布，有桃崖瀑布、织锦瀑布、伏龙桥、定心石、龙池瀑布、燕子洞、鹰嘴岩和二圣殿、一宿庵、大桥庵、甘露寺（九华山佛学院）、龙池庵等著名寺院。伫…整体感受是还蛮满意，周末来刚好。二刷意愿：是。', '1%', 65);
