INSERT INTO `travel_review` VALUES (22375, 'TR022375', '龙岗遗址', '商丘', '河南', '拍照旅行', '春季', 1, 2, 616.00, '是', 3, '1月去的龙岗遗址，一个人出行。地点在商丘，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约616元，氛围感不错。景点印象：位于睢县蓼堤乡周龙村北面，地势较高，南北长300米，东西宽200米，文物层度约2米。1978年试掘，上发现灰坑6个、残陶鬲、陶盆、陶罐等。下层为龙山文化层，发现灰坑6个、残陶窘1个和一些文化遗物。并采集到一些殷商时代的文化遗物和两片仰韶文化时期…整体感受是体验一般，别抱太高期待。二刷意愿：是。', '0%', 38);
