INSERT INTO `travel_review` VALUES (22380, 'TR022380', '古石龙', '邯郸', '河北', '城市漫游', '春季', 1, 2, 636.00, '是', 5, '1月去的古石龙，和朋友出行。地点在邯郸，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约636元，历史文化气息浓。景点印象：古石龙风景区位于河北省邯郸市西北10公里，309国道古石龙牌坊北行4公里，107国道黄粱梦西行7公里。属自然景观、历史遗址、休闲度假于一体的综合性旅游风景区。\n古石龙风景区占地面积60万平方米，属太行山脉、紫山东麓，北距赵王陵1公里。地势因降水…整体感受是特别满意，以后还会来。二刷意愿：是。', '0%', 108);
INSERT INTO `travel_review` VALUES (22381, 'TR022381', '九九归一', '琼海', '海南', '拍照旅行', '夏季', 5, 2, 296.00, '否', 4, '5月去的九九归一，一个人出行。地点在琼海，打车比较省心，现场游客较多。这次玩了2天，人均花费约296元，拍照很出片。景点印象：这个整体看上去状若莲花的景点名为：九九归一，古时数字中“九”是最大的数，古人说：“九九之数以合天道”。所谓“归一”即是教导警醒人们天、地、人本为一体。这九瓣比人高的莲花瓣儿以及花瓣儿上的观音像，象征着佛教所说的“九品莲台”。西方极…整体感受是还蛮满意，推荐来看看。二刷意愿：否。', '0%', 84);
