INSERT INTO `travel_review` VALUES (22431, 'TR022431', '辽宁省博物馆', '沈阳', '辽宁', '文化打卡', '冬季', 10, 3, 841.00, '是', 5, '10月去的辽宁省博物馆，和家人出行。地点在沈阳，公交换乘方便，现场人不算多。这次玩了3天，人均花费约841元，氛围感不错。景点印象：辽宁省博物馆成立于1949年，是新中国第一座博物馆。整体感受是超出预期，以后还会来。二刷意愿：是。', '11%', 87);
INSERT INTO `travel_review` VALUES (22432, 'TR022432', '董永故里', '孝感', '湖北', '周末短途', '夏季', 4, 2, 573.00, '否', 5, '4月去的董永故里，情侣出行。地点在孝感，地铁到达方便，现场人流量适中。这次玩了2天，人均花费约573元，拍照很出片。景点印象：在孝感市北郊。董永，文学故事人物。传为东汉千乘（今山东博兴）人。早年丧母。灵帝中平时（184-189），随父避兵，流落孝感，佃耕养父。父亡，无以葬，乃自卖为奴。其孝行感动仙女下凡，为其织锦偿债赎身，且与其结为夫妻。《灵芝篇》、《搜神记》…整体感受是超出预期，以后还会来。二刷意愿：否。', '0%', 65);
INSERT INTO `travel_review` VALUES (22433, 'TR022433', '铺前胜利老街', '文昌', '海南', '城市漫游', '夏季', 4, 3, 662.00, '是', 5, '4月去的铺前胜利老街，情侣出行。地点在文昌，打车比较省心，现场人流量适中。这次玩了3天，人均花费约662元，夜景表现很好。景点印象：走在这不足五百米的老街上，能感受到到当时繁华。现在很多老字号的手艺还在这条街上传承着。整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 97);
INSERT INTO `travel_review` VALUES (22434, 'TR022434', '卓尔山', '海北', '青海', '城市漫游', '冬季', 9, 4, 1343.00, '是', 3, '9月去的卓尔山，和家人出行。地点在海北，自驾停车需要提前规划，现场人流量适中。这次玩了4天，人均花费约1343元，夜景表现很好。景点印象：碧绿草原与火红地貌辉映，隔河观赏巍峨雪山，是摄影师们的最爱。整体感受是体验一般，按需选择。二刷意愿：是。', '28%', 50);
