INSERT INTO `travel_review` VALUES (22462, 'TR022462', '汉画像石', '吕梁', '山西', '周末短途', '夏季', 5, 7, 1776.00, '否', 5, '5月去的汉画像石，和家人出行。地点在吕梁，打车比较省心，现场高峰时段比较拥挤。这次玩了7天，人均花费约1776元，氛围感不错。景点印象：汉画像石是汉代人雕刻在墓室、祠堂四壁的装饰石刻壁画。它在内容上包括神话传说、典章制度、风土人情等各个方面。在艺术形式上它上承战国绘画古朴之风，下开魏晋风度艺术之先河，奠定了中国画的基本法规和规范。汉画像石同商周的青铜器、南北朝的石…整体感受是特别满意，值得专门打卡。二刷意愿：否。', '11%', 107);
