INSERT INTO `travel_review` VALUES (22499, 'TR022499', '富窝村', '云浮', '广东', '周末短途', '冬季', 9, 2, 462.00, '是', 5, '9月去的富窝村，一个人出行。地点在云浮，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约462元，历史文化气息浓。景点印象：富窝村位于云浮市郁南县都城镇西南面，距县城5公里，交通十分便利。该村在山上、山下、村前、屋后种植沙糖桔2250亩，和建城镇、平台镇的沙糖桔连成一片成为名符其实的百里果乡。富窝村村民生活宽裕，村庄错落有有致，布局合理，设施配套，户户建起…整体感受是超出预期，很推荐。二刷意愿：是。', '25%', 94);
