INSERT INTO `travel_review` VALUES (22617, 'TR022617', '阳日湾', '神农架', '湖北', '文化打卡', '夏季', 4, 1, 337.00, '否', 3, '4月去的阳日湾，情侣出行。地点在神农架，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约337元，历史文化气息浓。景点印象：阳日湾景区在神农架林区东大门，西距松柏镇24公里，海拔偏低，气温较高。以高山湖泊、河川幽谷、自然风光特写及田园观光为主题的漂流探险游览区。主要景致有：夹道河、武山湖等。整体感受是还可以，避开高峰更好。二刷意愿：否。', '0%', 51);
INSERT INTO `travel_review` VALUES (22618, 'TR022618', '锦江瀑布', '白山', '吉林', '深度游', '秋季', 6, 3, 1228.00, '是', 5, '6月去的锦江瀑布，和家人出行。地点在白山，地铁到达方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约1228元，拍照很出片。景点印象：锦江瀑布又叫梯河瀑布，是二级瀑布，两级落差共70米。巨大水流聚然从黑褐色的火山岩陡崖上跌落，激起白色的水雾。瀑布声如雷鸣，水花四溅，靠近瀑布，就能感到水雾缭绕，全身凉透的感觉。整体感受是特别满意，很推荐。二刷意愿：是。', '3%', 84);
