INSERT INTO `travel_review` VALUES (22644, 'TR022644', '长汀太平桥', '龙岩', '福建', '城市漫游', '夏季', 5, 2, 392.00, '否', 3, '5月去的长汀太平桥，一个人出行。地点在龙岩，公交换乘方便，现场游客较多。这次玩了2天，人均花费约392元，氛围感不错。景点印象：长汀太平桥是一座双廊桥，全长近百米，造型典雅、古朴，翘角飞檐，犹如双龙飞渡汀江之上。整体感受是体验一般，按需选择。二刷意愿：否。', '0%', 44);
INSERT INTO `travel_review` VALUES (22645, 'TR022645', '龙鹄山', '眉山', '四川', '周末短途', '春季', 2, 2, 715.00, '否', 4, '2月去的龙鹄山，一个人出行。地点在眉山，公交换乘方便，现场人流量适中。这次玩了2天，人均花费约715元，拍照很出片。景点印象：龙鹄山，距丹棱县城约3公里。唐代名\"龙鹤山\"，自南宋孝宗皇帝手书\"龙鹄山\"三字赐史学家李焘后更名。龙鹄山山势奇特，恰似一个巍巍巨人，端坐于环绕的群山之中，有人说它像莲台打坐的佛祖，左手拈决，右手抚膝，神态肃穆。据当地人说，足有48座\"磕头…整体感受是整体不错，可以安排半天到一天。二刷意愿：否。', '0%', 58);
