INSERT INTO `travel_review` VALUES (22647, 'TR022647', '圣仙洞', '娄底', '湖南', '城市漫游', '秋季', 7, 2, 880.00, '是', 5, '7月去的圣仙洞，和朋友出行。地点在娄底，自驾停车需要提前规划，现场人流量适中。这次玩了2天，人均花费约880元，夜景表现很好。景点印象：圣仙洞位于市郊尖子山白石岩腰。此洞穿通整个尖子山内腹，有洞口通向山顶。洞内的景观有正宫殿、观音殿、水晶殿、万家灶、千层塔、大象厅、玉兰园、瀑布岩、葫芦台、阳河口、神龟潭等大小厅堂14个，还有隐龙宫、舍身岩、南天门、北天门、银河口、地…整体感受是特别满意，很推荐。二刷意愿：是。', '0%', 52);
