INSERT INTO `travel_review` VALUES (22651, 'TR022651', '封阳古城', '贺州', '广西', '深度游', '春季', 2, 2, 196.00, '否', 3, '2月去的封阳古城，和家人出行。地点在贺州，地铁到达方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约196元，拍照很出片。景点印象：前111年，汉武帝在贺江的下游与临贺县同时置封阳县，宋开宝4年（971年）并入临贺县，封阳设县置1082年。封阳县古城设在今铺门镇河东村离渡船码头北去约600米的高台地上，这里历史上又称高寨古城。板筑的城垣残墙至今还在，基脚全用石砌。城内西侧有…整体感受是还可以，避开高峰更好。二刷意愿：否。', '5%', 35);
