INSERT INTO `travel_review` VALUES (22656, 'TR022656', '连滩古建文化景区', '云浮', '广东', '城市漫游', '夏季', 4, 2, 571.00, '否', 5, '4月去的连滩古建文化景区，和朋友出行。地点在云浮，自驾停车需要提前规划，现场人流量适中。这次玩了2天，人均花费约571元，历史文化气息浓。景点印象：位于云浮市郁南县连滩镇西坝、思和等村，省道德珠线直达，距云浮市区105公里。是文物旅游景点和游览胜地。\n光二大屋建于清朝嘉庆年间，距今已有200多年历史，占地面积10亩，建筑面积8亩。该屋呈四方形，全部青砖灰瓦，屋脊上为飞檐灰塑，四周是又…整体感受是特别满意，很推荐。二刷意愿：否。', '25%', 88);
