INSERT INTO `travel_review` VALUES (22673, 'TR022673', '青竹农家乐园', '阳江', '广东', '城市漫游', '夏季', 5, 4, 1324.00, '否', 3, '5月去的青竹农家乐园，和家人出行。地点在阳江，打车比较省心，现场人流量适中。这次玩了4天，人均花费约1324元，历史文化气息浓。景点印象：青竹农家乐园位于城郊头堡村，这里山青水秀，环境洁静如人。在头堡村内的青竹农家乐园已成为城市人休闲、娱乐和品尝农家菜的 最佳去处。这里的农民纯朴和热情好客，村内有原始古朴的民居，有富有特色的农家菜肴，有风景优美的河塘水景，有连片绿油…整体感受是体验一般，别抱太高期待。二刷意愿：否。', '0%', 68);
