INSERT INTO `travel_review` VALUES (22688, 'TR022688', '山西黄河壶口瀑布旅游区', '临汾', '山西', '亲子出游', '冬季', 10, 3, 876.00, '否', 4, '10月去的山西黄河壶口瀑布旅游区，和朋友出行。地点在临汾，公交换乘方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约876元，夜景表现很好。景点印象：世界上少见的黄色瀑布，滚滚黄河水奔腾呼啸而下，气势磅礴。整体感受是整体不错，周末来刚好。二刷意愿：否。', '79%', 83);
