INSERT INTO `travel_review` VALUES (22690, 'TR022690', '康益泉温泉', '廊坊', '河北', '拍照旅行', '秋季', 8, 1, 268.00, '是', 5, '8月去的康益泉温泉，和朋友出行。地点在廊坊，公交换乘方便，现场人流量适中。这次玩了1天，人均花费约268元，氛围感不错。景点印象：位于固安县牛驼镇南，106国道西侧，距北京70公里。独特的大型露天温泉浴池，水性温热而富含多种元素，浴之可温经通络、畅达气血，祛寒舒筋，消除疲劳，强身健体，疗效独特，常浴可使肌肤润滑光亮。室外桑拿室、康乐中心等设施相配套，能使步入康益…整体感受是特别满意，以后还会来。二刷意愿：是。', '50%', 109);
