INSERT INTO `travel_review` VALUES (22701, 'TR022701', '天门山山门', '张家界', '湖南', '深度游', '秋季', 7, 2, 513.00, '是', 4, '7月去的天门山山门，和家人出行。地点在张家界，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约513元，历史文化气息浓。景点印象：天门山国家森林公园山门位于张家界市永定区双峡村，距市区天门山索道下站8公里，山门入口处悬挂有金庸先生亲笔题词“天门仙山”，山门内有设有《天门狐仙》演出剧场。整体感受是整体不错，周末来刚好。二刷意愿：是。', '0%', 63);
INSERT INTO `travel_review` VALUES (22702, 'TR022702', '九皇山', '绵阳', '四川', '深度游', '冬季', 9, 1, 587.00, '否', 5, '9月去的九皇山，和朋友出行。地点在绵阳，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约587元，氛围感不错。景点印象：九皇山景区内可观赏羌家碉楼、白石贡奉，在悠悠羌笛声中感受几千年的羌族文化。整体感受是特别满意，很推荐。二刷意愿：否。', '0%', 51);
