INSERT INTO `travel_review` VALUES (22704, 'TR022704', '雪峰寺', '莆田', '福建', '周末短途', '夏季', 3, 2, 289.00, '否', 5, '3月去的雪峰寺，和家人出行。地点在莆田，地铁到达方便，现场人流量适中。这次玩了2天，人均花费约289元，氛围感不错。景点印象：又名崇圣寺，全名雪峰崇圣禅寺,位于闽侯县西北雪峰凤凰山南麓。唐咸通十一年（870）建,现存殿宇多为光绪年间重修。寺内主要建筑是山门、法堂、大雄宝殿、斋堂。大雄宝殿内有来自缅甸的三世如来玉佛。十八罗汉姿态各异，栩栩如生。山门外有古树四株…整体感受是挺惊喜，很推荐。二刷意愿：否。', '0%', 41);
