INSERT INTO `travel_review` VALUES (22725, 'TR022725', '李时珍纪念馆', '黄冈', '湖北', '周末短途', '秋季', 7, 5, 1285.00, '是', 5, '7月去的李时珍纪念馆，和朋友出行。地点在黄冈，打车比较省心，现场高峰时段比较拥挤。这次玩了5天，人均花费约1285元，历史文化气息浓。景点印象：李时珍（1518-1593），是我国明代著名的医学家、药物学家，为纪念对人类作出伟大贡献的这位科学巨人，在湖北省蕲春县蕲州镇李时珍墓所在地竹林湖村建立了李时珍纪念馆。整个纪念馆占地面积50000平方米，由本草碑廊、纪念展览、药物馆、百草药园、墓…整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 76);
