INSERT INTO `travel_review` VALUES (22750, 'TR022750', '文庙', '运城', '山西', '周末短途', '夏季', 5, 1, 570.00, '否', 5, '5月去的文庙，和家人出行。地点在运城，自驾停车需要提前规划，现场游客较多。这次玩了1天，人均花费约570元，氛围感不错。景点印象：位于县城东北隅，创建年代失考，2002年修复后向游人开放，中轴线上依次是：下马碑→大门→照壁→泮池→棂星门→大成门→东西廊房→御路石→大成殿。 大成殿现存为明代遗构，重檐歇山屋顶，四周有回廊，面宽七间，殿宇巍峨，气势宏伟，素有“三晋文…整体感受是超出预期，以后还会来。二刷意愿：否。', '2%', 104);
INSERT INTO `travel_review` VALUES (22751, 'TR022751', '黑龙洞', '邯郸', '河北', '文化打卡', '秋季', 8, 4, 1045.00, '是', 5, '8月去的黑龙洞，一个人出行。地点在邯郸，打车比较省心，现场高峰时段比较拥挤。这次玩了4天，人均花费约1045元，氛围感不错。景点印象：又名龙洞珠泉，在河北邯郸市峰峰矿区滏阳河边，石洞深遂，俗传有黑龙潜藏，前人诗有“骊龙出洞去，洞深不可测”之句。 洞上有黑龙庙，依山而筑。据碑文记载，始建于唐代，山门之内有大殿及配房等。大殿原供龙神，洞下深潭，其色黛绿，清泉从岩缝喷…整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 65);
