INSERT INTO `travel_review` VALUES (22781, 'TR022781', '梅州五指石', '梅州', '广东', '文化打卡', '秋季', 7, 1, 760.00, '是', 3, '7月去的梅州五指石，和家人出行。地点在梅州，打车比较省心，现场人流量适中。这次玩了1天，人均花费约760元，拍照很出片。景点印象：五指石因景区内的五座石峰拔地而起、形同五指擎天而得名。景区内树木葱茏、奇石林立，景区内设有高空栈道，移步换景，雄伟壮观。整体感受是中规中矩，别抱太高期待。二刷意愿：是。', '0%', 67);
