INSERT INTO `travel_review` VALUES (22813, 'TR022813', '义井遗址', '焦作', '河南', '周末短途', '冬季', 11, 4, 1215.00, '是', 5, '11月去的义井遗址，和家人出行。地点在焦作，公交换乘方便，现场游客较多。这次玩了4天，人均花费约1215元，氛围感不错。景点印象：义井遗址位于孟县城西5公里处义井村村西的曹马沟内。遗址南北长700余米，东西宽450米，总面积约31.5万平方米，文化层厚约3-5米。经过多次考察，采集到的石器有石刀、石铲等，陶器有豆、瓮、澄滤器、甑、大口尊等，以灰陶居多，也发现有少量黑陶。纹…整体感受是超出预期，值得专门打卡。二刷意愿：是。', '0%', 83);
