INSERT INTO `travel_review` VALUES (22890, 'TR022890', '洞沟古墓群', '通化', '吉林', '城市漫游', '春季', 1, 4, 1054.00, '是', 3, '1月去的洞沟古墓群，情侣出行。地点在通化，地铁到达方便，现场高峰时段比较拥挤。这次玩了4天，人均花费约1054元，历史文化气息浓。景点印象：古墓壁画均藏于集安的洞沟古墓群中，是土墓代替了石墓后，绘于墓室土壁上的精美壁画，是研究公元5世纪至6世纪，高句丽历史文化的珍贵实物资料。\n公元4世纪晚期的墓室壁画，也就是墓室的早期壁画内容主要以描绘社会风俗习惯为主，较有名的有反映力士…整体感受是中规中矩，别抱太高期待。二刷意愿：是。', '20%', 72);
