INSERT INTO `travel_review` VALUES (22892, 'TR022892', '中流砥柱', '三门峡', '河南', '城市漫游', '冬季', 11, 4, 1296.00, '是', 5, '11月去的中流砥柱，一个人出行。地点在三门峡，地铁到达方便，现场人流量适中。这次玩了4天，人均花费约1296元，拍照很出片。景点印象：中流砥柱位于三门峡大坝下方的激流之中。黄河上的艄公又叫它\"朝我来\"，距市区约30公里。冬天水浅的时候，它露出水面两丈多；洪水季节，它只露出一个尖顶，看上去好像马上就被洪水吞没，惊险万分。千百年来，无论狂风暴雨的侵袭，还是惊涛骇浪的冲刷…整体感受是超出预期，以后还会来。二刷意愿：是。', '20%', 63);
