INSERT INTO `travel_review` VALUES (22905, 'TR022905', '当阳峪瓷窑遗址', '焦作', '河南', '城市漫游', '夏季', 5, 1, 153.00, '是', 5, '5月去的当阳峪瓷窑遗址，情侣出行。地点在焦作，地铁到达方便，现场游客较多。这次玩了1天，人均花费约153元，夜景表现很好。景点印象：当阳峪瓷窑遗址位于修武县西村乡当阳峪村。遗址东西长约2000米，南北宽约1000米。遗址上尚存有北宋崇宁四年（1105年）雕刻的《德应侯百灵翁之庙记》碑刻一块，上载有：\"世利瓷器，埏埴者百余家，资养者万余口\"，可见当时规模之大。该窑传世产品以剔…整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 83);
