INSERT INTO `travel_review` VALUES (22914, 'TR022914', '西大圈', '七台河', '黑龙江', '周末短途', '秋季', 6, 3, 740.00, '否', 5, '6月去的西大圈，情侣出行。地点在七台河，打车比较省心，现场人不算多。这次玩了3天，人均花费约740元，拍照很出片。景点印象：西大圈森林公园风光旖旎，令观光者心旷神怡，流连忘返。公园内有极其丰富的自然景观，洪峡谷可供漂流，河水清澈见底，河道磐石错落、蜿蜒曲折，两岸树木高大茂盛，百鸟争鸣，百花争艳，景色秀美；卧龙峰可供攀登，峰顶是一座高43米、长350米的悬崖…整体感受是挺惊喜，以后还会来。二刷意愿：否。', '0%', 120);
