INSERT INTO `travel_review` VALUES (22930, 'TR022930', '汉长城遗址', '酒泉', '甘肃', '拍照旅行', '夏季', 5, 2, 674.00, '否', 3, '5月去的汉长城遗址，一个人出行。地点在酒泉，地铁到达方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约674元，历史文化气息浓。景点印象：汉长城是我国目前玉门关西面党谷隧一带汉代长城保留最完整的一段。整体感受是还可以，别抱太高期待。二刷意愿：否。', '28%', 44);
INSERT INTO `travel_review` VALUES (22931, 'TR022931', '杨家城', '天水', '甘肃', '城市漫游', '秋季', 7, 2, 677.00, '否', 5, '7月去的杨家城，一个人出行。地点在天水，地铁到达方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约677元，夜景表现很好。景点印象：该城始建于唐天宝年间（公元742-756）。五代至宋，州刺史杨宏信，长子杨重勋（重训）和孙杨光，世守麟州；次子杨业和孙杨延昭，都是宋代名将，北拒契丹，称雄一方。世人怀着对捍边英雄的崇敬心情，改呼此城为杨家城。城东南约70米处，原有松树3株，…整体感受是超出预期，值得专门打卡。二刷意愿：否。', '0%', 58);
