INSERT INTO `travel_review` VALUES (22951, 'TR022951', '醴泉寺', '滨州', '山东', '城市漫游', '冬季', 11, 2, 771.00, '是', 5, '11月去的醴泉寺，和家人出行。地点在滨州，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约771元，氛围感不错。景点印象：醴泉寺始建于南北朝时期，后圮。唐中宗时，寺僧仁万重建寺院，时东山有一泉涌出，中宗赐名“醴泉”，醴泉寺即由此得名。\n醴泉寺建于群山环抱之中，坐南面北。大门两侧蹲踞一对石狮，迎门为文昌阁，阁上有殿，塑有文昌帝君神像。殿西有一古钟，径口2…整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '0%', 60);
