INSERT INTO `travel_review` VALUES (22972, 'TR022972', '鹤岗小兴安岭林区', '鹤岗', '黑龙江', '深度游', '秋季', 7, 2, 1078.00, '否', 3, '7月去的鹤岗小兴安岭林区，情侣出行。地点在鹤岗，公交换乘方便，现场人不算多。这次玩了2天，人均花费约1078元，拍照很出片。景点印象：鹤岗与萝北县的西部均为小兴安岭的林区，共有三块面积较大的原始森林保护区，其中面积最大是位于鹤岗林业局联营红松母树保护区。这里古树参天、松涛滚滚。市区西部的金顶山原始森林保护区最长的树龄达到千年，沐浴在原始森林中，才能真正感受回归大…整体感受是还可以，避开高峰更好。二刷意愿：否。', '0%', 29);
