INSERT INTO `travel_review` VALUES (22974, 'TR022974', '梅州千佛塔', '梅州', '广东', '城市漫游', '冬季', 9, 3, 759.00, '是', 5, '9月去的梅州千佛塔，和家人出行。地点在梅州，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了3天，人均花费约759元，拍照很出片。景点印象：千佛宝塔的塔中上下共三干尊佛，构成塔中有塔，塔上有塔，铁佛、玉佛、金佛共容一塔的特色，为梅州一大艺术杰作，是东南胜境之奇观。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '35%', 108);
