INSERT INTO `travel_review` VALUES (22986, 'TR022986', '万岁山', '开封', '河南', '亲子出游', '夏季', 3, 3, 1254.00, '是', 4, '3月去的万岁山，和朋友出行。地点在开封，公交换乘方便，现场游客较多。这次玩了3天，人均花费约1254元，氛围感不错。景点印象：万岁山藏自然山水美与人工美于一体，括天下之绝，含古今之胜，集我国古代南北园林建筑艺术之大成，荟萃华夏名山大川雄伟、险峻、奇秀、幽美、畅旷诸特色，成为全国山水奇景的一个缩影，堪称世界一绝。整体感受是还蛮满意，推荐来看看。二刷意愿：是。', '1%', 65);
