INSERT INTO `travel_review` VALUES (23009, 'TR023009', '山口湖', '黑河', '黑龙江', '拍照旅行', '夏季', 5, 4, 752.00, '否', 5, '5月去的山口湖，情侣出行。地点在黑河，自驾停车需要提前规划，现场游客较多。这次玩了4天，人均花费约752元，拍照很出片。景点印象：山口湖风景区位于五大连池市东50公里处，与世界地质公园--五大连池风景名胜区相毗邻。山口湖风景区自然生态条件优越，森林植被、野生植被、各种珍禽益兽栖息于此，84平方公里壮阔的水面并辅之以两岸青山、绿树、怪石及大坝、山口湖、岛屿等六大景区…整体感受是挺惊喜，很推荐。二刷意愿：否。', '0%', 102);
