INSERT INTO `travel_review` VALUES (23014, 'TR023014', '东圳水库', '莆田', '福建', '城市漫游', '冬季', 11, 4, 889.00, '否', 5, '11月去的东圳水库，情侣出行。地点在莆田，打车比较省心，现场高峰时段比较拥挤。这次玩了4天，人均花费约889元，氛围感不错。景点印象：位于市区西北8公里许的莆田县常太乡东圳尾村，是福建大型水库之一，具有灌溉、防洪、发电、航运、养殖、游览等作用。水库拦河大坝长360米，高58米，顶宽8米，象一座巨大的屏障，横亘在天马、地龙两山峡谷之间，拦住了自仙游九鲤湖奔流而下的溪水，…整体感受是特别满意，很推荐。二刷意愿：否。', '5%', 54);
