INSERT INTO `travel_review` VALUES (23028, 'TR023028', '史可法衣冠墓', '六安', '安徽', '城市漫游', '春季', 12, 1, 441.00, '否', 5, '12月去的史可法衣冠墓，和朋友出行。地点在六安，自驾停车需要提前规划，现场游客较多。这次玩了1天，人均花费约441元，氛围感不错。景点印象：明崇须十年七月至十二年夏（1637一1639），史可法任右金都御史，巡抚安庆、庐州、太平、池州四府及河南、湖广、江西邻近诸州、县，驻节六安州，与当时世居六安东乡的史姓有交往，追溯先祖原是同根，遂将可法分支归入六安史姓族谱系。史可法壮烈殉国…整体感受是超出预期，以后还会来。二刷意愿：否。', '0%', 102);
