INSERT INTO `travel_review` VALUES (23031, 'TR023031', '景德镇民窑博物馆', '景德镇', '江西', '拍照旅行', '春季', 2, 4, 1294.00, '否', 5, '2月去的景德镇民窑博物馆，一个人出行。地点在景德镇，公交换乘方便，现场人不算多。这次玩了4天，人均花费约1294元，氛围感不错。景点印象：丰富的文化遗存反映了七百年间陶瓷工艺史上重大变革和集中国古代制瓷历史之大成的过程。整体感受是特别满意，很推荐。二刷意愿：否。', '5%', 54);
