INSERT INTO `travel_review` VALUES (23077, 'TR023077', '日照文山茶博园', '日照', '山东', '文化打卡', '夏季', 4, 6, 1311.00, '是', 5, '4月去的日照文山茶博园，一个人出行。地点在日照，地铁到达方便，现场游客较多。这次玩了6天，人均花费约1311元，拍照很出片。景点印象：2009年，文山凤眉茶业斥资2000万元建成日照文山茶博园，公司位于东港区山东路西首。日照文山茶博园集自然景观、绿茶生态自采游、茶文化体验、民间茶艺表演于一身，使游客在亲手采茶、制茶、品茶的同时，深刻体味江北特有的茶文化和自然景观。整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 76);
INSERT INTO `travel_review` VALUES (23078, 'TR023078', '白马寺', '洛阳', '河南', '城市漫游', '秋季', 6, 3, 658.00, '是', 5, '6月去的白马寺，一个人出行。地点在洛阳，地铁到达方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约658元，拍照很出片。景点印象：中国佛教的祖庭，寺内的“镇寺之宝”——元代的“夹贮干漆造像”，已有700年的历史。 观赏珍贵碑碣——元代书法家赵孟頫手书的《洛京白马寺祖庭记》。整体感受是超出预期，值得专门打卡。二刷意愿：是。', '49%', 113);
