INSERT INTO `travel_review` VALUES (23090, 'TR023090', '祝圣寺', '衡阳', '湖南', '城市漫游', '冬季', 10, 1, 245.00, '是', 5, '10月去的祝圣寺，一个人出行。地点在衡阳，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约245元，拍照很出片。景点印象：曾经是为康熙皇帝南巡而改建的行宫，寺内还保留着很多世俗题材的浮雕。 寺中罗汉堂的罗汉像，各个栩栩如生，姿态各异，是“南岳”中的至宝。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '5%', 108);
