INSERT INTO `travel_review` VALUES (23094, 'TR023094', '白龙庙', '吕梁', '山西', '深度游', '秋季', 6, 3, 474.00, '否', 3, '6月去的白龙庙，和家人出行。地点在吕梁，公交换乘方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约474元，拍照很出片。景点印象：白龙庙位于岚县城西22公里与兴县接壤的白龙山腰部。该山原名大万山，因建有白龙庙而得名，是吕梁山向北延伸的一条支脉。它山势雄伟，挺拔俊秀，群峰耸立，层峦叠嶂。遍山苍松翠柏，名花异草，既有珍贵的省鸟褐马鸡及麋鹿、貂、麝等珍稀动物，又有“…整体感受是还可以，避开高峰更好。二刷意愿：否。', '0%', 44);
