INSERT INTO `travel_review` VALUES (23099, 'TR023099', '麒麟山', '鸡西', '黑龙江', '周末短途', '春季', 12, 3, 1098.00, '是', 4, '12月去的麒麟山，和家人出行。地点在鸡西，地铁到达方便，现场人不算多。这次玩了3天，人均花费约1098元，夜景表现很好。景点印象：麒麟山风景区位于黑龙江省鸡东县兴农镇西侧，距鸡西市中心约42公里，它的特点是自然景观秀丽迷人，人文景观别致新颖、山峰陡峭、湖水清幽，是一处不可多得的旅游胜地。\n风景区的大门楼高8米、宽20米，采用的是中华民族传统的建筑风格，金色琉璃瓦、…整体感受是还蛮满意，周末来刚好。二刷意愿：是。', '0%', 80);
