INSERT INTO `travel_review` VALUES (23110, 'TR023110', '关门山国家森林公园', '本溪', '辽宁', '周末短途', '秋季', 8, 2, 817.00, '否', 5, '8月去的关门山国家森林公园，情侣出行。地点在本溪，打车比较省心，现场高峰时段比较拥挤。这次玩了2天，人均花费约817元，夜景表现很好。景点印象：著名的秋季赏枫胜地，随处可以捕捉到迷人的镜头。 登临山巅俯瞰绝美山水，景致秀丽堪称“东北小黄山”。 行走于溪流边、在茂密的林间吐纳最纯净的空气。整体感受是特别满意，很推荐。二刷意愿：否。', '0%', 112);
