INSERT INTO `travel_review` VALUES (23152, 'TR023152', '马尾岛', '阳江', '广东', '周末短途', '夏季', 5, 1, 318.00, '是', 5, '5月去的马尾岛，和朋友出行。地点在阳江，打车比较省心，现场游客较多。这次玩了1天，人均花费约318元，历史文化气息浓。景点印象：整体环境还算干净整体感受是特别满意，很推荐。二刷意愿：是。', '29%', 89);
INSERT INTO `travel_review` VALUES (23153, 'TR023153', '灵东水库', '钦州', '广西', '周末短途', '冬季', 10, 1, 80.00, '是', 5, '10月去的灵东水库，和家人出行。地点在钦州，打车比较省心，现场人流量适中。这次玩了1天，人均花费约80元，历史文化气息浓。景点印象：又称“东湖”，位于灵山县城东14公里，在号称灵山第一峰的罗阳山翠峦环抱中，高山出平湖，水色湛蓝，似是一面明镜。\n该水库始建于1958年，当时全国兴修的十大水库之一，景区总面积728万平方米，现在已建设成为以灌溉防洪为主，兼发电、种养、旅游等…整体感受是超出预期，很推荐。二刷意愿：是。', '6%', 67);
