INSERT INTO `travel_review` VALUES (23157, 'TR023157', '晒秋人家', '上饶', '江西', '拍照旅行', '冬季', 10, 2, 436.00, '是', 5, '10月去的晒秋人家，情侣出行。地点在上饶，地铁到达方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约436元，氛围感不错。景点印象：秉承祖上遗风，篁岭村民习惯用平和心态与“地无三尺平”崎岖地形“交流”，用自己的方式在人与自然和谐相处中寻求新平衡点。整体感受是特别满意，很推荐。二刷意愿：是。', '0%', 91);
