INSERT INTO `travel_review` VALUES (23184, 'TR023184', '草原风情园', '邵阳', '湖南', '亲子出游', '春季', 1, 6, 1584.00, '否', 5, '1月去的草原风情园，情侣出行。地点在邵阳，自驾停车需要提前规划，现场游客较多。这次玩了6天，人均花费约1584元，夜景表现很好。景点印象：来南山体验一下过去牧民的生活是必不可少的，随着时代的变迁，过去旧的生活方式早就不复存在了\n草原风情园提供了我们体验牧民生活的可能。整体感受是超出预期，以后还会来。二刷意愿：否。', '0%', 98);
