INSERT INTO `travel_review` VALUES (23211, 'TR023211', '中国翰园碑林', '开封', '河南', '周末短途', '秋季', 7, 2, 627.00, '否', 2, '7月去的中国翰园碑林，和朋友出行。地点在开封，打车比较省心，现场人不算多。这次玩了2天，人均花费约627元，氛围感不错。景点印象：这里是书法爱好者的最爱，园中收藏的上千块碑刻，展现了当代书法大师的风采。坐游船，游弋在翰园湖中，观赏园中的湖光山色。 国庆前后观赏菊花展，春节庙会上体验满满的民俗风情。整体感受是没达到预期，可考虑其他景点。二刷意愿：否。', '15%', 42);
