INSERT INTO `travel_review` VALUES (23257, 'TR023257', '井冈山碑林', '吉安', '江西', '拍照旅行', '春季', 2, 2, 565.00, '否', 4, '2月去的井冈山碑林，情侣出行。地点在吉安，地铁到达方便，现场人流量适中。这次玩了2天，人均花费约565元，氛围感不错。景点印象：井冈山碑林始建于1987年7月，自1989年清明节起对外开放。碑林由碑亭、碑廊、自然碑型等部分组成，因势而构，曲折回环，别具一番情趣。整体感受是还蛮满意，周末来刚好。二刷意愿：否。', '5%', 44);
