INSERT INTO `travel_review` VALUES (23276, 'TR023276', '麒麟山', '鸡西', '黑龙江', '深度游', '春季', 2, 1, 184.00, '是', 5, '2月去的麒麟山，和家人出行。地点在鸡西，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约184元，氛围感不错。景点印象：麒麟山风景区位于黑龙江省鸡东县兴农镇西侧，距鸡西市中心约42公里，它的特点是自然景观秀丽迷人，人文景观别致新颖、山峰陡峭、湖水清幽，是一处不可多得的旅游胜地。\n风景区的大门楼高8米、宽20米，采用的是中华民族传统的建筑风格，金色琉璃瓦、…整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 73);
