INSERT INTO `travel_review` VALUES (23311, 'TR023311', '天梯山景区', '邢台', '河北', '文化打卡', '冬季', 9, 3, 931.00, '否', 5, '9月去的天梯山景区，情侣出行。地点在邢台，公交换乘方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约931元，夜景表现很好。景点印象：登山走在悬空古桥和吊桥之间，感受天梯山地貌的独特和险峻。 走进一个个形状各异的天然山洞，观看雕像、石刻等古迹。 乘船进入金水洞，观赏古洞内的钟乳石美景。整体感受是特别满意，以后还会来。二刷意愿：否。', '0%', 69);
