INSERT INTO `travel_review` VALUES (23318, 'TR023318', '南汀河', '临沧', '云南', '文化打卡', '秋季', 7, 4, 882.00, '否', 2, '7月去的南汀河，一个人出行。地点在临沧，自驾停车需要提前规划，现场游客较多。这次玩了4天，人均花费约882元，拍照很出片。景点印象：耿马南汀河风景名胜区位于耿马傣族佤族自治县境内，由四片一线组成，即孟定片区、景戈片区、福音山片区、清水河片区、孟省――清水河旅游线,总面积约146平方公里。景观有俗称版纳、瑞丽、孟定“三姐妹”风光秀丽的孟定坝亚热带风光；有郁郁葱葱的原…整体感受是没达到预期，不建议高峰来。二刷意愿：否。', '0%', 46);
