INSERT INTO `travel_review` VALUES (23342, 'TR023342', '莽山国家森林公园', '郴州', '湖南', '城市漫游', '夏季', 5, 1, 641.00, '是', 5, '5月去的莽山国家森林公园，情侣出行。地点在郴州，公交换乘方便，现场人流量适中。这次玩了1天，人均花费约641元，氛围感不错。景点印象：莽山国家森林公园，位于郴州市宜章县南部，莽山境内1000米以上的山峰就有150多座，最高峰“猛坑石”海拔约两千米，号称“天南第一峰”，而山中蜿蜒山间的长乐河是珠江的发源地之一。整体感受是挺惊喜，很推荐。二刷意愿：是。', '12%', 80);
INSERT INTO `travel_review` VALUES (23343, 'TR023343', '御河生态园', '大同', '山西', '亲子出游', '冬季', 10, 2, 765.00, '是', 4, '10月去的御河生态园，情侣出行。地点在大同，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约765元，拍照很出片。景点印象：御河生态园，南北长5.5公里，使昔日贫瘠、荒凉的御河两岸重现风光，一条河流能给予一座城市以灵魂，河畔生态园使城市物华得以体现，城市的审美和灵性凭河而含，籍园而展，御河蓄水，御园绽绿。整体感受是体验挺好，推荐来看看。二刷意愿：是。', '1%', 35);
