INSERT INTO `travel_review` VALUES (23348, 'TR023348', '灵光寺', '梅州', '广东', '周末短途', '夏季', 3, 1, 272.00, '否', 4, '3月去的灵光寺，一个人出行。地点在梅州，公交换乘方便，现场游客较多。这次玩了1天，人均花费约272元，拍照很出片。景点印象：阴那山麓灵光寺内，香火极盛，寺外仍不见一缕青烟；参天古木，殿顶亦不留一片落叶。整体感受是体验挺好，周末来刚好。二刷意愿：否。', '15%', 111);
