INSERT INTO `travel_review` VALUES (23359, 'TR023359', '柏枧山', '宣城', '安徽', '城市漫游', '冬季', 10, 7, 2030.00, '是', 3, '10月去的柏枧山，情侣出行。地点在宣城，地铁到达方便，现场人流量适中。这次玩了7天，人均花费约2030元，氛围感不错。景点印象：柏枧山乃黄山余脉，主峰海拔999米，位于宣州区境内，离市区约20公里，景区面积达80平方公里。《辞源》称其“溪谷深邃，峰岩回曲，山水秀美，甲于江南”。\n这里山水田园美不胜收。雄奇的山川、幽深的峡谷、茂密的森林、珍奇的禽兽、美丽的河流、广阔…整体感受是还可以，按需选择。二刷意愿：是。', '0%', 36);
INSERT INTO `travel_review` VALUES (23360, 'TR023360', '香格里拉巴拉格宗风景名胜区', '迪庆', '云南', '城市漫游', '夏季', 3, 6, 1302.00, '是', 5, '3月去的香格里拉巴拉格宗风景名胜区，和朋友出行。地点在迪庆，地铁到达方便，现场人不算多。这次玩了6天，人均花费约1302元，拍照很出片。景点印象：拥有非常壮阔的自然风光，可以在风光秀美的谷中漂流，也可以拜访原始的藏族古村。整体感受是超出预期，值得专门打卡。二刷意愿：是。', '2%', 66);
