INSERT INTO `travel_review` VALUES (23364, 'TR023364', '扬州大运河文化旅游度假区·观音山', '扬州', '江苏', '拍照旅行', '冬季', 11, 1, 220.00, '是', 5, '11月去的扬州大运河文化旅游度假区·观音山，情侣出行。地点在扬州，公交换乘方便，现场游客较多。这次玩了1天，人均花费约220元，氛围感不错。景点印象：位于隋炀帝迷楼故址上，寺庙建筑犹如迷宫，游客不多，非常清静。整体感受是特别满意，很推荐。二刷意愿：是。', '6%', 76);
INSERT INTO `travel_review` VALUES (23365, 'TR023365', '天府广场', '成都', '四川', '拍照旅行', '夏季', 4, 3, 940.00, '否', 2, '4月去的天府广场，情侣出行。地点在成都，地铁到达方便，现场人不算多。这次玩了3天，人均花费约940元，历史文化气息浓。景点印象：成都的中心广场，城市的地标和象征，还是两条地铁线的换乘中心。整体感受是略失望，不建议高峰来。二刷意愿：否。', '0%', 33);
INSERT INTO `travel_review` VALUES (23366, 'TR023366', '唐杜工部之墓', '襄阳', '湖北', '文化打卡', '春季', 1, 1, 802.00, '否', 4, '1月去的唐杜工部之墓，和家人出行。地点在襄阳，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约802元，历史文化气息浓。景点印象：在襄樊市襄阳城南岘首山西侧。即杜甫庐墓所在地。其《回掉》诗曾述：“清思汉水上，凉忆岘山巅。吾家碑不昧，王氏井依然。”唐大历五年（770年）仲冬，杜甫病逝湖南，其后人自河南巩县前往奔丧，路经此处，邑人为纪念他，特于此建衣冠冢。民国时期…整体感受是整体不错，可以安排半天到一天。二刷意愿：否。', '0%', 86);
INSERT INTO `travel_review` VALUES (23367, 'TR023367', '君山岛', '岳阳', '湖南', '城市漫游', '冬季', 9, 1, 589.00, '是', 5, '9月去的君山岛，和家人出行。地点在岳阳，自驾停车需要提前规划，现场人不算多。这次玩了1天，人均花费约589元，拍照很出片。景点印象：听听古老的神话传说，感受古代爱情的伟大之处。 漫步在满目苍翠间，品一杯君山毛尖，度一段休闲时光。整体感受是特别满意，以后还会来。二刷意愿：是。', '27%', 76);
INSERT INTO `travel_review` VALUES (23368, 'TR023368', '罗布林卡', '拉萨', '西藏', '文化打卡', '冬季', 11, 6, 1492.00, '否', 4, '11月去的罗布林卡，一个人出行。地点在拉萨，打车比较省心，现场人流量适中。这次玩了6天，人均花费约1492元，历史文化气息浓。景点印象：西藏精美的园林，还有各国元首送的礼物。整体感受是体验挺好，可以安排半天到一天。二刷意愿：否。', '26%', 64);
INSERT INTO `travel_review` VALUES (23369, 'TR023369', '九龙山', '邵阳', '湖南', '周末短途', '秋季', 7, 3, 1273.00, '是', 5, '7月去的九龙山，一个人出行。地点在邵阳，打车比较省心，现场人不算多。这次玩了3天，人均花费约1273元，拍照很出片。景点印象：九龙山海拔1142米，座落在县城东北面的岩口乡， 南距县城45公里，东距宝庆古城55公里。九龙山有一处古人石刻“不让武陵”。说明了其风景秀丽不亚于武陵源。这里竹木葱茏，巨石林立。在山的东面有人面狮头石，侧面看，活象仰面的高尔基在望天兴叹；…整体感受是特别满意，以后还会来。二刷意愿：是。', '0%', 71);
