INSERT INTO `travel_review` VALUES (23389, 'TR023389', '达斡尔哈拉新村', '齐齐哈尔', '黑龙江', '周末短途', '秋季', 8, 1, 187.00, '否', 4, '8月去的达斡尔哈拉新村，和朋友出行。地点在齐齐哈尔，自驾停车需要提前规划，现场游客较多。这次玩了1天，人均花费约187元，历史文化气息浓。景点印象：原哈拉村毁于1998年嫩江特大洪灾。经全国政协和中华慈善总会拨款救助，在省市区党委、政府的关怀下，于翌年重新建成现代化的哈拉新村。\n        哈拉新村地处齐查、齐林公路交汇处，东濒嫩江，西南与明月岛隔江相望。全村有居民300户，其中达斡尔族…整体感受是体验挺好，可以安排半天到一天。二刷意愿：否。', '0%', 96);
