INSERT INTO `travel_review` VALUES (23432, 'TR023432', '澄水洞旅游区', '咸宁', '湖北', '文化打卡', '春季', 12, 5, 1628.00, '否', 3, '12月去的澄水洞旅游区，和朋友出行。地点在咸宁，打车比较省心，现场人不算多。这次玩了5天，人均花费约1628元，历史文化气息浓。景点印象：1968年，中苏边境局势紧张，国家准备应战，毛泽东主席下令汪东兴在鄂南为他修建战时住房。澄水洞地下工程，即是在这种背景下由当时的军委参谋长于1969年1月31日签署命令，亲自选址后始建的地下军事工程。整个工程神密而传奇，原计划投资3亿元，后因…整体感受是体验一般，避开高峰更好。二刷意愿：否。', '0%', 70);
