INSERT INTO `travel_review` VALUES (23448, 'TR023448', '保安寺', '中卫', '宁夏', '文化打卡', '夏季', 5, 1, 210.00, '是', 5, '5月去的保安寺，一个人出行。地点在中卫，公交换乘方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约210元，拍照很出片。景点印象：高庙保安寺位于宁夏中卫县高庙村，前平后台，分上下两院，上为高庙，下为保安寺，习惯地把下边的保安寺包括在内，通称“高庙”。创建于明朝永乐年间，距今600多年的历史。整体感受是挺惊喜，很推荐。二刷意愿：是。', '4%', 88);
