INSERT INTO `travel_review` VALUES (23469, 'TR023469', '塞海', '娄底', '湖南', '城市漫游', '春季', 12, 5, 1586.00, '否', 3, '12月去的塞海，和家人出行。地点在娄底，打车比较省心，现场游客较多。这次玩了5天，人均花费约1586元，夜景表现很好。景点印象：为湄江中心景区，主要景点有一湖秀水塞海，绝秀景观合掌崖，天然巨型回音壁，诗家杰作湄江诗岩、天子山、观音望海、舵手峰等。泛舟塞海,如画中游。整体感受是还可以，别抱太高期待。二刷意愿：否。', '7%', 70);
