INSERT INTO `travel_review` VALUES (23472, 'TR023472', '麻姑仙境', '衡阳', '湖南', '亲子出游', '冬季', 11, 1, 293.00, '否', 5, '11月去的麻姑仙境，和朋友出行。地点在衡阳，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约293元，拍照很出片。景点印象：可以在灵芝喷泉旁日光浴、森林浴，十分惬意。 周边到处是盛开的野花，满眼绿荫，是传说中仙女麻姑酿酒的地方。整体感受是超出预期，值得专门打卡。二刷意愿：否。', '8%', 101);
INSERT INTO `travel_review` VALUES (23473, 'TR023473', '下草湾古人类遗址', '宿迁', '江苏', '文化打卡', '春季', 12, 2, 639.00, '是', 5, '12月去的下草湾古人类遗址，和家人出行。地点在宿迁，打车比较省心，现场人流量适中。这次玩了2天，人均花费约639元，氛围感不错。景点印象：位于双沟镇东南8公里处的下草湾引河东岸，是江苏省发现最早的古人类遗址。2002年，被市政府确定为市级重点文物保护单位。1954年6月，中国科学院院士、古脊椎动物和古人类研究所所长杨钟健教授在下草湾考察时，采集到一段长15.27厘米的骨化石。经研…整体感受是特别满意，以后还会来。二刷意愿：是。', '0%', 30);
