INSERT INTO `travel_review` VALUES (23503, 'TR023503', '南山风景旅游区', '伊春', '黑龙江', '城市漫游', '冬季', 11, 1, 1050.00, '否', 4, '11月去的南山风景旅游区，和朋友出行。地点在伊春，公交换乘方便，现场人不算多。这次玩了1天，人均花费约1050元，拍照很出片。景点印象：南山风景旅游区始建于1993年，景区占地面积为3500公顷，山体平均海拔420米，其中兴安塔主峰海拔653米，塔高47米，是景区的标志性建筑。南山景区地势起伏、峰谷迂回、空间富于变化、自然形成山体，峰容坡地构成风景区多种的地貌景观。景区森林覆盖率…整体感受是还蛮满意，推荐来看看。二刷意愿：否。', '0%', 61);
