INSERT INTO `travel_review` VALUES (23511, 'TR023511', '丹阳王墓', '朔州', '山西', '周末短途', '冬季', 11, 3, 696.00, '否', 2, '11月去的丹阳王墓，和家人出行。地点在朔州，打车比较省心，现场人流量适中。这次玩了3天，人均花费约696元，氛围感不错。景点印象：丹阳王墓位于怀仁县城北4公里的大运公路边。《怀仁县志》记载墓主人是丹阳王叔孙建，但无确凿史料及出土文物为证。建造年代当是北魏无疑。\n该墓分墓道、甬道、前室、后室和东西侧室。墓室平面均呈弧边长方形，四角攒尖顶，墓室高7．2米，墓室面积…整体感受是略失望，可考虑其他景点。二刷意愿：否。', '0%', 40);
