INSERT INTO `travel_review` VALUES (23521, 'TR023521', '青竹农家乐园', '阳江', '广东', '文化打卡', '夏季', 4, 4, 380.00, '否', 5, '4月去的青竹农家乐园，一个人出行。地点在阳江，公交换乘方便，现场游客较多。这次玩了4天，人均花费约380元，拍照很出片。景点印象：青竹农家乐园位于城郊头堡村，这里山青水秀，环境洁静如人。在头堡村内的青竹农家乐园已成为城市人休闲、娱乐和品尝农家菜的 最佳去处。这里的农民纯朴和热情好客，村内有原始古朴的民居，有富有特色的农家菜肴，有风景优美的河塘水景，有连片绿油…整体感受是挺惊喜，很推荐。二刷意愿：否。', '0%', 71);
INSERT INTO `travel_review` VALUES (23522, 'TR023522', '大峪沟风景区', '甘南', '甘肃', '亲子出游', '夏季', 5, 2, 625.00, '是', 5, '5月去的大峪沟风景区，情侣出行。地点在甘南，打车比较省心，现场人流量适中。这次玩了2天，人均花费约625元，历史文化气息浓。景点印象：风光非常原始纯粹，是一座清净美丽的世外桃源。整体感受是特别满意，很推荐。二刷意愿：是。', '2%', 66);
