INSERT INTO `travel_review` VALUES (23533, 'TR023533', '冠山', '阳泉', '山西', '深度游', '春季', 1, 3, 1405.00, '否', 2, '1月去的冠山，情侣出行。地点在阳泉，公交换乘方便，现场人流量适中。这次玩了3天，人均花费约1405元，氛围感不错。景点印象：山西省冠山森林公园位于山西省东部的平定县城关镇内，公园总面积709。4公顷，最高海拔1152米，植物种类丰富，有古松、奇树35株，医用药材160余种，危崖峭立，松柏参天，山光水色瑰丽，景色四季宜人，更有佛寺书院、石峒亭阁、乔宇诗碑、傅山篆刻，…整体感受是体验偏一般，建议谨慎前往。二刷意愿：否。', '0%', 43);
