INSERT INTO `travel_review` VALUES (23578, 'TR023578', '循化撒拉族绿色家园', '海东', '青海', '城市漫游', '春季', 1, 1, 526.00, '否', 4, '1月去的循化撒拉族绿色家园，和朋友出行。地点在海东，公交换乘方便，现场人不算多。这次玩了1天，人均花费约526元，氛围感不错。景点印象：循化撒拉族绿色家园位于自治县东北，平均海拔2500米以上，主峰高4178米，山清水秀，数百种树木掩天蔽日，各种花草植物绿茵盖地，有人参、三七、贝母等名贵药材，还有大量的珍稀动物，有“高原西双版纳”之美称。整体感受是整体不错，推荐来看看。二刷意愿：否。', '6%', 55);
