INSERT INTO `travel_review` VALUES (23588, 'TR023588', '避暑山庄罗家园', '石嘴山', '宁夏', '周末短途', '冬季', 11, 5, 1089.00, '是', 5, '11月去的避暑山庄罗家园，和家人出行。地点在石嘴山，地铁到达方便，现场高峰时段比较拥挤。这次玩了5天，人均花费约1089元，拍照很出片。景点印象：位于惠农县燕子墩汪家村以东海拔3000多米的贺兰山脚下的王泉沟口，是贺兰山脚下的一片绿洲，罗家园以其秀丽的景色，潺潺的泉水，清凉的气候，山水的交汇，独特的绿洲和鬼斧神工的幽谷险峰，形成了贺兰山下一个美丽的风景区。\n罗家园总面积约3万多…整体感受是特别满意，很推荐。二刷意愿：是。', '0%', 102);
