INSERT INTO `travel_review` VALUES (23701, 'TR023701', '天安门广场', '北京', '北京', '深度游', '秋季', 8, 1, 243.00, '否', 5, '8月去的天安门广场，一个人出行。地点在北京，自驾停车需要提前规划，现场人流量适中。这次玩了1天，人均花费约243元，拍照很出片。景点印象：伟大祖国的标志，早起看一场庄严肃穆的升旗仪式，瞻仰人民英雄纪念碑。整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '50%', 85);
INSERT INTO `travel_review` VALUES (23702, 'TR023702', '释迦多宝如来佛塔', '黄冈', '湖北', '文化打卡', '春季', 1, 2, 717.00, '否', 5, '1月去的释迦多宝如来佛塔，情侣出行。地点在黄冈，地铁到达方便，现场游客较多。这次玩了2天，人均花费约717元，历史文化气息浓。景点印象：在五祖寺前一天门。据塔身铭记为北宋宣和三年（1121年）所建。系用素面灰色砂粒岩石砌成，八角五级，高5米，下设莲瓣束腰须弥座，束腰八角各设有挺拔劲健的托塔力士一尊。座上置塔身，形如立鼓，其南面凿佛龛，内供佛像端坐，龛右镌刻“释迦多宝如…整体感受是挺惊喜，以后还会来。二刷意愿：否。', '0%', 80);
INSERT INTO `travel_review` VALUES (23703, 'TR023703', '月亮山', '中卫', '宁夏', '拍照旅行', '冬季', 10, 1, 400.00, '是', 4, '10月去的月亮山，和朋友出行。地点在中卫，公交换乘方便，现场人不算多。这次玩了1天，人均花费约400元，历史文化气息浓。景点印象：月亮山是西吉县境内最高的山脉，位于县城西北部西吉、海原两县交界处，白城乡东北。属屈吴山余脉，因其形状近似弧月而得名。主峰海拔2633米，上下山路程约七华里，西麓有宝河沟，故又名七里宝山。\n月亮山东南接六盘山余脉--西峰岭，西北与西华山接…整体感受是整体不错，推荐来看看。二刷意愿：是。', '25%', 84);
