INSERT INTO `travel_review` VALUES (23706, 'TR023706', '上堡古国', '邵阳', '湖南', '亲子出游', '冬季', 11, 3, 786.00, '否', 5, '11月去的上堡古国，情侣出行。地点在邵阳，地铁到达方便，现场人流量适中。这次玩了3天，人均花费约786元，拍照很出片。景点印象：上堡古国地处绥宁县黄桑坪苗族乡，南抵城步南山景区，西接通道万佛山景区，为明朝侗苗民族起义根据地.整体感受是超出预期，值得专门打卡。二刷意愿：否。', '0%', 65);
