INSERT INTO `travel_review` VALUES (23722, 'TR023722', '神仙湾', '阿勒泰', '新疆', '文化打卡', '春季', 2, 4, 1054.00, '是', 5, '2月去的神仙湾，情侣出行。地点在阿勒泰，地铁到达方便，现场人流量适中。这次玩了4天，人均花费约1054元，历史文化气息浓。景点印象：常年云雾缭绕，日出时河面流光溢彩宛如仙境。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '32%', 68);
INSERT INTO `travel_review` VALUES (23723, 'TR023723', '万岁山', '开封', '河南', '亲子出游', '春季', 2, 3, 1184.00, '否', 2, '2月去的万岁山，一个人出行。地点在开封，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了3天，人均花费约1184元，氛围感不错。景点印象：万岁山藏自然山水美与人工美于一体，括天下之绝，含古今之胜，集我国古代南北园林建筑艺术之大成，荟萃华夏名山大川雄伟、险峻、奇秀、幽美、畅旷诸特色，成为全国山水奇景的一个缩影，堪称世界一绝。整体感受是略失望，建议谨慎前往。二刷意愿：否。', '1%', 23);
INSERT INTO `travel_review` VALUES (23724, 'TR023724', '怪山', '通辽', '内蒙古', '城市漫游', '夏季', 5, 2, 260.00, '否', 4, '5月去的怪山，一个人出行。地点在通辽，地铁到达方便，现场人不算多。这次玩了2天，人均花费约260元，拍照很出片。景点印象：怪山旅游区位于内蒙古霍林郭勒市西北14公里处，距通辽市政府所在地科尔沁区320公里，占地11.4平方公里。景区内分营业区、水库区和自然保护区。怪山由地壳运动时挤压而形成，山脉长度约2000米，海拔1199.3米。闻名于世的怪山耸立在哈布其勒水库岸边…整体感受是体验挺好，可以安排半天到一天。二刷意愿：否。', '4%', 77);
