INSERT INTO `travel_review` VALUES (23729, 'TR023729', '雄县', '雄安新区', '河北', '深度游', '秋季', 7, 3, 776.00, '是', 5, '7月去的雄县，和朋友出行。地点在雄安新区，地铁到达方便，现场人不算多。这次玩了3天，人均花费约776元，历史文化气息浓。景点印象：雄县隶属于河北省保定市，地处冀中平原，北距首都108公里，东距天津100公里，西距保定70公里，东依霸州市，南部、东南部隔大清河与任丘市、文安县相望，西南隔白洋淀与安新县相连，西部与容城县相接，西北与高碑店市毗邻，东北与固安县接壤。整体感受是超出预期，值得专门打卡。二刷意愿：是。', '0%', 44);
