INSERT INTO `travel_review` VALUES (23733, 'TR023733', '天生桥', '邵阳', '湖南', '文化打卡', '冬季', 10, 2, 418.00, '否', 4, '10月去的天生桥，和家人出行。地点在邵阳，地铁到达方便，现场游客较多。这次玩了2天，人均花费约418元，氛围感不错。景点印象：天生桥景区紧临广西，是莨山景区近年来新发现的最具特色的景区之一，区内山环水绕，群峰横列，赤壁对峙，万巷迷离，约有近50平方公里折大面积丹霞赤壁群景观，景观资源特色鲜明，个性突出，具有强劲的比较优势，是开发丹霞观光、生态旅游、休头娱乐…整体感受是体验挺好，周末来刚好。二刷意愿：否。', '0%', 60);
INSERT INTO `travel_review` VALUES (23734, 'TR023734', '金海水晶宫', '本溪', '辽宁', '城市漫游', '春季', 12, 1, 257.00, '否', 5, '12月去的金海水晶宫，和朋友出行。地点在本溪，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约257元，历史文化气息浓。景点印象：石桥子开发区的金海水晶宫拥有国际标准竞赛泳道，不仅填补了本溪水上竞赛场馆的空白，馆内100平方米的儿童嬉水池，美国进口的水处理设备，泳池中央可升降的自动舞台等更为本溪开展冬季旅游增添了娱乐的场所。不仅可以满足全市城乡居民的冬季休闲度…整体感受是挺惊喜，以后还会来。二刷意愿：否。', '1%', 123);
