INSERT INTO `travel_review` VALUES (23736, 'TR023736', '中国内陆海拔零点', '吐鲁番', '新疆', '城市漫游', '冬季', 10, 2, 793.00, '是', 4, '10月去的中国内陆海拔零点，一个人出行。地点在吐鲁番，地铁到达方便，现场人流量适中。这次玩了2天，人均花费约793元，拍照很出片。景点印象：位于新疆吐鲁番亚尔乡巴村境内。地理坐标为东经89度11分。北纬42度56分，“零点”西至交河故城13公里，东至高昌故城50公里，北至苏公塔2公里，南至艾丁湖最低点30公里。“零点”属特殊地理位置。\n新疆吐鲁番盆地是中国最低的内陆盆地，也是世界第二…整体感受是还蛮满意，可以安排半天到一天。二刷意愿：是。', '1%', 83);
INSERT INTO `travel_review` VALUES (23737, 'TR023737', '赤坎华侨古镇', '江门', '广东', '文化打卡', '冬季', 10, 7, 2178.00, '否', 4, '10月去的赤坎华侨古镇，和朋友出行。地点在江门，地铁到达方便，现场高峰时段比较拥挤。这次玩了7天，人均花费约2178元，氛围感不错。景点印象：原生态的侨乡古镇，骑楼林立，还有独特的碉楼建筑。整体感受是整体不错，推荐来看看。二刷意愿：否。', '33%', 44);
