INSERT INTO `travel_review` VALUES (23739, 'TR023739', '中国渔村', '宁波', '浙江', '城市漫游', '冬季', 11, 3, 1211.00, '否', 3, '11月去的中国渔村，和朋友出行。地点在宁波，地铁到达方便，现场人流量适中。这次玩了3天，人均花费约1211元，氛围感不错。景点印象：十分成熟的度假海滩，在皇城沙滩吹吹海风，十足的享受。 坐上海边的摩天轮，在高空俯瞰眼前辽阔的大海。整体感受是中规中矩，按需选择。二刷意愿：否。', '0%', 39);
INSERT INTO `travel_review` VALUES (23740, 'TR023740', '香陈湾', '漯河', '河南', '城市漫游', '秋季', 7, 2, 762.00, '否', 3, '7月去的香陈湾，和家人出行。地点在漯河，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约762元，夜景表现很好。景点印象：漯河市香陈湾是因园址建在沙河环抱的香陈湾村而得名。原名陈湾村，因村上陈姓居多，又加上处在沙河河湾当中，因此称陈湾村，旧社会由于该村加工敬天拜神的香远近闻名，又称香陈湾。\n由澳的利投资兴建的漯河市香陈湾游乐园，一期工程占地面积600余…整体感受是中规中矩，按需选择。二刷意愿：否。', '33%', 77);
