INSERT INTO `travel_review` VALUES (23784, 'TR023784', '白水岭热带森林', '万宁', '海南', '亲子出游', '夏季', 3, 3, 936.00, '否', 5, '3月去的白水岭热带森林，和家人出行。地点在万宁，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了3天，人均花费约936元，历史文化气息浓。景点印象：属热带原始森林，总面积45700多亩，这里生长着茂密的热带山地雨季林，林中栖息着种类众多的珍稀动物，被誉为海南物华天宝之地，是热带森林旅游观光的好去处。\n进入保护区古林绿海之中，那林海涛声，时而咆哮，时而低吟。立于山巅俯视，日挂中天，树…整体感受是特别满意，值得专门打卡。二刷意愿：否。', '0%', 67);
INSERT INTO `travel_review` VALUES (23785, 'TR023785', '东西塔', '泉州', '福建', '深度游', '秋季', 6, 1, 770.00, '否', 4, '6月去的东西塔，和朋友出行。地点在泉州，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约770元，氛围感不错。景点印象：该塔是我国石构建筑瑰宝，它既是泉州海外交通繁荣的象征，也是泉州历史文化名城的标志。整体感受是整体不错，推荐来看看。二刷意愿：否。', '2%', 82);
