INSERT INTO `travel_review` VALUES (23801, 'TR023801', '哈斯哈吉甫陵墓', '喀什', '新疆', '亲子出游', '春季', 1, 2, 488.00, '是', 5, '1月去的哈斯哈吉甫陵墓，一个人出行。地点在喀什，打车比较省心，现场游客较多。这次玩了2天，人均花费约488元，拍照很出片。景点印象：玉素甫·哈斯哈吉甫是维吾尔族伟大的思想家，他于公元1069年-1070年间，以当时的维吾尔文完成了13290行的长诗《福乐智慧》。\n玉素甫·哈斯哈吉甫墓，座落在喀什市体育路十二小学院内，占地965平方米。玉素甫.哈斯哈吉甫墓是一组富于维吾尔传统建筑…整体感受是超出预期，值得专门打卡。二刷意愿：是。', '3%', 54);
