INSERT INTO `travel_review` VALUES (23848, 'TR023848', '雪岭云杉自然保护区', '伊犁', '新疆', '拍照旅行', '春季', 2, 3, 993.00, '否', 5, '2月去的雪岭云杉自然保护区，和朋友出行。地点在伊犁，公交换乘方便，现场人流量适中。这次玩了3天，人均花费约993元，历史文化气息浓。景点印象：雪岭云杉是天山林海中特有的一个树种。在巍巍天山深处，它苍劲挺拔、四季青翠、攀坡漫生、绵延不绝，犹如一道沿山而筑的绿色长城。风吹林海，松涛声声，绿波起伏，其势如潮。整体感受是特别满意，值得专门打卡。二刷意愿：否。', '0%', 60);
