INSERT INTO `travel_review` VALUES (23852, 'TR023852', '安乐寺', '贺州', '广西', '文化打卡', '冬季', 9, 1, 80.00, '是', 5, '9月去的安乐寺，情侣出行。地点在贺州，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约80元，氛围感不错。景点印象：安乐寺始建于顺治元年（1644年），康熙四十三年（1704年），道光十一年（1831年）重修。一1944年改建为街公所粮库，1933年农历月十五日动工修复。寺里供奉着“李道清公爷神像”，上面挂着“聪听弈训”的牌匾，两边的条幅左边为“国泰民安”，右边为…整体感受是超出预期，值得专门打卡。二刷意愿：是。', '6%', 79);
