INSERT INTO `travel_review` VALUES (23938, 'TR023938', '曹州武术馆', '菏泽', '山东', '城市漫游', '秋季', 7, 5, 1087.00, '否', 5, '7月去的曹州武术馆，和家人出行。地点在菏泽，地铁到达方便，现场人不算多。这次玩了5天，人均花费约1087元，拍照很出片。景点印象：曹州武术馆是国家教委、体委批准认可的一所大型规范化、军事化教武育人的训练基地。本馆指导思想是：“以文保武”，“以武促文”、“以质量求生存”，“以信誉求发展”以法治馆，以德育人，培养“四有”人才，以传授和发扬中华武术为已任。整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '0%', 109);
INSERT INTO `travel_review` VALUES (23939, 'TR023939', '鸡足山', '大理', '云南', '城市漫游', '冬季', 10, 1, 317.00, '否', 5, '10月去的鸡足山，情侣出行。地点在大理，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约317元，历史文化气息浓。景点印象：佛教明山，可以参拜古老寺院，欣赏秀丽山色。整体感受是挺惊喜，以后还会来。二刷意愿：否。', '0%', 67);
INSERT INTO `travel_review` VALUES (23940, 'TR023940', '纯阳宫', '太原', '山西', '周末短途', '春季', 2, 6, 1105.00, '否', 5, '2月去的纯阳宫，情侣出行。地点在太原，打车比较省心，现场人不算多。这次玩了6天，人均花费约1105元，夜景表现很好。景点印象：当地著名道观，能够观赏到铸像、古碑、石佛和石兽等唐代之前的文物。整体感受是超出预期，很推荐。二刷意愿：否。', '8%', 78);
