INSERT INTO `travel_review` VALUES (23942, 'TR023942', '法门寺博物馆', '宝鸡', '陕西', '亲子出游', '春季', 12, 1, 476.00, '是', 5, '12月去的法门寺博物馆，和朋友出行。地点在宝鸡，公交换乘方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约476元，拍照很出片。景点印象：法门寺博物馆与驰名中外的千年古刹法门寺为邻，是以收藏、保护、展示和研究法门寺唐塔地宫出土珍贵文物为主要内容的专题性佛教艺术博物馆。整体感受是特别满意，很推荐。二刷意愿：是。', '22%', 78);
