INSERT INTO `travel_review` VALUES (23944, 'TR023944', '鹿回头风景区', '三亚', '海南', '亲子出游', '夏季', 3, 1, 206.00, '是', 5, '3月去的鹿回头风景区，情侣出行。地点在三亚，公交换乘方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约206元，氛围感不错。景点印象：登高展望三亚城区风光与海岸美景，也是观赏日出日落的制高点。整体感受是超出预期，值得专门打卡。二刷意愿：是。', '20%', 96);
INSERT INTO `travel_review` VALUES (23945, 'TR023945', '董必武旧居', '黄冈', '湖北', '拍照旅行', '春季', 12, 2, 471.00, '否', 4, '12月去的董必武旧居，和朋友出行。地点在黄冈，打车比较省心，现场高峰时段比较拥挤。这次玩了2天，人均花费约471元，夜景表现很好。景点印象：董必武旧居在红安县城民主街。旧居为一栋7间中式平房，坐西向东，面积120平方米。正中一间为小堂屋，上方香台依墙高置，大条桌放于中央，两张圆椅分列两旁，下方存放着董必武母亲用过的纺线车、织布机和灯架。堂屋北面的后半间房，是董必武诞生地，…整体感受是整体不错，推荐来看看。二刷意愿：否。', '0%', 105);
