INSERT INTO `travel_review` VALUES (24035, 'TR024035', '云峰湖', '通化', '吉林', '城市漫游', '春季', 12, 2, 535.00, '否', 5, '12月去的云峰湖，和朋友出行。地点在通化，打车比较省心，现场人不算多。这次玩了2天，人均花费约535元，拍照很出片。景点印象：云峰湖风景旅游度假区坐落在集安市以东、鸭绿江上游40公里处，有以\"界河明珠\"之称的云峰发电厂，象征中朝友谊纽带的云峰大坝，和大坝截流形成的海拔218.5米，面积102.5平方公里的人工湖组成。\n云峰湖两岸高山耸立，怪石嶙峋，古木参天，树种繁多；…整体感受是超出预期，以后还会来。二刷意愿：否。', '0%', 94);
