INSERT INTO `travel_review` VALUES (24058, 'TR024058', '太行太岳烈士陵园', '长治', '山西', '深度游', '冬季', 9, 3, 548.00, '否', 5, '9月去的太行太岳烈士陵园，和朋友出行。地点在长治，打车比较省心，现场人不算多。这次玩了3天，人均花费约548元，拍照很出片。景点印象：位于长治市内的梅辉坡。它是根据1946年3月晋冀鲁豫边区参议会第一届第二次会议的决议，为纪念在抗日战争中英勇牺牲于太行太岳的中华民族优秀儿女而建立的。1951年落成。 占地总面积为9460万平方米。陵园开南、东两个门，南门为正门。大门两壁是戎子…整体感受是挺惊喜，很推荐。二刷意愿：否。', '0%', 116);
