INSERT INTO `travel_review` VALUES (24068, 'TR024068', '哈拉新村', '齐齐哈尔', '黑龙江', '深度游', '冬季', 9, 2, 983.00, '否', 4, '9月去的哈拉新村，一个人出行。地点在齐齐哈尔，打车比较省心，现场高峰时段比较拥挤。这次玩了2天，人均花费约983元，拍照很出片。景点印象：蛇洞山风景区位于齐齐哈尔市碾子山区西部4.5公里，占地面积300公顷，最高峰龙峰海拔406米，是国家“AA”级风景区。景区由青石崖、蛇洞山、龙峰、佛尔寺及西河园等景观构成。区内峰峦起伏，怪石嶙峋，各景点错落有致、浑然一体，龟、牛、蛙、龙、狮…整体感受是整体不错，周末来刚好。二刷意愿：否。', '0%', 79);
