INSERT INTO `travel_review` VALUES (24071, 'TR024071', '自怀风景区', '泸州', '四川', '城市漫游', '冬季', 9, 4, 1263.00, '是', 5, '9月去的自怀风景区，情侣出行。地点在泸州，打车比较省心，现场人不算多。这次玩了4天，人均花费约1263元，氛围感不错。景点印象：自怀风景区是世界同纬度上唯一的，保留完整的常绿阔叶林带，自怀景区在1989年被确定为省级风景名胜区。这里四季风光各异，盛夏，气温平均比山外低5森摄氏度以上，有天然大空调之说，山秀、水美、石奇、民风纯朴，是自怀风光所独有。这里的原始林，…整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 72);
