INSERT INTO `travel_review` VALUES (24139, 'TR024139', '贾登峪国家森林公园', '北疆', '新疆', '深度游', '春季', 1, 2, 413.00, '是', 5, '1月去的贾登峪国家森林公园，情侣出行。地点在北疆，打车比较省心，现场高峰时段比较拥挤。这次玩了2天，人均花费约413元，氛围感不错。景点印象：观赏由围起的毡房群、山丘森林和欧式城堡等一起构成的美丽童话世界。 居住在内部色彩艳丽的毡房里，体验牧民们的淳朴生活。 交通便利，是徒步或坐车进入喀纳斯湖景区、禾木风景区的中转站。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 108);
