INSERT INTO `travel_review` VALUES (24141, 'TR024141', '金牛山', '营口', '辽宁', '文化打卡', '冬季', 9, 2, 762.00, '否', 2, '9月去的金牛山，和家人出行。地点在营口，地铁到达方便，现场人流量适中。这次玩了2天，人均花费约762元，氛围感不错。景点印象：金牛山古人类遗址位于大石桥市永安镇西田屯村，是迄今为止东北地区最早的古人类居住址。1974年以来，国家、省市有关部门对金牛山古人类遗址进行多次发掘，除发现78种哺乳动物化石外，还发现人类使用的打制石器、人类居住面和人类用火的痕迹。\n1984…整体感受是没达到预期，可考虑其他景点。二刷意愿：否。', '3%', 27);
INSERT INTO `travel_review` VALUES (24142, 'TR024142', '海南槟榔谷黎苗文化旅游区麻纺馆', '保亭', '海南', '城市漫游', '夏季', 5, 3, 1160.00, '是', 5, '5月去的海南槟榔谷黎苗文化旅游区麻纺馆，和朋友出行。地点在保亭，公交换乘方便，现场人流量适中。这次玩了3天，人均花费约1160元，历史文化气息浓。景点印象：景点本身有一定特色整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '0%', 113);
INSERT INTO `travel_review` VALUES (24143, 'TR024143', '乾明寺', '许昌', '河南', '拍照旅行', '春季', 2, 2, 584.00, '否', 4, '2月去的乾明寺，情侣出行。地点在许昌，打车比较省心，现场高峰时段比较拥挤。这次玩了2天，人均花费约584元，拍照很出片。景点印象：主体建筑占地15万平方米，被誉为“中州第一丛林”。\n乾明寺位于襄城县南1？？5公里首山之阴，故又称背影寺。创建于唐武德年间。后唐清泰元年(934年)僧省念禅师开山重修，明清两代历经修缮，规模雄伟，主体建筑占地15万平方米，被誉为“中州第一丛…整体感受是还蛮满意，推荐来看看。二刷意愿：否。', '0%', 55);
INSERT INTO `travel_review` VALUES (24144, 'TR024144', '封江生态旅游区', '随州', '湖北', '文化打卡', '春季', 1, 1, 748.00, '否', 5, '1月去的封江生态旅游区，和朋友出行。地点在随州，地铁到达方便，现场人不算多。这次玩了1天，人均花费约748元，拍照很出片。景点印象：封江水库两岸山峦连绵起伏，库汊水岛犬牙交错，形成了封江独具特色的库区风光。27公里长的水域犹如一幅画廊，14万亩山场四季如画：春季山花烂漫，映山红满山遍野；夏日绿树成荫，满目青翠；秋天叶红果熟，四处飘香；冬时雪压青松，银装素裹。库区上…整体感受是挺惊喜，以后还会来。二刷意愿：否。', '0%', 65);
INSERT INTO `travel_review` VALUES (24145, 'TR024145', '古城岛', '大兴安岭', '黑龙江', '城市漫游', '春季', 2, 1, 198.00, '否', 5, '2月去的古城岛，和家人出行。地点在大兴安岭，公交换乘方便，现场游客较多。这次玩了1天，人均花费约198元，氛围感不错。景点印象：它是黑龙江的第二大岛，曾经历经雅克萨战争的硝烟，见证康熙大帝抗击外敌的雄才伟略，如今的它，宁静淡泊，依偎于美丽的黑龙江上，享受着岁月的静美无边。整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '0%', 83);
