INSERT INTO `travel_review` VALUES (24161, 'TR024161', '凤凰山', '安康', '陕西', '亲子出游', '秋季', 6, 2, 721.00, '是', 4, '6月去的凤凰山，和朋友出行。地点在安康，公交换乘方便，现场人流量适中。这次玩了2天，人均花费约721元，夜景表现很好。景点印象：《兴安府志.凤凰山记》载：“陕之关南则见安阳之凤凰山，绵亘三百余里，势若游龙，即天下之名山，似难出其右者，盖此山上百仞芙蓉，朵朵活波，直逼青天，下有汉水迂，淙淙泉石，极桡幽韵，此亦终南一大名胜也。卧苍崖，荫栝柏，凭高远眺，但见忽聚…整体感受是还蛮满意，可以安排半天到一天。二刷意愿：是。', '0%', 44);
