INSERT INTO `travel_review` VALUES (24202, 'TR024202', '丙中洛茶马驿道', '怒江', '云南', '文化打卡', '夏季', 4, 2, 719.00, '否', 2, '4月去的丙中洛茶马驿道，和朋友出行。地点在怒江，地铁到达方便，现场人流量适中。这次玩了2天，人均花费约719元，历史文化气息浓。景点印象：丙中洛茶马驿道是一条从贡山通往西藏的人马驿道。驿道穿越青藏高原与云贵高原转换的整个地带。途中地形、地貌独特，风光优美，景色无以伦比，瀑布无数，珍稀生物繁多，且不乏危险。全程步行，约四－五天时间，到达西藏的察瓦洛。该人马驿道是当年解…整体感受是体验偏一般，建议谨慎前往。二刷意愿：否。', '1%', 48);
INSERT INTO `travel_review` VALUES (24203, 'TR024203', '明永冰川', '迪庆', '云南', '周末短途', '秋季', 7, 6, 1497.00, '否', 5, '7月去的明永冰川，情侣出行。地点在迪庆，地铁到达方便，现场人流量适中。这次玩了6天，人均花费约1497元，历史文化气息浓。景点印象：登上冰川观景台，近距离感受冰川和卡瓦格博的壮美。整体感受是特别满意，值得专门打卡。二刷意愿：否。', '3%', 70);
INSERT INTO `travel_review` VALUES (24204, 'TR024204', '梧州古墓群', '梧州', '广西', '周末短途', '冬季', 10, 6, 1500.00, '否', 3, '10月去的梧州古墓群，一个人出行。地点在梧州，地铁到达方便，现场人流量适中。这次玩了6天，人均花费约1500元，氛围感不错。景点印象：位于市区的云盖山、螺山、莲花山一带，范围较分散。墓葬年代多数是西汉、东汉和两晋时期的，出土文物有大量的陶器、铜器、瓷器等。这表明梧州自汉代以来就是中国南方地区的一座重镇。整体感受是中规中矩，按需选择。二刷意愿：否。', '0%', 48);
