INSERT INTO `travel_review` VALUES (24216, 'TR024216', '双溪', '自贡', '四川', '拍照旅行', '秋季', 7, 4, 853.00, '是', 5, '7月去的双溪，和朋友出行。地点在自贡，地铁到达方便，现场高峰时段比较拥挤。这次玩了4天，人均花费约853元，氛围感不错。景点印象：双溪，即梧枫水与寿水河这双溪汇合之处，是一个风水绝佳之地，位于荣县城西约2公里的旭水河源头。早年，这里有“书阁”，就是古荣州的图书馆；有“双溪王氏石穴”，就是北宋黄山谷题字的“地仙洞”，还有南宋诗人－容州通判陆游最喜爱的梅树。正是…整体感受是特别满意，很推荐。二刷意愿：是。', '0%', 56);
