INSERT INTO `travel_review` VALUES (24231, 'TR024231', '鄂豫皖苏区首府烈士陵园', '信阳', '河南', '城市漫游', '春季', 1, 3, 553.00, '否', 5, '1月去的鄂豫皖苏区首府烈士陵园，一个人出行。地点在信阳，自驾停车需要提前规划，现场游客较多。这次玩了3天，人均花费约553元，历史文化气息浓。景点印象：鄂豫皖苏区革命烈士陵园建于1957年、占地330亩由大门、烈士浮雕墙、烈士纪念碑、烈士纪念堂、革命斗争史陈列室、吴焕先半身塑像、烈士纪念亭、烈士墓地八大部分组成。\n大门 为现代建筑，园名由原国家主席李先念亲笔题写。\n烈士浮雕墙 用花岗岩雕塑…整体感受是超出预期，值得专门打卡。二刷意愿：否。', '0%', 42);
INSERT INTO `travel_review` VALUES (24232, 'TR024232', '紫霄宫', '十堰', '湖北', '城市漫游', '夏季', 3, 1, 386.00, '否', 4, '3月去的紫霄宫，和家人出行。地点在十堰，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约386元，夜景表现很好。景点印象：明代的“国家祈福之地”，紫宵大殿在明代只供皇帝朝拜，殿中的真武大帝等塑像都是明代的珍品。整体感受是体验挺好，可以安排半天到一天。二刷意愿：否。', '43%', 79);
