INSERT INTO `travel_review` VALUES (24234, 'TR024234', '玄素洞景区', '咸宁', '湖北', '城市漫游', '夏季', 5, 1, 688.00, '是', 5, '5月去的玄素洞景区，和朋友出行。地点在咸宁，公交换乘方便，现场人不算多。这次玩了1天，人均花费约688元，历史文化气息浓。景点印象：玄素洞是咸宁市首家国家AA级旅游景区。位于雪峰山下、陆水湖畔。因远古时有一玄素真人在此修炼而得名。洞长难度量。据《大清一统志》载：旧时有好事者裹粮入，信步趋出，相距百里余。该溶洞洞道幽深，千姿百态的钟乳石遍布洞中。目前已开发三千余米…整体感受是超出预期，以后还会来。二刷意愿：是。', '3%', 87);
