INSERT INTO `travel_review` VALUES (24257, 'TR024257', '祠堂山山野公园', '汕尾', '广东', '城市漫游', '冬季', 10, 1, 530.00, '是', 5, '10月去的祠堂山山野公园，和家人出行。地点在汕尾，公交换乘方便，现场游客较多。这次玩了1天，人均花费约530元，氛围感不错。景点印象：风景区包括南告水库、南万红维林和古莎椤自然保护区。南告水库由于自然风光 美，被称为“南天湖”。南告水库是截洪蓄水与引水发电双蒹的大型水库，库区周围群 山环抱，青山绿水，湖面如镜，水库拦水大坝建筑气势宏伟。\n南万红维林基地位于南万镇，…整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 92);
