INSERT INTO `travel_review` VALUES (24271, 'TR024271', '天国四王故里', '梧州', '广西', '深度游', '秋季', 6, 1, 423.00, '否', 2, '6月去的天国四王故里，和家人出行。地点在梧州，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约423元，拍照很出片。景点印象：是中国历史上太平天国农民革命运动忠王李秀成、英王陈玉成、耒王陆顺德、侍王李世贤等四王的故里，又是中共湄江游击队的革命根据地，故被划定为革命老区。四王故里，钟灵毓秀，美丽神奇。整体感受是没达到预期，建议谨慎前往。二刷意愿：否。', '0%', 71);
