INSERT INTO `travel_review` VALUES (24276, 'TR024276', '泗水塔', '南阳', '河南', '周末短途', '夏季', 3, 6, 1667.00, '否', 4, '3月去的泗水塔，情侣出行。地点在南阳，地铁到达方便，现场高峰时段比较拥挤。这次玩了6天，人均花费约1667元，夜景表现很好。景点印象：泗洲塔又称泗水塔，位于唐河县城东南隅菩提寺旧址内。宋绍圣二年（1095年）建，高47.33米。底层坐落在台基上，南面辟一拱形门，第二至十层每层各辟1门。下均置砖雕斗拱，转角处有风铎，檐下为平座，塔内有塔心柱，柱之周围筑盘88旋石阶踏道，第一层…整体感受是整体不错，推荐来看看。二刷意愿：否。', '0%', 82);
