INSERT INTO `travel_review` VALUES (24323, 'TR024323', '棋盘滩', '百色', '广西', '城市漫游', '春季', 2, 1, 433.00, '否', 5, '2月去的棋盘滩，一个人出行。地点在百色，打车比较省心，现场游客较多。这次玩了1天，人均花费约433元，历史文化气息浓。景点印象：棋盘滩风景区由棋盘滩、莲花山、寄情谷、独木成林、布洛佗石像等景点构成。棋盘滩是棋盘滩风景区的核心。棋盘滩形成于2亿多年前，是地壳运动过程中的产物。这种地质结构称为“剪节理”。这种地质结构方式许多地方都有，但一般来说别处都是在斜坡上…整体感受是挺惊喜，很推荐。二刷意愿：否。', '2%', 70);
