INSERT INTO `travel_review` VALUES (24355, 'TR024355', '锦阳湖生态园', '铜川', '陕西', '深度游', '春季', 12, 1, 816.00, '否', 3, '12月去的锦阳湖生态园，和朋友出行。地点在铜川，公交换乘方便，现场游客较多。这次玩了1天，人均花费约816元，拍照很出片。景点印象：锦阳湖生态园是“省级旅游风景区”和“国家水利风景区”。锦阳湖水域6千亩，湖岸延绵10多公里，与铜川境内的药王山、玉华宫等风景名胜古迹融为了秦北一条旅游热线，被誉为渭北旱塬上一颗璀璨明珠。\n作家贾平凹先生《废都》一书便是创作于此，其后重…整体感受是体验一般，别抱太高期待。二刷意愿：否。', '0%', 59);
INSERT INTO `travel_review` VALUES (24356, 'TR024356', '日土山洞古壁画', '阿里', '西藏', '深度游', '秋季', 6, 5, 962.00, '是', 4, '6月去的日土山洞古壁画，和朋友出行。地点在阿里，地铁到达方便，现场人不算多。这次玩了5天，人均花费约962元，氛围感不错。景点印象：日土山洞古壁画在日土县班公湖东北乌江河谷山沟内，山洞名“顶琼拉康”，高和宽各有4米左右，顶部和四周上画满各种国佛像和舞蹈人物。整体感受是还蛮满意，推荐来看看。二刷意愿：是。', '3%', 56);
