INSERT INTO `travel_review` VALUES (24368, 'TR024368', '陈胜墓', '商丘', '河南', '文化打卡', '夏季', 3, 6, 1249.00, '否', 5, '3月去的陈胜墓，和家人出行。地点在商丘，地铁到达方便，现场游客较多。这次玩了6天，人均花费约1249元，夜景表现很好。景点印象：中国历史上第一个农民起义领袖陈胜之墓，位于永城市东北芒砀山主峰西南麓。现存墓冢高5米，周长约50米。周围筑有青石围墙，高顶，下有须弥座，正中镌刻郭沫若书“秦末农民起义领袖陈胜之墓”。陈胜字涉，阳城人，秦二世元年（前209）被征屯戌渔阳，…整体感受是特别满意，以后还会来。二刷意愿：否。', '0%', 109);
