INSERT INTO `travel_review` VALUES (24372, 'TR024372', '永兴湖', '乌兰察布', '内蒙古', '文化打卡', '秋季', 7, 2, 222.00, '否', 5, '7月去的永兴湖，情侣出行。地点在乌兰察布，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约222元，氛围感不错。景点印象：永兴湖的形成距今有50多万年，有商业活动2000多年。永兴湖的山不高，湖水不大，但山水相映，秀丽多姿，群山环抱，湖面如镜，候鸟啼鸣，树影婆娑，空气清新，小河流水等绿色景观，以及篝火晚会，乡土文化，令人陶醉，流连忘返。钓鱼、爬山、游泳、划…整体感受是挺惊喜，以后还会来。二刷意愿：否。', '0%', 95);
