INSERT INTO `travel_review` VALUES (24393, 'TR024393', '九龙山', '邵阳', '湖南', '城市漫游', '夏季', 4, 2, 628.00, '否', 4, '4月去的九龙山，一个人出行。地点在邵阳，地铁到达方便，现场游客较多。这次玩了2天，人均花费约628元，氛围感不错。景点印象：九龙山海拔1142米，座落在县城东北面的岩口乡， 南距县城45公里，东距宝庆古城55公里。九龙山有一处古人石刻“不让武陵”。说明了其风景秀丽不亚于武陵源。这里竹木葱茏，巨石林立。在山的东面有人面狮头石，侧面看，活象仰面的高尔基在望天兴叹；…整体感受是体验挺好，周末来刚好。二刷意愿：否。', '0%', 87);
