INSERT INTO `travel_review` VALUES (24402, 'TR024402', '黄连河', '昭通', '云南', '周末短途', '冬季', 10, 4, 1300.00, '是', 4, '10月去的黄连河，和家人出行。地点在昭通，打车比较省心，现场人不算多。这次玩了4天，人均花费约1300元，历史文化气息浓。景点印象：黄连河瀑布群距县城5公里，有专线公路及中巴车直达景区。沿途山花烂漫、幽谷纵横、清泉奔涌、鸟语花香。主要景点有仙女瀑、情郎瀑、少女瀑、月老瀑、鸳鸯瀑、洞房瀑、相思瀑、对歌瀑、姊妹瀑、银链瀑、迎客瀑、寿星瀑、珠帘瀑及神秘莫测、千姿百态…整体感受是还蛮满意，推荐来看看。二刷意愿：是。', '6%', 78);
