INSERT INTO `travel_review` VALUES (24440, 'TR024440', '梧州古墓群', '梧州', '广西', '文化打卡', '冬季', 10, 2, 659.00, '否', 4, '10月去的梧州古墓群，一个人出行。地点在梧州，打车比较省心，现场人流量适中。这次玩了2天，人均花费约659元，夜景表现很好。景点印象：位于市区的云盖山、螺山、莲花山一带，范围较分散。墓葬年代多数是西汉、东汉和两晋时期的，出土文物有大量的陶器、铜器、瓷器等。这表明梧州自汉代以来就是中国南方地区的一座重镇。整体感受是还蛮满意，周末来刚好。二刷意愿：否。', '0%', 64);
