INSERT INTO `travel_review` VALUES (24476, 'TR024476', '群英湖', '焦作', '河南', '拍照旅行', '冬季', 9, 1, 773.00, '是', 5, '9月去的群英湖，情侣出行。地点在焦作，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约773元，拍照很出片。景点印象：群英湖风景名胜区地处太行山前沿，面积约25平方公里，跨越焦作市区、修武县、博爱县与山西省晋城市地界。 群英湖风景区内景点集中，分布均匀。河流、湖泊深秀，高山、峡谷险峻，悬崖、溶洞遍布，奇峰、怪石林立。有寺庙、古树，有台地、草坪，有丛…整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '0%', 71);
