INSERT INTO `travel_review` VALUES (24484, 'TR024484', '屈原碑林', '岳阳', '湖南', '城市漫游', '春季', 12, 1, 369.00, '否', 2, '12月去的屈原碑林，一个人出行。地点在岳阳，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约369元，夜景表现很好。景点印象：是汩罗市政府近年在屈原风景区进行的一项规模浩大、气势雄伟、结构恢宏的园林式工程。主体结构由离骚阁、天问坛、九歌台、九章馆、招魂堂等五个部分组成。以屈原忧国忧民、上下求索的爱国主义精神为主题，将屈原的全部作品串成一个整体。五个建筑均…整体感受是略失望，建议谨慎前往。二刷意愿：否。', '0%', 28);
