INSERT INTO `travel_review` VALUES (24491, 'TR024491', '紫团山', '长治', '山西', '文化打卡', '秋季', 7, 2, 587.00, '否', 4, '7月去的紫团山，和家人出行。地点在长治，地铁到达方便，现场人不算多。这次玩了2天，人均花费约587元，历史文化气息浓。景点印象：壶关有个避暑胜地叫紫团山。在壶关县东南60公里的树掌镇。紫团山又名翠微山，抱犊山。晋代旅游家抱朴子在游历了我国名山丽川后曾写道：“天下佳山者南五夷，北抱犊。”北抱犊山就是指的这里。因山腰有一形成于30万年前的天然溶洞，坐东面西，每天日…整体感受是整体不错，周末来刚好。二刷意愿：否。', '4%', 70);
