INSERT INTO `travel_review` VALUES (24494, 'TR024494', '史可法衣冠墓', '六安', '安徽', '拍照旅行', '春季', 2, 7, 1651.00, '是', 5, '2月去的史可法衣冠墓，情侣出行。地点在六安，地铁到达方便，现场高峰时段比较拥挤。这次玩了7天，人均花费约1651元，夜景表现很好。景点印象：明崇须十年七月至十二年夏（1637一1639），史可法任右金都御史，巡抚安庆、庐州、太平、池州四府及河南、湖广、江西邻近诸州、县，驻节六安州，与当时世居六安东乡的史姓有交往，追溯先祖原是同根，遂将可法分支归入六安史姓族谱系。史可法壮烈殉国…整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 75);
