INSERT INTO `travel_review` VALUES (24533, 'TR024533', '董氏砖雕墓', '临汾', '山西', '深度游', '秋季', 8, 3, 920.00, '是', 5, '8月去的董氏砖雕墓，情侣出行。地点在临汾，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了3天，人均花费约920元，历史文化气息浓。景点印象：在山西侯马市西北郊基建工地发现，1959年和1969年，分别迁于山西考古研究所候马工作站院内。墓主人一名董海，一名董明，先后于金明昌七年（1196年）和大安二年（1210年）埋葬。均为仿木构砖雕墓，平面皆方形。董海墓为前后两室，系我国北方地区传统…整体感受是特别满意，很推荐。二刷意愿：是。', '0%', 84);
