INSERT INTO `travel_review` VALUES (24541, 'TR024541', '冶父山', '巢湖', '安徽', '拍照旅行', '春季', 1, 1, 504.00, '是', 4, '1月去的冶父山，一个人出行。地点在巢湖，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约504元，拍照很出片。景点印象：冶父山，距庐江县城东约9公里，峰峦叠翠，庙宇辉煌，古迹遗存，佳传甚多，有\"江北小九华\"之称。据传春秋时，铸剑之父欧冶子曾在此山铸剑，山上存有铸剑池古迹，因此得名冶父山。诗人赞道：“长剑欲一淬，夜寻冶父山，揽衣望奇气，直在斗牛间。”\n冶…整体感受是整体不错，可以安排半天到一天。二刷意愿：是。', '0%', 70);
