INSERT INTO `travel_review` VALUES (24544, 'TR024544', '白鹭岛', '衢州', '浙江', '深度游', '夏季', 3, 1, 679.00, '否', 5, '3月去的白鹭岛，和家人出行。地点在衢州，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约679元，历史文化气息浓。景点印象：距衢州城东南18公里处有一村落，叫横溪村。风景空气清新。山水宜人，古木参天。村前有一片数白亩大的河滩，山面覆盖着茂密的树林，阳光丝丝透进，林间清流潺潺，村后是一座上百年古松，千年樟枫。这里常年栖息着上万只白鹭以及画眉，翠鸟，黄鹂，猫…整体感受是超出预期，很推荐。二刷意愿：否。', '0%', 75);
