INSERT INTO `travel_review` VALUES (24569, 'TR024569', '云龙湖旅游景区', '徐州', '江苏', '城市漫游', '夏季', 3, 3, 1170.00, '否', 5, '3月去的云龙湖旅游景区，和家人出行。地点在徐州，打车比较省心，现场人不算多。这次玩了3天，人均花费约1170元，历史文化气息浓。景点印象：景区内湖光山色，山水争辉，湖波浩渺，山色叠翠。整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '16%', 83);
INSERT INTO `travel_review` VALUES (24570, 'TR024570', '世界名泉观光区', '黑河', '黑龙江', '深度游', '春季', 2, 6, 1562.00, '是', 5, '2月去的世界名泉观光区，一个人出行。地点在黑河，自驾停车需要提前规划，现场人流量适中。这次玩了6天，人均花费约1562元，夜景表现很好。景点印象：世界名泉观光区位于五大连池风景区城区的中心部位，主要由南饮泉、北饮泉、翻花泉、二龙眼泉和相关的一些景点组成。南、北饮泉隔道相望，但两泉的口感却不一样，疗效也不一样。民谚有：南泉子睡觉，北泉子利尿。说的是饮南泉水主要对人的神经系统疾…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '16%', 73);
