INSERT INTO `travel_review` VALUES (24714, 'TR024714', '中卫高庙', '中卫', '宁夏', '亲子出游', '秋季', 8, 7, 1957.00, '是', 5, '8月去的中卫高庙，和朋友出行。地点在中卫，自驾停车需要提前规划，现场人不算多。这次玩了7天，人均花费约1957元，夜景表现很好。景点印象：一座建在高台上的寺庙，不大的面积内集中了260多间楼阁，极为紧凑有序。 三教合一，同时可以敬拜佛祖、玉帝和孔子、关老爷。整体感受是特别满意，很推荐。二刷意愿：是。', '21%', 110);
INSERT INTO `travel_review` VALUES (24715, 'TR024715', '天池', '陇南', '甘肃', '深度游', '春季', 2, 2, 660.00, '否', 5, '2月去的天池，情侣出行。地点在陇南，打车比较省心，现场人流量适中。这次玩了2天，人均花费约660元，拍照很出片。景点印象：天池在天魏山之中，有9道大湾108曲，汇成一泓形似葫芦的碧池。整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '3%', 87);
