INSERT INTO `travel_review` VALUES (24771, 'TR024771', '毕升森林公园', '黄冈', '湖北', '城市漫游', '冬季', 11, 1, 746.00, '否', 5, '11月去的毕升森林公园，情侣出行。地点在黄冈，自驾停车需要提前规划，现场人流量适中。这次玩了1天，人均花费约746元，历史文化气息浓。景点印象：毕升森林公园位于湖北省英山县城北郊，占地约一万亩，三十二处人文景点分布全园，自一九九八年建园以来，共接待游客近五十万人次。\n这里自然风光秀美：既有原始森林的恬静，又有现代都市的繁华；既有蓝天白云的广阔，又有小桥流水的温柔。这里人文…整体感受是挺惊喜，以后还会来。二刷意愿：否。', '0%', 109);
