INSERT INTO `travel_review` VALUES (24826, 'TR024826', '黄河(贵德段)', '海南藏族自治州', '青海', '亲子出游', '春季', 2, 2, 677.00, '是', 4, '2月去的黄河(贵德段)，情侣出行。地点在海南藏族自治州，打车比较省心，现场人流量适中。这次玩了2天，人均花费约677元，夜景表现很好。景点印象：黄河从贵德县西面的龙羊峡入境，经过拉西瓦峡谷、三河谷地从松巴峡出境，在贵德境内全长76.8公里，贵德的黄河水域清澈见底，有着浓烈的黄河风情。整体感受是体验挺好，可以安排半天到一天。二刷意愿：是。', '4%', 48);
