INSERT INTO `travel_review` VALUES (24837, 'TR024837', '西千佛洞', '酒泉', '甘肃', '亲子出游', '春季', 12, 3, 820.00, '否', 3, '12月去的西千佛洞，和朋友出行。地点在酒泉，打车比较省心，现场人不算多。这次玩了3天，人均花费约820元，夜景表现很好。景点印象：西千佛洞是敦惶佛教艺术体系的一部分，内塑佛像，四壁大多画着贤劫千佛、佛跌坐说法图等。整体感受是中规中矩，避开高峰更好。二刷意愿：否。', '20%', 78);
