INSERT INTO `travel_review` VALUES (25012, 'TR025012', '卓果特沁古城', '巴音郭楞', '新疆', '周末短途', '秋季', 6, 1, 288.00, '是', 5, '6月去的卓果特沁古城，情侣出行。地点在巴音郭楞，自驾停车需要提前规划，现场游客较多。这次玩了1天，人均花费约288元，氛围感不错。景点印象：位于轮台县城东南约20公里处，东汉至唐时代遗址，相传城为三重，城为土筑，略作圆形，周约1200米，城垣已颓，仅余高6～7米的土岗。中有一环形小湖，湖中心有一高台似为古代建筑遗址，南面有二小土丘，左边者似为仓库，右边者似为官署遗址。城东南隅…整体感受是特别满意，以后还会来。二刷意愿：是。', '0%', 48);
