INSERT INTO `travel_review` VALUES (25020, 'TR025020', '龟山公园', '迪庆', '云南', '城市漫游', '冬季', 10, 2, 774.00, '是', 5, '10月去的龟山公园，和家人出行。地点在迪庆，公交换乘方便，现场人流量适中。这次玩了2天，人均花费约774元，历史文化气息浓。景点印象：此园依山而建，日月城尽收眼底，公园内的龟山寺和转经筒，为公园里最具特色的建筑。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '11%', 52);
INSERT INTO `travel_review` VALUES (25021, 'TR025021', '空厢寺', '三门峡', '河南', '城市漫游', '秋季', 6, 7, 1726.00, '是', 5, '6月去的空厢寺，情侣出行。地点在三门峡，自驾停车需要提前规划，现场人不算多。这次玩了7天，人均花费约1726元，夜景表现很好。景点印象：空厢寺原名定林寺（又称熊耳山寺），位于陕县西李村乡的熊耳山下，距三门峡市约53公里。据清朝和民国的《陕州志》记载，佛教从东汉永平年间（公元58-75年）传入陕州时，修建了空厢寺，距今已1900多年，是与中国第一古刹白马寺同一时期的佛门圣地。\n…整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 91);
INSERT INTO `travel_review` VALUES (25022, 'TR025022', '杨莫岭森林公园', '朔州', '山西', '城市漫游', '春季', 2, 1, 604.00, '是', 5, '2月去的杨莫岭森林公园，和家人出行。地点在朔州，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约604元，夜景表现很好。景点印象：杨莫岭森林公园位于山西省朔州市山阴县马营庄乡地处山阴县东南部，东邻应县，西连本县后所乡，北毗本县古城镇，南接忻州市代县。距朔州市50公里，距大同市80公里，距太原市200公里，距首都北京400公里。\n杨莫岭森林公园地势南高北低，南部为山坡区…整体感受是特别满意，以后还会来。二刷意愿：是。', '0%', 76);
