INSERT INTO `travel_review` VALUES (25034, 'TR025034', '莲峰山', '定西', '甘肃', '亲子出游', '夏季', 3, 1, 735.00, '是', 5, '3月去的莲峰山，和朋友出行。地点在定西，打车比较省心，现场游客较多。这次玩了1天，人均花费约735元，历史文化气息浓。景点印象：位于县城东南34公里处的莲峰乡张家滩与古迹坪村之间，东望陇西、南眺漳县，面积198公顷，海拔2214-2441米。莲峰山地质为砂岩土石山体，系西秦岭地槽地带，山峦起伏，山体陡峻，植被良好，风景优美。莲峰山，因九峰环峙、状似莲花而得名，又因马鹿成…整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 64);
