INSERT INTO `travel_review` VALUES (25045, 'TR025045', '空厢寺', '三门峡', '河南', '城市漫游', '秋季', 7, 1, 293.00, '否', 5, '7月去的空厢寺，一个人出行。地点在三门峡，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约293元，夜景表现很好。景点印象：空厢寺原名定林寺（又称熊耳山寺），位于陕县西李村乡的熊耳山下，距三门峡市约53公里。据清朝和民国的《陕州志》记载，佛教从东汉永平年间（公元58-75年）传入陕州时，修建了空厢寺，距今已1900多年，是与中国第一古刹白马寺同一时期的佛门圣地。\n…整体感受是特别满意，很推荐。二刷意愿：否。', '0%', 73);
INSERT INTO `travel_review` VALUES (25046, 'TR025046', '金顶', '乐山', '四川', '周末短途', '秋季', 7, 1, 266.00, '否', 5, '7月去的金顶，情侣出行。地点在乐山，打车比较省心，现场游客较多。这次玩了1天，人均花费约266元，历史文化气息浓。景点印象：峨眉山的最高处，有震撼心灵的四面十方普贤菩萨金像。整体感受是特别满意，值得专门打卡。二刷意愿：否。', '31%', 86);
INSERT INTO `travel_review` VALUES (25047, 'TR025047', '朱然陈列馆', '马鞍山', '安徽', '拍照旅行', '秋季', 7, 3, 968.00, '是', 5, '7月去的朱然陈列馆，情侣出行。地点在马鞍山，地铁到达方便，现场游客较多。这次玩了3天，人均花费约968元，夜景表现很好。景点印象：朱然陈列馆位于安徽省马鞍山市区南部的雨山乡境内，为三国东吴大将朱然之墓。朱然墓发掘于1984年6月，出土许多珍贵文物，部分漆器填补了三国美术史的空白，也是已发掘东吴墓葬中墓主身份最高、墓葬规模最大的、时间最早的一座大墓，被列为80年代中…整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '25%', 112);
