INSERT INTO `travel_review` VALUES (25050, 'TR025050', '水泊梁山', '济宁', '山东', '拍照旅行', '秋季', 7, 3, 718.00, '是', 5, '7月去的水泊梁山，一个人出行。地点在济宁，公交换乘方便，现场游客较多。这次玩了3天，人均花费约718元，夜景表现很好。景点印象：在《水浒传》故事的发祥地游览梁山山寨，感受水浒文化。 欣赏水浒情景剧与民间艺术表演，去古刹莲台寺礼佛祈福。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '2%', 55);
INSERT INTO `travel_review` VALUES (25051, 'TR025051', '红格镇', '攀枝花', '四川', '城市漫游', '秋季', 6, 1, 448.00, '否', 3, '6月去的红格镇，一个人出行。地点在攀枝花，打车比较省心，现场人流量适中。这次玩了1天，人均花费约448元，夜景表现很好。景点印象：红格景区位于攀枝花市区东南部，距市区38公里，总面积174平方公里。景区内风光秀丽，加之居住着白、彝、傣、普米、回等少数民族，丰富多彩的民族风情给整个景区格外增色。\n红格温泉疗养区，距市中心38公里。红格温泉水温达摄氏58度，水质优良，对皮…整体感受是还可以，别抱太高期待。二刷意愿：否。', '3%', 65);
