INSERT INTO `travel_review` VALUES (25068, 'TR025068', '董永故里', '孝感', '湖北', '拍照旅行', '春季', 1, 1, 312.00, '是', 4, '1月去的董永故里，和朋友出行。地点在孝感，自驾停车需要提前规划，现场人不算多。这次玩了1天，人均花费约312元，拍照很出片。景点印象：在孝感市北郊。董永，文学故事人物。传为东汉千乘（今山东博兴）人。早年丧母。灵帝中平时（184-189），随父避兵，流落孝感，佃耕养父。父亡，无以葬，乃自卖为奴。其孝行感动仙女下凡，为其织锦偿债赎身，且与其结为夫妻。《灵芝篇》、《搜神记》…整体感受是整体不错，可以安排半天到一天。二刷意愿：是。', '0%', 59);
