INSERT INTO `travel_review` VALUES (25085, 'TR025085', '天坛山', '晋城', '山西', '拍照旅行', '夏季', 5, 1, 420.00, '否', 4, '5月去的天坛山，和家人出行。地点在晋城，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约420元，历史文化气息浓。景点印象：天坛山，又名阳洛山，位于市城区西北约31公里处，海拔1711米，为王屋山主峰。绝顶有坛。传为轩辕帝祈天之所，故名天坛；又因与东岳泰山鼎峙，谓之西顶，俗称老爷顶。天坛山高耸入云，独柱凌空。人们登上山顶，翘首太空，云霞眩目；远望黄河，细流如…整体感受是整体不错，可以安排半天到一天。二刷意愿：否。', '0%', 60);
