INSERT INTO `travel_review` VALUES (25103, 'TR025103', '金莲川草原', '锡林郭勒盟', '内蒙古', '城市漫游', '春季', 2, 2, 1009.00, '是', 5, '2月去的金莲川草原，情侣出行。地点在锡林郭勒盟，自驾停车需要提前规划，现场人流量适中。这次玩了2天，人均花费约1009元，氛围感不错。景点印象：金莲川草原位于内蒙古锡林郭勒盟南端的正蓝旗，草原东西长60公里，南北宽约20公里，是草原风光和蒙古族民族风情的有机结合。金莲川草原正蓝旗闪电河两岸的金莲花午前为花蕾，午后为花瓣，花大色黄，每年7月至8月是金莲花盛开的季节。金莲川草原曾经…整体感受是超出预期，很推荐。二刷意愿：是。', '1%', 54);
INSERT INTO `travel_review` VALUES (25104, 'TR025104', '龙津西西关大屋区', '广州', '广东', '拍照旅行', '夏季', 5, 1, 630.00, '是', 5, '5月去的龙津西西关大屋区，情侣出行。地点在广州，公交换乘方便，现场人流量适中。这次玩了1天，人均花费约630元，夜景表现很好。景点印象：曾经西关富商的住宅，青砖高墙满洲窗，是广州老式民居的代表，整体感受是挺惊喜，以后还会来。二刷意愿：是。', '10%', 67);
INSERT INTO `travel_review` VALUES (25105, 'TR025105', '灵通风景区', '漳州', '福建', '周末短途', '春季', 1, 7, 2087.00, '否', 4, '1月去的灵通风景区，和家人出行。地点在漳州，地铁到达方便，现场高峰时段比较拥挤。这次玩了7天，人均花费约2087元，氛围感不错。景点印象：欣赏世界第一天然大佛和飞瀑景观，去悬崖绝壁之上的灵通寺祈福。整体感受是还蛮满意，周末来刚好。二刷意愿：否。', '0%', 57);
INSERT INTO `travel_review` VALUES (25106, 'TR025106', '佛山祖庙', '佛山', '广东', '亲子出游', '春季', 12, 5, 1161.00, '否', 2, '12月去的佛山祖庙，和朋友出行。地点在佛山，公交换乘方便，现场人不算多。这次玩了5天，人均花费约1161元，拍照很出片。景点印象：佛山必游景点，三雕二塑的典型，黄飞鸿和叶问馆都在这里，还可以看武术和舞狮表演。整体感受是略失望，不建议高峰来。二刷意愿：否。', '31%', 26);
