INSERT INTO `travel_review` VALUES (25124, 'TR025124', '月亮湖', '衢州', '浙江', '拍照旅行', '春季', 2, 3, 639.00, '是', 5, '2月去的月亮湖，情侣出行。地点在衢州，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了3天，人均花费约639元，氛围感不错。景点印象：江山月亮湖是国家水利风景区、浙江省爱国主义教育基地、国家级蜂业示范区、国家级蜂产品基地。因座落在江山最有名的太阳山下，取阴阳对应和山水相映成趣而得名。\n旅游区内自然景观和人文景观都十分丰富。有旅游区出土的国家二级文物春秋时期的打击…整体感受是特别满意，很推荐。二刷意愿：是。', '0%', 60);
