INSERT INTO `travel_review` VALUES (25203, 'TR025203', '黄遵宪纪念馆', '梅州', '广东', '深度游', '秋季', 8, 1, 649.00, '否', 3, '8月去的黄遵宪纪念馆，和家人出行。地点在梅州，公交换乘方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约649元，拍照很出片。景点印象：清末爱国诗人黄遵宪的故居名为“人境庐”，坐落在梅州市东3公里处的周溪畔，庐舍内环境优美，曲径通幽，书香四溢。整体感受是中规中矩，别抱太高期待。二刷意愿：否。', '35%', 22);
