INSERT INTO `travel_review` VALUES (25218, 'TR025218', '天国四王故里', '梧州', '广西', '城市漫游', '秋季', 7, 2, 579.00, '是', 5, '7月去的天国四王故里，一个人出行。地点在梧州，地铁到达方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约579元，拍照很出片。景点印象：是中国历史上太平天国农民革命运动忠王李秀成、英王陈玉成、耒王陆顺德、侍王李世贤等四王的故里，又是中共湄江游击队的革命根据地，故被划定为革命老区。四王故里，钟灵毓秀，美丽神奇。整体感受是特别满意，以后还会来。二刷意愿：是。', '0%', 110);
