INSERT INTO `travel_review` VALUES (25248, 'TR025248', '佛光岩', '遵义', '贵州', '拍照旅行', '夏季', 4, 3, 894.00, '是', 5, '4月去的佛光岩，情侣出行。地点在遵义，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了3天，人均花费约894元，氛围感不错。景点印象：丹岩绝壁、奇峰异石、崖廓岩穴比比皆是、多不胜数，大地山崖呈现出红艳艳的赤红色彩。是我国丹霞地貌面积最大，出露最齐，特色最典型的景区。素有“世界丹霞之冠”、“世界丹霞第一园”之美誉。整体感受是超出预期，以后还会来。二刷意愿：是。', '12%', 136);
