INSERT INTO `travel_review` VALUES (25263, 'TR025263', '合水镇平北村', '阳江', '广东', '文化打卡', '冬季', 10, 1, 481.00, '否', 2, '10月去的合水镇平北村，和朋友出行。地点在阳江，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约481元，历史文化气息浓。景点印象：平北石山群峰：平北村位于阳春市合水镇北部，这里群山环绕着一个广阔草地，面积约1.2平方公里。该处具有典型的喀斯特岩溶地貌特征，一座座巍峨峻峭的石山群峰簇拥屏列，层峦叠翠，奇峰怪石状人状物，如剑锋，如石笋，如怪兽。山上许多溶洞奇形怪状…整体感受是略失望，不建议高峰来。二刷意愿：否。', '0%', 6);
