INSERT INTO `travel_review` VALUES (25273, 'TR025273', '双石牌坊', '眉山', '四川', '城市漫游', '春季', 2, 2, 625.00, '是', 4, '2月去的双石牌坊，一个人出行。地点在眉山，公交换乘方便，现场人不算多。这次玩了2天，人均花费约625元，夜景表现很好。景点印象：双石牌坊，位于仁寿县城东南部50余公里的禾加区中华乡牌坊村，距牌坊村小学东方200米，南北向，两坊上下对列，一条南北走向的石板大道贯穿其间。两坊间距44.5米，依所处地势由低到高分别编为一号坊和二号坊。\n一号坊建于清光绪七年（1882年），是…整体感受是还蛮满意，推荐来看看。二刷意愿：是。', '0%', 60);
