INSERT INTO `travel_review` VALUES (25302, 'TR025302', '阿古拉草原', '通辽', '内蒙古', '周末短途', '夏季', 3, 2, 995.00, '否', 5, '3月去的阿古拉草原，一个人出行。地点在通辽，自驾停车需要提前规划，现场人流量适中。这次玩了2天，人均花费约995元，夜景表现很好。景点印象：在科尔沁大草原腹地，保存着一块十分完整的原始草原――阿古拉草原旅游区，距通辽70公里，距大青沟100公里。蒙古族聚居比例达100%。\n阿古拉历史悠久，文化底蕴深厚，是远近闻名的“风水宝地”，1650年设“府”建旗，是一代名将僧格林沁的家乡，双合…整体感受是特别满意，值得专门打卡。二刷意愿：否。', '17%', 75);
