INSERT INTO `travel_review` VALUES (25330, 'TR025330', '铭德农业生态园', '钦州', '广西', '城市漫游', '冬季', 11, 2, 566.00, '是', 5, '11月去的铭德农业生态园，和朋友出行。地点在钦州，地铁到达方便，现场人不算多。这次玩了2天，人均花费约566元，历史文化气息浓。景点印象：铭德生态园位于钦州城东郊金海湾东大街，黎合江往市区走400米处，是南宁、北海、钦州港、三娘湾交通要道的交汇点。园区山青水秀，有铁索桥横跨湖中，山边竹木草棚，花香鸟语，集钓虾、烧烤、饮食、休闲、娱乐于一体，是旅游者周末的好去处。整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 89);
INSERT INTO `travel_review` VALUES (25331, 'TR025331', '三块石', '海南藏族自治州', '青海', '文化打卡', '春季', 2, 2, 578.00, '是', 5, '2月去的三块石，和家人出行。地点在海南藏族自治州，公交换乘方便，现场人流量适中。这次玩了2天，人均花费约578元，夜景表现很好。景点印象：三块石在湖的西南部，由密集在一起的白色石灰岩礁石组成，怪石峥嵘，远远望去，形似三块巨大的巨鼎屹立于波涛之中，水拍浪激，惊心动魄，现栖息于礁石上的鸟类数量已超过鸟岛。整体感受是挺惊喜，很推荐。二刷意愿：是。', '2%', 91);
