INSERT INTO `travel_review` VALUES (25372, 'TR025372', '阿古拉草原', '通辽', '内蒙古', '周末短途', '春季', 1, 2, 699.00, '否', 5, '1月去的阿古拉草原，和朋友出行。地点在通辽，公交换乘方便，现场人不算多。这次玩了2天，人均花费约699元，氛围感不错。景点印象：在科尔沁大草原腹地，保存着一块十分完整的原始草原――阿古拉草原旅游区，距通辽70公里，距大青沟100公里。蒙古族聚居比例达100%。\n阿古拉历史悠久，文化底蕴深厚，是远近闻名的“风水宝地”，1650年设“府”建旗，是一代名将僧格林沁的家乡，双合…整体感受是特别满意，以后还会来。二刷意愿：否。', '17%', 81);
