INSERT INTO `travel_review` VALUES (25442, 'TR025442', '金华山', '遂宁', '四川', '深度游', '夏季', 3, 1, 579.00, '否', 3, '3月去的金华山，情侣出行。地点在遂宁，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约579元，拍照很出片。景点印象：位于金华城北，为国家级重点风景名胜区。海拔150-1200米，绵延250平方公里，像一条长龙横卧于古婺大地。全年气候湿润、云雾缥缈，环境清凉宜人，并以林海莽原、奇异洞景和黄大仙真源为特色，被游客公认为休闲度假的仙游胜地。\n金华山洞奇、石怪、山…整体感受是中规中矩，避开高峰更好。二刷意愿：否。', '50%', 39);
