INSERT INTO `travel_review` VALUES (25554, 'TR025554', '太极湖村', '宣城', '安徽', '文化打卡', '春季', 12, 2, 719.00, '是', 5, '12月去的太极湖村，一个人出行。地点在宣城，自驾停车需要提前规划，现场游客较多。这次玩了2天，人均花费约719元，氛围感不错。景点印象：以砖雕门楼取胜的徽派古村，精细的砖雕能叠加到九层之多。 章氏宗祠木雕精美，里面的明代蟠龙香亭上，六条蟠龙栩栩如生。 整个村庄像幅太极图，4月可赏油菜花。整体感受是特别满意，以后还会来。二刷意愿：是。', '5%', 37);
