INSERT INTO `travel_review` VALUES (25565, 'TR025565', '大理古城', '大理', '云南', '文化打卡', '冬季', 11, 5, 1548.00, '否', 4, '11月去的大理古城，和朋友出行。地点在大理，打车比较省心，现场高峰时段比较拥挤。这次玩了5天，人均花费约1548元，拍照很出片。景点印象：享受苍山下的慢生活，逛小店、泡酒吧，品味文艺时尚的魅力古城。整体感受是整体不错，推荐来看看。二刷意愿：否。', '74%', 82);
INSERT INTO `travel_review` VALUES (25566, 'TR025566', '热瓦克佛教遗址', '和田', '新疆', '深度游', '秋季', 7, 1, 578.00, '是', 5, '7月去的热瓦克佛教遗址，情侣出行。地点在和田，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约578元，氛围感不错。景点印象：位于洛浦县城西北50多公里的大沙漠中，是著名的佛教文化遗址，自治区文物保护单位。是一组以佛塔为中心的佛寺建筑。\n佛寺为正方形，院中心有一座残高约10米的佛塔，因而得“热瓦克”之名。院墙内外，密布泥塑壁画，佛像最大的高达3米，虽已残缺，但…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 115);
INSERT INTO `travel_review` VALUES (25567, 'TR025567', '甘孜寺', '甘孜藏族自治州', '四川', '城市漫游', '冬季', 10, 1, 347.00, '否', 4, '10月去的甘孜寺，和朋友出行。地点在甘孜藏族自治州，公交换乘方便，现场人不算多。这次玩了1天，人均花费约347元，历史文化气息浓。景点印象：周边配套比较齐全整体感受是还蛮满意，可以安排半天到一天。二刷意愿：否。', '1%', 52);
