INSERT INTO `travel_review` VALUES (25569, 'TR025569', '乌兰木图山', '阜新', '辽宁', '城市漫游', '冬季', 11, 2, 779.00, '否', 2, '11月去的乌兰木图山，和朋友出行。地点在阜新，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了2天，人均花费约779元，拍照很出片。景点印象：阜蒙县八家子乡境内的乌兰木图山，早年叫阿力玛图山。两个名都是蒙语的音译，前者汉译为“有红色树木之山”，后者译为“有梨之山”。梨山之名更久。\n　　这座山的主峰叫锅底山，海拔高度831.4米，是阜新市第一高峰。站在主峰上近观远眺，收入眼帘的…整体感受是没达到预期，不建议高峰来。二刷意愿：否。', '0%', 44);
