INSERT INTO `travel_review` VALUES (25581, 'TR025581', '马攸木拉山垭口', '阿里', '西藏', '亲子出游', '冬季', 9, 4, 1104.00, '是', 5, '9月去的马攸木拉山垭口，和家人出行。地点在阿里，打车比较省心，现场人流量适中。这次玩了4天，人均花费约1104元，氛围感不错。景点印象：马攸木拉山垭口海拔5216米，是日喀则地区和阿里地区的地理分界。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '9%', 55);
INSERT INTO `travel_review` VALUES (25582, 'TR025582', '文庙', '临沧', '云南', '深度游', '夏季', 4, 2, 973.00, '是', 5, '4月去的文庙，情侣出行。地点在临沧，打车比较省心，现场人不算多。这次玩了2天，人均花费约973元，历史文化气息浓。景点印象：在凤庆县城西文庙街。由鸣凤阁、崇圣殿、大成殿、大成门、棂星门、龙门石坊、泮池等建筑组成。占地12000平方米。始建一明万历三十四年（1606年），清康熙八年（1669年）迁建。大成殿重檐歇山顶，面阔18.3米，进深13米，檐下悬\"圣集大成\"、\"斯文在兹…整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 83);
