INSERT INTO `travel_review` VALUES (25610, 'TR025610', '赛罕乌拉', '赤峰', '内蒙古', '深度游', '春季', 1, 4, 1078.00, '是', 5, '1月去的赛罕乌拉，情侣出行。地点在赤峰，地铁到达方便，现场人流量适中。这次玩了4天，人均花费约1078元，历史文化气息浓。景点印象：赛罕乌拉自然保护区是一个以保护森林、草原、湿地等多样生态系统和珍稀濒危野生动植物及西辽河上游水原涵养林为主的山地综合性自然保护区，总面积为10.04万公顷。\n该保护区2000年4月被国务院批准为国家级自然保护区，1999年被国际鸟类联盟确定为世…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 99);
