INSERT INTO `travel_review` VALUES (25644, 'TR025644', '雷台汉墓', '武威', '甘肃', '拍照旅行', '秋季', 6, 2, 456.00, '否', 2, '6月去的雷台汉墓，和家人出行。地点在武威，地铁到达方便，现场游客较多。这次玩了2天，人均花费约456元，氛围感不错。景点印象：是1969年10月在雷台下发现的一处东汉晚期的大型砖石墓葬，因出土了文物珍宝，中国旅游标志铜奔马而著名。雷台是古代祭祀雷神的地方，因在一高约十米的土台上建有明朝中期建造的雷祖观而得名。据出土马俑胸前铭文记载，雷台汉墓系“守张掖长张君”之…整体感受是没达到预期，不建议高峰来。二刷意愿：否。', '67%', 64);
