INSERT INTO `travel_review` VALUES (25664, 'TR025664', '马过河景区', '曲靖', '云南', '城市漫游', '秋季', 6, 2, 724.00, '是', 5, '6月去的马过河景区，和家人出行。地点在曲靖，地铁到达方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约724元，拍照很出片。景点印象：马龙县马过河风景名胜区地处滇中高原马龙县境内，由马过河、万亩草场、香炉山三个片区组成，共有37个景点，景区面积28平方公里。马过河风景名胜区以溪流平湖、陡壁峭岩、瀑布、跌水为特色，森林植被保存了滇中地区原生植被和生态景观，景区溪水、瀑…整体感受是超出预期，值得专门打卡。二刷意愿：是。', '0%', 96);
INSERT INTO `travel_review` VALUES (25665, 'TR025665', '南京城墙', '南京', '江苏', '城市漫游', '春季', 2, 4, 743.00, '否', 4, '2月去的南京城墙，和朋友出行。地点在南京，打车比较省心，现场人流量适中。这次玩了4天，人均花费约743元，拍照很出片。景点印象：世界上现存最长、规模最大、保存原真性最好的古代城垣整体感受是整体不错，周末来刚好。二刷意愿：否。', '1%', 87);
