INSERT INTO `travel_review` VALUES (25670, 'TR025670', '朝阳台', '渭南', '陕西', '亲子出游', '夏季', 4, 2, 553.00, '是', 5, '4月去的朝阳台，和朋友出行。地点在渭南，公交换乘方便，现场人流量适中。这次玩了2天，人均花费约553元，夜景表现很好。景点印象：朝阳台在东峰绝顶，因是太阳最先照耀的地方，又是游人观赏华山日出的最佳位置，故名。东峰也因此被称为朝阳峰。 台面积约十平方米，因崖势向外悬空伸出，从远处望去，如同鹰嘴。整体感受是特别满意，以后还会来。二刷意愿：是。', '2%', 99);
