INSERT INTO `travel_review` VALUES (25693, 'TR025693', '金莲洞风景区', '陇南', '甘肃', '拍照旅行', '冬季', 10, 3, 751.00, '是', 5, '10月去的金莲洞风景区，情侣出行。地点在陇南，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了3天，人均花费约751元，历史文化气息浓。景点印象：金莲洞位于成县店村乡新村仙洞湾山腰，一名华阳洞，洞阔400余米，入则渐小，约500米深处仍有一小洞，人不能入，深不可测。洞内密布钟乳石，多呈莲花状，故名。\n据载，元成宗元贞二年（1296年）至大德六年（1302年）间，道士刘道通、罗道隐者，在此…整体感受是特别满意，很推荐。二刷意愿：是。', '0%', 96);
