INSERT INTO `travel_review` VALUES (25719, 'TR025719', '青青生态度假村', '新乡', '河南', '周末短途', '冬季', 10, 3, 598.00, '否', 3, '10月去的青青生态度假村，情侣出行。地点在新乡，公交换乘方便，现场人流量适中。这次玩了3天，人均花费约598元，拍照很出片。景点印象：新乡市青青生态园位于新乡市凤泉区，由国家级文明村耿庄村2002年元月投资兴建，项目总投资5290万元，2003年国庆节正式营业。新乡市青青生态园是国家AA级旅游景点、全国首批农业旅游示范点。\n　　新乡市青青生态园是集高效农业、生态旅游、休闲度假…整体感受是体验一般，避开高峰更好。二刷意愿：否。', '0%', 68);
