INSERT INTO `travel_review` VALUES (25732, 'TR025732', '太极湖村', '宣城', '安徽', '文化打卡', '秋季', 7, 3, 709.00, '否', 4, '7月去的太极湖村，情侣出行。地点在宣城，地铁到达方便，现场人流量适中。这次玩了3天，人均花费约709元，历史文化气息浓。景点印象：以砖雕门楼取胜的徽派古村，精细的砖雕能叠加到九层之多。 章氏宗祠木雕精美，里面的明代蟠龙香亭上，六条蟠龙栩栩如生。 整个村庄像幅太极图，4月可赏油菜花。整体感受是体验挺好，可以安排半天到一天。二刷意愿：否。', '5%', 77);
