INSERT INTO `travel_review` VALUES (25740, 'TR025740', '双湖', '那曲', '西藏', '城市漫游', '秋季', 7, 2, 896.00, '是', 4, '7月去的双湖，和家人出行。地点在那曲，公交换乘方便，现场人不算多。这次玩了2天，人均花费约896元，氛围感不错。景点印象：蒙语为“胡尔巴努尔”意为“双湖”，地处喀纳斯湖西岸―恰其阿依特山南坡河谷中，北西走向，呈椭圆状，由相隔三百米左右的两个狭长小湖串连构成，长1200米，宽度不等，一般在300m左右，湖面积1.4km2，海拔1498米。整体感受是体验挺好，周末来刚好。二刷意愿：是。', '1%', 53);
