INSERT INTO `travel_review` VALUES (25773, 'TR025773', '司徒小镇', '晋城', '山西', '城市漫游', '秋季', 6, 3, 1019.00, '是', 5, '6月去的司徒小镇，一个人出行。地点在晋城，地铁到达方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约1019元，氛围感不错。景点印象：漫步古色古香的小镇，欣赏震撼人心的千人打铁花表演，感受穿越千年的山西味道。整体感受是特别满意，很推荐。二刷意愿：是。', '2%', 103);
INSERT INTO `travel_review` VALUES (25774, 'TR025774', '鄂豫皖苏区首府烈士陵园', '信阳', '河南', '城市漫游', '秋季', 7, 4, 988.00, '是', 5, '7月去的鄂豫皖苏区首府烈士陵园，和朋友出行。地点在信阳，公交换乘方便，现场游客较多。这次玩了4天，人均花费约988元，夜景表现很好。景点印象：鄂豫皖苏区革命烈士陵园建于1957年、占地330亩由大门、烈士浮雕墙、烈士纪念碑、烈士纪念堂、革命斗争史陈列室、吴焕先半身塑像、烈士纪念亭、烈士墓地八大部分组成。\n大门 为现代建筑，园名由原国家主席李先念亲笔题写。\n烈士浮雕墙 用花岗岩雕塑…整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 75);
