INSERT INTO `travel_review` VALUES (25815, 'TR025815', '多宝佛塔话珍奇', '襄阳', '湖北', '城市漫游', '夏季', 5, 1, 845.00, '否', 2, '5月去的多宝佛塔话珍奇，和家人出行。地点在襄阳，打车比较省心，现场人不算多。这次玩了1天，人均花费约845元，历史文化气息浓。景点印象：距隆中一箭之遥，有一座寺庙，叫广德寺。它离山不远，在一片空旷的田野上。南望，是巍巍清山，北眺，是滔滔汉水。寺院方方正正，四外有整整齐齐的护寺河，除东山门外，别处进不了寺院。这恐怕是其它很多寺院所没有的。此寺以刹深殿高而著称于世，更…整体感受是略失望，不建议高峰来。二刷意愿：否。', '22%', 26);
