INSERT INTO `travel_review` VALUES (25863, 'TR025863', '常德诗墙博物馆', '常德', '湖南', '城市漫游', '春季', 1, 5, 1333.00, '是', 5, '1月去的常德诗墙博物馆，和朋友出行。地点在常德，公交换乘方便，现场人流量适中。这次玩了5天，人均花费约1333元，拍照很出片。景点印象：常德市古名武陵，建城两千余年，素称文物之邦。在改革开放和社会主义建设新时期，国家投资一亿多元，修建长达三公里的城区防洪大堤，保护这座历史名城。中共常德市委、市人民政府决定以此为契机，以大堤一万四千多平米的墙面为载体，兴建一座旨在弘…整体感受是超出预期，以后还会来。二刷意愿：是。', '5%', 79);
