INSERT INTO `travel_review` VALUES (25878, 'TR025878', '扶苏墓', '榆林', '陕西', '城市漫游', '春季', 2, 3, 857.00, '否', 5, '2月去的扶苏墓，情侣出行。地点在榆林，打车比较省心，现场人不算多。这次玩了3天，人均花费约857元，夜景表现很好。景点印象：扶苏墓位于绥德县城疏属山。扶苏（？--公元前210年），秦始皇长子。贤良明达，颇得众望，始皇三士五年，秦始皇“焚书坑儒”，在咸阳坑杀儒生460多人，引起扶苏犹虑，及时进谏：“天下初定，远方黔首未集，诸生皆诵法孔子，今以重法绳之，臣恐天下不…整体感受是超出预期，值得专门打卡。二刷意愿：否。', '1%', 73);
