INSERT INTO `travel_review` VALUES (25888, 'TR025888', '磨盘山', '吉林市', '吉林', '拍照旅行', '夏季', 4, 6, 1508.00, '否', 2, '4月去的磨盘山，一个人出行。地点在吉林市，自驾停车需要提前规划，现场人不算多。这次玩了6天，人均花费约1508元，氛围感不错。景点印象：磨盘山又叫小磨盘山，在丰满区前二道乡王相村境内。距市区15公里，总面积10平方公里。磨盘山顶峰形状如磨盘，因此而得名。该山南北走向，南北峰对峙，南侧面为长山顶，北侧为尖山顶。北侧主峰海拔783.8米。磨盘山山势陡峻。峰奇石秀，林木茂密，狼…整体感受是略失望，可考虑其他景点。二刷意愿：否。', '0%', 76);
