INSERT INTO `travel_review` VALUES (25891, 'TR025891', '中国长寿城', '眉山', '四川', '亲子出游', '夏季', 5, 3, 1042.00, '是', 5, '5月去的中国长寿城，情侣出行。地点在眉山，公交换乘方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约1042元，拍照很出片。景点印象：彭山，是汉张纲晋李密的故乡，城市雕塑\"忠孝之邦\"，成为彭山人弘扬传统美德的警示与见证；彭山，是古代长寿老人彭祖的生栖之地，长寿文化源远流长，据全国第四次人口普查表明，彭山百岁老人的比例高出全国平均水平的17倍；彭山，是世界茶叶的发源地…整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '0%', 78);
