INSERT INTO `travel_review` VALUES (25894, 'TR025894', '梦幻锦江', '铜仁', '贵州', '亲子出游', '春季', 12, 2, 432.00, '是', 4, '12月去的梦幻锦江，一个人出行。地点在铜仁，地铁到达方便，现场游客较多。这次玩了2天，人均花费约432元，拍照很出片。景点印象：“梦幻锦江”依托三江公园，把锦江两岸自然景观和人文景观用现代灯光先进技术与艺术手段巧妙融合，突出景观特色，集休闲、娱乐、游览等功能为一体。以清新、优美的自然风光与文化景观创造出梦幻般的意境。整体感受是还蛮满意，可以安排半天到一天。二刷意愿：是。', '2%', 73);
