INSERT INTO `travel_review` VALUES (25946, 'TR025946', '石博园', '珠海', '广东', '拍照旅行', '春季', 12, 4, 797.00, '是', 5, '12月去的石博园，一个人出行。地点在珠海，公交换乘方便，现场人不算多。这次玩了4天，人均花费约797元，夜景表现很好。景点印象：独树一帜的石文化主题公园，植被资源丰富，园内多奇峰异石。整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 78);
INSERT INTO `travel_review` VALUES (25947, 'TR025947', '茨坪毛泽东同志旧居', '吉安', '江西', '亲子出游', '秋季', 7, 3, 946.00, '是', 5, '7月去的茨坪毛泽东同志旧居，和家人出行。地点在吉安，地铁到达方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约946元，历史文化气息浓。景点印象：这里原是一栋农民的住房。1927年10月27日,毛泽东率领湘赣边界秋收起义部队来到茨坪就居住在这里。到1929年1月的一年多时间里,毛泽东每到茨坪就在这栋房子的中厅右后间居住和办公。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '2%', 57);
INSERT INTO `travel_review` VALUES (25948, 'TR025948', '珍珠泉', '济南', '山东', '城市漫游', '夏季', 5, 3, 848.00, '是', 5, '5月去的珍珠泉，和朋友出行。地点在济南，自驾停车需要提前规划，现场游客较多。这次玩了3天，人均花费约848元，历史文化气息浓。景点印象：济南四大名泉之一，自池底涌出的一串串气泡美如珍珠。 环境清幽的院落，来此赏泉、散步、喂鲤鱼，惬意悠闲。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '8%', 115);
INSERT INTO `travel_review` VALUES (25949, 'TR025949', '鹿峰山风景区', '玉林', '广西', '周末短途', '夏季', 5, 5, 1418.00, '否', 3, '5月去的鹿峰山风景区，情侣出行。地点在玉林，自驾停车需要提前规划，现场人不算多。这次玩了5天，人均花费约1418元，氛围感不错。景点印象：这里有秀美的山水之景，更有别致的“地球心脏”溶洞景观。整体感受是体验一般，避开高峰更好。二刷意愿：否。', '12%', 57);
INSERT INTO `travel_review` VALUES (25950, 'TR025950', '长春水库', '安庆', '安徽', '拍照旅行', '秋季', 7, 4, 1196.00, '是', 5, '7月去的长春水库，和家人出行。地点在安庆，打车比较省心，现场人不算多。这次玩了4天，人均花费约1196元，氛围感不错。景点印象：周边配套比较齐全整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 97);
INSERT INTO `travel_review` VALUES (25951, 'TR025951', '陆九渊之墓', '抚州', '江西', '城市漫游', '春季', 1, 2, 534.00, '否', 4, '1月去的陆九渊之墓，一个人出行。地点在抚州，公交换乘方便，现场人流量适中。这次玩了2天，人均花费约534元，拍照很出片。景点印象：座落于金溪县陆坊乡青田村东山上，1957年被列为江西省省级保护文物。陆九渊，字子静，号象山，陆坊乡青田人，是南宋时与朱熹双峰对峙的理学大师、哲学家、教育家，在历史上有深远影响。其理学又称“心学”，提出“心即理”、“宇宙便是吾心，吾心便…整体感受是还蛮满意，周末来刚好。二刷意愿：否。', '0%', 76);
INSERT INTO `travel_review` VALUES (25952, 'TR025952', '童乐(文卫南路店)', '乌兰察布', '内蒙古', '拍照旅行', '春季', 12, 6, 1919.00, '是', 5, '12月去的童乐(文卫南路店)，和家人出行。地点在乌兰察布，打车比较省心，现场高峰时段比较拥挤。这次玩了6天，人均花费约1919元，夜景表现很好。景点印象：整体环境还算干净整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 63);
INSERT INTO `travel_review` VALUES (25953, 'TR025953', '锦阳湖生态园', '铜川', '陕西', '周末短途', '冬季', 10, 4, 1015.00, '否', 5, '10月去的锦阳湖生态园，和家人出行。地点在铜川，公交换乘方便，现场高峰时段比较拥挤。这次玩了4天，人均花费约1015元，氛围感不错。景点印象：锦阳湖生态园是“省级旅游风景区”和“国家水利风景区”。锦阳湖水域6千亩，湖岸延绵10多公里，与铜川境内的药王山、玉华宫等风景名胜古迹融为了秦北一条旅游热线，被誉为渭北旱塬上一颗璀璨明珠。\n作家贾平凹先生《废都》一书便是创作于此，其后重…整体感受是特别满意，以后还会来。二刷意愿：否。', '0%', 71);
