INSERT INTO `travel_review` VALUES (25957, 'TR025957', '芦庄清真寺', '廊坊', '河北', '拍照旅行', '夏季', 3, 4, 1430.00, '是', 4, '3月去的芦庄清真寺，和朋友出行。地点在廊坊，公交换乘方便，现场高峰时段比较拥挤。这次玩了4天，人均花费约1430元，拍照很出片。景点印象：史记明永乐年间，燕王朱棣扫北，何氏祖先曾随燕王征战，屡建战功，受封武德将军。后迁至大厂县芦庄定居，并兴建清真寺。该寺经历修缮，1999年回族群众又集资重建。现在清真寺大殿为宫殿式建筑。大殿居中两面三刀旁南北讲堂相对，后殿凹壁，外角楼屹…整体感受是还蛮满意，推荐来看看。二刷意愿：是。', '0%', 41);
