INSERT INTO `travel_review` VALUES (26020, 'TR026020', '东狮山', '宁德', '福建', '城市漫游', '秋季', 8, 4, 1415.00, '是', 5, '8月去的东狮山，和家人出行。地点在宁德，自驾停车需要提前规划，现场人流量适中。这次玩了4天，人均花费约1415元，氛围感不错。景点印象：东狮山是太姥山脉的主峰，海拔1480米，气势雄伟。东狮山属花岗岩地貌，岩体、岩洞千姿百态。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 84);
