INSERT INTO `travel_review` VALUES (26022, 'TR026022', '于国故城', '焦作', '河南', '深度游', '夏季', 5, 1, 342.00, '否', 5, '5月去的于国故城，和朋友出行。地点在焦作，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约342元，夜景表现很好。景点印象：于国故城位于沁阳县西北15公里于邰村东。于国是商代鄂侯封地。西周时期，鄂侯南迁，周武王将此地分封给其子于叔。《史记》徐广注、《水经注》、《河内县志》等均有记载。现遗址仅存北墙，东西长820米，宽17-22米，高2-7米。目前，对该遗址尚未进行…整体感受是超出预期，很推荐。二刷意愿：否。', '0%', 85);
