INSERT INTO `travel_review` VALUES (26044, 'TR026044', '龙山', '莱芜', '山东', '城市漫游', '夏季', 5, 2, 546.00, '否', 3, '5月去的龙山，一个人出行。地点在莱芜，公交换乘方便，现场人不算多。这次玩了2天，人均花费约546元，拍照很出片。景点印象：山东龙山风景区，位于莱芜市莱城区东北茶业口镇境内，总面积 240 万平方米。龙山因其独特的自然形态而得名。当你登山观望，蜿蜒起伏的自然山势，犹如一条巨龙静静盘卧，山脚下的龙潭，恰似一颗镶嵌在崇山峻岭中的明珠，形成相为呼应，蔚为壮观的“…整体感受是还可以，别抱太高期待。二刷意愿：否。', '0%', 79);
