INSERT INTO `travel_review` VALUES (26051, 'TR026051', '云石山', '赣州', '江西', '深度游', '秋季', 6, 2, 322.00, '是', 5, '6月去的云石山，和家人出行。地点在赣州，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约322元，拍照很出片。景点印象：云石山位于瑞金市西南15公里。1934年7月临时中央政府从沙洲坝迁驻此地小山上的云山古寺，山中风景优美。1934年10月，中央机关编为红军中央纵队，从云石山出发开始长征，因而云石山被称为“长征第一山”。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 65);
