INSERT INTO `travel_review` VALUES (26053, 'TR026053', '聚星塔', '抚州', '江西', '周末短途', '冬季', 10, 3, 723.00, '是', 2, '10月去的聚星塔，一个人出行。地点在抚州，打车比较省心，现场高峰时段比较拥挤。这次玩了3天，人均花费约723元，历史文化气息浓。景点印象：为省级重点保护文物，始建于明万历四十二年（1614年），重修于乾隆十九年（1754年）。塔高30米，共7层，呈八角形，塔檐锯齿形，塔身自下而上逐层内收，叠托而上，基部砖石皆用糯米汁浇浆垒砌而成，塔梯在内外塔身夹墙之中，分左右盘旋而上，全塔根…整体感受是没达到预期，可考虑其他景点。二刷意愿：是。', '0%', 63);
