INSERT INTO `travel_review` VALUES (26068, 'TR026068', '太极湖村', '宣城', '安徽', '拍照旅行', '冬季', 9, 1, 475.00, '是', 5, '9月去的太极湖村，一个人出行。地点在宣城，公交换乘方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约475元，夜景表现很好。景点印象：以砖雕门楼取胜的徽派古村，精细的砖雕能叠加到九层之多。 章氏宗祠木雕精美，里面的明代蟠龙香亭上，六条蟠龙栩栩如生。 整个村庄像幅太极图，4月可赏油菜花。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '5%', 92);
