INSERT INTO `travel_review` VALUES (26076, 'TR026076', '仙人府', '娄底', '湖南', '周末短途', '秋季', 7, 1, 127.00, '是', 5, '7月去的仙人府，和家人出行。地点在娄底，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约127元，夜景表现很好。景点印象：仙人府主要景点有洞中飞瀑长寿瀑，洞中一线天，世间绝景三孔立交仙人桥、洞内舞厅、南天门、东方维纳斯等。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '7%', 48);
INSERT INTO `travel_review` VALUES (26077, 'TR026077', '壶头峡漂流', '咸宁', '湖北', '拍照旅行', '夏季', 5, 2, 972.00, '否', 5, '5月去的壶头峡漂流，情侣出行。地点在咸宁，打车比较省心，现场人流量适中。这次玩了2天，人均花费约972元，历史文化气息浓。景点印象：壶头峡漂流河流两岸风景如画，袅袅炊烟升起，小桥流水人家，山路十八弯，水路九连环，翠竹密布，植被繁茂，春华秋实，四季景异，美不胜收。整体感受是超出预期，以后还会来。二刷意愿：否。', '0%', 67);
