INSERT INTO `travel_review` VALUES (26079, 'TR026079', '鼓城山自然保护区', '广元', '四川', '周末短途', '秋季', 7, 1, 357.00, '否', 2, '7月去的鼓城山自然保护区，和朋友出行。地点在广元，地铁到达方便，现场游客较多。这次玩了1天，人均花费约357元，夜景表现很好。景点印象：鼓城山景区为省级风景名胜区，位于广元市旺苍县北部鼓城乡境内，距县城63公里，由鼓城山、七里峡、白龙宫三大景区组成，面积100平方公里。这里属米仓山系西段，为构造侵蚀、溶蚀中的地貌，最高点东鼓城海拔2073米，最低点关口垭河谷海拔880米。\n鼓…整体感受是没达到预期，可考虑其他景点。二刷意愿：否。', '0%', 54);
