INSERT INTO `travel_review` VALUES (26095, 'TR026095', '白鹭岛', '衢州', '浙江', '亲子出游', '夏季', 4, 2, 848.00, '否', 5, '4月去的白鹭岛，情侣出行。地点在衢州，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约848元，氛围感不错。景点印象：距衢州城东南18公里处有一村落，叫横溪村。风景空气清新。山水宜人，古木参天。村前有一片数白亩大的河滩，山面覆盖着茂密的树林，阳光丝丝透进，林间清流潺潺，村后是一座上百年古松，千年樟枫。这里常年栖息着上万只白鹭以及画眉，翠鸟，黄鹂，猫…整体感受是特别满意，以后还会来。二刷意愿：否。', '0%', 58);
