INSERT INTO `travel_review` VALUES (26134, 'TR026134', '摩天岭', '威海', '山东', '拍照旅行', '冬季', 11, 3, 902.00, '是', 5, '11月去的摩天岭，和家人出行。地点在威海，地铁到达方便，现场人不算多。这次玩了3天，人均花费约902元，历史文化气息浓。景点印象：体验亚洲最长的跨海索道，凭栏观海，体验云间穿梭，俯视碧海仙境。整体感受是挺惊喜，很推荐。二刷意愿：是。', '3%', 48);
INSERT INTO `travel_review` VALUES (26135, 'TR026135', '女娲城址', '周口', '河南', '深度游', '秋季', 8, 4, 918.00, '是', 5, '8月去的女娲城址，和家人出行。地点在周口，公交换乘方便，现场游客较多。这次玩了4天，人均花费约918元，氛围感不错。景点印象：女娲，是我国古代神话传说中的人类始祖，她抟泥为人、化育万物、炼石补天并发明了笙簧乐器，对此《世本作篇》留有记载。《说文》曰：“娲，古之神圣女，化万物者也”。中国考古学者认为，古代传说中的女娲氏是部落首领，属仰韶文化，当在六七年之前…整体感受是超出预期，很推荐。二刷意愿：是。', '33%', 96);
