INSERT INTO `travel_review` VALUES (26148, 'TR026148', '侗文化城', '怀化', '湖南', '深度游', '夏季', 5, 2, 669.00, '是', 5, '5月去的侗文化城，一个人出行。地点在怀化，打车比较省心，现场人不算多。这次玩了2天，人均花费约669元，夜景表现很好。景点印象：湖南怀化中国侗文化城位于芷江侗族自治县象狮坡省级森林公园内，距怀化市中心6公里，西到芷江抗战胜利受降纪念馆20余公里，南连舞水河，北靠湘黔铁路和320国道，区位、交通条件十分优越。该景区占地3500亩，阳光、松林、溪流、草滩构成了这里独特而…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '2%', 87);
