INSERT INTO `travel_review` VALUES (26156, 'TR026156', '清代立交桥', '雅安', '四川', '深度游', '冬季', 11, 2, 323.00, '是', 5, '11月去的清代立交桥，情侣出行。地点在雅安，打车比较省心，现场高峰时段比较拥挤。这次玩了2天，人均花费约323元，历史文化气息浓。景点印象：高桥建于清乾十四年。为三卷拱桥，桥下东西两端各有一人行道，桥上、桥下东西两端各有一人行道，桥上、桥下皆可通行，又称清代立交桥。整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 31);
