INSERT INTO `travel_review` VALUES (26210, 'TR026210', '高贵三潭', '随州', '湖北', '周末短途', '夏季', 4, 1, 160.00, '是', 4, '4月去的高贵三潭，和朋友出行。地点在随州，自驾停车需要提前规划，现场人不算多。这次玩了1天，人均花费约160元，拍照很出片。景点印象：高贵三潭风景区位于广水市北部，这里有清奇幽深的三叠瀑布\"一线天\"；闻名遐迩的雄关古道平靖关；碧波万顷的许家冲水库；峻险的鄂北第一峰大贵寺金顶，海拔908米；还有千姿百态、惟妙惟肖的\"双狮夺珠\"石，碧玉湖，天池，龙眼圣水井，罗汉池。这里林…整体感受是还蛮满意，可以安排半天到一天。二刷意愿：是。', '0%', 83);
