INSERT INTO `travel_review` VALUES (26248, 'TR026248', '马家大院', '晋中', '山西', '周末短途', '夏季', 3, 2, 586.00, '是', 5, '3月去的马家大院，一个人出行。地点在晋中，地铁到达方便，现场人流量适中。这次玩了2天，人均花费约586元，夜景表现很好。景点印象：马家大院位于古城窑场街的北马家巷，是“平遥四大家族”之首、清代巨商马中选的故居,是清代建筑装饰风格的典范,是极富艺术魅力的民宅建筑群,被誉为“平遥第一大院”。整体感受是超出预期，很推荐。二刷意愿：是。', '1%', 76);
