INSERT INTO `travel_review` VALUES (26252, 'TR026252', '巧家药山', '昭通', '云南', '周末短途', '秋季', 8, 1, 508.00, '是', 5, '8月去的巧家药山，一个人出行。地点在昭通，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约508元，氛围感不错。景点印象：药山位于巧家县境内。金沙江和牛栏江环山而过。药山山体面积220平方公里，主峰金顶山海拔4042米，雄踞于昭通群峰之上。\n由于受北―东向构成控制发育成型，药山走向近于北―东。西坡地势陡峭，悬崖绝壁从两江汇流的谷地中凌宵而起，柱地擎天，高不可…整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 90);
