INSERT INTO `travel_review` VALUES (26259, 'TR026259', '闵子骞祠', '宿州', '安徽', '亲子出游', '夏季', 3, 1, 426.00, '否', 5, '3月去的闵子骞祠，和朋友出行。地点在宿州，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约426元，历史文化气息浓。景点印象：闵子骞祠及墓座落在曹村镇闵祠村。三面环山，泉水涌流，环境幽雅。紧傍206国道，交通便利。是我市重点名胜古迹之一，为省级重点文物保护单位。\n闵子名损，字子骞，春秋鲁国人，孔子弟子，名列七十二贤之首，德与颜渊齐名。闵子以孝名天下，孔子赞曰…整体感受是超出预期，以后还会来。二刷意愿：否。', '0%', 115);
