INSERT INTO `travel_review` VALUES (26272, 'TR026272', '龙神沟', '陇南', '甘肃', '文化打卡', '冬季', 9, 2, 478.00, '否', 2, '9月去的龙神沟，和家人出行。地点在陇南，地铁到达方便，现场人不算多。这次玩了2天，人均花费约478元，夜景表现很好。景点印象：龙神沟距县城约70千米。这里的风景美在峡谷，峡谷间有一龙头巨崖，伸向龙神河，故有龙神沟之称。龙神沟夹在两峰之间，跌入谷底深涧，有蓊郁的密林笼罩其上，只听水声淙淙，不见流水滟滟，藏龙卧虎，神奇奥秘。\n漫山遍野的森林，亭亭玉立，秀美至极…整体感受是体验偏一般，可考虑其他景点。二刷意愿：否。', '0%', 28);
