INSERT INTO `travel_review` VALUES (26292, 'TR026292', '钦州坭兴陶艺有限公司', '钦州', '广西', '深度游', '秋季', 7, 1, 391.00, '否', 5, '7月去的钦州坭兴陶艺有限公司，情侣出行。地点在钦州，自驾停车需要提前规划，现场人流量适中。这次玩了1天，人均花费约391元，拍照很出片。景点印象：广西工业旅游示范点,是一家集坭兴陶工艺品研究、开发、生产、经营于一体的实体。主要通过以公司化运作为载体，拯救和发扬光大“钦州坭兴”这一具有千年历史的文化瑰宝而创建。产品以中、高档次的旅游工艺品、礼品、和高附加值的艺术藏品为主。2000…整体感受是超出预期，值得专门打卡。二刷意愿：否。', '0%', 107);
