INSERT INTO `travel_review` VALUES (26325, 'TR026325', '爱珲历史陈列馆', '黑河', '黑龙江', '文化打卡', '冬季', 9, 1, 202.00, '是', 5, '9月去的爱珲历史陈列馆，情侣出行。地点在黑河，公交换乘方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约202元，历史文化气息浓。景点印象：爱辉因《瑷珲条约》而闻名于世，爱辉历史陈列馆也因《瑷珲条约》而倍受世人关注。爱辉历史陈列馆记载了中俄关系的演变史。\n爱辉历史陈列馆始建于1975年6月，同年9月竣工并对外展出。初建馆时，定名为“爱辉反修展览馆”。1979年7月展览馆对展出的内…整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '8%', 42);
