INSERT INTO `travel_review` VALUES (26390, 'TR026390', '皤滩古镇', '台州', '浙江', '亲子出游', '春季', 12, 5, 1312.00, '是', 5, '12月去的皤滩古镇，一个人出行。地点在台州，地铁到达方便，现场人流量适中。这次玩了5天，人均花费约1312元，夜景表现很好。景点印象：沿着龙形古街探访老商铺、老宅子，寻觅旧时商埠的繁华往事。 品味祠堂庙宇的建筑之美，欣赏无骨花灯刺绣与拼贴的奇妙艺术。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '5%', 58);
