INSERT INTO `travel_review` VALUES (26540, 'TR026540', '水泊梁山', '济宁', '山东', '亲子出游', '夏季', 5, 1, 125.00, '否', 5, '5月去的水泊梁山，情侣出行。地点在济宁，自驾停车需要提前规划，现场游客较多。这次玩了1天，人均花费约125元，历史文化气息浓。景点印象：在《水浒传》故事的发祥地游览梁山山寨，感受水浒文化。 欣赏水浒情景剧与民间艺术表演，去古刹莲台寺礼佛祈福。整体感受是特别满意，很推荐。二刷意愿：否。', '2%', 82);
