INSERT INTO `travel_review` VALUES (26545, 'TR026545', '唐布拉风景区', '伊犁', '新疆', '周末短途', '秋季', 7, 4, 842.00, '否', 5, '7月去的唐布拉风景区，一个人出行。地点在伊犁，公交换乘方便，现场人不算多。这次玩了4天，人均花费约842元，历史文化气息浓。景点印象：唐布拉百里风景区有草原、温泉、雪峰、河流为主要特色，这里有芳草萋萋，流水滔滔，雪岭云杉相辉映，高山白云相依相伴，胜似人间仙景的唐布拉大草原；有一步一景，如诗如画。整体感受是特别满意，很推荐。二刷意愿：否。', '5%', 72);
