INSERT INTO `travel_review` VALUES (26557, 'TR026557', '瑞安堡', '武威', '甘肃', '深度游', '春季', 1, 2, 802.00, '是', 5, '1月去的瑞安堡，和家人出行。地点在武威，地铁到达方便，现场人流量适中。这次玩了2天，人均花费约802元，氛围感不错。景点印象：河西走廊东北部有一块被腾格里沙漠和巴丹吉林沙漠包围着的绿洲，这就是甘肃省武威市(中国旅游标志的故乡)的民勤县，距省城兰州300多公里.长年沙暴肆虐，地广人稀。近年来，这里因盛产黄河密瓜和大板瓜子而闻名遐迩，小城商客渐多。这里有一座年代并…整体感受是超出预期，很推荐。二刷意愿：是。', '3%', 80);
