INSERT INTO `travel_review` VALUES (26579, 'TR026579', '渡蚁桥', '随州', '湖北', '周末短途', '秋季', 7, 2, 162.00, '否', 3, '7月去的渡蚁桥，情侣出行。地点在随州，打车比较省心，现场人不算多。这次玩了2天，人均花费约162元，历史文化气息浓。景点印象：在广水市西原应山县城南郊。为纪念北来宋庠、宋祁以竹渡蚁而建，故名。宋库（996一1066）与其弟宋祁（998-1061），安陆（今属湖北）人，后迁开封雍丘（今河南杞县）。皆北宋大臣，有文名，时称“二宋”。天圣二年（1024年）二宋同举进士，库名列第…整体感受是体验一般，按需选择。二刷意愿：否。', '0%', 59);
