INSERT INTO `travel_review` VALUES (26674, 'TR026674', '双湖', '那曲', '西藏', '周末短途', '夏季', 5, 4, 928.00, '否', 4, '5月去的双湖，和家人出行。地点在那曲，地铁到达方便，现场人不算多。这次玩了4天，人均花费约928元，历史文化气息浓。景点印象：蒙语为“胡尔巴努尔”意为“双湖”，地处喀纳斯湖西岸―恰其阿依特山南坡河谷中，北西走向，呈椭圆状，由相隔三百米左右的两个狭长小湖串连构成，长1200米，宽度不等，一般在300m左右，湖面积1.4km2，海拔1498米。整体感受是体验挺好，可以安排半天到一天。二刷意愿：否。', '1%', 49);
