INSERT INTO `travel_review` VALUES (26724, 'TR026724', '黄河大佛', '济源', '河南', '城市漫游', '春季', 2, 1, 563.00, '是', 5, '2月去的黄河大佛，一个人出行。地点在济源，地铁到达方便，现场游客较多。这次玩了1天，人均花费约563元，拍照很出片。景点印象：黄河大佛\n在孟良寨对面崖壁上，有一石崖酷似大佛屹立在黄河峡谷岸边，称之为黄河大佛。大佛高80余米，宝相庄严、浑然天成，令世人叹为观之。有趣的是，由于小浪底水库蓄水，黄河大佛下部被淹没水中，成为天下第一“浴佛”了。整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 66);
