INSERT INTO `travel_review` VALUES (26762, 'TR026762', '玻璃栈道', '焦作', '河南', '深度游', '春季', 2, 1, 343.00, '是', 5, '2月去的玻璃栈道，和朋友出行。地点在焦作，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约343元，历史文化气息浓。景点印象：云台山玻璃栈道位于云台山茱萸峰凤凰岭景点，在海拔1080米的半山腰上依崖而建。玻璃栈道分为两段，其中一段沿崖壁呈U型，另一段悬于千米悬崖之上，总长400余米，宽约1.6米。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '1%', 77);
