INSERT INTO `travel_review` VALUES (26765, 'TR026765', '庙子湖岛', '舟山', '浙江', '拍照旅行', '春季', 1, 1, 570.00, '否', 3, '1月去的庙子湖岛，和朋友出行。地点在舟山，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约570元，夜景表现很好。景点印象：乘观光车轻松环岛；买张明信片，从中国最东给亲友寄去祝福。整体感受是体验一般，别抱太高期待。二刷意愿：否。', '10%', 54);
