INSERT INTO `travel_review` VALUES (26783, 'TR026783', '双河市热带植物园', '双河', '新疆', '深度游', '夏季', 5, 2, 776.00, '否', 5, '5月去的双河市热带植物园，和朋友出行。地点在双河，地铁到达方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约776元，夜景表现很好。景点印象：周边配套比较齐全整体感受是挺惊喜，以后还会来。二刷意愿：否。', '0%', 49);
INSERT INTO `travel_review` VALUES (26784, 'TR026784', '络丝潭', '安阳', '河南', '周末短途', '春季', 12, 3, 1035.00, '是', 5, '12月去的络丝潭，一个人出行。地点在安阳，地铁到达方便，现场人不算多。这次玩了3天，人均花费约1035元，夜景表现很好。景点印象：处在青年洞西约1公里处的络丝潭风景区，亦被人称为“天桥断”。“络丝潭”因其潭深达一络蚕丝而得名，又因浊漳河有“九峡十八断”，此处是一较大断崭跌水，上有连接豫、冀两省的峡谷索桥，故又称“天桥断”。这里有漳河名胜“小三峡”，可放艇畅游…整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 103);
