INSERT INTO `travel_review` VALUES (26788, 'TR026788', '百灵庙抗日纪念碑', '包头', '内蒙古', '拍照旅行', '冬季', 10, 2, 840.00, '是', 5, '10月去的百灵庙抗日纪念碑，和家人出行。地点在包头，自驾停车需要提前规划，现场人流量适中。这次玩了2天，人均花费约840元，历史文化气息浓。景点印象：1936年2月12日，德王在日本关东军参谋田中隆吉和驻德王府的日本特务机关长浦的操纵下，成立了伪“蒙古军总司令部”。4月24日，德王顺从关东军的旨意，在锡盟乌珠穆沁右旗召开所谓“第一次蒙古大会”，决定成立“蒙古军政府”，通过了建立“蒙古国”…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '1%', 104);
