INSERT INTO `travel_review` VALUES (26903, 'TR026903', '大纵湖风光带', '泰州', '江苏', '城市漫游', '秋季', 6, 2, 403.00, '否', 2, '6月去的大纵湖风光带，情侣出行。地点在泰州，地铁到达方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约403元，氛围感不错。景点印象：大纵湖形成于南宋之前，距今已有800多年历史，这里不仅有丰富的湿地生态资源，享有“水乡泽国”、“鱼米之乡”盛誉，并且有着隽永的人文历史。\n传说大纵湖原为东晋城，东晋城内有一十分孝顺母亲的少年宗保子，在天地一声巨响、洪水汹涌而来时，背…整体感受是体验偏一般，可考虑其他景点。二刷意愿：否。', '0%', 51);
