INSERT INTO `travel_review` VALUES (26906, 'TR026906', '金长城', '齐齐哈尔', '黑龙江', '拍照旅行', '秋季', 6, 2, 432.00, '是', 5, '6月去的金长城，和家人出行。地点在齐齐哈尔，打车比较省心，现场人流量适中。这次玩了2天，人均花费约432元，历史文化气息浓。景点印象：齐齐哈尔市境内有金代所修长城206．15公里，经行于齐齐哈尔市的甘南县、碾子山区和龙江县。金长城是公元12～13世纪以女真人为主体，驱役各族人民共同修筑的，从东北的嫩江之滨到西南的黄河河套，是一段长达4千多公里的军事防御工事。工程分东北、西…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '2%', 90);
