INSERT INTO `travel_review` VALUES (26937, 'TR026937', '避暑山庄', '承德', '河北', '拍照旅行', '夏季', 4, 1, 824.00, '是', 5, '4月去的避暑山庄，情侣出行。地点在承德，公交换乘方便，现场人不算多。这次玩了1天，人均花费约824元，历史文化气息浓。景点印象：中国现存最大的古典皇家园林，面积是颐和园的两倍。 看气派的皇家建筑，还有仿江南园林的湖区。 “烟雨楼”是电视剧《还珠格格》里“漱芳斋”的取景地。整体感受是超出预期，值得专门打卡。二刷意愿：是。', '35%', 135);
