INSERT INTO `travel_review` VALUES (26940, 'TR026940', '龙岩景区', '梧州', '广西', '深度游', '秋季', 6, 5, 1057.00, '否', 5, '6月去的龙岩景区，一个人出行。地点在梧州，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了5天，人均花费约1057元，夜景表现很好。景点印象：龙岩在石桥镇西北500米处，岩洞状若喇叭，长80余米，最宽处60米，后有出口，洞顶有一孔通天，抬头仰望可窥见蓝天白云，故龙岩又称“通天岩”。整体感受是挺惊喜，很推荐。二刷意愿：否。', '6%', 94);
