INSERT INTO `travel_review` VALUES (26945, 'TR026945', '御河生态园', '大同', '山西', '文化打卡', '冬季', 11, 1, 270.00, '否', 4, '11月去的御河生态园，一个人出行。地点在大同，打车比较省心，现场游客较多。这次玩了1天，人均花费约270元，氛围感不错。景点印象：御河生态园，南北长5.5公里，使昔日贫瘠、荒凉的御河两岸重现风光，一条河流能给予一座城市以灵魂，河畔生态园使城市物华得以体现，城市的审美和灵性凭河而含，籍园而展，御河蓄水，御园绽绿。整体感受是整体不错，可以安排半天到一天。二刷意愿：否。', '1%', 83);
