INSERT INTO `travel_review` VALUES (26949, 'TR026949', '董永故里', '孝感', '湖北', '周末短途', '春季', 2, 3, 942.00, '否', 5, '2月去的董永故里，和朋友出行。地点在孝感，打车比较省心，现场人流量适中。这次玩了3天，人均花费约942元，夜景表现很好。景点印象：在孝感市北郊。董永，文学故事人物。传为东汉千乘（今山东博兴）人。早年丧母。灵帝中平时（184-189），随父避兵，流落孝感，佃耕养父。父亡，无以葬，乃自卖为奴。其孝行感动仙女下凡，为其织锦偿债赎身，且与其结为夫妻。《灵芝篇》、《搜神记》…整体感受是特别满意，值得专门打卡。二刷意愿：否。', '0%', 72);
