INSERT INTO `travel_review` VALUES (26955, 'TR026955', '国恩寺', '云浮', '广东', '城市漫游', '春季', 2, 4, 988.00, '否', 2, '2月去的国恩寺，和家人出行。地点在云浮，公交换乘方便，现场高峰时段比较拥挤。这次玩了4天，人均花费约988元，氛围感不错。景点印象：千年古寺，静谧清幽，香火缭绕，祈福佳选。整体感受是没达到预期，不建议高峰来。二刷意愿：否。', '26%', 38);
INSERT INTO `travel_review` VALUES (26956, 'TR026956', '南岳忠烈祠', '衡阳', '湖南', '深度游', '冬季', 11, 1, 243.00, '是', 5, '11月去的南岳忠烈祠，和朋友出行。地点在衡阳，地铁到达方便，现场人不算多。这次玩了1天，人均花费约243元，历史文化气息浓。景点印象：祭奠抗战中牺牲的中国军人。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '19%', 64);
INSERT INTO `travel_review` VALUES (26957, 'TR026957', '泗水塔', '南阳', '河南', '拍照旅行', '夏季', 3, 6, 1510.00, '是', 5, '3月去的泗水塔，和朋友出行。地点在南阳，自驾停车需要提前规划，现场人流量适中。这次玩了6天，人均花费约1510元，夜景表现很好。景点印象：泗洲塔又称泗水塔，位于唐河县城东南隅菩提寺旧址内。宋绍圣二年（1095年）建，高47.33米。底层坐落在台基上，南面辟一拱形门，第二至十层每层各辟1门。下均置砖雕斗拱，转角处有风铎，檐下为平座，塔内有塔心柱，柱之周围筑盘88旋石阶踏道，第一层…整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 60);
