INSERT INTO `travel_review` VALUES (26962, 'TR026962', '天都峰', '黄山', '安徽', '文化打卡', '夏季', 5, 2, 707.00, '是', 5, '5月去的天都峰，一个人出行。地点在黄山，打车比较省心，现场人流量适中。这次玩了2天，人均花费约707元，拍照很出片。景点印象：黄山三大主峰中最险的一座，可登顶鲫鱼背，在万丈悬崖上行走。整体感受是超出预期，很推荐。二刷意愿：是。', '11%', 106);
