INSERT INTO `travel_review` VALUES (26982, 'TR026982', '长廊怀古', '盐城', '江苏', '城市漫游', '冬季', 11, 4, 1405.00, '否', 4, '11月去的长廊怀古，一个人出行。地点在盐城，自驾停车需要提前规划，现场游客较多。这次玩了4天，人均花费约1405元，拍照很出片。景点印象：长廊长20余米，东首“聚仙亭”，西列“观湖楼”，好象书法家写的“一”字，从聚仙亭起笔到观湖楼收笔，这“一”字横空出世，为恬淡雅静的大纵湖划上了一道风景线，置身其间，面对大湖，心旷神怡，遐想万千。整体感受是体验挺好，推荐来看看。二刷意愿：否。', '0%', 67);
