INSERT INTO `travel_review` VALUES (27043, 'TR027043', '五柳龙泉', '宿州', '安徽', '周末短途', '秋季', 7, 3, 1105.00, '是', 4, '7月去的五柳龙泉，和朋友出行。地点在宿州，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了3天，人均花费约1105元，氛围感不错。景点印象：五柳省级风景名胜区位于宿州市市区北约30公里的夹沟镇，处于徐州图库、淮北、宿州三市的中心，总面积35平方公里，这里以“山青、水秀、洞奇、泉灵、稻香”而闻名，景区南、西、北三面环山，植物种类繁多，气候宜人。\n主景区内龙泉湖碧波荡漾、水质…整体感受是体验挺好，可以安排半天到一天。二刷意愿：是。', '0%', 80);
