INSERT INTO `travel_review` VALUES (27068, 'TR027068', '天子驾六博物馆', '洛阳', '河南', '亲子出游', '秋季', 6, 2, 832.00, '是', 5, '6月去的天子驾六博物馆，和朋友出行。地点在洛阳，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约832元，拍照很出片。景点印象：观赏周天子乘坐的“驾六”马车和出行车队的遗迹。 在车马坑前想象周天子出行时马匹嘶叫、车轮滚滚的盛大场面。 原址博物馆，能在这里了解洛阳城作为东周王城的历史。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '25%', 80);
