INSERT INTO `travel_review` VALUES (27077, 'TR027077', '曾家山景区', '广元', '四川', '城市漫游', '秋季', 8, 1, 582.00, '否', 4, '8月去的曾家山景区，和家人出行。地点在广元，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约582元，氛围感不错。景点印象：拥有神奇的地质景观，是自驾游的不错选择。整体感受是还蛮满意，周末来刚好。二刷意愿：否。', '7%', 69);
INSERT INTO `travel_review` VALUES (27078, 'TR027078', '井冈山碑林', '吉安', '江西', '城市漫游', '夏季', 4, 2, 703.00, '否', 5, '4月去的井冈山碑林，情侣出行。地点在吉安，地铁到达方便，现场人不算多。这次玩了2天，人均花费约703元，氛围感不错。景点印象：井冈山碑林始建于1987年7月，自1989年清明节起对外开放。碑林由碑亭、碑廊、自然碑型等部分组成，因势而构，曲折回环，别具一番情趣。整体感受是特别满意，很推荐。二刷意愿：否。', '5%', 69);
