INSERT INTO `travel_review` VALUES (27081, 'TR027081', '五龙山', '天水', '甘肃', '文化打卡', '冬季', 11, 5, 1008.00, '是', 5, '11月去的五龙山，一个人出行。地点在天水，公交换乘方便，现场人不算多。这次玩了5天，人均花费约1008元，氛围感不错。景点印象：五龙山风景区地处张家川回族自治县马鹿乡和寺湾村之间，占地约18.1平方公里，动植物资源极为丰富。\n该景点将关山秀丽的景色集为一体，构成了景区清、幽、秀、雅、雄、奇、险、峻的自然风光。主要景观有：五龙山、佛爷崖太极八卦图、老龙潭、斩蛇崖…整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 87);
INSERT INTO `travel_review` VALUES (27082, 'TR027082', '九龙湖风景区', '衢州', '浙江', '亲子出游', '夏季', 4, 1, 385.00, '是', 4, '4月去的九龙湖风景区，和朋友出行。地点在衢州，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约385元，夜景表现很好。景点印象：整体环境还算干净整体感受是体验挺好，可以安排半天到一天。二刷意愿：是。', '6%', 36);
