INSERT INTO `travel_review` VALUES (27095, 'TR027095', '北湖公园', '郴州', '湖南', '文化打卡', '秋季', 6, 2, 440.00, '是', 5, '6月去的北湖公园，情侣出行。地点在郴州，地铁到达方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约440元，氛围感不错。景点印象：北湖公园位于郴州市中心，公园中的“北湖水月”为郴州八景之一，曾得到过历代文人墨客的赞誉。公园南半部为樟树林区和青少年游乐场所，再现了长征的各色路线，特别适合亲子游玩。整体感受是特别满意，很推荐。二刷意愿：是。', '2%', 110);
INSERT INTO `travel_review` VALUES (27096, 'TR027096', '雪岭云杉自然保护区', '伊犁', '新疆', '拍照旅行', '春季', 1, 3, 460.00, '是', 5, '1月去的雪岭云杉自然保护区，一个人出行。地点在伊犁，公交换乘方便，现场人流量适中。这次玩了3天，人均花费约460元，拍照很出片。景点印象：雪岭云杉是天山林海中特有的一个树种。在巍巍天山深处，它苍劲挺拔、四季青翠、攀坡漫生、绵延不绝，犹如一道沿山而筑的绿色长城。风吹林海，松涛声声，绿波起伏，其势如潮。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '0%', 101);
