INSERT INTO `travel_review` VALUES (27105, 'TR027105', '松口古镇', '梅州', '广东', '城市漫游', '春季', 12, 3, 501.00, '否', 5, '12月去的松口古镇，和朋友出行。地点在梅州，自驾停车需要提前规划，现场人流量适中。这次玩了3天，人均花费约501元，拍照很出片。景点印象：松口不仅仅是千年古镇，而且是客家人的栖身之地，古镇傍水而依，古老的房子与蓝天碧水融为一体，凝成了一幅绝美的山水画，是梅县区第一大镇。整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '0%', 79);
