INSERT INTO `travel_review` VALUES (27110, 'TR027110', '丹阳王墓', '朔州', '山西', '周末短途', '春季', 2, 2, 730.00, '是', 4, '2月去的丹阳王墓，和朋友出行。地点在朔州，打车比较省心，现场游客较多。这次玩了2天，人均花费约730元，历史文化气息浓。景点印象：丹阳王墓位于怀仁县城北4公里的大运公路边。《怀仁县志》记载墓主人是丹阳王叔孙建，但无确凿史料及出土文物为证。建造年代当是北魏无疑。\n该墓分墓道、甬道、前室、后室和东西侧室。墓室平面均呈弧边长方形，四角攒尖顶，墓室高7．2米，墓室面积…整体感受是还蛮满意，可以安排半天到一天。二刷意愿：是。', '0%', 94);
