INSERT INTO `travel_review` VALUES (27133, 'TR027133', '师宗通玄洞', '曲靖', '云南', '文化打卡', '秋季', 7, 1, 674.00, '是', 5, '7月去的师宗通玄洞，和家人出行。地点在曲靖，自驾停车需要提前规划，现场人不算多。这次玩了1天，人均花费约674元，历史文化气息浓。景点印象：师宗的通玄洞，分上洞、中洞、水洞（水洞尚未对外开放）。\n上洞高大宽敞，洞中有山，洞中套洞，大厅一个连着一个， 钟乳石千姿百态，多为白色和朱红色。最为典型的是“两重天”，因下层呈朱红色，上层为乳白石，故人们把它形象地称为两重天。它的顶…整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 75);
