INSERT INTO `travel_review` VALUES (27151, 'TR027151', '加榜梯田', '黔东南', '贵州', '文化打卡', '夏季', 5, 1, 415.00, '否', 4, '5月去的加榜梯田，一个人出行。地点在黔东南，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约415元，历史文化气息浓。景点印象：加榜梯田集天下梯田之精华，它比云南元阳梯田更加秀丽，比广西龙胜梯田更加壮观，极具魅力。整体感受是整体不错，可以安排半天到一天。二刷意愿：否。', '5%', 43);
INSERT INTO `travel_review` VALUES (27152, 'TR027152', '中山公园', '贵港', '广西', '拍照旅行', '春季', 12, 2, 480.00, '否', 5, '12月去的中山公园，和家人出行。地点在贵港，公交换乘方便，现场游客较多。这次玩了2天，人均花费约480元，拍照很出片。景点印象：原属明代京官马文祥私人花园，旧称马家园，后又称芥园、浔州公园，1936年辟为中山公园，迄今已有600多年历史。园内浓荫覆盖，古榕婆娑，花径回环，绿草如茵，桥影碧波，亭台错落有致，环境整洁幽雅，有各种大小乔、灌木约4万株，其中百年以上的古榕…整体感受是挺惊喜，以后还会来。二刷意愿：否。', '10%', 141);
