INSERT INTO `travel_review` VALUES (27180, 'TR027180', '擂鼓墩古墓群', '随州', '湖北', '拍照旅行', '春季', 2, 2, 445.00, '否', 5, '2月去的擂鼓墩古墓群，一个人出行。地点在随州，地铁到达方便，现场人不算多。这次玩了2天，人均花费约445元，历史文化气息浓。景点印象：在随州市城关西北2.5公里的擂鼓墩。擂鼓墩古为随国领地，北望桐柏，南面涡山（即大洪山），东临极水，山岭绵亘，古冢森森。曾侯乙系战国早期曾国君主，其墓营建于红砂岩坡之上，凿石为穴，墓扩面积220平方米，深近20米，停分四室，均以巨木镶隔。主…整体感受是超出预期，很推荐。二刷意愿：否。', '0%', 117);
