INSERT INTO `travel_review` VALUES (27197, 'TR027197', '沙屯叠瀑布', '崇左', '广西', '亲子出游', '冬季', 10, 3, 912.00, '是', 5, '10月去的沙屯叠瀑布，情侣出行。地点在崇左，打车比较省心，现场人不算多。这次玩了3天，人均花费约912元，夜景表现很好。景点印象：沙屯叠瀑，位于大新县硕龙镇，距县城46公里，距崇左市区92公里，传说是七仙女下凡沐浴的地方，瀑布分成七级层层泻下，如垂帘挂珠，河水凝脂，结玉，，水声如歌，如诉，时有渔人乘竹筏于瀑布间出没，秀美景致，更增古朴神韵。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '1%', 91);
INSERT INTO `travel_review` VALUES (27198, 'TR027198', '高山红哨', '邵阳', '湖南', '拍照旅行', '春季', 12, 1, 538.00, '否', 3, '12月去的高山红哨，情侣出行。地点在邵阳，自驾停车需要提前规划，现场人不算多。这次玩了1天，人均花费约538元，历史文化气息浓。景点印象：高山红哨\n高山红哨是广州军区在1963年6月为了国防需要而建，并派兵驻守，担任防空任务。哨所由营房、碉堡、地道、战壕、蓝球场五部分组成，总占地面积3456平方米。1969年10月1日其驻军代表赴北京参加国庆观礼，受到毛主席的亲切接见后，被中央军委…整体感受是中规中矩，别抱太高期待。二刷意愿：否。', '5%', 33);
