INSERT INTO `travel_review` VALUES (27201, 'TR027201', '竹山景区', '防城港', '广西', '城市漫游', '夏季', 3, 1, 617.00, '是', 3, '3月去的竹山景区，一个人出行。地点在防城港，打车比较省心，现场人流量适中。这次玩了1天，人均花费约617元，历史文化气息浓。景点印象：竹山景区位于北仑河入海口，是海陆交汇处。中国大陆海岸线东起鸭绿江，西至北仑河，这里是中国大陆海岸线的最西端，又是陆路边界线的起点，其对面隔海相望是越南的芒街市和万柱海滩。这里是大清国一号界碑，还是北仑河国家海洋自然生态保护区。历史…整体感受是还可以，按需选择。二刷意愿：是。', '13%', 41);
