INSERT INTO `travel_review` VALUES (27206, 'TR027206', '福音堂', '南充', '四川', '亲子出游', '夏季', 4, 2, 791.00, '否', 5, '4月去的福音堂，情侣出行。地点在南充，公交换乘方便，现场人不算多。这次玩了2天，人均花费约791元，拍照很出片。景点印象：位于杨天井街7号，又称圣约翰大教堂，建于光绪三十四年，已有近百年历史。它是四川最早的西洋建筑之一，也是西南现存规模最大的基督教堂，曾一度为基督教东川教区总堂，系英国传教士“剑桥七杰”之一的盖世礼筹资修建，澳大利亚工程师设计，教堂临…整体感受是超出预期，以后还会来。二刷意愿：否。', '1%', 85);
