INSERT INTO `travel_review` VALUES (27245, 'TR027245', '九女湖', '晋城', '山西', '文化打卡', '冬季', 9, 1, 650.00, '是', 5, '9月去的九女湖，和朋友出行。地点在晋城，公交换乘方便，现场人不算多。这次玩了1天，人均花费约650元，历史文化气息浓。景点印象：九仙女湖旅游风景区--位于山西省阳城县，是传说中仙女下凡游玩之处所，湖中矗立有九女仙台，台上建有九女仙祠，是阳城古城八景之一。曾是历代文人墨客经常观光旅游的地方。\n九女湖地处太行山和中条山交汇的沁河峡谷之中，它是阳城县继国家级自然风…整体感受是超出预期，很推荐。二刷意愿：是。', '11%', 52);
