INSERT INTO `travel_review` VALUES (27257, 'TR027257', '冈仁波齐', '阿里', '西藏', '深度游', '夏季', 3, 1, 80.00, '是', 2, '3月去的冈仁波齐，情侣出行。地点在阿里，地铁到达方便，现场游客较多。这次玩了1天，人均花费约80元，历史文化气息浓。景点印象：冈仁波齐是公认的神山，山势壮丽秀美，被《中国国家地理》杂志评选为中国最美的十大名山之一。 每年春秋两季，是转山的最佳时刻。尤其是藏历马年，来此转山的朝圣者络绎不绝。整体感受是略失望，可考虑其他景点。二刷意愿：是。', '70%', 1);
