INSERT INTO `travel_review` VALUES (27273, 'TR027273', '龙山晓日', '商洛', '陕西', '亲子出游', '夏季', 3, 1, 591.00, '否', 5, '3月去的龙山晓日，情侣出行。地点在商洛，自驾停车需要提前规划，现场人流量适中。这次玩了1天，人均花费约591元，氛围感不错。景点印象：商州东五里许，有山耸拔，起伏趋江，如龙吸水，故曰龙山。每当海日初升，曜若金鳞，盖不同于凡岭云。山之阳有东岳庙，南有关帝祠。\n[注释]海日：古人以为日从海中升起，故称。金鳞：金色鲫鱼。代指丹水清漪波涛经太阳照谢后像鱼斡。此景在今商州市…整体感受是超出预期，以后还会来。二刷意愿：否。', '0%', 110);
