INSERT INTO `travel_review` VALUES (27284, 'TR027284', '黄河源', '果洛', '青海', '周末短途', '春季', 1, 2, 866.00, '是', 5, '1月去的黄河源，和朋友出行。地点在果洛，地铁到达方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约866元，氛围感不错。景点印象：也许你无法想像黄河的源头竟不是洪水滚滚，而是由众多细微的清泉和有许多砂砾野草的荒滩而组成，但会让你感受袒露无疑的大自然之美。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '2%', 91);
INSERT INTO `travel_review` VALUES (27285, 'TR027285', '东吴石塔', '莆田', '福建', '拍照旅行', '夏季', 5, 4, 1396.00, '否', 3, '5月去的东吴石塔，情侣出行。地点在莆田，地铁到达方便，现场游客较多。这次玩了4天，人均花费约1396元，历史文化气息浓。景点印象：是明代礼部尚书陈经邦的府第，位于城厢区长寿街庙前路（俗称铁树里）。陈经邦字公望，号肃庵，嘉靖四十四年（1565年）进士，授翰林编修。大宗伯第建成于明万历二十年（1592年），按明制建造，五进五开间三厅六房，抬梁式与穿斗式相结合的木质结构，…整体感受是还可以，别抱太高期待。二刷意愿：否。', '0%', 33);
