INSERT INTO `travel_review` VALUES (27287, 'TR027287', '告庄西双景', '西双版纳', '云南', '深度游', '冬季', 9, 2, 754.00, '是', 5, '9月去的告庄西双景，情侣出行。地点在西双版纳，地铁到达方便，现场游客较多。这次玩了2天，人均花费约754元，夜景表现很好。景点印象：充满当地风情的景点，美食美景一个不少。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '11%', 84);
INSERT INTO `travel_review` VALUES (27288, 'TR027288', '南山风景旅游区', '伊春', '黑龙江', '城市漫游', '夏季', 5, 1, 539.00, '是', 5, '5月去的南山风景旅游区，情侣出行。地点在伊春，打车比较省心，现场游客较多。这次玩了1天，人均花费约539元，氛围感不错。景点印象：南山风景旅游区始建于1993年，景区占地面积为3500公顷，山体平均海拔420米，其中兴安塔主峰海拔653米，塔高47米，是景区的标志性建筑。南山景区地势起伏、峰谷迂回、空间富于变化、自然形成山体，峰容坡地构成风景区多种的地貌景观。景区森林覆盖率…整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 102);
INSERT INTO `travel_review` VALUES (27289, 'TR027289', '富家桥异蛇村', '永州', '湖南', '拍照旅行', '冬季', 10, 2, 485.00, '是', 5, '10月去的富家桥异蛇村，和家人出行。地点在永州，自驾停车需要提前规划，现场游客较多。这次玩了2天，人均花费约485元，拍照很出片。景点印象：永州“异蛇”之可怕，世人皆知。早在公元854年，柳宗元笔下的《捕蛇者说》中就有记载，称它“触草木，尽死；以啮人，无御之者。”永州真的产这么一种剧毒无比的“异蛇”吗？带着疑惑，我们来到当地有名的“异蛇村”。\n其实，“异蛇村”并非一个行…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 76);
