INSERT INTO `travel_review` VALUES (27294, 'TR027294', '沙屯叠瀑布', '崇左', '广西', '深度游', '夏季', 5, 3, 968.00, '是', 5, '5月去的沙屯叠瀑布，一个人出行。地点在崇左，打车比较省心，现场人不算多。这次玩了3天，人均花费约968元，氛围感不错。景点印象：沙屯叠瀑，位于大新县硕龙镇，距县城46公里，距崇左市区92公里，传说是七仙女下凡沐浴的地方，瀑布分成七级层层泻下，如垂帘挂珠，河水凝脂，结玉，，水声如歌，如诉，时有渔人乘竹筏于瀑布间出没，秀美景致，更增古朴神韵。整体感受是特别满意，以后还会来。二刷意愿：是。', '1%', 79);
