INSERT INTO `travel_review` VALUES (27300, 'TR027300', '古银州摩崖石刻', '榆林', '陕西', '拍照旅行', '冬季', 11, 7, 1975.00, '否', 2, '11月去的古银州摩崖石刻，情侣出行。地点在榆林，地铁到达方便，现场人不算多。这次玩了7天，人均花费约1975元，拍照很出片。景点印象：无定河南岸石崖之上，有“古银州”三字的摩崖石刻，宽8.3米，高3米，每字宽1.5米，高1.8米，字距为1米。\n民国二十三年(1934年)时任县长严建章主持勒石，阴刻楷书，刚健雄宏，蔚为壮观。由本县清末进士高增爵邀请段祺瑞政府总统徐世昌所书。整体感受是略失望，不建议高峰来。二刷意愿：否。', '1%', 79);
