INSERT INTO `travel_review` VALUES (27303, 'TR027303', '武关遗址', '商洛', '陕西', '拍照旅行', '春季', 1, 1, 104.00, '是', 5, '1月去的武关遗址，一个人出行。地点在商洛，打车比较省心，现场人不算多。这次玩了1天，人均花费约104元，氛围感不错。景点印象：位于丹凤县东武关河的北岸,与函谷关,萧关,大散关成为“秦之四塞”。武关历史悠久，远在春秋时即以建置,明曰“少习关”,战国时改为“武关”。关城建立在峡谷间一座较为平坦的高地上,北依高峻的少习山,南濒险要。关城周长1.5公里，城墙用土筑,略成方…整体感受是特别满意，很推荐。二刷意愿：是。', '0%', 43);
