INSERT INTO `travel_review` VALUES (27327, 'TR027327', '小天池', '白山', '吉林', '文化打卡', '春季', 12, 2, 636.00, '否', 5, '12月去的小天池，和家人出行。地点在白山，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约636元，氛围感不错。景点印象：小天池又称银环湖，坐落在长白山景区海拔比较低的地方，湖的四周围绕着郁郁葱葱的树林，湖水也绿得透亮。虽然小天池没有天池的壮观，但如果能避开旅游团的打扰，那里也是散步发呆聊天摄影的好地方。整体感受是特别满意，值得专门打卡。二刷意愿：否。', '32%', 88);
