INSERT INTO `travel_review` VALUES (27387, 'TR027387', '黄遵宪纪念馆', '梅州', '广东', '周末短途', '春季', 2, 1, 391.00, '是', 4, '2月去的黄遵宪纪念馆，和家人出行。地点在梅州，打车比较省心，现场游客较多。这次玩了1天，人均花费约391元，拍照很出片。景点印象：清末爱国诗人黄遵宪的故居名为“人境庐”，坐落在梅州市东3公里处的周溪畔，庐舍内环境优美，曲径通幽，书香四溢。整体感受是体验挺好，推荐来看看。二刷意愿：是。', '35%', 48);
