INSERT INTO `travel_review` VALUES (27390, 'TR027390', '凤县', '宝鸡', '陕西', '深度游', '冬季', 11, 2, 669.00, '是', 5, '11月去的凤县，一个人出行。地点在宝鸡，打车比较省心，现场人不算多。这次玩了2天，人均花费约669元，拍照很出片。景点印象：凤县古称“凤州”，始建于秦朝。地处陕西省宝鸡市西南，位于东经106°24′54″~107°7′30″，北纬33°34′57″~34°18′21″。因地连陕甘，又处入川孔道，北依秦岭主脊，南接紫柏山，古栈道贯通全境，故有“秦蜀咽喉，汉北锁钥”之称。整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 104);
INSERT INTO `travel_review` VALUES (27391, 'TR027391', '嘉陵江', '陇南', '甘肃', '周末短途', '冬季', 11, 1, 100.00, '否', 2, '11月去的嘉陵江，和朋友出行。地点在陇南，打车比较省心，现场人不算多。这次玩了1天，人均花费约100元，历史文化气息浓。景点印象：“汉水南入嘉陵道而为嘉陵水”，江名由此而来，嘉陵江发源于秦岭南麓，流经陕、甘、川至重庆流入长江。沿江两岸奇峰壁立、怪石嶙峋、森林茂密、泉瀑众多、美不胜收。整体感受是体验偏一般，不建议高峰来。二刷意愿：否。', '41%', 40);
