INSERT INTO `travel_review` VALUES (27397, 'TR027397', '雅尔湖千佛洞', '吐鲁番', '新疆', '拍照旅行', '夏季', 5, 4, 1273.00, '否', 5, '5月去的雅尔湖千佛洞，和家人出行。地点在吐鲁番，地铁到达方便，现场人不算多。这次玩了4天，人均花费约1273元，拍照很出片。景点印象：雅尔湖千佛洞位于交河故城西南河谷南岸，依崖凿窟，窟区东西长40米，现存洞窟7个。窟前有宽约5米的长形平台，平台下距河谷谷底约20米深。洞窟内壁画内容为比丘供养人、说法图、回鹘人供养像等，还有部分汉文、突厥文题记。关于雅尔湖石窟的年代问题…整体感受是挺惊喜，以后还会来。二刷意愿：否。', '0%', 90);
