INSERT INTO `travel_review` VALUES (27403, 'TR027403', '南山特产', '邵阳', '湖南', '城市漫游', '冬季', 10, 4, 663.00, '否', 3, '10月去的南山特产，情侣出行。地点在邵阳，公交换乘方便，现场高峰时段比较拥挤。这次玩了4天，人均花费约663元，氛围感不错。景点印象：南山奶粉\n“南山”牌系列乳制品以“凉开水即溶，喝了不上火”蜚声全国，被誉为“南国净土里长出的绿色食品”，其中婴幼儿系列奶粉为“国家免检产品”。南山奶粉畅销全国近30个省、自治区、直辖市，成为全国奶粉行业十大畅销产品，在广大消费者的心…整体感受是中规中矩，按需选择。二刷意愿：否。', '0%', 79);
INSERT INTO `travel_review` VALUES (27404, 'TR027404', '桃源洞', '株洲', '湖南', '城市漫游', '秋季', 7, 3, 1151.00, '否', 4, '7月去的桃源洞，情侣出行。地点在株洲，公交换乘方便，现场人流量适中。这次玩了3天，人均花费约1151元，历史文化气息浓。景点印象：桃源洞的地形、地貌、地质和气候等自然条件构成独特的自然生态环境，使他不仅成为天然动植物物种基因库，而且成为不可多得的森林旅游福地，令世人神往的人间仙景。\n丰富的动植物资源 桃源洞属华南、华东等多种植物区第成份的交汇处和过渡地，植物…整体感受是体验挺好，可以安排半天到一天。二刷意愿：否。', '0%', 121);
INSERT INTO `travel_review` VALUES (27405, 'TR027405', '江淮岭生态园', '信阳', '河南', '亲子出游', '春季', 12, 5, 1627.00, '是', 4, '12月去的江淮岭生态园，和朋友出行。地点在信阳，地铁到达方便，现场人不算多。这次玩了5天，人均花费约1627元，拍照很出片。景点印象：江淮岭生态园始建于1997年8月，位于新县城南8公里处的江淮分水岭，气候温和，雨量充沛，植被丰富，怪石林立。园区座落于风景秀丽的江淮岭上，如今，这里已成为人们观光旅游、休闲度假、揽胜猎奇、陶冶心境的好去处。1999年4月，新县县委、县政府把…整体感受是体验挺好，可以安排半天到一天。二刷意愿：是。', '0%', 57);
