INSERT INTO `travel_review` VALUES (27446, 'TR027446', '老秃顶自然保护区', '本溪', '辽宁', '拍照旅行', '春季', 12, 2, 795.00, '否', 4, '12月去的老秃顶自然保护区，和朋友出行。地点在本溪，打车比较省心，现场人流量适中。这次玩了2天，人均花费约795元，历史文化气息浓。景点印象：老秃顶是“辽宁屋脊”，省级自然保护区。位于桓仁县境内，属长白山脉。主峰海拔一千三百二十五公尺，面积七万二千亩，山顶气候寒冷，草木低矮，似龙爪状，故名老秃顶，但山腰森林茂密，有原始林。林中，有柞、桦、楸、椴、松、枫、槐、曲柳等树种，…整体感受是体验挺好，可以安排半天到一天。二刷意愿：否。', '1%', 67);
