INSERT INTO `travel_review` VALUES (27455, 'TR027455', '五龙山', '天水', '甘肃', '周末短途', '春季', 1, 1, 86.00, '否', 5, '1月去的五龙山，情侣出行。地点在天水，自驾停车需要提前规划，现场人流量适中。这次玩了1天，人均花费约86元，历史文化气息浓。景点印象：五龙山风景区地处张家川回族自治县马鹿乡和寺湾村之间，占地约18.1平方公里，动植物资源极为丰富。\n该景点将关山秀丽的景色集为一体，构成了景区清、幽、秀、雅、雄、奇、险、峻的自然风光。主要景观有：五龙山、佛爷崖太极八卦图、老龙潭、斩蛇崖…整体感受是特别满意，值得专门打卡。二刷意愿：否。', '0%', 64);
