INSERT INTO `travel_review` VALUES (27457, 'TR027457', '雅尔湖千佛洞', '吐鲁番', '新疆', '周末短途', '夏季', 5, 3, 925.00, '否', 2, '5月去的雅尔湖千佛洞，和朋友出行。地点在吐鲁番，打车比较省心，现场游客较多。这次玩了3天，人均花费约925元，夜景表现很好。景点印象：雅尔湖千佛洞位于交河故城西南河谷南岸，依崖凿窟，窟区东西长40米，现存洞窟7个。窟前有宽约5米的长形平台，平台下距河谷谷底约20米深。洞窟内壁画内容为比丘供养人、说法图、回鹘人供养像等，还有部分汉文、突厥文题记。关于雅尔湖石窟的年代问题…整体感受是体验偏一般，建议谨慎前往。二刷意愿：否。', '0%', 44);
