INSERT INTO `travel_review` VALUES (27505, 'TR027505', '高山红哨', '邵阳', '湖南', '文化打卡', '夏季', 4, 4, 1187.00, '否', 2, '4月去的高山红哨，情侣出行。地点在邵阳，打车比较省心，现场高峰时段比较拥挤。这次玩了4天，人均花费约1187元，历史文化气息浓。景点印象：高山红哨\n高山红哨是广州军区在1963年6月为了国防需要而建，并派兵驻守，担任防空任务。哨所由营房、碉堡、地道、战壕、蓝球场五部分组成，总占地面积3456平方米。1969年10月1日其驻军代表赴北京参加国庆观礼，受到毛主席的亲切接见后，被中央军委…整体感受是略失望，建议谨慎前往。二刷意愿：否。', '5%', 27);
