INSERT INTO `travel_review` VALUES (27507, 'TR027507', '崆峒山', '平凉', '甘肃', '拍照旅行', '冬季', 11, 2, 502.00, '否', 4, '11月去的崆峒山，一个人出行。地点在平凉，打车比较省心，现场人流量适中。这次玩了2天，人均花费约502元，夜景表现很好。景点印象：探寻道教的千年圣地，在峻峭山岭间登山徒步，欣赏秀美风光。整体感受是整体不错，推荐来看看。二刷意愿：否。', '76%', 79);
INSERT INTO `travel_review` VALUES (27508, 'TR027508', '清远宝晶宫国际旅游度假区', '清远', '广东', '亲子出游', '秋季', 6, 1, 169.00, '否', 2, '6月去的清远宝晶宫国际旅游度假区，和家人出行。地点在清远，自驾停车需要提前规划，现场人流量适中。这次玩了1天，人均花费约169元，夜景表现很好。景点印象：探秘天然溶洞，感受“岭南第一洞天”的雄奇。整体感受是略失望，可考虑其他景点。二刷意愿：否。', '4%', 45);
INSERT INTO `travel_review` VALUES (27509, 'TR027509', '安乐寺', '贺州', '广西', '城市漫游', '夏季', 4, 3, 636.00, '是', 5, '4月去的安乐寺，和朋友出行。地点在贺州，地铁到达方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约636元，历史文化气息浓。景点印象：安乐寺始建于顺治元年（1644年），康熙四十三年（1704年），道光十一年（1831年）重修。一1944年改建为街公所粮库，1933年农历月十五日动工修复。寺里供奉着“李道清公爷神像”，上面挂着“聪听弈训”的牌匾，两边的条幅左边为“国泰民安”，右边为…整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '6%', 126);
