INSERT INTO `travel_review` VALUES (27512, 'TR027512', '星岛·桃花岛风景区', '日照', '山东', '文化打卡', '秋季', 8, 4, 1031.00, '否', 4, '8月去的星岛·桃花岛风景区，和朋友出行。地点在日照，公交换乘方便，现场游客较多。这次玩了4天，人均花费约1031元，拍照很出片。景点印象：自然景观与海岛码头融为一体，赏桃花盛开，鸟语花香。整体感受是还蛮满意，推荐来看看。二刷意愿：否。', '8%', 40);
INSERT INTO `travel_review` VALUES (27513, 'TR027513', '空厢寺', '三门峡', '河南', '城市漫游', '春季', 12, 3, 821.00, '否', 2, '12月去的空厢寺，一个人出行。地点在三门峡，打车比较省心，现场人不算多。这次玩了3天，人均花费约821元，拍照很出片。景点印象：空厢寺原名定林寺（又称熊耳山寺），位于陕县西李村乡的熊耳山下，距三门峡市约53公里。据清朝和民国的《陕州志》记载，佛教从东汉永平年间（公元58-75年）传入陕州时，修建了空厢寺，距今已1900多年，是与中国第一古刹白马寺同一时期的佛门圣地。\n…整体感受是没达到预期，可考虑其他景点。二刷意愿：否。', '0%', 41);
