INSERT INTO `travel_review` VALUES (27540, 'TR027540', '向阳湖', '佳木斯', '黑龙江', '亲子出游', '夏季', 3, 2, 340.00, '否', 5, '3月去的向阳湖，情侣出行。地点在佳木斯，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约340元，氛围感不错。景点印象：向阳湖位于黑龙江省桦南县中部，距县城东北9公里，因坐落于向阳山脚下而得名，素有\"三江第一湖\"的美誉。 \"V\"字型的向阳湖位于佳木斯市、七台河市、双鸭山市的三角地带，东有省级七星峰自然保护区，北有全国著名的针叶人工林孟家岗林场，三处交相呼…整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '0%', 94);
