INSERT INTO `travel_review` VALUES (27552, 'TR027552', '白马雪山', '迪庆', '云南', '文化打卡', '夏季', 4, 3, 772.00, '否', 3, '4月去的白马雪山，和家人出行。地点在迪庆，自驾停车需要提前规划，现场游客较多。这次玩了3天，人均花费约772元，氛围感不错。景点印象：寒温带高山动植物王国，翻越垭口远观白马雪山主峰。整体感受是中规中矩，按需选择。二刷意愿：否。', '3%', 55);
