INSERT INTO `travel_review` VALUES (27556, 'TR027556', '雨王庙', '临沂', '山东', '深度游', '冬季', 9, 2, 971.00, '否', 5, '9月去的雨王庙，和家人出行。地点在临沂，打车比较省心，现场人不算多。这次玩了2天，人均花费约971元，夜景表现很好。景点印象：雨王庙是蒙山国家森林公园的一处重要景点，也是一处值得珍视的人文景观。庙中所祀主神――雨王，是蒙山地区专祀的司雨神灵，这位雨王即不在姜子牙《封神演义》七十二部正神当中，也不在中国民间普遍信仰的专司风雨的神祗谱系中（如龙王、关公等）。…整体感受是挺惊喜，很推荐。二刷意愿：否。', '2%', 88);
INSERT INTO `travel_review` VALUES (27557, 'TR027557', '龙子湖', '蚌埠', '安徽', '文化打卡', '秋季', 6, 1, 197.00, '是', 5, '6月去的龙子湖，和家人出行。地点在蚌埠，打车比较省心，现场游客较多。这次玩了1天，人均花费约197元，氛围感不错。景点印象：龙子湖风景区座落于蚌埠市东郊，主要由龙湖、曹山、雪华山、西芦山及锥子山组成，大体呈三山夹一湖的独特地貌。整体感受是超出预期，以后还会来。二刷意愿：是。', '50%', 90);
