INSERT INTO `travel_review` VALUES (27587, 'TR027587', '武威市博物馆', '武威', '甘肃', '亲子出游', '夏季', 3, 7, 1402.00, '是', 5, '3月去的武威市博物馆，和朋友出行。地点在武威，打车比较省心，现场高峰时段比较拥挤。这次玩了7天，人均花费约1402元，历史文化气息浓。景点印象：武威市博物馆现馆藏文物4.4万多件，其中国宝级文物2件，一级文件170件，二级文物278件，三级文物594件，是甘肃省第二大历史博物馆。以铜奔马、医药简、礼仪简、木雕、墓志石刻为代表的汉唐文物，以西夏碑、木缘塔、木版画、金碗为代表的西夏文物，…整体感受是特别满意，很推荐。二刷意愿：是。', '6%', 86);
