INSERT INTO `travel_review` VALUES (27649, 'TR027649', '金兰山', '信阳', '河南', '拍照旅行', '秋季', 8, 1, 203.00, '否', 5, '8月去的金兰山，一个人出行。地点在信阳，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约203元，拍照很出片。景点印象：金兰山国家森林公园，地处亚热带向暧温带过渡地带，是我国华东、华中、华北三大植物区系交汇处和我国动植物南迁北移的缓冲带，森林资源丰富，树木种类繁多。有森林面积3072公顷，森林覆盖率93.1%，植物种类2000多种，其中国家重点保护植物19种。有…整体感受是超出预期，以后还会来。二刷意愿：否。', '0%', 59);
INSERT INTO `travel_review` VALUES (27650, 'TR027650', '福建省苏维埃政府旧址', '龙岩', '福建', '亲子出游', '夏季', 4, 1, 794.00, '否', 4, '4月去的福建省苏维埃政府旧址，和家人出行。地点在龙岩，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约794元，拍照很出片。景点印象：福建省苏维埃政府旧址，全国重点文物保护单位，位于福建省长汀县汀州镇兆征路41号。该址宋代为汀州禁军署地，元代为汀州卫署址，明、清两代辟为试院，是汀州历史极具象征意义的一处古迹。1932年3月18日，福建省第一次工农兵代表大会在此隆重召开，…整体感受是整体不错，周末来刚好。二刷意愿：否。', '1%', 61);
INSERT INTO `travel_review` VALUES (27651, 'TR027651', '徽杭古道', '宣城', '安徽', '城市漫游', '冬季', 10, 1, 80.00, '否', 5, '10月去的徽杭古道，和家人出行。地点在宣城，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约80元，拍照很出片。景点印象：初级徒步者的天堂，没有旅行团身影，可以在此体会到纯正的徒步体验。整体感受是特别满意，很推荐。二刷意愿：否。', '21%', 90);
