INSERT INTO `travel_review` VALUES (27691, 'TR027691', '药泉山钟灵禅寺', '黑河', '黑龙江', '城市漫游', '夏季', 4, 1, 801.00, '否', 4, '4月去的药泉山钟灵禅寺，情侣出行。地点在黑河，公交换乘方便，现场人不算多。这次玩了1天，人均花费约801元，历史文化气息浓。景点印象：药泉山钟灵禅寺坐落在五大连池风景名胜区老期火山药泉山的火山口中平旷之处，距火口垣尚有十余米的高程，它与火山堰塞湖和新老期火山相映生辉，构成了独特的人文景观，在火山口里建寺庙在世界上是唯一的，所以钟灵禅寺又号称火口第一寺。\n登药泉山…整体感受是整体不错，推荐来看看。二刷意愿：否。', '2%', 52);
