INSERT INTO `travel_review` VALUES (27699, 'TR027699', '武关遗址', '商洛', '陕西', '深度游', '春季', 1, 3, 667.00, '是', 5, '1月去的武关遗址，一个人出行。地点在商洛，地铁到达方便，现场人流量适中。这次玩了3天，人均花费约667元，历史文化气息浓。景点印象：位于丹凤县东武关河的北岸,与函谷关,萧关,大散关成为“秦之四塞”。武关历史悠久，远在春秋时即以建置,明曰“少习关”,战国时改为“武关”。关城建立在峡谷间一座较为平坦的高地上,北依高峻的少习山,南濒险要。关城周长1.5公里，城墙用土筑,略成方…整体感受是特别满意，以后还会来。二刷意愿：是。', '0%', 95);
