INSERT INTO `travel_review` VALUES (27714, 'TR027714', '福音堂', '南充', '四川', '深度游', '秋季', 7, 2, 557.00, '是', 5, '7月去的福音堂，一个人出行。地点在南充，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约557元，历史文化气息浓。景点印象：位于杨天井街7号，又称圣约翰大教堂，建于光绪三十四年，已有近百年历史。它是四川最早的西洋建筑之一，也是西南现存规模最大的基督教堂，曾一度为基督教东川教区总堂，系英国传教士“剑桥七杰”之一的盖世礼筹资修建，澳大利亚工程师设计，教堂临…整体感受是超出预期，很推荐。二刷意愿：是。', '1%', 61);
