INSERT INTO `travel_review` VALUES (27720, 'TR027720', '桂东南抗日武装起义纪念塔', '玉林', '广西', '城市漫游', '秋季', 8, 1, 80.00, '否', 5, '8月去的桂东南抗日武装起义纪念塔，情侣出行。地点在玉林，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约80元，历史文化气息浓。景点印象：纪念塔，于1992年3月5日奠基，有用石头雕刻而成的侏罗纪时代的恐龙沟，有巨石龟、石兔、石羊、石牛构成的独占鳌头风景点。整体感受是挺惊喜，以后还会来。二刷意愿：否。', '0%', 82);
