INSERT INTO `travel_review` VALUES (27724, 'TR027724', '黄河旅游区', '忻州', '山西', '亲子出游', '春季', 12, 2, 397.00, '是', 4, '12月去的黄河旅游区，和家人出行。地点在忻州，打车比较省心，现场人流量适中。这次玩了2天，人均花费约397元，夜景表现很好。景点印象：忻州的黄河旅游区，包括偏关、河曲和保德三县。黄河经过内蒙托克托县的河日镇后，急转直下，进人约180公里长的\"晋陕峡谷\"之中，此段黄河，咆哮奔腾，水面时宽时窄，河谷深切，山势险要，河水湍急，气势磅礴，十分壮观。特别是在汹涌澎湃的黄河之中…整体感受是还蛮满意，可以安排半天到一天。二刷意愿：是。', '0%', 103);
