INSERT INTO `travel_review` VALUES (27763, 'TR027763', '竹泉村', '临沂', '山东', '文化打卡', '夏季', 3, 2, 773.00, '否', 5, '3月去的竹泉村，情侣出行。地点在临沂，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约773元，夜景表现很好。景点印象：竹因泉而生，泉依山而活，清泉竹林茅舍，是难得的避暑佳地。整体感受是特别满意，以后还会来。二刷意愿：否。', '2%', 63);
