INSERT INTO `travel_review` VALUES (27765, 'TR027765', '贵城寨遗址', '焦作', '河南', '城市漫游', '夏季', 4, 3, 512.00, '否', 5, '4月去的贵城寨遗址，一个人出行。地点在焦作，打车比较省心，现场游客较多。这次玩了3天，人均花费约512元，氛围感不错。景点印象：贵城寨遗址位于焦作市东北部安阳城乡贵城寨村东南1公里处。《左传》（隐公十一年）杜注：\"贵在修武县北\"。《水经注》也载：\"修武县北有故贵城\"。现在城虽然已经被破坏，但是还有个别地方略高出地面，经过专家和学者考证，为古代贵城遗址。总面积有1…整体感受是特别满意，值得专门打卡。二刷意愿：否。', '0%', 49);
