INSERT INTO `travel_review` VALUES (27769, 'TR027769', '云南民族村', '昆明', '云南', '拍照旅行', '夏季', 3, 3, 1050.00, '否', 5, '3月去的云南民族村，一个人出行。地点在昆明，地铁到达方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约1050元，拍照很出片。景点印象：参观25个少数民族的村寨，体验丰富多彩的民族文化风情。整体感受是特别满意，值得专门打卡。二刷意愿：否。', '16%', 78);
INSERT INTO `travel_review` VALUES (27770, 'TR027770', '百泉故址', '固原', '宁夏', '深度游', '春季', 12, 1, 318.00, '否', 3, '12月去的百泉故址，和家人出行。地点在固原，公交换乘方便，现场游客较多。这次玩了1天，人均花费约318元，氛围感不错。景点印象：隋、唐百泉县城和百泉寺遗址，座落在彭阳县城西南10.2公里处的沟口乡陶家海子。\n故址翠山掩映，杨柳蔽日，碧草茵茵，风景秀丽，气候宜人。在青翠欲滴的绿荫下，数十条清溪细流穿绕犹如巨幅绿毡般的草地，潺潺有声。夏日避暑于此，凉爽无比。每当拂…整体感受是还可以，避开高峰更好。二刷意愿：否。', '0%', 68);
