INSERT INTO `travel_review` VALUES (27806, 'TR027806', '长廊怀古', '盐城', '江苏', '深度游', '夏季', 5, 1, 720.00, '否', 3, '5月去的长廊怀古，一个人出行。地点在盐城，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约720元，历史文化气息浓。景点印象：长廊长20余米，东首“聚仙亭”，西列“观湖楼”，好象书法家写的“一”字，从聚仙亭起笔到观湖楼收笔，这“一”字横空出世，为恬淡雅静的大纵湖划上了一道风景线，置身其间，面对大湖，心旷神怡，遐想万千。整体感受是还可以，避开高峰更好。二刷意愿：否。', '0%', 27);
