INSERT INTO `travel_review` VALUES (27808, 'TR027808', '七星河自然保护区', '双鸭山', '黑龙江', '亲子出游', '秋季', 6, 2, 632.00, '否', 5, '6月去的七星河自然保护区，情侣出行。地点在双鸭山，公交换乘方便，现场人流量适中。这次玩了2天，人均花费约632元，氛围感不错。景点印象：位于黑龙江省宝清县境内，地理座标为东经132°5′--132°26′，北纬46°40′--46°52′，总面积20000公顷。保护区于1991年经宝清县政府批准建立，1996年经双鸭山市政府批准晋升为市级，1998年晋升为省级，是一个以沼泽湿地生态系统及珍禽为主要保护…整体感受是特别满意，值得专门打卡。二刷意愿：否。', '0%', 131);
