INSERT INTO `travel_review` VALUES (27838, 'TR027838', '喀拉库勒湖', '克孜勒苏柯尔克孜', '新疆', '深度游', '秋季', 7, 2, 724.00, '是', 5, '7月去的喀拉库勒湖，一个人出行。地点在克孜勒苏柯尔克孜，打车比较省心，现场人流量适中。这次玩了2天，人均花费约724元，夜景表现很好。景点印象：高原湖泊-----喀拉库勒湖距阿图什220公里，海拔3600百米，面积为10平方公里，水深30多米，因湖水深邃幽黯，故名“喀拉库勒”（柯尔克孜语意为黑湖）。湖东面矗立着“冰山之父”慕士塔格峰，西面雄踞逶迤不绝的萨尔阔勒山脉；湖的南面是一片草原，一…整体感受是挺惊喜，以后还会来。二刷意愿：是。', '80%', 83);
