INSERT INTO `travel_review` VALUES (27981, 'TR027981', '凤凰山', '铜陵', '安徽', '城市漫游', '夏季', 3, 1, 465.00, '是', 5, '3月去的凤凰山，和朋友出行。地点在铜陵，公交换乘方便，现场人不算多。这次玩了1天，人均花费约465元，氛围感不错。景点印象：凤凰山形胜凤凰，由横山、面山、灵风山、潭山、金山等构成。境内山清水秀，风景如画，是铜陵家喻户晓的旅游胜地。早在明朝“景泰”年间，诗人周铎就书写“庐外山高播半天，石也孤井聚甘泉，凤凰一饮千年后，尚有遗迹万古传”等十六首“凤凰八景”组…整体感受是超出预期，值得专门打卡。二刷意愿：是。', '0%', 31);
