INSERT INTO `travel_review` VALUES (27983, 'TR027983', '汀州府城隍庙', '龙岩', '福建', '亲子出游', '秋季', 6, 2, 772.00, '否', 2, '6月去的汀州府城隍庙，情侣出行。地点在龙岩，打车比较省心，现场人流量适中。这次玩了2天，人均花费约772元，拍照很出片。景点印象：汀州城隍庙位于福建省长汀县（城关）汀州镇兆征路。城隍是汉民族宗教文化中普遍崇祀的重要神祇，大多由有功于地方民众的名臣英雄充当，是汉族民间和道教信奉 守护城池之神。整体感受是没达到预期，不建议高峰来。二刷意愿：否。', '0%', 28);
