INSERT INTO `travel_review` VALUES (28023, 'TR028023', '忻州城楼', '忻州', '山西', '深度游', '秋季', 8, 4, 816.00, '是', 5, '8月去的忻州城楼，和朋友出行。地点在忻州，公交换乘方便，现场人流量适中。这次玩了4天，人均花费约816元，拍照很出片。景点印象：忻州城原有四门，城门上均有楼，始建于明万历二十四年（1596），由于历史的原因，仅有北城门楼幸存于今。城楼总高28米，宽七间，深四间，四周围廊重檐三滴水（明三层，暗三层），歇山式屋顶，楼内无柱，梁架结构简洁，连接严实，充分体现了古代劳动…整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 62);
INSERT INTO `travel_review` VALUES (28024, 'TR028024', '汪口', '上饶', '江西', '周末短途', '春季', 1, 4, 1233.00, '是', 5, '1月去的汪口，一个人出行。地点在上饶，打车比较省心，现场人流量适中。这次玩了4天，人均花费约1233元，夜景表现很好。景点印象：欣赏水墨画般的古朴村落，俞氏宗祠内精雕细琢的木质构造令人叹服。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '24%', 96);
