INSERT INTO `travel_review` VALUES (28048, 'TR028048', '白马寺', '洛阳', '河南', '文化打卡', '秋季', 7, 1, 393.00, '否', 5, '7月去的白马寺，情侣出行。地点在洛阳，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了1天，人均花费约393元，拍照很出片。景点印象：中国佛教的祖庭，寺内的“镇寺之宝”——元代的“夹贮干漆造像”，已有700年的历史。 观赏珍贵碑碣——元代书法家赵孟頫手书的《洛京白马寺祖庭记》。整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '49%', 62);
