INSERT INTO `travel_review` VALUES (28062, 'TR028062', '野马饲养放生基地', '哈密', '新疆', '深度游', '春季', 12, 1, 548.00, '否', 5, '12月去的野马饲养放生基地，一个人出行。地点在哈密，打车比较省心，现场游客较多。这次玩了1天，人均花费约548元，拍照很出片。景点印象：浦氏野马的学名叫“普尔热瓦尔斯基马”，原来是新疆野马，因俄罗斯探险家普尔热瓦尔斯基1876年捕猎到欧洲就以他的名字命名。19世纪中后期由于探险家的掠杀和其它原因，新疆野马在自己的故乡消声遗迹了。全世界的存量也不足1000匹，是比大熊猫还要珍…整体感受是超出预期，值得专门打卡。二刷意愿：否。', '0%', 58);
