INSERT INTO `travel_review` VALUES (28090, 'TR028090', '三和牡丹景区', '临汾', '山西', '文化打卡', '秋季', 8, 5, 1113.00, '否', 5, '8月去的三和牡丹景区，和朋友出行。地点在临汾，自驾停车需要提前规划，现场人流量适中。这次玩了5天，人均花费约1113元，历史文化气息浓。景点印象：位于山西晋南的古县历史悠久，文化底蕴深厚。据史记载，早在六千多年前仰韶文化时期当地已有人群居住繁衍，上古时期曾是大禹治水之地。在烟波浩渺的历史长河中，古县涌现出蔺相如等著名政治家，近代的古县还留有朱德、刘少奇、邓小平、薄一波、陈赓…整体感受是特别满意，值得专门打卡。二刷意愿：否。', '0%', 77);
