INSERT INTO `travel_review` VALUES (28097, 'TR028097', '毛岸苗村', '五指山', '海南', '城市漫游', '秋季', 8, 6, 1541.00, '是', 5, '8月去的毛岸苗村，和朋友出行。地点在五指山，打车比较省心，现场人不算多。这次玩了6天，人均花费约1541元，历史文化气息浓。景点印象：沿海榆中线公路南行15公里到达冲山镇，陡水河缓缓流过，毛岸苗村就位于此。苗村保留着浓郁的民族特色，特有的山兰禾架和竹编的小谷包点缀着房前屋后。每当三月三佳节，苗族同胞便跳起欢乐的舞蹈，捧出山兰米饭和野味山菜，欢迎远方的客人，让人倍感…整体感受是超出预期，很推荐。二刷意愿：是。', '2%', 96);
