INSERT INTO `travel_review` VALUES (28099, 'TR028099', '乌斯河镇', '雅安', '四川', '文化打卡', '冬季', 9, 1, 405.00, '否', 5, '9月去的乌斯河镇，情侣出行。地点在雅安，打车比较省心，现场游客较多。这次玩了1天，人均花费约405元，历史文化气息浓。景点印象：汉源县乌斯河镇位于汉源县城东37公里处。为汉（源）乌（斯河）、金（口河）乌（斯河）、皇（木）越（西）公路与成昆铁路的交点。整体感受是特别满意，以后还会来。二刷意愿：否。', '0%', 72);
INSERT INTO `travel_review` VALUES (28100, 'TR028100', '龙江公园', '楚雄州', '云南', '城市漫游', '冬季', 9, 4, 1068.00, '是', 5, '9月去的龙江公园，和家人出行。地点在楚雄州，打车比较省心，现场人流量适中。这次玩了4天，人均花费约1068元，拍照很出片。景点印象：龙江公园，是1981年才开始兴建的。这里原是龙川江的旧河道，形如马蹄，故名马蹄弯。现因龙川江改道，已辟为公园。总面积为170余亩。这里的建筑安排得比较丰富而和谐，北面小巧的梅园，回廊阁楼，梅树环绕，清净幽雅，其中常有花卉、文物、字画展览…整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '1%', 59);
