INSERT INTO `travel_review` VALUES (28157, 'TR028157', '哈拉新村', '齐齐哈尔', '黑龙江', '城市漫游', '夏季', 3, 2, 905.00, '是', 5, '3月去的哈拉新村，和朋友出行。地点在齐齐哈尔，公交换乘方便，现场人流量适中。这次玩了2天，人均花费约905元，夜景表现很好。景点印象：蛇洞山风景区位于齐齐哈尔市碾子山区西部4.5公里，占地面积300公顷，最高峰龙峰海拔406米，是国家“AA”级风景区。景区由青石崖、蛇洞山、龙峰、佛尔寺及西河园等景观构成。区内峰峦起伏，怪石嶙峋，各景点错落有致、浑然一体，龟、牛、蛙、龙、狮…整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '0%', 107);
