INSERT INTO `travel_review` VALUES (28169, 'TR028169', '宝鸡青铜器博物院', '宝鸡', '陕西', '周末短途', '春季', 2, 1, 234.00, '否', 5, '2月去的宝鸡青铜器博物院，情侣出行。地点在宝鸡，地铁到达方便，现场游客较多。这次玩了1天，人均花费约234元，氛围感不错。景点印象：馆内珍藏众多的青铜器，精品众多，有厉王胡簋、秦公镈等重器。 所藏的“何尊”，内有铭文“宅兹中国”，是“中国”称谓最早的文字记载。整体感受是超出预期，值得专门打卡。二刷意愿：否。', '3%', 83);
INSERT INTO `travel_review` VALUES (28170, 'TR028170', '玉露井', '泰安', '山东', '周末短途', '冬季', 11, 5, 985.00, '否', 2, '11月去的玉露井，情侣出行。地点在泰安，公交换乘方便，现场人不算多。这次玩了5天，人均花费约985元，夜景表现很好。景点印象：周边配套比较齐全整体感受是没达到预期，可考虑其他景点。二刷意愿：否。', '0%', 0);
INSERT INTO `travel_review` VALUES (28171, 'TR028171', '黄仙洞', '荆门', '湖北', '周末短途', '冬季', 9, 6, 1556.00, '否', 4, '9月去的黄仙洞，情侣出行。地点在荆门，地铁到达方便，现场人不算多。这次玩了6天，人均花费约1556元，历史文化气息浓。景点印象：黄仙洞位于大洪山脉南麓，相传黄石公曾在此休憩，故得名黄仙洞。洞内拥有四个世界级景级景观：边石池大厅、钙膜片边坝、石将军溶蚀石牙、三拱门景观。尤其是边石池，气势恢弘，波澜壮阔，被誉为世界溶洞之一绝。整体感受是体验挺好，周末来刚好。二刷意愿：否。', '20%', 65);
