INSERT INTO `travel_review` VALUES (28179, 'TR028179', '大漠沙湖滑雪场', '石嘴山', '宁夏', '文化打卡', '春季', 12, 6, 1496.00, '否', 4, '12月去的大漠沙湖滑雪场，一个人出行。地点在石嘴山，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了6天，人均花费约1496元，夜景表现很好。景点印象：沙湖滑雪场借助的是沙湖一望无垠的万亩冰园，得天独厚的自然条件也让来者乐此不疲。沙湖的优势在于溶身于冰天雪地的大自然之中，任何的娱乐完全可以发自内心，自娱自乐。这里的冰面娱乐设施充满童趣，诸如打老牛、溜冰车都是我们童年的游戏，信手拈…整体感受是整体不错，推荐来看看。二刷意愿：否。', '0%', 72);
