INSERT INTO `travel_review` VALUES (28186, 'TR028186', '隆德县城', '固原', '宁夏', '城市漫游', '冬季', 11, 4, 958.00, '否', 2, '11月去的隆德县城，一个人出行。地点在固原，自驾停车需要提前规划，现场人不算多。这次玩了4天，人均花费约958元，氛围感不错。景点印象：隆德县城位于六盘山西5公里的甜水河南岸。这里地势开阔，\"坦为兵冲\"，为历代兵家用兵之地。秦、汉时期朝那县治古城遗址，位于彭阳县城西15公里处的古城镇境内。地处茹河与任山河交汇处的茹河北岸三角平川正中，东濒店洼水库，西临朝那湫，北依罗家…整体感受是略失望，可考虑其他景点。二刷意愿：否。', '0%', 63);
