INSERT INTO `travel_review` VALUES (28198, 'TR028198', '清水泉旅游度假村', '昌吉', '新疆', '深度游', '秋季', 8, 3, 385.00, '是', 5, '8月去的清水泉旅游度假村，和朋友出行。地点在昌吉，地铁到达方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约385元，氛围感不错。景点印象：位于硫磺沟镇以南8公里处，头屯河西岸，依山傍水，占地面积45708平方米，约67亩，总建筑面积1630平方米，景区内有一眼泉水涌出地面，甘甜清澈，潺潺不息，得名清水泉。 泉水蜿蜒流淌，形成多处天然水潭，泉水叮咚，自然回响。度假村内野生植被繁盛…整体感受是挺惊喜，以后还会来。二刷意愿：是。', '0%', 79);
