INSERT INTO `travel_review` VALUES (28235, 'TR028235', '敦煌古城', '酒泉', '甘肃', '文化打卡', '夏季', 5, 1, 480.00, '是', 5, '5月去的敦煌古城，一个人出行。地点在酒泉，打车比较省心，现场人不算多。这次玩了1天，人均花费约480元，夜景表现很好。景点印象：漫步西北特色的古城内，拍摄古色古香的漂亮照片。 体会几条街道不同风情的建筑，感受地域穿梭的乐趣。 行走在众多影视作品的拍摄地，寻找心中熟悉的场景。整体感受是挺惊喜，很推荐。二刷意愿：是。', '7%', 51);
