INSERT INTO `travel_review` VALUES (28239, 'TR028239', '古湖', '内江', '四川', '亲子出游', '冬季', 9, 2, 749.00, '否', 2, '9月去的古湖，一个人出行。地点在内江，打车比较省心，现场游客较多。这次玩了2天，人均花费约749元，氛围感不错。景点印象：隆昌古湖风景区位于隆昌县西部，它是以古宇庙为主体的风景名胜区，包括湖区、圣灯山、金鹅镇三景区10余个景点，总面积61平方公里。景区有峭壁、怪石、瀑布溶洞、寺庙、牌坊等风景名胜。古湖位于隆昌县城西南2公里，在楼峰山与圣灯山之间，湖面5平方…整体感受是体验偏一般，不建议高峰来。二刷意愿：否。', '0%', 40);
