INSERT INTO `travel_review` VALUES (28275, 'TR028275', '龙井古民居', '贺州', '广西', '拍照旅行', '冬季', 9, 1, 685.00, '否', 3, '9月去的龙井古民居，情侣出行。地点在贺州，地铁到达方便，现场游客较多。这次玩了1天，人均花费约685元，拍照很出片。景点印象：距离市区9千米。历史文化类人文风景旅游区。是一个建于清同治—光绪年间的古村，目前仍然保留大量清朝同治至光绪年间的古民居群，其中包括民国三任总统顾问张廷辅故居。古民居建筑技术精湛，建筑物雕龙画凤，至今保持完整，龙井村也是本地人聚居的…整体感受是还可以，避开高峰更好。二刷意愿：否。', '0%', 28);
INSERT INTO `travel_review` VALUES (28276, 'TR028276', '云和梯田景区', '丽水', '浙江', '文化打卡', '秋季', 6, 3, 804.00, '是', 5, '6月去的云和梯田景区，情侣出行。地点在丽水，地铁到达方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约804元，氛围感不错。景点印象：看华东地区规模最大的梯田，在七星墩守候云海日出。 在坑根石寨看当年银矿留下的古井、老房子。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '26%', 102);
