INSERT INTO `travel_review` VALUES (28279, 'TR028279', '黄蜂窝茶山', '梅州', '广东', '亲子出游', '秋季', 8, 5, 1341.00, '是', 4, '8月去的黄蜂窝茶山，和家人出行。地点在梅州，打车比较省心，现场游客较多。这次玩了5天，人均花费约1341元，拍照很出片。景点印象：黄蜂窝茶山旅游区，于一九九零年建成，是集种茶、采茶、制茶、宣传茶文化的名茶示范基地和旅游观光的旅游区。整体感受是整体不错，可以安排半天到一天。二刷意愿：是。', '5%', 76);
