INSERT INTO `travel_review` VALUES (28298, 'TR028298', '侗文化城', '怀化', '湖南', '深度游', '冬季', 10, 2, 539.00, '否', 5, '10月去的侗文化城，和朋友出行。地点在怀化，自驾停车需要提前规划，现场游客较多。这次玩了2天，人均花费约539元，氛围感不错。景点印象：湖南怀化中国侗文化城位于芷江侗族自治县象狮坡省级森林公园内，距怀化市中心6公里，西到芷江抗战胜利受降纪念馆20余公里，南连舞水河，北靠湘黔铁路和320国道，区位、交通条件十分优越。该景区占地3500亩，阳光、松林、溪流、草滩构成了这里独特而…整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '2%', 79);
INSERT INTO `travel_review` VALUES (28299, 'TR028299', '色拉寺', '拉萨', '西藏', '亲子出游', '春季', 2, 2, 285.00, '否', 5, '2月去的色拉寺，情侣出行。地点在拉萨，打车比较省心，现场高峰时段比较拥挤。这次玩了2天，人均花费约285元，夜景表现很好。景点印象：看著名的辩经，整个场面十分精彩，登色拉寺后山，可以拍摄拉萨全景。整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '32%', 93);
