INSERT INTO `travel_review` VALUES (28335, 'TR028335', '莲花湖', '锦州', '辽宁', '深度游', '夏季', 5, 4, 1064.00, '否', 4, '5月去的莲花湖，一个人出行。地点在锦州，打车比较省心，现场游客较多。这次玩了4天，人均花费约1064元，历史文化气息浓。景点印象：莲花湖位于黑山县姜屯镇东北4公里处，在土城子村旁，有一块近千亩的水面， 湖内数万株自然生长的莲花亭亭玉立，硕大的绿叶上滚动的水珠晶滢透澈，粉中透白的莲花散发着迷人的芳香。水中菱角一串串，水下鱼儿成群结对嬉戏，竹杆支撑着小船在湖面滑行…整体感受是整体不错，推荐来看看。二刷意愿：否。', '0%', 61);
