INSERT INTO `travel_review` VALUES (28401, 'TR028401', '遗址', '咸宁', '湖北', '亲子出游', '秋季', 6, 2, 1020.00, '是', 4, '6月去的遗址，情侣出行。地点在咸宁，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约1020元，夜景表现很好。景点印象：古战场赤壁，位于长江中游南岸，湖北省赤壁市境内，距武汉市164公里， 距湖南岳阳90公里，湖北省重点文物保护单位。\n赤璧位于赤璧市境。东汉建安十三年（元二○八年），曹操率二十几万大军南下，连克新野、襄阳数城，从江陵顺江东下，与逆江西上的…整体感受是整体不错，推荐来看看。二刷意愿：是。', '0%', 47);
