INSERT INTO `travel_review` VALUES (28435, 'TR028435', '邓庄农业科技示范园', '衡水', '河北', '拍照旅行', '春季', 1, 6, 1368.00, '否', 5, '1月去的邓庄农业科技示范园，和朋友出行。地点在衡水，公交换乘方便，现场高峰时段比较拥挤。这次玩了6天，人均花费约1368元，夜景表现很好。景点印象：邓庄农业科技示范园区先后投资170多万元新建连栋温室一座，修建了绿色长廊和百亩果脯采摘园，完善了蔬菜花卉组织培养中心和肉奶牛胚胎移植中心，把现代农业技术示范园区改造成了一个集科研、生产、观光、学习于一体的农业旅游示范点。整体感受是特别满意，很推荐。二刷意愿：否。', '0%', 72);
