INSERT INTO `travel_review` VALUES (28437, 'TR028437', '飞龙洞', '吉安', '江西', '深度游', '冬季', 9, 1, 492.00, '否', 3, '9月去的飞龙洞，一个人出行。地点在吉安，地铁到达方便，现场游客较多。这次玩了1天，人均花费约492元，拍照很出片。景点印象：位于桐木岭附近山腰上,是一个巨大的溶洞,洞口通道是一先倾斜后直立的孔穴。洞内石钟乳、石笋，石柱、石花等琳琅满目，奇幻多姿，现已成为井冈山著名的风景点之一。整体感受是中规中矩，避开高峰更好。二刷意愿：否。', '0%', 73);
