INSERT INTO `travel_review` VALUES (28439, 'TR028439', '金山寺', '抚州', '江西', '亲子出游', '春季', 1, 2, 968.00, '是', 5, '1月去的金山寺，情侣出行。地点在抚州，公交换乘方便，现场人流量适中。这次玩了2天，人均花费约968元，氛围感不错。景点印象：江西尼众佛学院设于江西省临川市金山寺。古之临川，有“才子之乡”之美誉，金山寺所在之金山岭，钟云毓秀，风景如画。宋朝名相王安石曾两次赋诗赞之。金山寺始建于唐，盛时有僧五百余人。然自宋以来，金山寺几经摧颓；明末遭兵燹后，三百余年间，有…整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 107);
