INSERT INTO `travel_review` VALUES (28456, 'TR028456', '彩铜照壁', '许昌', '河南', '亲子出游', '冬季', 9, 3, 864.00, '否', 5, '9月去的彩铜照壁，情侣出行。地点在许昌，自驾停车需要提前规划，现场人不算多。这次玩了3天，人均花费约864元，历史文化气息浓。景点印象：位于乾明寺内，建于明嘉靖年间，长12．93米，高4．66米，厚0．73米。上嵌浮雕，雕功精细，风格古朴，典雅大方，有较高的艺术价值。据《庄子》所载，它是由黄帝及其随从绘制。正面“黄帝采铜图”，两侧有联“梵林明媚储万汇之精英，山势嵯峨壮一方之…整体感受是特别满意，很推荐。二刷意愿：否。', '0%', 92);
