INSERT INTO `travel_review` VALUES (28471, 'TR028471', '太行太岳烈士陵园', '长治', '山西', '亲子出游', '秋季', 7, 7, 1765.00, '是', 5, '7月去的太行太岳烈士陵园，和朋友出行。地点在长治，打车比较省心，现场游客较多。这次玩了7天，人均花费约1765元，历史文化气息浓。景点印象：位于长治市内的梅辉坡。它是根据1946年3月晋冀鲁豫边区参议会第一届第二次会议的决议，为纪念在抗日战争中英勇牺牲于太行太岳的中华民族优秀儿女而建立的。1951年落成。 占地总面积为9460万平方米。陵园开南、东两个门，南门为正门。大门两壁是戎子…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 41);
