INSERT INTO `travel_review` VALUES (28518, 'TR028518', '香山', '陇南', '甘肃', '深度游', '冬季', 10, 4, 1404.00, '是', 5, '10月去的香山，和朋友出行。地点在陇南，公交换乘方便，现场高峰时段比较拥挤。这次玩了4天，人均花费约1404元，夜景表现很好。景点印象：香山位于甘肃省礼县境内，主要保护森林生态系统、名胜古迹以及珍稀动物等。区内有天然林3730公顷，飞播造林4000公顷。已知有高等植物120科250属500余种；野生动物中兽类30余种，鸟类50种，爬行类10种，两栖类10种，鱼类9种，昆虫类数百种，属国家重…整体感受是超出预期，很推荐。二刷意愿：是。', '3%', 95);
INSERT INTO `travel_review` VALUES (28519, 'TR028519', '跃进湖', '常德', '湖南', '文化打卡', '春季', 2, 6, 1472.00, '否', 4, '2月去的跃进湖，情侣出行。地点在常德，公交换乘方便，现场人流量适中。这次玩了6天，人均花费约1472元，历史文化气息浓。景点印象：原为1958年修建的跃进水库，位于五溪湖东北处港二口镇境内，与五溪湖首尾相连，同居枉水西源干流。跃进湖聚雨面积12.5平方公里,正常库容1700万立方米,蓄水面积4590亩。水库大坝在桅子岗处,长263米,坝高25米。大坝处湖面开阔,湖畔山上种了雪梨、苍溪…整体感受是体验挺好，可以安排半天到一天。二刷意愿：否。', '0%', 37);
