INSERT INTO `travel_review` VALUES (28535, 'TR028535', '叶赫风景名胜区', '四平', '吉林', '周末短途', '春季', 2, 1, 343.00, '否', 5, '2月去的叶赫风景名胜区，情侣出行。地点在四平，打车比较省心，现场人不算多。这次玩了1天，人均花费约343元，拍照很出片。景点印象：叶赫风景名胜区位于吉辽两省结合部，吉林省梨树县东南部――叶赫满族镇内，是连接开发区内山门、二龙湖风景区旅游线的纽带。总面积 68 平方公里，集满族历史文化特色与自然山水风光于一体，风格独特，是我国北方少有的旅游胜地。\n叶赫，是满族的重…整体感受是挺惊喜，值得专门打卡。二刷意愿：否。', '0%', 95);
