INSERT INTO `travel_review` VALUES (28554, 'TR028554', '浆水泉', '济南', '山东', '城市漫游', '春季', 2, 6, 1422.00, '是', 5, '2月去的浆水泉，和家人出行。地点在济南，打车比较省心，现场游客较多。这次玩了6天，人均花费约1422元，夜景表现很好。景点印象：浆水泉公园在回龙山、老虎山脚下，因有济南七十二名泉之一的浆水泉坐落在回龙山脚下便命名为浆水泉公园。乘坐49路公共汽车到浆水泉下车，再步行300米就到达浆水泉公园。整体感受是超出预期，很推荐。二刷意愿：是。', '0%', 72);
