INSERT INTO `travel_review` VALUES (28563, 'TR028563', '沙漠博物馆', '中卫', '宁夏', '深度游', '秋季', 6, 6, 1602.00, '否', 5, '6月去的沙漠博物馆，和朋友出行。地点在中卫，公交换乘方便，现场高峰时段比较拥挤。这次玩了6天，人均花费约1602元，历史文化气息浓。景点印象：博物馆位于沙坡头区迎水桥镇旅游景区，在这里可以了解到沙漠科普知识，认识沙漠的历史文化，还可以参与沙漠互动游戏。整体感受是挺惊喜，以后还会来。二刷意愿：否。', '1%', 85);
INSERT INTO `travel_review` VALUES (28564, 'TR028564', '猪叫石', '安阳', '河南', '城市漫游', '夏季', 3, 6, 1720.00, '是', 5, '3月去的猪叫石，情侣出行。地点在安阳，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了6天，人均花费约1720元，夜景表现很好。景点印象：千古之谜猪叫石，去灾消难保平安。猪叫石也称“报警石\"、\"灵通石\"、\"神石”、“奇石’等，因其发音如猪叫，故称“猪叫石\"。该石位于林州市太行大峡谷风景名胜区内的高家台辉伏岩自然村旁，进出交通方便，县乡二级水泥公路直通景区，东距林州市区32…整体感受是特别满意，以后还会来。二刷意愿：是。', '0%', 65);
