INSERT INTO `travel_review` VALUES (28651, 'TR028651', '泗水塔', '南阳', '河南', '城市漫游', '夏季', 5, 1, 80.00, '否', 3, '5月去的泗水塔，和家人出行。地点在南阳，自驾停车需要提前规划，现场人不算多。这次玩了1天，人均花费约80元，氛围感不错。景点印象：泗洲塔又称泗水塔，位于唐河县城东南隅菩提寺旧址内。宋绍圣二年（1095年）建，高47.33米。底层坐落在台基上，南面辟一拱形门，第二至十层每层各辟1门。下均置砖雕斗拱，转角处有风铎，檐下为平座，塔内有塔心柱，柱之周围筑盘88旋石阶踏道，第一层…整体感受是还可以，避开高峰更好。二刷意愿：否。', '0%', 42);
