INSERT INTO `travel_review` VALUES (28657, 'TR028657', '龙台观', '商洛', '陕西', '深度游', '春季', 2, 3, 636.00, '是', 5, '2月去的龙台观，和朋友出行。地点在商洛，打车比较省心，现场人不算多。这次玩了3天，人均花费约636元，历史文化气息浓。景点印象：龙台观位于丹凤县城东30公里处的铁峪铺镇花子沟村，观的对面有一天然溶洞名为黄龙洞。洞高数丈，洞深无底，洞内钟乳奇观，如龙腾虎跃，似玉树琼阁，造型精美。山腰一股龙泉喷泻成瀑布披岩而下，为天然浴泉，游人可沐。\n与洞相对的峻岩峰顶有龙台观…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 50);
