INSERT INTO `travel_review` VALUES (28659, 'TR028659', '圣寿寺舍利塔', '运城', '山西', '拍照旅行', '春季', 1, 4, 1008.00, '是', 4, '1月去的圣寿寺舍利塔，情侣出行。地点在运城，地铁到达方便，现场高峰时段比较拥挤。这次玩了4天，人均花费约1008元，拍照很出片。景点印象：在芮城县城北里许。创建于北宋天圣年间，明、清时曾予重修。现仅存宋建砖塔。增平面八角形，十三层，高约48米。塔身锥形，逐级向内收缩，檐下砖雕斗拱，完全仿木结构形制，古朴苍劲。塔中空。直达顶层，各层原有楼板，可缘梯攀登、现已不存。塔内保…整体感受是体验挺好，推荐来看看。二刷意愿：是。', '0%', 80);
