INSERT INTO `travel_review` VALUES (28725, 'TR028725', '象山', '荆门', '湖北', '亲子出游', '冬季', 9, 7, 1787.00, '是', 3, '9月去的象山，和家人出行。地点在荆门，地铁到达方便，现场人不算多。这次玩了7天，人均花费约1787元，氛围感不错。景点印象：在荆门市西郊。原名蒙山，因象山先生陆九渊曾讲学于此而称今名。历为游览胜地。南北向，长600米，宽250米，海拔176米。现为占地50余万平方米的龙泉公园重要组成部分。有龙泉书院、陆夫子词、老莱山庄、蒙泉、龙泉、惠泉、顺口泉、文明湖、讲经台、…整体感受是体验一般，按需选择。二刷意愿：是。', '0%', 68);
INSERT INTO `travel_review` VALUES (28726, 'TR028726', '晋祠博物馆', '太原', '山西', '拍照旅行', '春季', 2, 1, 729.00, '是', 5, '2月去的晋祠博物馆，和家人出行。地点在太原，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约729元，夜景表现很好。景点印象：晋国的宗祠，梁柱上没用一颗铁钉的献殿、有梁无柱的圣母殿最为神奇。整体感受是挺惊喜，很推荐。二刷意愿：是。', '29%', 62);
INSERT INTO `travel_review` VALUES (28727, 'TR028727', '长洲岛', '广州', '广东', '亲子出游', '冬季', 11, 6, 1589.00, '是', 5, '11月去的长洲岛，情侣出行。地点在广州，打车比较省心，现场游客较多。这次玩了6天，人均花费约1589元，夜景表现很好。景点印象：黄埔地区的江心岛，因黄埔军校所在地而出名，保留了很多文化古迹和革命史迹，环境也不错。整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 89);
INSERT INTO `travel_review` VALUES (28728, 'TR028728', '援疆生态公园', '五家渠', '新疆', '深度游', '秋季', 6, 2, 796.00, '否', 4, '6月去的援疆生态公园，和朋友出行。地点在五家渠，打车比较省心，现场人不算多。这次玩了2天，人均花费约796元，拍照很出片。景点印象：景点本身有一定特色整体感受是还蛮满意，可以安排半天到一天。二刷意愿：否。', '0%', 71);
INSERT INTO `travel_review` VALUES (28729, 'TR028729', '虎跳峡(香格里拉段)', '迪庆', '云南', '文化打卡', '冬季', 10, 1, 191.00, '否', 5, '10月去的虎跳峡(香格里拉段)，和家人出行。地点在迪庆，自驾停车需要提前规划，现场人不算多。这次玩了1天，人均花费约191元，氛围感不错。景点印象：位列“国内十大徒步线路”之一，曾获《中国国家地理》杂志“中国十大峡谷之一”称号。整体感受是挺惊喜，很推荐。二刷意愿：否。', '0%', 54);
INSERT INTO `travel_review` VALUES (28730, 'TR028730', '抚顺苏子河漂流', '抚顺', '辽宁', '文化打卡', '冬季', 10, 3, 918.00, '是', 2, '10月去的抚顺苏子河漂流，一个人出行。地点在抚顺，打车比较省心，现场人不算多。这次玩了3天，人均花费约918元，夜景表现很好。景点印象：苏子河漂流位于新宾满族自治县境内的苏子河中段，距市区90余公里，乘车经202国道和东南公路仅1小时就可以到达。坐在船筏上沿途可欣赏到冰湖沟、望石谷、石龙峡、望松台、奇峰山、卧龙岭、怪石涯、万古峡、刺激关等景观。漂流段全长13公里，漂流全程…整体感受是略失望，建议谨慎前往。二刷意愿：是。', '0%', 31);
INSERT INTO `travel_review` VALUES (28731, 'TR028731', '阴山古刹', '乌兰察布', '内蒙古', '亲子出游', '夏季', 5, 1, 666.00, '否', 2, '5月去的阴山古刹，情侣出行。地点在乌兰察布，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约666元，夜景表现很好。景点印象：在呼和浩特北一百公里，是辽阔的蒙古草原上众多喇嘛庙宇中的一座。四周有茫茫无际的草原大地，殿宇雄伟的姿态映衬在蓝天和绿草之间，就像绣在绿色缎面上的精美图案。\n阴山古刹规模并不很大，只有三数殿宇，但建筑精巧玲珑，金碧辉煌。大殿建于方整…整体感受是没达到预期，建议谨慎前往。二刷意愿：否。', '0%', 42);
