INSERT INTO `travel_review` VALUES (28735, 'TR028735', '太极洞', '宣城', '安徽', '拍照旅行', '冬季', 9, 1, 545.00, '是', 4, '9月去的太极洞，和朋友出行。地点在宣城，地铁到达方便，现场游客较多。这次玩了1天，人均花费约545元，夜景表现很好。景点印象：皖南溶洞游首选，自古就有人游览，洞内钟乳石千姿百态。 欣赏洞中黄山，钟乳石群像黄山72峰，还能看到灯光营造出的黄山日出。 坐游船探秘地下暗河很有趣，船只摇摇晃晃，时不时需要低头躲避山岩。整体感受是整体不错，周末来刚好。二刷意愿：是。', '2%', 40);
