INSERT INTO `travel_review` VALUES (28775, 'TR028775', '黑河森林公园', '张掖', '甘肃', '拍照旅行', '秋季', 7, 3, 879.00, '否', 4, '7月去的黑河森林公园，情侣出行。地点在张掖，公交换乘方便，现场人流量适中。这次玩了3天，人均花费约879元，历史文化气息浓。景点印象：黑河森林公园位于甘州城区西郊、国道312线2737公里处的黑河滩林区，我国第二大内陆河------黑河萦绕而过，这里树木郁郁葱葱，泉流清澈见底，鸟鸣清脆悦耳，奇花异草争奇斗艳；春绿如茵，夏凉风徐，秋红似火，冬静情幽，自然景观独具特色。\n公园始建…整体感受是还蛮满意，可以安排半天到一天。二刷意愿：否。', '0%', 60);
