INSERT INTO `travel_review` VALUES (28834, 'TR028834', '二佛寺', '自贡', '四川', '亲子出游', '秋季', 6, 1, 96.00, '否', 4, '6月去的二佛寺，情侣出行。地点在自贡，打车比较省心，现场人流量适中。这次玩了1天，人均花费约96元，历史文化气息浓。景点印象：荣县二佛寺沿崖林立，造像上千尊，唐宋时名“浮图崖”，亦称千佛崖。因其众多佛像装金饰彩，阳光照射，金碧辉煌，故又称“金碧崖”。\n佛像为唐代开凿的弥勒坐佛，佛高5.8米，宽2.6米。左右龛壁上，刻有28小龛120尊造佛。整体感受是还蛮满意，周末来刚好。二刷意愿：否。', '0%', 78);
INSERT INTO `travel_review` VALUES (28835, 'TR028835', '紫云山', '许昌', '河南', '亲子出游', '冬季', 10, 3, 541.00, '否', 4, '10月去的紫云山，和朋友出行。地点在许昌，自驾停车需要提前规划，现场人流量适中。这次玩了3天，人均花费约541元，夜景表现很好。景点印象：紫云山风景区位于河南省襄城县境内，311国道，郑南、许南公路穿境而过，距郑、汴、洛、宛均百余公里，平、许、漯15―60公里，与石人山飞少林寺、乾明寺联为一体。景区由九山十八峰，五湖一条河和众多文物古迹组成，面积40多平方公里。九山谓紫云山…整体感受是还蛮满意，推荐来看看。二刷意愿：否。', '0%', 61);
