INSERT INTO `travel_review` VALUES (28841, 'TR028841', '一万泉旅游度假村', '昌吉', '新疆', '亲子出游', '冬季', 9, 3, 1163.00, '否', 4, '9月去的一万泉旅游度假村，和朋友出行。地点在昌吉，公交换乘方便，现场人流量适中。这次玩了3天，人均花费约1163元，夜景表现很好。景点印象：一万泉旅游度假村为国家AAA级景区，位于农六师奇台农场以南天山无名峰下，源于哈拉萨依沟，有众多泉水汇成一股清流，常年不息，故名“一万泉”。\n　　此景点是北疆东部天山北坡最好的天然草场之一，自然降水丰富，山梁阴坡翠松挺拔，阳坡牧草茂盛，…整体感受是整体不错，推荐来看看。二刷意愿：否。', '0%', 48);
