INSERT INTO `travel_review` VALUES (28861, 'TR028861', '神象山', '汕尾', '广东', '亲子出游', '冬季', 9, 2, 797.00, '否', 4, '9月去的神象山，情侣出行。地点在汕尾，打车比较省心，现场人流量适中。这次玩了2天，人均花费约797元，历史文化气息浓。景点印象：神象山公园风景区位于南万镇南天湖旁，海拔653米！整座山因酷似一头大象而得名！山上树木莽莽苍苍！百年老树随处可见！说不出名的奇花异草争奇斗艳。为了游客能近距离的亲近大自然！观赏雄伟神象山，特开辟了登山险道！架设长200多米的登山木梯通往…整体感受是体验挺好，周末来刚好。二刷意愿：否。', '0%', 96);
