INSERT INTO `travel_review` VALUES (28917, 'TR028917', '辽南国际射击娱乐中心', '营口', '辽宁', '拍照旅行', '夏季', 5, 5, 1381.00, '否', 5, '5月去的辽南国际射击娱乐中心，和朋友出行。地点在营口，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了5天，人均花费约1381元，历史文化气息浓。景点印象：拥有东北地区唯一一家真枪实弹射击俱乐部，设施先进，是射击加游泳休闲锻炼好去处。整体感受是特别满意，很推荐。二刷意愿：否。', '0%', 114);
