INSERT INTO `travel_review` VALUES (28936, 'TR028936', '冶父山', '巢湖', '安徽', '拍照旅行', '秋季', 6, 2, 644.00, '是', 5, '6月去的冶父山，一个人出行。地点在巢湖，打车比较省心，现场人流量适中。这次玩了2天，人均花费约644元，氛围感不错。景点印象：冶父山，距庐江县城东约9公里，峰峦叠翠，庙宇辉煌，古迹遗存，佳传甚多，有\"江北小九华\"之称。据传春秋时，铸剑之父欧冶子曾在此山铸剑，山上存有铸剑池古迹，因此得名冶父山。诗人赞道：“长剑欲一淬，夜寻冶父山，揽衣望奇气，直在斗牛间。”\n冶…整体感受是超出预期，值得专门打卡。二刷意愿：是。', '0%', 123);
