INSERT INTO `travel_review` VALUES (28940, 'TR028940', '古乡湖景区', '林芝', '西藏', '亲子出游', '春季', 2, 2, 493.00, '是', 5, '2月去的古乡湖景区，一个人出行。地点在林芝，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约493元，拍照很出片。景点印象：帕隆藏布江的堰塞湖，有亭台树木，环境怡人。整体感受是挺惊喜，很推荐。二刷意愿：是。', '3%', 104);
INSERT INTO `travel_review` VALUES (28941, 'TR028941', '王莽洞', '荆门', '湖北', '拍照旅行', '秋季', 6, 1, 359.00, '否', 4, '6月去的王莽洞，一个人出行。地点在荆门，自驾停车需要提前规划，现场游客较多。这次玩了1天，人均花费约359元，氛围感不错。景点印象：王莽洞风景区为国家2A级景点，是太子山国家森林公园的核心景区，位于荆门市东南。是一个以优良的生态环境为基础，人文景观为辅，集观光、度假、探险、科考于一体的生态旅游风景区。 景区内森林植被茂盛，四季分明，气候宜人。景区主要以自然景观、…整体感受是还蛮满意，推荐来看看。二刷意愿：否。', '0%', 50);
