INSERT INTO `travel_review` VALUES (29006, 'TR029006', '党家岔堰湖', '固原', '宁夏', '亲子出游', '春季', 1, 3, 867.00, '是', 4, '1月去的党家岔堰湖，和朋友出行。地点在固原，打车比较省心，现场人流量适中。这次玩了3天，人均花费约867元，氛围感不错。景点印象：党家岔堰湖是目前同原地区最大的地震堰塞湖，也是宁夏最大的堰塞湖。现有水面南北长3110米，东西平均宽600 米，水面积达186.6万平方米。平均水深6米，最大水深11.5 米，蓄水量1120万立方米。湖内生长着鲢、鲤、草鱼等近10 种鱼类，其中有彩色鲫鱼。…整体感受是整体不错，周末来刚好。二刷意愿：是。', '0%', 65);
INSERT INTO `travel_review` VALUES (29007, 'TR029007', '宁波鼓楼', '宁波', '浙江', '周末短途', '夏季', 3, 4, 1212.00, '是', 5, '3月去的宁波鼓楼，和朋友出行。地点在宁波，自驾停车需要提前规划，现场人流量适中。这次玩了4天，人均花费约1212元，氛围感不错。景点印象：中西合璧的古老地标，周围古色古香的步行街适合夜晚吃吃逛逛。整体感受是超出预期，很推荐。二刷意愿：是。', '20%', 107);
