INSERT INTO `travel_review` VALUES (29012, 'TR029012', '清水湾旅游区', '陵水', '海南', '城市漫游', '秋季', 8, 3, 917.00, '否', 5, '8月去的清水湾旅游区，一个人出行。地点在陵水，打车比较省心，现场人不算多。这次玩了3天，人均花费约917元，历史文化气息浓。景点印象：原生态海滩，一半细沙，一半礁岩，景色奇特。整体感受是挺惊喜，以后还会来。二刷意愿：否。', '1%', 84);
