INSERT INTO `travel_review` VALUES (29022, 'TR029022', '小天池', '九江', '江西', '城市漫游', '冬季', 10, 2, 731.00, '是', 5, '10月去的小天池，一个人出行。地点在九江，自驾停车需要提前规划，现场人流量适中。这次玩了2天，人均花费约731元，夜景表现很好。景点印象：周边配套比较齐全整体感受是特别满意，很推荐。二刷意愿：是。', '3%', 66);
INSERT INTO `travel_review` VALUES (29023, 'TR029023', '金华山', '遂宁', '四川', '拍照旅行', '秋季', 8, 4, 1326.00, '否', 4, '8月去的金华山，和朋友出行。地点在遂宁，公交换乘方便，现场人不算多。这次玩了4天，人均花费约1326元，历史文化气息浓。景点印象：位于金华城北，为国家级重点风景名胜区。海拔150-1200米，绵延250平方公里，像一条长龙横卧于古婺大地。全年气候湿润、云雾缥缈，环境清凉宜人，并以林海莽原、奇异洞景和黄大仙真源为特色，被游客公认为休闲度假的仙游胜地。\n金华山洞奇、石怪、山…整体感受是整体不错，可以安排半天到一天。二刷意愿：否。', '50%', 90);
