INSERT INTO `travel_review` VALUES (29029, 'TR029029', '紫阳峰', '邵阳', '湖南', '城市漫游', '春季', 1, 2, 817.00, '否', 3, '1月去的紫阳峰，和朋友出行。地点在邵阳，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约817元，拍照很出片。景点印象：紫阳峰\n紫阳峰被誉为中国南方“呼伦贝尔”的南山牧场，犹如一颗璀璨的明珠，镶嵌在湘西南边境，著名的紫阳峰牧区便是方圆百里的南山的缩影。紫阳峰牧区是典型的高山台地草原风光，登临紫阳峰，眺望四周，如置身绿色的海洋之中，起伏的草山宛如绿色…整体感受是中规中矩，避开高峰更好。二刷意愿：否。', '0%', 43);
