INSERT INTO `travel_review` VALUES (29079, 'TR029079', '迎恩宫', '济源', '河南', '文化打卡', '秋季', 8, 5, 1378.00, '是', 5, '8月去的迎恩宫，一个人出行。地点在济源，打车比较省心，现场游客较多。这次玩了5天，人均花费约1378元，氛围感不错。景点印象：位于市城区西北29公里的三官坪村北的迎恩宫，北依黛珠峰，西临小有河。相传，唐初紫微宫道士为迎接皇帝或圣旨而建，故名。\n宫座北向阳，为三进院落，依山趁势，就岩砌台，逐级升高，错落有致。现存古建筑有山门、祖师大殿、四圣殿、吕祖殿、三官殿…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '0%', 90);
