INSERT INTO `travel_review` VALUES (29135, 'TR029135', '五店市传统街区', '泉州', '福建', '拍照旅行', '夏季', 3, 2, 581.00, '是', 5, '3月去的五店市传统街区，和朋友出行。地点在泉州，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约581元，夜景表现很好。景点印象：闽南特色建筑群的集合，欣赏多元建筑的完美交融，感受闽南深厚的文化底蕴。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '2%', 56);
