INSERT INTO `travel_review` VALUES (29147, 'TR029147', '朝阳台', '渭南', '陕西', '城市漫游', '春季', 2, 2, 712.00, '否', 4, '2月去的朝阳台，一个人出行。地点在渭南，公交换乘方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约712元，氛围感不错。景点印象：朝阳台在东峰绝顶，因是太阳最先照耀的地方，又是游人观赏华山日出的最佳位置，故名。东峰也因此被称为朝阳峰。 台面积约十平方米，因崖势向外悬空伸出，从远处望去，如同鹰嘴。整体感受是体验挺好，周末来刚好。二刷意愿：否。', '2%', 81);
INSERT INTO `travel_review` VALUES (29148, 'TR029148', '长春电影制片厂', '长春', '吉林', '拍照旅行', '冬季', 11, 3, 777.00, '是', 5, '11月去的长春电影制片厂，一个人出行。地点在长春，地铁到达方便，现场人不算多。这次玩了3天，人均花费约777元，夜景表现很好。景点印象：新中国第一家电影制片厂，介绍了长影的历史，创造电影史上七个第一。整体感受是超出预期，很推荐。二刷意愿：是。', '2%', 108);
