INSERT INTO `travel_review` VALUES (29153, 'TR029153', '东戴河', '葫芦岛', '辽宁', '深度游', '冬季', 9, 1, 391.00, '否', 5, '9月去的东戴河，情侣出行。地点在葫芦岛，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约391元，夜景表现很好。景点印象：来止锚湾吃海鲜，去沙滩晒太阳、体验水上运动。 参观碣石宫遗址、万佛禅寺，游览九门口长城、前所古城等景点。整体感受是超出预期，值得专门打卡。二刷意愿：否。', '21%', 98);
