INSERT INTO `travel_review` VALUES (29181, 'TR029181', '驼铃梦坡沙漠公园', '昌吉', '新疆', '城市漫游', '夏季', 4, 1, 237.00, '是', 5, '4月去的驼铃梦坡沙漠公园，一个人出行。地点在昌吉，地铁到达方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约237元，氛围感不错。景点印象：准噶尔盆地古尔班通古特沙漠南缘，是一片原始、粗犷、一望无垠的沙漠世界，又是一座天然的荒漠植物园，葱绿的梭梭、茂密的胡杨、沁人心脾的沙枣、飘逸羽叶的三芒草，以丑为美的猪毛菜、富有药用价值的大黄、大芸黄芪、“叮铛”作声的铃铛刺、形似鹿…整体感受是特别满意，值得专门打卡。二刷意愿：是。', '1%', 71);
