INSERT INTO `travel_review` VALUES (29201, 'TR029201', '抚顺苏子河漂流', '抚顺', '辽宁', '亲子出游', '秋季', 6, 4, 974.00, '否', 5, '6月去的抚顺苏子河漂流，和朋友出行。地点在抚顺，地铁到达方便，现场人不算多。这次玩了4天，人均花费约974元，夜景表现很好。景点印象：苏子河漂流位于新宾满族自治县境内的苏子河中段，距市区90余公里，乘车经202国道和东南公路仅1小时就可以到达。坐在船筏上沿途可欣赏到冰湖沟、望石谷、石龙峡、望松台、奇峰山、卧龙岭、怪石涯、万古峡、刺激关等景观。漂流段全长13公里，漂流全程…整体感受是挺惊喜，以后还会来。二刷意愿：否。', '0%', 80);
