INSERT INTO `travel_review` VALUES (29232, 'TR029232', '跃进湖', '常德', '湖南', '文化打卡', '夏季', 5, 2, 808.00, '否', 5, '5月去的跃进湖，一个人出行。地点在常德，公交换乘方便，现场游客较多。这次玩了2天，人均花费约808元，拍照很出片。景点印象：原为1958年修建的跃进水库，位于五溪湖东北处港二口镇境内，与五溪湖首尾相连，同居枉水西源干流。跃进湖聚雨面积12.5平方公里,正常库容1700万立方米,蓄水面积4590亩。水库大坝在桅子岗处,长263米,坝高25米。大坝处湖面开阔,湖畔山上种了雪梨、苍溪…整体感受是挺惊喜，以后还会来。二刷意愿：否。', '0%', 122);
