INSERT INTO `travel_review` VALUES (29242, 'TR029242', '燕子洞', '怀化', '湖南', '深度游', '秋季', 7, 1, 218.00, '否', 4, '7月去的燕子洞，一个人出行。地点在怀化，公交换乘方便，现场人流量适中。这次玩了1天，人均花费约218元，夜景表现很好。景点印象：燕子洞位于辰溪县火马冲，距辰溪火车站一公里，怀化市五十余公里，交通便捷。 燕子洞景区属岩溶地貌，山势险峻，沟壑幽深，林木葱茏，溪水淙淙。自然景观丰富优美。人文景巧夺天工。这里，有悬崖峭壁的\"一线天\"，险峻幽深的燕子洞，灵秀婀娜的高峡…整体感受是整体不错，可以安排半天到一天。二刷意愿：否。', '2%', 74);
