INSERT INTO `travel_review` VALUES (29262, 'TR029262', '滕王阁', '南昌', '江西', '文化打卡', '冬季', 9, 1, 637.00, '是', 5, '9月去的滕王阁，情侣出行。地点在南昌，自驾停车需要提前规划，现场游客较多。这次玩了1天，人均花费约637元，夜景表现很好。景点印象：南昌市的地标，因王勃的《滕王阁序》而闻名，是“江南三大名楼”之一。 登楼远眺，遥想当年文人雅士在此吟诗作对的场景。整体感受是超出预期，很推荐。二刷意愿：是。', '57%', 65);
