INSERT INTO `travel_review` VALUES (29277, 'TR029277', '凤凰山龛群', '济源', '河南', '亲子出游', '夏季', 4, 3, 746.00, '否', 4, '4月去的凤凰山龛群，一个人出行。地点在济源，打车比较省心，现场高峰时段比较拥挤。这次玩了3天，人均花费约746元，夜景表现很好。景点印象：凤凰山龛群\n孤山东面，山梁褶皱起伏，犹如凤凰展翅，洼前有一山峰突起，恰似凤头，故名凤凰山。峰顶有祖师庙，山洼中有夫子崖、老君龛、娘娘龛十多处宗教文化胜迹，吸引着众多善男信女虔诚朝拜，香火非常旺盛。整体感受是体验挺好，可以安排半天到一天。二刷意愿：否。', '0%', 53);
