INSERT INTO `travel_review` VALUES (29341, 'TR029341', '中岩', '眉山', '四川', '拍照旅行', '冬季', 9, 1, 318.00, '否', 2, '9月去的中岩，情侣出行。地点在眉山，公交换乘方便，现场游客较多。这次玩了1天，人均花费约318元，夜景表现很好。景点印象：中岩，唐代建寺，川南佛刹丛林之一，素以“川南第一山”、“西川林泉最佳处”著称。现坐落在上寺翠微峰下的“中岩书院”曾培育出大文豪苏东坡。系四川省重点文物保护单位，四川省级风景名胜区, 国家ＡＡ级旅游区。\n中岩在青神城东黄金旅游线上，北…整体感受是略失望，可考虑其他景点。二刷意愿：否。', '0%', 25);
