INSERT INTO `travel_review` VALUES (29343, 'TR029343', '河仓城(大方盘城)', '酒泉', '甘肃', '深度游', '秋季', 7, 7, 1386.00, '否', 4, '7月去的河仓城(大方盘城)，和家人出行。地点在酒泉，地铁到达方便，现场人不算多。这次玩了7天，人均花费约1386元，氛围感不错。景点印象：是古代中国西北长城边防至今存留下来古老的、规模较大的、罕见的军需仓库。整体感受是还蛮满意，可以安排半天到一天。二刷意愿：否。', '5%', 113);
INSERT INTO `travel_review` VALUES (29344, 'TR029344', '加井岛', '万宁', '海南', '深度游', '春季', 12, 6, 1834.00, '是', 4, '12月去的加井岛，和家人出行。地点在万宁，地铁到达方便，现场高峰时段比较拥挤。这次玩了6天，人均花费约1834元，历史文化气息浓。景点印象：原生态的无人小岛，沙白水清，是享受海岛时光的绝佳去处。整体感受是体验挺好，可以安排半天到一天。二刷意愿：是。', '36%', 56);
INSERT INTO `travel_review` VALUES (29345, 'TR029345', '万仙楼（望仙楼）', '泰安', '山东', '城市漫游', '秋季', 6, 1, 723.00, '是', 5, '6月去的万仙楼（望仙楼），情侣出行。地点在泰安，打车比较省心，现场游客较多。这次玩了1天，人均花费约723元，拍照很出片。景点印象：万仙楼位于红门宫北，又名望仙楼。跨盘道而建，门楼式建筑，创建于明万历 四十八年(1620年)，明清多次重修，保存了清代建筑风格。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '2%', 101);
