INSERT INTO `travel_review` VALUES (29351, 'TR029351', '三块石', '海南藏族自治州', '青海', '周末短途', '冬季', 9, 3, 932.00, '否', 5, '9月去的三块石，一个人出行。地点在海南藏族自治州，打车比较省心，现场人流量适中。这次玩了3天，人均花费约932元，历史文化气息浓。景点印象：三块石在湖的西南部，由密集在一起的白色石灰岩礁石组成，怪石峥嵘，远远望去，形似三块巨大的巨鼎屹立于波涛之中，水拍浪激，惊心动魄，现栖息于礁石上的鸟类数量已超过鸟岛。整体感受是特别满意，以后还会来。二刷意愿：否。', '2%', 86);
