INSERT INTO `travel_review` VALUES (29375, 'TR029375', '湖田古窑遗址', '景德镇', '江西', '拍照旅行', '冬季', 9, 1, 539.00, '否', 4, '9月去的湖田古窑遗址，和朋友出行。地点在景德镇，地铁到达方便，现场人不算多。这次玩了1天，人均花费约539元，氛围感不错。景点印象：湖田窑是我国宋、元两代各大制瓷规模最大、延续烧造时间最长、生产的瓷器最精美的古代窑场。遗址保存的遗物非常丰富，历代古窑遍地。整体感受是整体不错，周末来刚好。二刷意愿：否。', '10%', 77);
INSERT INTO `travel_review` VALUES (29376, 'TR029376', '博鳌高尔夫乡村俱乐部', '琼海', '海南', '拍照旅行', '春季', 1, 1, 657.00, '否', 5, '1月去的博鳌高尔夫乡村俱乐部，情侣出行。地点在琼海，公交换乘方便，现场人流量适中。这次玩了1天，人均花费约657元，氛围感不错。景点印象：博鳌高尔夫乡村俱乐部是博鳌大型综合性国际旅游度假开发区的重点项目。由于得天独厚的地理条件和开发人的精心设计，巧夺天工，经过两年多的建设和试营业，一座中国业内首创、亚洲唯一的全岛型林克斯风格的高尔夫球场终于在万泉河入海口处的沙坡岛上…整体感受是挺惊喜，很推荐。二刷意愿：否。', '1%', 60);
