INSERT INTO `travel_review` VALUES (29392, 'TR029392', '月岩', '永州', '湖南', '亲子出游', '秋季', 6, 4, 958.00, '是', 5, '6月去的月岩，和朋友出行。地点在永州，公交换乘方便，现场高峰时段比较拥挤。这次玩了4天，人均花费约958元，拍照很出片。景点印象：月岩，是开放性的岩。一般的岩都是封闭的，从洞口进入，里面阴暗幽明，或高大宽敞，或深不可测，封闭在石山里面。月岩则是开放的，它实际上是一座顶腹皆空的大石山，依据遗留下来的岩石结构和自然走势，天造地化，鬼斧神工，自然地形成东、中、西三…整体感受是特别满意，以后还会来。二刷意愿：是。', '8%', 75);
