INSERT INTO `travel_review` VALUES (29434, 'TR029434', '止锚湾', '葫芦岛', '辽宁', '文化打卡', '夏季', 3, 2, 1068.00, '是', 5, '3月去的止锚湾，和朋友出行。地点在葫芦岛，打车比较省心，现场游客较多。这次玩了2天，人均花费约1068元，拍照很出片。景点印象：游人较少，可看矗立在海中的巨大礁石。 白天可在海滩戏水，夜晚可在海滩吃海鲜、放飞孔明灯。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '10%', 72);
