INSERT INTO `travel_review` VALUES (29439, 'TR029439', '星湖湿地公园', '肇庆', '广东', '城市漫游', '春季', 2, 1, 603.00, '是', 4, '2月去的星湖湿地公园，情侣出行。地点在肇庆，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约603元，历史文化气息浓。景点印象：可以欣赏到湿地之神——丹顶鹤以及多种湿地鸟类。 全国首个湿地公园，空气清新，是个森林氧吧。整体感受是体验挺好，可以安排半天到一天。二刷意愿：是。', '9%', 38);
