INSERT INTO `travel_review` VALUES (29501, 'TR029501', '仙庾风景', '株洲', '湖南', '亲子出游', '秋季', 8, 7, 2006.00, '是', 5, '8月去的仙庾风景，和家人出行。地点在株洲，公交换乘方便，现场游客较多。这次玩了7天，人均花费约2006元，夜景表现很好。景点印象：仙庾风景名胜区位于株洲市荷塘区东北方仙庾镇境内，有公路直达市中心，路距15公里。东与浏阳毗邻，南距大京风景区10多公里，景区两侧有株浏公路、茶马公路通过，交通十分便利。\n仙庾岭主峰海拔233米，位于主峰之上的文昌阁又名仙庾塔，为八角形石…整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 88);
