INSERT INTO `travel_review` VALUES (29517, 'TR029517', '鼓城山自然保护区', '广元', '四川', '文化打卡', '春季', 12, 2, 419.00, '否', 4, '12月去的鼓城山自然保护区，情侣出行。地点在广元，打车比较省心，现场游客较多。这次玩了2天，人均花费约419元，拍照很出片。景点印象：鼓城山景区为省级风景名胜区，位于广元市旺苍县北部鼓城乡境内，距县城63公里，由鼓城山、七里峡、白龙宫三大景区组成，面积100平方公里。这里属米仓山系西段，为构造侵蚀、溶蚀中的地貌，最高点东鼓城海拔2073米，最低点关口垭河谷海拔880米。\n鼓…整体感受是还蛮满意，可以安排半天到一天。二刷意愿：否。', '0%', 50);
