INSERT INTO `travel_review` VALUES (29590, 'TR029590', '释迦多宝如来佛塔', '黄冈', '湖北', '文化打卡', '夏季', 5, 5, 1628.00, '否', 2, '5月去的释迦多宝如来佛塔，一个人出行。地点在黄冈，地铁到达方便，现场高峰时段比较拥挤。这次玩了5天，人均花费约1628元，拍照很出片。景点印象：在五祖寺前一天门。据塔身铭记为北宋宣和三年（1121年）所建。系用素面灰色砂粒岩石砌成，八角五级，高5米，下设莲瓣束腰须弥座，束腰八角各设有挺拔劲健的托塔力士一尊。座上置塔身，形如立鼓，其南面凿佛龛，内供佛像端坐，龛右镌刻“释迦多宝如…整体感受是没达到预期，可考虑其他景点。二刷意愿：否。', '0%', 65);
