INSERT INTO `travel_review` VALUES (29613, 'TR029613', '渡蚁桥', '随州', '湖北', '城市漫游', '冬季', 9, 3, 735.00, '是', 5, '9月去的渡蚁桥，情侣出行。地点在随州，地铁到达方便，现场人流量适中。这次玩了3天，人均花费约735元，夜景表现很好。景点印象：在广水市西原应山县城南郊。为纪念北来宋庠、宋祁以竹渡蚁而建，故名。宋库（996一1066）与其弟宋祁（998-1061），安陆（今属湖北）人，后迁开封雍丘（今河南杞县）。皆北宋大臣，有文名，时称“二宋”。天圣二年（1024年）二宋同举进士，库名列第…整体感受是超出预期，以后还会来。二刷意愿：是。', '0%', 70);
