INSERT INTO `travel_review` VALUES (29638, 'TR029638', '战国长城遗址', '朝阳', '辽宁', '拍照旅行', '秋季', 6, 2, 642.00, '是', 5, '6月去的战国长城遗址，情侣出行。地点在朝阳，公交换乘方便，现场人流量适中。这次玩了2天，人均花费约642元，夜景表现很好。景点印象：战国长城位于建平北部烧锅营子办事处化匠沟村张家湾至蛤蟆沟脑处，长约七公里，为建平境内保存最好的一段长城，主要为战国燕文化时期遗存，绝对年代在公元前311年至前279年，距今约2000多年。1979年9月5日被公布为辽宁省重点文物保护单位。\n长城址…整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 86);
