INSERT INTO `travel_review` VALUES (29682, 'TR029682', '稼禾生态农业旅游基地', '钦州', '广西', '城市漫游', '夏季', 5, 1, 321.00, '是', 4, '5月去的稼禾生态农业旅游基地，一个人出行。地点在钦州，打车比较省心，现场高峰时段比较拥挤。这次玩了1天，人均花费约321元，拍照很出片。景点印象：稼禾公司生态农业旅游基地获得“广西生态农业旅游示范点”称号，其建设的广西沿海地区唯一专业彩弹枪射击场——“火龙战场”乘南博会的东风在2005年会期全面开放。整体感受是体验挺好，周末来刚好。二刷意愿：是。', '0%', 49);
