INSERT INTO `travel_review` VALUES (29686, 'TR029686', '金沙湾', '乌海', '内蒙古', '拍照旅行', '秋季', 7, 3, 1244.00, '否', 4, '7月去的金沙湾，和家人出行。地点在乌海，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了3天，人均花费约1244元，历史文化气息浓。景点印象：金沙湾生态旅游区，是古代经典故事的历史见证，是现代乌海开拓者的辉煌雄姿。独特的生态环境把现代文明与神奇亘古的历史紧紧相连，以它独特的英雄气魄和神奇，点缀着黄河金腰带上的明珠，沙漠中崛起的新兴工业城市---乌海市。\n大自然的鬼斧神工造就…整体感受是整体不错，可以安排半天到一天。二刷意愿：否。', '42%', 56);
