INSERT INTO `travel_review` VALUES (29718, 'TR029718', '江山半岛', '防城港', '广西', '周末短途', '冬季', 10, 3, 550.00, '否', 5, '10月去的江山半岛，和朋友出行。地点在防城港，自驾停车需要提前规划，现场人流量适中。这次玩了3天，人均花费约550元，拍照很出片。景点印象：赏“北部湾最美海岸”，一次看尽黄、白、黑三种颜色的沙滩。整体感受是超出预期，以后还会来。二刷意愿：否。', '0%', 67);
INSERT INTO `travel_review` VALUES (29719, 'TR029719', '巨柏', '林芝', '西藏', '深度游', '夏季', 5, 6, 1685.00, '是', 5, '5月去的巨柏，一个人出行。地点在林芝，地铁到达方便，现场人流量适中。这次玩了6天，人均花费约1685元，夜景表现很好。景点印象：多株树龄2000-3000年左右的参天古树，十分稀有。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '4%', 110);
INSERT INTO `travel_review` VALUES (29720, 'TR029720', '李家峡水电站', '黄南', '青海', '拍照旅行', '春季', 12, 3, 903.00, '是', 5, '12月去的李家峡水电站，情侣出行。地点在黄南，自驾停车需要提前规划，现场人不算多。这次玩了3天，人均花费约903元，历史文化气息浓。景点印象：李家峡水电站青海省境内第二座大型梯级水电站，夏秋时节游客可在湖中泛舟、垂钓，冬春季节可观赏高原雪景。整体感受是特别满意，值得专门打卡。二刷意愿：是。', '22%', 48);
INSERT INTO `travel_review` VALUES (29721, 'TR029721', '清真寺', '固原', '宁夏', '深度游', '秋季', 7, 3, 672.00, '是', 5, '7月去的清真寺，和家人出行。地点在固原，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了3天，人均花费约672元，氛围感不错。景点印象：固原是我国回族的主要聚居地之一，全地区190万多人口中，回族人口占47.8%。从元朝以来，回族人民就在西海固这片黄土地上繁衍生息，勤奋劳作，星罗棋布的清真寺显示它独特的民族色彩。在现有的清真寺中，明朝的有6座，清朝的有428座，民国年间的有61…整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '4%', 70);
