INSERT INTO `travel_review` VALUES (29728, 'TR029728', '合水镇平北村', '阳江', '广东', '周末短途', '春季', 2, 5, 1470.00, '是', 5, '2月去的合水镇平北村，情侣出行。地点在阳江，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了5天，人均花费约1470元，历史文化气息浓。景点印象：平北石山群峰：平北村位于阳春市合水镇北部，这里群山环绕着一个广阔草地，面积约1.2平方公里。该处具有典型的喀斯特岩溶地貌特征，一座座巍峨峻峭的石山群峰簇拥屏列，层峦叠翠，奇峰怪石状人状物，如剑锋，如石笋，如怪兽。山上许多溶洞奇形怪状…整体感受是挺惊喜，很推荐。二刷意愿：是。', '0%', 72);
