INSERT INTO `travel_review` VALUES (29730, 'TR029730', '巴图湾电厂', '鄂尔多斯', '内蒙古', '拍照旅行', '夏季', 4, 3, 615.00, '否', 4, '4月去的巴图湾电厂，和家人出行。地点在鄂尔多斯，打车比较省心，现场人流量适中。这次玩了3天，人均花费约615元，历史文化气息浓。景点印象：巴图湾水电站座落在无定河中上游，巴图湾村境内，是鄂尔多斯规模较大的水力发电站。总装机容量为2800kw，单机800 kw3台，400 kw1台，设计年发电量600万kwh，是一座集发电、防洪、蓄水、旅游于一体的多效益型电站，承担着乌审旗西部电网调峰任务。\n…整体感受是整体不错，推荐来看看。二刷意愿：否。', '0%', 78);
