INSERT INTO `travel_review` VALUES (29765, 'TR029765', '乌尔禾风城', '克拉玛依', '新疆', '拍照旅行', '春季', 1, 3, 634.00, '否', 3, '1月去的乌尔禾风城，情侣出行。地点在克拉玛依，公交换乘方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约634元，历史文化气息浓。景点印象：位于市区东北100多公里的乌尔干地，北倚哈拉阿拉特山，方圆约30余公里，是我国罕见的风蚀地貌。亿万年前，这里是淡水湖泊，地壳的沧桑剧变使它形成了戈壁平台，年复一年的风蚀雨剥，使地面形成沟壑、纵横深浅不一的石层，并将石层雕塑成各种奇形怪…整体感受是还可以，避开高峰更好。二刷意愿：否。', '6%', 52);
