INSERT INTO `travel_review` VALUES (29776, 'TR029776', '石瓯山生态景区', '钦州', '广西', '城市漫游', '秋季', 8, 1, 521.00, '是', 4, '8月去的石瓯山生态景区，情侣出行。地点在钦州，地铁到达方便，现场人不算多。这次玩了1天，人均花费约521元，夜景表现很好。景点印象：石瓯山生态景区——融风景、避暑、品茶于一体。石瓯山海拔498米，山间云雾缭绕，四季常青，因山顶天然“石瓯”而得名。“石瓯”乃日出彩光之聚点，登此观日出，其妙无穷。石瓯山水库位于山下，岛屿众多，如桃花岛、情人岛、相思岛等，弯山曲水，曲…整体感受是整体不错，可以安排半天到一天。二刷意愿：是。', '0%', 75);
