INSERT INTO `travel_review` VALUES (29785, 'TR029785', '龙门群岛', '钦州', '广西', '周末短途', '秋季', 7, 1, 808.00, '否', 5, '7月去的龙门群岛，一个人出行。地点在钦州，公交换乘方便，现场高峰时段比较拥挤。这次玩了1天，人均花费约808元，拍照很出片。景点印象：龙门群岛位于广西壮族自治区钦州市钦州港经济开发区西北部。钦州至钦州港公路可达。距钦州市区约25公里。是集自然景观和人文景观于一体的滨海型旅游区。明清时期一直是钦州的八景之一而备受赞誉。\n龙门群岛是由100多个大小各异的岛屿镶嵌在方圆约50…整体感受是超出预期，值得专门打卡。二刷意愿：否。', '0%', 64);
