INSERT INTO `travel_review` VALUES (29810, 'TR029810', '淮安府署', '淮安', '江苏', '亲子出游', '春季', 1, 2, 494.00, '否', 2, '1月去的淮安府署，和朋友出行。地点在淮安，地铁到达方便，现场游客较多。这次玩了2天，人均花费约494元，历史文化气息浓。景点印象：景点本身有一定特色整体感受是体验偏一般，可考虑其他景点。二刷意愿：否。', '39%', 36);
INSERT INTO `travel_review` VALUES (29811, 'TR029811', '鲁朗国际旅游小镇', '林芝', '西藏', '城市漫游', '冬季', 9, 4, 757.00, '否', 5, '9月去的鲁朗国际旅游小镇，一个人出行。地点在林芝，打车比较省心，现场人不算多。这次玩了4天，人均花费约757元，历史文化气息浓。景点印象：森林环绕的高原小镇，木屋、篱笆、高山草甸，好似瑞士风光。整体感受是超出预期，很推荐。二刷意愿：否。', '12%', 78);
INSERT INTO `travel_review` VALUES (29812, 'TR029812', '蜀南竹海', '宜宾', '四川', '文化打卡', '冬季', 9, 4, 1348.00, '是', 4, '9月去的蜀南竹海，一个人出行。地点在宜宾，公交换乘方便，现场游客较多。这次玩了4天，人均花费约1348元，氛围感不错。景点印象：在竹海翻腾的林间小径漫步，耳边是阵阵“竹”涛，感觉悠闲惬意。整体感受是还蛮满意，推荐来看看。二刷意愿：是。', '58%', 53);
INSERT INTO `travel_review` VALUES (29813, 'TR029813', '关王庙', '阳泉', '山西', '深度游', '春季', 2, 3, 472.00, '否', 5, '2月去的关王庙，和朋友出行。地点在阳泉，地铁到达方便，现场高峰时段比较拥挤。这次玩了3天，人均花费约472元，历史文化气息浓。景点印象：关王庙又称关帝庙，俗称老爷庙，位于郊区白泉乡林里村南。殿宇由绿树、红墙萦围。占地面积近7000平方米，分内外两大院落。关王庙建成已有900多年，据有关资料证实，是我国最早的关羽庙建筑。关王庙以关王正殿为主，由献殿、马殿、南北配殿，以及外…整体感受是特别满意，以后还会来。二刷意愿：否。', '7%', 45);
INSERT INTO `travel_review` VALUES (29814, 'TR029814', '敬亭山', '宣城', '安徽', '文化打卡', '冬季', 10, 2, 722.00, '是', 4, '10月去的敬亭山，一个人出行。地点在宣城，地铁到达方便，现场游客较多。这次玩了2天，人均花费约722元，历史文化气息浓。景点印象：李白写下“相看两不厌，只有敬亭山”的地方。 参观地标宋代广教寺双塔，在太白独坐楼下缅怀李白。 山上有大片茶园和竹林，空气清新，登云桥俯看宣城和水阳江。整体感受是还蛮满意，周末来刚好。二刷意愿：是。', '14%', 34);
INSERT INTO `travel_review` VALUES (29815, 'TR029815', '东昌湖', '聊城', '山东', '拍照旅行', '夏季', 3, 2, 719.00, '否', 5, '3月去的东昌湖，和朋友出行。地点在聊城，自驾停车需要提前规划，现场人不算多。这次玩了2天，人均花费约719元，夜景表现很好。景点印象：整体环境还算干净整体感受是挺惊喜，以后还会来。二刷意愿：否。', '100%', 74);
INSERT INTO `travel_review` VALUES (29816, 'TR029816', '水坑生态旅游娱乐区', '河源', '广东', '城市漫游', '夏季', 3, 4, 1491.00, '否', 5, '3月去的水坑生态旅游娱乐区，情侣出行。地点在河源，自驾停车需要提前规划，现场人流量适中。这次玩了4天，人均花费约1491元，氛围感不错。景点印象：水坑生态旅游娱乐区是以自然生态为依托和独立的创意，开发建设成为颇受人们钟爱的游乐休闲圣地，被誉为城市人的“世外桃源”。\n进入水坑，就似投入大自然的怀抱，使您变得年轻，忘却了烦恼。景区内青山滴翠，一片绿海，方圆50平方公里内绝无污染，…整体感受是特别满意，值得专门打卡。二刷意愿：否。', '0%', 68);
