INSERT INTO `travel_review` VALUES (29843, 'TR029843', '松口古镇', '梅州', '广东', '深度游', '冬季', 9, 2, 321.00, '否', 4, '9月去的松口古镇，情侣出行。地点在梅州，地铁到达方便，现场人流量适中。这次玩了2天，人均花费约321元，拍照很出片。景点印象：松口不仅仅是千年古镇，而且是客家人的栖身之地，古镇傍水而依，古老的房子与蓝天碧水融为一体，凝成了一幅绝美的山水画，是梅县区第一大镇。整体感受是整体不错，推荐来看看。二刷意愿：否。', '0%', 82);
