INSERT INTO `travel_review` VALUES (29849, 'TR029849', '抚顺努尔哈赤冰雪大世界', '抚顺', '辽宁', '拍照旅行', '夏季', 5, 5, 1093.00, '否', 5, '5月去的抚顺努尔哈赤冰雪大世界，情侣出行。地点在抚顺，公交换乘方便，现场人不算多。这次玩了5天，人均花费约1093元，拍照很出片。景点印象：抚顺努尔哈赤冰雪大世界于2000年10月28日举行奠基开工仪式。该项目坐落在抚顺著名风景区萨尔浒区内，预计投资4000万元，占地50万平方米，集滑雪、滑冰、冰雕、雪雕、狩猎为一体。并首次投入科技含量高，新奇刺激的火箭蹦极、进口雪地摩托车、雪地卡…整体感受是超出预期，值得专门打卡。二刷意愿：否。', '0%', 61);
INSERT INTO `travel_review` VALUES (29850, 'TR029850', '运城关公故里文化旅游景区', '运城', '山西', '拍照旅行', '冬季', 9, 2, 787.00, '是', 5, '9月去的运城关公故里文化旅游景区，和家人出行。地点在运城，地铁到达方便，现场高峰时段比较拥挤。这次玩了2天，人均花费约787元，夜景表现很好。景点印象：在关羽的家乡，朝拜武圣人关羽，瞻仰关帝祖庙。 这里是国内始建早、规模较大较完整的庙宇。 观赏庙悬挂的康熙、乾隆、咸丰三位皇帝亲笔、钦定的匾额。整体感受是挺惊喜，值得专门打卡。二刷意愿：是。', '30%', 50);
INSERT INTO `travel_review` VALUES (29851, 'TR029851', '日升昌票号', '晋中', '山西', '深度游', '春季', 2, 1, 499.00, '是', 4, '2月去的日升昌票号，一个人出行。地点在晋中，自驾停车需要提前规划，现场人不算多。这次玩了1天，人均花费约499元，历史文化气息浓。景点印象：这里是中国最早的私人银行，其经营网点曾经几乎遍布整个中国，是平遥古城中的必游之地。整体感受是还蛮满意，周末来刚好。二刷意愿：是。', '28%', 66);
INSERT INTO `travel_review` VALUES (29852, 'TR029852', '百花声处休闲度假营地', '石河子', '新疆', '城市漫游', '春季', 2, 2, 462.00, '否', 5, '2月去的百花声处休闲度假营地，一个人出行。地点在石河子，公交换乘方便，现场人流量适中。这次玩了2天，人均花费约462元，氛围感不错。景点印象：周边配套比较齐全整体感受是特别满意，很推荐。二刷意愿：否。', '0%', 100);
INSERT INTO `travel_review` VALUES (29853, 'TR029853', '黄河古栈道', '三门峡', '河南', '亲子出游', '冬季', 11, 1, 343.00, '是', 5, '11月去的黄河古栈道，一个人出行。地点在三门峡，公交换乘方便，现场游客较多。这次玩了1天，人均花费约343元，拍照很出片。景点印象：黄河古栈道位于三门峡大坝下游北岸紧靠黄河的陡壁悬崖上，共有两条。一条离河面较高，一条离河面较低，都是紧挨着石壁的冲击处开凿的。\n从遗迹上可以看出，黄河古栈道是在紧靠三门峡谷的黄河两岸徒壁的河水冲击处开凿出一条狭窄的石路，再在路断处…整体感受是挺惊喜，以后还会来。二刷意愿：是。', '4%', 100);
INSERT INTO `travel_review` VALUES (29854, 'TR029854', '中国最北邮政局', '大兴安岭', '黑龙江', '拍照旅行', '春季', 1, 1, 405.00, '是', 5, '1月去的中国最北邮政局，和家人出行。地点在大兴安岭，公交换乘方便，现场人不算多。这次玩了1天，人均花费约405元，拍照很出片。景点印象：周边配套比较齐全整体感受是特别满意，以后还会来。二刷意愿：是。', '19%', 48);
