INSERT INTO `travel_review` VALUES (29856, 'TR029856', '汉口江滩', '武汉', '湖北', '拍照旅行', '春季', 2, 2, 1066.00, '是', 5, '2月去的汉口江滩，情侣出行。地点在武汉，打车比较省心，现场高峰时段比较拥挤。这次玩了2天，人均花费约1066元，夜景表现很好。景点印象：吹江风，观赏十几幢不同风格的百年老建筑。整体感受是挺惊喜，以后还会来。二刷意愿：是。', '3%', 88);
INSERT INTO `travel_review` VALUES (29857, 'TR029857', '金华山', '遂宁', '四川', '文化打卡', '春季', 1, 5, 1584.00, '是', 5, '1月去的金华山，一个人出行。地点在遂宁，打车比较省心，现场人流量适中。这次玩了5天，人均花费约1584元，历史文化气息浓。景点印象：位于金华城北，为国家级重点风景名胜区。海拔150-1200米，绵延250平方公里，像一条长龙横卧于古婺大地。全年气候湿润、云雾缥缈，环境清凉宜人，并以林海莽原、奇异洞景和黄大仙真源为特色，被游客公认为休闲度假的仙游胜地。\n金华山洞奇、石怪、山…整体感受是超出预期，值得专门打卡。二刷意愿：是。', '50%', 85);
