INSERT INTO `travel_review` VALUES (29893, 'TR029893', '赵庄遗址', '焦作', '河南', '拍照旅行', '夏季', 5, 1, 571.00, '否', 5, '5月去的赵庄遗址，和朋友出行。地点在焦作，公交换乘方便，现场人流量适中。这次玩了1天，人均花费约571元，氛围感不错。景点印象：赵庄遗址位于武陟县西南30公里处的大封乡赵庄村南。遗址东西长350米，南北宽200米，面积约7万平方米。文化曾包括仰韶文化、龙山文化、二里头文化和西周战国文化。遗址西部主要为二里头文化区，出土有大量拟质灰陶细绳纹陶鬲、大口尊、平口瓮和骨针…整体感受是特别满意，值得专门打卡。二刷意愿：否。', '0%', 98);
