INSERT INTO `travel_review` VALUES (29916, 'TR029916', '文笔峰', '铜仁', '贵州', '城市漫游', '夏季', 4, 5, 1187.00, '否', 2, '4月去的文笔峰，情侣出行。地点在铜仁，公交换乘方便，现场人不算多。这次玩了5天，人均花费约1187元，氛围感不错。景点印象：文笔峰在铜仁城南的对岸，其峰高插入云端，陡峭如削。每当旭日东升，朝霞偶尔掩映在山巅之上，天幕就像五色纸一样绚丽多彩，不愧为铜仁城的一大奇观。如橼巨笔在五彩天幕挥洒泼墨，其景不愧为铜仁一大奇观。整体感受是体验偏一般，不建议高峰来。二刷意愿：否。', '1%', 0);
