INSERT INTO `travel_review` VALUES (29927, 'TR029927', '五溪', '池州', '安徽', '拍照旅行', '秋季', 7, 1, 455.00, '否', 2, '7月去的五溪，和家人出行。地点在池州，公交换乘方便，现场人流量适中。这次玩了1天，人均花费约455元，拍照很出片。景点印象：五溪是九华山的北大门，由龙溪、缥溪、舒溪、曹溪、濂溪、五溪汇集于六泉口，经溪流横穿318国道，北流注入长江。立于五溪桥上，远眺九华山，秀峰叠翠，云烟缥缈。近观碧水溪流，山影倒映，风景幽绝，令人倾倒。元文宗皇帝路过山地，即兴赋诗:“当年…整体感受是略失望，可考虑其他景点。二刷意愿：否。', '1%', 57);
