INSERT INTO `travel_review` VALUES (29953, 'TR029953', '五道豁洛影视城', '黑河', '黑龙江', '深度游', '冬季', 11, 2, 776.00, '是', 5, '11月去的五道豁洛影视城，和家人出行。地点在黑河，自驾停车需要提前规划，现场高峰时段比较拥挤。这次玩了2天，人均花费约776元，拍照很出片。景点印象：五道豁洛影视城位于黑龙江中方一侧，距黑河市区1.5公里处。五道豁洛岛旅游区共分为影视基地、黑龙湾、历史文物馆、原始人部落、天然动物园五个景区。后几个景区正在规划和修复之中。影视基地建于中俄界河―黑龙江的五道豁洛岛上，占地面积12万平方…整体感受是超出预期，值得专门打卡。二刷意愿：是。', '14%', 89);
