INSERT INTO `travel_review` VALUES (29959, 'TR029959', '五道峡', '襄阳', '湖北', '周末短途', '夏季', 4, 1, 562.00, '是', 4, '4月去的五道峡，和朋友出行。地点在襄阳，打车比较省心，现场人不算多。这次玩了1天，人均花费约562元，历史文化气息浓。景点印象：五道峡里面特凉爽，外面39摄氏度，里面要穿外套，冰火两重天。整体感受是整体不错，可以安排半天到一天。二刷意愿：是。', '3%', 66);
