INSERT INTO `travel_review` VALUES (29962, 'TR029962', '明堂公园', '大同', '山西', '城市漫游', '冬季', 11, 1, 499.00, '是', 5, '11月去的明堂公园，一个人出行。地点在大同，自驾停车需要提前规划，现场游客较多。这次玩了1天，人均花费约499元，拍照很出片。景点印象：周边配套比较齐全整体感受是超出预期，值得专门打卡。二刷意愿：是。', '0%', 86);
INSERT INTO `travel_review` VALUES (29963, 'TR029963', '鄂豫皖苏区首府烈士陵园', '信阳', '河南', '亲子出游', '夏季', 4, 2, 416.00, '是', 5, '4月去的鄂豫皖苏区首府烈士陵园，一个人出行。地点在信阳，地铁到达方便，现场人不算多。这次玩了2天，人均花费约416元，拍照很出片。景点印象：鄂豫皖苏区革命烈士陵园建于1957年、占地330亩由大门、烈士浮雕墙、烈士纪念碑、烈士纪念堂、革命斗争史陈列室、吴焕先半身塑像、烈士纪念亭、烈士墓地八大部分组成。\n大门 为现代建筑，园名由原国家主席李先念亲笔题写。\n烈士浮雕墙 用花岗岩雕塑…整体感受是超出预期，值得专门打卡。二刷意愿：是。', '0%', 101);
