INSERT INTO `travel_review` VALUES (29965, 'TR029965', '太子石', '铜仁', '贵州', '文化打卡', '夏季', 4, 2, 615.00, '否', 5, '4月去的太子石，一个人出行。地点在铜仁，地铁到达方便，现场游客较多。这次玩了2天，人均花费约615元，氛围感不错。景点印象：在梵净山老金顶南麓，牛尾河源头处，耸立着一座海拔1748.2米，如剑劈斧砍成的石山，远远望去，俨然一巨人正在仰望，相传为皇太子所化，故名太子石。整体感受是挺惊喜，以后还会来。二刷意愿：否。', '7%', 60);
