INSERT INTO `travel_review` VALUES (29996, 'TR029996', '雷音寺', '酒泉', '甘肃', '周末短途', '春季', 2, 1, 424.00, '是', 5, '2月去的雷音寺，情侣出行。地点在酒泉，地铁到达方便，现场人流量适中。这次玩了1天，人均花费约424元，历史文化气息浓。景点印象：鸠摩罗什、玄奘等高僧大德都曾留下过踪迹，在唐代时就有“善国神乡、佛国圣地”的美誉。整体感受是挺惊喜，很推荐。二刷意愿：是。', '5%', 112);
